CORE_ACTION_ORDER = ("ACTION1", "ACTION2", "ACTION3", "ACTION4", "ACTION5", "ACTION6")
DIRECTIONAL_ACTIONS = ("ACTION1", "ACTION2", "ACTION3", "ACTION4")
GOAL_BIASED_DIRECTIONAL_ACTIONS = ("ACTION1", "ACTION4", "ACTION2", "ACTION3")
# E-1 S4: a single-step displacement beyond this L1 distance is a
# reset/teleport, not a stride move (largest observed legit stride is 6;
# tu93's reset jump is ~18).
RESET_JUMP_DISTANCE = 10
