    def _coordinate_hypothesis_recent_no_progress_plan_count(self) -> int:
        count = 0
        for outcome in reversed(self._coordinate_hypothesis_plan_outcomes[-8:]):
            if not bool(outcome.get("plan_completed")):
                continue
            if int(outcome.get("score_before", 0) or 0) <= 0:
                continue
            verdict = str(outcome.get("verdict", "") or "")
            if verdict == "falsified_no_coordinate_progress":
                count += 1
                continue
            if verdict in {"score_confirmed", "coordinate_progress"}:
                break
        return int(count)

    def _coordinate_hypothesis_post_score1_stale_target_keys(self) -> list[str]:
        if not bool(self._coordinate_hypothesis_post_score1_score_bearing_immediate_guard_enabled()):
            return []
        return self._coordinate_hypothesis_recent_completed_no_score_target_keys()

    def _coordinate_hypothesis_recent_completed_no_score_target_keys(
        self,
        *,
        exact_instance: bool = False,
    ) -> list[str]:
        keys: list[str] = []
        for outcome in reversed(self._coordinate_hypothesis_plan_outcomes[-8:]):
            if int(outcome.get("score_delta", 0) or 0) > 0:
                break
            if not bool(outcome.get("plan_completed")):
                continue
            if int(outcome.get("score_before", 0) or 0) <= 0:
                continue
            if str(outcome.get("primitive_id", "") or "") not in {
                "coordinate_hypothesis_choice",
                "coordinate_hypothesis_plan_lease",
                "coordinate_hypothesis_target_commitment",
                "coordinate_hypothesis_terminal_local_verifier",
                "coordinate_hypothesis_post_peak_replan",
            }:
                continue
            raw_keys = [
                *list(outcome.get("requested_target_keys") or []),
                outcome.get("requested_target_key", ""),
                outcome.get("post_target_key", ""),
                outcome.get("pre_target_key", ""),
            ]
            for raw_key in raw_keys:
                key = str(raw_key or "")
                if not key:
                    continue
                if exact_instance:
                    if key not in keys:
                        keys.append(key)
                elif not _coordinate_target_key_matches_any(key, keys):
                    keys.append(key)
        return keys[:8]

    def _coordinate_hypothesis_recent_completed_no_score_exact_target_counts(
        self,
    ) -> dict[str, int]:
        counts: Counter[str] = Counter()
        for outcome in reversed(self._coordinate_hypothesis_plan_outcomes[-8:]):
            if int(outcome.get("score_delta", 0) or 0) > 0:
                break
            if not bool(outcome.get("plan_completed")):
                continue
            if int(outcome.get("score_before", 0) or 0) <= 0:
                continue
            if str(outcome.get("primitive_id", "") or "") not in {
                "coordinate_hypothesis_choice",
                "coordinate_hypothesis_plan_lease",
                "coordinate_hypothesis_target_commitment",
                "coordinate_hypothesis_terminal_local_verifier",
                "coordinate_hypothesis_post_peak_replan",
            }:
                continue
            outcome_keys: list[str] = []
            for raw_key in [
                *list(outcome.get("requested_target_keys") or []),
                outcome.get("requested_target_key", ""),
                outcome.get("post_target_key", ""),
                outcome.get("pre_target_key", ""),
            ]:
                key = str(raw_key or "")
                if key and key not in outcome_keys:
                    outcome_keys.append(key)
            for key in outcome_keys:
                counts[key] += 1
        return dict(counts)

    def _coordinate_hypothesis_recent_completed_no_score_exact_target_sites(
        self,
    ) -> dict[str, list[list[int]]]:
        sites: dict[str, list[list[int]]] = {}
        for outcome in reversed(self._coordinate_hypothesis_plan_outcomes[-8:]):
            if int(outcome.get("score_delta", 0) or 0) > 0:
                break
            if not bool(outcome.get("plan_completed")):
                continue
            if int(outcome.get("score_before", 0) or 0) <= 0:
                continue
            if str(outcome.get("primitive_id", "") or "") not in {
                "coordinate_hypothesis_choice",
                "coordinate_hypothesis_plan_lease",
                "coordinate_hypothesis_target_commitment",
                "coordinate_hypothesis_terminal_local_verifier",
                "coordinate_hypothesis_post_peak_replan",
            }:
                continue
            raw_site = outcome.get("selected_site")
            if not isinstance(raw_site, (list, tuple)) or len(raw_site) < 2:
                continue
            try:
                selected_site = [int(raw_site[0]), int(raw_site[1])]
            except (TypeError, ValueError):
                continue
            outcome_keys: list[str] = []
            for raw_key in [
                *list(outcome.get("requested_target_keys") or []),
                outcome.get("requested_target_key", ""),
                outcome.get("post_target_key", ""),
                outcome.get("pre_target_key", ""),
            ]:
                key = str(raw_key or "")
                if key and key not in outcome_keys:
                    outcome_keys.append(key)
            for key in outcome_keys:
                bucket = sites.setdefault(key, [])
                if selected_site not in bucket:
                    bucket.append(list(selected_site))
        return sites

