    def _coordinate_hypothesis_remembered_targets(self) -> list[dict[str, Any]]:
        return [dict(row) for row in self._coordinate_hypothesis_r11l_target_memory.values()]

    def _remember_coordinate_hypothesis_targets(self, packet: Mapping[str, Any]) -> None:
        for component in list(packet.get("components") or []):
            if not isinstance(component, Mapping):
                continue
            if component.get("kind") != "target" or component.get("role") != "target":
                continue
            raw_colors = component.get("colors")
            if raw_colors is None:
                raw_colors = [component.get("color")]
            if not isinstance(raw_colors, (list, tuple, set)):
                raw_colors = [raw_colors]
            colors: list[int] = []
            for item in raw_colors:
                try:
                    colors.append(int(item))
                except (TypeError, ValueError):
                    continue
            color_key = tuple(sorted(set(colors)))
            raw_bbox = component.get("bbox")
            if not color_key or not isinstance(raw_bbox, (list, tuple)) or len(raw_bbox) < 4:
                continue
            try:
                bbox = [int(raw_bbox[0]), int(raw_bbox[1]), int(raw_bbox[2]), int(raw_bbox[3])]
            except (TypeError, ValueError):
                continue
            self._coordinate_hypothesis_r11l_target_memory[color_key] = {
                "bbox": bbox,
                "pos": [bbox[0], bbox[1]],
                "size": [bbox[2] - bbox[0] + 1, bbox[3] - bbox[1] + 1],
                "color": int(color_key[0]),
                "colors": list(color_key),
                "source": "eca_observed_target_memory",
            }

