    def _lane_c_firewall_stable_solvers(self) -> set[str]:
        configured = _parse_env_allowlist("ECA_LANE_C_FIREWALL_STABLE_SOLVERS")
        if configured:
            return configured
        return {
            "axis_reflection_coverage_search",
            "color_cycle_constraint_solver",
            "rule_table_rotation_solver",
            "shape_coverage_paste_solver",
        }

    def _lane_c_eligibility_firewall_decision(
        self,
        *,
        mechanic_hypothesis_choice: Mapping[str, Any] | None,
        mechanic_goal_candidate_choice: Mapping[str, Any] | None,
        unknown_action_choice: Mapping[str, Any] | None = None,
        cycle_constraint_choice: Mapping[str, Any] | None = None,
        axis_reflection_action: str | None = None,
        shape_coverage_action: str | None = None,
    ) -> dict[str, Any]:
        enabled = self._lane_c_eligibility_firewall_enabled()
        blocked_choices: list[str] = []
        if mechanic_hypothesis_choice is not None:
            blocked_choices.append("mechanic_hypothesis_cycle_executor")
        if mechanic_goal_candidate_choice is not None:
            blocked_choices.append("mechanic_hypothesis_goal_candidate_plan")
        if unknown_action_choice is not None:
            blocked_choices.append("unknown_affordance_probe")
        stable_solver = ""
        stable_solvers = self._lane_c_firewall_stable_solvers()
        if isinstance(cycle_constraint_choice, Mapping):
            primitive_id = str(cycle_constraint_choice.get("primitive_id", "") or "")
            if primitive_id in stable_solvers:
                stable_solver = primitive_id
        if not stable_solver and axis_reflection_action is not None and "axis_reflection_coverage_search" in stable_solvers:
            stable_solver = "axis_reflection_coverage_search"
        if not stable_solver and shape_coverage_action is not None and "shape_coverage_paste_solver" in stable_solvers:
            stable_solver = "shape_coverage_paste_solver"
        blocked = bool(enabled and stable_solver and blocked_choices)
        return {
            "enabled": bool(enabled),
            "blocked": bool(blocked),
            "reason": "existing_stable_solver_available" if blocked else "",
            "stable_solver": stable_solver,
            "blocked_choices": blocked_choices if blocked else [],
            "stable_solvers": sorted(stable_solvers),
        }

    def _internal_llm_candidate_max_calls(self) -> int | None:
        raw = str(os.environ.get("ECA_INTERNAL_LLM_CANDIDATE_MAX_CALLS", "") or "").strip()
        if not raw:
            return None
        try:
            return max(0, int(raw))
        except (TypeError, ValueError):
            return None

    def _internal_llm_candidate_min_records(self) -> int:
        raw = str(os.environ.get("ECA_INTERNAL_LLM_CANDIDATE_MIN_RECORDS", "") or "").strip()
        if not raw:
            return 0
        try:
            return max(0, int(raw))
        except (TypeError, ValueError):
            return 0

    def _internal_llm_candidate_call_gate(self, *, records_count: int) -> tuple[bool, dict[str, Any]]:
        enabled = self._internal_llm_cognition_enabled()
        max_calls = self._internal_llm_candidate_max_calls()
        min_records = self._internal_llm_candidate_min_records()
        reason = ""
        allowed = bool(enabled)
        if not enabled:
            reason = "disabled"
        elif int(records_count) < min_records:
            allowed = False
            reason = "min_records"
        elif max_calls is not None and self._internal_llm_cognition_provider_call_count >= max_calls:
            allowed = False
            reason = "max_calls"
        return allowed, {
            "configured_enabled": bool(enabled),
            "allowed": bool(allowed),
            "block_reason": reason,
            "records_count": int(records_count),
            "min_records": int(min_records),
            "max_calls": None if max_calls is None else int(max_calls),
            "provider_call_count_before": int(self._internal_llm_cognition_provider_call_count),
        }

    def _coordinate_hypothesis_call_gate(
        self,
        *,
        records_count: int,
        available_actions: set[str],
        blocked_by_stable_solver: bool,
        stable_solver_reasons: list[str],
    ) -> tuple[bool, dict[str, Any]]:
        enabled = self._coordinate_hypothesis_lane_enabled()
        max_calls = self._coordinate_hypothesis_max_calls()
        min_records = self._coordinate_hypothesis_min_records()
        no_progress_pause_threshold = self._coordinate_hypothesis_pause_after_no_progress_plans()
        recent_no_progress_plans = self._coordinate_hypothesis_recent_no_progress_plan_count()
        provider_cooldown_before = int(self._coordinate_hypothesis_provider_cooldown_remaining)
        reason = ""
        allowed = bool(enabled)
        if not enabled:
            allowed = False
            reason = "disabled"
        elif "ACTION6" not in available_actions:
            allowed = False
            reason = "action6_unavailable"
        elif (
            self._coordinate_hypothesis_stop_after_score_success()
            and self._coordinate_hypothesis_score_success_count > 0
        ):
            allowed = False
            reason = "coordinate_score_success_observed"
        elif int(records_count) < min_records:
            allowed = False
            reason = "min_records"
        elif max_calls is not None and self._coordinate_hypothesis_provider_call_count >= max_calls:
            allowed = False
            reason = "max_calls"
        elif provider_cooldown_before > 0:
            allowed = False
            reason = str(
                self._coordinate_hypothesis_provider_cooldown_source
                or "repair_completion_provider_cooldown"
            )
            self._coordinate_hypothesis_provider_cooldown_remaining = max(
                0,
                provider_cooldown_before - 1,
            )
            if self._coordinate_hypothesis_provider_cooldown_remaining <= 0:
                self._coordinate_hypothesis_provider_cooldown_source = ""
        elif (
            no_progress_pause_threshold > 0
            and recent_no_progress_plans >= no_progress_pause_threshold
        ):
            allowed = False
            reason = "coordinate_plan_no_progress_posterior"
        elif bool(blocked_by_stable_solver):
            allowed = False
            reason = "stable_solver_available"
        return allowed, {
            "configured_enabled": bool(enabled),
            "allowed": bool(allowed),
            "block_reason": reason,
            "records_count": int(records_count),
            "min_records": int(min_records),
            "max_calls": None if max_calls is None else int(max_calls),
            "provider_call_count_before": int(self._coordinate_hypothesis_provider_call_count),
            "score_success_count": int(self._coordinate_hypothesis_score_success_count),
            "stable_solver_reasons": list(stable_solver_reasons),
            "no_progress_plan_pause_threshold": int(no_progress_pause_threshold),
            "recent_no_progress_plan_count": int(recent_no_progress_plans),
            "repair_completion_provider_cooldown_before": int(provider_cooldown_before),
            "repair_completion_provider_cooldown_after": int(
                self._coordinate_hypothesis_provider_cooldown_remaining
            ),
            "provider_cooldown_source": str(
                self._coordinate_hypothesis_provider_cooldown_source or reason
            ) if provider_cooldown_before > 0 else "",
        }

    def _coordinate_hypothesis_terminal_local_verifier_choice(
        self,
        *,
        frame_arr: np.ndarray,
        current_hash: str,
        records_count: int,
        call_gate: Mapping[str, Any],
    ) -> tuple[dict[str, Any] | None, dict[str, Any]]:
        enabled = bool(
            self._coordinate_hypothesis_terminal_local_verifier_after_max_calls_enabled()
        )
        max_attempts = (
            self._coordinate_hypothesis_terminal_local_verifier_after_max_calls_max_attempts()
        )
        min_score_successes = (
            self._coordinate_hypothesis_terminal_local_verifier_after_max_calls_min_score_successes()
        )
        diag: dict[str, Any] = {
            "enabled": bool(enabled),
            "provider_available": bool(self.coordinate_hypothesis_bridge.provider is not None),
            "provider_called": False,
            "choice_generated": False,
            "selected_site": [],
            "candidate_sites_generated_from_hypothesis_count": 0,
            "candidate_sites_contains_selected_site": False,
            "direct_llm_action_blocked_count": 0,
            "terminal_local_verifier_after_max_calls": {
                "enabled": bool(enabled),
                "attempt_count": int(
                    self._coordinate_hypothesis_terminal_local_verifier_after_max_calls_count
                ),
                "max_attempts": int(max_attempts),
                "min_score_successes": int(min_score_successes),
                "applied": False,
                "block_reason": "",
            },
            "call_gate": {
                **dict(call_gate),
                "allowed": False,
                "provider_call_count_after": int(self._coordinate_hypothesis_provider_call_count),
            },
        }
        block_reason = ""
        if not enabled:
            block_reason = "terminal_local_verifier_after_max_calls_disabled"
        elif str(call_gate.get("block_reason", "") or "") != "max_calls":
            block_reason = "call_gate_not_max_calls"
        elif int(self._coordinate_hypothesis_score_success_count) < int(min_score_successes):
            block_reason = "terminal_local_verifier_min_score_successes"
        elif max_attempts <= 0:
            block_reason = "terminal_local_verifier_max_attempts_zero"
        elif (
            self._coordinate_hypothesis_terminal_local_verifier_after_max_calls_count
            >= max_attempts
        ):
            block_reason = "terminal_local_verifier_max_attempts"
        if block_reason:
            diag["terminal_local_verifier_after_max_calls"]["block_reason"] = block_reason
            return None, diag
        try:
            packet = build_r11l_l1_coordinate_sensor_packet(
                frame_arr,
                state_hash=current_hash,
                step=int(records_count),
                remembered_targets=self._coordinate_hypothesis_remembered_targets(),
                include_eca_only_context=True,
            )
            self._remember_coordinate_hypothesis_targets(packet)
            group_focus = self._coordinate_hypothesis_group_focus_payload_from_packet(packet)
            stale_target_keys = self._coordinate_hypothesis_post_score1_stale_target_keys()
            attempted_sites = [
                [int(site[0]), int(site[1])]
                for site in sorted(self._coordinate_hypothesis_attempted_sites)
            ]
            fallback_focus = {
                **dict(group_focus),
                "source": "coordinate_terminal_local_verifier_after_max_calls",
                "strict_preferred_targets": False,
                "terminal_attempted_site_alternatives_enabled": bool(
                    self._coordinate_hypothesis_terminal_attempted_site_alternatives_enabled()
                ),
                "terminal_execution_order_alternatives_enabled": bool(
                    self._coordinate_hypothesis_terminal_execution_order_alternatives_enabled()
                ),
                "terminal_execution_order_canvas_safety_enabled": bool(
                    self._coordinate_hypothesis_terminal_execution_order_canvas_safety_enabled()
                ),
                "terminal_immediate_target_diversity_enabled": bool(
                    self._coordinate_hypothesis_terminal_immediate_target_diversity_enabled()
                ),
                "terminal_structured_target_diversity_enabled": bool(
                    self._coordinate_hypothesis_terminal_structured_target_diversity_enabled()
                ),
                "terminal_immediate_move_click_empty_guard_enabled": bool(
                    self._coordinate_hypothesis_terminal_immediate_move_click_empty_guard_enabled()
                ),
                "terminal_joint_action_budget_guard_enabled": bool(
                    self._coordinate_hypothesis_terminal_joint_action_budget_guard_enabled()
                ),
                "terminal_joint_single_target_after_score_guard_enabled": bool(
                    self._coordinate_hypothesis_terminal_joint_single_target_after_score_guard_enabled()
                ),
                **self._coordinate_hypothesis_terminal_joint_single_target_after_score_ceiling_payload(),
                "terminal_completion_coverage_guard_enabled": bool(
                    self._coordinate_hypothesis_terminal_completion_coverage_guard_enabled()
                ),
                "terminal_completion_best_incomplete_telemetry_enabled": bool(
                    self._coordinate_hypothesis_terminal_completion_best_incomplete_telemetry_enabled()
                ),
                "terminal_completion_best_incomplete_fallback_enabled": bool(
                    self._coordinate_hypothesis_terminal_completion_best_incomplete_fallback_enabled()
                ),
                "terminal_completion_best_incomplete_min_coverage": int(
                    self._coordinate_hypothesis_terminal_completion_best_incomplete_min_coverage()
                ),
                "terminal_completion_best_incomplete_fallback_application_count": int(
                    self._coordinate_hypothesis_terminal_best_incomplete_fallback_applied_count
                ),
                "terminal_completion_best_incomplete_max_applications": int(
                    self._coordinate_hypothesis_terminal_completion_best_incomplete_max_applications()
                ),
                "post_score1_score_bearing_immediate_guard_enabled": bool(
                    self._coordinate_hypothesis_post_score1_score_bearing_immediate_guard_enabled()
                    and stale_target_keys
                ),
                "post_score1_score_bearing_stale_target_keys": list(stale_target_keys),
                **self._coordinate_hypothesis_terminal_structured_action_budget_payload(
                    records_count=records_count
                ),
                "attempted_candidate_sites": list(attempted_sites),
            }
            eca_context = dict(packet.get("eca_only_context") or {})
            eca_context["coordinate_group_focus"] = fallback_focus
            eca_context["coordinate_target_preselection"] = {
                "enabled": bool(self._coordinate_hypothesis_target_preselection_enabled()),
                "source": "coordinate_terminal_local_verifier_after_max_calls",
            }
            eca_context["coordinate_immediate_candidate_flood_guard"] = {
                "enabled": True,
                "threshold": 1,
                "source": "coordinate_terminal_local_verifier_after_max_calls",
            }
            packet["eca_only_context"] = eca_context
        except Exception as exc:
            diag["error"] = f"{type(exc).__name__}: {exc}"
            diag["terminal_local_verifier_after_max_calls"]["block_reason"] = (
                "packet_build_error"
            )
            return None, diag
        preflight_diag = coordinate_hypothesis_preflight(
            packet,
            require_candidate_sites=self._coordinate_hypothesis_require_candidate_sites_preflight(),
        )
        verification = verify_coordinate_hypothesis(
            packet,
            self._coordinate_hypothesis_default_hypothesis(),
            current_state_hash=current_hash,
        )
        candidate_sites_before_filter = list(getattr(verification, "candidate_sites", ()) or ())
        candidate_sites = [
            site
            for site in candidate_sites_before_filter
            if (int(site[0]), int(site[1])) not in self._coordinate_hypothesis_attempted_sites
        ]
        candidate_sites, requested_overlap_rank_diag = (
            self._coordinate_hypothesis_requested_target_overlap_rank(
                verification,
                candidate_sites,
                preferred_target_keys=fallback_focus.get("preferred_target_keys") or [],
            )
        )
        candidate_sites, requested_score_precondition_rank_diag = (
            self._coordinate_hypothesis_requested_target_score_precondition_rank(
                verification,
                candidate_sites,
                preferred_target_keys=fallback_focus.get("preferred_target_keys") or [],
            )
        )
        candidate_sites, post_score1_positive_delta_guard_diag = (
            self._coordinate_hypothesis_post_score1_immediate_positive_delta_guard(
                verification,
                candidate_sites,
                preferred_target_keys=fallback_focus.get("preferred_target_keys") or [],
                source="coordinate_terminal_local_verifier_after_max_calls",
            )
        )
        candidate_sites, requested_completion_preflight_rank_diag = (
            self._coordinate_hypothesis_requested_target_completion_preflight_rank(
                verification,
                candidate_sites,
                preferred_target_keys=fallback_focus.get("preferred_target_keys") or [],
            )
        )
        selected_site = candidate_sites[0] if candidate_sites else None
        active_family_retarget_diag: dict[str, Any] = {
            "enabled": bool(
                self._coordinate_hypothesis_active_family_retarget_reclick_enabled()
            ),
            "applied": False,
            "block_reason": "not_evaluated",
        }
        if selected_site is None:
            retarget_site, active_family_retarget_diag = (
                self._coordinate_hypothesis_active_family_retarget_reclick_site(
                    verification,
                    candidate_sites_before_filter=candidate_sites_before_filter,
                )
            )
            if retarget_site is not None:
                candidate_sites = [retarget_site]
                selected_site = retarget_site
        diag["preflight"] = preflight_diag
        diag["verification"] = verification.to_dict()
        diag["coordinate_group_focus"] = dict(fallback_focus)
        diag["requested_target_overlap_rank"] = requested_overlap_rank_diag
        diag["requested_target_score_precondition_rank"] = (
            requested_score_precondition_rank_diag
        )
        diag["post_score1_immediate_positive_delta_guard"] = (
            post_score1_positive_delta_guard_diag
        )
        diag["requested_target_completion_preflight_rank"] = (
            requested_completion_preflight_rank_diag
        )
        diag["active_family_retarget_reclick"] = active_family_retarget_diag
        diag["attempted_site_suppression_enabled"] = True
        diag["attempted_site_count_before_choice"] = int(
            len(self._coordinate_hypothesis_attempted_sites)
        )
        diag["candidate_sites_before_attempted_filter_count"] = int(
            len(candidate_sites_before_filter)
        )
        diag["candidate_sites_suppressed_attempted_count"] = int(
            len(candidate_sites_before_filter) - len(candidate_sites)
        )
        diag["candidate_sites_generated_from_hypothesis_count"] = int(len(candidate_sites))
        diag["candidate_sites_contains_selected_site"] = bool(selected_site in candidate_sites)
        diag["single_piece_target_family_outcome_probe"] = {
            "enabled": bool(
                self._coordinate_hypothesis_single_piece_target_family_outcome_probe_enabled()
            ),
            "applied": False,
            "block_reason": "not_needed_local_verifier_candidate_available"
            if selected_site is not None
            else "not_evaluated",
        }
        if selected_site is None:
            probe_candidate, probe_diag = (
                self._coordinate_hypothesis_single_piece_target_family_outcome_probe_candidate(
                    verification,
                    preferred_target_keys=fallback_focus.get("preferred_target_keys") or [],
                )
            )
            diag["single_piece_target_family_outcome_probe"] = probe_diag
            if probe_candidate is not None:
                route_sites = [
                    (int(site[0]), int(site[1]))
                    for site in list(probe_candidate.get("route_sites") or [])
                    if isinstance(site, (list, tuple)) and len(site) >= 2
                ]
                if route_sites:
                    selected_site = route_sites[0]
                    protected_plan_sites = list(route_sites)
                    protected_plan_remaining_sites = list(route_sites[1:])
                    coordinate_target_key = str(
                        probe_candidate.get("target_key", "") or ""
                    )
                    coordinate_target_keys = [
                        str(key or "")
                        for key in list(probe_candidate.get("target_keys") or [])
                        if str(key or "")
                    ]
                    self._coordinate_hypothesis_terminal_local_verifier_after_max_calls_count += 1
                    self._coordinate_hypothesis_single_piece_target_family_probe_choice_count += 1
                    self._coordinate_hypothesis_attempted_sites.add(
                        (int(selected_site[0]), int(selected_site[1]))
                    )
                    diag["choice_generated"] = True
                    diag["selected_site"] = [
                        int(selected_site[0]),
                        int(selected_site[1]),
                    ]
                    diag["candidate_sites_generated_from_hypothesis_count"] = int(
                        probe_candidate.get("candidate_count", 0) or 0
                    )
                    diag["candidate_sites_contains_selected_site"] = True
                    diag["attempted_site_count_after_choice"] = int(
                        len(self._coordinate_hypothesis_attempted_sites)
                    )
                    diag["protected_plan_site_count"] = int(len(protected_plan_sites))
                    diag["protected_plan_remaining_site_count"] = int(
                        len(protected_plan_remaining_sites)
                    )
                    diag["single_piece_target_family_outcome_probe"] = {
                        **dict(diag["single_piece_target_family_outcome_probe"]),
                        "choice_count_after": int(
                            self._coordinate_hypothesis_single_piece_target_family_probe_choice_count
                        ),
                    }
                    diag["terminal_local_verifier_after_max_calls"] = {
                        **dict(diag["terminal_local_verifier_after_max_calls"]),
                        "applied": True,
                        "attempt_count_after": int(
                            self._coordinate_hypothesis_terminal_local_verifier_after_max_calls_count
                        ),
                    }
                    diag["call_gate"] = {
                        **dict(diag["call_gate"]),
                        "allowed": True,
                        "block_reason": "terminal_local_verifier_single_piece_target_family_outcome_probe",
                    }
                    choice = {
                        "primitive_id": "coordinate_hypothesis_terminal_local_verifier",
                        "step": (
                            "ACTION6",
                            {"x": int(selected_site[0]), "y": int(selected_site[1])},
                        ),
                        "reason": (
                            "coordinate_hypothesis_terminal_local_verifier promoted a "
                            "diagnostic single-piece target-family route as an "
                            "outcome-gated protected probe"
                        ),
                        "selected_site": [
                            int(selected_site[0]),
                            int(selected_site[1]),
                        ],
                        "candidate_count": int(
                            probe_candidate.get("candidate_count", 0) or 0
                        ),
                        "hypothesis": self._coordinate_hypothesis_default_hypothesis(),
                        "protected_plan_sites": [
                            [int(site[0]), int(site[1])] for site in protected_plan_sites
                        ],
                        "protected_plan_remaining_sites": [
                            [int(site[0]), int(site[1])]
                            for site in protected_plan_remaining_sites
                        ],
                        "coordinate_target_key": str(coordinate_target_key),
                        "coordinate_target_keys": list(coordinate_target_keys),
                        "terminal_completion_best_incomplete_fallback_applied": False,
                        "single_piece_target_family_outcome_probe_applied": True,
                        "single_piece_target_family_outcome_probe_route_key": str(
                            probe_candidate.get("route_key", "") or ""
                        ),
                        "single_piece_target_family_outcome_probe_route_sites": [
                            [int(site[0]), int(site[1])] for site in protected_plan_sites
                        ],
                    }
                    return choice, diag
            diag["terminal_local_verifier_after_max_calls"]["block_reason"] = (
                "no_fresh_local_verifier_candidate"
            )
            diag["call_gate"] = {
                **dict(diag["call_gate"]),
                "block_reason": "no_fresh_local_verifier_candidate",
            }
            return None, diag
        self._coordinate_hypothesis_terminal_local_verifier_after_max_calls_count += 1
        self._coordinate_hypothesis_attempted_sites.add(
            (int(selected_site[0]), int(selected_site[1]))
        )
        protected_plan_sites = self._coordinate_hypothesis_execution_sites_from_verification(
            verification
        )
        best_incomplete_fallback_applied = (
            self._coordinate_hypothesis_best_incomplete_fallback_applied_from_verification(
                verification
            )
        )
        coordinate_target_key = self._coordinate_hypothesis_target_key_from_verification(
            verification,
            selected_site=selected_site,
            allow_immediate_metadata=True,
        )
        coordinate_target_keys = self._coordinate_hypothesis_target_keys_from_verification(
            verification,
            selected_site=selected_site,
            allow_immediate_metadata=True,
        )
        selected_site_key = (int(selected_site[0]), int(selected_site[1]))
        if protected_plan_sites and protected_plan_sites[0] == selected_site_key:
            protected_plan_remaining_sites = protected_plan_sites[1:]
        else:
            protected_plan_sites = []
            protected_plan_remaining_sites = []
        detour_metadata = (
            self._coordinate_hypothesis_self_overlap_detour_metadata_from_verification(
                verification
            )
        )
        diag["terminal_self_overlap_detour"] = dict(detour_metadata)
        diag["choice_generated"] = True
        diag["selected_site"] = [int(selected_site[0]), int(selected_site[1])]
        diag["attempted_site_count_after_choice"] = int(
            len(self._coordinate_hypothesis_attempted_sites)
        )
        diag["protected_plan_site_count"] = int(len(protected_plan_sites))
        diag["protected_plan_remaining_site_count"] = int(len(protected_plan_remaining_sites))
        diag["terminal_local_verifier_after_max_calls"] = {
            **dict(diag["terminal_local_verifier_after_max_calls"]),
            "applied": True,
            "attempt_count_after": int(
                self._coordinate_hypothesis_terminal_local_verifier_after_max_calls_count
            ),
        }
        diag["call_gate"] = {
            **dict(diag["call_gate"]),
            "allowed": True,
            "block_reason": "terminal_local_verifier_after_max_calls",
        }
        choice = {
            "primitive_id": "coordinate_hypothesis_terminal_local_verifier",
            "step": ("ACTION6", {"x": int(selected_site[0]), "y": int(selected_site[1])}),
            "reason": (
                "coordinate_hypothesis_terminal_local_verifier continued with an "
                "ECA-only verifier candidate after provider max_calls"
            ),
            "selected_site": [int(selected_site[0]), int(selected_site[1])],
            "candidate_count": int(len(candidate_sites)),
            "hypothesis": self._coordinate_hypothesis_default_hypothesis(),
            "protected_plan_sites": [
                [int(site[0]), int(site[1])] for site in protected_plan_sites
            ],
            "protected_plan_remaining_sites": [
                [int(site[0]), int(site[1])] for site in protected_plan_remaining_sites
            ],
            "coordinate_target_key": str(coordinate_target_key),
            "coordinate_target_keys": list(coordinate_target_keys),
            "terminal_completion_best_incomplete_fallback_applied": bool(
                best_incomplete_fallback_applied
            ),
            "terminal_self_overlap_detour_used": bool(detour_metadata.get("used")),
            "terminal_self_overlap_detour_count": int(
                detour_metadata.get("count", 0) or 0
            ),
            "terminal_self_overlap_detour": dict(detour_metadata.get("detour") or {}),
        }
        return choice, diag

    def _coordinate_hypothesis_post_peak_replan_target_keys_from_outcome(
        self,
        outcome: Mapping[str, Any],
    ) -> list[str]:
        source_target_key = str(
            outcome.get("requested_target_key", "")
            or outcome.get("post_target_key", "")
            or outcome.get("pre_target_key", "")
            or ""
        )
        keys: list[str] = []
        fallback: list[str] = []
        for raw_key in list(outcome.get("post_unsatisfied_target_keys") or []):
            key = str(raw_key or "")
            if not key:
                continue
            if not _coordinate_target_key_matches_any(key, fallback):
                fallback.append(key)
            if source_target_key and _coordinate_target_keys_match(source_target_key, key):
                continue
            if not _coordinate_target_key_matches_any(key, keys):
                keys.append(key)
        return keys or fallback

    def _coordinate_hypothesis_terminal_best_incomplete_post_peak_replan_choice(
        self,
        *,
        frame_arr: np.ndarray,
        current_hash: str,
        available_actions: set[str],
        records_count: int,
        blocked_by_stable_solver: bool,
        stable_solver_reasons: list[str],
    ) -> tuple[dict[str, Any] | None, dict[str, Any]]:
        enabled = bool(
            self._coordinate_hypothesis_terminal_best_incomplete_post_peak_replan_enabled()
        )
        state = dict(self._coordinate_hypothesis_terminal_best_incomplete_post_peak_replan or {})
        target_keys = [
            str(key or "")
            for key in list(state.get("target_keys") or [])
            if str(key or "")
        ]
        max_attempts = (
            self._coordinate_hypothesis_terminal_best_incomplete_post_peak_replan_max_attempts()
        )
        attempt_count = int(state.get("attempt_count", 0) or 0)
        diag: dict[str, Any] = {
            "enabled": bool(self._coordinate_hypothesis_lane_enabled()),
            "provider_available": bool(self.coordinate_hypothesis_bridge.provider is not None),
            "provider_called": False,
            "choice_generated": False,
            "selected_site": [],
            "candidate_sites_generated_from_hypothesis_count": 0,
            "candidate_sites_contains_selected_site": False,
            "direct_llm_action_blocked_count": 0,
            "terminal_best_incomplete_post_peak_replan": {
                "enabled": bool(enabled),
                "available": bool(target_keys),
                "target_keys": list(target_keys),
                "attempt_count": int(attempt_count),
                "max_attempts": int(max_attempts),
                "applied": False,
                "block_reason": "",
            },
            "call_gate": {
                "configured_enabled": bool(self._coordinate_hypothesis_lane_enabled()),
                "allowed": False,
                "block_reason": "terminal_best_incomplete_post_peak_replan_not_selected",
                "records_count": int(records_count),
                "provider_call_count_before": int(self._coordinate_hypothesis_provider_call_count),
                "provider_call_count_after": int(self._coordinate_hypothesis_provider_call_count),
                "score_success_count": int(self._coordinate_hypothesis_score_success_count),
                "stable_solver_reasons": list(stable_solver_reasons),
            },
        }
        preserve_no_candidate_attempts = bool(
            self._coordinate_hypothesis_terminal_best_incomplete_post_peak_replan_preserve_no_candidate_attempts_enabled()
        )
        require_target_bound_plan = bool(
            self._coordinate_hypothesis_terminal_best_incomplete_post_peak_replan_require_target_bound_plan_enabled()
        )
        max_unbound_plan_prechecks = int(
            self._coordinate_hypothesis_terminal_best_incomplete_post_peak_replan_max_unbound_plan_prechecks()
        )
        unbound_plan_precheck_count = int(
            state.get("unbound_target_plan_precheck_count", 0) or 0
        )
        best_incomplete_fallback_enabled = bool(
            self._coordinate_hypothesis_terminal_best_incomplete_post_peak_replan_best_incomplete_fallback_enabled()
        )
        best_incomplete_fallback_application_count = int(
            state.get("best_incomplete_fallback_application_count", 0) or 0
        )
        best_incomplete_fallback_max_applications = int(
            self._coordinate_hypothesis_terminal_best_incomplete_post_peak_replan_best_incomplete_max_applications()
        )
        best_incomplete_fallback_min_coverage = int(
            self._coordinate_hypothesis_terminal_best_incomplete_post_peak_replan_best_incomplete_min_coverage()
        )
        diag["terminal_best_incomplete_post_peak_replan"][
            "preserve_no_candidate_attempts_enabled"
        ] = bool(preserve_no_candidate_attempts)
        diag["terminal_best_incomplete_post_peak_replan"][
            "require_target_bound_plan_enabled"
        ] = bool(require_target_bound_plan)
        diag["terminal_best_incomplete_post_peak_replan"][
            "unbound_target_plan_precheck_count"
        ] = int(unbound_plan_precheck_count)
        diag["terminal_best_incomplete_post_peak_replan"][
            "max_unbound_target_plan_prechecks"
        ] = int(max_unbound_plan_prechecks)
        diag["terminal_best_incomplete_post_peak_replan"][
            "best_incomplete_fallback_enabled"
        ] = bool(best_incomplete_fallback_enabled)
        diag["terminal_best_incomplete_post_peak_replan"][
            "best_incomplete_fallback_application_count"
        ] = int(best_incomplete_fallback_application_count)
        diag["terminal_best_incomplete_post_peak_replan"][
            "best_incomplete_fallback_max_applications"
        ] = int(best_incomplete_fallback_max_applications)
        diag["terminal_best_incomplete_post_peak_replan"][
            "best_incomplete_fallback_min_coverage"
        ] = int(best_incomplete_fallback_min_coverage)
        block_reason = ""
        if not enabled:
            block_reason = "terminal_best_incomplete_post_peak_replan_disabled"
        elif not self._coordinate_hypothesis_lane_enabled():
            block_reason = "coordinate_hypothesis_lane_disabled"
        elif not target_keys:
            block_reason = "no_post_peak_replan_target"
        elif "ACTION6" not in available_actions:
            block_reason = "action6_unavailable"
        elif bool(blocked_by_stable_solver):
            block_reason = "stable_solver_available"
        elif max_attempts <= 0:
            block_reason = "post_peak_replan_max_attempts_zero"
        elif attempt_count >= max_attempts:
            block_reason = "post_peak_replan_max_attempts"
        elif (
            require_target_bound_plan
            and unbound_plan_precheck_count >= max_unbound_plan_prechecks
        ):
            block_reason = "post_peak_replan_unbound_target_plan_max_prechecks"
        if block_reason:
            diag["terminal_best_incomplete_post_peak_replan"]["block_reason"] = block_reason
            diag["call_gate"] = {
                **dict(diag["call_gate"]),
                "block_reason": block_reason,
            }
            return None, diag
        try:
            packet = build_r11l_l1_coordinate_sensor_packet(
                frame_arr,
                state_hash=current_hash,
                step=int(records_count),
                remembered_targets=self._coordinate_hypothesis_remembered_targets(),
                include_eca_only_context=True,
            )
            self._remember_coordinate_hypothesis_targets(packet)
            group_focus = self._coordinate_hypothesis_group_focus_payload_from_packet(packet)
            suppressed_target_keys = [
                key
                for key in list(group_focus.get("suppressed_target_keys") or [])
                if not _coordinate_target_key_matches_any(str(key or ""), target_keys)
            ]
            attempted_sites = [
                [int(site[0]), int(site[1])]
                for site in sorted(self._coordinate_hypothesis_attempted_sites)
            ]
            replan_focus = {
                **dict(group_focus),
                "enabled": True,
                "preferred_target_keys": list(target_keys),
                "suppressed_target_keys": list(suppressed_target_keys),
                "source": "terminal_best_incomplete_post_peak_replan",
                "strict_preferred_targets": False,
                "terminal_attempted_site_alternatives_enabled": bool(
                    self._coordinate_hypothesis_terminal_attempted_site_alternatives_enabled()
                ),
                "terminal_execution_order_alternatives_enabled": bool(
                    self._coordinate_hypothesis_terminal_execution_order_alternatives_enabled()
                ),
                "terminal_execution_order_canvas_safety_enabled": bool(
                    self._coordinate_hypothesis_terminal_execution_order_canvas_safety_enabled()
                ),
                "terminal_immediate_target_diversity_enabled": bool(
                    self._coordinate_hypothesis_terminal_immediate_target_diversity_enabled()
                ),
                "terminal_structured_target_diversity_enabled": bool(
                    self._coordinate_hypothesis_terminal_structured_target_diversity_enabled()
                ),
                "terminal_immediate_move_click_empty_guard_enabled": bool(
                    self._coordinate_hypothesis_terminal_immediate_move_click_empty_guard_enabled()
                ),
                "terminal_joint_action_budget_guard_enabled": bool(
                    self._coordinate_hypothesis_terminal_joint_action_budget_guard_enabled()
                ),
                "terminal_joint_single_target_after_score_guard_enabled": bool(
                    self._coordinate_hypothesis_terminal_joint_single_target_after_score_guard_enabled()
                ),
                **self._coordinate_hypothesis_terminal_joint_single_target_after_score_ceiling_payload(),
                "terminal_completion_coverage_guard_enabled": bool(
                    self._coordinate_hypothesis_terminal_completion_coverage_guard_enabled()
                ),
                "terminal_completion_best_incomplete_telemetry_enabled": bool(
                    self._coordinate_hypothesis_terminal_completion_best_incomplete_telemetry_enabled()
                ),
                "terminal_completion_best_incomplete_fallback_enabled": bool(
                    best_incomplete_fallback_enabled
                ),
                "terminal_completion_best_incomplete_min_coverage": int(
                    best_incomplete_fallback_min_coverage
                ),
                "terminal_completion_best_incomplete_fallback_application_count": int(
                    best_incomplete_fallback_application_count
                ),
                "terminal_completion_best_incomplete_max_applications": int(
                    best_incomplete_fallback_max_applications
                ),
                "terminal_target_color_coverage_rank_enabled": bool(
                    self._coordinate_hypothesis_terminal_best_incomplete_post_peak_replan_target_color_rank_enabled()
                ),
                "terminal_exact_color_target_match_enabled": bool(
                    self._coordinate_hypothesis_terminal_exact_color_target_match_enabled()
                ),
                "terminal_canvas_primary_color_grouping_enabled": bool(
                    self._coordinate_hypothesis_terminal_canvas_primary_color_grouping_enabled()
                ),
                **self._coordinate_hypothesis_terminal_structured_action_budget_payload(
                    records_count=records_count
                ),
                "attempted_candidate_sites": list(attempted_sites),
            }
            eca_context = dict(packet.get("eca_only_context") or {})
            eca_context["coordinate_group_focus"] = replan_focus
            eca_context["coordinate_target_preselection"] = {
                "enabled": bool(self._coordinate_hypothesis_target_preselection_enabled()),
                "source": "terminal_best_incomplete_post_peak_replan",
            }
            eca_context["coordinate_immediate_candidate_flood_guard"] = {
                "enabled": True,
                "threshold": 1,
                "source": "terminal_best_incomplete_post_peak_replan",
            }
            packet["eca_only_context"] = eca_context
        except Exception as exc:
            diag["error"] = f"{type(exc).__name__}: {exc}"
            diag["terminal_best_incomplete_post_peak_replan"]["block_reason"] = (
                "packet_build_error"
            )
            return None, diag
        verification = verify_coordinate_hypothesis(
            packet,
            self._coordinate_hypothesis_default_hypothesis(),
            current_state_hash=current_hash,
        )
        candidate_sites_before_filter = list(getattr(verification, "candidate_sites", ()) or ())
        candidate_sites = [
            site
            for site in candidate_sites_before_filter
            if (int(site[0]), int(site[1])) not in self._coordinate_hypothesis_attempted_sites
        ]
        candidate_sites, requested_overlap_rank_diag = (
            self._coordinate_hypothesis_requested_target_overlap_rank(
                verification,
                candidate_sites,
                preferred_target_keys=target_keys,
            )
        )
        candidate_sites, requested_score_precondition_rank_diag = (
            self._coordinate_hypothesis_requested_target_score_precondition_rank(
                verification,
                candidate_sites,
                preferred_target_keys=target_keys,
            )
        )
        candidate_sites, requested_completion_preflight_rank_diag = (
            self._coordinate_hypothesis_requested_target_completion_preflight_rank(
                verification,
                candidate_sites,
                preferred_target_keys=target_keys,
            )
        )
        selected_site = candidate_sites[0] if candidate_sites else None
        raw_protected_plan_sites = self._coordinate_hypothesis_execution_sites_from_verification(
            verification
        )
        coordinate_target_key = self._coordinate_hypothesis_target_key_from_verification(
            verification,
            selected_site=selected_site,
            allow_immediate_metadata=True,
        )
        coordinate_target_keys = self._coordinate_hypothesis_target_keys_from_verification(
            verification,
            selected_site=selected_site,
            allow_immediate_metadata=True,
        )
        best_incomplete_fallback_applied = (
            self._coordinate_hypothesis_best_incomplete_fallback_applied_from_verification(
                verification
            )
        )
        diag["verification"] = verification.to_dict()
        diag["coordinate_group_focus"] = dict(replan_focus)
        diag["requested_target_overlap_rank"] = requested_overlap_rank_diag
        diag["requested_target_score_precondition_rank"] = (
            requested_score_precondition_rank_diag
        )
        diag["requested_target_completion_preflight_rank"] = (
            requested_completion_preflight_rank_diag
        )
        diag["attempted_site_suppression_enabled"] = True
        diag["attempted_site_count_before_choice"] = int(
            len(self._coordinate_hypothesis_attempted_sites)
        )
        diag["candidate_sites_before_attempted_filter_count"] = int(
            len(candidate_sites_before_filter)
        )
        diag["candidate_sites_suppressed_attempted_count"] = int(
            len(candidate_sites_before_filter) - len(candidate_sites)
        )
        diag["candidate_sites_generated_from_hypothesis_count"] = int(len(candidate_sites))
        diag["candidate_sites_contains_selected_site"] = bool(selected_site in candidate_sites)
        diag["protected_plan_site_count"] = int(len(raw_protected_plan_sites))
        diag["protected_plan_remaining_site_count"] = 0
        diag["terminal_best_incomplete_post_peak_replan"]["resolved_target_key"] = str(
            coordinate_target_key
        )
        diag["terminal_best_incomplete_post_peak_replan"][
            "best_incomplete_fallback_applied"
        ] = bool(best_incomplete_fallback_applied)
        diag["terminal_best_incomplete_post_peak_replan"][
            "verification_summary"
        ] = self._coordinate_hypothesis_structured_summary_from_verification(
            verification
        )
        if selected_site is None:
            state["last_block_reason"] = "no_fresh_post_peak_replan_candidate"
            state["no_candidate_precheck_count"] = (
                int(state.get("no_candidate_precheck_count", 0) or 0) + 1
            )
            if preserve_no_candidate_attempts:
                state["last_no_candidate_preserved_attempt"] = True
                self._coordinate_hypothesis_terminal_best_incomplete_post_peak_replan = state
            else:
                state["attempt_count"] = int(attempt_count) + 1
                if int(state["attempt_count"]) >= int(max_attempts):
                    self._coordinate_hypothesis_terminal_best_incomplete_post_peak_replan.clear()
                else:
                    self._coordinate_hypothesis_terminal_best_incomplete_post_peak_replan = state
            diag["terminal_best_incomplete_post_peak_replan"]["block_reason"] = (
                "no_fresh_post_peak_replan_candidate"
            )
            diag["terminal_best_incomplete_post_peak_replan"][
                "no_candidate_attempt_preserved"
            ] = bool(preserve_no_candidate_attempts)
            diag["terminal_best_incomplete_post_peak_replan"][
                "no_candidate_precheck_count_after"
            ] = int(state.get("no_candidate_precheck_count", 0) or 0)
            diag["terminal_best_incomplete_post_peak_replan"]["attempt_count_after"] = int(
                state.get("attempt_count", attempt_count) or 0
            )
            diag["call_gate"] = {
                **dict(diag["call_gate"]),
                "block_reason": "no_fresh_post_peak_replan_candidate",
            }
            return None, diag
        selected_site_key = (int(selected_site[0]), int(selected_site[1]))
        protected_plan_sites = list(raw_protected_plan_sites)
        if protected_plan_sites and protected_plan_sites[0] == selected_site_key:
            protected_plan_remaining_sites = protected_plan_sites[1:]
        else:
            protected_plan_sites = []
            protected_plan_remaining_sites = []
        if require_target_bound_plan and (
            not protected_plan_sites or not str(coordinate_target_key or "")
        ):
            state["last_block_reason"] = "post_peak_replan_unbound_target_plan"
            state["unbound_target_plan_precheck_count"] = (
                int(state.get("unbound_target_plan_precheck_count", 0) or 0) + 1
            )
            state["last_unbound_target_plan_preserved_attempt"] = True
            self._coordinate_hypothesis_terminal_best_incomplete_post_peak_replan = state
            diag["selected_site"] = [int(selected_site[0]), int(selected_site[1])]
            diag["protected_plan_site_count"] = int(len(protected_plan_sites))
            diag["protected_plan_remaining_site_count"] = int(
                len(protected_plan_remaining_sites)
            )
            diag["terminal_best_incomplete_post_peak_replan"]["block_reason"] = (
                "post_peak_replan_unbound_target_plan"
            )
            diag["terminal_best_incomplete_post_peak_replan"][
                "target_bound_plan_required"
            ] = True
            diag["terminal_best_incomplete_post_peak_replan"][
                "target_bound_plan_attempt_preserved"
            ] = True
            diag["terminal_best_incomplete_post_peak_replan"][
                "unbound_target_plan_precheck_count_after"
            ] = int(state.get("unbound_target_plan_precheck_count", 0) or 0)
            diag["terminal_best_incomplete_post_peak_replan"]["attempt_count_after"] = int(
                state.get("attempt_count", attempt_count) or 0
            )
            diag["call_gate"] = {
                **dict(diag["call_gate"]),
                "block_reason": "post_peak_replan_unbound_target_plan",
            }
            return None, diag
        self._coordinate_hypothesis_attempted_sites.add(
            (int(selected_site[0]), int(selected_site[1]))
        )
        state["attempt_count"] = int(attempt_count) + 1
        state["last_selected_site"] = [int(selected_site[0]), int(selected_site[1])]
        if best_incomplete_fallback_applied:
            state["best_incomplete_fallback_application_count"] = (
                int(best_incomplete_fallback_application_count) + 1
            )
        self._coordinate_hypothesis_terminal_best_incomplete_post_peak_replan = state
        diag["choice_generated"] = True
        diag["selected_site"] = [int(selected_site[0]), int(selected_site[1])]
        diag["attempted_site_count_after_choice"] = int(
            len(self._coordinate_hypothesis_attempted_sites)
        )
        diag["protected_plan_site_count"] = int(len(protected_plan_sites))
        diag["protected_plan_remaining_site_count"] = int(len(protected_plan_remaining_sites))
        diag["terminal_best_incomplete_post_peak_replan"] = {
            **dict(diag["terminal_best_incomplete_post_peak_replan"]),
            "applied": True,
            "attempt_count_after": int(state["attempt_count"]),
            "selected_site": [int(selected_site[0]), int(selected_site[1])],
            "resolved_target_key": str(coordinate_target_key),
            "best_incomplete_fallback_application_count_after": int(
                state.get(
                    "best_incomplete_fallback_application_count",
                    best_incomplete_fallback_application_count,
                )
                or 0
            ),
        }
        diag["call_gate"] = {
            **dict(diag["call_gate"]),
            "allowed": True,
            "block_reason": "terminal_best_incomplete_post_peak_replan",
        }
        choice = {
            "primitive_id": "coordinate_hypothesis_post_peak_replan",
            "step": ("ACTION6", {"x": int(selected_site[0]), "y": int(selected_site[1])}),
            "reason": (
                "coordinate_hypothesis_post_peak_replan used an ECA-only verifier "
                "candidate after terminal best-incomplete peak-stop"
            ),
            "selected_site": [int(selected_site[0]), int(selected_site[1])],
            "candidate_count": int(len(candidate_sites)),
            "hypothesis": self._coordinate_hypothesis_default_hypothesis(),
            "protected_plan_sites": [
                [int(site[0]), int(site[1])] for site in protected_plan_sites
            ],
            "protected_plan_remaining_sites": [
                [int(site[0]), int(site[1])] for site in protected_plan_remaining_sites
            ],
            "coordinate_target_key": str(coordinate_target_key),
            "coordinate_target_keys": list(coordinate_target_keys or target_keys),
            "terminal_best_incomplete_post_peak_replan": True,
            "terminal_best_incomplete_post_peak_replan_target_keys": list(target_keys),
            "terminal_completion_best_incomplete_fallback_applied": bool(
                best_incomplete_fallback_applied
            ),
        }
        return choice, diag

    def _coordinate_hypothesis_choice(
        self,
        *,
        frame_arr: np.ndarray,
        current_hash: str,
        available_actions: set[str],
        records_count: int,
        blocked_by_stable_solver: bool,
        stable_solver_reasons: list[str],
    ) -> tuple[dict[str, Any] | None, dict[str, Any]]:
        allowed, call_gate = self._coordinate_hypothesis_call_gate(
            records_count=records_count,
            available_actions=available_actions,
            blocked_by_stable_solver=blocked_by_stable_solver,
            stable_solver_reasons=stable_solver_reasons,
        )
        provider_flood_guard_enabled = bool(
            self._coordinate_hypothesis_provider_immediate_flood_guard_enabled()
        )
        provider_flood_threshold = self._coordinate_hypothesis_provider_immediate_flood_threshold()
        empty_diag: dict[str, Any] = {
            "enabled": bool(self._coordinate_hypothesis_lane_enabled()),
            "provider_available": bool(self.coordinate_hypothesis_bridge.provider is not None),
            "provider_called": False,
            "choice_generated": False,
            "selected_site": [],
            "candidate_sites_generated_from_hypothesis_count": 0,
            "candidate_sites_contains_selected_site": False,
            "direct_llm_action_blocked_count": 0,
            "preflight": {
                "enabled": bool(self._coordinate_hypothesis_require_candidate_triple()),
                "passed": None,
                "block_reason": "",
            },
            "provider_immediate_flood_guard": {
                "enabled": bool(provider_flood_guard_enabled),
                "threshold": int(provider_flood_threshold),
                "eligible": False,
                "applied_to_packet": False,
            },
            "call_gate": {
                **call_gate,
                "provider_call_count_after": int(self._coordinate_hypothesis_provider_call_count),
            },
        }
        if not allowed:
            if str(call_gate.get("block_reason", "") or "") == "max_calls":
                local_choice, local_diag = (
                    self._coordinate_hypothesis_terminal_local_verifier_choice(
                        frame_arr=frame_arr,
                        current_hash=current_hash,
                        records_count=records_count,
                        call_gate=call_gate,
                    )
                )
                if local_choice is not None:
                    return local_choice, local_diag
                empty_diag["terminal_local_verifier_after_max_calls"] = dict(
                    local_diag.get("terminal_local_verifier_after_max_calls") or {}
                )
                empty_diag["terminal_local_verifier_preflight"] = local_diag.get("preflight")
                empty_diag["terminal_local_verifier_verification"] = local_diag.get(
                    "verification"
                )
            return None, empty_diag
        try:
            remembered_targets = self._coordinate_hypothesis_remembered_targets()
            packet = build_r11l_l1_coordinate_sensor_packet(
                frame_arr,
                state_hash=current_hash,
                step=int(records_count),
                remembered_targets=remembered_targets,
                include_eca_only_context=True,
            )
            self._remember_coordinate_hypothesis_targets(packet)
            empty_diag["remembered_target_count"] = int(
                len(self._coordinate_hypothesis_r11l_target_memory)
            )
            group_focus = self._coordinate_hypothesis_group_focus_payload_from_packet(packet)
            group_focus = {
                **dict(group_focus),
                "terminal_execution_order_canvas_safety_enabled": bool(
                    self._coordinate_hypothesis_terminal_execution_order_canvas_safety_enabled()
                ),
                "terminal_joint_action_budget_guard_enabled": bool(
                    self._coordinate_hypothesis_terminal_joint_action_budget_guard_enabled()
                ),
                "terminal_joint_single_target_after_score_guard_enabled": bool(
                    self._coordinate_hypothesis_terminal_joint_single_target_after_score_guard_enabled()
                ),
                **self._coordinate_hypothesis_terminal_joint_single_target_after_score_ceiling_payload(),
                "terminal_completion_coverage_guard_enabled": bool(
                    self._coordinate_hypothesis_terminal_completion_coverage_guard_enabled()
                ),
                "terminal_completion_best_incomplete_telemetry_enabled": bool(
                    self._coordinate_hypothesis_terminal_completion_best_incomplete_telemetry_enabled()
                ),
                "terminal_completion_best_incomplete_fallback_enabled": bool(
                    self._coordinate_hypothesis_terminal_completion_best_incomplete_fallback_enabled()
                ),
                "terminal_completion_best_incomplete_min_coverage": int(
                    self._coordinate_hypothesis_terminal_completion_best_incomplete_min_coverage()
                ),
                "terminal_completion_best_incomplete_fallback_application_count": int(
                    self._coordinate_hypothesis_terminal_best_incomplete_fallback_applied_count
                ),
                "terminal_completion_best_incomplete_max_applications": int(
                    self._coordinate_hypothesis_terminal_completion_best_incomplete_max_applications()
                ),
                **self._coordinate_hypothesis_terminal_structured_action_budget_payload(
                    records_count=records_count
                ),
            }
            if bool(group_focus.get("enabled")):
                eca_context = dict(packet.get("eca_only_context") or {})
                eca_context["coordinate_group_focus"] = group_focus
                preferred_target_keys = [
                    str(key or "") for key in list(group_focus.get("preferred_target_keys") or [])
                    if str(key or "")
                ]
                provider_flood_guard_eligible = bool(preferred_target_keys)
                empty_diag["provider_immediate_flood_guard"]["eligible"] = bool(
                    provider_flood_guard_eligible
                )
                if provider_flood_guard_enabled and provider_flood_guard_eligible:
                    eca_context["coordinate_immediate_candidate_flood_guard"] = {
                        "enabled": True,
                        "threshold": int(provider_flood_threshold),
                        "source": "coordinate_provider_choice_unsatisfied_group_focus",
                    }
                    empty_diag["provider_immediate_flood_guard"]["applied_to_packet"] = True
                packet["eca_only_context"] = eca_context
            empty_diag["coordinate_group_focus"] = group_focus
        except Exception as exc:
            empty_diag["error"] = f"{type(exc).__name__}: {exc}"
            return None, empty_diag
        require_preflight = self._coordinate_hypothesis_require_candidate_triple()
        suppress_attempted_sites = self._coordinate_hypothesis_suppress_attempted_sites()
        min_preflight_candidate_sites = self._coordinate_hypothesis_min_preflight_candidate_sites()
        min_candidate_relax_after_blocks = (
            self._coordinate_hypothesis_min_preflight_candidate_sites_relax_after_blocks()
        )
        preflight_diag: dict[str, Any] = {
            "enabled": bool(require_preflight),
            "passed": True,
            "block_reason": "",
            "min_candidate_sites": int(min_preflight_candidate_sites),
            "min_candidate_sites_relax_after_blocks": int(min_candidate_relax_after_blocks),
            "min_candidate_site_block_count": int(
                self._coordinate_hypothesis_min_candidate_site_block_count
            ),
        }
        if require_preflight:
            preflight_diag = coordinate_hypothesis_preflight(
                packet,
                require_candidate_sites=self._coordinate_hypothesis_require_candidate_sites_preflight(),
            )
            preflight_diag["min_candidate_sites"] = int(min_preflight_candidate_sites)
            preflight_diag["min_candidate_sites_relax_after_blocks"] = int(
                min_candidate_relax_after_blocks
            )
            preflight_diag["min_candidate_site_block_count"] = int(
                self._coordinate_hypothesis_min_candidate_site_block_count
            )
            empty_diag["preflight"] = preflight_diag
            if not bool(preflight_diag.get("passed")):
                block_reason = str(
                    preflight_diag.get("block_reason", "coordinate_hypothesis_preflight_blocked")
                    or "coordinate_hypothesis_preflight_blocked"
                )
                empty_diag["call_gate"] = {
                    **call_gate,
                    "allowed": False,
                    "block_reason": block_reason,
                    "provider_call_count_after": int(self._coordinate_hypothesis_provider_call_count),
                }
                return None, empty_diag
            if suppress_attempted_sites:
                preflight_sites = [
                    (int(site[0]), int(site[1]))
                    for site in list(preflight_diag.get("candidate_sites") or [])
                    if isinstance(site, (list, tuple)) and len(site) >= 2
                ]
                fresh_preflight_sites = [
                    site for site in preflight_sites if site not in self._coordinate_hypothesis_attempted_sites
                ]
                preflight_diag["attempted_site_suppression_enabled"] = True
                preflight_diag["attempted_site_count"] = int(len(self._coordinate_hypothesis_attempted_sites))
                preflight_diag["candidate_sites_after_attempted_filter_count"] = int(len(fresh_preflight_sites))
                if preflight_sites and not fresh_preflight_sites:
                    fallback_diag = {
                        "enabled": bool(
                            self._coordinate_hypothesis_terminal_structured_preflight_fallback_enabled()
                        ),
                        "eligible": bool(
                            group_focus.get("suppressed_target_keys")
                            and group_focus.get("preferred_target_keys")
                        ),
                        "applied": False,
                        "block_reason": "",
                        "source": "all_coordinate_preflight_sites_attempted",
                        "candidate_sites_before_attempted_filter_count": 0,
                        "candidate_sites_after_attempted_filter_count": 0,
                    }
                    if bool(fallback_diag["enabled"]) and bool(fallback_diag["eligible"]):
                        fallback_context = dict(packet.get("eca_only_context") or {})
                        fallback_group_focus = dict(group_focus)
                        fallback_attempted_sites = [
                            [int(site[0]), int(site[1])]
                            for site in sorted(self._coordinate_hypothesis_attempted_sites)
                        ]
                        fallback_attempted_alternatives_enabled = bool(
                            self._coordinate_hypothesis_terminal_attempted_site_alternatives_enabled()
                        )
                        fallback_execution_order_alternatives_enabled = bool(
                            self._coordinate_hypothesis_terminal_execution_order_alternatives_enabled()
                        )
                        if self._coordinate_hypothesis_terminal_attempted_site_alternatives_enabled():
                            fallback_group_focus[
                                "terminal_attempted_site_alternatives_enabled"
                            ] = True
                            fallback_group_focus["attempted_candidate_sites"] = list(
                                fallback_attempted_sites
                            )
                        if fallback_execution_order_alternatives_enabled:
                            fallback_group_focus[
                                "terminal_execution_order_alternatives_enabled"
                            ] = True
                            fallback_group_focus["attempted_candidate_sites"] = list(
                                fallback_attempted_sites
                            )
                        if (
                            self._coordinate_hypothesis_terminal_execution_order_canvas_safety_enabled()
                        ):
                            fallback_group_focus[
                                "terminal_execution_order_canvas_safety_enabled"
                            ] = True
                        if self._coordinate_hypothesis_terminal_joint_action_budget_guard_enabled():
                            fallback_group_focus[
                                "terminal_joint_action_budget_guard_enabled"
                            ] = True
                        if self._coordinate_hypothesis_terminal_completion_coverage_guard_enabled():
                            fallback_group_focus[
                                "terminal_completion_coverage_guard_enabled"
                            ] = True
                        if self._coordinate_hypothesis_terminal_completion_best_incomplete_telemetry_enabled():
                            fallback_group_focus[
                                "terminal_completion_best_incomplete_telemetry_enabled"
                            ] = True
                        if self._coordinate_hypothesis_terminal_completion_best_incomplete_fallback_enabled():
                            fallback_group_focus[
                                "terminal_completion_best_incomplete_fallback_enabled"
                            ] = True
                            fallback_group_focus[
                                "terminal_completion_best_incomplete_min_coverage"
                            ] = int(
                                self._coordinate_hypothesis_terminal_completion_best_incomplete_min_coverage()
                            )
                            fallback_group_focus[
                                "terminal_completion_best_incomplete_fallback_application_count"
                            ] = int(
                                self._coordinate_hypothesis_terminal_best_incomplete_fallback_applied_count
                            )
                            fallback_group_focus[
                                "terminal_completion_best_incomplete_max_applications"
                            ] = int(
                                self._coordinate_hypothesis_terminal_completion_best_incomplete_max_applications()
                            )
                        if self._coordinate_hypothesis_terminal_structured_target_diversity_enabled():
                            fallback_group_focus[
                                "terminal_structured_target_diversity_enabled"
                            ] = True
                        fallback_group_focus = {
                            **dict(fallback_group_focus),
                            **self._coordinate_hypothesis_terminal_structured_action_budget_payload(
                                records_count=records_count
                            ),
                        }
                        fallback_context["coordinate_group_focus"] = fallback_group_focus
                        fallback_context["coordinate_immediate_candidate_flood_guard"] = {
                            "enabled": True,
                            "threshold": 1,
                            "source": "terminal_structured_preflight_fallback",
                        }
                        fallback_packet = dict(packet)
                        fallback_packet["eca_only_context"] = fallback_context
                        fallback_preflight = coordinate_hypothesis_preflight(
                            fallback_packet,
                            require_candidate_sites=self._coordinate_hypothesis_require_candidate_sites_preflight(),
                        )
                        fallback_sites = [
                            (int(site[0]), int(site[1]))
                            for site in list(fallback_preflight.get("candidate_sites") or [])
                            if isinstance(site, (list, tuple)) and len(site) >= 2
                        ]
                        fallback_fresh_sites = [
                            site
                            for site in fallback_sites
                            if site not in self._coordinate_hypothesis_attempted_sites
                        ]
                        fallback_candidate_generation = dict(
                            fallback_preflight.get("candidate_generation_preflight") or {}
                        )
                        fallback_structured = dict(
                            fallback_candidate_generation.get("structured_group_completion")
                            or {}
                        )
                        fallback_diag = {
                            **fallback_diag,
                            "preflight_passed": bool(fallback_preflight.get("passed")),
                            "preflight_block_reason": str(
                                fallback_preflight.get("block_reason", "") or ""
                            ),
                            "candidate_sites_before_attempted_filter_count": int(
                                len(fallback_sites)
                            ),
                            "candidate_sites_after_attempted_filter_count": int(
                                len(fallback_fresh_sites)
                            ),
                            "attempted_site_alternatives_enabled": bool(
                                fallback_attempted_alternatives_enabled
                            ),
                            "attempted_candidate_site_count": int(
                                len(fallback_attempted_sites)
                            ),
                            "structured_attempted_site_candidate_count": int(
                                fallback_structured.get("attempted_site_candidate_count", 0)
                                or 0
                            ),
                            "structured_alternative_selected": bool(
                                fallback_structured.get(
                                    "terminal_attempted_site_alternative_selected"
                                )
                            ),
                            "execution_order_alternatives_enabled": bool(
                                fallback_execution_order_alternatives_enabled
                            ),
                            "structured_execution_order_alternative_selected": bool(
                                fallback_structured.get(
                                    "terminal_execution_order_alternative_selected"
                                )
                            ),
                            "structured_selected_group": dict(
                                fallback_structured.get("selected_group") or {}
                            ),
                        }
                        if bool(fallback_preflight.get("passed")) and fallback_fresh_sites:
                            fallback_diag["applied"] = True
                            packet = fallback_packet
                            preflight_diag = {
                                **fallback_preflight,
                                "min_candidate_sites": int(min_preflight_candidate_sites),
                                "min_candidate_sites_relax_after_blocks": int(
                                    min_candidate_relax_after_blocks
                                ),
                                "min_candidate_site_block_count": int(
                                    self._coordinate_hypothesis_min_candidate_site_block_count
                                ),
                                "attempted_site_suppression_enabled": True,
                                "attempted_site_count": int(
                                    len(self._coordinate_hypothesis_attempted_sites)
                                ),
                                "candidate_sites_after_attempted_filter_count": int(
                                    len(fallback_fresh_sites)
                                ),
                                "terminal_structured_preflight_fallback": fallback_diag,
                            }
                            empty_diag["preflight"] = preflight_diag
                            preflight_sites = fallback_sites
                            fresh_preflight_sites = fallback_fresh_sites
                        else:
                            fallback_diag["block_reason"] = (
                                "fallback_no_fresh_candidate_site"
                            )
                    if bool(fallback_diag.get("applied")):
                        pass
                    else:
                        preflight_diag["terminal_structured_preflight_fallback"] = fallback_diag
                        empty_diag["preflight"] = {
                            **preflight_diag,
                            "passed": False,
                            "block_reason": "all_coordinate_preflight_sites_attempted",
                        }
                        empty_diag["call_gate"] = {
                            **call_gate,
                            "allowed": False,
                            "block_reason": "all_coordinate_preflight_sites_attempted",
                            "provider_call_count_after": int(self._coordinate_hypothesis_provider_call_count),
                        }
                        return None, empty_diag
            candidate_site_count_for_support = int(
                preflight_diag.get("candidate_sites_after_attempted_filter_count")
                if "candidate_sites_after_attempted_filter_count" in preflight_diag
                else preflight_diag.get("candidate_sites_generated_from_preflight_count", 0)
                or 0
            )
            preflight_diag["candidate_site_count_for_min_support"] = int(
                candidate_site_count_for_support
            )
            min_candidate_relaxed = bool(
                min_candidate_relax_after_blocks > 0
                and self._coordinate_hypothesis_min_candidate_site_block_count
                >= min_candidate_relax_after_blocks
            )
            preflight_diag["min_candidate_sites_relaxed"] = bool(min_candidate_relaxed)
            if (
                min_preflight_candidate_sites > 0
                and candidate_site_count_for_support < min_preflight_candidate_sites
                and not min_candidate_relaxed
            ):
                self._coordinate_hypothesis_min_candidate_site_block_count += 1
                empty_diag["preflight"] = {
                    **preflight_diag,
                    "passed": False,
                    "block_reason": "insufficient_coordinate_preflight_candidate_sites",
                    "min_candidate_site_block_count_after": int(
                        self._coordinate_hypothesis_min_candidate_site_block_count
                    ),
                }
                empty_diag["call_gate"] = {
                    **call_gate,
                    "allowed": False,
                    "block_reason": "insufficient_coordinate_preflight_candidate_sites",
                    "provider_call_count_after": int(self._coordinate_hypothesis_provider_call_count),
                }
                return None, empty_diag
        result = self.coordinate_hypothesis_bridge.build(
            enabled=True,
            packet=packet,
            current_state_hash=current_hash,
            max_hypotheses=1,
        )
        diagnostics = dict(result.diagnostics)
        diagnostics["remembered_target_count"] = int(
            len(self._coordinate_hypothesis_r11l_target_memory)
        )
        diagnostics["coordinate_group_focus"] = dict(empty_diag.get("coordinate_group_focus") or {})
        diagnostics["provider_immediate_flood_guard"] = dict(
            empty_diag.get("provider_immediate_flood_guard") or {}
        )
        if bool(diagnostics.get("provider_called")):
            self._coordinate_hypothesis_provider_call_count += 1
        verification = result.verification
        candidate_sites_before_attempted_filter = list(
            getattr(verification, "candidate_sites", ()) if verification else ()
        )
        if suppress_attempted_sites:
            candidate_sites = [
                site
                for site in candidate_sites_before_attempted_filter
                if (int(site[0]), int(site[1])) not in self._coordinate_hypothesis_attempted_sites
            ]
        else:
            candidate_sites = list(candidate_sites_before_attempted_filter)
        selected_site = candidate_sites[0] if candidate_sites else None
        diagnostics["call_gate"] = {
            **call_gate,
            "provider_call_count_after": int(self._coordinate_hypothesis_provider_call_count),
        }
        diagnostics["preflight"] = preflight_diag
        diagnostics["enabled"] = True
        diagnostics["choice_generated"] = bool(selected_site is not None)
        diagnostics["selected_site"] = [int(selected_site[0]), int(selected_site[1])] if selected_site else []
        diagnostics["attempted_site_suppression_enabled"] = bool(suppress_attempted_sites)
        diagnostics["attempted_site_count_before_choice"] = int(len(self._coordinate_hypothesis_attempted_sites))
        diagnostics["candidate_sites_before_attempted_filter_count"] = int(
            len(candidate_sites_before_attempted_filter)
        )
        diagnostics["candidate_sites_suppressed_attempted_count"] = int(
            len(candidate_sites_before_attempted_filter) - len(candidate_sites)
        )
        diagnostics["candidate_sites_generated_from_hypothesis_count"] = int(len(candidate_sites))
        diagnostics["candidate_sites_contains_selected_site"] = bool(selected_site in candidate_sites)
        diagnostics["verification"] = verification.to_dict() if verification is not None else None
        if selected_site is None:
            return None, diagnostics
        self._coordinate_hypothesis_attempted_sites.add((int(selected_site[0]), int(selected_site[1])))
        diagnostics["attempted_site_count_after_choice"] = int(len(self._coordinate_hypothesis_attempted_sites))
        protected_plan_sites = self._coordinate_hypothesis_execution_sites_from_verification(verification)
        best_incomplete_fallback_applied = (
            self._coordinate_hypothesis_best_incomplete_fallback_applied_from_verification(
                verification
            )
        )
        coordinate_target_key = self._coordinate_hypothesis_target_key_from_verification(
            verification,
            selected_site=selected_site,
        )
        coordinate_target_keys = self._coordinate_hypothesis_target_keys_from_verification(
            verification,
            selected_site=selected_site,
        )
        selected_site_key = (int(selected_site[0]), int(selected_site[1]))
        if protected_plan_sites and protected_plan_sites[0] == selected_site_key:
            protected_plan_remaining_sites = protected_plan_sites[1:]
        else:
            protected_plan_sites = []
            protected_plan_remaining_sites = []
        diagnostics["protected_plan_site_count"] = int(len(protected_plan_sites))
        diagnostics["protected_plan_remaining_site_count"] = int(len(protected_plan_remaining_sites))
        choice = {
            "primitive_id": "coordinate_hypothesis_choice",
            "step": ("ACTION6", {"x": int(selected_site[0]), "y": int(selected_site[1])}),
            "reason": (
                "coordinate_hypothesis_choice compiled ECA-verified "
                "coordinate relation candidate into protected probe"
            ),
            "selected_site": [int(selected_site[0]), int(selected_site[1])],
            "candidate_count": int(len(candidate_sites)),
            "hypothesis": dict(result.hypothesis or {}),
            "protected_plan_sites": [
                [int(site[0]), int(site[1])] for site in protected_plan_sites
            ],
            "protected_plan_remaining_sites": [
                [int(site[0]), int(site[1])] for site in protected_plan_remaining_sites
            ],
            "coordinate_target_key": str(coordinate_target_key),
            "coordinate_target_keys": list(coordinate_target_keys),
            "terminal_completion_best_incomplete_fallback_applied": bool(
                best_incomplete_fallback_applied
            ),
        }
        return choice, diagnostics

    def _coordinate_hypothesis_execution_sites_from_verification(
        self,
        verification: Any,
    ) -> list[tuple[int, int]]:
        diagnostics = dict(getattr(verification, "diagnostics", {}) or {})
        structured = dict(diagnostics.get("structured_group_completion") or {})
        selected_group = dict(structured.get("selected_group") or {})
        raw_sites = selected_group.get("execution_sites")
        if not isinstance(raw_sites, (list, tuple)):
            return []
        out: list[tuple[int, int]] = []
        for raw_site in raw_sites:
            if not isinstance(raw_site, (list, tuple)) or len(raw_site) < 2:
                continue
            try:
                out.append((int(raw_site[0]), int(raw_site[1])))
            except (TypeError, ValueError):
                continue
        return out

    def _coordinate_hypothesis_self_overlap_detour_metadata_from_verification(
        self,
        verification: Any,
    ) -> dict[str, Any]:
        diagnostics = dict(getattr(verification, "diagnostics", {}) or {})
        structured = dict(diagnostics.get("structured_group_completion") or {})
        selected_group = dict(structured.get("selected_group") or {})
        execution = dict(selected_group.get("execution_diagnostics") or {})
        count = int(execution.get("self_overlap_detour_count", 0) or 0)
        detour = execution.get("self_overlap_detour")
        detour_payload = dict(detour) if isinstance(detour, Mapping) else {}
        return {
            "enabled": bool(execution.get("self_overlap_detour_enabled")),
            "used": bool(count > 0),
            "count": int(count),
            "detour": detour_payload,
            "failed_reason": str(execution.get("failed_reason", "") or ""),
        }

    def _coordinate_hypothesis_site_metadata_from_verification(
        self,
        verification: Any,
        selected_site: Any,
    ) -> dict[str, Any]:
        if not isinstance(selected_site, (list, tuple)) or len(selected_site) < 2:
            return {}
        try:
            selected = (int(selected_site[0]), int(selected_site[1]))
        except (TypeError, ValueError):
            return {}
        diagnostics = dict(getattr(verification, "diagnostics", {}) or {})
        for raw_row in list(diagnostics.get("immediate_candidate_site_metadata") or []):
            if not isinstance(raw_row, Mapping):
                continue
            raw_site = raw_row.get("site")
            if not isinstance(raw_site, (list, tuple)) or len(raw_site) < 2:
                continue
            try:
                site = (int(raw_site[0]), int(raw_site[1]))
            except (TypeError, ValueError):
                continue
            if site == selected:
                return dict(raw_row)
        return {}

    def _coordinate_hypothesis_target_key_from_verification(
        self,
        verification: Any,
        *,
        selected_site: Any = None,
        allow_immediate_metadata: bool = False,
    ) -> str:
        diagnostics = dict(getattr(verification, "diagnostics", {}) or {})
        structured = dict(diagnostics.get("structured_group_completion") or {})
        selected_group = dict(structured.get("selected_group") or {})
        target_key = str(selected_group.get("target_focus_key", "") or "")
        if target_key:
            return target_key
        if not allow_immediate_metadata:
            return ""
        site_metadata = self._coordinate_hypothesis_site_metadata_from_verification(
            verification,
            selected_site,
        )
        return str(site_metadata.get("target_focus_key", "") or "")

    def _coordinate_hypothesis_target_keys_from_verification(
        self,
        verification: Any,
        *,
        selected_site: Any = None,
        allow_immediate_metadata: bool = False,
    ) -> list[str]:
        diagnostics = dict(getattr(verification, "diagnostics", {}) or {})
        structured = dict(diagnostics.get("structured_group_completion") or {})
        selected_group = dict(structured.get("selected_group") or {})
        raw_keys = list(selected_group.get("joint_assignment_target_keys") or [])
        if not raw_keys:
            raw_keys = [selected_group.get("target_focus_key", "")]
        if allow_immediate_metadata and not any(str(raw_key or "") for raw_key in raw_keys):
            site_metadata = self._coordinate_hypothesis_site_metadata_from_verification(
                verification,
                selected_site,
            )
            raw_keys = [site_metadata.get("target_focus_key", "")]
        keys: list[str] = []
        for raw_key in raw_keys:
            key = str(raw_key or "")
            if key and key not in keys:
                keys.append(key)
        return keys

    def _coordinate_hypothesis_single_piece_target_family_probe_route_key(
        self,
        *,
        target_key: str,
        route_sites: Sequence[Sequence[int] | tuple[int, int]],
    ) -> str:
        site_key = ";".join(f"{int(site[0])},{int(site[1])}" for site in route_sites)
        return f"{target_key}|{site_key}"

    def _coordinate_hypothesis_single_piece_target_family_probe_completed_no_score(
        self,
        *,
        route_key: str,
    ) -> bool:
        for row in self._coordinate_hypothesis_single_piece_target_family_probe_outcomes:
            if str(row.get("route_key", "") or "") != str(route_key):
                continue
            if bool(row.get("plan_completed")) and int(row.get("score_delta", 0) or 0) <= 0:
                return True
        return False

    def _coordinate_hypothesis_single_piece_target_family_probe_churn_ready(
        self,
        *,
        target_key: str,
    ) -> bool:
        for row in reversed(self._coordinate_hypothesis_satisfied_target_churn_events):
            if str(row.get("source", "") or "") != "target_commitment_choice":
                continue
            remaining_keys = [
                str(key or "")
                for key in list(row.get("remaining_unsatisfied_target_keys") or [])
                if str(key or "")
            ]
            if any(_coordinate_target_keys_match(target_key, key) for key in remaining_keys):
                return True
        return False

    def _coordinate_hypothesis_single_piece_target_family_outcome_probe_candidate(
        self,
        verification: Any,
        *,
        preferred_target_keys: Sequence[str],
    ) -> tuple[dict[str, Any] | None, dict[str, Any]]:
        enabled = bool(
            self._coordinate_hypothesis_single_piece_target_family_outcome_probe_enabled()
        )
        max_attempts = (
            self._coordinate_hypothesis_single_piece_target_family_outcome_probe_max_attempts()
        )
        diag: dict[str, Any] = {
            "enabled": bool(enabled),
            "max_attempts": int(max_attempts),
            "attempt_count": int(
                self._coordinate_hypothesis_single_piece_target_family_probe_choice_count
            ),
            "applied": False,
            "block_reason": "",
            "row_count": 0,
            "route_candidate_count": 0,
            "prior_no_score_block_count": 0,
            "attempted_first_site_block_count": 0,
            "churn_guard_block_count": 0,
            "score_bearing_projection_block_count": 0,
            "selected_target_key": "",
            "selected_route_sites": [],
            "route_key": "",
        }
        if not enabled:
            diag["block_reason"] = "single_piece_target_family_outcome_probe_disabled"
            return None, diag
        if max_attempts <= 0:
            diag["block_reason"] = "single_piece_target_family_outcome_probe_max_attempts_zero"
            return None, diag
        if int(self._coordinate_hypothesis_score_success_count) <= 0:
            diag["block_reason"] = (
                "single_piece_target_family_outcome_probe_requires_prior_score_success"
            )
            return None, diag
        if self._coordinate_hypothesis_single_piece_target_family_probe_choice_count >= max_attempts:
            diag["block_reason"] = "single_piece_target_family_outcome_probe_max_attempts"
            return None, diag
        diagnostics = dict(getattr(verification, "diagnostics", {}) or {})
        if not diagnostics and hasattr(verification, "to_dict"):
            try:
                verification_payload = verification.to_dict()
            except Exception:
                verification_payload = {}
            if isinstance(verification_payload, Mapping):
                diagnostics = dict(verification_payload.get("diagnostics") or {})
        structured = dict(diagnostics.get("structured_group_completion") or {})
        sensor = dict(structured.get("single_piece_target_family_sensor") or {})
        rows = [row for row in list(sensor.get("rows") or []) if isinstance(row, Mapping)]
        diag["row_count"] = int(len(rows))
        if not rows:
            diag["block_reason"] = "single_piece_target_family_outcome_probe_no_sensor_rows"
            return None, diag

        preferred = [str(key or "") for key in preferred_target_keys if str(key or "")]
        candidates: list[tuple[tuple[int, int, int, int], dict[str, Any]]] = []
        for index, row in enumerate(rows):
            if not bool(row.get("route_candidate")):
                continue
            raw_sites = row.get("execution_sites")
            if not isinstance(raw_sites, (list, tuple)):
                continue
            route_sites: list[tuple[int, int]] = []
            for raw_site in raw_sites:
                if not isinstance(raw_site, (list, tuple)) or len(raw_site) < 2:
                    continue
                try:
                    route_sites.append((int(raw_site[0]), int(raw_site[1])))
                except (TypeError, ValueError):
                    continue
            if not route_sites:
                continue
            target_key = str(row.get("target_focus_key", "") or "")
            if not target_key:
                continue
            if not self._coordinate_hypothesis_single_piece_target_family_probe_churn_ready(
                target_key=target_key,
            ):
                diag["churn_guard_block_count"] = int(
                    diag["churn_guard_block_count"]
                ) + 1
                continue
            if row.get("score_bearing_projection_candidate") is False:
                diag["score_bearing_projection_block_count"] = int(
                    diag["score_bearing_projection_block_count"]
                ) + 1
                continue
            route_key = self._coordinate_hypothesis_single_piece_target_family_probe_route_key(
                target_key=target_key,
                route_sites=route_sites,
            )
            if self._coordinate_hypothesis_single_piece_target_family_probe_completed_no_score(
                route_key=route_key,
            ):
                diag["prior_no_score_block_count"] = int(
                    diag["prior_no_score_block_count"]
                ) + 1
                continue
            if route_sites[0] in self._coordinate_hypothesis_attempted_sites:
                diag["attempted_first_site_block_count"] = int(
                    diag["attempted_first_site_block_count"]
                ) + 1
                continue
            preferred_rank = 0
            if preferred:
                preferred_rank = (
                    0
                    if any(_coordinate_target_keys_match(target_key, key) for key in preferred)
                    else 1
                )
            current_overlap = int(row.get("current_canvas_target_overlap", 0) or 0)
            candidates.append(
                (
                    (
                        int(preferred_rank),
                        int(current_overlap),
                        int(len(route_sites)),
                        int(index),
                    ),
                    {
                        "target_key": target_key,
                        "route_key": route_key,
                        "route_sites": route_sites,
                        "row": dict(row),
                    },
                )
            )
        diag["route_candidate_count"] = int(len(candidates))
        if not candidates:
            diag["block_reason"] = "single_piece_target_family_outcome_probe_no_eligible_route"
            return None, diag
        candidates.sort(key=lambda item: item[0])
        selected = candidates[0][1]
        route_sites = list(selected["route_sites"])
        diag["applied"] = True
        diag["block_reason"] = ""
        diag["selected_target_key"] = str(selected["target_key"])
        diag["selected_route_sites"] = [
            [int(site[0]), int(site[1])] for site in route_sites
        ]
        diag["route_key"] = str(selected["route_key"])
        return {
            "target_key": str(selected["target_key"]),
            "target_keys": [str(selected["target_key"])],
            "route_key": str(selected["route_key"]),
            "route_sites": route_sites,
            "selected_row": dict(selected["row"]),
            "candidate_count": int(len(candidates)),
        }, diag

    def _coordinate_hypothesis_active_family_retarget_reclick_site(
        self,
        verification: Any,
        *,
        candidate_sites_before_filter: Sequence[Any],
    ) -> tuple[tuple[int, int] | None, dict[str, Any]]:
        enabled = bool(self._coordinate_hypothesis_active_family_retarget_reclick_enabled())
        diagnostics: dict[str, Any] = {
            "enabled": bool(enabled),
            "applied": False,
            "block_reason": "",
            "candidate_sites_before_filter_count": int(len(candidate_sites_before_filter)),
            "attempted_site_count": int(len(self._coordinate_hypothesis_attempted_sites)),
            "selected_site": [],
            "target_key": "",
            "active_piece_in_group": None,
            "execution_site_count": None,
            "failed_reason": "",
        }
        if not enabled:
            diagnostics["block_reason"] = "active_family_retarget_reclick_disabled"
            return None, diagnostics
        if not candidate_sites_before_filter:
            diagnostics["block_reason"] = "no_candidate_before_filter"
            return None, diagnostics
        verification_diag = dict(getattr(verification, "diagnostics", {}) or {})
        structured = dict(verification_diag.get("structured_group_completion") or {})
        selected_group = dict(structured.get("selected_group") or {})
        if not selected_group:
            diagnostics["block_reason"] = "missing_selected_group"
            return None, diagnostics
        diagnostics["target_key"] = str(selected_group.get("target_focus_key", "") or "")
        diagnostics["active_piece_in_group"] = bool(
            selected_group.get("active_piece_in_group")
        )
        diagnostics["execution_site_count"] = int(
            selected_group.get("execution_site_count", 0) or 0
        )
        execution_diag = dict(selected_group.get("execution_diagnostics") or {})
        diagnostics["failed_reason"] = str(execution_diag.get("failed_reason", "") or "")
        if bool(selected_group.get("active_piece_in_group")):
            diagnostics["block_reason"] = "active_piece_already_in_group"
            return None, diagnostics
        if int(selected_group.get("execution_site_count", 0) or 0) > 0:
            diagnostics["block_reason"] = "selected_group_has_execution_plan"
            return None, diagnostics
        raw_site = selected_group.get("first_action_site")
        if not isinstance(raw_site, (list, tuple)) or len(raw_site) < 2:
            diagnostics["block_reason"] = "missing_first_action_site"
            return None, diagnostics
        try:
            site = (int(raw_site[0]), int(raw_site[1]))
        except (TypeError, ValueError):
            diagnostics["block_reason"] = "invalid_first_action_site"
            return None, diagnostics
        before_sites: list[tuple[int, int]] = []
        for raw_candidate in candidate_sites_before_filter:
            if not isinstance(raw_candidate, (list, tuple)) or len(raw_candidate) < 2:
                continue
            try:
                before_sites.append((int(raw_candidate[0]), int(raw_candidate[1])))
            except (TypeError, ValueError):
                continue
        if site not in before_sites:
            diagnostics["block_reason"] = "first_action_site_not_candidate"
            return None, diagnostics
        if site not in self._coordinate_hypothesis_attempted_sites:
            diagnostics["block_reason"] = "first_action_site_not_attempted"
            return None, diagnostics
        diagnostics["applied"] = True
        diagnostics["selected_site"] = [int(site[0]), int(site[1])]
        return site, diagnostics

    def _coordinate_hypothesis_requested_target_overlap_rank(
        self,
        verification: Any,
        candidate_sites: Sequence[Any],
        *,
        preferred_target_keys: Sequence[str] | None = None,
    ) -> tuple[list[Any], dict[str, Any]]:
        enabled = bool(self._coordinate_hypothesis_requested_target_overlap_rank_enabled())
        preferred = [
            str(key or "")
            for key in list(preferred_target_keys or [])
            if str(key or "")
        ]
        sites = list(candidate_sites)
        diagnostics: dict[str, Any] = {
            "enabled": bool(enabled),
            "applied": False,
            "candidate_count": int(len(sites)),
            "metadata_count": 0,
            "preferred_target_keys": list(preferred),
            "matched_candidate_count": 0,
            "selected_site_before_rank": [
                int(sites[0][0]),
                int(sites[0][1]),
            ] if sites and isinstance(sites[0], (list, tuple)) and len(sites[0]) >= 2 else [],
            "selected_site_after_rank": [],
            "selected_site_changed": False,
            "top_ranked_site_metadata": {},
        }
        if not enabled or len(sites) <= 1:
            diagnostics["selected_site_after_rank"] = list(
                diagnostics["selected_site_before_rank"]
            )
            return sites, diagnostics
        if not preferred:
            diagnostics["block_reason"] = "no_preferred_target_keys"
            diagnostics["selected_site_after_rank"] = list(
                diagnostics["selected_site_before_rank"]
            )
            return sites, diagnostics

        metadata_by_site: dict[tuple[int, int], dict[str, Any]] = {}
        diagnostics_map = dict(getattr(verification, "diagnostics", {}) or {})
        for raw_row in list(diagnostics_map.get("immediate_candidate_site_metadata") or []):
            if not isinstance(raw_row, Mapping):
                continue
            raw_site = raw_row.get("site")
            if not isinstance(raw_site, (list, tuple)) or len(raw_site) < 2:
                continue
            try:
                site_key = (int(raw_site[0]), int(raw_site[1]))
            except (TypeError, ValueError):
                continue
            metadata_by_site[site_key] = dict(raw_row)
        diagnostics["metadata_count"] = int(len(metadata_by_site))
        if not metadata_by_site:
            diagnostics["selected_site_after_rank"] = list(
                diagnostics["selected_site_before_rank"]
            )
            return sites, diagnostics

        def metadata_for_site(site: Any) -> dict[str, Any]:
            if not isinstance(site, (list, tuple)) or len(site) < 2:
                return {}
            try:
                site_key = (int(site[0]), int(site[1]))
            except (TypeError, ValueError):
                return {}
            return dict(metadata_by_site.get(site_key) or {})

        def target_rank(target_key: str) -> int:
            if not preferred:
                return 0
            for index, preferred_key in enumerate(preferred):
                if _coordinate_target_keys_match(target_key, preferred_key):
                    return int(index)
            return 10**6

        def int_meta(row: Mapping[str, Any], key: str, default: int = 0) -> int:
            try:
                return int(row.get(key, default) or default)
            except (TypeError, ValueError):
                return int(default)

        ranked_sites = sorted(
            enumerate(sites),
            key=lambda item: (
                target_rank(str(metadata_for_site(item[1]).get("target_focus_key", "") or "")),
                -int_meta(metadata_for_site(item[1]), "overlap_area"),
                int_meta(metadata_for_site(item[1]), "target_color_missing_count"),
                -int_meta(metadata_for_site(item[1]), "target_color_coverage_count"),
                int_meta(metadata_for_site(item[1]), "distance", 10**9),
                int(item[0]),
            ),
        )
        ordered = [site for _index, site in ranked_sites]
        matched_count = 0
        if preferred:
            for site in ordered:
                key = str(metadata_for_site(site).get("target_focus_key", "") or "")
                if key and _coordinate_target_key_matches_any(key, preferred):
                    matched_count += 1
        diagnostics["matched_candidate_count"] = int(matched_count)
        diagnostics["applied"] = bool(ordered != sites)
        if ordered and isinstance(ordered[0], (list, tuple)) and len(ordered[0]) >= 2:
            diagnostics["selected_site_after_rank"] = [
                int(ordered[0][0]),
                int(ordered[0][1]),
            ]
            diagnostics["top_ranked_site_metadata"] = metadata_for_site(ordered[0])
        diagnostics["selected_site_changed"] = bool(
            diagnostics["selected_site_before_rank"]
            and diagnostics["selected_site_after_rank"]
            and diagnostics["selected_site_before_rank"]
            != diagnostics["selected_site_after_rank"]
        )
        return ordered, diagnostics

    def _coordinate_hypothesis_requested_target_score_precondition_rank(
        self,
        verification: Any,
        candidate_sites: Sequence[Any],
        *,
        preferred_target_keys: Sequence[str] | None = None,
    ) -> tuple[list[Any], dict[str, Any]]:
        enabled = bool(
            self._coordinate_hypothesis_requested_target_score_precondition_rank_enabled()
        )
        preferred = [
            str(key or "")
            for key in list(preferred_target_keys or [])
            if str(key or "")
        ]
        sites = list(candidate_sites)
        diagnostics: dict[str, Any] = {
            "enabled": bool(enabled),
            "applied": False,
            "candidate_count": int(len(sites)),
            "metadata_count": 0,
            "preferred_target_keys": list(preferred),
            "matched_candidate_count": 0,
            "positive_precondition_candidate_count": 0,
            "pair_regression_candidate_count": 0,
            "selected_site_before_rank": [
                int(sites[0][0]),
                int(sites[0][1]),
            ] if sites and isinstance(sites[0], (list, tuple)) and len(sites[0]) >= 2 else [],
            "selected_site_after_rank": [],
            "selected_site_changed": False,
            "top_ranked_site_metadata": {},
        }
        if not enabled or len(sites) <= 1:
            diagnostics["selected_site_after_rank"] = list(
                diagnostics["selected_site_before_rank"]
            )
            return sites, diagnostics
        if not preferred:
            diagnostics["block_reason"] = "no_preferred_target_keys"
            diagnostics["selected_site_after_rank"] = list(
                diagnostics["selected_site_before_rank"]
            )
            return sites, diagnostics

        metadata_by_site: dict[tuple[int, int], dict[str, Any]] = {}
        diagnostics_map = dict(getattr(verification, "diagnostics", {}) or {})
        for raw_row in list(diagnostics_map.get("immediate_candidate_site_metadata") or []):
            if not isinstance(raw_row, Mapping):
                continue
            raw_site = raw_row.get("site")
            if not isinstance(raw_site, (list, tuple)) or len(raw_site) < 2:
                continue
            try:
                site_key = (int(raw_site[0]), int(raw_site[1]))
            except (TypeError, ValueError):
                continue
            metadata_by_site[site_key] = dict(raw_row)
        diagnostics["metadata_count"] = int(len(metadata_by_site))
        if not metadata_by_site:
            diagnostics["selected_site_after_rank"] = list(
                diagnostics["selected_site_before_rank"]
            )
            return sites, diagnostics

        def metadata_for_site(site: Any) -> dict[str, Any]:
            if not isinstance(site, (list, tuple)) or len(site) < 2:
                return {}
            try:
                site_key = (int(site[0]), int(site[1]))
            except (TypeError, ValueError):
                return {}
            return dict(metadata_by_site.get(site_key) or {})

        def target_rank(target_key: str) -> int:
            for index, preferred_key in enumerate(preferred):
                if _coordinate_target_keys_match(target_key, preferred_key):
                    return int(index)
            return 10**6

        def int_meta(row: Mapping[str, Any], key: str, default: int = 0) -> int:
            try:
                return int(row.get(key, default) or default)
            except (TypeError, ValueError):
                return int(default)

        def precondition_pass(row: Mapping[str, Any]) -> bool:
            return bool(
                int_meta(row, "predicted_requested_target_satisfied_delta") > 0
                and int_meta(row, "predicted_canvas_satisfied_pair_delta") >= 0
            )

        matched_count = 0
        positive_count = 0
        regression_count = 0
        for site in sites:
            row = metadata_for_site(site)
            target_key = str(row.get("target_focus_key", "") or "")
            if target_key and _coordinate_target_key_matches_any(target_key, preferred):
                matched_count += 1
            if row and precondition_pass(row):
                positive_count += 1
            if row and int_meta(row, "predicted_canvas_satisfied_pair_delta") < 0:
                regression_count += 1
        diagnostics["matched_candidate_count"] = int(matched_count)
        diagnostics["positive_precondition_candidate_count"] = int(positive_count)
        diagnostics["pair_regression_candidate_count"] = int(regression_count)

        ranked_sites = sorted(
            enumerate(sites),
            key=lambda item: (
                target_rank(
                    str(metadata_for_site(item[1]).get("target_focus_key", "") or "")
                ),
                0 if precondition_pass(metadata_for_site(item[1])) else 1,
                -int_meta(
                    metadata_for_site(item[1]),
                    "predicted_requested_target_satisfied_delta",
                ),
                -int_meta(
                    metadata_for_site(item[1]),
                    "predicted_canvas_satisfied_pair_delta",
                ),
                -int_meta(
                    metadata_for_site(item[1]),
                    "predicted_canvas_overlap_area_delta",
                ),
                -int_meta(
                    metadata_for_site(item[1]),
                    "projected_canvas_satisfied_pair_count",
                ),
                int_meta(
                    metadata_for_site(item[1]),
                    "current_canvas_satisfied_pair_count",
                    10**6,
                ),
                -int_meta(metadata_for_site(item[1]), "overlap_area"),
                int_meta(
                    metadata_for_site(item[1]),
                    "target_color_missing_count",
                ),
                -int_meta(
                    metadata_for_site(item[1]),
                    "target_color_coverage_count",
                ),
                int_meta(metadata_for_site(item[1]), "distance", 10**9),
                int(item[0]),
            ),
        )
        ordered = [site for _index, site in ranked_sites]
        diagnostics["applied"] = bool(ordered != sites)
        if ordered and isinstance(ordered[0], (list, tuple)) and len(ordered[0]) >= 2:
            diagnostics["selected_site_after_rank"] = [
                int(ordered[0][0]),
                int(ordered[0][1]),
            ]
            diagnostics["top_ranked_site_metadata"] = metadata_for_site(ordered[0])
        diagnostics["selected_site_changed"] = bool(
            diagnostics["selected_site_before_rank"]
            and diagnostics["selected_site_after_rank"]
            and diagnostics["selected_site_before_rank"]
            != diagnostics["selected_site_after_rank"]
        )
        return ordered, diagnostics

    def _coordinate_hypothesis_post_score1_immediate_positive_delta_guard(
        self,
        verification: Any,
        candidate_sites: Sequence[Any],
        *,
        preferred_target_keys: Sequence[str] | None = None,
        source: str = "",
    ) -> tuple[list[Any], dict[str, Any]]:
        enabled = bool(
            self._coordinate_hypothesis_post_score1_immediate_positive_delta_guard_enabled()
        )
        sites = list(candidate_sites)
        recent_completed_no_score_target_keys = (
            self._coordinate_hypothesis_post_score1_stale_target_keys()
        )
        recent_no_progress_target_keys = self._coordinate_hypothesis_recent_no_progress_target_keys()
        preferred = [
            str(key or "")
            for key in list(preferred_target_keys or [])
            if str(key or "")
        ]
        guard_target_keys: list[str] = []
        for key in [
            *preferred,
            *recent_no_progress_target_keys,
            *recent_completed_no_score_target_keys,
        ]:
            key = str(key or "")
            if key and not _coordinate_target_key_matches_any(key, guard_target_keys):
                guard_target_keys.append(key)
        diagnostics: dict[str, Any] = {
            "enabled": bool(enabled),
            "applied": False,
            "source": str(source or ""),
            "candidate_count": int(len(sites)),
            "metadata_count": 0,
            "score_success_count": int(self._coordinate_hypothesis_score_success_count),
            "recent_no_progress_plan_count": int(
                self._coordinate_hypothesis_recent_no_progress_plan_count()
            ),
            "preferred_target_keys": list(preferred),
            "recent_no_progress_target_keys": list(recent_no_progress_target_keys),
            "recent_completed_no_score_target_keys": list(
                recent_completed_no_score_target_keys
            ),
            "guard_target_keys": list(guard_target_keys),
            "eligible": False,
            "matched_candidate_count": 0,
            "positive_delta_candidate_count": 0,
            "filtered_no_delta_candidate_count": 0,
            "candidate_count_after_filter": int(len(sites)),
            "selected_site_before_filter": [
                int(sites[0][0]),
                int(sites[0][1]),
            ] if sites and isinstance(sites[0], (list, tuple)) and len(sites[0]) >= 2 else [],
            "selected_site_after_filter": [],
            "selected_site_changed": False,
            "top_candidate_metadata": {},
        }
        if not enabled:
            diagnostics["selected_site_after_filter"] = list(
                diagnostics["selected_site_before_filter"]
            )
            return sites, diagnostics
        if not sites:
            return sites, diagnostics
        if int(self._coordinate_hypothesis_score_success_count) <= 0:
            diagnostics["block_reason"] = "pre_score1"
            diagnostics["selected_site_after_filter"] = list(
                diagnostics["selected_site_before_filter"]
            )
            return sites, diagnostics
        if not recent_no_progress_target_keys and not recent_completed_no_score_target_keys:
            diagnostics["block_reason"] = "no_recent_completed_no_score_target"
            diagnostics["selected_site_after_filter"] = list(
                diagnostics["selected_site_before_filter"]
            )
            return sites, diagnostics
        if not guard_target_keys:
            diagnostics["block_reason"] = "no_guard_target_keys"
            diagnostics["selected_site_after_filter"] = list(
                diagnostics["selected_site_before_filter"]
            )
            return sites, diagnostics

        metadata_by_site: dict[tuple[int, int], dict[str, Any]] = {}
        diagnostics_map = dict(getattr(verification, "diagnostics", {}) or {})
        for raw_row in list(diagnostics_map.get("immediate_candidate_site_metadata") or []):
            if not isinstance(raw_row, Mapping):
                continue
            raw_site = raw_row.get("site")
            if not isinstance(raw_site, (list, tuple)) or len(raw_site) < 2:
                continue
            try:
                site_key = (int(raw_site[0]), int(raw_site[1]))
            except (TypeError, ValueError):
                continue
            metadata_by_site[site_key] = dict(raw_row)
        diagnostics["metadata_count"] = int(len(metadata_by_site))
        if not metadata_by_site:
            diagnostics["block_reason"] = "no_immediate_candidate_metadata"
            diagnostics["selected_site_after_filter"] = list(
                diagnostics["selected_site_before_filter"]
            )
            return sites, diagnostics

        def metadata_for_site(site: Any) -> dict[str, Any]:
            if not isinstance(site, (list, tuple)) or len(site) < 2:
                return {}
            try:
                site_key = (int(site[0]), int(site[1]))
            except (TypeError, ValueError):
                return {}
            return dict(metadata_by_site.get(site_key) or {})

        def int_meta(row: Mapping[str, Any], key: str, default: int = 0) -> int:
            try:
                return int(row.get(key, default) or default)
            except (TypeError, ValueError):
                return int(default)

        def target_matches(row: Mapping[str, Any]) -> bool:
            target_key = str(row.get("target_focus_key", "") or "")
            return bool(
                target_key
                and _coordinate_target_key_matches_any(target_key, guard_target_keys)
            )

        def positive_delta(row: Mapping[str, Any]) -> bool:
            return bool(
                int_meta(row, "predicted_requested_target_satisfied_delta") > 0
                or int_meta(row, "predicted_canvas_satisfied_pair_delta") > 0
            )

        kept: list[Any] = []
        matched_count = 0
        positive_count = 0
        filtered_count = 0
        for site in sites:
            row = metadata_for_site(site)
            if not row or not target_matches(row):
                kept.append(site)
                continue
            matched_count += 1
            if positive_delta(row):
                positive_count += 1
                kept.append(site)
            else:
                filtered_count += 1
        diagnostics["eligible"] = bool(matched_count > 0)
        diagnostics["matched_candidate_count"] = int(matched_count)
        diagnostics["positive_delta_candidate_count"] = int(positive_count)
        diagnostics["filtered_no_delta_candidate_count"] = int(filtered_count)
        diagnostics["candidate_count_after_filter"] = int(len(kept))
        diagnostics["applied"] = bool(filtered_count > 0)
        if kept and isinstance(kept[0], (list, tuple)) and len(kept[0]) >= 2:
            diagnostics["selected_site_after_filter"] = [
                int(kept[0][0]),
                int(kept[0][1]),
            ]
            diagnostics["top_candidate_metadata"] = metadata_for_site(kept[0])
        else:
            diagnostics["block_reason"] = "all_matched_immediate_candidates_no_positive_delta"
        diagnostics["selected_site_changed"] = bool(
            diagnostics["selected_site_before_filter"]
            and diagnostics["selected_site_after_filter"]
            and diagnostics["selected_site_before_filter"]
            != diagnostics["selected_site_after_filter"]
        )
        return kept, diagnostics

    def _coordinate_hypothesis_target_commitment_immediate_target_match_guard(
        self,
        verification: Any,
        candidate_sites: Sequence[Any],
        *,
        target_key: str,
        progress_kind: str,
    ) -> tuple[list[Any], dict[str, Any]]:
        enabled = bool(
            self._coordinate_hypothesis_target_commitment_immediate_target_match_guard_enabled()
        )
        sites = list(candidate_sites)
        target_key = str(target_key or "")
        diagnostics: dict[str, Any] = {
            "enabled": bool(enabled),
            "eligible": False,
            "applied": False,
            "target_key": target_key,
            "progress_kind": str(progress_kind or ""),
            "candidate_count": int(len(sites)),
            "metadata_count": 0,
            "matched_candidate_count": 0,
            "unmatched_immediate_candidate_count": 0,
            "metadata_missing_candidate_count": 0,
            "candidate_count_after_filter": int(len(sites)),
            "selected_site_before_filter": [
                int(sites[0][0]),
                int(sites[0][1]),
            ] if sites and isinstance(sites[0], (list, tuple)) and len(sites[0]) >= 2 else [],
            "selected_site_after_filter": [],
            "selected_site_changed": False,
            "top_candidate_metadata": {},
        }
        if not enabled:
            diagnostics["selected_site_after_filter"] = list(
                diagnostics["selected_site_before_filter"]
            )
            diagnostics["block_reason"] = "target_match_guard_disabled"
            return sites, diagnostics
        if not sites:
            diagnostics["block_reason"] = "no_candidate_sites"
            return sites, diagnostics
        if not target_key:
            diagnostics["selected_site_after_filter"] = list(
                diagnostics["selected_site_before_filter"]
            )
            diagnostics["block_reason"] = "no_target_key"
            return sites, diagnostics
        if str(progress_kind or "") != "satisfied_target_handoff":
            diagnostics["selected_site_after_filter"] = list(
                diagnostics["selected_site_before_filter"]
            )
            diagnostics["block_reason"] = "not_satisfied_target_handoff"
            return sites, diagnostics

        metadata_by_site: dict[tuple[int, int], dict[str, Any]] = {}
        diagnostics_map = dict(getattr(verification, "diagnostics", {}) or {})
        for raw_row in list(diagnostics_map.get("immediate_candidate_site_metadata") or []):
            if not isinstance(raw_row, Mapping):
                continue
            raw_site = raw_row.get("site")
            if not isinstance(raw_site, (list, tuple)) or len(raw_site) < 2:
                continue
            try:
                site_key = (int(raw_site[0]), int(raw_site[1]))
            except (TypeError, ValueError):
                continue
            metadata_by_site[site_key] = dict(raw_row)
        diagnostics["metadata_count"] = int(len(metadata_by_site))
        if not metadata_by_site:
            diagnostics["selected_site_after_filter"] = list(
                diagnostics["selected_site_before_filter"]
            )
            diagnostics["block_reason"] = "no_immediate_candidate_metadata"
            return sites, diagnostics

        def metadata_for_site(site: Any) -> dict[str, Any]:
            if not isinstance(site, (list, tuple)) or len(site) < 2:
                return {}
            try:
                site_key = (int(site[0]), int(site[1]))
            except (TypeError, ValueError):
                return {}
            return dict(metadata_by_site.get(site_key) or {})

        kept: list[Any] = []
        matched_count = 0
        unmatched_count = 0
        missing_count = 0
        for site in sites:
            row = metadata_for_site(site)
            if not row:
                missing_count += 1
                kept.append(site)
                continue
            focus_key = str(row.get("target_focus_key", "") or "")
            if focus_key and _coordinate_target_keys_match(focus_key, target_key):
                matched_count += 1
                kept.append(site)
            else:
                unmatched_count += 1
        diagnostics["eligible"] = bool(matched_count > 0 or unmatched_count > 0)
        diagnostics["matched_candidate_count"] = int(matched_count)
        diagnostics["unmatched_immediate_candidate_count"] = int(unmatched_count)
        diagnostics["metadata_missing_candidate_count"] = int(missing_count)
        diagnostics["candidate_count_after_filter"] = int(len(kept))
        diagnostics["applied"] = bool(unmatched_count > 0)
        if kept and isinstance(kept[0], (list, tuple)) and len(kept[0]) >= 2:
            diagnostics["selected_site_after_filter"] = [int(kept[0][0]), int(kept[0][1])]
            diagnostics["top_candidate_metadata"] = metadata_for_site(kept[0])
        else:
            diagnostics["block_reason"] = "all_immediate_candidates_wrong_target"
        diagnostics["selected_site_changed"] = bool(
            diagnostics["selected_site_before_filter"]
            and diagnostics["selected_site_after_filter"]
            and diagnostics["selected_site_before_filter"]
            != diagnostics["selected_site_after_filter"]
        )
        return kept, diagnostics

    def _coordinate_hypothesis_target_commitment_score_bearing_handoff_defer(
        self,
        verification: Any,
        candidate_sites: Sequence[Any],
        *,
        target_key: str,
        progress_kind: str,
        attempt_count: int,
    ) -> tuple[bool, dict[str, Any]]:
        enabled = bool(
            self._coordinate_hypothesis_target_commitment_score_bearing_handoff_defer_enabled()
        )
        min_attempts = (
            self._coordinate_hypothesis_target_commitment_score_bearing_handoff_defer_min_attempts()
        )
        sites = list(candidate_sites)
        target_key = str(target_key or "")
        diagnostics: dict[str, Any] = {
            "enabled": bool(enabled),
            "eligible": False,
            "defer": False,
            "target_key": target_key,
            "progress_kind": str(progress_kind or ""),
            "attempt_count": int(attempt_count),
            "min_attempts": int(min_attempts),
            "candidate_count": int(len(sites)),
            "metadata_count": 0,
            "matched_candidate_count": 0,
            "matched_positive_candidate_count": 0,
            "unmatched_candidate_count": 0,
            "structured_candidate_count": 0,
            "immediate_candidate_count": 0,
            "top_candidate_metadata": {},
            "block_reason": "",
        }
        if not enabled:
            diagnostics["block_reason"] = "score_bearing_handoff_defer_disabled"
            return False, diagnostics
        if int(attempt_count) < int(min_attempts):
            diagnostics["block_reason"] = "below_min_attempts"
            return False, diagnostics
        if str(progress_kind or "") != "satisfied_target_handoff":
            diagnostics["block_reason"] = "not_satisfied_target_handoff"
            return False, diagnostics
        if not target_key:
            diagnostics["block_reason"] = "no_target_key"
            return False, diagnostics
        if not sites:
            diagnostics["block_reason"] = "no_candidate_sites"
            return False, diagnostics

        diagnostics_map = dict(getattr(verification, "diagnostics", {}) or {})
        structured = dict(diagnostics_map.get("structured_group_completion") or {})
        structured_count = int(structured.get("first_action_site_count", 0) or 0)
        diagnostics["structured_candidate_count"] = int(structured_count)
        immediate_count = int(diagnostics_map.get("immediate_candidate_sites_generated_count", 0) or 0)
        diagnostics["immediate_candidate_count"] = int(immediate_count)
        if structured_count > 0:
            diagnostics["block_reason"] = "structured_candidate_available"
            return False, diagnostics

        metadata_by_site: dict[tuple[int, int], dict[str, Any]] = {}
        for raw_row in list(diagnostics_map.get("immediate_candidate_site_metadata") or []):
            if not isinstance(raw_row, Mapping):
                continue
            raw_site = raw_row.get("site")
            if not isinstance(raw_site, (list, tuple)) or len(raw_site) < 2:
                continue
            try:
                site_key = (int(raw_site[0]), int(raw_site[1]))
            except (TypeError, ValueError):
                continue
            metadata_by_site[site_key] = dict(raw_row)
        diagnostics["metadata_count"] = int(len(metadata_by_site))
        if not metadata_by_site:
            diagnostics["block_reason"] = "no_immediate_candidate_metadata"
            return False, diagnostics

        def int_meta(row: Mapping[str, Any], key: str, default: int = 0) -> int:
            try:
                return int(row.get(key, default) or default)
            except (TypeError, ValueError):
                return int(default)

        matched_count = 0
        matched_positive_count = 0
        unmatched_count = 0
        top_metadata: dict[str, Any] = {}
        for index, site in enumerate(sites):
            if not isinstance(site, (list, tuple)) or len(site) < 2:
                continue
            try:
                site_key = (int(site[0]), int(site[1]))
            except (TypeError, ValueError):
                continue
            row = dict(metadata_by_site.get(site_key) or {})
            if index == 0:
                top_metadata = row
            if not row:
                continue
            focus_key = str(row.get("target_focus_key", "") or "")
            if focus_key and _coordinate_target_keys_match(focus_key, target_key):
                matched_count += 1
                if (
                    int_meta(row, "predicted_requested_target_satisfied_delta") > 0
                    or int_meta(row, "predicted_canvas_satisfied_pair_delta") > 0
                ):
                    matched_positive_count += 1
            else:
                unmatched_count += 1
        diagnostics["matched_candidate_count"] = int(matched_count)
        diagnostics["matched_positive_candidate_count"] = int(matched_positive_count)
        diagnostics["unmatched_candidate_count"] = int(unmatched_count)
        diagnostics["top_candidate_metadata"] = top_metadata
        diagnostics["eligible"] = bool(immediate_count > 0 and matched_positive_count == 0)
        if not diagnostics["eligible"]:
            diagnostics["block_reason"] = "score_bearing_handoff_candidate_available"
            return False, diagnostics
        diagnostics["defer"] = True
        diagnostics["block_reason"] = "defer_non_score_bearing_handoff_immediates"
        return True, diagnostics

    def _coordinate_hypothesis_target_commitment_preconditioning_observation(
        self,
        verification: Any,
        selected_site: Any,
        *,
        target_key: str,
        progress_kind: str,
        attempt_count: int,
    ) -> dict[str, Any]:
        enabled = bool(
            self._coordinate_hypothesis_target_commitment_preconditioning_attribution_enabled()
        )
        observation: dict[str, Any] = {
            "enabled": bool(enabled),
            "observed": False,
            "potential_preconditioning": False,
            "target_key": str(target_key or ""),
            "progress_kind": str(progress_kind or ""),
            "attempt_count": int(attempt_count),
            "selected_site": [],
            "metadata": {},
            "block_reason": "",
        }
        if not enabled:
            observation["block_reason"] = "preconditioning_attribution_disabled"
            return observation
        if str(progress_kind or "") != "satisfied_target_handoff":
            observation["block_reason"] = "not_satisfied_target_handoff"
            return observation
        if not isinstance(selected_site, (list, tuple)) or len(selected_site) < 2:
            observation["block_reason"] = "missing_selected_site"
            return observation
        try:
            site_key = (int(selected_site[0]), int(selected_site[1]))
        except (TypeError, ValueError):
            observation["block_reason"] = "invalid_selected_site"
            return observation
        observation["selected_site"] = [int(site_key[0]), int(site_key[1])]
        diagnostics_map = dict(getattr(verification, "diagnostics", {}) or {})
        selected_metadata: dict[str, Any] = {}
        for raw_row in list(diagnostics_map.get("immediate_candidate_site_metadata") or []):
            if not isinstance(raw_row, Mapping):
                continue
            raw_site = raw_row.get("site")
            if not isinstance(raw_site, (list, tuple)) or len(raw_site) < 2:
                continue
            try:
                candidate_site = (int(raw_site[0]), int(raw_site[1]))
            except (TypeError, ValueError):
                continue
            if candidate_site == site_key:
                selected_metadata = dict(raw_row)
                break
        if not selected_metadata:
            observation["block_reason"] = "selected_site_not_immediate_metadata"
            return observation

        def int_meta(key: str, default: int = 0) -> int:
            try:
                return int(selected_metadata.get(key, default) or default)
            except (TypeError, ValueError):
                return int(default)

        focus_key = str(selected_metadata.get("target_focus_key", "") or "")
        target_key = str(target_key or "")
        target_match = bool(focus_key and _coordinate_target_keys_match(focus_key, target_key))
        predicted_requested_delta = int_meta("predicted_requested_target_satisfied_delta")
        predicted_pair_delta = int_meta("predicted_canvas_satisfied_pair_delta")
        observation["observed"] = True
        observation["metadata"] = {
            "source": str(selected_metadata.get("source", "") or ""),
            "target_focus_key": focus_key,
            "predicted_requested_target_satisfied_delta": int(predicted_requested_delta),
            "predicted_canvas_satisfied_pair_delta": int(predicted_pair_delta),
            "predicted_canvas_overlap_area_delta": int_meta(
                "predicted_canvas_overlap_area_delta"
            ),
            "overlap_area": int_meta("overlap_area"),
            "distance": int_meta("distance", 10**9),
        }
        observation["target_match"] = bool(target_match)
        observation["non_score_bearing_immediate"] = bool(
            predicted_requested_delta <= 0 and predicted_pair_delta <= 0
        )
        observation["potential_preconditioning"] = bool(
            not target_match and observation["non_score_bearing_immediate"]
        )
        observation["block_reason"] = (
            ""
            if observation["potential_preconditioning"]
            else "not_wrong_target_non_score_bearing_immediate"
        )
        return observation

    def _coordinate_hypothesis_target_commitment_preconditioning_repeat_defer(
        self,
        observation: Mapping[str, Any],
    ) -> tuple[bool, dict[str, Any]]:
        enabled = bool(
            self._coordinate_hypothesis_target_commitment_preconditioning_repeat_defer_enabled()
        )
        min_pending = (
            self._coordinate_hypothesis_target_commitment_preconditioning_repeat_defer_min_pending()
        )
        metadata = dict(observation.get("metadata") or {})
        target_key = str(observation.get("target_key", "") or "")
        focus_key = str(metadata.get("target_focus_key", "") or "")
        diagnostics: dict[str, Any] = {
            "enabled": bool(enabled),
            "eligible": False,
            "defer": False,
            "min_pending": int(min_pending),
            "target_key": target_key,
            "immediate_target_focus_key": focus_key,
            "prior_pending_count": 0,
            "prior_attributed_count": 0,
            "block_reason": "",
        }
        if not enabled:
            diagnostics["block_reason"] = "preconditioning_repeat_defer_disabled"
            return False, diagnostics
        if not bool(observation.get("potential_preconditioning")):
            diagnostics["block_reason"] = "not_potential_preconditioning"
            return False, diagnostics
        if not target_key or not focus_key:
            diagnostics["block_reason"] = "missing_relation_key"
            return False, diagnostics
        for event in self._coordinate_hypothesis_preconditioning_events:
            event_target = str(event.get("commitment_target_key", "") or "")
            event_focus = str(event.get("immediate_target_focus_key", "") or "")
            if not _coordinate_target_keys_match(event_target, target_key):
                continue
            if not _coordinate_target_keys_match(event_focus, focus_key):
                continue
            if bool(event.get("attributed")):
                diagnostics["prior_attributed_count"] += 1
            else:
                diagnostics["prior_pending_count"] += 1
        diagnostics["eligible"] = True
        if diagnostics["prior_attributed_count"] > 0:
            diagnostics["block_reason"] = "relation_has_prior_attribution"
            return False, diagnostics
        if diagnostics["prior_pending_count"] < int(min_pending):
            diagnostics["block_reason"] = "below_min_pending"
            return False, diagnostics
        diagnostics["defer"] = True
        diagnostics["block_reason"] = "preconditioning_repeat_pending_defer"
        return True, diagnostics

    def _coordinate_hypothesis_target_commitment_preconditioning_structured_fallback(
        self,
        packet: Mapping[str, Any],
        observation: Mapping[str, Any],
        *,
        current_hash: str,
        records_count: int,
        target_key: str,
    ) -> tuple[dict[str, Any] | None, dict[str, Any]]:
        enabled = bool(
            self._coordinate_hypothesis_target_commitment_preconditioning_structured_fallback_enabled()
        )
        min_pending = (
            self._coordinate_hypothesis_target_commitment_preconditioning_structured_fallback_min_pending()
        )
        fallback_mode = (
            self._coordinate_hypothesis_target_commitment_preconditioning_structured_fallback_mode()
        )
        metadata = dict(observation.get("metadata") or {})
        target_key = str(target_key or observation.get("target_key", "") or "")
        focus_key = str(metadata.get("target_focus_key", "") or "")
        diagnostics: dict[str, Any] = {
            "enabled": bool(enabled),
            "eligible": False,
            "applied": False,
            "mode": str(fallback_mode),
            "min_pending": int(min_pending),
            "target_key": target_key,
            "suppressed_immediate_target_focus_key": focus_key,
            "prior_pending_count": 0,
            "prior_attributed_count": 0,
            "candidate_count": 0,
            "candidate_count_before_attempted_filter": 0,
            "selected_site": [],
            "block_reason": "",
        }
        if not enabled:
            diagnostics["block_reason"] = "preconditioning_structured_fallback_disabled"
            return None, diagnostics
        if not bool(observation.get("potential_preconditioning")):
            diagnostics["block_reason"] = "not_potential_preconditioning"
            return None, diagnostics
        if not target_key or not focus_key:
            diagnostics["block_reason"] = "missing_relation_key"
            return None, diagnostics
        for event in self._coordinate_hypothesis_preconditioning_events:
            event_target = str(event.get("commitment_target_key", "") or "")
            event_focus = str(event.get("immediate_target_focus_key", "") or "")
            if not _coordinate_target_keys_match(event_target, target_key):
                continue
            if not _coordinate_target_keys_match(event_focus, focus_key):
                continue
            if bool(event.get("attributed")):
                diagnostics["prior_attributed_count"] += 1
            else:
                diagnostics["prior_pending_count"] += 1
        diagnostics["eligible"] = True
        if diagnostics["prior_attributed_count"] > 0:
            diagnostics["block_reason"] = "relation_has_prior_attribution"
            return None, diagnostics
        if diagnostics["prior_pending_count"] < int(min_pending):
            diagnostics["block_reason"] = "below_min_pending"
            return None, diagnostics

        fallback_packet = dict(packet)
        fallback_context = dict(fallback_packet.get("eca_only_context") or {})
        group_focus = self._coordinate_hypothesis_group_focus_payload_from_packet(packet)
        suppressed_target_keys = [
            str(value or "")
            for value in list(group_focus.get("suppressed_target_keys") or [])
            if str(value or "")
        ]
        if focus_key and not _coordinate_target_key_matches_any(
            focus_key, suppressed_target_keys
        ):
            suppressed_target_keys.append(focus_key)
        preferred_target_keys = [] if fallback_mode == "suppress_only" else [target_key]
        fallback_focus = {
            **dict(group_focus),
            "source": "coordinate_target_commitment_preconditioning_structured_fallback",
            "preferred_target_keys": list(preferred_target_keys),
            "suppressed_target_keys": list(suppressed_target_keys),
            "strict_preferred_targets": False,
            "terminal_immediate_target_diversity_enabled": True,
            "terminal_structured_target_diversity_enabled": True,
            "terminal_execution_order_canvas_safety_enabled": bool(
                self._coordinate_hypothesis_terminal_execution_order_canvas_safety_enabled()
            ),
            "terminal_joint_action_budget_guard_enabled": bool(
                self._coordinate_hypothesis_terminal_joint_action_budget_guard_enabled()
            ),
            "terminal_joint_single_target_after_score_guard_enabled": bool(
                self._coordinate_hypothesis_terminal_joint_single_target_after_score_guard_enabled()
            ),
            **self._coordinate_hypothesis_terminal_joint_single_target_after_score_ceiling_payload(),
            "terminal_completion_coverage_guard_enabled": bool(
                self._coordinate_hypothesis_terminal_completion_coverage_guard_enabled()
            ),
            "terminal_completion_best_incomplete_telemetry_enabled": bool(
                self._coordinate_hypothesis_terminal_completion_best_incomplete_telemetry_enabled()
            ),
            "terminal_completion_best_incomplete_fallback_enabled": bool(
                self._coordinate_hypothesis_terminal_completion_best_incomplete_fallback_enabled()
            ),
            "terminal_completion_best_incomplete_min_coverage": int(
                self._coordinate_hypothesis_terminal_completion_best_incomplete_min_coverage()
            ),
            "terminal_completion_best_incomplete_fallback_application_count": int(
                self._coordinate_hypothesis_terminal_best_incomplete_fallback_applied_count
            ),
            "terminal_completion_best_incomplete_max_applications": int(
                self._coordinate_hypothesis_terminal_completion_best_incomplete_max_applications()
            ),
            **self._coordinate_hypothesis_terminal_structured_action_budget_payload(
                records_count=records_count
            ),
            "attempted_candidate_sites": [
                [int(site[0]), int(site[1])]
                for site in sorted(self._coordinate_hypothesis_attempted_sites)
            ],
        }
        if (
            self._coordinate_hypothesis_preconditioning_structured_fallback_remaining_group_enabled()
        ):
            fallback_focus["remaining_target_group_fallback_enabled"] = True
        if (
            self._coordinate_hypothesis_preconditioning_structured_fallback_single_piece_enabled()
        ):
            fallback_focus["single_piece_target_completion_enabled"] = True
        fallback_context["coordinate_group_focus"] = fallback_focus
        fallback_context["coordinate_target_preselection"] = {
            "enabled": bool(self._coordinate_hypothesis_target_preselection_enabled()),
            "source": "coordinate_target_commitment_preconditioning_structured_fallback",
        }
        fallback_context["coordinate_immediate_candidate_flood_guard"] = {
            "enabled": True,
            "threshold": 1,
            "source": "coordinate_target_commitment_preconditioning_structured_fallback",
        }
        fallback_packet["eca_only_context"] = fallback_context
        verification = verify_coordinate_hypothesis(
            fallback_packet,
            self._coordinate_hypothesis_default_hypothesis(),
            current_state_hash=current_hash,
        )
        candidate_sites_before_filter = list(
            getattr(verification, "candidate_sites", ()) or ()
        )
        candidate_sites = [
            site
            for site in candidate_sites_before_filter
            if (int(site[0]), int(site[1])) not in self._coordinate_hypothesis_attempted_sites
        ]
        candidate_sites, requested_overlap_rank_diag = (
            self._coordinate_hypothesis_requested_target_overlap_rank(
                verification,
                candidate_sites,
                preferred_target_keys=preferred_target_keys,
            )
        )
        candidate_sites, requested_score_precondition_rank_diag = (
            self._coordinate_hypothesis_requested_target_score_precondition_rank(
                verification,
                candidate_sites,
                preferred_target_keys=preferred_target_keys,
            )
        )
        candidate_sites, requested_completion_preflight_rank_diag = (
            self._coordinate_hypothesis_requested_target_completion_preflight_rank(
                verification,
                candidate_sites,
                preferred_target_keys=preferred_target_keys,
            )
        )
        selected_site = candidate_sites[0] if candidate_sites else None
        verification_dict = verification.to_dict()
        diagnostics["verification"] = verification_dict
        diagnostics["coordinate_group_focus"] = dict(fallback_focus)
        diagnostics["requested_target_overlap_rank"] = requested_overlap_rank_diag
        diagnostics["requested_target_score_precondition_rank"] = (
            requested_score_precondition_rank_diag
        )
        diagnostics["requested_target_completion_preflight_rank"] = (
            requested_completion_preflight_rank_diag
        )
        diagnostics["candidate_count_before_attempted_filter"] = int(
            len(candidate_sites_before_filter)
        )
        diagnostics["candidate_count"] = int(len(candidate_sites))
        if selected_site is None:
            diagnostics["block_reason"] = "no_structured_fallback_candidate"
            return None, diagnostics
        selected_group = (
            verification_dict.get("diagnostics", {})
            .get("structured_group_completion", {})
            .get("selected_group", {})
        )
        selected_piece_count = int(selected_group.get("piece_count", 0) or 0)
        selected_group_target_key = str(
            selected_group.get("target_focus_key", "") or target_key
        )
        positive_single_piece_prior_count = sum(
            1
            for row in self._coordinate_hypothesis_preconditioning_fallback_outcomes
            if bool(row.get("single_piece"))
            and int(row.get("score_delta", 0) or 0) > 0
            and (
                not selected_group_target_key
                or _coordinate_target_keys_match(
                    str(row.get("selected_target_key", "") or ""),
                    selected_group_target_key,
                )
            )
        )
        score_evidence_guard = {
            "enabled": bool(
                self._coordinate_hypothesis_preconditioning_single_piece_score_evidence_guard_enabled()
            ),
            "applied": False,
            "selected_piece_count": int(selected_piece_count),
            "selected_target_key": str(selected_group_target_key),
            "positive_single_piece_prior_count": int(positive_single_piece_prior_count),
            "block_reason": "",
        }
        diagnostics["preconditioning_single_piece_score_evidence_guard"] = (
            score_evidence_guard
        )
        if (
            bool(score_evidence_guard["enabled"])
            and selected_piece_count == 1
            and positive_single_piece_prior_count <= 0
        ):
            score_evidence_guard["applied"] = True
            score_evidence_guard["block_reason"] = (
                "single_piece_without_prior_score_evidence"
            )
            diagnostics["preconditioning_single_piece_score_evidence_guard"] = (
                score_evidence_guard
            )
            diagnostics["block_reason"] = (
                "preconditioning_single_piece_score_evidence_guard"
            )
            return None, diagnostics

        self._coordinate_hypothesis_attempted_sites.add(
            (int(selected_site[0]), int(selected_site[1]))
        )
        protected_plan_sites = self._coordinate_hypothesis_execution_sites_from_verification(
            verification
        )
        selected_site_key = (int(selected_site[0]), int(selected_site[1]))
        if protected_plan_sites and protected_plan_sites[0] == selected_site_key:
            protected_plan_remaining_sites = protected_plan_sites[1:]
        else:
            protected_plan_sites = []
            protected_plan_remaining_sites = []
        coordinate_target_key = self._coordinate_hypothesis_target_key_from_verification(
            verification,
            selected_site=selected_site,
            allow_immediate_metadata=True,
        )
        coordinate_target_keys = self._coordinate_hypothesis_target_keys_from_verification(
            verification,
            selected_site=selected_site,
            allow_immediate_metadata=True,
        )
        diagnostics["applied"] = True
        diagnostics["selected_site"] = [int(selected_site[0]), int(selected_site[1])]
        diagnostics["protected_plan_site_count"] = int(len(protected_plan_sites))
        diagnostics["protected_plan_remaining_site_count"] = int(
            len(protected_plan_remaining_sites)
        )
        diagnostics["block_reason"] = ""
        choice = {
            "primitive_id": "coordinate_hypothesis_target_commitment",
            "step": ("ACTION6", {"x": int(selected_site[0]), "y": int(selected_site[1])}),
            "reason": (
                "coordinate_hypothesis_target_commitment routed repeated "
                "preconditioning into an ECA-only structured fallback"
            ),
            "selected_site": [int(selected_site[0]), int(selected_site[1])],
            "candidate_count": int(len(candidate_sites)),
            "hypothesis": self._coordinate_hypothesis_default_hypothesis(),
            "protected_plan_sites": [
                [int(site[0]), int(site[1])] for site in protected_plan_sites
            ],
            "protected_plan_remaining_sites": [
                [int(site[0]), int(site[1])] for site in protected_plan_remaining_sites
            ],
            "coordinate_target_key": str(coordinate_target_key or target_key),
            "coordinate_target_keys": list(coordinate_target_keys or [target_key]),
            "target_commitment_preconditioning_structured_fallback_applied": True,
            "target_commitment_preconditioning_structured_fallback_selected_target_key": str(
                coordinate_target_key or target_key
            ),
            "target_commitment_preconditioning_structured_fallback_single_piece": bool(
                selected_piece_count == 1
            ),
            "target_commitment_preconditioning_observation": dict(observation),
            "target_commitment_preconditioning_structured_fallback": dict(diagnostics),
        }
        return choice, diagnostics

    def _coordinate_hypothesis_requested_target_completion_preflight_rank(
        self,
        verification: Any,
        candidate_sites: Sequence[Any],
        *,
        preferred_target_keys: Sequence[str] | None = None,
    ) -> tuple[list[Any], dict[str, Any]]:
        enabled = bool(
            self._coordinate_hypothesis_requested_target_completion_preflight_rank_enabled()
        )
        configured_min_coverage = (
            self._coordinate_hypothesis_requested_target_completion_preflight_min_coverage()
        )
        preferred = [
            str(key or "")
            for key in list(preferred_target_keys or [])
            if str(key or "")
        ]
        sites = list(candidate_sites)
        diagnostics: dict[str, Any] = {
            "enabled": bool(enabled),
            "applied": False,
            "candidate_count": int(len(sites)),
            "metadata_count": 0,
            "preferred_target_keys": list(preferred),
            "configured_min_coverage": int(configured_min_coverage),
            "effective_min_coverage": 0,
            "covered_candidate_count": 0,
            "filtered_candidate_count": 0,
            "candidate_count_after_filter": int(len(sites)),
            "max_projected_preferred_coverage_count": 0,
            "selected_site_before_rank": [
                int(sites[0][0]),
                int(sites[0][1]),
            ] if sites and isinstance(sites[0], (list, tuple)) and len(sites[0]) >= 2 else [],
            "selected_site_after_rank": [],
            "selected_site_changed": False,
            "top_projected_preferred_target_keys": [],
            "top_ranked_site_metadata": {},
        }
        if not enabled:
            diagnostics["selected_site_after_rank"] = list(
                diagnostics["selected_site_before_rank"]
            )
            return sites, diagnostics
        if not sites:
            return sites, diagnostics
        if not preferred:
            diagnostics["block_reason"] = "no_preferred_target_keys"
            diagnostics["selected_site_after_rank"] = list(
                diagnostics["selected_site_before_rank"]
            )
            return sites, diagnostics
        effective_min_coverage = max(1, min(int(configured_min_coverage), len(preferred)))
        diagnostics["effective_min_coverage"] = int(effective_min_coverage)

        metadata_by_site: dict[tuple[int, int], dict[str, Any]] = {}
        diagnostics_map = dict(getattr(verification, "diagnostics", {}) or {})
        for raw_row in list(diagnostics_map.get("immediate_candidate_site_metadata") or []):
            if not isinstance(raw_row, Mapping):
                continue
            raw_site = raw_row.get("site")
            if not isinstance(raw_site, (list, tuple)) or len(raw_site) < 2:
                continue
            try:
                site_key = (int(raw_site[0]), int(raw_site[1]))
            except (TypeError, ValueError):
                continue
            metadata_by_site[site_key] = dict(raw_row)
        diagnostics["metadata_count"] = int(len(metadata_by_site))
        if not metadata_by_site:
            diagnostics["selected_site_after_rank"] = list(
                diagnostics["selected_site_before_rank"]
            )
            return sites, diagnostics

        def metadata_for_site(site: Any) -> dict[str, Any]:
            if not isinstance(site, (list, tuple)) or len(site) < 2:
                return {}
            try:
                site_key = (int(site[0]), int(site[1]))
            except (TypeError, ValueError):
                return {}
            return dict(metadata_by_site.get(site_key) or {})

        def int_meta(row: Mapping[str, Any], key: str, default: int = 0) -> int:
            try:
                return int(row.get(key, default) or default)
            except (TypeError, ValueError):
                return int(default)

        def projected_keys(row: Mapping[str, Any]) -> list[str]:
            keys: list[str] = []
            raw_keys = row.get("projected_satisfied_target_keys")
            if isinstance(raw_keys, (list, tuple)):
                keys.extend(str(key or "") for key in raw_keys if str(key or ""))
            target_key = str(row.get("target_focus_key", "") or "")
            if (
                target_key
                and int_meta(row, "predicted_requested_target_satisfied_delta") > 0
            ):
                keys.append(target_key)
            return list(dict.fromkeys(keys))

        def coverage_keys(row: Mapping[str, Any]) -> list[str]:
            keys = projected_keys(row)
            covered: list[str] = []
            for preferred_key in preferred:
                if any(_coordinate_target_keys_match(key, preferred_key) for key in keys):
                    covered.append(preferred_key)
            return list(dict.fromkeys(covered))

        def coverage_count(row: Mapping[str, Any]) -> int:
            return int(len(coverage_keys(row)))

        ranked_sites = sorted(
            enumerate(sites),
            key=lambda item: (
                -coverage_count(metadata_for_site(item[1])),
                -int_meta(
                    metadata_for_site(item[1]),
                    "predicted_requested_target_satisfied_delta",
                ),
                -int_meta(
                    metadata_for_site(item[1]),
                    "predicted_canvas_satisfied_pair_delta",
                ),
                -int_meta(
                    metadata_for_site(item[1]),
                    "predicted_canvas_overlap_area_delta",
                ),
                -int_meta(metadata_for_site(item[1]), "overlap_area"),
                int_meta(metadata_for_site(item[1]), "distance", 10**9),
                int(item[0]),
            ),
        )
        ordered = [site for _index, site in ranked_sites]
        max_coverage = max(
            [coverage_count(metadata_for_site(site)) for site in sites] or [0]
        )
        filtered = [
            site
            for site in ordered
            if coverage_count(metadata_for_site(site)) >= int(effective_min_coverage)
        ]
        diagnostics["covered_candidate_count"] = int(len(filtered))
        diagnostics["filtered_candidate_count"] = int(len(sites) - len(filtered))
        diagnostics["candidate_count_after_filter"] = int(len(filtered))
        diagnostics["max_projected_preferred_coverage_count"] = int(max_coverage)
        if not filtered:
            diagnostics["block_reason"] = (
                "no_candidate_meets_requested_target_completion_preflight"
            )
            diagnostics["applied"] = bool(bool(sites))
            return [], diagnostics
        diagnostics["applied"] = bool(filtered != sites)
        if filtered and isinstance(filtered[0], (list, tuple)) and len(filtered[0]) >= 2:
            top_metadata = metadata_for_site(filtered[0])
            diagnostics["selected_site_after_rank"] = [
                int(filtered[0][0]),
                int(filtered[0][1]),
            ]
            diagnostics["top_projected_preferred_target_keys"] = coverage_keys(top_metadata)
            diagnostics["top_ranked_site_metadata"] = top_metadata
        diagnostics["selected_site_changed"] = bool(
            diagnostics["selected_site_before_rank"]
            and diagnostics["selected_site_after_rank"]
            and diagnostics["selected_site_before_rank"]
            != diagnostics["selected_site_after_rank"]
        )
        return filtered, diagnostics

    def _coordinate_hypothesis_best_incomplete_fallback_applied_from_verification(
        self,
        verification: Any,
    ) -> bool:
        diagnostics = dict(getattr(verification, "diagnostics", {}) or {})
        structured = dict(diagnostics.get("structured_group_completion") or {})
        return bool(
            structured.get("terminal_completion_best_incomplete_fallback_applied")
        )

    def _coordinate_hypothesis_structured_summary_from_verification(
        self,
        verification: Any,
    ) -> dict[str, Any]:
        diagnostics = dict(getattr(verification, "diagnostics", {}) or {})
        structured = dict(diagnostics.get("structured_group_completion") or {})
        selected_group = dict(structured.get("selected_group") or {})
        joint = dict(structured.get("joint_target_assignment") or {})
        candidate_sites = list(getattr(verification, "candidate_sites", ()) or ())

        def int_value(mapping: Mapping[str, Any], key: str) -> int:
            try:
                return int(mapping.get(key, 0) or 0)
            except (TypeError, ValueError):
                return 0

        def str_list(value: Any, *, limit: int = 8) -> list[str]:
            if not isinstance(value, (list, tuple)):
                return []
            return [str(item or "") for item in list(value)[:limit] if str(item or "")]

        skip_reasons = {
            str(key): int(value or 0)
            for key, value in dict(structured.get("skip_reasons") or {}).items()
        }
        return {
            "candidate_site_count": int(len(candidate_sites)),
            "first_candidate_site": [
                int(candidate_sites[0][0]),
                int(candidate_sites[0][1]),
            ] if candidate_sites else [],
            "structured_group_completion": {
                "attempted": bool(structured.get("attempted")),
                "groups_evaluated": int_value(structured, "groups_evaluated"),
                "target_options_evaluated": int_value(
                    structured, "target_options_evaluated"
                ),
                "safe_destination_plan_count": int_value(
                    structured, "safe_destination_plan_count"
                ),
                "first_action_site_count": int_value(
                    structured, "first_action_site_count"
                ),
                "terminal_completion_required_target_count": int_value(
                    structured, "terminal_completion_required_target_count"
                ),
                "terminal_completion_coverage_skip_count": int_value(
                    structured, "terminal_completion_coverage_skip_count"
                ),
                "terminal_completion_best_incomplete_fallback_enabled": bool(
                    structured.get("terminal_completion_best_incomplete_fallback_enabled")
                ),
                "terminal_completion_best_incomplete_fallback_applied": bool(
                    structured.get("terminal_completion_best_incomplete_fallback_applied")
                ),
                "terminal_completion_best_incomplete_coverage_count": int_value(
                    structured, "terminal_completion_best_incomplete_coverage_count"
                ),
                "terminal_completion_best_incomplete_assignment_count": int_value(
                    structured, "terminal_completion_best_incomplete_assignment_count"
                ),
                "terminal_completion_best_incomplete_execution_site_count": int_value(
                    structured,
                    "terminal_completion_best_incomplete_execution_site_count",
                ),
                "terminal_completion_best_incomplete_target_keys": str_list(
                    structured.get("terminal_completion_best_incomplete_target_keys")
                ),
                "terminal_completion_best_incomplete_first_site": list(
                    structured.get("terminal_completion_best_incomplete_first_site")
                    or []
                )[:2],
                "selected_group_target_focus_key": str(
                    selected_group.get("target_focus_key", "") or ""
                ),
                "selected_group_execution_site_count": int_value(
                    selected_group, "execution_site_count"
                ),
                "selected_group_target_color_coverage_count": int_value(
                    selected_group, "target_color_coverage_count"
                ),
                "selected_group_target_color_missing_count": int_value(
                    selected_group, "target_color_missing_count"
                ),
                "selected_group_target_color_complete": bool(
                    selected_group.get("target_color_complete")
                ),
                "selected_group_joint_target_keys": str_list(
                    selected_group.get("joint_assignment_target_keys")
                ),
                "skip_reasons": skip_reasons,
                "joint_target_assignment": {
                    "attempted": bool(joint.get("attempted")),
                    "pair_candidate_count": int_value(joint, "pair_candidate_count"),
                    "search_state_count": int_value(joint, "search_state_count"),
                    "selected_assignment_count": int_value(
                        joint, "selected_assignment_count"
                    ),
                    "selected_execution_site_count": int_value(
                        joint, "selected_execution_site_count"
                    ),
                    "selected_target_keys": str_list(joint.get("selected_target_keys")),
                    "block_reason": str(joint.get("block_reason", "") or ""),
                    "best_incomplete_fallback_enabled": bool(
                        joint.get("best_incomplete_fallback_enabled")
                    ),
                    "best_incomplete_fallback_applied": bool(
                        joint.get("best_incomplete_fallback_applied")
                    ),
                    "best_incomplete_coverage_count": int_value(
                        joint, "best_incomplete_coverage_count"
                    ),
                    "best_incomplete_assignment_count": int_value(
                        joint, "best_incomplete_assignment_count"
                    ),
                    "best_incomplete_execution_site_count": int_value(
                        joint, "best_incomplete_execution_site_count"
                    ),
                    "best_incomplete_target_keys": str_list(
                        joint.get("best_incomplete_target_keys")
                    ),
                },
            },
        }

    def _coordinate_hypothesis_default_hypothesis(self) -> dict[str, Any]:
        return {
            "schema_version": "eca_coordinate_hypothesis.v1",
            "coordinate_hypothesis": "centroid_overlap",
            "actors": ["piece_group", "canvas", "target"],
            "relation": "canvas_centroid_tracks_piece_group_centroid",
            "goal_test": "canvas_overlaps_target",
            "candidate_generation": "solve_missing_piece_position",
            "confidence": 0.7,
            "required_sensors": ["component_centroids", "component_bboxes"],
        }

    def _coordinate_hypothesis_target_commitment_pause_exception(
        self,
        commitment: Mapping[str, Any],
    ) -> tuple[bool, dict[str, Any]]:
        enabled = bool(self._coordinate_hypothesis_target_commitment_pause_exception_enabled())
        progress_kind = str(commitment.get("progress_kind", "") or "")
        source_primitive = str(commitment.get("source_primitive_id", "") or "")
        last_no_progress_primitive = str(commitment.get("last_no_progress_primitive_id", "") or "")
        has_corrective_source = bool(
            commitment.get("last_progress_site")
            and commitment.get("last_no_progress_plan_id") is not None
            and last_no_progress_primitive != "coordinate_hypothesis_target_commitment"
        )
        has_handoff_source = bool(
            progress_kind == "satisfied_target_handoff"
            and commitment.get("handoff_from_target_key")
        )
        reason = ""
        eligible = False
        if not enabled:
            reason = "disabled"
        elif bool(commitment.get("pause_exception_used")):
            reason = "already_used"
        elif has_handoff_source:
            eligible = True
            reason = "satisfied_target_handoff"
        elif has_corrective_source:
            eligible = True
            reason = "post_no_progress_corrective_commitment"
        else:
            reason = "no_corrective_commitment_source"
        return bool(eligible), {
            "enabled": enabled,
            "eligible": bool(eligible),
            "reason": reason,
            "progress_kind": progress_kind,
            "source_primitive_id": source_primitive,
            "last_no_progress_primitive_id": last_no_progress_primitive,
            "already_used": bool(commitment.get("pause_exception_used")),
        }

    def record_coordinate_hypothesis_target_commitment_shadow_rejection(
        self,
        event: Mapping[str, Any],
    ) -> dict[str, Any]:
        enabled = bool(
            self._coordinate_hypothesis_target_commitment_shadow_rejection_suppression_enabled()
        )
        target_keys: list[str] = []
        for raw_key in [
            event.get("target_key", ""),
            event.get("resolved_target_key", ""),
            *list(event.get("target_keys") or []),
        ]:
            key = str(raw_key or "")
            if key and not _coordinate_target_key_matches_any(key, target_keys):
                target_keys.append(key)

        sites: list[tuple[int, int]] = []

        def add_site(raw_site: Any) -> None:
            if not isinstance(raw_site, (list, tuple)) or len(raw_site) < 2:
                return
            try:
                site = (int(raw_site[0]), int(raw_site[1]))
            except (TypeError, ValueError):
                return
            if site not in sites:
                sites.append(site)

        add_site(event.get("selected_site"))
        for raw_site in list(event.get("candidate_sites") or []):
            add_site(raw_site)
        for row in list(event.get("first_candidate_results") or []):
            if isinstance(row, Mapping):
                add_site(row.get("site"))

        diag = {
            "enabled": bool(enabled),
            "target_keys": list(target_keys),
            "site_count": int(len(sites)),
            "recorded": False,
            "suppressed_target_key_count_before": int(
                len(self._coordinate_hypothesis_shadow_rejected_target_keys)
            ),
            "suppressed_site_count_before": int(
                len(self._coordinate_hypothesis_shadow_rejected_sites)
            ),
        }
        if not enabled:
            return diag
        for key in target_keys:
            if not _coordinate_target_key_matches_any(
                key,
                self._coordinate_hypothesis_shadow_rejected_target_keys,
            ):
                self._coordinate_hypothesis_shadow_rejected_target_keys.append(key)
        for site in sites:
            self._coordinate_hypothesis_shadow_rejected_sites.add(site)
        self._coordinate_hypothesis_shadow_rejection_events.append(
            {
                "target_keys": list(target_keys),
                "selected_site": list(event.get("selected_site") or []),
                "candidate_sites": [[int(x), int(y)] for x, y in sites[:16]],
                "step": int(event.get("step", 0) or 0),
                "positive_score_candidate_count": int(
                    event.get("positive_score_candidate_count", 0) or 0
                ),
                "tested_count": int(event.get("tested_count", 0) or 0),
            }
        )
        self._coordinate_hypothesis_shadow_rejection_events = (
            self._coordinate_hypothesis_shadow_rejection_events[-16:]
        )
        diag.update(
            {
                "recorded": True,
                "suppressed_target_key_count_after": int(
                    len(self._coordinate_hypothesis_shadow_rejected_target_keys)
                ),
                "suppressed_site_count_after": int(
                    len(self._coordinate_hypothesis_shadow_rejected_sites)
                ),
            }
        )
        return diag

    def _coordinate_hypothesis_shadow_rejected_target_keys_if_enabled(self) -> list[str]:
        if not bool(
            self._coordinate_hypothesis_target_commitment_shadow_rejection_suppression_enabled()
        ):
            return []
        return list(self._coordinate_hypothesis_shadow_rejected_target_keys)

    def _coordinate_hypothesis_target_commitment_choice(
        self,
        *,
        frame_arr: np.ndarray,
        current_hash: str,
        available_actions: set[str],
        records_count: int,
        blocked_by_stable_solver: bool,
        stable_solver_reasons: list[str],
    ) -> tuple[dict[str, Any] | None, dict[str, Any]]:
        enabled = bool(self._coordinate_hypothesis_target_commitment_enabled())
        commitment = dict(self._coordinate_hypothesis_target_commitment or {})
        target_key = str(commitment.get("target_key", "") or "")
        progress_kind = str(commitment.get("progress_kind", "") or "")
        max_attempts = self._coordinate_hypothesis_target_commitment_max_attempts()
        attempt_count = int(commitment.get("attempt_count", 0) or 0)
        retirement_enabled = bool(
            self._coordinate_hypothesis_terminal_failed_commitment_retirement_enabled()
        )
        recent_no_progress_target_keys = (
            self._coordinate_hypothesis_recent_no_progress_target_keys()
            if retirement_enabled
            else []
        )
        completed_no_score_retirement_enabled = bool(
            self._coordinate_hypothesis_target_commitment_completed_no_score_retirement_enabled()
        )
        recent_completed_no_score_target_keys = (
            self._coordinate_hypothesis_recent_completed_no_score_target_keys()
            if completed_no_score_retirement_enabled
            else []
        )
        completed_no_score_exact_retirement_enabled = bool(
            self._coordinate_hypothesis_target_commitment_completed_no_score_exact_instance_retirement_enabled()
        )
        recent_completed_no_score_exact_target_keys = (
            self._coordinate_hypothesis_recent_completed_no_score_target_keys(
                exact_instance=True
            )
            if completed_no_score_exact_retirement_enabled
            else []
        )
        repeated_exact_retirement_enabled = bool(
            self._coordinate_hypothesis_target_commitment_completed_no_score_repeated_exact_instance_retirement_enabled()
        )
        repeated_exact_min_observations = (
            self._coordinate_hypothesis_target_commitment_completed_no_score_repeated_exact_instance_min_observations()
        )
        repeated_exact_counts = (
            self._coordinate_hypothesis_recent_completed_no_score_exact_target_counts()
            if repeated_exact_retirement_enabled
            else {}
        )
        repeated_exact_target_keys = [
            key
            for key, count in repeated_exact_counts.items()
            if int(count) >= int(repeated_exact_min_observations)
        ]
        single_no_score_alternative_enabled = bool(
            self._coordinate_hypothesis_target_commitment_single_no_score_alternative_probe_enabled()
        )
        single_no_score_alternative_extra_attempts = (
            self._coordinate_hypothesis_target_commitment_single_no_score_alternative_extra_attempts()
        )
        single_no_score_alternative_counts = (
            self._coordinate_hypothesis_recent_completed_no_score_exact_target_counts()
            if single_no_score_alternative_enabled
            else {}
        )
        single_no_score_alternative_sites_by_target = (
            self._coordinate_hypothesis_recent_completed_no_score_exact_target_sites()
            if single_no_score_alternative_enabled
            else {}
        )
        single_no_score_alternative_nonpositive_sites_by_target = (
            self._coordinate_hypothesis_recent_nonpositive_exact_target_sites()
            if single_no_score_alternative_enabled
            else {}
        )
        shadow_rejected_target_keys = (
            self._coordinate_hypothesis_shadow_rejected_target_keys_if_enabled()
        )
        retired_target_key = ""
        if (
            retirement_enabled
            and target_key
            and _coordinate_target_key_matches_any(target_key, recent_no_progress_target_keys)
        ):
            retired_target_key = target_key
            self._coordinate_hypothesis_target_commitment.clear()
            commitment = {}
            target_key = ""
            progress_kind = ""
            attempt_count = 0
        completed_no_score_retired_target_key = ""
        if (
            completed_no_score_retirement_enabled
            and target_key
            and _coordinate_target_key_matches_any(
                target_key,
                recent_completed_no_score_target_keys,
            )
        ):
            completed_no_score_retired_target_key = target_key
            self._coordinate_hypothesis_target_commitment.clear()
            commitment = {}
            target_key = ""
            progress_kind = ""
            attempt_count = 0
        completed_no_score_exact_retired_target_key = ""
        if (
            completed_no_score_exact_retirement_enabled
            and target_key
            and target_key in set(recent_completed_no_score_exact_target_keys)
        ):
            completed_no_score_exact_retired_target_key = target_key
            self._coordinate_hypothesis_target_commitment.clear()
            commitment = {}
            target_key = ""
            progress_kind = ""
            attempt_count = 0
        repeated_exact_retired_target_key = ""
        repeated_exact_retired_observation_count = 0
        if (
            repeated_exact_retirement_enabled
            and target_key
            and int(repeated_exact_counts.get(target_key, 0) or 0)
            >= int(repeated_exact_min_observations)
        ):
            repeated_exact_retired_target_key = target_key
            repeated_exact_retired_observation_count = int(
                repeated_exact_counts.get(target_key, 0) or 0
            )
            self._coordinate_hypothesis_target_commitment.clear()
            commitment = {}
            target_key = ""
            progress_kind = ""
            attempt_count = 0
        shadow_rejected_target_key = ""
        if (
            target_key
            and _coordinate_target_key_matches_any(target_key, shadow_rejected_target_keys)
        ):
            shadow_rejected_target_key = target_key
            self._coordinate_hypothesis_target_commitment.clear()
            commitment = {}
            target_key = ""
            progress_kind = ""
            attempt_count = 0
        no_progress_pause_threshold = self._coordinate_hypothesis_pause_after_no_progress_plans()
        recent_no_progress_plans = self._coordinate_hypothesis_recent_no_progress_plan_count()
        pause_exception_allowed, pause_exception_diag = (
            self._coordinate_hypothesis_target_commitment_pause_exception(commitment)
        )
        handoff_flood_guard_enabled = bool(
            self._coordinate_hypothesis_handoff_immediate_flood_guard_enabled()
        )
        handoff_flood_threshold = self._coordinate_hypothesis_handoff_immediate_flood_threshold()
        lock_replan_enabled = bool(
            self._coordinate_hypothesis_satisfied_pair_lock_replan_enabled()
        )
        single_no_score_target_count = int(
            single_no_score_alternative_counts.get(target_key, 0) or 0
        )
        single_no_score_target_sites = [
            list(site)
            for site in list(single_no_score_alternative_sites_by_target.get(target_key) or [])
            if isinstance(site, (list, tuple)) and len(site) >= 2
        ]
        single_no_score_nonpositive_target_sites = [
            list(site)
            for site in list(
                single_no_score_alternative_nonpositive_sites_by_target.get(target_key)
                or []
            )
            if isinstance(site, (list, tuple)) and len(site) >= 2
        ]
        for raw_site in [
            commitment.get("last_selected_site"),
            commitment.get("last_progress_site"),
            commitment.get("last_no_progress_site"),
        ]:
            if not isinstance(raw_site, (list, tuple)) or len(raw_site) < 2:
                continue
            try:
                site = [int(raw_site[0]), int(raw_site[1])]
            except (TypeError, ValueError):
                continue
            if site not in single_no_score_nonpositive_target_sites:
                single_no_score_nonpositive_target_sites.append(site)
        single_no_score_alternative_max_attempts_eligible = bool(
            single_no_score_alternative_enabled
            and target_key
            and max_attempts > 0
            and attempt_count >= max_attempts
            and attempt_count
            < max_attempts + int(single_no_score_alternative_extra_attempts)
            and single_no_score_target_count == 1
            and single_no_score_target_sites
        )
        single_no_score_alternative_grace_defer_enabled = bool(
            self._coordinate_hypothesis_target_commitment_single_no_score_alternative_grace_defer_enabled()
        )
        single_no_score_alternative_grace_blocks = int(
            self._coordinate_hypothesis_target_commitment_single_no_score_alternative_grace_blocks()
        )
        single_no_score_alternative_defer_count = int(
            commitment.get("single_no_score_alternative_defer_count", 0) or 0
        )
        single_no_score_alternative_grace_deferred = bool(
            single_no_score_alternative_max_attempts_eligible
            and single_no_score_alternative_grace_defer_enabled
            and single_no_score_alternative_defer_count
            < single_no_score_alternative_grace_blocks
        )
        diag: dict[str, Any] = {
            "enabled": bool(self._coordinate_hypothesis_lane_enabled()),
            "provider_available": bool(self.coordinate_hypothesis_bridge.provider is not None),
            "provider_called": False,
            "choice_generated": False,
            "selected_site": [],
            "candidate_sites_generated_from_hypothesis_count": 0,
            "candidate_sites_contains_selected_site": False,
            "direct_llm_action_blocked_count": 0,
            "target_commitment": {
                "enabled": enabled,
                "available": bool(target_key),
                "target_key": target_key,
                "attempt_count": int(attempt_count),
                "max_attempts": int(max_attempts),
                "applied": False,
                "block_reason": "",
            },
            "terminal_failed_commitment_retirement": {
                "enabled": bool(retirement_enabled),
                "retired": bool(retired_target_key),
                "retired_target_key": str(retired_target_key),
                "recent_no_progress_target_keys": list(recent_no_progress_target_keys),
            },
            "target_commitment_completed_no_score_retirement": {
                "enabled": bool(completed_no_score_retirement_enabled),
                "retired": bool(completed_no_score_retired_target_key),
                "retired_target_key": str(completed_no_score_retired_target_key),
                "recent_completed_no_score_target_keys": list(
                    recent_completed_no_score_target_keys
                ),
            },
            "target_commitment_completed_no_score_exact_instance_retirement": {
                "enabled": bool(completed_no_score_exact_retirement_enabled),
                "retired": bool(completed_no_score_exact_retired_target_key),
                "retired_target_key": str(completed_no_score_exact_retired_target_key),
                "recent_completed_no_score_exact_target_keys": list(
                    recent_completed_no_score_exact_target_keys
                ),
            },
            "target_commitment_completed_no_score_repeated_exact_instance_retirement": {
                "enabled": bool(repeated_exact_retirement_enabled),
                "retired": bool(repeated_exact_retired_target_key),
                "retired_target_key": str(repeated_exact_retired_target_key),
                "retired_observation_count": int(
                    repeated_exact_retired_observation_count
                ),
                "min_observations": int(repeated_exact_min_observations),
                "recent_completed_no_score_exact_target_counts": dict(
                    repeated_exact_counts
                ),
                "eligible_target_keys": list(repeated_exact_target_keys),
            },
            "target_commitment_single_no_score_alternative_probe": {
                "enabled": bool(single_no_score_alternative_enabled),
                "eligible": bool(single_no_score_alternative_max_attempts_eligible),
                "applied": False,
                "bypassed_max_attempts": False,
                "single_remaining_target_guard_enabled": bool(
                    self._coordinate_hypothesis_target_commitment_single_no_score_alternative_single_remaining_target_guard_enabled()
                ),
                "single_remaining_target_guard_applied": False,
                "unsatisfied_target_keys": [],
                "grace_defer_enabled": bool(
                    single_no_score_alternative_grace_defer_enabled
                ),
                "grace_deferred": bool(
                    single_no_score_alternative_grace_deferred
                ),
                "grace_blocks": int(single_no_score_alternative_grace_blocks),
                "grace_defer_count_before": int(
                    single_no_score_alternative_defer_count
                ),
                "grace_defer_count_after": int(
                    single_no_score_alternative_defer_count
                    + (1 if single_no_score_alternative_grace_deferred else 0)
                ),
                "extra_attempts": int(single_no_score_alternative_extra_attempts),
                "target_key": str(target_key),
                "target_completed_no_score_exact_count": int(single_no_score_target_count),
                "recent_completed_no_score_exact_target_counts": dict(
                    single_no_score_alternative_counts
                ),
                "recent_completed_no_score_exact_sites": list(
                    single_no_score_target_sites
                ),
                "recent_nonpositive_exact_sites": list(
                    single_no_score_nonpositive_target_sites
                ),
                "candidate_count_before_filter": 0,
                "candidate_count_after_filter": 0,
                "selected_site_before_filter": [],
                "selected_site_after_filter": [],
                "filtered_no_score_site_count": 0,
                "block_reason": "",
            },
            "target_commitment_shadow_rejection_suppression": {
                "enabled": bool(
                    self._coordinate_hypothesis_target_commitment_shadow_rejection_suppression_enabled()
                ),
                "suppressed": bool(shadow_rejected_target_key),
                "suppressed_target_key": str(shadow_rejected_target_key),
                "shadow_rejected_target_keys": list(shadow_rejected_target_keys),
                "shadow_rejected_site_count": int(
                    len(self._coordinate_hypothesis_shadow_rejected_sites)
                ),
            },
            "handoff_immediate_flood_guard": {
                "enabled": bool(handoff_flood_guard_enabled),
                "threshold": int(handoff_flood_threshold),
                "eligible": bool(progress_kind == "satisfied_target_handoff"),
                "applied_to_packet": False,
            },
            "target_commitment_pause_exception": {
                **dict(pause_exception_diag),
                "applied": False,
            },
            "satisfied_pair_lock_replan": {
                "enabled": bool(lock_replan_enabled),
                "eligible": False,
                "applied": False,
                "block_reason": "",
                "locked_satisfied_canvas_id_count": 0,
                "fallback_candidate_count": 0,
            },
            "call_gate": {
                "allowed": False,
                "block_reason": "target_commitment_not_selected",
                "provider_call_count_before": int(self._coordinate_hypothesis_provider_call_count),
                "provider_call_count_after": int(self._coordinate_hypothesis_provider_call_count),
                "score_success_count": int(self._coordinate_hypothesis_score_success_count),
                "stable_solver_reasons": list(stable_solver_reasons),
                "no_progress_plan_pause_threshold": int(no_progress_pause_threshold),
                "recent_no_progress_plan_count": int(recent_no_progress_plans),
            },
        }
        block_reason = ""
        if not enabled:
            block_reason = "target_commitment_disabled"
        elif not self._coordinate_hypothesis_lane_enabled():
            block_reason = "coordinate_hypothesis_lane_disabled"
        elif retired_target_key:
            block_reason = "target_commitment_recent_no_progress_retired"
        elif completed_no_score_retired_target_key:
            block_reason = "target_commitment_completed_no_score_retired"
        elif completed_no_score_exact_retired_target_key:
            block_reason = "target_commitment_completed_no_score_exact_instance_retired"
        elif repeated_exact_retired_target_key:
            block_reason = (
                "target_commitment_completed_no_score_repeated_exact_instance_retired"
            )
        elif shadow_rejected_target_key:
            block_reason = "target_commitment_shadow_rejected_target_family"
        elif not target_key:
            block_reason = "no_active_target_commitment"
        elif "ACTION6" not in available_actions:
            block_reason = "action6_unavailable"
        elif blocked_by_stable_solver:
            block_reason = "stable_solver_available"
        elif (
            no_progress_pause_threshold > 0
            and recent_no_progress_plans >= no_progress_pause_threshold
            and not pause_exception_allowed
        ):
            block_reason = "coordinate_plan_no_progress_posterior"
        elif max_attempts <= 0:
            block_reason = "max_attempts_zero"
        elif attempt_count >= max_attempts:
            if single_no_score_alternative_grace_deferred:
                commitment["single_no_score_alternative_defer_count"] = (
                    int(single_no_score_alternative_defer_count) + 1
                )
                self._coordinate_hypothesis_target_commitment = dict(commitment)
                block_reason = "single_no_score_alternative_grace_defer"
                diag["target_commitment_single_no_score_alternative_probe"] = {
                    **dict(
                        diag[
                            "target_commitment_single_no_score_alternative_probe"
                        ]
                    ),
                    "grace_deferred": True,
                    "grace_defer_count_after": int(
                        single_no_score_alternative_defer_count + 1
                    ),
                    "block_reason": "single_no_score_alternative_grace_defer",
                }
            elif single_no_score_alternative_max_attempts_eligible:
                diag["target_commitment_single_no_score_alternative_probe"] = {
                    **dict(
                        diag[
                            "target_commitment_single_no_score_alternative_probe"
                        ]
                    ),
                    "bypassed_max_attempts": True,
                }
            else:
                block_reason = "target_commitment_max_attempts"
        if block_reason:
            diag["target_commitment"]["block_reason"] = block_reason
            diag["call_gate"] = {
                **dict(diag["call_gate"]),
                "block_reason": block_reason,
                "stable_solver_reasons": list(stable_solver_reasons),
            }
            return None, diag
        try:
            remembered_targets = self._coordinate_hypothesis_remembered_targets()
            packet = build_r11l_l1_coordinate_sensor_packet(
                frame_arr,
                state_hash=current_hash,
                step=int(records_count),
                remembered_targets=remembered_targets,
                include_eca_only_context=True,
            )
            self._remember_coordinate_hypothesis_targets(packet)
            eca_context = dict(packet.get("eca_only_context") or {})
            lock_payload = self._coordinate_hypothesis_satisfied_pair_lock_payload_from_packet(packet)
            stale_target_keys = self._coordinate_hypothesis_post_score1_stale_target_keys()
            eca_context["coordinate_group_focus"] = {
                "enabled": True,
                "preferred_target_keys": [target_key],
                "suppressed_target_keys": [],
                "source": "coordinate_target_commitment",
                "strict_preferred_targets": True,
                "terminal_execution_order_canvas_safety_enabled": bool(
                    self._coordinate_hypothesis_terminal_execution_order_canvas_safety_enabled()
                ),
                "terminal_joint_action_budget_guard_enabled": bool(
                    self._coordinate_hypothesis_terminal_joint_action_budget_guard_enabled()
                ),
                "terminal_joint_single_target_after_score_guard_enabled": bool(
                    self._coordinate_hypothesis_terminal_joint_single_target_after_score_guard_enabled()
                ),
                **self._coordinate_hypothesis_terminal_joint_single_target_after_score_ceiling_payload(),
                "terminal_completion_coverage_guard_enabled": bool(
                    self._coordinate_hypothesis_terminal_completion_coverage_guard_enabled()
                ),
                "terminal_completion_best_incomplete_telemetry_enabled": bool(
                    self._coordinate_hypothesis_terminal_completion_best_incomplete_telemetry_enabled()
                ),
                "terminal_completion_best_incomplete_fallback_enabled": bool(
                    self._coordinate_hypothesis_terminal_completion_best_incomplete_fallback_enabled()
                ),
                "terminal_completion_best_incomplete_min_coverage": int(
                    self._coordinate_hypothesis_terminal_completion_best_incomplete_min_coverage()
                ),
                "terminal_completion_best_incomplete_fallback_application_count": int(
                    self._coordinate_hypothesis_terminal_best_incomplete_fallback_applied_count
                ),
                "terminal_completion_best_incomplete_max_applications": int(
                    self._coordinate_hypothesis_terminal_completion_best_incomplete_max_applications()
                ),
                **lock_payload,
                "post_score1_score_bearing_immediate_guard_enabled": bool(
                    self._coordinate_hypothesis_post_score1_score_bearing_immediate_guard_enabled()
                    and stale_target_keys
                ),
                "post_score1_score_bearing_stale_target_keys": list(stale_target_keys),
                **self._coordinate_hypothesis_terminal_structured_action_budget_payload(
                    records_count=records_count
                ),
            }
            eca_context["coordinate_target_preselection"] = {
                "enabled": bool(self._coordinate_hypothesis_target_preselection_enabled()),
                "source": "coordinate_target_commitment",
            }
            if handoff_flood_guard_enabled and progress_kind == "satisfied_target_handoff":
                eca_context["coordinate_immediate_candidate_flood_guard"] = {
                    "enabled": True,
                    "threshold": int(handoff_flood_threshold),
                    "source": "satisfied_target_handoff",
                }
                diag["handoff_immediate_flood_guard"]["applied_to_packet"] = True
            packet["eca_only_context"] = eca_context
        except Exception as exc:
            diag["error"] = f"{type(exc).__name__}: {exc}"
            diag["target_commitment"]["block_reason"] = "packet_build_error"
            return None, diag
        if (
            single_no_score_alternative_max_attempts_eligible
            and self._coordinate_hypothesis_target_commitment_single_no_score_alternative_single_remaining_target_guard_enabled()
        ):
            components = [
                row
                for row in list(packet.get("components") or [])
                if isinstance(row, Mapping)
            ]
            snapshot = self._coordinate_hypothesis_relation_snapshot_from_components(
                components
            )
            unsatisfied_keys = [
                str(key or "")
                for key in list(snapshot.get("unsatisfied_target_keys") or [])
                if str(key or "")
            ]
            matching_unsatisfied = [
                key
                for key in unsatisfied_keys
                if _coordinate_target_keys_match(target_key, key)
            ]
            guard_applies = bool(
                len(unsatisfied_keys) != 1 or not matching_unsatisfied
            )
            diag["target_commitment_single_no_score_alternative_probe"] = {
                **dict(diag["target_commitment_single_no_score_alternative_probe"]),
                "single_remaining_target_guard_enabled": True,
                "single_remaining_target_guard_applied": bool(guard_applies),
                "unsatisfied_target_keys": list(unsatisfied_keys),
                "block_reason": (
                    "single_no_score_alternative_not_single_remaining_target"
                    if guard_applies
                    else ""
                ),
            }
            if guard_applies:
                diag["target_commitment"]["block_reason"] = (
                    "single_no_score_alternative_not_single_remaining_target"
                )
                diag["call_gate"] = {
                    **dict(diag["call_gate"]),
                    "block_reason": (
                        "single_no_score_alternative_not_single_remaining_target"
                    ),
                }
                return None, diag
        verification = verify_coordinate_hypothesis(
            packet,
            self._coordinate_hypothesis_default_hypothesis(),
            current_state_hash=current_hash,
        )
        primary_verification_dict = verification.to_dict()
        candidate_sites_before_attempted_filter = list(getattr(verification, "candidate_sites", ()) or ())
        candidate_sites = list(candidate_sites_before_attempted_filter)
        candidate_sites, post_score1_positive_delta_guard_diag = (
            self._coordinate_hypothesis_post_score1_immediate_positive_delta_guard(
                verification,
                candidate_sites,
                preferred_target_keys=[target_key],
                source="coordinate_target_commitment",
            )
        )
        should_defer_handoff, score_bearing_handoff_defer_diag = (
            self._coordinate_hypothesis_target_commitment_score_bearing_handoff_defer(
                verification,
                candidate_sites,
                target_key=target_key,
                progress_kind=progress_kind,
                attempt_count=attempt_count,
            )
        )
        if should_defer_handoff:
            diag["primary_verification"] = primary_verification_dict
            diag["verification"] = verification.to_dict()
            diag["post_score1_immediate_positive_delta_guard"] = (
                post_score1_positive_delta_guard_diag
            )
            diag["target_commitment_score_bearing_handoff_defer"] = (
                score_bearing_handoff_defer_diag
            )
            diag["target_commitment"]["block_reason"] = (
                "score_bearing_handoff_defer"
            )
            diag["call_gate"] = {
                **dict(diag["call_gate"]),
                "block_reason": "score_bearing_handoff_defer",
            }
            return None, diag
        candidate_sites, immediate_target_match_guard_diag = (
            self._coordinate_hypothesis_target_commitment_immediate_target_match_guard(
                verification,
                candidate_sites,
                target_key=target_key,
                progress_kind=progress_kind,
            )
        )
        requested_rank_enabled = bool(
            self._coordinate_hypothesis_target_commitment_requested_target_rank_enabled()
        )
        requested_rank_eligible = bool(progress_kind == "satisfied_target_handoff")
        requested_overlap_rank_diag: dict[str, Any] = {
            "enabled": bool(requested_rank_enabled),
            "eligible": bool(requested_rank_eligible),
            "applied": False,
            "block_reason": (
                "target_commitment_requested_target_rank_disabled"
                if not requested_rank_enabled
                else "not_satisfied_target_handoff"
            ),
        }
        requested_score_precondition_rank_diag: dict[str, Any] = dict(
            requested_overlap_rank_diag
        )
        requested_completion_preflight_rank_diag: dict[str, Any] = dict(
            requested_overlap_rank_diag
        )
        if requested_rank_enabled and requested_rank_eligible:
            candidate_sites, requested_overlap_rank_diag = (
                self._coordinate_hypothesis_requested_target_overlap_rank(
                    verification,
                    candidate_sites,
                    preferred_target_keys=[target_key],
                )
            )
            requested_overlap_rank_diag["eligible"] = True
            candidate_sites, requested_score_precondition_rank_diag = (
                self._coordinate_hypothesis_requested_target_score_precondition_rank(
                    verification,
                    candidate_sites,
                    preferred_target_keys=[target_key],
                )
            )
            requested_score_precondition_rank_diag["eligible"] = True
            candidate_sites, requested_completion_preflight_rank_diag = (
                self._coordinate_hypothesis_requested_target_completion_preflight_rank(
                    verification,
                    candidate_sites,
                    preferred_target_keys=[target_key],
                )
            )
            requested_completion_preflight_rank_diag["eligible"] = True
        site_diversity_enabled = bool(
            self._coordinate_hypothesis_target_commitment_site_diversity_enabled()
        )
        skipped_recent_sites: list[tuple[int, int]] = []
        if site_diversity_enabled and len(candidate_sites) > 1:
            recent_sites: set[tuple[int, int]] = set()
            for key in ("last_selected_site", "last_progress_site"):
                raw_site = commitment.get(key)
                if isinstance(raw_site, (list, tuple)) and len(raw_site) >= 2:
                    try:
                        recent_sites.add((int(raw_site[0]), int(raw_site[1])))
                    except (TypeError, ValueError):
                        continue
            if recent_sites:
                filtered_sites = [
                    site for site in candidate_sites if (int(site[0]), int(site[1])) not in recent_sites
                ]
                if filtered_sites:
                    skipped_recent_sites = [
                        site for site in candidate_sites if (int(site[0]), int(site[1])) in recent_sites
                    ]
                    candidate_sites = filtered_sites
        if single_no_score_alternative_max_attempts_eligible:
            no_score_sites: set[tuple[int, int]] = set()
            for raw_site in single_no_score_nonpositive_target_sites:
                if not isinstance(raw_site, (list, tuple)) or len(raw_site) < 2:
                    continue
                try:
                    no_score_sites.add((int(raw_site[0]), int(raw_site[1])))
                except (TypeError, ValueError):
                    continue
            selected_before_filter = (
                [
                    int(candidate_sites[0][0]),
                    int(candidate_sites[0][1]),
                ]
                if candidate_sites
                and isinstance(candidate_sites[0], (list, tuple))
                and len(candidate_sites[0]) >= 2
                else []
            )
            candidate_count_before_single_filter = int(len(candidate_sites))
            filtered_sites = [
                site
                for site in candidate_sites
                if (int(site[0]), int(site[1])) not in no_score_sites
            ]
            filtered_no_score_candidate_count = int(
                candidate_count_before_single_filter - len(filtered_sites)
            )
            if filtered_sites:
                candidate_sites = filtered_sites
            else:
                candidate_sites = []
            selected_after_filter = (
                [
                    int(candidate_sites[0][0]),
                    int(candidate_sites[0][1]),
                ]
                if candidate_sites
                and isinstance(candidate_sites[0], (list, tuple))
                and len(candidate_sites[0]) >= 2
                else []
            )
            diag["target_commitment_single_no_score_alternative_probe"] = {
                **dict(diag["target_commitment_single_no_score_alternative_probe"]),
                "applied": bool(candidate_sites),
                "candidate_count_before_filter": int(
                    candidate_count_before_single_filter
                ),
                "candidate_count_after_filter": int(len(candidate_sites)),
                "selected_site_before_filter": list(selected_before_filter),
                "selected_site_after_filter": list(selected_after_filter),
                "filtered_no_score_site_count": int(filtered_no_score_candidate_count),
                "block_reason": (
                    "" if filtered_sites else "single_no_score_alternative_no_fresh_candidate"
                ),
            }
        if selected_site := (candidate_sites[0] if candidate_sites else None):
            pass
        elif single_no_score_alternative_max_attempts_eligible:
            diag["target_commitment"]["block_reason"] = (
                "single_no_score_alternative_no_fresh_candidate"
            )
            diag["call_gate"] = {
                **dict(diag["call_gate"]),
                "block_reason": "single_no_score_alternative_no_fresh_candidate",
            }
            return None, diag
        elif lock_replan_enabled:
            fallback_focus = self._coordinate_hypothesis_group_focus_payload_from_packet(packet)
            locked_canvas_ids = [
                str(value or "")
                for value in list(fallback_focus.get("locked_satisfied_canvas_ids") or [])
                if str(value or "")
            ]
            preferred_targets = [
                str(value or "")
                for value in list(fallback_focus.get("preferred_target_keys") or [])
                if str(value or "")
            ]
            diag["satisfied_pair_lock_replan"] = {
                **dict(diag["satisfied_pair_lock_replan"]),
                "eligible": bool(locked_canvas_ids and preferred_targets),
                "locked_satisfied_canvas_id_count": int(len(locked_canvas_ids)),
            }
            if locked_canvas_ids and preferred_targets:
                fallback_context = dict(packet.get("eca_only_context") or {})
                fallback_context["coordinate_group_focus"] = {
                    **dict(fallback_focus),
                    "source": "coordinate_target_commitment_satisfied_pair_lock_replan",
                    "strict_preferred_targets": False,
                    "terminal_execution_order_canvas_safety_enabled": bool(
                        self._coordinate_hypothesis_terminal_execution_order_canvas_safety_enabled()
                    ),
                    "terminal_joint_action_budget_guard_enabled": bool(
                        self._coordinate_hypothesis_terminal_joint_action_budget_guard_enabled()
                    ),
                    "terminal_joint_single_target_after_score_guard_enabled": bool(
                        self._coordinate_hypothesis_terminal_joint_single_target_after_score_guard_enabled()
                    ),
                    **self._coordinate_hypothesis_terminal_joint_single_target_after_score_ceiling_payload(),
                    "terminal_completion_coverage_guard_enabled": bool(
                        self._coordinate_hypothesis_terminal_completion_coverage_guard_enabled()
                    ),
                    "terminal_completion_best_incomplete_telemetry_enabled": bool(
                        self._coordinate_hypothesis_terminal_completion_best_incomplete_telemetry_enabled()
                    ),
                    "terminal_completion_best_incomplete_fallback_enabled": bool(
                        self._coordinate_hypothesis_terminal_completion_best_incomplete_fallback_enabled()
                    ),
                    "terminal_completion_best_incomplete_min_coverage": int(
                        self._coordinate_hypothesis_terminal_completion_best_incomplete_min_coverage()
                    ),
                    "terminal_completion_best_incomplete_fallback_application_count": int(
                        self._coordinate_hypothesis_terminal_best_incomplete_fallback_applied_count
                    ),
                    "terminal_completion_best_incomplete_max_applications": int(
                        self._coordinate_hypothesis_terminal_completion_best_incomplete_max_applications()
                    ),
                    **self._coordinate_hypothesis_terminal_structured_action_budget_payload(
                        records_count=records_count
                    ),
                }
                fallback_context["coordinate_target_preselection"] = {
                    "enabled": bool(self._coordinate_hypothesis_target_preselection_enabled()),
                    "source": "coordinate_target_commitment_satisfied_pair_lock_replan",
                }
                if self._coordinate_hypothesis_provider_immediate_flood_guard_enabled():
                    fallback_context["coordinate_immediate_candidate_flood_guard"] = {
                        "enabled": True,
                        "threshold": int(
                            self._coordinate_hypothesis_provider_immediate_flood_threshold()
                        ),
                        "source": "coordinate_target_commitment_satisfied_pair_lock_replan",
                    }
                fallback_packet = dict(packet)
                fallback_packet["eca_only_context"] = fallback_context
                fallback_verification = verify_coordinate_hypothesis(
                    fallback_packet,
                    self._coordinate_hypothesis_default_hypothesis(),
                    current_state_hash=current_hash,
                )
                fallback_candidates = list(
                    getattr(fallback_verification, "candidate_sites", ()) or ()
                )
                diag["satisfied_pair_lock_replan"] = {
                    **dict(diag["satisfied_pair_lock_replan"]),
                    "fallback_candidate_count": int(len(fallback_candidates)),
                    "fallback_verification": fallback_verification.to_dict(),
                }
                if fallback_candidates:
                    verification = fallback_verification
                    candidate_sites_before_attempted_filter = list(fallback_candidates)
                    candidate_sites = list(fallback_candidates)
                    selected_site = candidate_sites[0]
                    skipped_recent_sites = []
                    diag["satisfied_pair_lock_replan"] = {
                        **dict(diag["satisfied_pair_lock_replan"]),
                        "applied": True,
                        "block_reason": "",
                    }
                else:
                    diag["satisfied_pair_lock_replan"] = {
                        **dict(diag["satisfied_pair_lock_replan"]),
                        "block_reason": "fallback_no_candidate",
                    }
            else:
                diag["satisfied_pair_lock_replan"] = {
                    **dict(diag["satisfied_pair_lock_replan"]),
                    "block_reason": "no_locked_canvas_or_preferred_target",
                }
        else:
            selected_site = None
        diag["primary_verification"] = primary_verification_dict
        diag["verification"] = verification.to_dict()
        diag["post_score1_immediate_positive_delta_guard"] = (
            post_score1_positive_delta_guard_diag
        )
        diag["target_commitment_score_bearing_handoff_defer"] = (
            score_bearing_handoff_defer_diag
        )
        diag["target_commitment_immediate_target_match_guard"] = (
            immediate_target_match_guard_diag
        )
        diag["requested_target_overlap_rank"] = requested_overlap_rank_diag
        diag["requested_target_score_precondition_rank"] = (
            requested_score_precondition_rank_diag
        )
        diag["requested_target_completion_preflight_rank"] = (
            requested_completion_preflight_rank_diag
        )
        diag["attempted_site_suppression_enabled"] = False
        diag["target_commitment_site_diversity_enabled"] = bool(site_diversity_enabled)
        diag["target_commitment_recent_sites_skipped_count"] = int(len(skipped_recent_sites))
        diag["target_commitment_recent_sites_skipped"] = [
            [int(site[0]), int(site[1])] for site in skipped_recent_sites[:8]
        ]
        diag["attempted_site_count_before_choice"] = int(len(self._coordinate_hypothesis_attempted_sites))
        diag["candidate_sites_before_attempted_filter_count"] = int(
            len(candidate_sites_before_attempted_filter)
        )
        diag["candidate_sites_suppressed_attempted_count"] = 0
        diag["candidate_sites_generated_from_hypothesis_count"] = int(len(candidate_sites))
        diag["candidate_sites_contains_selected_site"] = bool(selected_site in candidate_sites)
        if selected_site is None:
            diag["target_commitment"]["block_reason"] = "no_fresh_commitment_candidate"
            diag["call_gate"] = {
                **dict(diag["call_gate"]),
                "block_reason": "no_fresh_commitment_candidate",
            }
            return None, diag
        preconditioning_observation = (
            self._coordinate_hypothesis_target_commitment_preconditioning_observation(
                verification,
                selected_site,
                target_key=target_key,
                progress_kind=progress_kind,
                attempt_count=attempt_count,
            )
        )
        should_defer_preconditioning_repeat, preconditioning_repeat_defer_diag = (
            self._coordinate_hypothesis_target_commitment_preconditioning_repeat_defer(
                preconditioning_observation
            )
        )
        diag["target_commitment_preconditioning_observation"] = (
            preconditioning_observation
        )
        structured_fallback_choice, preconditioning_structured_fallback_diag = (
            self._coordinate_hypothesis_target_commitment_preconditioning_structured_fallback(
                packet,
                preconditioning_observation,
                current_hash=current_hash,
                records_count=records_count,
                target_key=target_key,
            )
        )
        diag["target_commitment_preconditioning_structured_fallback"] = (
            preconditioning_structured_fallback_diag
        )
        if structured_fallback_choice is not None:
            fallback_selected_site = list(
                structured_fallback_choice.get("selected_site") or []
            )
            commitment["attempt_count"] = int(attempt_count) + 1
            if len(fallback_selected_site) >= 2:
                commitment["last_selected_site"] = [
                    int(fallback_selected_site[0]),
                    int(fallback_selected_site[1]),
                ]
            if pause_exception_allowed:
                commitment["pause_exception_used"] = True
                commitment["pause_exception_reason"] = str(
                    pause_exception_diag.get("reason", "") or ""
                )
            self._coordinate_hypothesis_target_commitment = dict(commitment)
            diag["choice_generated"] = True
            diag["selected_site"] = [
                int(fallback_selected_site[0]),
                int(fallback_selected_site[1]),
            ]
            diag["candidate_sites_generated_from_hypothesis_count"] = int(
                preconditioning_structured_fallback_diag.get("candidate_count", 0)
                or 0
            )
            diag["candidate_sites_contains_selected_site"] = True
            diag["attempted_site_count_after_choice"] = int(
                len(self._coordinate_hypothesis_attempted_sites)
            )
            diag["protected_plan_site_count"] = int(
                preconditioning_structured_fallback_diag.get(
                    "protected_plan_site_count", 0
                )
                or 0
            )
            diag["protected_plan_remaining_site_count"] = int(
                preconditioning_structured_fallback_diag.get(
                    "protected_plan_remaining_site_count", 0
                )
                or 0
            )
            diag["target_commitment"] = {
                **dict(diag["target_commitment"]),
                "applied": True,
                "attempt_count_after": int(commitment["attempt_count"]),
                "selected_site": [
                    int(fallback_selected_site[0]),
                    int(fallback_selected_site[1]),
                ],
                "resolved_target_key": str(
                    structured_fallback_choice.get("coordinate_target_key", "")
                    or target_key
                ),
                "route": "preconditioning_structured_fallback",
            }
            diag["call_gate"] = {
                **dict(diag["call_gate"]),
                "allowed": True,
                "block_reason": "preconditioning_structured_fallback",
                "pause_exception_applied": bool(pause_exception_allowed),
            }
            diag["target_commitment_pause_exception"] = {
                **dict(diag["target_commitment_pause_exception"]),
                "applied": bool(pause_exception_allowed),
            }
            return structured_fallback_choice, diag
        diag["target_commitment_preconditioning_repeat_defer"] = (
            preconditioning_repeat_defer_diag
        )
        if should_defer_preconditioning_repeat:
            diag["target_commitment"]["block_reason"] = "preconditioning_repeat_defer"
            diag["call_gate"] = {
                **dict(diag["call_gate"]),
                "block_reason": "preconditioning_repeat_defer",
            }
            return None, diag
        protected_plan_sites = self._coordinate_hypothesis_execution_sites_from_verification(verification)
        best_incomplete_fallback_applied = (
            self._coordinate_hypothesis_best_incomplete_fallback_applied_from_verification(
                verification
            )
        )
        coordinate_target_key = self._coordinate_hypothesis_target_key_from_verification(
            verification,
            selected_site=selected_site,
        )
        coordinate_target_keys = self._coordinate_hypothesis_target_keys_from_verification(
            verification,
            selected_site=selected_site,
        )
        selected_site_key = (int(selected_site[0]), int(selected_site[1]))
        if protected_plan_sites and protected_plan_sites[0] == selected_site_key:
            protected_plan_remaining_sites = protected_plan_sites[1:]
        else:
            protected_plan_sites = []
            protected_plan_remaining_sites = []
        detour_metadata = (
            self._coordinate_hypothesis_self_overlap_detour_metadata_from_verification(
                verification
            )
        )
        current_components = [
            row for row in list(packet.get("components") or []) if isinstance(row, Mapping)
        ]
        current_snapshot = self._coordinate_hypothesis_relation_snapshot_from_components(
            current_components
        )
        selected_target_key_for_guard = str(coordinate_target_key or target_key)
        guard_satisfied_keys = [
            str(key or "")
            for key in list(current_snapshot.get("satisfied_target_keys") or [])
            if str(key or "")
        ]
        guard_unsatisfied_keys = [
            str(key or "")
            for key in list(current_snapshot.get("unsatisfied_target_keys") or [])
            if str(key or "")
        ]
        guard_remaining_keys = (
            self._coordinate_hypothesis_satisfied_target_churn_remaining_keys(
                selected_target_key=selected_target_key_for_guard,
                satisfied_target_keys=guard_satisfied_keys,
                unsatisfied_target_keys=guard_unsatisfied_keys,
            )
        )
        guard_score_evidence_count = (
            self._coordinate_hypothesis_target_score_evidence_count(
                selected_target_key_for_guard
            )
        )
        guard_prior_observation_count = sum(
            1
            for row in self._coordinate_hypothesis_satisfied_target_churn_events
            if str(row.get("source", "") or "") == "target_commitment_update_sensor"
            and _coordinate_target_keys_match(
                selected_target_key_for_guard,
                str(row.get("selected_target_key", "") or ""),
            )
        )
        guard_min_observations = (
            self._coordinate_hypothesis_target_commitment_satisfied_target_churn_guard_min_observations()
        )
        satisfied_target_churn_guard = {
            "enabled": bool(
                self._coordinate_hypothesis_target_commitment_satisfied_target_churn_guard_enabled()
            ),
            "applied": False,
            "selected_target_key": str(selected_target_key_for_guard),
            "target_already_satisfied": bool(guard_remaining_keys),
            "remaining_unsatisfied_target_keys": list(guard_remaining_keys),
            "protected_plan_site_count": int(len(protected_plan_sites)),
            "positive_score_evidence_count": int(guard_score_evidence_count),
            "prior_observation_count": int(guard_prior_observation_count),
            "min_observations": int(guard_min_observations),
            "block_reason": "",
        }
        diag["satisfied_target_churn_guard"] = satisfied_target_churn_guard
        if (
            bool(satisfied_target_churn_guard["enabled"])
            and guard_remaining_keys
            and int(guard_prior_observation_count) >= int(guard_min_observations)
            and (
                not protected_plan_sites
                or int(guard_score_evidence_count) <= 0
            )
        ):
            block_reason = (
                "satisfied_target_churn_without_protected_plan"
                if not protected_plan_sites
                else "satisfied_target_churn_without_score_evidence"
            )
            satisfied_target_churn_guard["applied"] = True
            satisfied_target_churn_guard["block_reason"] = block_reason
            diag["satisfied_target_churn_guard"] = satisfied_target_churn_guard
            event = {
                "source": "target_commitment_choice",
                "step": int(records_count),
                "selected_site": [int(selected_site[0]), int(selected_site[1])],
                "selected_target_key": str(selected_target_key_for_guard),
                "remaining_unsatisfied_target_keys": list(guard_remaining_keys),
                "protected_plan_site_count": int(len(protected_plan_sites)),
                "positive_score_evidence_count": int(guard_score_evidence_count),
                "prior_observation_count": int(guard_prior_observation_count),
                "min_observations": int(guard_min_observations),
                "block_reason": block_reason,
            }
            self._record_coordinate_hypothesis_satisfied_target_churn_event(event)
            self._coordinate_hypothesis_target_commitment.clear()
            diag["target_commitment"]["block_reason"] = block_reason
            diag["call_gate"] = {
                **dict(diag["call_gate"]),
                "block_reason": block_reason,
            }
            return None, diag
        self._coordinate_hypothesis_attempted_sites.add((int(selected_site[0]), int(selected_site[1])))
        diag["attempted_site_count_after_choice"] = int(len(self._coordinate_hypothesis_attempted_sites))
        commitment["attempt_count"] = int(attempt_count) + 1
        commitment["last_selected_site"] = [int(selected_site[0]), int(selected_site[1])]
        if pause_exception_allowed:
            commitment["pause_exception_used"] = True
            commitment["pause_exception_reason"] = str(pause_exception_diag.get("reason", "") or "")
        self._coordinate_hypothesis_target_commitment = dict(commitment)
        diag["choice_generated"] = True
        diag["selected_site"] = [int(selected_site[0]), int(selected_site[1])]
        diag["protected_plan_site_count"] = int(len(protected_plan_sites))
        diag["protected_plan_remaining_site_count"] = int(len(protected_plan_remaining_sites))
        diag["terminal_self_overlap_detour"] = dict(detour_metadata)
        diag["target_commitment"] = {
            **dict(diag["target_commitment"]),
            "applied": True,
            "attempt_count_after": int(commitment["attempt_count"]),
            "selected_site": [int(selected_site[0]), int(selected_site[1])],
            "resolved_target_key": str(coordinate_target_key or target_key),
        }
        diag["call_gate"] = {
            **dict(diag["call_gate"]),
            "allowed": True,
            "block_reason": "",
            "pause_exception_applied": bool(pause_exception_allowed),
        }
        diag["target_commitment_pause_exception"] = {
            **dict(diag["target_commitment_pause_exception"]),
            "applied": bool(pause_exception_allowed),
        }
        diag["target_commitment_preconditioning_observation"] = (
            preconditioning_observation
        )
        diag["target_commitment_preconditioning_repeat_defer"] = (
            preconditioning_repeat_defer_diag
        )
        choice = {
            "primitive_id": "coordinate_hypothesis_target_commitment",
            "step": ("ACTION6", {"x": int(selected_site[0]), "y": int(selected_site[1])}),
            "reason": (
                "coordinate_hypothesis_target_commitment continued an ECA-observed "
                "coordinate target after prior progress without another provider call"
            ),
            "selected_site": [int(selected_site[0]), int(selected_site[1])],
            "candidate_count": int(len(candidate_sites)),
            "hypothesis": self._coordinate_hypothesis_default_hypothesis(),
            "protected_plan_sites": [
                [int(site[0]), int(site[1])] for site in protected_plan_sites
            ],
            "protected_plan_remaining_sites": [
                [int(site[0]), int(site[1])] for site in protected_plan_remaining_sites
            ],
            "coordinate_target_key": str(coordinate_target_key or target_key),
            "coordinate_target_keys": list(coordinate_target_keys or [coordinate_target_key or target_key]),
            "terminal_completion_best_incomplete_fallback_applied": bool(
                best_incomplete_fallback_applied
            ),
            "terminal_self_overlap_detour_used": bool(detour_metadata.get("used")),
            "terminal_self_overlap_detour_count": int(
                detour_metadata.get("count", 0) or 0
            ),
            "terminal_self_overlap_detour": dict(detour_metadata.get("detour") or {}),
            "target_commitment_single_no_score_alternative_probe_applied": bool(
                diag.get("target_commitment_single_no_score_alternative_probe", {}).get(
                    "bypassed_max_attempts"
                )
            ),
            "target_commitment_single_no_score_alternative_probe": dict(
                diag.get("target_commitment_single_no_score_alternative_probe") or {}
            ),
            "target_commitment_preconditioning_observation": dict(
                preconditioning_observation
            ),
        }
        return choice, diag

    def _start_coordinate_hypothesis_plan_lease(self, choice: Mapping[str, Any]) -> None:
        self._active_coordinate_hypothesis_plan.clear()
        self._active_coordinate_hypothesis_plan_context.clear()
        raw_remaining = choice.get("protected_plan_remaining_sites")
        if not isinstance(raw_remaining, (list, tuple)):
            return
        remaining: list[tuple[int, int]] = []
        for raw_site in raw_remaining:
            if not isinstance(raw_site, (list, tuple)) or len(raw_site) < 2:
                continue
            try:
                remaining.append((int(raw_site[0]), int(raw_site[1])))
            except (TypeError, ValueError):
                continue
        if not remaining:
            return
        self._coordinate_hypothesis_next_plan_id += 1
        plan_id = int(self._coordinate_hypothesis_next_plan_id)
        if isinstance(choice, dict):
            choice["coordinate_plan_id"] = int(plan_id)
            choice["coordinate_plan_step_index"] = 0
            choice["coordinate_plan_remaining_after"] = int(len(remaining))
        self._active_coordinate_hypothesis_plan.extend(remaining)
        self._active_coordinate_hypothesis_plan_context = {
            "plan_id": int(plan_id),
            "hypothesis": dict(choice.get("hypothesis") or {}),
            "candidate_count": int(choice.get("candidate_count", 0) or 0),
            "origin_site": list(choice.get("selected_site") or []),
            "protected_plan_site_count": int(
                len(choice.get("protected_plan_sites") or [])
            ),
            "executed_count": 0,
            "coordinate_target_key": str(choice.get("coordinate_target_key", "") or ""),
            "coordinate_target_keys": [
                str(key or "")
                for key in list(choice.get("coordinate_target_keys") or [])
                if str(key or "")
            ],
            "target_commitment_preconditioning_structured_fallback_applied": bool(
                choice.get("target_commitment_preconditioning_structured_fallback_applied")
            ),
            "target_commitment_preconditioning_structured_fallback_selected_target_key": str(
                choice.get(
                    "target_commitment_preconditioning_structured_fallback_selected_target_key",
                    "",
                )
                or ""
            ),
            "target_commitment_preconditioning_structured_fallback_single_piece": bool(
                choice.get("target_commitment_preconditioning_structured_fallback_single_piece")
            ),
            "single_piece_target_family_outcome_probe_applied": bool(
                choice.get("single_piece_target_family_outcome_probe_applied")
            ),
            "single_piece_target_family_outcome_probe_route_key": str(
                choice.get("single_piece_target_family_outcome_probe_route_key", "")
                or ""
            ),
            "single_piece_target_family_outcome_probe_route_sites": [
                [int(site[0]), int(site[1])]
                for site in list(
                    choice.get("single_piece_target_family_outcome_probe_route_sites")
                    or []
                )
                if isinstance(site, (list, tuple)) and len(site) >= 2
            ],
            "terminal_completion_best_incomplete_fallback_applied": bool(
                choice.get("terminal_completion_best_incomplete_fallback_applied")
            ),
            "terminal_completion_best_incomplete_fallback_application_count_after": int(
                choice.get(
                    "terminal_completion_best_incomplete_fallback_application_count_after",
                    0,
                )
                or 0
            ),
            "terminal_completion_best_incomplete_fallback_provider_cooldown_started": bool(
                choice.get(
                    "terminal_completion_best_incomplete_fallback_provider_cooldown_started"
                )
            ),
            "terminal_completion_best_incomplete_fallback_provider_cooldown_steps": int(
                choice.get(
                    "terminal_completion_best_incomplete_fallback_provider_cooldown_steps",
                    0,
                )
                or 0
            ),
            "terminal_self_overlap_detour_used": bool(
                choice.get("terminal_self_overlap_detour_used")
            ),
            "terminal_self_overlap_detour_count": int(
                choice.get("terminal_self_overlap_detour_count", 0) or 0
            ),
            "terminal_self_overlap_detour": dict(
                choice.get("terminal_self_overlap_detour") or {}
            ),
        }

    def _coordinate_hypothesis_plan_lease_choice(
        self,
        *,
        available_actions: set[str],
        blocked_by_stable_solver: bool,
        stable_solver_reasons: list[str],
    ) -> tuple[dict[str, Any] | None, dict[str, Any]]:
        active_count = int(len(self._active_coordinate_hypothesis_plan))
        enabled = bool(self._coordinate_hypothesis_lane_enabled())
        block_reason = ""
        if not enabled:
            block_reason = "disabled"
        elif "ACTION6" not in available_actions:
            block_reason = "action6_unavailable"
        elif active_count <= 0:
            block_reason = "no_active_coordinate_plan_lease"
        elif bool(blocked_by_stable_solver):
            block_reason = "stable_solver_available"
        diag: dict[str, Any] = {
            "enabled": bool(enabled),
            "provider_available": bool(self.coordinate_hypothesis_bridge.provider is not None),
            "provider_called": False,
            "choice_generated": False,
            "selected_site": [],
            "candidate_sites_generated_from_hypothesis_count": 0,
            "candidate_sites_contains_selected_site": False,
            "direct_llm_action_blocked_count": 0,
            "plan_lease": {
                "active": bool(active_count > 0),
                "applied": False,
                "remaining_before": int(active_count),
                "remaining_after": int(active_count),
                "executed_count_before": int(
                    self._coordinate_hypothesis_plan_lease_executed_count
                ),
                "context": dict(self._active_coordinate_hypothesis_plan_context),
            },
            "preflight": {
                "enabled": False,
                "passed": None,
                "block_reason": "not_required_for_active_coordinate_plan_lease",
            },
            "call_gate": {
                "configured_enabled": bool(enabled),
                "allowed": not bool(block_reason),
                "block_reason": block_reason,
                "records_count": int(self.records_count),
                "min_records": int(self._coordinate_hypothesis_min_records()),
                "max_calls": self._coordinate_hypothesis_max_calls(),
                "provider_call_count_before": int(self._coordinate_hypothesis_provider_call_count),
                "provider_call_count_after": int(self._coordinate_hypothesis_provider_call_count),
                "score_success_count": int(self._coordinate_hypothesis_score_success_count),
                "stable_solver_reasons": list(stable_solver_reasons),
            },
        }
        if block_reason:
            return None, diag
        site = self._active_coordinate_hypothesis_plan.popleft()
        self._coordinate_hypothesis_attempted_sites.add((int(site[0]), int(site[1])))
        self._coordinate_hypothesis_plan_lease_executed_count += 1
        diag["choice_generated"] = True
        diag["selected_site"] = [int(site[0]), int(site[1])]
        diag["candidate_sites_generated_from_hypothesis_count"] = int(active_count)
        diag["candidate_sites_contains_selected_site"] = True
        diag["attempted_site_count_after_choice"] = int(
            len(self._coordinate_hypothesis_attempted_sites)
        )
        diag["plan_lease"] = {
            **dict(diag["plan_lease"]),
            "applied": True,
            "remaining_after": int(len(self._active_coordinate_hypothesis_plan)),
            "executed_count_after": int(self._coordinate_hypothesis_plan_lease_executed_count),
        }
        context = dict(self._active_coordinate_hypothesis_plan_context)
        step_index = int(context.get("executed_count", 0) or 0) + 1
        context["executed_count"] = int(step_index)
        self._active_coordinate_hypothesis_plan_context = dict(context)
        choice = {
            "primitive_id": "coordinate_hypothesis_plan_lease",
            "step": ("ACTION6", {"x": int(site[0]), "y": int(site[1])}),
            "reason": (
                "coordinate_hypothesis_plan_lease continued an ECA-verified "
                "coordinate relation protected plan without a provider call"
            ),
            "selected_site": [int(site[0]), int(site[1])],
            "candidate_count": int(context.get("candidate_count", active_count) or active_count),
            "hypothesis": dict(context.get("hypothesis") or {}),
            "coordinate_plan_id": int(context.get("plan_id", 0) or 0),
            "coordinate_plan_step_index": int(step_index),
            "coordinate_plan_remaining_after": int(len(self._active_coordinate_hypothesis_plan)),
            "coordinate_target_key": str(context.get("coordinate_target_key", "") or ""),
            "coordinate_target_keys": [
                str(key or "")
                for key in list(context.get("coordinate_target_keys") or [])
                if str(key or "")
            ],
            "target_commitment_preconditioning_structured_fallback_applied": bool(
                context.get("target_commitment_preconditioning_structured_fallback_applied")
            ),
            "target_commitment_preconditioning_structured_fallback_selected_target_key": str(
                context.get(
                    "target_commitment_preconditioning_structured_fallback_selected_target_key",
                    "",
                )
                or ""
            ),
            "target_commitment_preconditioning_structured_fallback_single_piece": bool(
                context.get("target_commitment_preconditioning_structured_fallback_single_piece")
            ),
            "single_piece_target_family_outcome_probe_applied": bool(
                context.get("single_piece_target_family_outcome_probe_applied")
            ),
            "single_piece_target_family_outcome_probe_route_key": str(
                context.get("single_piece_target_family_outcome_probe_route_key", "")
                or ""
            ),
            "single_piece_target_family_outcome_probe_route_sites": [
                [int(site[0]), int(site[1])]
                for site in list(
                    context.get("single_piece_target_family_outcome_probe_route_sites")
                    or []
                )
                if isinstance(site, (list, tuple)) and len(site) >= 2
            ],
            "terminal_completion_best_incomplete_fallback_applied": bool(
                context.get("terminal_completion_best_incomplete_fallback_applied")
            ),
            "terminal_completion_best_incomplete_fallback_application_count_after": int(
                context.get(
                    "terminal_completion_best_incomplete_fallback_application_count_after",
                    0,
                )
                or 0
            ),
            "terminal_completion_best_incomplete_fallback_provider_cooldown_started": False,
            "terminal_completion_best_incomplete_fallback_provider_cooldown_steps": 0,
            "terminal_self_overlap_detour_used": bool(
                context.get("terminal_self_overlap_detour_used")
            ),
            "terminal_self_overlap_detour_count": int(
                context.get("terminal_self_overlap_detour_count", 0) or 0
            ),
            "terminal_self_overlap_detour": dict(
                context.get("terminal_self_overlap_detour") or {}
            ),
        }
        return choice, diag

    def _mechanic_hypothesis_posterior_enabled(self) -> bool:
        raw = str(os.environ.get("ECA_ENABLE_MECHANIC_HYPOTHESIS_POSTERIOR", "") or "").strip().lower()
        return raw in {"1", "true", "yes", "on"}

    def _mechanic_hypothesis_goal_candidate_plan_enabled(self) -> bool:
        raw = str(os.environ.get("ECA_ENABLE_MECHANIC_HYPOTHESIS_GOAL_CANDIDATE_PLAN", "") or "").strip().lower()
        return raw in {"1", "true", "yes", "on"}

    def _unknown_affordance_goal_link_handoff_enabled(self) -> bool:
        raw = str(os.environ.get("ECA_ENABLE_UNKNOWN_AFFORDANCE_GOAL_LINK_HANDOFF", "") or "").strip().lower()
        return raw in {"1", "true", "yes", "on"}

    def _unknown_affordance_continuation_refresh_enabled(self) -> bool:
        raw = str(
            os.environ.get("ECA_ENABLE_UNKNOWN_AFFORDANCE_CONTINUATION_REFRESH", "")
            or ""
        ).strip().lower()
        return raw in {"1", "true", "yes", "on"}

    def _unknown_affordance_continuation_refresh_max(self) -> int:
        raw = str(os.environ.get("ECA_UNKNOWN_AFFORDANCE_CONTINUATION_MAX", "") or "").strip()
        try:
            value = int(raw)
        except (TypeError, ValueError):
            value = 4
        return max(1, min(12, value))

    def _unknown_affordance_structural_digest_handoff_enabled(self) -> bool:
        raw = str(
            os.environ.get("ECA_ENABLE_UNKNOWN_AFFORDANCE_STRUCTURAL_DIGEST_HANDOFF", "")
            or ""
        ).strip().lower()
        return raw in {"1", "true", "yes", "on"}

    def _unknown_affordance_structural_digest_direction_contrast_enabled(self) -> bool:
        raw = str(
            os.environ.get(
                "ECA_UNKNOWN_AFFORDANCE_STRUCTURAL_DIGEST_ENABLE_DIRECTION_CONTRAST",
                "1",
            )
            or "1"
        ).strip().lower()
        return raw not in {"0", "false", "no", "off"}

    def _unknown_affordance_target_relation_early_handoff_enabled(self) -> bool:
        raw = str(
            os.environ.get(
                "ECA_ENABLE_UNKNOWN_AFFORDANCE_TARGET_RELATION_EARLY_HANDOFF",
                "",
            )
            or ""
        ).strip().lower()
        return raw in {"1", "true", "yes", "on"}

    def _unknown_affordance_target_relation_early_handoff_min(self) -> int:
        raw = str(
            os.environ.get(
                "ECA_UNKNOWN_AFFORDANCE_TARGET_RELATION_EARLY_HANDOFF_MIN_CONTINUATIONS",
                "",
            )
            or ""
        ).strip()
        try:
            value = int(raw)
        except (TypeError, ValueError):
            value = 1
        return max(0, min(12, value))

    def _psa_cycle_goal_link_repaired_abstractions(
        self,
        *,
        frame_arr: np.ndarray,
        current_state_hash: str,
        abstractions: Iterable[PSAAbstraction],
    ) -> tuple[list[PSAAbstraction], dict[str, Any]]:
        items = list(abstractions)
        enabled = self._psa_cycle_goal_link_repair_enabled()
        control_mode = self._psa_cycle_goal_link_repair_control_mode()
        require_evidence_site = self._psa_cycle_goal_link_repair_require_evidence_site()
        enable_direction_contrast = self._psa_cycle_goal_link_repair_enable_direction_contrast()
        allow_symbolic_source = self._psa_cycle_goal_link_repair_allow_symbolic_source()
        symbolic_source_input_count = sum(
            1
            for item in items
            if str(getattr(item, "source_kind", "") or "") in {"psa_induced", "psa_symbolic_induced"}
        )
        llm_source_input_count = sum(
            1
            for item in items
            if str(getattr(item, "source_kind", "") or "") == "psa_llm_proposed"
        )
        summary: dict[str, Any] = {
            "enabled": bool(enabled),
            "control_mode": control_mode,
            "require_evidence_site": bool(require_evidence_site),
            "direction_contrast_enabled": bool(enable_direction_contrast),
            "allow_symbolic_source": bool(allow_symbolic_source),
            "input_count": int(len(items)),
            "symbolic_source_input_count": int(symbolic_source_input_count),
            "llm_source_input_count": int(llm_source_input_count),
            "applied_count": 0,
            "skipped_count": 0,
            "skip_reasons": {},
            "visible_cycle_state_found": False,
            "visible_cycle_state_type": "",
            "evidence_site_match_count": 0,
            "evidence_site_mismatch_count": 0,
            "evidence_site_guided_plan_count": 0,
            "direction_contrast_applied_count": 0,
            "evidence_site_roles": {},
            "selected_site_roles": {},
            "operation_plan_len": 0,
            "control_operation_plan_len": 0,
            "source_kind_after_repair": "",
            "repair_ids": [],
            "goal_link_ids": [],
            "protected_plan_ids": [],
            "control_details": {},
        }
        if not enabled or not items:
            return items, summary
        state_kind = "button_cycle"
        state = _button_cycle_rotation_state(frame_arr)
        if state is None:
            state_kind = "color_cycle"
            state = _color_cycle_constraint_state(frame_arr, role_cache=self._color_cycle_role_cache)
        if state is None:
            summary["skip_reasons"] = {"missing_visible_cycle_state": int(len(items))}
            summary["skipped_count"] = int(len(items))
            return items, summary
        plan = _bounded_plan_from_steps(state.get("operation_plan") or (), max_len=6)
        if not plan:
            summary["skip_reasons"] = {"missing_visible_cycle_operation_plan": int(len(items))}
            summary["skipped_count"] = int(len(items))
            return items, summary
        if state_kind == "button_cycle":
            state, plan, control_details = _button_cycle_repair_control_state_and_plan(
                state,
                plan,
                mode=control_mode,
            )
        else:
            control_details = {"mode": str(control_mode or "").strip().lower()}
        summary["visible_cycle_state_found"] = True
        summary["visible_cycle_state_type"] = state_kind
        summary["operation_plan_len"] = int(len(plan))
        summary["control_operation_plan_len"] = int(len(plan))
        summary["control_details"] = control_details
        repaired: list[PSAAbstraction] = []
        skip_reasons: Counter[str] = Counter()
        for abstraction in items:
            if abstraction.family != "cycle":
                repaired.append(abstraction)
                skip_reasons["unsupported_family"] += 1
                continue
            source_kind = str(abstraction.source_kind or "")
            symbolic_allowed = bool(
                allow_symbolic_source and source_kind in {"psa_induced", "psa_symbolic_induced"}
            )
            if str(abstraction.llm_role or "none") == "none" and not symbolic_allowed:
                repaired.append(abstraction)
                skip_reasons["not_llm_proposed"] += 1
                continue
            if bool(abstraction.llm_direct_action):
                repaired.append(abstraction)
                skip_reasons["llm_direct_action"] += 1
                continue
            repair_state = state
            repair_plan = plan
            if require_evidence_site:
                guided = (
                    _button_cycle_evidence_guided_state_and_plan(
                        state,
                        abstraction=abstraction,
                        max_len=6,
                        enable_direction_contrast=enable_direction_contrast,
                    )
                    if state_kind == "button_cycle"
                    else _color_cycle_evidence_guided_state_and_plan(
                        state,
                        abstraction=abstraction,
                        max_len=6,
                    )
                )
                if guided is None:
                    repaired.append(abstraction)
                    summary["evidence_site_mismatch_count"] = int(summary["evidence_site_mismatch_count"]) + 1
                    skip_reasons["evidence_site_mismatch"] += 1
                    continue
                repair_state, repair_plan = guided
                summary["evidence_site_guided_plan_count"] = int(summary["evidence_site_guided_plan_count"]) + 1
                evidence_role = str(repair_state.get("evidence_site_role", "") or "")
                selected_role = str(repair_state.get("selected_site_role", "") or "")
                if evidence_role:
                    roles = dict(summary["evidence_site_roles"])
                    roles[evidence_role] = int(roles.get(evidence_role, 0)) + 1
                    summary["evidence_site_roles"] = roles
                if selected_role and state_kind != "color_cycle":
                    roles = dict(summary["selected_site_roles"])
                    roles[selected_role] = int(roles.get(selected_role, 0)) + 1
                    summary["selected_site_roles"] = roles
                if str(repair_state.get("operator_direction_source", "") or "") == "goal_link_contrast":
                    summary["direction_contrast_applied_count"] = int(
                        summary["direction_contrast_applied_count"]
                    ) + 1
            if state_kind == "color_cycle":
                repair_state, repair_plan, color_control_details = _color_cycle_repair_control_state_and_plan(
                    repair_state,
                    repair_plan,
                    mode=control_mode,
                )
                control_details = color_control_details
                summary["control_details"] = color_control_details
                summary["control_operation_plan_len"] = int(len(repair_plan))
                selected_role = str(repair_state.get("selected_site_role", "") or "")
                if selected_role:
                    roles = dict(summary["selected_site_roles"])
                    roles[selected_role] = int(roles.get(selected_role, 0)) + 1
                    summary["selected_site_roles"] = roles
            if require_evidence_site:
                summary["evidence_site_match_count"] = int(summary["evidence_site_match_count"]) + 1
            repaired_abstraction = (
                _repair_psa_abstraction_with_button_cycle_goal_link(
                    abstraction,
                    state=repair_state,
                    plan=repair_plan,
                    current_state_hash=current_state_hash,
                    control_mode=control_mode,
                )
                if state_kind == "button_cycle"
                else _repair_psa_abstraction_with_color_cycle_goal_link(
                    abstraction,
                    state=repair_state,
                    plan=repair_plan,
                    current_state_hash=current_state_hash,
                    control_mode=control_mode,
                )
            )
            repaired.append(repaired_abstraction)
            metadata = dict(repaired_abstraction.metadata or {})
            for summary_key, metadata_key in (
                ("repair_ids", "psa_cycle_goal_link_repair_id"),
                ("goal_link_ids", "psa_cycle_goal_link_id"),
                ("protected_plan_ids", "psa_cycle_protected_plan_id"),
            ):
                value = str(metadata.get(metadata_key, "") or "")
                if value:
                    existing = list(summary.get(summary_key) or [])
                    if value not in existing:
                        existing.append(value)
                    summary[summary_key] = existing[-4:]
            summary["applied_count"] = int(summary["applied_count"]) + 1
        summary["skipped_count"] = int(sum(skip_reasons.values()))
        summary["skip_reasons"] = dict(sorted(skip_reasons.items()))
        if int(summary["applied_count"]) > 0:
            summary["source_kind_after_repair"] = "mixed"
        return repaired, summary

    def _psa_structural_goal_link_repaired_abstractions(
        self,
        *,
        frame_arr: np.ndarray,
        current_state_hash: str,
        abstractions: Iterable[PSAAbstraction],
    ) -> tuple[list[PSAAbstraction], dict[str, Any]]:
        items = list(abstractions)
        enabled = self._psa_structural_goal_link_repair_enabled()
        allow_symbolic_source = self._psa_structural_goal_link_repair_allow_symbolic_source()
        summary: dict[str, Any] = {
            "enabled": bool(enabled),
            "allow_symbolic_source": bool(allow_symbolic_source),
            "input_count": int(len(items)),
            "llm_source_input_count": int(
                sum(1 for item in items if str(getattr(item, "source_kind", "") or "") == "psa_llm_proposed")
            ),
            "symbolic_source_input_count": int(
                sum(
                    1
                    for item in items
                    if str(getattr(item, "source_kind", "") or "") in {"psa_induced", "psa_symbolic_induced"}
                )
            ),
            "applied_count": 0,
            "skipped_count": 0,
            "skip_reasons": {},
            "visible_structural_state_found": False,
            "visible_structural_state_type": "",
            "operation_plan_len": 0,
            "source_kind_after_repair": "",
            "selected_repair_target": "",
            "selected_repair_posterior_key": "",
            "candidate_repair_targets": [],
            "posterior_rank_before": [],
            "posterior_rank_after": [],
            "posterior": self._psa_structural_repair_posterior_summary(),
            "repair_ids": [],
            "goal_link_ids": [],
            "protected_plan_ids": [],
        }
        if not enabled or not items:
            return items, summary
        repair_candidates: list[dict[str, Any]] = []
        shape_state = _shape_coverage_paste_state(frame_arr)
        if shape_state is not None:
            shape_plan = _shape_coverage_paste_full_plan(shape_state, set(CORE_ACTION_ORDER))
            if shape_plan:
                repair_candidates.append(
                    {
                        "repair_kind": "shape_coverage",
                        "state": shape_state,
                        "plan_kind": "shape_coverage_paste_full_plan",
                        "plan_actions": shape_plan,
                    }
                )
        axis_state = _axis_reflection_coverage_state(frame_arr)
        if axis_state is not None:
            axis_plan = _axis_reflection_coverage_plan(axis_state, set(CORE_ACTION_ORDER))
            if axis_plan:
                repair_candidates.append(
                    {
                        "repair_kind": "axis_reflection",
                        "state": axis_state,
                        "plan_kind": "axis_reflection_coverage_plan",
                        "plan_actions": axis_plan,
                    }
                )
        summary["candidate_repair_targets"] = [
            str(candidate["repair_kind"]) for candidate in repair_candidates
        ]
        summary["posterior_rank_before"] = self._psa_structural_repair_candidate_rank(
            repair_candidates
        )
        if self._psa_structural_repair_posterior_enabled():
            repair_candidates = sorted(
                enumerate(repair_candidates),
                key=lambda item: (
                    -self._psa_structural_repair_posterior_score(
                        self._psa_structural_repair_posterior_key(
                            str(item[1]["repair_kind"]),
                            str(item[1]["plan_kind"]),
                        )
                    ),
                    item[0],
                ),
            )
            repair_candidates = [item[1] for item in repair_candidates]
        summary["posterior_rank_after"] = self._psa_structural_repair_candidate_rank(
            repair_candidates
        )
        if not repair_candidates:
            summary["skipped_count"] = int(len(items))
            summary["skip_reasons"] = {"missing_structural_state": int(len(items))}
            return items, summary
        selected = repair_candidates[0]
        state = selected["state"]
        plan_actions = list(selected["plan_actions"])
        plan_kind = str(selected["plan_kind"])
        repair_kind = str(selected["repair_kind"])
        repair_posterior_key = self._psa_structural_repair_posterior_key(
            repair_kind,
            plan_kind,
        )
        self._psa_structural_repair_posterior_attempts[repair_posterior_key] += 1
        if not plan_actions:
            summary["skipped_count"] = int(len(items))
            summary["skip_reasons"] = {"missing_structural_plan": int(len(items))}
            return items, summary
        summary["visible_structural_state_found"] = True
        summary["visible_structural_state_type"] = repair_kind
        summary["operation_plan_len"] = int(len(plan_actions))
        summary["selected_repair_target"] = repair_kind
        summary["selected_repair_posterior_key"] = repair_posterior_key
        repaired: list[PSAAbstraction] = []
        skip_reasons: Counter[str] = Counter()
        for abstraction in items:
            source_kind = str(abstraction.source_kind or "")
            symbolic_allowed = bool(
                allow_symbolic_source and source_kind in {"psa_induced", "psa_symbolic_induced"}
            )
            if source_kind != "psa_llm_proposed" and not symbolic_allowed:
                repaired.append(abstraction)
                skip_reasons["not_supported_source"] += 1
                continue
            if bool(abstraction.llm_direct_action):
                repaired.append(abstraction)
                skip_reasons["llm_direct_action"] += 1
                continue
            if not abstraction.source_event_ids:
                repaired.append(abstraction)
                skip_reasons["missing_source_event_ids"] += 1
                continue
            if repair_kind == "axis_reflection":
                repaired_abstraction = _repair_psa_abstraction_with_axis_reflection_goal_link(
                    abstraction,
                    state=state,
                    plan_actions=plan_actions,
                    plan_kind=plan_kind,
                    current_state_hash=current_state_hash,
                )
            else:
                repaired_abstraction = _repair_psa_abstraction_with_shape_coverage_goal_link(
                    abstraction,
                    state=state,
                    plan_actions=plan_actions,
                    plan_kind=plan_kind,
                    current_state_hash=current_state_hash,
                )
            repaired.append(repaired_abstraction)
            metadata = dict(repaired_abstraction.metadata or {})
            for summary_key, metadata_key in (
                ("repair_ids", "psa_structural_goal_link_repair_id"),
                ("goal_link_ids", "psa_structural_goal_link_id"),
                ("protected_plan_ids", "psa_structural_protected_plan_id"),
            ):
                value = str(metadata.get(metadata_key, "") or "")
                if value:
                    existing = list(summary.get(summary_key) or [])
                    if value not in existing:
                        existing.append(value)
                    summary[summary_key] = existing[-4:]
            summary["applied_count"] = int(summary["applied_count"]) + 1
            self._psa_structural_repair_posterior_applied[repair_posterior_key] += 1
        summary["skipped_count"] = int(sum(skip_reasons.values()))
        summary["skip_reasons"] = dict(sorted(skip_reasons.items()))
        if int(summary["applied_count"]) > 0:
            summary["source_kind_after_repair"] = "mixed"
        summary["posterior"] = self._psa_structural_repair_posterior_summary()
        return repaired, summary

    def _psa_structural_repair_posterior_key(self, repair_kind: str, plan_kind: str) -> str:
        kind = str(repair_kind or "unknown").strip() or "unknown"
        plan = str(plan_kind or "unknown").strip() or "unknown"
        return f"{kind}|{plan}"

    def _psa_structural_repair_posterior_score(self, key: str) -> int:
        key = str(key or "")
        return int(
            self._psa_structural_repair_posterior_applied[key]
            + 2 * self._psa_structural_repair_posterior_confirmed[key]
            + 4 * self._psa_structural_repair_posterior_score_delta[key]
            - 3 * self._psa_structural_repair_posterior_falsified[key]
        )

    def _psa_structural_repair_candidate_rank(
        self,
        repair_candidates: Iterable[Mapping[str, Any]],
    ) -> list[dict[str, Any]]:
        rows: list[dict[str, Any]] = []
        for candidate in repair_candidates:
            kind = str(candidate.get("repair_kind", "") or "")
            plan_kind = str(candidate.get("plan_kind", "") or "")
            key = self._psa_structural_repair_posterior_key(kind, plan_kind)
            plan_actions = candidate.get("plan_actions")
            rows.append(
                {
                    "repair_target": kind,
                    "posterior_key": key,
                    "posterior_score": self._psa_structural_repair_posterior_score(key),
                    "attempts": int(self._psa_structural_repair_posterior_attempts[key]),
                    "applied": int(self._psa_structural_repair_posterior_applied[key]),
                    "confirmed": int(self._psa_structural_repair_posterior_confirmed[key]),
                    "falsified": int(self._psa_structural_repair_posterior_falsified[key]),
                    "score_delta": int(self._psa_structural_repair_posterior_score_delta[key]),
                    "plan_len": int(len(plan_actions)) if isinstance(plan_actions, list) else 0,
                }
            )
        return rows

    def _psa_structural_repair_posterior_key_from_repair_id(self, repair_id: str) -> str:
        text = str(repair_id or "")
        if ":shape_coverage:" in text:
            return self._psa_structural_repair_posterior_key(
                "shape_coverage",
                "shape_coverage_paste_full_plan",
            )
        if ":axis_reflection:" in text:
            return self._psa_structural_repair_posterior_key(
                "axis_reflection",
                "axis_reflection_coverage_plan",
            )
        return ""

    def _record_psa_structural_repair_posterior_outcome(
        self,
        *,
        pending: Mapping[str, Any],
        verification: Mapping[str, Any],
        verdict: str,
    ) -> None:
        repair_id = str(pending.get("repair_id", "") or "")
        key = self._psa_structural_repair_posterior_key_from_repair_id(repair_id)
        if not key:
            return
        score_delta = int(verification.get("score_delta", 0) or 0)
        confirmed = str(verdict or "") == "confirmed"
        if confirmed:
            self._psa_structural_repair_posterior_confirmed[key] += 1
        else:
            self._psa_structural_repair_posterior_falsified[key] += 1
        if score_delta > 0:
            self._psa_structural_repair_posterior_score_delta[key] += score_delta
        self._psa_structural_repair_posterior_recent.append(
            {
                "posterior_key": key,
                "repair_id": repair_id,
                "goal_link_id": str(pending.get("goal_link_id", "") or ""),
                "protected_plan_id": str(pending.get("protected_plan_id", "") or ""),
                "verdict": str(verdict or ""),
                "score_delta": int(score_delta),
                "target_success": bool(verification.get("target_success")),
                "structural_progress": bool(verification.get("structural_progress")),
                "goal_aligned_progress": bool(verification.get("goal_aligned_progress")),
                "goal_progress": bool(verification.get("goal_progress")),
            }
        )

    def _psa_structural_repair_posterior_summary(self) -> dict[str, Any]:
        keys = set(self._psa_structural_repair_posterior_attempts)
        keys.update(self._psa_structural_repair_posterior_applied)
        keys.update(self._psa_structural_repair_posterior_confirmed)
        keys.update(self._psa_structural_repair_posterior_falsified)
        keys.update(self._psa_structural_repair_posterior_score_delta)
        by_key = {
            str(key): {
                "attempts": int(self._psa_structural_repair_posterior_attempts[key]),
                "applied": int(self._psa_structural_repair_posterior_applied[key]),
                "confirmed": int(self._psa_structural_repair_posterior_confirmed[key]),
                "falsified": int(self._psa_structural_repair_posterior_falsified[key]),
                "score_delta": int(self._psa_structural_repair_posterior_score_delta[key]),
                "rank_score": int(self._psa_structural_repair_posterior_score(key)),
            }
            for key in sorted(keys)
        }
        return {
            "enabled": bool(self._psa_structural_repair_posterior_enabled()),
            "entry_count": int(len(by_key)),
            "attempt_count": int(sum(self._psa_structural_repair_posterior_attempts.values())),
            "applied_count": int(sum(self._psa_structural_repair_posterior_applied.values())),
            "confirmed_count": int(sum(self._psa_structural_repair_posterior_confirmed.values())),
            "falsified_count": int(sum(self._psa_structural_repair_posterior_falsified.values())),
            "score_delta_sum": int(sum(self._psa_structural_repair_posterior_score_delta.values())),
            "by_key": by_key,
            "recent": list(self._psa_structural_repair_posterior_recent)[-8:],
        }

    def _lane_available(self, primitive_id: str) -> bool:
        """Pillar A1 arbitration gate: skip a lane whose no-score lease is
        exhausted (it has won grant_steps decisions without producing a
        score). Score owners never exhaust. No-op unless
        ECA_ENABLE_LANE_LEASE is on."""
        if not self._lane_lease_enabled:
            return True
        return not self._lane_lease.exhausted(primitive_id)

    def _primitive_enabled(self, primitive_id: str) -> bool:
        return str(primitive_id or "").strip() not in self.disabled_primitives

    def _mechanic_hypotheses_after_posterior_gate(
        self,
        hypotheses: Iterable[Any],
    ) -> tuple[list[Any], dict[str, Any]]:
        items = list(hypotheses)
        enabled = self._mechanic_hypothesis_posterior_enabled()
        suppressed: list[str] = []
        kept: list[Any] = []
        for hypothesis in items:
            key = mechanic_hypothesis_posterior_key(hypothesis)
            confirmed = int(self._mechanic_hypothesis_posterior_confirmed[key])
            falsified = int(self._mechanic_hypothesis_posterior_falsified[key])
            should_suppress = bool(
                enabled
                and falsified >= 2
                and (confirmed <= 0 or falsified >= confirmed + 2)
            )
            if should_suppress:
                suppressed.append(key)
                self._mechanic_hypothesis_posterior_suppressed[key] += 1
                continue
            kept.append(hypothesis)
        return kept, {
            "enabled": bool(enabled),
            "hypothesis_count_before": int(len(items)),
            "hypothesis_count_after": int(len(kept)),
            "suppressed_count": int(len(suppressed)),
            "suppressed_keys": suppressed[:8],
        }

    @property
    def records_count(self) -> int:
        return self.tracker.summary().records_count

