    def observe_transition(
        self,
        *,
        action_name: Any,
        pre_frame: Any,
        post_frame: Any,
        pre_score: int = 0,
        post_score: int = 0,
        pre_state: str = "",
        post_state: str = "",
        action_payload: dict[str, Any] | None = None,
        metadata: dict[str, Any] | None = None,
    ) -> None:
        pre_arr = np.asarray(pre_frame)
        post_arr = np.asarray(post_frame)
        self._last_observed_score = int(pre_score or 0)
        record = self.tracker.observe_transition(
            action_name=action_name,
            pre_frame=pre_arr,
            post_frame=post_arr,
            pre_score=pre_score,
            post_score=post_score,
            pre_state=pre_state,
            post_state=post_state,
            action_payload=dict(action_payload or {}),
            metadata=dict(metadata or {}),
        )
        self._last_observed_score = int(post_score or 0)
        if self._configure_cast is not None:
            observe = getattr(self._configure_cast, "observe_transition", None)
            if callable(observe):
                observe(pre_score=int(pre_score or 0), post_score=int(post_score or 0))
        if self._button_press is not None:
            observe = getattr(self._button_press, "observe_transition", None)
            if callable(observe):
                observe(pre_score=int(pre_score or 0), post_score=int(post_score or 0))
        if self._shape_transform_tile is not None:
            observe = getattr(self._shape_transform_tile, "observe_transition", None)
            if callable(observe):
                observe(pre_score=int(pre_score or 0), post_score=int(post_score or 0))
        if self._chain_sequence is not None:
            observe = getattr(self._chain_sequence, "observe_transition", None)
            if callable(observe):
                observe(pre_score=int(pre_score or 0), post_score=int(post_score or 0))
        if self._peg_solitaire is not None:
            observe = getattr(self._peg_solitaire, "observe_transition", None)
            if callable(observe):
                observe(pre_score=int(pre_score or 0), post_score=int(post_score or 0))
        self._record_transition_memory(record, pre_arr, post_arr, metadata)
        # Phase L bookkeeping (ported from merge-phase246): accumulate
        # positive deltas so the TileEffectLearner's prediction-error
        # attribution can see whether the run is progressing.
        if int(record.score_delta) > 0:
            self._loop_running_positive_delta += int(record.score_delta)
        # W1 stage 2: feed the win-relation tracker (frame buffering +
        # score-event attribution). Skipped entirely when the bias flag is
        # off so the OFF arm stays bit-identical and cost-free.
        if self._win_relation_bias_enabled:
            self._win_relation_tracker.observe(
                post_arr,
                int(record.score_delta),
                actor_class=self.actor_value,
            )
        # E-1 S1: feed the click-effect operator learner (observation
        # only; the planner-side lane is S2). Same bit-identical-OFF
        # contract as the tracker above.
        if self._action_effect_learner_enabled:
            self._action_effect_learner.observe(
                record.action_name,
                dict(action_payload or {}),
                pre_arr,
                post_arr,
            )
        if int(record.score_delta) <= 0:
            self._record_rule_table_signature_successor(record.action_name, pre_arr, post_arr)
        planned_primitive_id = str(self._last_accounted_primitive_id or "")
        self._reconcile_accounted_decision(record.action_name)
        # Ownership bookkeeping (2026-06-10, review P4 "don't steal from an
        # established solver"): record score ownership in the lane lease.
        # The mirror certified dispatch yields when a DIFFERENT primitive
        # already owns score progress (the cn04 mid-episode pair is
        # perceptually indistinguishable from a real mirror pair, so
        # detection-side hardening cannot fix that case), and exhausted
        # non-scoring lanes are skipped by participating gates.
        if int(record.score_delta) > 0 and planned_primitive_id:
            self._lane_lease.on_score(planned_primitive_id)
        if planned_primitive_id == "goal_bearing_shortplan":
            score_delta = max(0, int(record.score_delta))
            self._active_goal_shortplan_score_delta += score_delta
            self._goal_shortplan_stats["score_delta_from_generated_plan"] += score_delta
        if (
            planned_primitive_id
            in {
                "coordinate_hypothesis_choice",
                "coordinate_hypothesis_plan_lease",
                "coordinate_hypothesis_target_commitment",
                "coordinate_hypothesis_terminal_local_verifier",
            }
            and int(record.score_delta) > 0
        ):
            self._coordinate_hypothesis_score_success_count += 1
        coordinate_progress_eval = self._coordinate_hypothesis_progress_eval(
            pending=self._pending_control_target,
            record=record,
            pre_frame=pre_arr,
            post_frame=post_arr,
        )
        key = (record.pre_state_hash, record.action_name)
        self._observed_counts[record.action_name] += 1
        self._epoch_records.append(record)
        self._epoch_observed_counts[record.action_name] += 1
        self._state_action_attempts[record.pre_state_hash][record.action_name] += 1
        if record.changed_pixel_count > 0:
            self._state_action_changed[key] += 1
        if record.no_op:
            self._state_action_noop[key] += 1
        self._state_action_score_delta[key] += int(record.score_delta)
        self._state_action_targets[key][record.post_state_hash] += 1
        # Step 3 emergent adoption: position-keyed tracking for ACTION6
        # so click selection can be routed by position later.
        if record.action_name == "ACTION6":
            click_pos = _click_payload_xy(record.action_payload)
            if click_pos is not None:
                click_key = (record.pre_state_hash, click_pos)
                self._state_click_attempts[click_key] += 1
                if record.changed_pixel_count > 0:
                    self._state_click_changed[click_key] += 1
                if record.no_op:
                    self._state_click_noop[click_key] += 1
                self._state_click_score_delta[click_key] += int(record.score_delta)
        self._record_component_extent_growth_target_distance_rank_guard_outcome(
            action_name=record.action_name,
            action_payload=record.action_payload,
            pre_frame=pre_arr,
            post_frame=post_arr,
            score_delta=int(record.score_delta),
        )
        self._record_multi_axis_button_cycle_membership_observation(
            action_name=record.action_name,
            action_payload=record.action_payload,
            pre_frame=pre_arr,
            post_frame=post_arr,
            score_delta=int(record.score_delta),
        )
        self._record_multi_axis_button_cycle_graph_plan_outcome(
            action_name=record.action_name,
            action_payload=record.action_payload,
            post_frame=post_arr,
            score_delta=int(record.score_delta),
        )
        if int(record.score_delta) > 0 and self._win_gate_evidence_carryover_enabled:
            scored_by_win_lane = planned_primitive_id in {
                "win_hypothesis_directed_walk",
                "action_effect_operator",
            }
            self._win_lane_scored_last_level = bool(
                scored_by_win_lane or self._win_gate_carryover_accept_any_score
            )
        # Step 3 r4: stuck-step counter. Increment when this step
        # made no progress (no_op AND no score). Reset on score gain or
        # state change. EA gate uses this to require the loop be
        # demonstrably stuck before overriding.
        if int(record.score_delta) > 0 or int(record.changed_pixel_count) > 0:
            self._emergent_adoption_stuck_steps = 0
        else:
            self._emergent_adoption_stuck_steps += 1
        self._recent_state_hashes.append(record.post_state_hash)
        if record.score_delta > 0:
            self._record_score_precondition(record, pre_arr)
            self._reset_level_local_actor_memory()
            if planned_primitive_id == "axis_reflection_coverage_search" and int(record.post_score) >= 3:
                self._axis_reflection_post_score_no_cycle_guard = 20
        elif _normalize_action_name(record.action_name) == "ACTION5":
            self._axis_reflection_action5_count_since_level += 1
        self._update_actor_graph(record, pre_arr, post_arr)
        self._update_click_memory(record, pre_arr)
        # Phase L-2 hardening: remember which action was actually ISSUED so
        # the mirror dynamic confirmation can verify the solver's own
        # prediction (issued == planned) instead of raw frame differences.
        self._mirror_last_issued_action = _normalize_action_name(record.action_name)
        pending_for_affordance = dict(self._pending_control_target or {})
        self.click_affordance_inducer.observe(
            record,
            pre_arr,
            post_arr,
            pending_target=pending_for_affordance,
        )
        if planned_primitive_id == "unknown_affordance_probe":
            self._record_unknown_affordance_probe_outcome(record)
        self._record_pending_target_verification(record, pre_arr, post_arr)
        if coordinate_progress_eval.get("applicable"):
            self._record_coordinate_hypothesis_plan_outcome(
                pending=coordinate_progress_eval.get("pending") if isinstance(coordinate_progress_eval.get("pending"), Mapping) else {},
                record=record,
                progress_eval=coordinate_progress_eval,
            )
        if planned_primitive_id == "goal_bearing_shortplan":
            self._update_goal_shortplan_target_health(record, post_arr)
        if planned_primitive_id == "goal_bearing_shortplan" and not self._active_goal_shortplan:
            self._finalize_goal_shortplan_outcome(record)
        # Artificial Body Schema closed-loop turn (default-off, observe-only).
        # Driven here because the body schema needs the action that PRODUCED
        # this frame + its score delta — exactly observe_transition's inputs.
        self._run_body_schema(
            post_arr=post_arr,
            action_name=str(record.action_name or ""),
            score_delta=int(record.score_delta),
            action_payload=record.action_payload,
        )
        self._observe_live_causal_click(
            action_name=str(record.action_name or ""),
            action_payload=record.action_payload,
            score_delta=int(record.score_delta),
        )

    def _objects_from_frame(self, frame_arr: np.ndarray) -> list[dict[str, Any]]:
        """Connected-component object source for the body schema (the
        strict-generic path has no observer/object_table). Emits
        {component_id, center=(x,y), color, size}; bbox is (row,col),
        center=(col,row)=(x,y). Drops the background sheet."""
        try:
            grid = frame_arr.tolist() if hasattr(frame_arr, "tolist") else [list(r) for r in frame_arr]
            if not grid or not grid[0]:
                return []
            comp_map = find_connected_components(grid)
            grouped: dict[int, dict[str, Any]] = {}
            for (row, col), cid in comp_map.items():
                e = grouped.setdefault(cid, {
                    "component_id": f"comp_{cid}", "value": int(grid[row][col]),
                    "size": 0, "min_row": row, "max_row": row, "min_col": col, "max_col": col,
                })
                e["size"] += 1
                e["min_row"] = min(e["min_row"], row); e["max_row"] = max(e["max_row"], row)
                e["min_col"] = min(e["min_col"], col); e["max_col"] = max(e["max_col"], col)
            total = len(grid) * len(grid[0])
            objects: list[dict[str, Any]] = []
            for e in grouped.values():
                if e["size"] >= total * 0.8:  # drop the background sheet
                    continue
                cx = (e["min_col"] + e["max_col"]) // 2
                cy = (e["min_row"] + e["max_row"]) // 2
                objects.append({
                    "component_id": e["component_id"],
                    "center": (int(cx), int(cy)),
                    "color": int(e["value"]),
                    "size": int(e["size"]),
                })
            return objects
        except Exception:
            return []

    def _record_transition_memory(
        self,
        record: ActionEffectRecord,
        pre_arr: np.ndarray,
        post_arr: np.ndarray,
        metadata: Mapping[str, Any] | None,
    ) -> None:
        """Passive T-1 transition capture. Never affects action choice."""
        if not self._transition_memory_enabled:
            return
        try:
            meta = dict(metadata or {})
            raw_level = meta.get("level_id", meta.get("level_idx", None))
            level_id = int(raw_level) if raw_level is not None else None
            raw_tags = meta.get("psa_tags", [])
            if isinstance(raw_tags, str):
                psa_tags = [raw_tags]
            elif isinstance(raw_tags, Iterable):
                psa_tags = [str(tag) for tag in raw_tags]
            else:
                psa_tags = []
            self._transition_memory.observe(
                record,
                pre_frame=pre_arr,
                post_frame=post_arr,
                game_id=self.game_id or None,
                level_id=level_id,
                psa_tags=psa_tags,
            )
        except Exception:
            pass

    def _run_body_schema(
        self,
        *,
        post_arr: np.ndarray,
        action_name: str,
        score_delta: int,
        action_payload: Any = None,
    ) -> None:
        """One BodySchema turn (default-off). Observe-only: updates the body
        schema's affordance/tension/completion/score-event state and stashes
        the BodyFrame; consumption is the separate steer flag. Never breaks the
        host loop."""
        if not self._body_schema_enabled:
            return
        try:
            objects = self._objects_from_frame(post_arr)
            click_xy = None
            if _normalize_action_name(action_name or "") == "ACTION6":
                click_xy = _click_payload_xy(action_payload or {})
            self._last_body_frame = self._body_schema.step(
                post_arr,
                objects,
                action_name=action_name or None,
                score_delta=int(score_delta or 0),
                click_xy=click_xy,
            )
            self._body_schema_steps += 1
        except Exception:
            pass

    def _live_causal_click_candidates_for_frame(
        self,
        frame_arr: np.ndarray,
    ) -> list[tuple[int, int]]:
        """Visible click-site candidates for the live causal bridge.

        This is the gateway-compatible half of the offline affordance prober:
        infer possible click targets from the current frame only, then let
        observe_transition decide which site is causal.
        """
        try:
            arr = np.asarray(frame_arr)
            if arr.ndim < 2:
                return []
            height, width = int(arr.shape[0]), int(arr.shape[1])
            if height <= 0 or width <= 0:
                return []
            max_component_size = max(1, int(height * width * 0.20))
            rows: list[tuple[int, int, int, int]] = []
            for obj in self._objects_from_frame(arr):
                try:
                    x, y = obj.get("center", (None, None))
                    x_i, y_i = int(x), int(y)
                    size = int(obj.get("size", 0) or 0)
                    color = int(obj.get("color", 0) or 0)
                except (TypeError, ValueError):
                    continue
                if size <= 0 or size > max_component_size:
                    continue
                if not (0 <= x_i < width and 0 <= y_i < height):
                    continue
                rows.append((x_i, y_i, size, color))
            seen: set[tuple[int, int]] = set()
            ordered: list[tuple[int, int]] = []
            for x_i, y_i, _size, _color in sorted(
                rows,
                key=lambda item: (-item[0], item[2], item[1], item[3]),
            ):
                site = (int(x_i), int(y_i))
                if site in seen:
                    continue
                seen.add(site)
                ordered.append(site)
            return ordered[:32]
        except Exception:
            return []

    def _observe_live_causal_click(
        self,
        *,
        action_name: str,
        action_payload: Any,
        score_delta: int,
    ) -> None:
        if not self._live_causal_click_enabled:
            return
        if _normalize_action_name(action_name or "") != "ACTION6":
            return
        site = _click_payload_xy(action_payload or {})
        if site is None:
            return
        try:
            site = (int(site[0]), int(site[1]))
        except (TypeError, ValueError, IndexError):
            return
        if (
            self._last_live_causal_click_site is not None
            and site != self._last_live_causal_click_site
        ):
            return
        if int(score_delta or 0) > 0:
            self._live_causal_click_score_events += 1
            self._live_causal_click_success_site = site
            self._live_causal_click_success_remaining = max(
                int(self._live_causal_click_success_remaining),
                int(self._live_causal_click_repeats * 3),
            )
            self._live_causal_click_active_site = None
            self._live_causal_click_active_remaining = 0
            self._live_causal_click_candidates.clear()

    def _live_causal_click_diagnostics(self) -> dict[str, Any]:
        return {
            "enabled": bool(self._live_causal_click_enabled),
            "full_actions": bool(self._live_causal_click_full_actions),
            "repeats": int(self._live_causal_click_repeats),
            "candidate_count": int(len(self._live_causal_click_candidates)),
            "attempted_count": int(len(self._live_causal_click_attempted_sites)),
            "active_site": (
                list(self._live_causal_click_active_site)
                if self._live_causal_click_active_site is not None
                else None
            ),
            "active_remaining": int(self._live_causal_click_active_remaining),
            "success_site": (
                list(self._live_causal_click_success_site)
                if self._live_causal_click_success_site is not None
                else None
            ),
            "success_remaining": int(self._live_causal_click_success_remaining),
            "probe_count": int(self._live_causal_click_probe_count),
            "replay_count": int(self._live_causal_click_replay_count),
            "score_events": int(self._live_causal_click_score_events),
            "last_site": (
                list(self._last_live_causal_click_site)
                if self._last_live_causal_click_site is not None
                else None
            ),
            "last_kind": str(self._last_live_causal_click_kind or ""),
        }

    def _early_return_lane_table(self):
        """A3 stage 1: ordered early-return lane table.

        Table order is the previous code order (= current priority). Lanes
        migrate here one branch per step from the inline early-return band
        in next_decision, each gated on bit-identical behaviour. Adding a
        lane becomes a table row + a decision method, not a position
        choice inside a 36k-line method.
        """
        return (
            ("source_backed_sim_search_replay", self._sim_search_replay_lane_decision),
            ("generic_canvas_centroid_bootstrap", self._generic_canvas_centroid_bootstrap_lane_decision),
            ("win_hypothesis_directed_walk", self._win_hypothesis_walk_lane_decision),
            ("action_effect_operator", self._action_effect_operator_lane_decision),
            ("generic_grow_drag", self._grow_drag_lane_decision),
            ("generic_drag_to_goal", self._generic_drag_to_goal_lane_decision),
            ("generic_button_press_bfs", self._generic_button_press_bfs_lane_decision),
            ("generic_configure_cast_bfs", self._generic_configure_cast_bfs_lane_decision),
            ("generic_force_field_merge_containment", self._generic_force_field_merge_containment_lane_decision),
            ("generic_peg_solitaire_bfs", self._generic_peg_solitaire_bfs_lane_decision),
            ("generic_side_fall_bfs", self._generic_side_fall_bfs_lane_decision),
            ("generic_shape_transform_tile_bfs", self._generic_shape_transform_tile_bfs_lane_decision),
            ("generic_chain_sequence_bfs", self._generic_chain_sequence_bfs_lane_decision),
        )

    # Per-level frames of fruitless exploration before the pre-score
    # directed walk is allowed to engage. Must exceed the typical
    # first-score step of the generic base so an early-scoring solver is
    # never preempted (measured pseudo-holdout OFF first-score: dc22 @57).
    WIN_HYPOTHESIS_STUCK_STEPS = 96

    def _win_hypothesis_exploration_stuck(self) -> bool:
        """True once the current level has run WIN_HYPOTHESIS_STUCK_STEPS
        frames without any score this episode — the precondition for the
        directed walk to engage. `_epoch_records` is cleared per level, so
        this counts steps-in-level; gating on it lets the generic base
        take first refusal and only hands the wheel to the win-relation
        bias when normal exploration is demonstrably stuck."""
        records = len(self._epoch_records)
        if (
            self._win_gate_evidence_carryover_enabled
            and self._win_lane_scored_last_level
            and records < self.WIN_HYPOTHESIS_STUCK_STEPS
        ):
            # Leave every fourth decision to the normal pipeline, so a
            # newly productive generic scorer can retake ownership.
            return records >= int(self._win_gate_carryover_steps) and (records % 4) != 3
        return records >= self.WIN_HYPOTHESIS_STUCK_STEPS

    def _sim_search_replay_lane_decision(
        self,
        *,
        frame_arr: np.ndarray,
        available: set[str],
        classification: Any,
        current_hash: str,
    ) -> PrimitiveActionDecision | None:
        """Default-off source-backed generic sim-search replay lane."""

        del frame_arr, classification
        if not self._sim_search_replay_enabled:
            return None
        if not self._game_allowed_by_env("ECA_SIM_SEARCH_REPLAY_GAME_ALLOWLIST"):
            return None
        if not self._sim_search_replay_initialized:
            self._sim_search_replay_initialized = True
            budget_raw = str(
                os.environ.get("ECA_SIM_SEARCH_REPLAY_PER_LEVEL_BUDGET_S", "10")
                or "10"
            )
            try:
                per_level_budget = max(1.0, min(120.0, float(budget_raw)))
            except (TypeError, ValueError):
                per_level_budget = 10.0
            max_levels = _eca_env_int(
                "ECA_SIM_SEARCH_REPLAY_MAX_LEVELS",
                4,
                minimum=1,
                maximum=16,
            )
            max_depth = _eca_env_int(
                "ECA_SIM_SEARCH_REPLAY_MAX_DEPTH",
                40,
                minimum=4,
                maximum=160,
            )
            try:
                from arcgym.sim_search.solver import solve_game

                result = solve_game(
                    self.game_id,
                    per_level_budget_s=per_level_budget,
                    max_depth=max_depth,
                    max_levels=max_levels,
                )
                plan = list(result.get("plan") or [])
                self._sim_search_replay_plan = deque(tuple(step) for step in plan)
                self._sim_search_replay_diag = {
                    "enabled": True,
                    "initialized": True,
                    "found": bool(plan),
                    "reason": str(result.get("reason", "") or ""),
                    "source": str(result.get("source", "") or ""),
                    "plan_length": int(len(plan)),
                    "max_levels": int(max_levels),
                    "per_level_budget_s": float(per_level_budget),
                    "max_depth": int(max_depth),
                }
            except Exception as exc:  # pragma: no cover - defensive runtime guard
                self._sim_search_replay_plan.clear()
                self._sim_search_replay_diag = {
                    "enabled": True,
                    "initialized": True,
                    "found": False,
                    "reason": f"{type(exc).__name__}: {exc}",
                    "source": "",
                    "plan_length": 0,
                    "max_levels": int(max_levels),
                    "per_level_budget_s": float(per_level_budget),
                    "max_depth": int(max_depth),
                }
        while self._sim_search_replay_plan:
            step = tuple(self._sim_search_replay_plan[0])
            if not step:
                self._sim_search_replay_plan.popleft()
                continue
            action_name = _normalize_action_name(str(step[0]))
            if action_name not in available:
                self._sim_search_replay_diag = {
                    **dict(self._sim_search_replay_diag),
                    "blocked_reason": "action_unavailable",
                    "blocked_action": action_name,
                    "remaining": int(len(self._sim_search_replay_plan)),
                }
                return None
            self._sim_search_replay_plan.popleft()
            payload: dict[str, Any] = {"action": action_name}
            if action_name == "ACTION6" and len(step) >= 3:
                payload["x"] = int(step[1])
                payload["y"] = int(step[2])
            return PrimitiveActionDecision(
                action_name=action_name,
                action_payload=payload,
                primitive_id="source_backed_sim_search_replay",
                classification_label="source_backed_sim_search",
                reason="source-backed generic sim-search replay plan",
                records_count=len(self._epoch_records),
                should_probe=False,
                state_hash=current_hash,
                frontier_actions=[],
                hypothesis_kinds=[],
                transition_edge_count=0,
                selection={"primary_primitive": "source_backed_sim_search_replay"},
                diagnostics={
                    "source_backed_sim_search_replay": {
                        **dict(self._sim_search_replay_diag),
                        "remaining_after_choice": int(len(self._sim_search_replay_plan)),
                    }
                },
            )
        return None

    # Per-site click budget for the operator lane (E-1 design §6).
    OPERATOR_SITE_BUDGET = 3

    def _generic_canvas_centroid_bootstrap_lane_decision(
        self,
        *,
        frame_arr: np.ndarray,
        available: set[str],
        classification: Any,
        current_hash: str,
    ) -> PrimitiveActionDecision | None:
        """Default-off canvas-centroid RESET+replay bootstrap.

        The bootstrap opens a sibling ArcAgi3Env, so this lane is explicitly
        simulator-dependent. It requires both an enable flag and a non-empty
        game allowlist before it can preempt the normal synthesis loop.
        """

        del frame_arr, classification
        if not self._generic_canvas_centroid_bootstrap_enabled:
            return None
        allowlist = _parse_env_allowlist(
            "ECA_GENERIC_CANVAS_CENTROID_BOOTSTRAP_GAME_ALLOWLIST"
        )
        if not allowlist or not (self.game_id and self.game_id in allowlist):
            return None
        if "ACTION6" not in available:
            return None
        if not self._generic_canvas_centroid_bootstrap_initialized:
            self._generic_canvas_centroid_bootstrap_initialized = True
            max_actions = _eca_env_int(
                "ECA_GENERIC_CANVAS_CENTROID_BOOTSTRAP_MAX_ACTIONS",
                240,
                minimum=8,
                maximum=512,
            )
            try:
                from arcgym.eca import generic_canvas_centroid_bootstrap as bootstrap

                plan = list(bootstrap.plan(self.game_id, max_actions=max_actions) or [])
                diag_obj = getattr(bootstrap, "LAST_DIAGNOSTICS", None)
                diag = (
                    dict(diag_obj.to_dict())
                    if diag_obj is not None and hasattr(diag_obj, "to_dict")
                    else {}
                )
                self._generic_canvas_centroid_bootstrap_plan = deque(
                    tuple(step) for step in plan
                )
                self._generic_canvas_centroid_bootstrap_diag = {
                    "enabled": True,
                    "initialized": True,
                    "found": bool(plan),
                    "plan_length": int(len(plan)),
                    "max_actions": int(max_actions),
                    "bootstrap": diag,
                }
            except Exception as exc:  # pragma: no cover - defensive runtime guard
                self._generic_canvas_centroid_bootstrap_plan.clear()
                self._generic_canvas_centroid_bootstrap_diag = {
                    "enabled": True,
                    "initialized": True,
                    "found": False,
                    "plan_length": 0,
                    "max_actions": int(max_actions),
                    "reason": f"{type(exc).__name__}: {exc}",
                    "bootstrap": {},
                }
        while self._generic_canvas_centroid_bootstrap_plan:
            step = tuple(self._generic_canvas_centroid_bootstrap_plan[0])
            if not step:
                self._generic_canvas_centroid_bootstrap_plan.popleft()
                continue
            action_name = _normalize_action_name(str(step[0]))
            if action_name not in available:
                self._generic_canvas_centroid_bootstrap_diag = {
                    **dict(self._generic_canvas_centroid_bootstrap_diag),
                    "blocked_reason": "action_unavailable",
                    "blocked_action": action_name,
                    "remaining": int(len(self._generic_canvas_centroid_bootstrap_plan)),
                }
                return None
            self._generic_canvas_centroid_bootstrap_plan.popleft()
            payload: dict[str, Any] = {"action": action_name}
            if action_name == "ACTION6" and len(step) >= 3:
                payload["x"] = int(step[1])
                payload["y"] = int(step[2])
            return PrimitiveActionDecision(
                action_name=action_name,
                action_payload=payload,
                primitive_id="generic_canvas_centroid_bootstrap",
                classification_label="simulator_canvas_centroid_bootstrap",
                reason="generic canvas-centroid RESET+replay confirmed plan",
                records_count=len(self._epoch_records),
                should_probe=False,
                state_hash=current_hash,
                frontier_actions=[],
                hypothesis_kinds=[],
                transition_edge_count=0,
                selection={"primary_primitive": "generic_canvas_centroid_bootstrap"},
                diagnostics={
                    "generic_canvas_centroid_bootstrap": {
                        **dict(self._generic_canvas_centroid_bootstrap_diag),
                        "remaining_after_choice": int(
                            len(self._generic_canvas_centroid_bootstrap_plan)
                        ),
                    }
                },
            )
        return None

    def _action_effect_operator_lane_decision(
        self,
        *,
        frame_arr: np.ndarray,
        available: set[str],
        classification: Any,
        current_hash: str,
    ) -> PrimitiveActionDecision | None:
        """E-1 S2 lane: operator-interleaved replanning. When exploration
        is stuck (same last-resort contract as the directed walk — the
        generic base keeps first refusal), fire an ADMITTED click
        operator: prefer the site nearest the active win-hypothesis
        object (the operator most likely to unblock the approach), else
        the least-attempted site. The movement planner replans on the
        next frame; the hypothesis lease treats a fruitless operator like
        any non-progressing step, so wrong operators rotate out."""
        if not self._action_effect_lane_enabled:
            return None
        if "ACTION6" not in available:
            return None
        if not self._win_hypothesis_exploration_stuck():
            return None
        sites = self._effect_bus.click_effect_sites(frame_arr)
        if not sites:
            return None
        goal = None
        if self._win_relation_bias_enabled:
            goal = self._win_relation_tracker.active_object_centroid(frame_arr)

        def _preference(item: tuple[tuple[int, int], str]) -> tuple:
            (x, y), _effect = item
            attempts = self._operator_site_attempts[(x, y)]
            if goal is not None:
                return (attempts, abs(x - goal[0]) + abs(y - goal[1]), x, y)
            return (attempts, 0, x, y)

        for (x, y), effect in sorted(sites.items(), key=lambda i: _preference(i)):
            if self._operator_site_attempts[(x, y)] >= self.OPERATOR_SITE_BUDGET:
                continue
            self._operator_site_attempts[(x, y)] += 1
            return PrimitiveActionDecision(
                action_name="ACTION6",
                action_payload={"action": "ACTION6", "x": int(x), "y": int(y)},
                primitive_id="action_effect_operator",
                classification_label=str(getattr(classification, "label", "") or ""),
                reason=f"learned click operator ({effect}) at ({x},{y})",
                records_count=len(self._epoch_records),
                should_probe=False,
                state_hash=current_hash,
                frontier_actions=[],
                hypothesis_kinds=[],
                transition_edge_count=0,
                selection={"primary_primitive": "action_effect_operator"},
                diagnostics={"action_effect_operator": {
                    "site": [int(x), int(y)],
                    "effect": effect,
                    "attempt": int(self._operator_site_attempts[(x, y)]),
                    "admitted_count": len(
                        self._action_effect_learner.admitted_operators()
                    ),
                }},
            )
        return None

    def _win_hypothesis_walk_lane_decision(
        self,
        *,
        frame_arr: np.ndarray,
        available: set[str],
        classification: Any,
        current_hash: str,
    ) -> PrimitiveActionDecision | None:
        """D-1 stage 3 lane: walk the active win hypothesis's subject
        toward its object. Registered through the A3 selector table (a
        table row + this method), arbitrated by the LaneLease (a
        non-scoring hypothesis walk exhausts its grant and yields) AND
        by the hypothesis lease inside the tracker (a non-progressing
        hypothesis rotates out). Fires only with an ACTIVE hypothesis —
        the D1-a-gated prior before the first score, the 92% attribution
        after it — so out-of-vocabulary games are untouched
        (no-hypothesis => this lane is silent)."""
        if not self._win_relation_bias_enabled:
            return None
        # Yield to the normal scoring pipeline until the level is
        # demonstrably stuck. A pre-score directed walk is an early-return
        # lane (highest priority), so without this gate it preempts the
        # generic base solvers that score on their own — measured dc22
        # 1->0 regression (click_opened_region_navigation scores at
        # action 57, but the walk monopolised from step 30). The walk is a
        # LAST RESORT: it engages only after WIN_HYPOTHESIS_STUCK_STEPS
        # frames of the current level produced no score.
        if not self._win_hypothesis_exploration_stuck():
            return None
        tracker = self._win_relation_tracker
        if tracker.active_hypothesis() is None:
            return None
        actor_pos = self._actor_position(frame_arr)
        if actor_pos is None:
            return None
        # Route toward the hypothesis object cell using the frame-only
        # navigators (learned-walkability BFS), not a greedy gradient.
        chosen = self._win_hypothesis_route_action(actor_pos, available, frame_arr)
        if chosen is None:
            return None
        active = tracker.active_hypothesis()
        return PrimitiveActionDecision(
            action_name=chosen,
            action_payload={"action": chosen},
            primitive_id="win_hypothesis_directed_walk",
            classification_label=str(getattr(classification, "label", "") or ""),
            reason=(
                f"win-hypothesis directed walk ({active.relation} "
                f"{active.subject}->{getattr(active, 'object', None)})"
            ),
            records_count=len(self._epoch_records),
            should_probe=False,
            state_hash=current_hash,
            frontier_actions=[],
            hypothesis_kinds=[],
            transition_edge_count=0,
            selection={"primary_primitive": "win_hypothesis_directed_walk"},
            diagnostics={"win_hypothesis_directed_walk": tracker.summary()},
        )

