    @property
    def transition_edge_count(self) -> int:
        return int(len(self._state_action_targets))

    def transition_graph_summary(self, *, current_frame: Any | None = None) -> dict[str, Any]:
        current_hash = frame_state_hash(current_frame) if current_frame is not None else ""
        current_attempts = dict(self._state_action_attempts.get(current_hash, {})) if current_hash else {}
        return {
            "state_count": len(self._state_action_attempts),
            "edge_count": self.transition_edge_count,
            "current_state_hash": current_hash,
            "current_state_attempts": current_attempts,
            "recent_state_count": len(set(self._recent_state_hashes)),
            "score_edge_count": sum(1 for value in self._state_action_score_delta.values() if value != 0),
            "noop_edge_count": sum(1 for value in self._state_action_noop.values() if value > 0),
            "actor_value": self.actor_value,
            "actor_state_count": len(self._actor_action_attempts),
            "actor_edge_count": len(self._actor_action_targets),
            "passable_values": self._passable_values(),
            "passable_value_prior": {
                int(value): int(count)
                for value, count in sorted(self._passable_value_prior.items())
            },
            "passable_demoted": sorted(int(value) for value in self._passable_demoted),
            "stride_lattice": {
                action: [int(vector[0]), int(vector[1])]
                for action, vector in sorted(
                    self._transport_effect_learner.stride_lattice(
                        max_manhattan=RESET_JUMP_DISTANCE,
                    ).items()
                )
            },
            "epoch_id": self._epoch_id,
            "disabled_primitives": sorted(self.disabled_primitives),
            "epoch_records_count": sum(self._epoch_observed_counts.values()),
            "epoch_observed_counts": dict(self._epoch_observed_counts),
            "score_precondition_count": len(self._score_preconditions),
            "score_preconditions": self._score_preconditions[-8:],
            "score_transition_kinds": self._score_transition_kind_counts(),
            "score_click_points": [list(point) for point in self._score_click_points[:8]],
            "click_topology_event_count": len(self._click_topology_events),
            "click_topology_targets": [list(point) for point in self._click_topology_targets()],
            "control_panel_lease_polarity_posterior": self._control_panel_lease_polarity_summary(),
            "control_panel_polarity_state_machine": self._control_panel_polarity_state_machine_summary(),
            "target_verification": self._target_verification_summary(),
            "structural_rods": self.rod_memory.summary(),
            "rod_action_binding": self._rod_action_binding_summary(),
            "rod_target_binding": self._rod_target_binding_summary(),
            "rod_score_precondition_action": self._rod_score_precondition_action_summary(),
        }

    def _epoch_summary(self):
        return summarize_action_effect_records(self._epoch_records)

    def _reset_level_local_actor_memory(self) -> None:
        self._epoch_id += 1
        self._epoch_records.clear()
        self._epoch_observed_counts.clear()
        self._reset_actor_topology_memory()
        if self._passable_carryover_enabled:
            for value, count in self._passable_value_votes.items():
                if int(count) <= 0:
                    continue
                current = int(self._passable_value_prior.get(int(value), 0))
                self._passable_value_prior[int(value)] = min(8, current + int(count))
        self._passable_value_votes.clear()
        self._passable_demoted.clear()
        self._passable_contradiction_cells.clear()
        # E-1 S2: a new level redraws the board — per-site click budgets
        # restart (admitted operators themselves persist; they are
        # signature-keyed, not site-keyed).
        self._operator_site_attempts.clear()
        self._wall_follow_commit = None
        self._reset_action_bans.clear()
        self._lane_node_attempts.clear()
        self._lane_node_edges.clear()
        self._effective_click_points.clear()
        self._epoch_click_points.clear()
        self._epoch_click_contexts.clear()
        self._exhausted_click_topology_targets.clear()
        self._control_panel_lease_checkpoint_attempts.clear()
        self._control_panel_lease_retired_checkpoints.clear()
        self._control_panel_polarity_state_machine_last.clear()
        self._control_panel_polarity_exit_handoff_epochs.clear()
        self._control_panel_polarity_exit_target_attempts.clear()
        self._active_control_panel_cycle_portal_plan.clear()
        self._active_control_panel_crusher_ferry_plan.clear()
        self._active_attach_plan.clear()
        self._active_attach_primitive_id = None
        self._attach_fill_zone_memory.clear()
        self._active_mirror_selectable_blocker_plan.clear()
        self._last_mirror_selectable_blocker_reposition = {}
        self._active_mirror_color_lock_target_plan.clear()
        self._last_mirror_color_lock_target = {}
        self._active_select_push_plan.clear()
        self._active_stride_marker_absorber_plan.clear()
        self._active_stride_marker_absorber_context.clear()
        self._active_shape_coverage_plan.clear()
        self._active_sprite_anchor_overlap_plan.clear()
        self._last_sprite_anchor_overlap_state = None
        self._sprite_anchor_hidden_probe_records.clear()
        self._sprite_anchor_hidden_probe_current_key = None
        self._active_axis_reflection_coverage_plan.clear()
        self._last_axis_reflection_coverage_state = None
        self._axis_reflection_action5_count_since_level = 0
        self._axis_reflection_post_score_no_cycle_guard = 0
        self._active_goal_shortplan.clear()
        self._active_goal_shortplan_target.clear()
        self._active_goal_shortplan_score_delta = 0
        self._active_goal_shortplan_executed_count = 0
        self._active_goal_shortplan_last_distance = None
        self._active_goal_shortplan_no_improve_count = 0
        self._active_coordinate_hypothesis_plan.clear()
        self._active_coordinate_hypothesis_plan_context.clear()
        self._coordinate_hypothesis_target_commitment.clear()
        self._click_index = 0
        self._last_click_probe_directional_count = -1
        self._last_attach_action_from_active_queue = False
        self._last_accounted_action = None
        self._last_accounted_primitive_id = None

    def _reconcile_accounted_decision(self, executed_action: str) -> None:
        planned = _normalize_action_name(self._last_accounted_action)
        primitive_id = self._last_accounted_primitive_id
        self._last_accounted_action = None
        self._last_accounted_primitive_id = None
        executed = _normalize_action_name(executed_action)
        if not planned or not executed:
            return
        if planned == executed:
            if primitive_id == "generic_stride_marker_coupled_motion_bfs":
                self._consume_stride_marker_coupled_motion_step(executed)
            if primitive_id == "generic_stride_marker_absorber_bfs":
                self._consume_stride_marker_absorber_step(executed)
            return

        if self._pending_rod_context is not None:
            context = dict(self._pending_rod_context)
            context["action_name"] = executed
            predicted = dict(context.get("predicted_effect") or {})
            predicted["planned_action_name"] = planned
            predicted["executed_action_name"] = executed
            predicted["execution_reconciled"] = True
            context["predicted_effect"] = predicted
            self._pending_rod_context = context

        if primitive_id in {
            "coordinate_hypothesis_choice",
            "coordinate_hypothesis_plan_lease",
            "coordinate_hypothesis_target_commitment",
            "coordinate_hypothesis_terminal_local_verifier",
        }:
            self._active_coordinate_hypothesis_plan.clear()
            self._active_coordinate_hypothesis_plan_context.clear()
        if primitive_id == "generic_stride_marker_absorber_bfs":
            self._active_stride_marker_absorber_plan.clear()
            self._active_stride_marker_absorber_context.clear()
        if primitive_id == "generic_stride_marker_coupled_motion_bfs":
            self._active_stride_marker_coupled_motion_plan.clear()
            self._active_stride_marker_coupled_motion_context.clear()

        if self._issued_counts[planned] > 0:
            self._issued_counts[planned] -= 1
        self._issued_counts[executed] += 1

        if self._recent_primitive_actions:
            recent_primitive, recent_action = self._recent_primitive_actions[-1]
            if recent_primitive == primitive_id and _normalize_action_name(recent_action) == planned:
                self._recent_primitive_actions[-1] = (str(recent_primitive), executed)

        if planned == "ACTION6" and executed != "ACTION6":
            self._click_index = max(0, int(self._click_index) - 1)
        elif planned != "ACTION6" and executed == "ACTION6":
            self._click_index += 1

        if planned == "ACTION6" or executed == "ACTION6":
            self._last_click_probe_directional_count = sum(
                self._issued_counts[action] for action in DIRECTIONAL_ACTIONS
            )
        self._pending_control_target = None

    def _consume_stride_marker_absorber_step(self, executed_action: str) -> None:
        executed = _normalize_action_name(executed_action)
        if not executed or not self._active_stride_marker_absorber_plan:
            return
        expected = _normalize_action_name(self._active_stride_marker_absorber_plan[0])
        if expected == executed:
            self._active_stride_marker_absorber_plan.popleft()
            if not self._active_stride_marker_absorber_plan:
                self._active_stride_marker_absorber_context.clear()
            return
        self._active_stride_marker_absorber_plan.clear()
        self._active_stride_marker_absorber_context.clear()

    def _consume_stride_marker_coupled_motion_step(self, executed_action: str) -> None:
        executed = _normalize_action_name(executed_action)
        if not executed or not self._active_stride_marker_coupled_motion_plan:
            return
        expected = _normalize_action_name(self._active_stride_marker_coupled_motion_plan[0])
        if executed == expected:
            self._active_stride_marker_coupled_motion_plan.popleft()
            if not self._active_stride_marker_coupled_motion_plan:
                self._active_stride_marker_coupled_motion_context.clear()
            return
        self._active_stride_marker_coupled_motion_plan.clear()
        self._active_stride_marker_coupled_motion_context.clear()

    def _reset_actor_topology_memory(self, *, preserve_blocked_clicks: bool = False) -> None:
        self._actor_action_attempts.clear()
        self._actor_action_targets.clear()
        self._actor_visit_counts.clear()
        self._recent_actor_positions.clear()
        if not preserve_blocked_clicks:
            self._blocked_click_counts.clear()
        self._last_click_probe_directional_count = -1

    def _record_score_precondition(self, record: ActionEffectRecord, pre_frame: np.ndarray) -> None:
        actor_pos = self._actor_position(pre_frame)
        recent_click_points = [tuple(point) for point in self._recent_click_points]
        current_click_point = (
            _click_point_from_payload(record.action_payload)
            if _normalize_action_name(record.action_name) == "ACTION6"
            else None
        )
        if current_click_point is not None:
            recent_click_points = [current_click_point] + [
                point for point in recent_click_points if point != current_click_point
            ]
        transition_kind = _score_transition_kind(record)
        bbox_area_fraction = _changed_bbox_area_fraction(record)
        self._score_preconditions.append(
            {
                "epoch_id": self._epoch_id,
                "action_name": record.action_name,
                "actor_pos": list(actor_pos) if actor_pos is not None else None,
                "action_site": list(current_click_point) if current_click_point is not None else None,
                "local_patch_hash": _local_patch_hash(pre_frame, actor_pos),
                "target_values": _score_target_values(
                    pre_frame,
                    actor_pos,
                    record.action_name,
                    actor_value=self.actor_value,
                ),
                "pre_state_hash": record.pre_state_hash,
                "post_state_hash": record.post_state_hash,
                "score_delta": int(record.score_delta),
                "changed_bbox": record.changed_bbox.to_dict() if record.changed_bbox else None,
                "changed_bbox_area_fraction": round(float(bbox_area_fraction), 6),
                "changed_fraction": round(float(record.changed_fraction), 6),
                "changed_values": list(record.changed_values[:8]),
                "transition_kind": transition_kind,
                "recent_click_points": [list(point) for point in recent_click_points],
            }
        )
        self._score_preconditions = self._score_preconditions[-32:]
        self._remember_score_click_points(recent_click_points)

    def _score_transition_kind_counts(self) -> dict[str, int]:
        counts: Counter[str] = Counter()
        for item in self._score_preconditions:
            counts[str(item.get("transition_kind") or "unknown")] += 1
        return dict(sorted(counts.items()))

    def _remember_score_click_points(self, points: Iterable[tuple[int, int]]) -> None:
        for point in reversed(list(points)):
            key = (int(point[0]), int(point[1]))
            if key in self._score_click_points:
                self._score_click_points.remove(key)
            self._score_click_points.insert(0, key)
        self._score_click_points = self._score_click_points[:16]

    def _early_click_affordance_bootstrap_payload(
        self,
        frame: np.ndarray,
        available: set[str],
        *,
        actor_pos: tuple[int, int] | None = None,
    ) -> dict[str, int] | None:
        if "ACTION6" not in available:
            return None
        if not any(action in available for action in DIRECTIONAL_ACTIONS):
            return None
        if self._epoch_id != 0:
            return None
        if self._epoch_observed_counts["ACTION6"] != 1:
            return None
        if not self._effective_click_points and not self._click_topology_events:
            return None
        if actor_pos is not None and self._click_topology_events:
            event_actor = self._latest_click_topology_actor_pos()
            if event_actor is not None and event_actor != (int(actor_pos[0]), int(actor_pos[1])):
                return None
        if frame.ndim < 2:
            return None
        height, width = int(frame.shape[0]), int(frame.shape[1])
        point = (width // 2, height // 2)
        if self._epoch_click_points[point] > 0:
            return None
        return {"x": int(point[0]), "y": int(point[1])}

    def _early_click_affordance_context_recovery_action(
        self,
        actor_pos: tuple[int, int],
        available: set[str],
    ) -> str | None:
        if "ACTION6" not in available:
            return None
        if self._epoch_id != 0:
            return None
        if self._epoch_observed_counts["ACTION6"] != 1:
            return None
        if sum(1 for primitive_id, _action in self._recent_primitive_actions if primitive_id == "click_context_recovery") >= 2:
            return None
        target = self._latest_click_topology_actor_pos()
        if target is None:
            return None
        if target == (int(actor_pos[0]), int(actor_pos[1])):
            return None
        return self._direction_toward_actor_context(actor_pos, target, available)

    def _latest_click_topology_actor_pos(self) -> tuple[int, int] | None:
        for event in reversed(self._click_topology_events):
            event_actor = event.get("actor_pos")
            if not isinstance(event_actor, (list, tuple)) or len(event_actor) < 2:
                continue
            try:
                return int(event_actor[0]), int(event_actor[1])
            except (TypeError, ValueError):
                continue
        return None

    def _direction_toward_actor_context(
        self,
        actor_pos: tuple[int, int],
        target: tuple[int, int],
        available: set[str],
    ) -> str | None:
        x, y = int(actor_pos[0]), int(actor_pos[1])
        tx, ty = int(target[0]), int(target[1])
        preferred: list[str] = []
        if abs(x - tx) >= abs(y - ty):
            if x < tx:
                preferred.append("ACTION4")
            elif x > tx:
                preferred.append("ACTION3")
            if y < ty:
                preferred.append("ACTION2")
            elif y > ty:
                preferred.append("ACTION1")
        else:
            if y < ty:
                preferred.append("ACTION2")
            elif y > ty:
                preferred.append("ACTION1")
            if x < tx:
                preferred.append("ACTION4")
            elif x > tx:
                preferred.append("ACTION3")
        for action in preferred:
            if action in available and not self._actor_action_blocked(actor_pos, action):
                return action
        return None

    def _probe_action(self, selection: PrimitiveSelection, available: set[str]) -> str:
        score_candidate_actions = self._score_candidate_probe_actions(selection, available)
        if score_candidate_actions:
            return score_candidate_actions[0]
        unissued = [action for action in self.action_order if action in available and self._epoch_observed_counts[action] <= 0]
        if unissued:
            return _least_issued(unissued, self._issued_counts)
        for candidate in selection.candidates:
            for action_name in candidate.next_probe_actions:
                normalized = _normalize_action_name(action_name)
                if normalized in available:
                    return normalized
        return _least_issued([action for action in self.action_order if action in available], self._issued_counts)

    def _score_candidate_probe_actions(
        self,
        selection: PrimitiveSelection,
        available: set[str],
    ) -> list[str]:
        control_target = dict(selection.control_target or {})
        operator = str(control_target.get("primary_operator", "") or "")
        uncertainty = set(str(item) for item in selection.uncertainty_reasons)
        uncertainty.update(str(item) for item in list(control_target.get("uncertainty_reasons") or []))
        if operator != "probe" and "stale_operator_candidates_exhausted" not in uncertainty:
            return []

        raw_actions: list[str] = []
        for action_name in list(control_target.get("next_probe_actions") or []):
            raw_actions.append(_normalize_action_name(action_name))
        for candidate in list(control_target.get("target_candidates") or []):
            if not isinstance(candidate, dict):
                continue
            raw_actions.append(_normalize_action_name(candidate.get("action_name")))
        for candidate in selection.candidates:
            for action_name in candidate.next_probe_actions:
                raw_actions.append(_normalize_action_name(action_name))

        deduped_actions: list[str] = []
        seen: set[str] = set()
        for action in raw_actions:
            if action and action in available and action not in seen:
                seen.add(action)
                deduped_actions.append(action)

        if not deduped_actions and (
            operator == "probe" or "stale_operator_candidates_exhausted" in uncertainty
        ):
            deduped_actions = [action for action in self.action_order if action in available]
        if not deduped_actions:
            return []

        summary = self._epoch_summary()
        goal_profile = dict(summary.goal_transition_profile or {})
        action_goal_scores = {
            _normalize_action_name(action): float(score)
            for action, score in dict(goal_profile.get("action_goal_scores") or {}).items()
        }
        terminal_actions = {
            _normalize_action_name(action)
            for action in list(goal_profile.get("terminal_no_score_actions") or [])
        }
        scored: list[tuple[float, int, float, int, int, str]] = []
        for index, action in enumerate(deduped_actions):
            if self._operator_action_stale("probe", action) or self._operator_action_stale("repeat_action", action):
                continue
            stats = summary.action_stats.get(action)
            goal_score = float(action_goal_scores.get(action, 0.0) or 0.0)
            terminal_penalty = 1 if action in terminal_actions else 0
            no_op_rate = float(stats.no_op_rate) if stats is not None else 0.0
            changed_bonus = float(stats.changed_rate) if stats is not None else 0.0
            unissued_bonus = 1 if self._epoch_observed_counts[action] <= 0 else 0
            scored.append(
                (
                    -goal_score,
                    terminal_penalty,
                    no_op_rate - changed_bonus - float(unissued_bonus),
                    self._issued_counts[action],
                    index,
                    action,
                )
            )
        if not scored:
            return []
        scored.sort()
        return [action for *_prefix, action in scored]

    def _rod_action_binding_decision(
        self,
        selection: PrimitiveSelection,
        *,
        summary: Any,
        primitive_id: str,
        current_action: str,
        available: set[str],
        action_payload_override: Mapping[str, Any] | None,
        protected_action: bool,
        reason: str,
    ) -> dict[str, Any]:
        family = str(
            (selection.control_target or {}).get("solver_family", "")
            or _solver_family_for_primitive_id(primitive_id)
        )
        query_effects = sorted(
            set(_effect_types_for_primitive(primitive_id))
            | set(_effect_types_from_summary(summary))
        )
        support = self.rod_memory.retrieve(
            primitive_id=primitive_id,
            solver_family=family,
            effect_types=query_effects,
            record_reuse=False,
        )
        current = _normalize_action_name(current_action)
        payload: dict[str, Any] = {
            "enabled": bool(self._enable_rod_action_binding),
            "applied": False,
            "primitive_id": str(primitive_id or ""),
            "solver_family": family,
            "current_action": current,
            "selected_action": current,
            "matched_rod_count": int(support.get("matched_rod_count", 0) or 0),
            "query_effect_types": query_effects,
            "attempt_count": int(self._rod_action_binding_attempts),
            "applied_count": int(self._rod_action_binding_applied),
        }
        if not self._enable_rod_action_binding:
            payload["blocked_reason"] = "disabled"
            self._last_rod_action_binding = dict(payload)
            return payload

        self._rod_action_binding_attempts += 1
        payload["attempt_count"] = int(self._rod_action_binding_attempts)
        if action_payload_override is not None:
            payload["blocked_reason"] = "explicit_payload_override"
            self._last_rod_action_binding = dict(payload)
            return payload
        if protected_action:
            payload["blocked_reason"] = "protected_target_or_macro_action"
            self._last_rod_action_binding = dict(payload)
            return payload
        if family not in {
            "transition_probe",
            "navigation",
            "segment_transport",
            "click_affordance",
            "score_frontier",
        }:
            payload["blocked_reason"] = "unsupported_solver_family"
            self._last_rod_action_binding = dict(payload)
            return payload
        if not available or current not in available:
            payload["blocked_reason"] = "current_action_unavailable"
            self._last_rod_action_binding = dict(payload)
            return payload
        if int(support.get("matched_rod_count", 0) or 0) <= 0:
            payload["blocked_reason"] = "no_matching_rods"
            self._last_rod_action_binding = dict(payload)
            return payload

        action_scores = _rod_action_score_entries(support.get("matched_by_action"), available)
        payload["candidate_scores"] = action_scores[:6]
        if not action_scores:
            payload["blocked_reason"] = "no_supported_available_action"
            self._last_rod_action_binding = dict(payload)
            return payload
        current_entry = next(
            (entry for entry in action_scores if entry["action"] == current),
            {"action": current, "net": 0, "supported": 0, "contradicted": 0},
        )
        best = action_scores[0]
        selected = str(best.get("action") or "")
        payload["recommended_action"] = selected
        payload["recommended_net_support"] = int(best.get("net", 0) or 0)
        payload["current_net_support"] = int(current_entry.get("net", 0) or 0)
        score_support = self.rod_memory.retrieve(
            effect_types=["score_delta"],
            generic_keys=["effect:score_delta", "target_kind:score_precondition"],
            record_reuse=False,
        )
        score_action_scores = _rod_action_score_entries(
            score_support.get("matched_by_action"),
            available,
        )
        score_entry = next(
            (entry for entry in score_action_scores if entry["action"] == selected),
            {"action": selected, "net": 0, "supported": 0, "contradicted": 0},
        )
        payload["score_relevant_matched_rod_count"] = int(
            score_support.get("matched_rod_count", 0) or 0
        )
        payload["score_relevant_candidate_scores"] = score_action_scores[:6]
        payload["score_relevant_selected_net_support"] = int(score_entry.get("net", 0) or 0)
        if not selected or selected == current:
            payload["blocked_reason"] = "current_action_already_best"
            self._last_rod_action_binding = dict(payload)
            return payload
        if int(score_entry.get("net", 0) or 0) <= 0:
            payload["blocked_reason"] = "no_score_relevant_action_support"
            self._last_rod_action_binding = dict(payload)
            return payload
        if current == "ACTION6" and selected != "ACTION6":
            payload["blocked_reason"] = "click_action_requires_target_binding"
            self._last_rod_action_binding = dict(payload)
            return payload
        if not _rod_action_allowed_for_family(selected, family):
            payload["blocked_reason"] = "recommended_action_family_mismatch"
            self._last_rod_action_binding = dict(payload)
            return payload
        if not _rod_action_binding_context_is_exploratory(
            selection=selection,
            primitive_id=primitive_id,
            reason=reason,
        ):
            payload["blocked_reason"] = "non_exploratory_context"
            self._last_rod_action_binding = dict(payload)
            return payload

        best_supported = int(best.get("supported", 0) or 0)
        best_net = int(best.get("net", 0) or 0)
        current_net = int(current_entry.get("net", 0) or 0)
        current_supported = int(current_entry.get("supported", 0) or 0)
        current_contradicted = int(current_entry.get("contradicted", 0) or 0)
        rescue_from_contradiction = bool(
            best_supported >= 1
            and best_net > 0
            and current_contradicted > current_supported
            and best_net >= current_net + 2
        )
        if not rescue_from_contradiction:
            payload["blocked_reason"] = "insufficient_action_support_margin"
            self._last_rod_action_binding = dict(payload)
            return payload

        self._rod_action_binding_applied += 1
        payload.update(
            {
                "applied": True,
                "selected_action": selected,
                "previous_action": current,
                "blocked_reason": "",
                "applied_count": int(self._rod_action_binding_applied),
            }
        )
        self._last_rod_action_binding = dict(payload)
        return payload

    def _rod_action_binding_summary(self) -> dict[str, Any]:
        return {
            "enabled": bool(self._enable_rod_action_binding),
            "attempt_count": int(self._rod_action_binding_attempts),
            "applied_count": int(self._rod_action_binding_applied),
            "last": dict(self._last_rod_action_binding),
        }

    def _rod_target_binding_decision(
        self,
        selection: PrimitiveSelection,
        *,
        summary: Any,
        primitive_id: str,
        action_name: str,
        action_payload: Mapping[str, Any],
        available: set[str],
        protected_payload: bool,
        frame_shape: Iterable[int] | None,
        reason: str,
    ) -> dict[str, Any]:
        family = str(
            (selection.control_target or {}).get("solver_family", "")
            or _solver_family_for_primitive_id(primitive_id)
        )
        query_effects = sorted(
            set(_effect_types_for_primitive(primitive_id))
            | set(_effect_types_from_summary(summary))
        )
        support = self.rod_memory.retrieve(
            primitive_id=primitive_id,
            solver_family=family,
            effect_types=query_effects,
            record_reuse=False,
        )
        action = _normalize_action_name(action_name)
        current_site = _click_point_from_payload(action_payload) if action == "ACTION6" else None
        payload: dict[str, Any] = {
            "enabled": bool(self._enable_rod_target_binding),
            "applied": False,
            "primitive_id": str(primitive_id or ""),
            "solver_family": family,
            "action_name": action,
            "current_site": list(current_site) if current_site is not None else None,
            "selected_site": list(current_site) if current_site is not None else None,
            "matched_rod_count": int(support.get("matched_rod_count", 0) or 0),
            "query_effect_types": query_effects,
            "attempt_count": int(self._rod_target_binding_attempts),
            "applied_count": int(self._rod_target_binding_applied),
        }
        if not self._enable_rod_target_binding:
            payload["blocked_reason"] = "disabled"
            self._last_rod_target_binding = dict(payload)
            return payload

        self._rod_target_binding_attempts += 1
        payload["attempt_count"] = int(self._rod_target_binding_attempts)
        if action != "ACTION6" or "ACTION6" not in available:
            payload["blocked_reason"] = "non_click_action"
            self._last_rod_target_binding = dict(payload)
            return payload
        if protected_payload:
            payload["blocked_reason"] = "protected_payload"
            self._last_rod_target_binding = dict(payload)
            return payload
        if family not in {"transition_probe", "click_affordance", "score_frontier", "overlay"}:
            payload["blocked_reason"] = "unsupported_solver_family"
            self._last_rod_target_binding = dict(payload)
            return payload
        if current_site is None:
            payload["blocked_reason"] = "missing_current_site"
            self._last_rod_target_binding = dict(payload)
            return payload
        if int(support.get("matched_rod_count", 0) or 0) <= 0:
            payload["blocked_reason"] = "no_matching_rods"
            self._last_rod_target_binding = dict(payload)
            return payload
        if not _rod_action_binding_context_is_exploratory(
            selection=selection,
            primitive_id=primitive_id,
            reason=reason,
        ):
            payload["blocked_reason"] = "non_exploratory_context"
            self._last_rod_target_binding = dict(payload)
            return payload

        candidates = _rod_target_binding_entries_for_click(
            support.get("matched_target_bindings"),
            frame_shape=frame_shape,
        )
        payload["candidate_targets"] = candidates[:6]
        if not candidates:
            payload["blocked_reason"] = "no_supported_click_target"
            self._last_rod_target_binding = dict(payload)
            return payload
        current_key = ("click_point", int(current_site[0]), int(current_site[1]), "click")
        current_failures = int(self._target_failures[current_key])
        current_successes = int(self._target_successes[current_key])
        current_attempts = int(self._epoch_click_points[current_site])
        best = candidates[0]
        selected_site = best.get("site")
        if not isinstance(selected_site, list) or len(selected_site) < 2:
            payload["blocked_reason"] = "invalid_selected_site"
            self._last_rod_target_binding = dict(payload)
            return payload
        selected = (int(selected_site[0]), int(selected_site[1]))
        payload["recommended_site"] = [int(selected[0]), int(selected[1])]
        payload["recommended_net_support"] = int(best.get("net_support", 0) or 0)
        payload["current_site_attempt_count"] = current_attempts
        payload["current_failure_count"] = current_failures
        payload["current_success_count"] = current_successes
        if selected == current_site:
            payload["blocked_reason"] = "current_site_already_best"
            self._last_rod_target_binding = dict(payload)
            return payload
        selected_key = (
            str(best.get("target_kind", "") or "click_point"),
            int(selected[0]),
            int(selected[1]),
            str(best.get("operator", "") or "click"),
        )
        if int(self._target_failures[selected_key]) > int(self._target_successes[selected_key]):
            payload["blocked_reason"] = "selected_site_failed_locally"
            self._last_rod_target_binding = dict(payload)
            return payload
        if int(best.get("supported", 0) or 0) < 1 or int(best.get("net_support", 0) or 0) <= 0:
            payload["blocked_reason"] = "insufficient_target_support"
            self._last_rod_target_binding = dict(payload)
            return payload
        if current_failures <= current_successes and current_successes > 0:
            payload["blocked_reason"] = "current_site_has_success"
            self._last_rod_target_binding = dict(payload)
            return payload
        best_supported = int(best.get("supported", 0) or 0)
        score_bearing_target = bool(
            str(best.get("effect_type", "") or "") == "score_delta"
            or str(best.get("target_kind", "") or "") == "score_precondition"
        )
        required_support = 1 if score_bearing_target else 2
        if current_failures <= 0 and best_supported < required_support:
            payload["blocked_reason"] = "insufficient_target_support_margin"
            self._last_rod_target_binding = dict(payload)
            return payload

        self._rod_target_binding_applied += 1
        payload.update(
            {
                "applied": True,
                "selected_site": [int(selected[0]), int(selected[1])],
                "previous_site": [int(current_site[0]), int(current_site[1])],
                "target_kind": str(best.get("target_kind", "") or "click_point"),
                "blocked_reason": "",
                "applied_count": int(self._rod_target_binding_applied),
            }
        )
        self._last_rod_target_binding = dict(payload)
        return payload

    def _rod_target_binding_summary(self) -> dict[str, Any]:
        return {
            "enabled": bool(self._enable_rod_target_binding),
            "attempt_count": int(self._rod_target_binding_attempts),
            "applied_count": int(self._rod_target_binding_applied),
            "last": dict(self._last_rod_target_binding),
        }

    def _score_precondition_probe_actor_position(
        self,
        frame: np.ndarray,
        selection: PrimitiveSelection,
        *,
        actor_pos: tuple[int, int] | None,
    ) -> tuple[tuple[int, int] | None, str]:
        if actor_pos is not None:
            return actor_pos, "actor_value"
        control_target = dict(selection.control_target or {})
        primary = dict(control_target.get("primary_target") or {})
        if str(primary.get("kind", "") or "") != "score_precondition":
            return None, ""
        site = _site_tuple(primary.get("site"))
        if site is None:
            return None, ""
        proxy = self._mirror_joint_cursor_proxy_position(frame, site)
        if proxy is None:
            return None, ""
        return proxy, "mirror_joint_cursor"

    def _mirror_joint_cursor_proxy_position(
        self,
        frame: np.ndarray,
        site: tuple[int, int],
    ) -> tuple[int, int] | None:
        joint_state = _mirror_joint_cursor_state(frame)
        if joint_state is None:
            return None
        origin_x, origin_y = joint_state["origin"]
        cell = int(joint_state["cell"])
        if cell <= 0:
            return None
        cursors: list[tuple[int, int]] = []
        for key in ("cursor_a", "cursor_b"):
            cursor = joint_state.get(key)
            if not isinstance(cursor, tuple) or len(cursor) < 2:
                continue
            gx, gy = int(cursor[0]), int(cursor[1])
            cursors.append(
                (
                    int(origin_x) + gx * cell + cell // 2,
                    int(origin_y) + gy * cell + cell // 2,
                )
            )
        if not cursors:
            return None
        return min(cursors, key=lambda pos: _manhattan(pos, site))

    def _rod_score_precondition_action_decision(
        self,
        selection: PrimitiveSelection,
        available: set[str],
        *,
        actor_pos: tuple[int, int] | None,
        actor_pos_source: str = "",
        current_action: str,
        macro_solver_step: bool,
    ) -> dict[str, Any]:
        control_target = dict(selection.control_target or {})
        primary = dict(control_target.get("primary_target") or {})
        target_action = _normalize_action_name(primary.get("action_name"))
        site = _site_tuple(primary.get("site"))
        payload: dict[str, Any] = {
            "enabled": bool(
                self._enable_rod_target_binding
                and self._enable_rod_score_precondition_action
            ),
            "target_binding_enabled": bool(self._enable_rod_target_binding),
            "action_preemption_enabled": bool(self._enable_rod_score_precondition_action),
            "low_commitment_probe_enabled": bool(
                self._enable_rod_score_precondition_low_commitment_probe
            ),
            "applied": False,
            "current_action": _normalize_action_name(current_action),
            "selected_action": _normalize_action_name(current_action),
            "macro_solver_step": bool(macro_solver_step),
            "target_kind": str(primary.get("kind", "") or ""),
            "target_action": target_action,
            "target_site": list(site) if site is not None else None,
            "actor_pos": list(actor_pos) if actor_pos is not None else None,
            "actor_pos_source": str(actor_pos_source or ("actor_value" if actor_pos is not None else "")),
            "rod_supported": bool(primary.get("rod_supported")),
            "rod_net_support": int(primary.get("rod_net_support", 0) or 0),
            "low_commitment_probe_eligible": False,
            "low_commitment_probe_applied": False,
            "low_commitment_probe_blocked_reason": "",
            "commitment_level": "observe_only",
            "max_probe_steps": 0,
            "bailout_conditions": [],
            "suggested_probe_action": "",
            "attempt_count": int(self._rod_score_precondition_action_attempts),
            "applied_count": int(self._rod_score_precondition_action_applied),
        }
        if not self._enable_rod_target_binding:
            payload["blocked_reason"] = "disabled"
            self._last_rod_score_precondition_action = dict(payload)
            return payload
        if not self._enable_rod_score_precondition_action:
            payload["blocked_reason"] = "score_precondition_action_disabled"
            self._last_rod_score_precondition_action = dict(payload)
            return payload

        self._rod_score_precondition_action_attempts += 1
        payload["attempt_count"] = int(self._rod_score_precondition_action_attempts)
        if not macro_solver_step:
            payload["blocked_reason"] = "non_macro_context"
            self._last_rod_score_precondition_action = dict(payload)
            return payload
        if str(primary.get("kind", "") or "") != "score_precondition" or not bool(primary.get("rod_supported")):
            payload["blocked_reason"] = "no_rod_score_precondition_primary"
            self._last_rod_score_precondition_action = dict(payload)
            return payload
        if not target_action or target_action not in available:
            payload["blocked_reason"] = "target_action_unavailable"
            self._last_rod_score_precondition_action = dict(payload)
            return payload
        if int(primary.get("rod_net_support", 0) or 0) <= 0:
            payload["blocked_reason"] = "insufficient_rod_support"
            self._last_rod_score_precondition_action = dict(payload)
            return payload

        operator = str(control_target.get("primary_operator", "") or "")
        key_operator = operator or "click" if target_action == "ACTION6" else operator or "repeat_action"
        target_key = self._target_candidate_key(primary, operator=key_operator)
        local_successes = int(self._target_successes[target_key]) if target_key is not None else 0
        local_failures = int(self._target_failures[target_key]) if target_key is not None else 0
        score_successes = self._target_score_success_count(target_key) if target_key is not None else 0
        goal_successes = self._target_goal_success_count(target_key) if target_key is not None else 0
        progress_only_successes = (
            self._target_progress_only_success_count(target_key)
            if target_key is not None
            else 0
        )
        score_grounded_score_target = bool(score_successes > 0 or goal_successes > 0)
        local_grounding_source = "none"
        if score_successes > 0:
            local_grounding_source = "score_delta"
        elif goal_successes > 0:
            local_grounding_source = "goal_progress"
        elif progress_only_successes > 0 or local_successes > 0:
            local_grounding_source = "progress_only"
        payload.update(
            {
                "target_key": list(target_key) if target_key is not None else [],
                "local_success_count": local_successes,
                "local_failure_count": local_failures,
                "local_score_success_count": score_successes,
                "local_goal_success_count": goal_successes,
                "local_progress_only_success_count": progress_only_successes,
                "score_grounded_score_target": score_grounded_score_target,
                "local_grounding_source": local_grounding_source,
            }
        )
        locally_grounded_score_target = bool(local_successes > 0 or score_successes > 0)
        payload["locally_grounded_score_target"] = locally_grounded_score_target
        near_score_site = bool(
            actor_pos is not None
            and site is not None
            and _manhattan(actor_pos, site) <= 1
        )
        direct_score_attempt = bool(
            target_action == "ACTION6"
            or operator in {"repeat_action", "probe", ""}
            or (operator == "route_to" and near_score_site)
        )
        if (
            direct_score_attempt
            and local_failures > 0
            and score_successes <= 0
            and local_successes <= local_failures
        ):
            payload["blocked_reason"] = "score_target_failed_locally"
            self._last_rod_score_precondition_action = dict(payload)
            return payload
        if target_action != "ACTION6" and not locally_grounded_score_target:
            low_commitment_route_action = ""
            low_commitment_probe_blocked_reason = ""
            low_commitment_probe_eligible = True
            if operator not in {"route_to", "probe", "repeat_action", ""}:
                low_commitment_probe_eligible = False
                low_commitment_probe_blocked_reason = "unsupported_operator"
            elif actor_pos is None:
                low_commitment_probe_eligible = False
                low_commitment_probe_blocked_reason = "actor_position_unknown"
            elif site is None:
                low_commitment_probe_eligible = False
                low_commitment_probe_blocked_reason = "target_site_missing"
            elif _manhattan(actor_pos, site) <= 1:
                low_commitment_probe_eligible = False
                low_commitment_probe_blocked_reason = "already_near_target"
            elif target_action not in DIRECTIONAL_ACTIONS:
                low_commitment_probe_eligible = False
                low_commitment_probe_blocked_reason = "non_directional_target_action"
            elif local_failures > 0:
                low_commitment_probe_eligible = False
                low_commitment_probe_blocked_reason = "local_failure_present"
            if low_commitment_probe_eligible:
                low_commitment_route_action = self._control_target_route_action(
                    actor_pos,
                    selection,
                    available,
                    current_action="",
                )
                if not low_commitment_route_action and actor_pos is not None and site is not None:
                    ax, ay = actor_pos
                    tx, ty = site
                    horizontal = "ACTION4" if ax < tx else "ACTION3"
                    vertical = "ACTION2" if ay < ty else "ACTION1"
                    preferred = (
                        [horizontal, vertical]
                        if abs(ax - tx) >= abs(ay - ty)
                        else [vertical, horizontal]
                    )
                    for action in preferred:
                        if action in available and not self._actor_action_blocked(actor_pos, action):
                            low_commitment_route_action = action
                            break
                low_commitment_probe_eligible = bool(
                    low_commitment_route_action
                    and low_commitment_route_action in available
                )
                if not low_commitment_probe_eligible:
                    low_commitment_probe_blocked_reason = "no_route_probe_action"
            payload.update(
                {
                    "low_commitment_probe_eligible": low_commitment_probe_eligible,
                    "low_commitment_probe_blocked_reason": (
                        "" if low_commitment_probe_eligible else low_commitment_probe_blocked_reason
                    ),
                    "commitment_level": (
                        "probe_low" if low_commitment_probe_eligible else "observe_only"
                    ),
                    "max_probe_steps": 1 if low_commitment_probe_eligible else 0,
                    "bailout_conditions": (
                        [
                            "blocked",
                            "target_unreachable",
                            "unexpected_noop",
                            "score_delta",
                        ]
                        if low_commitment_probe_eligible
                        else []
                    ),
                    "suggested_probe_action": low_commitment_route_action,
                }
            )
            if (
                low_commitment_probe_eligible
                and self._enable_rod_score_precondition_low_commitment_probe
                and low_commitment_route_action != _normalize_action_name(current_action)
            ):
                self._rod_score_precondition_action_applied += 1
                payload.update(
                    {
                        "applied": True,
                        "low_commitment_probe_applied": True,
                        "selected_action": low_commitment_route_action,
                        "previous_action": _normalize_action_name(current_action),
                        "mode": "low_commitment_route_probe",
                        "blocked_reason": "",
                        "applied_count": int(self._rod_score_precondition_action_applied),
                    }
                )
                self._last_rod_score_precondition_action = dict(payload)
                return payload
            payload["blocked_reason"] = "score_target_unverified_locally"
            self._last_rod_score_precondition_action = dict(payload)
            return payload
        interact_action = bool(target_action == "ACTION5")
        strong_interact_support = bool(
            interact_action
            and int(primary.get("rod_supported_count", 0) or 0) >= 2
            and int(primary.get("rod_net_support", 0) or 0) >= 2
            and local_failures <= local_successes
        )
        if (
            target_action != "ACTION6"
            and target_action not in DIRECTIONAL_ACTIONS
            and not strong_interact_support
        ):
            payload["blocked_reason"] = "unsupported_score_target_action"
            self._last_rod_score_precondition_action = dict(payload)
            return payload
        if strong_interact_support:
            payload["strong_interact_support"] = True
        selected_action = ""
        action_payload: dict[str, Any] | None = None
        mode = ""
        if target_action == "ACTION6" and site is not None:
            selected_action = "ACTION6"
            action_payload = {"x": int(site[0]), "y": int(site[1])}
            mode = "click_score_site"
        elif operator == "route_to" and actor_pos is not None and site is not None:
            if _manhattan(actor_pos, site) <= 1:
                selected_action = target_action
                mode = "repeat_score_action_at_site"
            else:
                route_action = self._control_target_route_action(
                    actor_pos,
                    selection,
                    available,
                    current_action="",
                )
                if route_action:
                    selected_action = route_action
                    mode = "route_to_score_site"
        elif operator in {"repeat_action", "probe", ""}:
            selected_action = target_action
            mode = "repeat_score_action"

        if not selected_action or selected_action not in available:
            payload["blocked_reason"] = "no_executable_score_target_action"
            self._last_rod_score_precondition_action = dict(payload)
            return payload

        if (
            selected_action == _normalize_action_name(current_action)
            and action_payload is None
        ):
            payload.update(
                {
                    "selected_action": selected_action,
                    "mode": mode,
                    "blocked_reason": "current_action_already_matches",
                }
            )
            self._last_rod_score_precondition_action = dict(payload)
            return payload

        progress_only_direct_score_probe = bool(
            self._enable_rod_score_precondition_low_commitment_probe
            and target_action != "ACTION6"
            and selected_action == target_action
            and mode in {"repeat_score_action", "repeat_score_action_at_site"}
            and locally_grounded_score_target
            and not score_grounded_score_target
            and local_grounding_source == "progress_only"
        )
        self._rod_score_precondition_action_applied += 1
        if progress_only_direct_score_probe:
            mode = "low_commitment_score_action_probe"
        payload.update(
            {
                "applied": True,
                "selected_action": selected_action,
                "previous_action": _normalize_action_name(current_action),
                "mode": mode,
                "action_payload": dict(action_payload or {}),
                "blocked_reason": "",
                "low_commitment_probe_eligible": bool(
                    payload.get("low_commitment_probe_eligible")
                    or progress_only_direct_score_probe
                ),
                "low_commitment_probe_applied": bool(
                    payload.get("low_commitment_probe_applied")
                    or progress_only_direct_score_probe
                ),
                "commitment_level": (
                    "probe_low"
                    if progress_only_direct_score_probe
                    else str(payload.get("commitment_level", "") or "observe_only")
                ),
                "max_probe_steps": (
                    1
                    if progress_only_direct_score_probe
                    else int(payload.get("max_probe_steps", 0) or 0)
                ),
                "bailout_conditions": (
                    [
                        "unexpected_noop",
                        "score_delta",
                        "target_contradiction",
                    ]
                    if progress_only_direct_score_probe
                    else list(payload.get("bailout_conditions") or [])
                ),
                "suggested_probe_action": (
                    selected_action
                    if progress_only_direct_score_probe
                    else str(payload.get("suggested_probe_action", "") or "")
                ),
                "applied_count": int(self._rod_score_precondition_action_applied),
            }
        )
        self._last_rod_score_precondition_action = dict(payload)
        return payload

    def _rod_score_precondition_action_summary(self) -> dict[str, Any]:
        return {
            "enabled": bool(
                self._enable_rod_target_binding
                and self._enable_rod_score_precondition_action
            ),
            "target_binding_enabled": bool(self._enable_rod_target_binding),
            "action_preemption_enabled": bool(self._enable_rod_score_precondition_action),
            "low_commitment_probe_enabled": bool(
                self._enable_rod_score_precondition_low_commitment_probe
            ),
            "attempt_count": int(self._rod_score_precondition_action_attempts),
            "applied_count": int(self._rod_score_precondition_action_applied),
            "last": dict(self._last_rod_score_precondition_action),
        }

    def _frontier_actions(
        self,
        state_hash: str,
        available: set[str],
        *,
        preferred_actions: Iterable[str] | None = None,
    ) -> list[str]:
        preferred = [_normalize_action_name(action) for action in (preferred_actions or self.action_order)]
        ordered = [action for action in preferred if action in available]
        attempts = self._state_action_attempts.get(state_hash, Counter())
        return [action for action in ordered if attempts[action] <= 0]

    def _frontier_or_probe(
        self,
        state_hash: str,
        selection: PrimitiveSelection,
        available: set[str],
        *,
        preferred_actions: Iterable[str] | None = None,
    ) -> tuple[str, bool]:
        frontier = self._frontier_actions(state_hash, available, preferred_actions=preferred_actions)
        if frontier:
            return _least_issued(frontier, self._issued_counts), True
        return self._probe_action(selection, available), False

    def _primitive_action_lockin_escape(
        self,
        primitive_id: str,
        action_name: str,
        available: set[str],
    ) -> str | None:
        if str(primitive_id or "") in set(CYCLE_CONSTRAINT_PRIMITIVE_ORDER):
            return None
        if len(self._recent_primitive_actions) < 10:
            return None
        recent = list(self._recent_primitive_actions)[-10:]
        repeated = sum(
            1
            for primitive, action in recent
            if primitive == primitive_id and action == action_name
        )
        if repeated < 9:
            return None
        candidates = [
            action
            for action in self.action_order
            if action in available and action != action_name
        ]
        if not candidates:
            return None
        # Keep deterministic, but rotate away from the repeated action toward
        # the least-issued alternative in the same visible action set.
        return _least_issued(candidates, self._issued_counts)

    def _selection_with_actor_context(
        self,
        selection: PrimitiveSelection,
        actor_pos: tuple[int, int] | None,
    ) -> PrimitiveSelection:
        control_target = dict(selection.control_target or {})
        operator = str(control_target.get("primary_operator", "") or "")
        if actor_pos is not None or operator not in {"route_to", "push"}:
            return selection
        target_candidates = [
            dict(candidate)
            for candidate in list(control_target.get("target_candidates") or [])
            if isinstance(candidate, dict)
        ]
        action_targets = [
            candidate
            for candidate in target_candidates
            if _normalize_action_name(candidate.get("action_name"))
        ]
        operator_candidates = [
            dict(item)
            for item in list(control_target.get("operator_candidates") or [])
            if isinstance(item, dict)
        ]
        uncertainty = list(selection.uncertainty_reasons)
        uncertainty.append("actor_unlocalized_for_route_operator")
        if action_targets:
            operator_candidates = [
                {
                    "operator": "repeat_action",
                    "confidence": 0.55,
                    "reason": "actor is unlocalized; retest target candidate's observed action instead of routing",
                },
                *[
                    item
                    for item in operator_candidates
                    if str(item.get("operator", "") or "") != "repeat_action"
                ],
            ]
            control_target["primary_operator"] = "repeat_action"
            control_target["primary_target"] = dict(action_targets[0])
        else:
            operator_candidates = [
                {
                    "operator": "probe",
                    "confidence": 0.35,
                    "reason": "actor is unlocalized and route target has no executable action evidence",
                },
                *[
                    item
                    for item in operator_candidates
                    if str(item.get("operator", "") or "") != "probe"
                ],
            ]
            control_target["primary_operator"] = "probe"
        control_target["operator_candidates"] = operator_candidates
        control_target["uncertainty_reasons"] = list(control_target.get("uncertainty_reasons") or []) + [
            "actor_unlocalized_for_route_operator"
        ]
        return replace(
            selection,
            uncertainty_reasons=uncertainty,
            control_target=control_target,
        )

    def _selection_with_score_precondition_context(
        self,
        selection: PrimitiveSelection,
        available: set[str],
        actor_pos: tuple[int, int] | None,
    ) -> PrimitiveSelection:
        local_precondition_targets = self._score_precondition_target_candidates(available)
        rod_precondition_targets = (
            self._rod_score_precondition_target_candidates(available)
            if self._enable_rod_target_binding
            else []
        )
        precondition_targets = _merge_score_precondition_target_candidates(
            local_precondition_targets,
            rod_precondition_targets,
        )
        precondition_targets = _rank_score_precondition_target_candidates(precondition_targets)
        if not precondition_targets:
            return selection
        control_target = dict(selection.control_target or {})
        existing_targets = [
            dict(candidate)
            for candidate in list(control_target.get("target_candidates") or [])
            if isinstance(candidate, dict)
        ]
        merged_targets = _dedupe_target_candidates(precondition_targets + existing_targets)
        primary = dict(precondition_targets[0])
        operator = "repeat_action"
        site = primary.get("site")
        action_name = _normalize_action_name(primary.get("action_name"))
        if bool(primary.get("rod_supported")) and action_name == "ACTION6":
            operator = "probe"
        if (
            actor_pos is not None
            and isinstance(site, (list, tuple))
            and len(site) >= 2
            and operator != "probe"
        ):
            try:
                target = (int(site[0]), int(site[1]))
            except (TypeError, ValueError):
                target = actor_pos
            if _manhattan(actor_pos, target) > 1:
                operator = "route_to"
        if operator == "repeat_action" and action_name not in available:
            operator = "probe"
        operator_candidates = [
            {
                "operator": operator,
                "confidence": 0.85,
                "reason": "prior positive-score precondition is available",
            },
            {
                "operator": "repeat_action",
                "confidence": 0.75,
                "reason": "retest action that previously produced score",
            },
            {
                "operator": "route_to",
                "confidence": 0.55,
                "reason": "route back to prior score precondition actor/site",
            },
        ]
        control_target.update(
            {
                "target_candidates": merged_targets,
                "primary_target": primary,
                "operator_candidates": _dedupe_operator_candidates(operator_candidates),
                "primary_operator": operator,
                "rod_score_precondition_candidate_count": len(rod_precondition_targets),
                "rod_score_precondition_candidates": rod_precondition_targets[:6],
            }
        )
        if action_name:
            next_probe_actions = [
                _normalize_action_name(action)
                for action in [action_name, *list(control_target.get("next_probe_actions") or [])]
            ]
            control_target["next_probe_actions"] = [
                action for action in _dedupe_action_names(next_probe_actions) if action in available
            ]
        uncertainty = list(selection.uncertainty_reasons)
        uncertainty.append("score_precondition_available")
        if bool(primary.get("rod_supported")):
            uncertainty.append("rod_score_precondition_available")
        control_target["uncertainty_reasons"] = list(control_target.get("uncertainty_reasons") or []) + [
            "score_precondition_available"
        ]
        if bool(primary.get("rod_supported")):
            control_target["uncertainty_reasons"] = list(control_target.get("uncertainty_reasons") or []) + [
                "rod_score_precondition_available"
            ]
        promoted_primitive = str(selection.primary_primitive or "")
        promoted_confidence = float(selection.confidence)
        promoted_should_probe = bool(selection.should_probe)
        if (
            bool(primary.get("rod_supported"))
            and action_name == "ACTION6"
            and _rod_action_binding_context_is_exploratory(
                selection=selection,
                primitive_id=promoted_primitive,
                reason="rod_score_precondition_available",
            )
        ):
            net_support = int(primary.get("rod_net_support", 0) or 0)
            promoted_primitive = "score_delta_frontier_search"
            promoted_confidence = max(
                promoted_confidence,
                min(0.62, 0.50 + 0.04 * float(max(1, net_support))),
            )
            promoted_should_probe = True
        return replace(
            selection,
            primary_primitive=promoted_primitive,
            confidence=promoted_confidence,
            should_probe=promoted_should_probe,
            uncertainty_reasons=uncertainty,
            control_target=control_target,
        )

    def _selection_with_control_panel_lease_context(
        self,
        selection: PrimitiveSelection,
        actor_pos: tuple[int, int] | None,
    ) -> PrimitiveSelection:
        candidates = self._control_panel_lease_candidates(actor_pos)
        if not candidates:
            return selection
        control_target = dict(selection.control_target or {})
        existing_targets = [
            dict(candidate)
            for candidate in list(control_target.get("target_candidates") or [])
            if isinstance(candidate, dict)
        ]
        merged_targets = _dedupe_target_candidates(candidates + existing_targets)
        ranked = self._rank_control_target_candidates(merged_targets, operator="route_to")
        lease_ranked = [
            dict(candidate)
            for candidate in ranked
            if str(candidate.get("kind", "") or "") == "control_panel_lease_route"
        ]
        if not lease_ranked:
            return selection
        primary = lease_ranked[0]
        operator_candidates = _dedupe_operator_candidates(
            [
                {
                    "operator": "route_to",
                    "confidence": 0.72,
                    "reason": "post-score click topology opened a candidate control-panel route continuation",
                },
                *[
                    dict(item)
                    for item in list(control_target.get("operator_candidates") or [])
                    if isinstance(item, dict)
                ],
            ]
        )
        control_target.update(
            {
                "target_candidates": merged_targets,
                "primary_target": primary,
                "primary_operator": "route_to",
                "operator_candidates": operator_candidates,
                "solver_family": "navigation",
                "control_panel_lease_polarity_posterior": (
                    self._control_panel_lease_polarity_summary(
                        actor_pos=actor_pos,
                        candidates=candidates,
                    )
                ),
            }
        )
        self._record_control_panel_lease_checkpoint_attempt(control_target)
        uncertainty = list(selection.uncertainty_reasons)
        uncertainty.append("control_panel_lease_route_available")
        control_target["uncertainty_reasons"] = list(control_target.get("uncertainty_reasons") or []) + [
            "control_panel_lease_route_available"
        ]
        return replace(
            selection,
            confidence=max(float(selection.confidence), 0.58),
            uncertainty_reasons=uncertainty,
            control_target=control_target,
        )

    def _selection_with_goal_target_contract_context(
        self,
        selection: PrimitiveSelection,
    ) -> PrimitiveSelection:
        control_target = dict(selection.control_target or {})
        contract = self._goal_target_contract(control_target)
        objectives = [
            dict(candidate)
            for candidate in list(contract.get("objective_candidates") or [])
            if isinstance(candidate, dict)
        ]
        if objectives:
            existing_targets = [
                dict(candidate)
                for candidate in list(control_target.get("target_candidates") or [])
                if isinstance(candidate, dict)
            ]
            control_target["target_candidates"] = _dedupe_target_candidates(objectives + existing_targets)
            control_target["primary_target"] = dict(objectives[0])
        control_target["goal_target_contract"] = contract
        return replace(selection, control_target=control_target)

    def _goal_target_contract(self, control_target: Mapping[str, Any]) -> dict[str, Any]:
        solver_family = str(control_target.get("solver_family", "") or "unknown")
        objectives = _goal_target_objective_candidates(control_target)
        goal_objectives = [item for item in objectives if bool(item.get("goal_bearing"))]
        if goal_objectives:
            status = "goal_objective_bound"
        elif objectives:
            status = "progress_objective_only"
        else:
            status = "missing_objective"
        return {
            "schema_version": "eca_goal_target_contract.v1",
            "solver_family": solver_family,
            "target_translation_status": status,
            "success_predicates": _goal_success_predicates_for_family(solver_family),
            "objective_candidate_count": int(len(objectives)),
            "goal_objective_candidate_count": int(len(goal_objectives)),
            "requires_goal_progress": bool(solver_family != "transition_probe"),
            "primary_objective": dict(objectives[0]) if objectives else {},
            "objective_candidates": objectives[:6],
        }

    def _selection_with_stale_operator_context(
        self,
        selection: PrimitiveSelection,
        available: set[str],
    ) -> PrimitiveSelection:
        control_target = dict(selection.control_target or {})
        operator = str(control_target.get("primary_operator", "") or "")
        if operator not in {"repeat_action", "click", "probe", "route_to", "push", "attach", "drop"}:
            return selection
        progress_stale = (
            operator in {"route_to", "push", "attach", "drop"}
            and self._operator_progress_stale(operator)
            and not self._control_panel_lease_route_stale_override(control_target)
        )
        if operator in {"route_to", "push", "attach", "drop"} and not progress_stale:
            return selection
        ranked = [] if progress_stale else self._rank_control_target_candidates(
            list(control_target.get("target_candidates") or []),
            operator=operator,
        )
        if ranked:
            return selection
        existing_targets = [
            dict(candidate)
            for candidate in list(control_target.get("target_candidates") or [])
            if isinstance(candidate, dict)
        ]
        if not existing_targets:
            return selection
        probe_actions = [
            action
            for action in self.action_order
            if action in available and self._epoch_observed_counts[action] <= 0
        ]
        if not probe_actions:
            probe_actions = [
                action
                for action in self.action_order
                if action in available and not self._operator_action_stale("probe", action)
            ]
        control_target["primary_operator"] = "probe"
        control_target["operator_candidates"] = _dedupe_operator_candidates(
            [
                {
                    "operator": "probe",
                    "confidence": 0.50,
                    "reason": "all target actions for prior operator are stale; return to frontier probing",
                },
                *[
                    item
                    for item in list(control_target.get("operator_candidates") or [])
                    if isinstance(item, dict)
                ],
            ]
        )
        if probe_actions:
            control_target["next_probe_actions"] = probe_actions
        uncertainty = list(selection.uncertainty_reasons)
        uncertainty.append("stale_operator_candidates_exhausted")
        control_target["uncertainty_reasons"] = list(control_target.get("uncertainty_reasons") or []) + [
            "stale_operator_candidates_exhausted"
        ]
        return replace(
            selection,
            should_probe=True,
            uncertainty_reasons=uncertainty,
            control_target=control_target,
        )

    def _selection_with_solver_family_budget_context(
        self,
        selection: PrimitiveSelection,
    ) -> PrimitiveSelection:
        control_target = dict(selection.control_target or {})
        current_family = str(control_target.get("solver_family", "") or "")
        if not current_family:
            current_family = _solver_family_for_primitive_id(selection.primary_primitive)
        if not self._solver_family_unproductive(current_family):
            return selection

        exhausted = {
            family
            for family in SOLVER_FAMILY_BUDGET_THRESHOLDS
            if self._solver_family_unproductive(family)
        }
        replacement_options: list[tuple[int, int, float, PrimitiveCandidate, dict[str, Any]]] = []
        for candidate in selection.candidates:
            primitive_id = str(candidate.primitive_id or "")
            if not self._primitive_enabled(primitive_id):
                continue
            family = _solver_family_for_primitive_id(primitive_id)
            if family in exhausted or family == current_family or family == "unknown":
                continue
            candidate_target = dict(control_target)
            candidate_target.update(
                {
                    "primitive_id": primitive_id,
                    "primitive_scope": primitive_scope(primitive_id),
                    "solver_family": family,
                    "confidence": float(candidate.confidence),
                    "next_probe_actions": list(candidate.next_probe_actions),
                    "required_evidence": list(candidate.required_evidence),
                    "source_labels": list(candidate.source_labels),
                    "primary_operator": _default_operator_for_solver_family(family),
                    "solver_family_budget": self._solver_family_budget_summary(),
                }
            )
            contract = self._goal_target_contract(candidate_target)
            candidate_target["goal_target_contract"] = contract
            replacement_options.append(
                (
                    _goal_target_contract_status_rank(
                        str(contract.get("target_translation_status", "") or "")
                    ),
                    int(candidate.priority),
                    -float(candidate.confidence),
                    candidate,
                    candidate_target,
                )
            )

        replacement_options.sort(key=lambda item: (item[0], item[1], item[2], str(item[3].primitive_id)))
        replacement = replacement_options[0][3] if replacement_options else None
        replacement_control_target = replacement_options[0][4] if replacement_options else None

        uncertainty = list(selection.uncertainty_reasons)
        reason = (
            f"solver_family_budget_exhausted:{current_family}"
            if self._solver_family_score_exhausted(current_family)
            else f"solver_family_unproductive:{current_family}"
        )
        uncertainty.append(reason)
        control_target["uncertainty_reasons"] = list(control_target.get("uncertainty_reasons") or []) + [reason]

        if replacement is None:
            control_target.update(
                {
                    "primitive_id": "action_loop_probe",
                    "primitive_scope": primitive_scope("action_loop_probe"),
                    "solver_family": "transition_probe",
                    "primary_operator": "probe",
                    "next_probe_actions": [
                        action
                        for action in self.action_order
                        if not self._operator_action_stale("probe", action)
                    ],
                    "solver_family_budget": self._solver_family_budget_summary(),
                }
            )
            control_target["goal_target_contract"] = self._goal_target_contract(control_target)
            return replace(
                selection,
                primary_primitive="action_loop_probe",
                confidence=min(float(selection.confidence), 0.35),
                should_probe=True,
                uncertainty_reasons=uncertainty,
                control_target=control_target,
            )

        control_target.update(dict(replacement_control_target or {}))
        return replace(
            selection,
            primary_primitive=str(replacement.primitive_id),
            confidence=float(replacement.confidence),
            should_probe=True,
            uncertainty_reasons=uncertainty,
            control_target=control_target,
        )

    def _score_precondition_target_candidates(self, available: set[str]) -> list[dict[str, Any]]:
        candidates: list[dict[str, Any]] = []
        for item in reversed(self._score_preconditions[-8:]):
            item_epoch = int(item.get("epoch_id", self._epoch_id) or 0)
            if item_epoch != int(self._epoch_id):
                continue
            action_name = _normalize_action_name(item.get("action_name"))
            if action_name and action_name not in available:
                continue
            site = item.get("action_site") if action_name == "ACTION6" else item.get("actor_pos")
            if not isinstance(site, (list, tuple)) or len(site) < 2:
                site = item.get("actor_pos")
            if not isinstance(site, (list, tuple)) or len(site) < 2:
                bbox = item.get("changed_bbox")
                if isinstance(bbox, dict):
                    try:
                        site = [
                            int(round((float(bbox["min_x"]) + float(bbox["max_x"])) / 2.0)),
                            int(round((float(bbox["min_y"]) + float(bbox["max_y"])) / 2.0)),
                        ]
                    except (KeyError, TypeError, ValueError):
                        site = None
            if not isinstance(site, (list, tuple)) or len(site) < 2:
                continue
            try:
                x = int(site[0])
                y = int(site[1])
            except (TypeError, ValueError):
                continue
            candidate = {
                "kind": "score_precondition",
                "site": [x, y],
                "action_name": action_name,
                "score_delta": int(item.get("score_delta", 1) or 1),
                "goal_likelihood": 1.0,
                "epoch_id": item_epoch,
                "transition_kind": str(item.get("transition_kind", "") or ""),
                "local_patch_hash": str(item.get("local_patch_hash", "") or ""),
            }
            if self._score_precondition_direct_probe_failure_count(candidate) > 0:
                continue
            candidates.append(
                candidate
            )
        return candidates

    def _rod_score_precondition_target_candidates(self, available: set[str]) -> list[dict[str, Any]]:
        support = self.rod_memory.retrieve(
            effect_types=["score_delta"],
            record_reuse=False,
        )
        raw_targets = support.get("matched_target_bindings")
        if not isinstance(raw_targets, list):
            return []
        candidates: list[dict[str, Any]] = []
        for raw in raw_targets:
            if not isinstance(raw, Mapping):
                continue
            effect_type = str(raw.get("effect_type", "") or "")
            target_kind = str(raw.get("target_kind", "") or "")
            if effect_type != "score_delta" and target_kind != "score_precondition":
                continue
            action_name = _normalize_action_name(raw.get("action_name"))
            if action_name and action_name not in available:
                continue
            site = raw.get("site")
            if not isinstance(site, (list, tuple)) or len(site) < 2:
                continue
            try:
                x = int(site[0])
                y = int(site[1])
            except (TypeError, ValueError):
                continue
            supported = int(raw.get("supported", 0) or 0)
            contradicted = int(raw.get("contradicted", 0) or 0)
            inconclusive = int(raw.get("inconclusive", 0) or 0)
            net_support = int(raw.get("net_support", supported - contradicted) or 0)
            if supported <= 0 or net_support <= 0:
                continue
            candidate = {
                "kind": "score_precondition",
                "site": [x, y],
                "action_name": action_name,
                "score_delta": 1,
                "goal_likelihood": 1.0,
                "transition_kind": "rod_score_delta",
                "binding_source": str(raw.get("binding_source", "") or "rod_memory"),
                "rod_supported": True,
                "rod_target_key": str(raw.get("target_key", "") or ""),
                "rod_supported_count": supported,
                "rod_contradicted_count": contradicted,
                "rod_inconclusive_count": inconclusive,
                "rod_net_support": net_support,
                "rod_score": float(raw.get("score", net_support) or 0.0),
            }
            if self._score_precondition_direct_probe_failure_count(candidate) > 0:
                continue
            candidates.append(
                candidate
            )
        candidates.sort(
            key=lambda item: (
                -float(item.get("rod_score", 0.0) or 0.0),
                -int(item.get("rod_supported_count", 0) or 0),
                int(item.get("rod_contradicted_count", 0) or 0),
                str(item.get("action_name", "") or ""),
                list(item.get("site") or []),
            )
        )
        return candidates

    def _control_target_route_action(
        self,
        actor_pos: tuple[int, int] | None,
        selection: PrimitiveSelection,
        available: set[str],
        *,
        current_action: str,
    ) -> str | None:
        if actor_pos is None:
            return None
        control_target = dict(selection.control_target or {})
        solver_family = str(control_target.get("solver_family", "") or "")
        if solver_family not in {"navigation", "segment_transport", "push_object", "attach_transport", "transition_probe"}:
            return None
        primary_operator = str(control_target.get("primary_operator", "") or "route_to")
        if primary_operator not in {"route_to", "push", "attach", "drop"}:
            return None
        if self._operator_progress_stale(
            primary_operator
        ) and not self._control_panel_lease_route_stale_override(control_target):
            return None
        candidates = self._rank_control_target_candidates(
            list(control_target.get("target_candidates") or []),
            operator=primary_operator,
        )
        if not candidates:
            return None
        scored: list[tuple[int, int, int, str]] = []
        ax, ay = actor_pos
        for candidate in candidates[:6]:
            site = candidate.get("site") if isinstance(candidate, dict) else None
            if not isinstance(site, (list, tuple)) or len(site) < 2:
                continue
            try:
                tx = int(site[0])
                ty = int(site[1])
            except (TypeError, ValueError):
                continue
            if abs(ax - tx) <= 1 and abs(ay - ty) <= 1:
                continue
            horizontal = "ACTION4" if ax < tx else "ACTION3"
            vertical = "ACTION2" if ay < ty else "ACTION1"
            preferred = (
                [horizontal, vertical]
                if abs(ax - tx) >= abs(ay - ty)
                else [vertical, horizontal]
            )
            for action in preferred:
                if action not in available or action == current_action:
                    continue
                if self._actor_action_blocked(actor_pos, action):
                    continue
                distance = abs(ax - tx) + abs(ay - ty)
                score_delta = int(candidate.get("score_delta", 0) or 0)
                scored.append((-score_delta, distance, self._issued_counts[action], action))
                break
        if not scored:
            return None
        scored.sort()
        return scored[0][3]

    def _control_panel_lease_preferred_route_action(
        self,
        actor_pos: tuple[int, int],
        selection: PrimitiveSelection,
        available: set[str],
        *,
        current_action: str,
    ) -> str | None:
        if not self._control_panel_lease_polarity_posterior_enabled():
            return None
        control_target = dict(selection.control_target or {})
        if str(control_target.get("primary_operator", "") or "") != "route_to":
            return None
        primary = control_target.get("primary_target")
        if not isinstance(primary, Mapping):
            return None
        if str(primary.get("kind", "") or "") != "control_panel_lease_route":
            return None
        return self._control_target_route_action(
            actor_pos,
            selection,
            available,
            current_action=current_action,
        )

    def _movement_click_affordance_probe_before_route(
        self,
        selection: PrimitiveSelection,
        available: set[str],
        *,
        current_action: str,
    ) -> bool:
        if "ACTION6" not in available:
            return False
        if self._epoch_observed_counts["ACTION6"] > 0:
            return False
        control_target = dict(selection.control_target or {})
        if str(control_target.get("solver_family", "") or "") != "navigation":
            return False
        if str(control_target.get("classification_label", "") or "") != "movement_game":
            return False
        if str(control_target.get("primary_operator", "") or "") != "route_to":
            return False
        candidates = [
            dict(candidate)
            for candidate in list(control_target.get("target_candidates") or [])
            if isinstance(candidate, dict)
        ]
        if any(int(candidate.get("score_delta", 0) or 0) > 0 for candidate in candidates):
            return False
        if any(float(candidate.get("goal_likelihood", 0.0) or 0.0) >= 0.5 for candidate in candidates):
            return False
        recent_navigation = [
            item
            for item in self._target_verification_history[-12:]
            if str(item.get("solver_family", "") or "") == "navigation"
        ]
        if len(recent_navigation) < 4:
            directional_count = sum(self._epoch_observed_counts[action] for action in DIRECTIONAL_ACTIONS)
            if directional_count < 5:
                return False
        if any(
            bool(item.get("goal_progress")) or int(item.get("score_delta", 0) or 0) > 0
            for item in recent_navigation
        ):
            return False
        scoreless_visible = sum(
            1
            for item in recent_navigation
            if (bool(item.get("progressed")) or bool(item.get("objective_progress")))
            and int(item.get("score_delta", 0) or 0) <= 0
        )
        return scoreless_visible >= 3

    def _control_target_operator_action(
        self,
        selection: PrimitiveSelection,
        available: set[str],
    ) -> tuple[str, dict[str, Any] | None] | None:
        control_target = dict(selection.control_target or {})
        operator = str(control_target.get("primary_operator", "") or "")
        ranked_targets = self._rank_control_target_candidates(
            list(control_target.get("target_candidates") or []),
            operator=operator or "route_to",
        )
        primary_target = dict(ranked_targets[0]) if ranked_targets else dict(control_target.get("primary_target") or {})
        if operator == "click":
            if "ACTION6" not in available:
                return None
            site = primary_target.get("site")
            if not isinstance(site, (list, tuple)) or len(site) < 2:
                return None
            try:
                x = int(site[0])
                y = int(site[1])
            except (TypeError, ValueError):
                return None
            return "ACTION6", {"x": x, "y": y}
        if operator == "repeat_action":
            if self._operator_progress_stale(operator):
                return None
            action_name = _normalize_action_name(primary_target.get("action_name"))
            if action_name in available:
                return action_name, None
        if operator in {"attach", "drop"}:
            if self._operator_progress_stale(operator):
                return None
            for action_name in ("ACTION5", "ACTION6"):
                if action_name in available:
                    return action_name, None
        return None

    def _segment_transport_probe_action(
        self,
        selection: PrimitiveSelection,
        available: set[str],
    ) -> str | None:
        if self._solver_family_unproductive("segment_transport"):
            return None
        control_target = dict(selection.control_target or {})
        candidates: list[str] = []
        group = dict(control_target.get("primary_segment_motion_group") or {})
        group_action = _normalize_action_name(group.get("action_name"))
        if group_action:
            candidates.append(group_action)
        primary_target = dict(control_target.get("primary_target") or {})
        target_action = _normalize_action_name(primary_target.get("action_name"))
        if target_action:
            candidates.append(target_action)
        for action_name in list(control_target.get("next_probe_actions") or []):
            action = _normalize_action_name(action_name)
            if action:
                candidates.append(action)
        for action in candidates:
            if action not in available:
                continue
            if self._segment_transport_action_unproductive(action):
                continue
            if self._operator_action_stale("repeat_action", action, threshold=6):
                continue
            return action
        return None

    def _control_target_click_payload(
        self,
        selection: PrimitiveSelection,
        action_name: str,
        *,
        frame: np.ndarray | None = None,
    ) -> dict[str, int] | None:
        if action_name != "ACTION6":
            return None
        control_target = dict(selection.control_target or {})
        if str(control_target.get("primary_operator", "") or "") != "click":
            return None
        ranked_targets = self._rank_control_target_candidates(
            list(control_target.get("target_candidates") or []),
            operator="click",
        )
        primary_target = dict(ranked_targets[0]) if ranked_targets else dict(control_target.get("primary_target") or {})
        site = primary_target.get("site")
        if not isinstance(site, (list, tuple)) or len(site) < 2:
            return None
        try:
            site_xy = (int(site[0]), int(site[1]))
        except (TypeError, ValueError):
            return None
        if self._button_cycle_target_noop_alignment_veto_enabled():
            target_kind = str(primary_target.get("kind", "") or "")
            mechanic_state_type = str(primary_target.get("mechanic_state_type", "") or "")
            if (
                target_kind == "button_cycle_target"
                or mechanic_state_type == "button_cycle_rotation"
            ) and self._state_click_noop_vetoed(frame, site_xy):
                return None
        return {"x": int(site_xy[0]), "y": int(site_xy[1])}

    def _state_click_noop_vetoed(
        self,
        frame: np.ndarray | None,
        site: tuple[int, int],
    ) -> bool:
        if frame is None:
            return False
        state_hash = frame_state_hash(frame)
        click_key = (state_hash, (int(site[0]), int(site[1])))
        attempts = int(self._state_click_attempts.get(click_key, 0) or 0)
        noop = int(self._state_click_noop.get(click_key, 0) or 0)
        changed = int(self._state_click_changed.get(click_key, 0) or 0)
        score_delta = int(self._state_click_score_delta.get(click_key, 0) or 0)
        min_attempts = self._button_cycle_target_noop_alignment_veto_min_attempts()
        return bool(
            attempts >= min_attempts
            and noop >= min_attempts
            and changed <= 0
            and score_delta <= 0
        )

    def _button_cycle_noop_veto_sites(self, frame: np.ndarray) -> set[tuple[int, int]]:
        if not self._button_cycle_target_noop_alignment_veto_enabled():
            return set()
        state = _button_cycle_rotation_state(frame)
        if not isinstance(state, Mapping):
            return set()
        sites: set[tuple[int, int]] = set()
        for step in _bounded_plan_from_steps(state.get("operation_plan") or (), max_len=4):
            payload = step.get("payload") if isinstance(step.get("payload"), Mapping) else {}
            try:
                sites.add((int(payload["x"]), int(payload["y"])))
            except (KeyError, TypeError, ValueError):
                continue
        return {
            site
            for site in sites
            if self._state_click_noop_vetoed(frame, site)
        }

    def _guarded_click_probe_site_payload(
        self,
        selection: PrimitiveSelection,
        action_name: str,
    ) -> dict[str, int] | None:
        if action_name != "ACTION6":
            return None
        control_target = dict(selection.control_target or {})
        if str(control_target.get("primary_operator", "") or "") != "click":
            return None
        if str(control_target.get("solver_family", "") or "") != "transition_probe":
            return None
        probe_sites = [
            dict(candidate)
            for candidate in list(control_target.get("probe_site_candidates") or [])
            if isinstance(candidate, dict)
        ]
        scored: list[tuple[float, int, int, dict[str, int]]] = []
        for index, candidate in enumerate(probe_sites[:12]):
            if str(candidate.get("operator", "") or "") != "click":
                continue
            if not bool(candidate.get("actionable")):
                continue
            if _normalize_action_name(candidate.get("action_name")) != "ACTION6":
                continue
            payload = dict(candidate.get("payload") or {})
            site = candidate.get("site")
            if ("x" not in payload or "y" not in payload) and isinstance(site, (list, tuple)) and len(site) >= 2:
                payload = {"x": site[0], "y": site[1]}
            try:
                point = {"x": int(payload.get("x")), "y": int(payload.get("y"))}
            except (TypeError, ValueError):
                continue
            kind = str(candidate.get("source_kind", "") or "click_point")
            target = {
                "kind": kind,
                "site": [point["x"], point["y"]],
                "action_name": "ACTION6",
                "score_delta": int(candidate.get("score_delta", 0) or 0),
                "goal_likelihood": float(candidate.get("goal_likelihood", 0.0) or 0.0),
            }
            key = self._target_candidate_key(target, operator="click")
            if key is not None:
                attempts = self._target_attempts[key]
                successes = self._target_successes[key]
                failures = self._target_failures[key]
                if attempts >= 1 and failures >= attempts and successes <= 0:
                    continue
            confidence = float(candidate.get("confidence", 0.0) or 0.0)
            goal_likelihood = float(candidate.get("goal_likelihood", 0.0) or 0.0)
            score_delta = int(candidate.get("score_delta", 0) or 0)
            score = confidence + max(0.0, goal_likelihood) + (0.5 if score_delta > 0 else 0.0)
            scored.append((-score, index, self._issued_counts["ACTION6"], point))
        if not scored:
            return None
        scored.sort(key=lambda item: (item[0], item[1], item[2]))
        return scored[0][3]

    def _discovered_click_site_payload(
        self,
        frame: np.ndarray,
        selection: PrimitiveSelection,
        available: set[str],
    ) -> dict[str, Any] | None:
        if "ACTION6" not in available:
            return None
        control_target = dict(selection.control_target or {})
        operator = str(control_target.get("primary_operator", "") or "")
        solver_family = str(control_target.get("solver_family", "") or "")
        if operator not in {"probe", "click"} and solver_family not in {"transition_probe", "click_affordance"}:
            return None
        actionable_clicks = [
            candidate
            for candidate in list(control_target.get("probe_site_candidates") or [])
            if isinstance(candidate, dict)
            and str(candidate.get("operator", "") or "") == "click"
            and bool(candidate.get("actionable"))
        ]
        if actionable_clicks:
            return None
        failed_sites = set(self._click_discovery_failures.keys())
        tested_sites = set(self._click_discovery_attempts.keys())
        scoreless_click_lockin = self._scoreless_click_lockin_active()
        if self._click_affordance_induction_enabled() and not scoreless_click_lockin:
            induced_candidates = self.click_affordance_inducer.propose(
                frame,
                failed_sites=failed_sites,
                tested_sites=tested_sites,
            )
            for candidate in induced_candidates:
                site = candidate.get("site")
                if not isinstance(site, (list, tuple)) or len(site) < 2:
                    continue
                try:
                    x = int(site[0])
                    y = int(site[1])
                except (TypeError, ValueError):
                    continue
                return {
                    "x": x,
                    "y": y,
                    "kind": str(candidate.get("kind", "") or "click_affordance"),
                    "source": str(candidate.get("source", "") or "induced_click_affordance"),
                    "relation_kind": str(candidate.get("relation_kind", "") or ""),
                    "follow_action_name": str(candidate.get("follow_action_name", "") or ""),
                    "confidence": float(candidate.get("confidence", 0.0) or 0.0),
                }
        if not self._click_site_discovery_enabled() and self._click_affordance_induction_enabled():
            return None
        if self._click_visual_sampling_exhausted():
            return None
        candidates = self.click_site_discovery.discover(
            frame,
            failed_sites=failed_sites,
            tested_sites=tested_sites,
            changed_bboxes=[
                dict(event.get("changed_bbox") or {})
                for event in self._click_topology_events[-8:]
                if isinstance(event, dict) and isinstance(event.get("changed_bbox"), dict)
            ],
            source_stats=self._click_discovery_source_stats(),
        )
        for candidate in candidates:
            site = candidate.get("site")
            if not isinstance(site, (list, tuple)) or len(site) < 2:
                continue
            try:
                x = int(site[0])
                y = int(site[1])
            except (TypeError, ValueError):
                continue
            key = (x, y)
            if self._click_discovery_attempts[key] > 0:
                continue
            return {
                "x": x,
                "y": y,
                "source": str(candidate.get("source", "") or ""),
                "confidence": float(candidate.get("confidence", 0.0) or 0.0),
            }
        if self._click_affordance_induction_enabled() and scoreless_click_lockin:
            induced_candidates = self.click_affordance_inducer.propose(
                frame,
                failed_sites=failed_sites,
                tested_sites=tested_sites,
            )
            for candidate in induced_candidates:
                relation_kind = str(candidate.get("relation_kind", "") or "")
                follow_action = str(candidate.get("follow_action_name", "") or "")
                if relation_kind not in {"score_click", "selector_effect"} and not follow_action:
                    continue
                site = candidate.get("site")
                if not isinstance(site, (list, tuple)) or len(site) < 2:
                    continue
                try:
                    x = int(site[0])
                    y = int(site[1])
                except (TypeError, ValueError):
                    continue
                return {
                    "x": x,
                    "y": y,
                    "kind": str(candidate.get("kind", "") or "click_affordance"),
                    "source": str(candidate.get("source", "") or "induced_click_affordance"),
                    "relation_kind": relation_kind,
                    "follow_action_name": follow_action,
                    "confidence": float(candidate.get("confidence", 0.0) or 0.0),
                }
        return None

    def _rank_control_target_candidates(
        self,
        candidates: list[dict[str, Any]],
        *,
        operator: str = "route_to",
    ) -> list[dict[str, Any]]:
        scored: list[tuple[int, int, int, int, int, int, dict[str, Any]]] = []
        for index, candidate in enumerate(candidates):
            candidate_operator = self._target_operator_for_candidate(candidate, default=operator)
            key = self._target_candidate_key(candidate, operator=candidate_operator)
            if key is None:
                continue
            attempts = self._target_attempts[key]
            successes = self._target_successes[key]
            failures = self._target_failures[key]
            if attempts >= 2 and successes <= 0 and failures >= attempts:
                continue
            score_delta = int(candidate.get("score_delta", 0) or 0)
            kind = str(candidate.get("kind", "") or "")
            segment_transport_candidate = kind in {
                "segment_displacement",
                "score_segment_displacement",
            }
            goal_successes = self._target_goal_success_count(key)
            progress_only_successes = self._target_progress_only_success_count(key)
            direct_score_probe_failures = self._target_direct_score_probe_without_goal_count(key)
            segment_continuity_successes = self._target_segment_transport_continuity_count(key)
            goal_posterior_failures, goal_posterior_successes = (
                self._goal_failure_posterior_counts_for_candidate(
                    candidate,
                    operator=candidate_operator,
                )
            )
            retain_segment_transport = (
                segment_transport_candidate
                and segment_continuity_successes > 0
                and not self._solver_family_score_exhausted("segment_transport")
            )
            if (
                goal_posterior_failures >= 2
                and goal_posterior_successes <= 0
                and not retain_segment_transport
            ):
                continue
            if (
                kind == "score_precondition"
                and direct_score_probe_failures > 0
                and goal_successes <= 0
                and score_delta > 0
            ):
                continue
            if (
                score_delta <= 0
                and attempts >= 4
                and goal_successes <= 0
                and not retain_segment_transport
                and (
                    progress_only_successes >= 3
                    or failures >= max(3, attempts - 1)
                )
            ):
                continue
            goal_likelihood = float(candidate.get("goal_likelihood", 0.0) or 0.0)
            action_name = _normalize_action_name(candidate.get("action_name"))
            if self._operator_action_stale(candidate_operator, action_name):
                continue
            kind_bonus = 3 if kind == "score_precondition" else 2 if kind == "score_changed_bbox" else 0
            action_score = self._candidate_action_effect_priority(candidate)
            capped_successes = min(2, int(successes))
            stale_progress_penalty = (
                max(0, int(successes) - 3)
                if score_delta <= 0 and kind != "score_changed_bbox" and not retain_segment_transport
                else 0
            )
            terminal_penalty = 4 if goal_likelihood < 0.0 else 0
            contradiction_penalty = 4 * min(2, int(direct_score_probe_failures))
            goal_failure_penalty = 4 * min(2, int(goal_posterior_failures))
            goal_success_bonus = min(2, int(goal_posterior_successes))
            goal_bonus = int(round(max(0.0, goal_likelihood) * 6.0))
            scored.append(
                (
                    -score_delta
                    - kind_bonus
                    - action_score
                    - goal_bonus
                    - goal_success_bonus
                    + goal_failure_penalty,
                    terminal_penalty
                    + stale_progress_penalty
                    + contradiction_penalty
                    + goal_failure_penalty,
                    failures,
                    -capped_successes,
                    attempts,
                    index,
                    candidate,
                )
            )
        scored.sort()
        return [candidate for *_rest, candidate in scored]

    def _goal_failure_posterior_counts_for_candidate(
        self,
        candidate: Mapping[str, Any],
        *,
        operator: str,
    ) -> tuple[int, int]:
        objective_kind = _objective_kind_for_candidate(candidate)
        if not _objective_kind_goal_bearing(objective_kind):
            return 0, 0
        posterior_key = _goal_failure_posterior_key(
            target_kind=str(candidate.get("kind", "") or "target"),
            objective_kind=objective_kind,
            action_name=str(candidate.get("action_name", "") or ""),
            operator=operator,
        )
        return int(self._goal_failure_posterior[posterior_key]), int(
            self._goal_success_posterior[posterior_key]
        )

    def _candidate_action_effect_priority(self, candidate: dict[str, Any]) -> int:
        action_name = _normalize_action_name(candidate.get("action_name"))
        if not action_name:
            return 0
        summary = self._epoch_summary()
        stats = summary.action_stats.get(action_name)
        if stats is None:
            return 0
        goal_profile = dict(summary.goal_transition_profile or {})
        action_goal_scores = dict(goal_profile.get("action_goal_scores") or {})
        goal_score = float(action_goal_scores.get(action_name, 0.0) or 0.0)
        priority = 0
        if goal_score > 0.0:
            priority += int(round(goal_score * 6.0))
        elif goal_score < 0.0:
            priority += int(round(goal_score * 4.0))
        if stats.score_event_count > 0 or stats.score_delta_total > 0:
            priority += 5
        if stats.changed_count > 0:
            priority += 1
        if stats.localized_change_rate >= 0.50:
            priority += 1
        if stats.no_op_count >= max(2, stats.changed_count + stats.score_event_count):
            priority -= 2
        return max(-2, min(6, priority))

    def _operator_action_stale(
        self,
        operator: str,
        action_name: str,
        *,
        window: int = 16,
        threshold: int = 4,
    ) -> bool:
        if not operator or not action_name:
            return False
        if operator in {"route_to", "push", "attach", "drop"}:
            return False
        recent = [
            item
            for item in self._target_verification_history[-max(1, int(window)) :]
            if str(item.get("operator", "") or "") == operator
            and _normalize_action_name(item.get("action_name")) == action_name
        ]
        if len(recent) < threshold:
            return False
        failures = sum(
            1
            for item in recent
            if not bool(item.get("progressed")) and int(item.get("score_delta", 0) or 0) <= 0
        )
        successes = sum(
            1
            for item in recent
            if bool(item.get("progressed")) or int(item.get("score_delta", 0) or 0) > 0
        )
        return failures >= threshold and successes <= 0

    def _segment_transport_action_unproductive(
        self,
        action_name: str,
        *,
        window: int = 8,
        threshold: int = 3,
    ) -> bool:
        normalized = _normalize_action_name(action_name)
        if not normalized:
            return False
        recent = [
            item
            for item in self._target_verification_history[-max(1, int(window)) :]
            if str(item.get("solver_family", "") or "") == "segment_transport"
            and _normalize_action_name(item.get("action_name")) == normalized
        ]
        if len(recent) < threshold:
            return False
        if any(
            bool(item.get("goal_progress")) or int(item.get("score_delta", 0) or 0) > 0
            for item in recent
        ):
            return False
        continuity = sum(
            1
            for item in recent
            if bool(item.get("objective_progress"))
            and str(item.get("objective_progress_kind", "") or "") == "segment_transport_continuity"
        )
        misses = sum(
            1
            for item in recent
            if (
                not bool(item.get("objective_progress"))
                or (
                    str(item.get("objective_progress_kind", "") or "").startswith("segment_transport_")
                    and str(item.get("objective_progress_kind", "") or "") != "segment_transport_continuity"
                )
            )
        )
        return misses >= threshold and continuity <= 0

    def _operator_progress_stale(self, operator: str, *, window: int = 8, threshold: int = 4) -> bool:
        recent = [
            item
            for item in self._target_verification_history[-max(1, int(window)) :]
            if str(item.get("operator", "") or "") == operator
        ]
        if len(recent) < threshold:
            return False
        stale_progress = sum(
            1
            for item in recent
            if bool(item.get("progressed")) and int(item.get("score_delta", 0) or 0) <= 0
        )
        score_progress = sum(1 for item in recent if int(item.get("score_delta", 0) or 0) > 0)
        return stale_progress >= threshold and score_progress <= 0

    def _solver_family_score_exhausted(self, solver_family: str, *, window: int = 32) -> bool:
        family = str(solver_family or "")
        threshold = int(SOLVER_FAMILY_BUDGET_THRESHOLDS.get(family, 0) or 0)
        if threshold <= 0:
            return False
        recent = [
            item
            for item in self._target_verification_history[-max(1, int(window)) :]
            if str(item.get("solver_family", "") or "") == family
        ]
        if len(recent) < threshold:
            return False
        goal_successes = sum(
            1
            for item in recent
            if bool(item.get("goal_progress")) or int(item.get("score_delta", 0) or 0) > 0
        )
        if goal_successes > 0:
            return False
        no_score = sum(1 for item in recent if int(item.get("score_delta", 0) or 0) <= 0)
        failures = sum(1 for item in recent if not bool(item.get("progressed")))
        progress_only = sum(
            1
            for item in recent
            if (bool(item.get("progressed")) or bool(item.get("objective_progress")))
            and not bool(item.get("goal_progress"))
            and int(item.get("score_delta", 0) or 0) <= 0
        )
        return no_score >= threshold and (failures + progress_only) >= threshold

    def _solver_family_scoreless_visible_effect_lockin(
        self,
        solver_family: str,
        *,
        window: int = 16,
    ) -> bool:
        family = str(solver_family or "")
        threshold = int(SCORELESS_VISIBLE_EFFECT_LOCKIN_THRESHOLDS.get(family, 0) or 0)
        if threshold <= 0:
            return False
        recent = [
            item
            for item in self._target_verification_history[-max(1, int(window)) :]
            if str(item.get("solver_family", "") or "") == family
        ]
        if len(recent) < threshold:
            return False
        goal_successes = sum(
            1
            for item in recent
            if bool(item.get("goal_progress")) or int(item.get("score_delta", 0) or 0) > 0
        )
        if goal_successes > 0:
            return False
        progress_only = sum(
            1
            for item in recent
            if (bool(item.get("progressed")) or bool(item.get("objective_progress")))
            and not bool(item.get("goal_progress"))
            and int(item.get("score_delta", 0) or 0) <= 0
        )
        return progress_only >= threshold

    def _solver_family_unproductive(self, solver_family: str) -> bool:
        if self._solver_family_score_exhausted(solver_family):
            return True
        # Visible-effect-only lock-in is only a reliable stop signal for
        # transition probing. Transport/push/navigation often need many
        # scoreless visible changes before the first score-bearing state.
        return str(solver_family or "") == "transition_probe" and self._solver_family_scoreless_visible_effect_lockin(
            solver_family
        )

    def _solver_family_budget_summary(self) -> dict[str, dict[str, int | bool]]:
        out: dict[str, dict[str, int | bool]] = {}
        for family, threshold in sorted(SOLVER_FAMILY_BUDGET_THRESHOLDS.items()):
            recent = [
                item
                for item in self._target_verification_history[-32:]
                if str(item.get("solver_family", "") or "") == family
            ]
            out[family] = {
                "threshold": int(threshold),
                "attempts": int(len(recent)),
                "score_successes": int(sum(1 for item in recent if int(item.get("score_delta", 0) or 0) > 0)),
                "goal_successes": int(
                    sum(
                        1
                        for item in recent
                        if bool(item.get("goal_progress")) or int(item.get("score_delta", 0) or 0) > 0
                    )
                ),
                "progress_only": int(
                    sum(
                        1
                        for item in recent
                        if (bool(item.get("progressed")) or bool(item.get("objective_progress")))
                        and not bool(item.get("goal_progress"))
                        and int(item.get("score_delta", 0) or 0) <= 0
                    )
                ),
                "failures": int(sum(1 for item in recent if not bool(item.get("progressed")))),
                "exhausted": bool(self._solver_family_score_exhausted(family)),
                "scoreless_visible_effect_lockin": bool(
                    self._solver_family_scoreless_visible_effect_lockin(family)
                ),
                "unproductive": bool(self._solver_family_unproductive(family)),
            }
        return out

    def _target_score_success_count(self, key: tuple[str, int, int, str]) -> int:
        key_list = list(key)
        return sum(
            1
            for item in self._target_verification_history
            if item.get("target_key") == key_list and int(item.get("score_delta", 0) or 0) > 0
        )

    def _target_goal_success_count(self, key: tuple[str, int, int, str]) -> int:
        key_list = list(key)
        return sum(
            1
            for item in self._target_verification_history
            if item.get("target_key") == key_list
            and (
                bool(item.get("goal_progress"))
                or int(item.get("score_delta", 0) or 0) > 0
            )
        )

    def _target_progress_only_success_count(self, key: tuple[str, int, int, str]) -> int:
        key_list = list(key)
        return sum(
            1
            for item in self._target_verification_history
            if item.get("target_key") == key_list
            and (bool(item.get("progressed")) or bool(item.get("objective_progress")))
            and not bool(item.get("goal_progress"))
            and int(item.get("score_delta", 0) or 0) <= 0
        )

    def _target_direct_score_probe_without_goal_count(self, key: tuple[str, int, int, str]) -> int:
        key_list = list(key)
        history_count = sum(
            1
            for item in self._target_verification_history
            if item.get("target_key") == key_list
            and bool(item.get("direct_score_probe_without_goal"))
            and not bool(item.get("target_success"))
        )
        return max(int(self._target_direct_score_probe_failures[key]), int(history_count))

    def _score_precondition_direct_probe_failure_count(self, candidate: Mapping[str, Any]) -> int:
        if str(candidate.get("kind", "") or "") != "score_precondition":
            return 0
        action_name = _normalize_action_name(candidate.get("action_name"))
        operators = {"repeat_action", "probe"}
        candidate_operator = str(candidate.get("operator", "") or "")
        if candidate_operator:
            operators.add(candidate_operator)
        if action_name == "ACTION6":
            operators.add("click")
        return sum(
            self._target_direct_score_probe_without_goal_count(key)
            for operator in operators
            for key in [self._target_candidate_key(dict(candidate), operator=operator)]
            if key is not None
        )

    def _target_segment_transport_continuity_count(self, key: tuple[str, int, int, str]) -> int:
        key_list = list(key)
        return sum(
            1
            for item in self._target_verification_history
            if item.get("target_key") == key_list
            and bool(item.get("objective_progress"))
            and str(item.get("objective_progress_kind", "") or "") == "segment_transport_continuity"
            and not bool(item.get("goal_progress"))
            and int(item.get("score_delta", 0) or 0) <= 0
        )

    def _pending_rod_context_from_decision(
        self,
        selection: PrimitiveSelection,
        *,
        frame: np.ndarray,
        state_hash: str,
        classification_label: str,
        primitive_id: str,
        action_name: str,
        action_payload: Mapping[str, Any],
        actor_pos: tuple[int, int] | None,
        pending_target: Mapping[str, Any] | None,
    ) -> dict[str, Any]:
        control_target = dict(selection.control_target or {})
        solver_family = str(
            (pending_target or {}).get("solver_family", "")
            or control_target.get("solver_family", "")
            or _solver_family_for_primitive_id(primitive_id)
        )
        operator = str(
            (pending_target or {}).get("operator", "")
            or control_target.get("primary_operator", "")
            or _default_operator_for_solver_family(solver_family)
        )
        candidate = (pending_target or {}).get("candidate")
        if not isinstance(candidate, Mapping):
            candidate = control_target.get("primary_target")
        target_kind = str(candidate.get("kind", "") or "") if isinstance(candidate, Mapping) else ""
        target_key = (pending_target or {}).get("key")
        target_binding = {
            "binding_source": "control_target" if pending_target else "selection",
            "target_kind": target_kind,
            "operator": operator,
            "action_name": str(action_name),
            "target_key": list(target_key) if isinstance(target_key, (list, tuple)) else None,
            "actor_pos_source": str((pending_target or {}).get("actor_pos_source", "") or ""),
            "objective_kind": str((pending_target or {}).get("objective_kind", "") or ""),
        }
        if isinstance(candidate, Mapping):
            site = candidate.get("site")
            if isinstance(site, (list, tuple)) and len(site) >= 2:
                try:
                    target_binding["site"] = [int(site[0]), int(site[1])]
                except (TypeError, ValueError):
                    pass
            for key in ("action_name", "segment_color", "dx", "dy", "relation_kind"):
                if key in candidate:
                    target_binding[key] = candidate[key]
        context_actor_pos = actor_pos
        pending_actor_pos = (pending_target or {}).get("actor_pos")
        if context_actor_pos is None and isinstance(pending_actor_pos, (list, tuple)) and len(pending_actor_pos) >= 2:
            try:
                context_actor_pos = (int(pending_actor_pos[0]), int(pending_actor_pos[1]))
            except (TypeError, ValueError):
                context_actor_pos = None
        return {
            "before_sig": {
                "state_hash": str(state_hash),
                "frame_shape": [int(value) for value in frame.shape],
                "actor_pos": list(context_actor_pos) if context_actor_pos is not None else None,
                "actor_pos_source": str((pending_target or {}).get("actor_pos_source", "") or ""),
                "epoch_id": int(self._epoch_id),
                "records_count": int(sum(self._epoch_observed_counts.values())),
                "classification_label": str(classification_label),
            },
            "primitive_id": str(primitive_id),
            "solver_family": solver_family,
            "operator": operator,
            "action_name": str(action_name),
            "target_kind": target_kind,
            "target_key": list(target_key) if isinstance(target_key, (list, tuple)) else None,
            "target_binding": target_binding,
            "predicted_effect": self._predicted_effect_from_context(
                solver_family=solver_family,
                operator=operator,
                action_name=str(action_name),
                target_kind=target_kind,
                action_payload=action_payload,
            ),
        }

    def _predicted_effect_from_context(
        self,
        *,
        solver_family: str,
        operator: str,
        action_name: str,
        target_kind: str,
        action_payload: Mapping[str, Any],
    ) -> dict[str, Any]:
        family = str(solver_family or "")
        op = str(operator or "")
        action = _normalize_action_name(action_name)
        kind = str(target_kind or "")
        if family == "segment_transport" or kind in {"segment_displacement", "score_segment_displacement"}:
            effect_type = "segment_transport"
        elif op == "click" or action == "ACTION6" or family in {"click_affordance", "overlay"}:
            effect_type = "click_transition"
        elif family == "navigation" or op == "route_to":
            effect_type = "route_connectivity_delta"
        elif family == "score_frontier":
            effect_type = "score_delta"
        else:
            effect_type = "visible_effect"
        payload = {
            "effect_type": effect_type,
            "solver_family": family,
            "operator": op,
            "action_name": action,
            "target_kind": kind,
        }
        click_point = _click_point_from_payload(action_payload)
        if click_point is not None:
            payload["click_point"] = [int(click_point[0]), int(click_point[1])]
        return payload

    def _pending_target_from_selection(
        self,
        selection: PrimitiveSelection,
        *,
        action_name: str,
        primitive_id: str,
        actor_pos: tuple[int, int] | None = None,
        actor_pos_source: str = "",
        score_precondition_action_mode: str = "",
        commitment_level: str = "",
    ) -> dict[str, Any] | None:
        operator = self._target_operator_for_candidate({}, selection=selection)
        candidates = self._rank_control_target_candidates(
            list((selection.control_target or {}).get("target_candidates") or []),
            operator=operator,
        )
        if not candidates:
            return None
        candidate = dict(candidates[0])
        key = self._target_candidate_key(candidate, operator=operator)
        if key is None:
            return None
        self._target_attempts[key] += 1
        return {
            "candidate": candidate,
            "key": list(key),
            "operator": operator,
            "action_name": action_name,
            "primitive_id": primitive_id,
            "solver_family": str((selection.control_target or {}).get("solver_family", "") or _solver_family_for_primitive_id(primitive_id)),
            "actor_pos": list(actor_pos) if actor_pos is not None else None,
            "actor_pos_source": str(actor_pos_source or ("actor_value" if actor_pos is not None else "")),
            "score_precondition_action_mode": str(score_precondition_action_mode or ""),
            "commitment_level": str(commitment_level or ""),
            "objective_key": _objective_key_for_candidate(candidate),
            "objective_kind": _objective_kind_for_candidate(candidate),
        }

    def _passive_pending_target_from_action(
        self,
        selection: PrimitiveSelection,
        *,
        action_name: str,
        action_payload: dict[str, Any],
        primitive_id: str,
        actor_pos: tuple[int, int] | None,
    ) -> dict[str, Any] | None:
        control_target = dict(selection.control_target or {})
        operator = self._target_operator_for_candidate({}, selection=selection)
        probe_pending = self._passive_pending_probe_site_from_action(
            control_target,
            action_name=action_name,
            action_payload=action_payload,
            primitive_id=primitive_id,
            actor_pos=actor_pos,
            default_operator=operator,
        )
        if probe_pending is not None:
            return probe_pending
        if self._selection_targets_segment_transport(control_target, primitive_id=primitive_id):
            ranked = self._rank_control_target_candidates(
                list(control_target.get("target_candidates") or []),
                operator=operator,
            )
            for candidate in ranked[:8]:
                if self._segment_transport_candidate_matches_action(candidate, action_name):
                    return self._pending_target_from_candidate(
                        candidate,
                        operator=operator,
                        action_name=action_name,
                        primitive_id=primitive_id,
                        actor_pos=actor_pos,
                    )
            return None
        if operator in {"route_to", "push"}:
            if actor_pos is None or action_name not in DIRECTIONAL_ACTIONS:
                return None
            ranked = self._rank_control_target_candidates(
                list(control_target.get("target_candidates") or []),
                operator=operator,
            )
            for candidate in ranked[:6]:
                if self._direction_reduces_distance_to_candidate(actor_pos, action_name, candidate):
                    return self._pending_target_from_candidate(
                        candidate,
                        operator=operator,
                        action_name=action_name,
                        primitive_id=primitive_id,
                        actor_pos=actor_pos,
                    )
            return None
        if operator == "click":
            if action_name != "ACTION6":
                return None
            click_point = _click_point_from_payload(action_payload)
            if click_point is None:
                return None
            ranked = self._rank_control_target_candidates(
                list(control_target.get("target_candidates") or []),
                operator=operator,
            )
            for candidate in ranked[:8]:
                if self._candidate_site_matches_point(candidate, click_point):
                    return self._pending_target_from_candidate(
                        candidate,
                        operator=operator,
                        action_name=action_name,
                        primitive_id=primitive_id,
                        actor_pos=actor_pos,
                    )
            return None
        if operator in {"attach", "drop"}:
            if action_name not in {"ACTION5", "ACTION6"}:
                return None
            ranked = self._rank_control_target_candidates(
                list(control_target.get("target_candidates") or []),
                operator=operator,
            )
            if not ranked:
                return None
            return self._pending_target_from_candidate(
                ranked[0],
                operator=operator,
                action_name=action_name,
                primitive_id=primitive_id,
                actor_pos=actor_pos,
            )
        if operator == "repeat_action":
            ranked = self._rank_control_target_candidates(
                list(control_target.get("target_candidates") or []),
                operator=operator,
            )
            for candidate in ranked[:6]:
                if _normalize_action_name(candidate.get("action_name")) == action_name:
                    return self._pending_target_from_candidate(
                        candidate,
                        operator=operator,
                        action_name=action_name,
                        primitive_id=primitive_id,
                        actor_pos=actor_pos,
                    )
        return None

    def _selection_targets_segment_transport(
        self,
        control_target: Mapping[str, Any],
        *,
        primitive_id: str,
    ) -> bool:
        if _solver_family_for_primitive_id(primitive_id) == "segment_transport":
            return True
        if str(control_target.get("solver_family", "") or "") == "segment_transport":
            return True
        for candidate in list(control_target.get("target_candidates") or []):
            if isinstance(candidate, dict) and str(candidate.get("kind", "") or "") in {
                "segment_displacement",
                "score_segment_displacement",
            }:
                return True
        return False

    def _segment_transport_candidate_matches_action(
        self,
        candidate: Mapping[str, Any],
        action_name: str,
    ) -> bool:
        if str(candidate.get("kind", "") or "") not in {
            "segment_displacement",
            "score_segment_displacement",
        }:
            return False
        candidate_action = _normalize_action_name(candidate.get("action_name"))
        if candidate_action and candidate_action != _normalize_action_name(action_name):
            return False
        return True

    def _passive_pending_probe_site_from_action(
        self,
        control_target: dict[str, Any],
        *,
        action_name: str,
        action_payload: dict[str, Any],
        primitive_id: str,
        actor_pos: tuple[int, int] | None,
        default_operator: str,
    ) -> dict[str, Any] | None:
        probe_sites = [
            dict(candidate)
            for candidate in list(control_target.get("probe_site_candidates") or [])
            if isinstance(candidate, dict)
        ]
        if not probe_sites:
            return None
        normalized_action = _normalize_action_name(action_name)
        click_point = _click_point_from_payload(action_payload) if normalized_action == "ACTION6" else None
        for probe_site in probe_sites[:12]:
            probe_action = _normalize_action_name(probe_site.get("action_name"))
            if probe_action and probe_action != normalized_action:
                continue
            site = probe_site.get("site")
            if site is None and isinstance(probe_site.get("payload"), dict):
                payload = dict(probe_site.get("payload") or {})
                if "x" in payload and "y" in payload:
                    site = [payload.get("x"), payload.get("y")]
            if not isinstance(site, (list, tuple)) or len(site) < 2:
                continue
            try:
                target_site = [int(site[0]), int(site[1])]
            except (TypeError, ValueError):
                continue
            if click_point is not None and _manhattan((target_site[0], target_site[1]), click_point) > 1:
                continue
            operator = str(probe_site.get("operator", "") or default_operator or "probe")
            source_kind = str(probe_site.get("source_kind", "") or "")
            kind = source_kind or ("click_point" if operator == "click" else "probe_site")
            candidate = {
                "kind": kind,
                "site": target_site,
                "action_name": normalized_action,
                "score_delta": int(probe_site.get("score_delta", 0) or 0),
                "goal_likelihood": float(probe_site.get("goal_likelihood", 0.0) or 0.0),
                "probe_site_candidate": True,
            }
            if probe_site.get("relation_kind"):
                candidate["relation_kind"] = str(probe_site.get("relation_kind", "") or "")
            return self._pending_target_from_candidate(
                candidate,
                operator=operator,
                action_name=normalized_action,
                primitive_id=primitive_id,
                actor_pos=actor_pos,
            )
        return None

    def _pending_target_from_candidate(
        self,
        candidate: dict[str, Any],
        *,
        operator: str,
        action_name: str,
        primitive_id: str,
        actor_pos: tuple[int, int] | None,
        actor_pos_source: str = "",
    ) -> dict[str, Any] | None:
        key = self._target_candidate_key(candidate, operator=operator)
        if key is None:
            return None
        self._target_attempts[key] += 1
        return {
            "candidate": dict(candidate),
            "key": list(key),
            "operator": operator,
            "action_name": action_name,
            "primitive_id": primitive_id,
            "solver_family": _solver_family_for_primitive_id(primitive_id),
            "actor_pos": list(actor_pos) if actor_pos is not None else None,
            "actor_pos_source": str(actor_pos_source or ("actor_value" if actor_pos is not None else "")),
            "objective_key": _objective_key_for_candidate(candidate),
            "objective_kind": _objective_kind_for_candidate(candidate),
        }

    def _direction_reduces_distance_to_candidate(
        self,
        actor_pos: tuple[int, int],
        action_name: str,
        candidate: dict[str, Any],
    ) -> bool:
        site = candidate.get("site")
        if not isinstance(site, (list, tuple)) or len(site) < 2:
            return False
        try:
            target = (int(site[0]), int(site[1]))
        except (TypeError, ValueError):
            return False
        next_pos = _project_actor_step(actor_pos, action_name)
        return _manhattan(next_pos, target) < _manhattan(actor_pos, target)

    def _candidate_site_matches_point(
        self,
        candidate: dict[str, Any],
        point: tuple[int, int],
    ) -> bool:
        site = candidate.get("site")
        if not isinstance(site, (list, tuple)) or len(site) < 2:
            return False
        try:
            target = (int(site[0]), int(site[1]))
        except (TypeError, ValueError):
            return False
        return _manhattan(target, point) <= 1

    def _record_pending_target_verification(
        self,
        record: ActionEffectRecord,
        pre_frame: np.ndarray,
        post_frame: np.ndarray,
    ) -> None:
        pending = self._pending_control_target
        self._pending_control_target = None
        rod_context = self._pending_rod_context
        self._pending_rod_context = None
        raw_key = pending.get("key") if isinstance(pending, Mapping) else None
        key: tuple[str, int, int, str] | None = None
        if isinstance(raw_key, list) and len(raw_key) >= 4:
            try:
                key = (str(raw_key[0]), int(raw_key[1]), int(raw_key[2]), str(raw_key[3]))
            except (TypeError, ValueError):
                key = None
        progressed = (
            self._target_verification_progressed(dict(pending), record, post_frame)
            if isinstance(pending, Mapping)
            else False
        )
        goal_progress, goal_progress_kind = _record_goal_progress(record)
        objective_progress, objective_progress_kind = (
            _record_objective_progress(
                pending,
                record=record,
                progressed=progressed,
                goal_progress=goal_progress,
                goal_progress_kind=goal_progress_kind,
            )
            if isinstance(pending, Mapping)
            else (
                bool(goal_progress or int(record.score_delta) > 0),
                str(goal_progress_kind if goal_progress else "none"),
            )
        )
        coordinate_progress_eval = self._coordinate_hypothesis_progress_eval(
            pending=pending,
            record=record,
            pre_frame=pre_frame,
            post_frame=post_frame,
        )
        if (
            bool(coordinate_progress_eval.get("applicable"))
            and not bool(goal_progress)
            and int(record.score_delta) <= 0
        ):
            objective_progress = bool(coordinate_progress_eval.get("objective_progress"))
            objective_progress_kind = str(
                coordinate_progress_eval.get("objective_progress_kind", "")
                or "coordinate_target_no_progress"
            )
        objective_kind = str(
            pending.get("objective_kind", "") if isinstance(pending, Mapping) else ""
        )
        goal_bearing = _objective_kind_goal_bearing(objective_kind)
        structural_progress = bool(int(record.changed_pixel_count) > 0 and not bool(record.no_op))
        goal_aligned_progress, goal_aligned_progress_kind = _record_goal_aligned_progress(
            pending if isinstance(pending, Mapping) else {},
            record=record,
            progressed=progressed,
            goal_progress=goal_progress,
            goal_progress_kind=goal_progress_kind,
        )
        if (
            bool(coordinate_progress_eval.get("applicable"))
            and not bool(goal_progress)
            and int(record.score_delta) <= 0
        ):
            goal_aligned_progress = bool(coordinate_progress_eval.get("objective_progress"))
            goal_aligned_progress_kind = str(
                coordinate_progress_eval.get("objective_progress_kind", "")
                or "coordinate_target_no_progress"
            )
        goal_link_type = _goal_link_type(
            objective_kind=objective_kind,
            goal_bearing=goal_bearing,
            structural_progress=structural_progress,
            objective_progress=objective_progress,
            objective_progress_kind=objective_progress_kind,
            goal_aligned_progress=goal_aligned_progress,
            goal_aligned_progress_kind=goal_aligned_progress_kind,
            goal_progress=goal_progress,
            goal_progress_kind=goal_progress_kind,
            score_delta=int(record.score_delta),
        )
        candidate = pending.get("candidate") if isinstance(pending, Mapping) else None
        target_kind = str(candidate.get("kind", "") or "") if isinstance(candidate, Mapping) else ""
        if not target_kind and isinstance(rod_context, Mapping):
            target_kind = str(rod_context.get("target_kind", "") or "")
        primitive_id = str(
            (pending or {}).get("primitive_id", "")
            if isinstance(pending, Mapping)
            else ""
        ) or str((rod_context or {}).get("primitive_id", "") if isinstance(rod_context, Mapping) else "")
        if not primitive_id:
            primitive_id = "action_effect_observation"
        solver_family = str(
            (pending or {}).get("solver_family", "")
            if isinstance(pending, Mapping)
            else ""
        ) or str(
            (rod_context or {}).get("solver_family", "")
            if isinstance(rod_context, Mapping)
            else ""
        ) or _solver_family_for_primitive_id(primitive_id)
        operator = str(
            (pending or {}).get("operator", "")
            if isinstance(pending, Mapping)
            else ""
        ) or str(
            (rod_context or {}).get("operator", "")
            if isinstance(rod_context, Mapping)
            else ""
        ) or _default_operator_for_solver_family(solver_family)
        score_precondition_action_mode = str(
            pending.get("score_precondition_action_mode", "")
            if isinstance(pending, Mapping)
            else ""
        )
        direct_score_probe_without_goal = bool(
            target_kind == "score_precondition"
            and score_precondition_action_mode == "low_commitment_score_action_probe"
            and not bool(objective_progress)
            and not bool(goal_progress)
            and int(record.score_delta) <= 0
        )
        closure_veto = bool(
            goal_bearing
            and not bool(goal_aligned_progress)
            and not bool(goal_progress)
            and int(record.score_delta) <= 0
            and (structural_progress or objective_progress or progressed)
        )
        if closure_veto:
            self._closure_veto_count += 1
        posterior_update = False
        posterior_key = _goal_failure_posterior_key(
            target_kind=target_kind,
            objective_kind=objective_kind,
            action_name=record.action_name,
            operator=operator,
        )
        posterior_verdict = "none"
        if bool(goal_bearing and isinstance(pending, Mapping)):
            if bool(not direct_score_probe_without_goal and (goal_progress or int(record.score_delta) > 0)):
                self._goal_success_posterior[posterior_key] += 1
                posterior_update = True
                posterior_verdict = "success"
            elif bool(direct_score_probe_without_goal or closure_veto):
                self._goal_failure_posterior[posterior_key] += 1
                posterior_update = True
                posterior_verdict = "failure"
        target_success = bool(objective_progress or progressed or goal_progress or goal_aligned_progress)
        if direct_score_probe_without_goal:
            target_success = False
        verification: dict[str, Any] | None = None
        if isinstance(pending, Mapping) and key is not None:
            changed_region = _changed_region_between_frames(pre_frame, post_frame)
            if target_success:
                self._target_successes[key] += 1
            else:
                self._target_failures[key] += 1
                if direct_score_probe_without_goal:
                    self._target_direct_score_probe_failures[key] += 1
            if isinstance(candidate, dict) and str(candidate.get("kind", "") or "") in {
                "click_affordance",
                "click_point",
                "discovered_click_site",
            }:
                self.click_affordance_inducer.observe_verification(candidate, progressed=bool(goal_progress))
                source = str(candidate.get("discovery_source", "") or "unknown")
                if target_success:
                    self._click_discovery_source_successes[source] += 1
                else:
                    self._click_discovery_source_failures[source] += 1
                site = candidate.get("site")
                if isinstance(site, (list, tuple)) and len(site) >= 2:
                    try:
                        click_key = (int(site[0]), int(site[1]))
                        if target_success:
                            self._click_discovery_successes[click_key] += 1
                        else:
                            self._click_discovery_failures[click_key] += 1
                    except (TypeError, ValueError):
                        pass
            verification = {
                "target_key": list(key),
                "operator": operator,
                "action_name": str(pending.get("action_name", "") or ""),
                "primitive_id": primitive_id,
                "solver_family": solver_family,
                "actor_pos_source": str(pending.get("actor_pos_source", "") or ""),
                "score_precondition_action_mode": score_precondition_action_mode,
                "commitment_level": str(pending.get("commitment_level", "") or ""),
                "objective_key": str(pending.get("objective_key", "") or ""),
                "objective_kind": objective_kind,
                "goal_bearing": bool(goal_bearing),
                "target_kind": target_kind,
                "target_success": bool(target_success),
                "direct_score_probe_without_goal": bool(direct_score_probe_without_goal),
                "failure_posterior_update": bool(posterior_update),
                "failure_posterior_verdict": posterior_verdict,
                "action_family": _action_family(record.action_name, operator=operator),
                "structural_progress": bool(structural_progress),
                "goal_aligned_progress": bool(goal_aligned_progress),
                "goal_aligned_progress_kind": str(goal_aligned_progress_kind),
                "goal_link_type": str(goal_link_type),
                "closure_veto": bool(closure_veto),
                "progressed": progressed,
                "objective_progress": bool(objective_progress),
                "objective_progress_kind": str(objective_progress_kind),
                "goal_progress": bool(goal_progress),
                "goal_progress_kind": str(goal_progress_kind),
                "coordinate_hypothesis_progress": {
                    key: value
                    for key, value in dict(coordinate_progress_eval).items()
                    if key != "pending"
                },
                "score_delta": int(record.score_delta),
                "changed_pixel_count": int(record.changed_pixel_count),
                "changed_region": changed_region,
                "changed_bbox": list(changed_region.get("bbox") or []),
                "changed_centroid": list(changed_region.get("centroid") or []),
                "pre_state_hash": str(record.pre_state_hash),
                "post_state_hash": str(record.post_state_hash),
                "no_op": bool(record.no_op),
            }
            self._record_mechanic_hypothesis_outcome(
                pending=dict(pending),
                verification=verification,
                record=record,
                pre_frame=pre_frame,
                post_frame=post_frame,
            )
            self._target_verification_history.append(verification)
            self._target_verification_history = self._target_verification_history[-32:]
            self._seed_goal_shortplan_from_verification(
                verification,
                pending=dict(pending),
                post_frame=post_frame,
            )
        binding_source = "target_verification" if verification is not None else "action_effect_record"
        if isinstance(rod_context, Mapping) and rod_context.get("target_binding"):
            binding_source = str(
                dict(rod_context.get("target_binding") or {}).get("binding_source", "")
                or binding_source
            )
        before_sig, after_sig = record_state_signatures(record)
        if isinstance(rod_context, Mapping):
            before_sig = {**dict(rod_context.get("before_sig") or {}), **before_sig}
        target_binding = (
            dict(rod_context.get("target_binding") or {})
            if isinstance(rod_context, Mapping)
            else {}
        )
        if verification is not None:
            target_binding.update(
                {
                    "binding_source": binding_source,
                    "target_key": list(key) if key is not None else None,
                    "target_kind": target_kind,
                    "operator": operator,
                    "actor_pos_source": str(verification.get("actor_pos_source", "") or ""),
                    "score_precondition_action_mode": str(
                        verification.get("score_precondition_action_mode", "") or ""
                    ),
                    "commitment_level": str(verification.get("commitment_level", "") or ""),
                    "objective_kind": str(verification.get("objective_kind", "") or ""),
                    "goal_bearing": bool(verification.get("goal_bearing")),
                    "goal_aligned_progress": bool(
                        verification.get("goal_aligned_progress")
                    ),
                    "goal_aligned_progress_kind": str(
                        verification.get("goal_aligned_progress_kind", "") or ""
                    ),
                    "goal_link_type": str(verification.get("goal_link_type", "") or ""),
                    "target_success": bool(verification.get("target_success")),
                    "direct_score_probe_without_goal": bool(
                        verification.get("direct_score_probe_without_goal")
                    ),
                }
            )
        score_target_binding = _score_bearing_target_binding_from_record(
            record,
            rod_context=rod_context if isinstance(rod_context, Mapping) else {},
            pending=pending if isinstance(pending, Mapping) else {},
            existing_binding=target_binding,
            goal_progress=bool(goal_progress),
            goal_progress_kind=str(goal_progress_kind),
            objective_progress=bool(objective_progress),
            objective_progress_kind=str(objective_progress_kind),
            operator=operator,
        )
        if score_target_binding is not None:
            target_binding.update(score_target_binding)
            if str(score_target_binding.get("target_kind", "") or ""):
                target_kind = str(score_target_binding.get("target_kind", "") or target_kind)
            binding_source = str(score_target_binding.get("binding_source", "") or binding_source)
        effect = effect_event_from_record(
            record,
            target_kind=target_kind,
            objective_progress=bool(objective_progress),
            objective_progress_kind=str(objective_progress_kind),
            goal_progress=bool(goal_progress),
            goal_progress_kind=str(goal_progress_kind),
            goal_aligned_progress=bool(goal_aligned_progress),
            goal_aligned_progress_kind=str(goal_aligned_progress_kind),
            binding_source=binding_source,
        )
        predicted_effect = (
            dict(rod_context.get("predicted_effect") or {})
            if isinstance(rod_context, Mapping)
            else {}
        )
        self.rod_memory.add(
            build_causal_trace_rod(
                primitive_id=primitive_id,
                solver_family=solver_family,
                operator=operator,
                action_name=str(record.action_name),
                target_kind=target_kind,
                target_key=key,
                effect=effect,
                progressed=bool(
                    (progressed or objective_progress or goal_progress)
                    and not direct_score_probe_without_goal
                ),
                before_sig=before_sig,
                after_sig=after_sig,
                target_binding=target_binding,
                predicted_effect=predicted_effect,
                observed_effect=observed_effect_from_record(record, effect),
            )
        )

    def _record_unknown_affordance_probe_outcome(self, record: ActionEffectRecord) -> None:
        self._unknown_affordance_stats["unknown_action_probe_executed_count"] += 1
        pending = self._pending_control_target
        pending_map = pending if isinstance(pending, Mapping) else {}
        posterior_key = self._unknown_affordance_posterior_key_from_pending(
            pending_map,
            record=record,
        )
        expected_hash = (
            str(pending.get("expected_post_state_hash", "") or "")
            if isinstance(pending, Mapping)
            else ""
        )
        expected_signature = (
            str(pending.get("expected_delta_signature", "") or "")
            if isinstance(pending, Mapping)
            else ""
        )
        expected_delta_match = False
        false_positive = False
        if expected_hash and str(record.post_state_hash) == expected_hash:
            self._unknown_affordance_stats["unknown_action_expected_delta_match_count"] += 1
            expected_delta_match = True
        elif expected_signature.startswith("repeat_visible_effect:") and int(record.changed_pixel_count) > 0 and not bool(record.no_op):
            self._unknown_affordance_stats["unknown_action_expected_delta_match_count"] += 1
            expected_delta_match = True
        elif int(record.changed_pixel_count) <= 0 or bool(record.no_op):
            self._unknown_affordance_stats["unknown_action_false_positive_count"] += 1
            false_positive = True
        if int(record.score_delta) > 0:
            self._unknown_affordance_stats["unknown_action_score_delta_count"] += int(record.score_delta)
        if expected_delta_match:
            self._unknown_affordance_posterior_support[posterior_key] += 1
            if int(record.score_delta) > 0:
                self._unknown_affordance_posterior_score_delta[posterior_key] += int(record.score_delta)
                verdict = "score_confirmed"
                digestion = "score_confirmed"
            else:
                self._unknown_affordance_posterior_needs_goal_link[posterior_key] += 1
                verdict = "effect_confirmed_no_score"
                digestion = "promote_to_goal_link_candidate"
        elif false_positive:
            self._unknown_affordance_posterior_falsified[posterior_key] += 1
            verdict = "falsified_no_effect"
            digestion = "suppress_or_probe_alternative"
        else:
            self._unknown_affordance_posterior_ambiguous[posterior_key] += 1
            verdict = "ambiguous_effect"
            digestion = "probe_more"
        candidate = pending_map.get("candidate") if isinstance(pending_map.get("candidate"), Mapping) else {}
        self._unknown_affordance_outcomes.append(
            {
                "posterior_key": posterior_key,
                "verdict": verdict,
                "digestion": digestion,
                "source_kind": str(pending_map.get("source_kind", "") or candidate.get("source_kind", "") or "unknown"),
                "llm_role": str(pending_map.get("llm_role", "") or candidate.get("llm_role", "") or "none"),
                "action_name": str(record.action_name),
                "site": list(candidate.get("site") or []),
                "source_event_id": str(candidate.get("source_event_id", "") or ""),
                "state_precondition_mode": str(candidate.get("state_precondition_mode", "") or ""),
                "expected_delta_signature": expected_signature,
                "expected_delta_match": bool(expected_delta_match),
                "false_positive": bool(false_positive),
                "score_delta": int(record.score_delta),
                "changed_pixel_count": int(record.changed_pixel_count),
                "no_op": bool(record.no_op),
                "pre_state_hash": str(record.pre_state_hash),
                "post_state_hash": str(record.post_state_hash),
            }
        )
        self._unknown_affordance_outcomes = self._unknown_affordance_outcomes[-32:]
        if (
            expected_delta_match
            and int(record.score_delta) <= 0
            and self._unknown_affordance_goal_link_handoff_enabled()
        ):
            self._record_unknown_affordance_goal_candidate(
                posterior_key=posterior_key,
                pending=pending_map,
                record=record,
                expected_signature=expected_signature,
            )

    def _record_unknown_affordance_goal_candidate(
        self,
        *,
        posterior_key: str,
        pending: Mapping[str, Any],
        record: ActionEffectRecord,
        expected_signature: str,
    ) -> None:
        candidate = pending.get("candidate")
        candidate = candidate if isinstance(candidate, Mapping) else {}
        site = _site_tuple(candidate.get("site"))
        if site is None:
            click = _click_payload_xy(record.action_payload)
            site = click
        if site is None:
            return
        action_name = _normalize_action_name(
            pending.get("action_name", "")
            or candidate.get("action_name", "")
            or record.action_name
        )
        if not action_name:
            return
        payload: dict[str, int] = {}
        if action_name == "ACTION6":
            payload = {"x": int(site[0]), "y": int(site[1])}
        source_kind = str(
            pending.get("source_kind", "")
            or candidate.get("source_kind", "")
            or "unknown"
        )
        llm_role = str(
            pending.get("llm_role", "")
            or candidate.get("llm_role", "")
            or "none"
        )
        protected_plan_id = f"unknown_affordance_goal_link:{posterior_key}"
        self._mechanic_hypothesis_goal_candidates.append(
            {
                "posterior_key": str(posterior_key),
                "hypothesis_id": f"unknown_affordance:{posterior_key}",
                "repair_id": f"unknown_affordance_posterior_repair:{posterior_key}",
                "goal_link_id": f"unknown_affordance_goal_link:{posterior_key}",
                "protected_plan_id": protected_plan_id,
                "protected_plan_len": 1,
                "protected_plan_step_index": 0,
                "source_kind": source_kind,
                "llm_role": llm_role,
                "llm_direct_action": False,
                "source_primitive_id": "unknown_affordance_probe",
                "mechanic_family": "unknown_affordance",
                "site": [int(site[0]), int(site[1])],
                "action_name": action_name,
                "operator": "protected_probe",
                "objective_kind": "state_advance",
                "goal_predicate_kind": "unknown_affordance_expected_delta_match",
                "goal_link_type": "unknown_affordance_expected_delta_match",
                "goal_linked_candidate": True,
                "score_bearing_candidate": False,
                "score_evidence": False,
                "structural_only_candidate": False,
                "expected_goal_delta": 0.0,
                "confidence": 0.58,
                "required_current_state_hash": str(record.post_state_hash),
                "bounded_plan": [{"action_name": action_name, "payload": payload}],
                "bounded_plan_max_len": 1,
                "remaining_plan_length": 1,
                "unknown_affordance_continuation_count": 0,
                "unknown_affordance_continuation_max": self._unknown_affordance_continuation_refresh_max(),
                "source_event_id": str(candidate.get("source_event_id", "") or ""),
                "expected_delta_signature": str(expected_signature or ""),
                "claim_boundary": "effect_confirmed_unknown_affordance_goal_link_handoff",
            }
        )
        self._mechanic_hypothesis_goal_candidates = self._mechanic_hypothesis_goal_candidates[-32:]
        self._unknown_affordance_stats["unknown_action_goal_linked_count"] += 1

    def _unknown_affordance_posterior_key_from_pending(
        self,
        pending: Mapping[str, Any],
        *,
        record: ActionEffectRecord,
    ) -> str:
        candidate = pending.get("candidate")
        candidate = candidate if isinstance(candidate, Mapping) else {}
        source_kind = str(
            pending.get("source_kind", "")
            or candidate.get("source_kind", "")
            or "unknown"
        )
        action_name = _normalize_action_name(
            pending.get("action_name", "")
            or candidate.get("action_name", "")
            or record.action_name
        )
        site = candidate.get("site")
        if isinstance(site, (list, tuple)) and len(site) >= 2:
            try:
                x = int(site[0])
                y = int(site[1])
            except (TypeError, ValueError):
                x = None
                y = None
        else:
            click = _click_payload_xy(record.action_payload)
            x, y = click if click is not None else (None, None)
        expected_signature = str(
            pending.get("expected_delta_signature", "")
            or candidate.get("expected_delta_signature", "")
            or ""
        )
        if expected_signature.startswith("repeat_visible_effect:"):
            signature_kind = "repeat_visible_effect"
        elif expected_signature:
            signature_kind = "predicted_hash_delta"
        else:
            signature_kind = "unknown_delta"
        site_key = f"{int(x)},{int(y)}" if x is not None and y is not None else "unknown_site"
        return f"{source_kind}|unknown_affordance|{action_name}|{site_key}|{signature_kind}"

