    def _coordinate_hypothesis_recent_no_progress_target_keys(self) -> list[str]:
        keys: list[str] = []
        include_terminal_no_progress = bool(
            self._coordinate_hypothesis_terminal_no_progress_target_suppression_enabled()
        )
        for outcome in reversed(self._coordinate_hypothesis_plan_outcomes[-8:]):
            if int(outcome.get("score_before", 0) or 0) <= 0:
                continue
            if str(outcome.get("verdict", "") or "") != "falsified_no_coordinate_progress":
                continue
            plan_completed = bool(outcome.get("plan_completed"))
            score_before = int(outcome.get("score_before", 0) or 0)
            if not plan_completed and not (
                include_terminal_no_progress and score_before >= 3
            ):
                continue
            key = str(
                outcome.get("post_target_key", "")
                or outcome.get("pre_target_key", "")
                or outcome.get("requested_target_key", "")
                or ""
            )
            if key and not _coordinate_target_key_matches_any(key, keys):
                keys.append(key)
        return keys

    def _coordinate_hypothesis_detour_no_score_suppressed_target_keys_if_enabled(
        self,
    ) -> list[str]:
        if not self._coordinate_hypothesis_detour_no_score_target_suppression_enabled():
            return []
        keys: list[str] = []
        for event in reversed(self._coordinate_hypothesis_detour_no_score_retirement_events[-8:]):
            if not bool(event.get("retired")):
                continue
            if int(event.get("score_before", 0) or 0) <= 0:
                continue
            if int(event.get("score_delta", 0) or 0) > 0:
                continue
            key = str(event.get("target_key", "") or "")
            if key and not _coordinate_target_key_matches_any(key, keys):
                keys.append(key)
        return keys

    def _coordinate_hypothesis_target_score_evidence_count(self, target_key: str) -> int:
        key = str(target_key or "")
        if not key:
            return 0
        count = 0
        for outcome in self._coordinate_hypothesis_plan_outcomes:
            if int(outcome.get("score_delta", 0) or 0) <= 0:
                continue
            raw_keys = [
                outcome.get("requested_target_key", ""),
                outcome.get("attributed_target_key", ""),
                outcome.get("post_target_key", ""),
                outcome.get("pre_target_key", ""),
                outcome.get(
                    "target_commitment_preconditioning_structured_fallback_selected_target_key",
                    "",
                ),
                *list(outcome.get("requested_target_keys") or []),
            ]
            if any(_coordinate_target_keys_match(key, str(raw_key or "")) for raw_key in raw_keys):
                count += 1
        return int(count)

    def _coordinate_hypothesis_satisfied_target_churn_remaining_keys(
        self,
        *,
        selected_target_key: str,
        satisfied_target_keys: list[str],
        unsatisfied_target_keys: list[str],
    ) -> list[str]:
        target_key = str(selected_target_key or "")
        if not target_key:
            return []
        if not _coordinate_target_key_matches_any(target_key, satisfied_target_keys):
            return []
        remaining = [
            str(key or "")
            for key in unsatisfied_target_keys
            if str(key or "") and not _coordinate_target_keys_match(target_key, str(key or ""))
        ]
        return list(dict.fromkeys(remaining))

    def _record_coordinate_hypothesis_satisfied_target_churn_event(
        self,
        event: Mapping[str, Any],
    ) -> None:
        self._coordinate_hypothesis_satisfied_target_churn_events.append(dict(event))
        self._coordinate_hypothesis_satisfied_target_churn_events = (
            self._coordinate_hypothesis_satisfied_target_churn_events[-32:]
        )

    def _coordinate_hypothesis_kinematic_canvas_coupling_recent_evidence(
        self,
    ) -> list[dict[str, Any]]:
        return [dict(row) for row in self._coordinate_hypothesis_kinematic_canvas_coupling_events[-16:]]

    def _coordinate_relation_from_snapshot_best(
        self,
        snapshot: Mapping[str, Any],
    ) -> dict[str, Any]:
        target_key = str(snapshot.get("best_target_key", "") or "")
        if not target_key:
            return {}
        return {
            "target_key": target_key,
            "canvas_id": str(snapshot.get("canvas_id", "") or ""),
            "target_id": str(snapshot.get("target_id", "") or ""),
            "overlap_area": int(snapshot.get("best_overlap_area", 0) or 0),
            "distance": int(snapshot.get("best_distance", 10**9) or 10**9),
            "satisfied": bool(int(snapshot.get("best_overlap_area", 0) or 0) > 0),
            "canvas_bbox": list(snapshot.get("canvas_bbox") or []),
            "target_bbox": list(snapshot.get("target_bbox") or []),
            "canvas_centroid": list(snapshot.get("canvas_centroid") or []),
            "target_centroid": list(snapshot.get("target_centroid") or []),
            "colors": list(snapshot.get("colors") or []),
        }

    def _record_coordinate_hypothesis_kinematic_canvas_coupling_event(
        self,
        *,
        outcome: Mapping[str, Any],
        progress_eval: Mapping[str, Any],
    ) -> None:
        if not self._coordinate_hypothesis_kinematic_canvas_coupling_sensor_enabled():
            return
        pre_snapshot = progress_eval.get("pre")
        post_snapshot = progress_eval.get("post")
        selected_site = [
            int(value)
            for value in list(outcome.get("selected_site") or [])
            if isinstance(value, int)
            or (isinstance(value, str) and value.strip().lstrip("-").isdigit())
        ][:2]
        target_key = str(
            outcome.get("attributed_target_key", "")
            or outcome.get("requested_target_key", "")
            or outcome.get("post_target_key", "")
            or outcome.get("pre_target_key", "")
            or ""
        )
        target_colors: list[int] = []
        parsed = _parse_coordinate_target_key(target_key)
        if parsed:
            target_colors = [int(value) for value in parsed[0]]
        status = "insufficient_evidence"
        pre_relation: dict[str, Any] = {}
        post_relation: dict[str, Any] = {}
        if isinstance(pre_snapshot, Mapping) and isinstance(post_snapshot, Mapping):
            if target_key:
                pre_relation = _coordinate_relation_for_target_key(pre_snapshot, target_key)
                post_relation = _coordinate_relation_for_target_key(post_snapshot, target_key)
            if not pre_relation:
                pre_relation = self._coordinate_relation_from_snapshot_best(pre_snapshot)
            if not post_relation:
                post_relation = self._coordinate_relation_from_snapshot_best(post_snapshot)
        if not target_colors and post_relation:
            target_colors = [
                int(value)
                for value in list(post_relation.get("colors") or [])
                if isinstance(value, int)
                or (isinstance(value, str) and value.strip().lstrip("-").isdigit())
            ]
        pre_centroid = [
            int(value)
            for value in list(pre_relation.get("canvas_centroid") or [])
            if isinstance(value, int)
            or (isinstance(value, str) and value.strip().lstrip("-").isdigit())
        ][:2]
        post_centroid = [
            int(value)
            for value in list(post_relation.get("canvas_centroid") or [])
            if isinstance(value, int)
            or (isinstance(value, str) and value.strip().lstrip("-").isdigit())
        ][:2]
        canvas_delta = [0, 0]
        if len(pre_centroid) == 2 and len(post_centroid) == 2:
            canvas_delta = [
                int(post_centroid[0] - pre_centroid[0]),
                int(post_centroid[1] - pre_centroid[1]),
            ]
        pre_overlap = int(pre_relation.get("overlap_area", 0) or 0)
        post_overlap = int(post_relation.get("overlap_area", 0) or 0)
        pre_distance = int(pre_relation.get("distance", 10**9) or 10**9)
        post_distance = int(post_relation.get("distance", 10**9) or 10**9)
        overlap_delta = int(post_overlap - pre_overlap)
        distance_delta = int(pre_distance - post_distance)
        score_delta = int(outcome.get("score_delta", 0) or 0)
        canvas_moved = bool(canvas_delta != [0, 0])
        improved = bool(overlap_delta > 0 or distance_delta > 0 or score_delta > 0)
        if target_key and selected_site and pre_relation and post_relation:
            if canvas_moved and improved:
                status = "confirmed"
            elif not canvas_moved:
                status = "falsified"
            else:
                status = "ambiguous"
        canvas_colors = [
            int(value)
            for value in list(post_relation.get("colors") or [])
            if isinstance(value, int)
            or (isinstance(value, str) and value.strip().lstrip("-").isdigit())
        ]
        active_piece_colors = [
            int(value)
            for value in list(outcome.get("active_piece_colors") or [])
            if isinstance(value, int)
            or (isinstance(value, str) and value.strip().lstrip("-").isdigit())
        ]
        target_color_key = ",".join(str(int(value)) for value in target_colors) or "unknown"
        site_key = (
            f"{int(selected_site[0])},{int(selected_site[1])}"
            if len(selected_site) == 2
            else "unknown"
        )
        canvas_color_key = ",".join(str(int(value)) for value in canvas_colors) or "unknown"
        event = {
            "outcome_index": int(len(self._coordinate_hypothesis_plan_outcomes)),
            "posterior_key": f"target:{target_color_key}|site:{site_key}|canvas:{canvas_color_key}",
            "status": status,
            "primitive_id": str(outcome.get("primitive_id", "") or ""),
            "plan_id": int(outcome.get("plan_id", 0) or 0),
            "selected_site": selected_site,
            "active_piece_colors": active_piece_colors,
            "moved_canvas_colors": canvas_colors,
            "canvas_delta": canvas_delta,
            "target_key": target_key,
            "target_colors": target_colors,
            "score_delta": int(score_delta),
            "overlap_delta": int(overlap_delta),
            "distance_delta": int(distance_delta),
            "pre_canvas_centroid": pre_centroid,
            "post_canvas_centroid": post_centroid,
            "pre_overlap": int(pre_overlap),
            "post_overlap": int(post_overlap),
            "pre_distance": int(pre_distance),
            "post_distance": int(post_distance),
            "verdict": str(outcome.get("verdict", "") or ""),
        }
        self._coordinate_hypothesis_kinematic_canvas_coupling_events.append(event)
        self._coordinate_hypothesis_kinematic_canvas_coupling_events = (
            self._coordinate_hypothesis_kinematic_canvas_coupling_events[-64:]
        )

    def _coordinate_hypothesis_kinematic_canvas_coupling_posterior_summary(
        self,
    ) -> dict[str, Any]:
        events = list(self._coordinate_hypothesis_kinematic_canvas_coupling_events)
        status_counts = Counter(str(row.get("status", "") or "insufficient_evidence") for row in events)
        grouped: dict[str, dict[str, Any]] = {}
        for row in events:
            key = str(row.get("posterior_key", "") or "")
            if not key:
                continue
            bucket = grouped.setdefault(
                key,
                {
                    "posterior_key": key,
                    "target_key": str(row.get("target_key", "") or ""),
                    "target_colors": list(row.get("target_colors") or []),
                    "selected_site": list(row.get("selected_site") or []),
                    "moved_canvas_colors": list(row.get("moved_canvas_colors") or []),
                    "confirmed": 0,
                    "falsified": 0,
                    "ambiguous": 0,
                    "insufficient_evidence": 0,
                    "state": "insufficient_evidence",
                },
            )
            status = str(row.get("status", "") or "insufficient_evidence")
            if status not in {
                "confirmed",
                "falsified",
                "ambiguous",
                "insufficient_evidence",
            }:
                status = "insufficient_evidence"
            bucket[status] = int(bucket.get(status, 0) or 0) + 1
            if int(bucket.get("confirmed", 0) or 0) > 0:
                bucket["state"] = "confirmed"
            elif int(bucket.get("falsified", 0) or 0) > 0:
                bucket["state"] = "falsified"
            elif int(bucket.get("ambiguous", 0) or 0) > 0:
                bucket["state"] = "ambiguous"
            else:
                bucket["state"] = "insufficient_evidence"
        return {
            "enabled": bool(
                self._coordinate_hypothesis_kinematic_canvas_coupling_sensor_enabled()
            ),
            "event_count": int(len(events)),
            "confirmed_count": int(status_counts.get("confirmed", 0)),
            "falsified_count": int(status_counts.get("falsified", 0)),
            "ambiguous_count": int(status_counts.get("ambiguous", 0)),
            "insufficient_evidence_count": int(
                status_counts.get("insufficient_evidence", 0)
            ),
            "target_keys": list(
                dict.fromkeys(
                    [
                        str(row.get("target_key", "") or "")
                        for row in events
                        if str(row.get("target_key", "") or "")
                    ]
                )
            )[:8],
            "entries": list(grouped.values())[-8:],
            "recent": events[-8:],
        }

    def _coordinate_hypothesis_relation_snapshot_from_components(
        self,
        components: list[Mapping[str, Any]],
    ) -> dict[str, Any]:
        canvases = [row for row in components if row.get("kind") == "canvas"]
        targets = [row for row in components if row.get("kind") == "target"]
        best: dict[str, Any] = {}
        group_relations: list[dict[str, Any]] = []
        pair_count = 0
        satisfied_count = 0
        for canvas in canvases:
            canvas_box = _component_bbox_tuple(canvas)
            canvas_centroid = _component_centroid_tuple(canvas)
            canvas_colors = _component_color_set(canvas)
            if canvas_box is None or canvas_centroid is None or not canvas_colors:
                continue
            for target in targets:
                target_box = _component_bbox_tuple(target)
                target_centroid = _component_centroid_tuple(target)
                target_colors = _component_color_set(target)
                if target_box is None or target_centroid is None or not target_colors:
                    continue
                if not bool(canvas_colors & target_colors):
                    continue
                pair_count += 1
                overlap = _bbox_overlap_area_tuple(canvas_box, target_box)
                if overlap > 0:
                    satisfied_count += 1
                distance = _manhattan(canvas_centroid, target_centroid)
                target_key = _coordinate_target_focus_key_from_component(target)
                relation = {
                    "target_key": str(target_key),
                    "canvas_id": str(canvas.get("id", "") or ""),
                    "target_id": str(target.get("id", "") or ""),
                    "overlap_area": int(overlap),
                    "distance": int(distance),
                    "satisfied": bool(overlap > 0),
                    "canvas_bbox": [int(value) for value in canvas_box],
                    "target_bbox": [int(value) for value in target_box],
                    "canvas_centroid": [int(canvas_centroid[0]), int(canvas_centroid[1])],
                    "target_centroid": [int(target_centroid[0]), int(target_centroid[1])],
                    "colors": sorted(int(color) for color in (canvas_colors & target_colors)),
                }
                group_relations.append(relation)
                score = (int(overlap), -int(distance))
                previous_score = (
                    _int_or_default(best.get("best_overlap_area"), -1),
                    -_int_or_default(best.get("best_distance"), 10**9),
                )
                if not best or score > previous_score:
                    best = {
                        "best_overlap_area": int(overlap),
                        "best_distance": int(distance),
                        "best_target_key": str(target_key),
                        "canvas_id": str(canvas.get("id", "") or ""),
                        "target_id": str(target.get("id", "") or ""),
                        "canvas_bbox": [int(value) for value in canvas_box],
                        "target_bbox": [int(value) for value in target_box],
                        "canvas_centroid": [int(canvas_centroid[0]), int(canvas_centroid[1])],
                        "target_centroid": [int(target_centroid[0]), int(target_centroid[1])],
                        "colors": sorted(int(color) for color in (canvas_colors & target_colors)),
                    }
        group_relations.sort(
            key=lambda row: (
                1 if bool(row.get("satisfied")) else 0,
                -int(row.get("overlap_area", 0) or 0),
                int(row.get("distance", 10**9) or 10**9),
                str(row.get("target_key", "") or ""),
            )
        )
        relations_by_target_key: dict[str, dict[str, Any]] = {}
        for relation in group_relations:
            key = str(relation.get("target_key", "") or "")
            if not key:
                continue
            current = relations_by_target_key.get(key)
            relation_score = (
                int(relation.get("overlap_area", 0) or 0),
                -int(relation.get("distance", 10**9) or 10**9),
            )
            current_score = (
                int(current.get("overlap_area", -1) or -1) if current else -1,
                -int(current.get("distance", 10**9) or 10**9) if current else -(10**9),
            )
            if current is None or relation_score > current_score:
                relations_by_target_key[key] = dict(relation)
        unsatisfied = [
            str(row.get("target_key", "") or "")
            for row in group_relations
            if not bool(row.get("satisfied")) and str(row.get("target_key", "") or "")
        ]
        satisfied = [
            str(row.get("target_key", "") or "")
            for row in group_relations
            if bool(row.get("satisfied")) and str(row.get("target_key", "") or "")
        ]
        satisfied_relations = [dict(row) for row in group_relations if bool(row.get("satisfied"))]
        return {
            "available": bool(pair_count > 0),
            "pair_count": int(pair_count),
            "satisfied_pair_count": int(satisfied_count),
            "unsatisfied_pair_count": int(max(0, pair_count - satisfied_count)),
            "unsatisfied_target_keys": list(dict.fromkeys(unsatisfied)),
            "satisfied_target_keys": list(dict.fromkeys(satisfied)),
            "group_relations": group_relations[:8],
            "satisfied_group_relations": satisfied_relations[:16],
            "relations_by_target_key": relations_by_target_key,
            **best,
        }

    def _record_coordinate_hypothesis_plan_outcome(
        self,
        *,
        pending: Mapping[str, Any],
        record: ActionEffectRecord,
        progress_eval: Mapping[str, Any],
    ) -> None:
        if not bool(progress_eval.get("applicable")):
            return
        candidate = pending.get("candidate")
        candidate = candidate if isinstance(candidate, Mapping) else {}
        outcome = {
            "primitive_id": str(pending.get("primitive_id", "") or ""),
            "plan_id": int(progress_eval.get("plan_id", 0) or 0),
            "plan_completed": bool(progress_eval.get("plan_completed")),
            "verdict": str(progress_eval.get("verdict", "") or ""),
            "objective_progress": bool(progress_eval.get("objective_progress")),
            "objective_progress_kind": str(progress_eval.get("objective_progress_kind", "") or ""),
            "selected_site": list(candidate.get("site") or progress_eval.get("selected_site") or []),
            "active_piece_colors": [
                int(value)
                for value in list(progress_eval.get("selected_site_active_colors") or [])
                if isinstance(value, int)
                or (isinstance(value, str) and value.strip().lstrip("-").isdigit())
            ],
            "score_before": int(progress_eval.get("score_before", 0) or 0),
            "score_delta": int(record.score_delta),
            "overlap_delta": int(progress_eval.get("overlap_delta", 0) or 0),
            "distance_delta": int(progress_eval.get("distance_delta", 0) or 0),
            "requested_target_key": str(progress_eval.get("requested_target_key", "") or ""),
            "requested_target_keys": list(progress_eval.get("requested_target_keys") or []),
            "attributed_target_key": str(progress_eval.get("attributed_target_key", "") or ""),
            "relation_scope": str(progress_eval.get("relation_scope", "") or ""),
            "requested_target_bound_progress_required": bool(
                progress_eval.get("requested_target_bound_progress_required")
            ),
            "requested_target_bound_progress_satisfied": bool(
                progress_eval.get("requested_target_bound_progress_satisfied")
            ),
            "pre_target_key": str(progress_eval.get("pre_target_key", "") or ""),
            "post_target_key": str(progress_eval.get("post_target_key", "") or ""),
            "pre_satisfied_pair_count": int(progress_eval.get("pre_satisfied_pair_count", 0) or 0),
            "post_satisfied_pair_count": int(progress_eval.get("post_satisfied_pair_count", 0) or 0),
            "pre_satisfied_target_keys": list(
                progress_eval.get("pre_satisfied_target_keys") or []
            ),
            "post_satisfied_target_keys": list(
                progress_eval.get("post_satisfied_target_keys") or []
            ),
            "satisfied_pair_regression": bool(progress_eval.get("satisfied_pair_regression")),
            "joint_plan_regression_tolerated": bool(
                progress_eval.get("joint_plan_regression_tolerated")
            ),
            "regressed_satisfied_target_keys": list(
                progress_eval.get("regressed_satisfied_target_keys") or []
            ),
            "post_unsatisfied_target_keys": list(progress_eval.get("post_unsatisfied_target_keys") or []),
            "remaining_after": _int_or_default(
                pending.get("coordinate_plan_remaining_after"),
                -1,
            ),
            "terminal_completion_best_incomplete_fallback_applied": bool(
                pending.get("terminal_completion_best_incomplete_fallback_applied")
            ),
            "terminal_completion_best_incomplete_fallback_application_count_after": int(
                pending.get(
                    "terminal_completion_best_incomplete_fallback_application_count_after",
                    0,
                )
                or 0
            ),
            "terminal_completion_best_incomplete_fallback_provider_cooldown_started": bool(
                pending.get(
                    "terminal_completion_best_incomplete_fallback_provider_cooldown_started"
                )
            ),
            "terminal_completion_best_incomplete_fallback_provider_cooldown_steps": int(
                pending.get(
                    "terminal_completion_best_incomplete_fallback_provider_cooldown_steps",
                    0,
                )
                or 0
            ),
            "target_commitment_preconditioning_structured_fallback_applied": bool(
                pending.get("target_commitment_preconditioning_structured_fallback_applied")
            ),
            "target_commitment_preconditioning_structured_fallback_selected_target_key": str(
                pending.get(
                    "target_commitment_preconditioning_structured_fallback_selected_target_key",
                    "",
                )
                or ""
            ),
            "target_commitment_preconditioning_structured_fallback_single_piece": bool(
                pending.get("target_commitment_preconditioning_structured_fallback_single_piece")
            ),
            "single_piece_target_family_outcome_probe_applied": bool(
                pending.get("single_piece_target_family_outcome_probe_applied")
            ),
            "single_piece_target_family_outcome_probe_route_key": str(
                pending.get("single_piece_target_family_outcome_probe_route_key", "")
                or ""
            ),
            "single_piece_target_family_outcome_probe_route_sites": [
                [int(site[0]), int(site[1])]
                for site in list(
                    pending.get("single_piece_target_family_outcome_probe_route_sites")
                    or []
                )
                if isinstance(site, (list, tuple)) and len(site) >= 2
            ],
            "terminal_self_overlap_detour_used": bool(
                pending.get("terminal_self_overlap_detour_used")
            ),
            "terminal_self_overlap_detour_count": int(
                pending.get("terminal_self_overlap_detour_count", 0) or 0
            ),
            "terminal_self_overlap_detour": dict(
                pending.get("terminal_self_overlap_detour") or {}
            ),
            "target_commitment_single_no_score_alternative_probe_applied": bool(
                pending.get(
                    "target_commitment_single_no_score_alternative_probe_applied"
                )
            ),
            "target_commitment_single_no_score_alternative_probe": dict(
                pending.get("target_commitment_single_no_score_alternative_probe")
                or {}
            ),
        }
        if bool(outcome.get("single_piece_target_family_outcome_probe_applied")):
            probe_event = {
                "outcome_index": int(len(self._coordinate_hypothesis_plan_outcomes)),
                "primitive_id": str(outcome.get("primitive_id", "") or ""),
                "plan_id": int(outcome.get("plan_id", 0) or 0),
                "plan_step_index": int(
                    pending.get("coordinate_plan_step_index", 0) or 0
                ),
                "plan_completed": bool(outcome.get("plan_completed")),
                "selected_site": list(outcome.get("selected_site") or []),
                "target_key": str(outcome.get("requested_target_key", "") or ""),
                "route_key": str(
                    outcome.get("single_piece_target_family_outcome_probe_route_key", "")
                    or ""
                ),
                "route_sites": list(
                    outcome.get("single_piece_target_family_outcome_probe_route_sites")
                    or []
                ),
                "verdict": str(outcome.get("verdict", "") or ""),
                "score_before": int(outcome.get("score_before", 0) or 0),
                "score_delta": int(outcome.get("score_delta", 0) or 0),
                "overlap_delta": int(outcome.get("overlap_delta", 0) or 0),
                "distance_delta": int(outcome.get("distance_delta", 0) or 0),
                "remaining_after": _int_or_default(outcome.get("remaining_after"), -1),
            }
            self._coordinate_hypothesis_single_piece_target_family_probe_outcomes.append(
                probe_event
            )
            self._coordinate_hypothesis_single_piece_target_family_probe_outcomes = (
                self._coordinate_hypothesis_single_piece_target_family_probe_outcomes[-32:]
            )
        if (
            bool(outcome.get("target_commitment_preconditioning_structured_fallback_applied"))
            and bool(self._coordinate_hypothesis_preconditioning_fallback_outcome_sensor_enabled())
        ):
            fallback_event = {
                "outcome_index": int(len(self._coordinate_hypothesis_plan_outcomes)),
                "primitive_id": str(outcome.get("primitive_id", "") or ""),
                "plan_id": int(outcome.get("plan_id", 0) or 0),
                "plan_step_index": int(
                    pending.get("coordinate_plan_step_index", 0) or 0
                ),
                "plan_completed": bool(outcome.get("plan_completed")),
                "selected_site": list(outcome.get("selected_site") or []),
                "selected_target_key": str(
                    outcome.get(
                        "target_commitment_preconditioning_structured_fallback_selected_target_key",
                        "",
                    )
                    or ""
                ),
                "single_piece": bool(
                    outcome.get(
                        "target_commitment_preconditioning_structured_fallback_single_piece"
                    )
                ),
                "verdict": str(outcome.get("verdict", "") or ""),
                "score_before": int(outcome.get("score_before", 0) or 0),
                "score_delta": int(outcome.get("score_delta", 0) or 0),
                "overlap_delta": int(outcome.get("overlap_delta", 0) or 0),
                "distance_delta": int(outcome.get("distance_delta", 0) or 0),
                "remaining_after": _int_or_default(outcome.get("remaining_after"), -1),
            }
            self._coordinate_hypothesis_preconditioning_fallback_outcomes.append(
                fallback_event
            )
            self._coordinate_hypothesis_preconditioning_fallback_outcomes = (
                self._coordinate_hypothesis_preconditioning_fallback_outcomes[-32:]
            )
        observation = pending.get("target_commitment_preconditioning_observation")
        if isinstance(observation, Mapping):
            outcome["target_commitment_preconditioning_observation"] = dict(observation)
        active_context = dict(self._active_coordinate_hypothesis_plan_context)
        temporary_regressed_keys = [
            str(key or "")
            for key in list(active_context.get("temporarily_regressed_satisfied_target_keys") or [])
            if str(key or "")
        ]
        post_satisfied_keys = [
            str(key or "")
            for key in list(outcome.get("post_satisfied_target_keys") or [])
            if str(key or "")
        ]
        if temporary_regressed_keys:
            restored_keys = [
                key
                for key in temporary_regressed_keys
                if _coordinate_target_key_matches_any(key, post_satisfied_keys)
            ]
            if restored_keys:
                outcome["joint_plan_regression_restored_keys"] = list(
                    dict.fromkeys(restored_keys)
                )
            temporary_regressed_keys = [
                key
                for key in temporary_regressed_keys
                if not _coordinate_target_key_matches_any(key, post_satisfied_keys)
            ]
            if temporary_regressed_keys:
                active_context["temporarily_regressed_satisfied_target_keys"] = list(
                    dict.fromkeys(temporary_regressed_keys)
                )
            else:
                active_context.pop("temporarily_regressed_satisfied_target_keys", None)
            self._active_coordinate_hypothesis_plan_context = active_context
        if bool(outcome.get("joint_plan_regression_tolerated")):
            tolerated_keys = [
                str(key or "")
                for key in list(outcome.get("regressed_satisfied_target_keys") or [])
                if str(key or "")
            ]
            if tolerated_keys:
                outcome["joint_plan_regression_tolerated_keys"] = list(
                    dict.fromkeys(tolerated_keys)
                )
                temporary_regressed_keys = list(
                    dict.fromkeys([*temporary_regressed_keys, *tolerated_keys])
                )
                active_context["temporarily_regressed_satisfied_target_keys"] = list(
                    temporary_regressed_keys
                )
                active_context["joint_plan_regression_tolerated_count"] = (
                    int(active_context.get("joint_plan_regression_tolerated_count", 0) or 0)
                    + 1
                )
                self._active_coordinate_hypothesis_plan_context = active_context
            outcome["regression_guard_applied"] = False
        if (
            bool(self._coordinate_hypothesis_joint_plan_regression_tolerance_enabled())
            and bool(outcome.get("plan_completed"))
            and temporary_regressed_keys
        ):
            outcome["joint_plan_regression_unrestored_on_completion"] = True
            outcome["joint_plan_regression_unrestored_keys"] = list(
                dict.fromkeys(temporary_regressed_keys)
            )
            outcome["satisfied_pair_regression"] = True
            outcome["objective_progress"] = False
            outcome["objective_progress_kind"] = "coordinate_satisfied_pair_regression_unrestored"
            outcome["verdict"] = "falsified_satisfied_pair_regression"
            outcome["regressed_satisfied_target_keys"] = list(
                dict.fromkeys(
                    [
                        *[
                            str(key or "")
                            for key in list(outcome.get("regressed_satisfied_target_keys") or [])
                            if str(key or "")
                        ],
                        *temporary_regressed_keys,
                    ]
                )
            )
        if (
            bool(
                self._coordinate_hypothesis_terminal_best_incomplete_peak_stop_replan_enabled()
            )
            and bool(outcome.get("terminal_completion_best_incomplete_fallback_applied"))
            and int(outcome.get("score_before", 0) or 0) >= 3
            and int(outcome.get("remaining_after", 0) or 0) > 0
            and int(outcome.get("post_satisfied_pair_count", 0) or 0)
            > int(outcome.get("pre_satisfied_pair_count", 0) or 0)
            and int(outcome.get("post_satisfied_pair_count", 0) or 0)
            >= int(
                self._coordinate_hypothesis_terminal_best_incomplete_peak_stop_min_post_satisfied_pairs()
            )
            and (
                int(outcome.get("post_satisfied_pair_count", 0) or 0)
                - int(outcome.get("pre_satisfied_pair_count", 0) or 0)
            )
            >= int(
                self._coordinate_hypothesis_terminal_best_incomplete_peak_stop_min_satisfied_pair_delta()
            )
        ):
            remaining_before_clear = int(len(self._active_coordinate_hypothesis_plan))
            outcome["terminal_best_incomplete_peak_stop_replan_applied"] = True
            outcome["terminal_best_incomplete_peak_stop_replan_remaining_cleared"] = int(
                remaining_before_clear
            )
            outcome["terminal_best_incomplete_peak_stop_replan_min_post_satisfied_pairs"] = int(
                self._coordinate_hypothesis_terminal_best_incomplete_peak_stop_min_post_satisfied_pairs()
            )
            outcome["terminal_best_incomplete_peak_stop_replan_min_satisfied_pair_delta"] = int(
                self._coordinate_hypothesis_terminal_best_incomplete_peak_stop_min_satisfied_pair_delta()
            )
            outcome["terminal_best_incomplete_peak_stop_replan_pre_satisfied_pair_count"] = int(
                outcome.get("pre_satisfied_pair_count", 0) or 0
            )
            outcome["terminal_best_incomplete_peak_stop_replan_post_satisfied_pair_count"] = int(
                outcome.get("post_satisfied_pair_count", 0) or 0
            )
            post_peak_target_keys = (
                self._coordinate_hypothesis_post_peak_replan_target_keys_from_outcome(outcome)
            )
            if (
                bool(
                    self._coordinate_hypothesis_terminal_best_incomplete_post_peak_replan_enabled()
                )
                and post_peak_target_keys
            ):
                outcome["terminal_best_incomplete_post_peak_replan_created"] = True
                outcome["terminal_best_incomplete_post_peak_replan_target_keys"] = list(
                    post_peak_target_keys
                )
                self._coordinate_hypothesis_terminal_best_incomplete_post_peak_replan = {
                    "target_keys": list(post_peak_target_keys),
                    "source_plan_id": int(outcome.get("plan_id", 0) or 0),
                    "source_primitive_id": str(outcome.get("primitive_id", "") or ""),
                    "source_selected_site": list(outcome.get("selected_site") or []),
                    "attempt_count": 0,
                    "pre_satisfied_pair_count": int(
                        outcome.get("pre_satisfied_pair_count", 0) or 0
                    ),
                    "post_satisfied_pair_count": int(
                        outcome.get("post_satisfied_pair_count", 0) or 0
                    ),
                }
            self._active_coordinate_hypothesis_plan.clear()
            self._active_coordinate_hypothesis_plan_context.clear()
        if (
            bool(outcome.get("satisfied_pair_regression"))
            and bool(self._coordinate_hypothesis_satisfied_pair_regression_guard_enabled())
            and not bool(outcome.get("joint_plan_regression_tolerated"))
        ):
            outcome["regression_guard_applied"] = True
            self._active_coordinate_hypothesis_plan.clear()
            self._active_coordinate_hypothesis_plan_context.clear()
            self._coordinate_hypothesis_target_commitment.clear()
            self._coordinate_hypothesis_terminal_best_incomplete_post_peak_replan.clear()
            if bool(self._coordinate_hypothesis_regression_repair_commitment_enabled()):
                repair_target_key = ""
                for raw_key in list(outcome.get("regressed_satisfied_target_keys") or []):
                    candidate_key = str(raw_key or "")
                    if candidate_key:
                        repair_target_key = candidate_key
                        break
                if repair_target_key:
                    outcome["regression_repair_commitment_created"] = True
                    outcome["regression_repair_target_key"] = repair_target_key
                    self._coordinate_hypothesis_target_commitment = {
                        "target_key": repair_target_key,
                        "source_plan_id": int(outcome.get("plan_id", 0) or 0),
                        "source_primitive_id": str(outcome.get("primitive_id", "") or ""),
                        "progress_kind": "satisfied_pair_regression_repair",
                        "attempt_count": 0,
                        "last_progress_site": list(outcome.get("selected_site") or []),
                    }
        self._record_coordinate_hypothesis_kinematic_canvas_coupling_event(
            outcome=outcome,
            progress_eval=progress_eval,
        )
        self._record_coordinate_hypothesis_preconditioning_attribution(outcome)
        self._coordinate_hypothesis_plan_outcomes.append(outcome)
        self._coordinate_hypothesis_plan_outcomes = self._coordinate_hypothesis_plan_outcomes[-32:]
        self._update_coordinate_hypothesis_target_commitment(outcome)

    def _record_coordinate_hypothesis_preconditioning_attribution(
        self,
        outcome: Mapping[str, Any],
    ) -> None:
        if not bool(
            self._coordinate_hypothesis_target_commitment_preconditioning_attribution_enabled()
        ):
            return
        outcome_index = int(len(self._coordinate_hypothesis_plan_outcomes))
        window = int(
            self._coordinate_hypothesis_target_commitment_preconditioning_attribution_window()
        )
        if int(outcome.get("score_delta", 0) or 0) > 0:
            for event in self._coordinate_hypothesis_preconditioning_events:
                if bool(event.get("attributed")):
                    continue
                age = outcome_index - int(event.get("outcome_index", 0) or 0)
                if age < 0 or age > window:
                    continue
                event["attributed"] = True
                event["attributed_outcome_index"] = int(outcome_index)
                event["attribution_age"] = int(age)
                event["attributed_score_delta"] = int(outcome.get("score_delta", 0) or 0)
                event["attributed_primitive_id"] = str(outcome.get("primitive_id", "") or "")
                event["attributed_selected_site"] = list(outcome.get("selected_site") or [])
                event["attributed_requested_target_key"] = str(
                    outcome.get("requested_target_key", "") or ""
                )
                event["attributed_post_target_key"] = str(
                    outcome.get("post_target_key", "") or ""
                )
        observation = outcome.get("target_commitment_preconditioning_observation")
        if not isinstance(observation, Mapping):
            return
        if not bool(observation.get("potential_preconditioning")):
            return
        metadata = dict(observation.get("metadata") or {})
        event = {
            "outcome_index": int(outcome_index),
            "source_primitive_id": str(outcome.get("primitive_id", "") or ""),
            "score_before": int(outcome.get("score_before", 0) or 0),
            "selected_site": list(observation.get("selected_site") or []),
            "commitment_target_key": str(observation.get("target_key", "") or ""),
            "immediate_target_focus_key": str(metadata.get("target_focus_key", "") or ""),
            "attempt_count": int(observation.get("attempt_count", 0) or 0),
            "predicted_requested_target_satisfied_delta": int(
                metadata.get("predicted_requested_target_satisfied_delta", 0) or 0
            ),
            "predicted_canvas_satisfied_pair_delta": int(
                metadata.get("predicted_canvas_satisfied_pair_delta", 0) or 0
            ),
            "attributed": False,
        }
        self._coordinate_hypothesis_preconditioning_events.append(event)
        self._coordinate_hypothesis_preconditioning_events = (
            self._coordinate_hypothesis_preconditioning_events[-32:]
        )

    def _update_coordinate_hypothesis_target_commitment(self, outcome: Mapping[str, Any]) -> None:
        target_key = str(
            outcome.get("post_target_key", "")
            or outcome.get("requested_target_key", "")
            or outcome.get("pre_target_key", "")
            or ""
        )
        verdict = str(outcome.get("verdict", "") or "")
        if verdict == "score_confirmed" or int(outcome.get("score_delta", 0) or 0) > 0:
            self._coordinate_hypothesis_target_commitment.clear()
            self._coordinate_hypothesis_terminal_best_incomplete_post_peak_replan.clear()
            return
        if not target_key:
            return
        if (
            bool(
                self._coordinate_hypothesis_target_commitment_single_no_score_alternative_failure_release_enabled()
            )
            and bool(
                outcome.get(
                    "target_commitment_single_no_score_alternative_probe_applied"
                )
            )
            and int(outcome.get("score_before", 0) or 0) > 0
            and int(outcome.get("score_delta", 0) or 0) <= 0
        ):
            if isinstance(outcome, dict):
                outcome[
                    "target_commitment_single_no_score_alternative_failure_released"
                ] = True
                outcome[
                    "target_commitment_single_no_score_alternative_failure_released_target_key"
                ] = str(target_key)
            self._active_coordinate_hypothesis_plan.clear()
            self._active_coordinate_hypothesis_plan_context.clear()
            self._coordinate_hypothesis_target_commitment.clear()
            self._coordinate_hypothesis_terminal_best_incomplete_post_peak_replan.clear()
            return
        if (
            bool(
                self._coordinate_hypothesis_target_commitment_detour_no_score_retirement_enabled()
            )
            and bool(outcome.get("terminal_self_overlap_detour_used"))
            and (
                bool(outcome.get("plan_completed"))
                or _int_or_default(outcome.get("remaining_after"), -1) <= 0
            )
            and int(outcome.get("score_before", 0) or 0) > 0
            and int(outcome.get("score_delta", 0) or 0) <= 0
        ):
            event = {
                "source": "target_commitment_update",
                "primitive_id": str(outcome.get("primitive_id", "") or ""),
                "plan_id": int(outcome.get("plan_id", 0) or 0),
                "selected_site": list(outcome.get("selected_site") or []),
                "target_key": str(target_key),
                "score_before": int(outcome.get("score_before", 0) or 0),
                "score_delta": int(outcome.get("score_delta", 0) or 0),
                "verdict": str(outcome.get("verdict", "") or ""),
                "detour_count": int(
                    outcome.get("terminal_self_overlap_detour_count", 0) or 0
                ),
                "detour": dict(outcome.get("terminal_self_overlap_detour") or {}),
                "retired": True,
            }
            self._coordinate_hypothesis_detour_no_score_retirement_events.append(event)
            self._coordinate_hypothesis_detour_no_score_retirement_events = (
                self._coordinate_hypothesis_detour_no_score_retirement_events[-32:]
            )
            if isinstance(outcome, dict):
                outcome["target_commitment_detour_no_score_retired"] = True
                outcome["target_commitment_detour_no_score_retired_target_key"] = str(
                    target_key
                )
                outcome["target_commitment_detour_no_score_retired_detour_count"] = int(
                    event["detour_count"]
                )
            self._active_coordinate_hypothesis_plan.clear()
            self._active_coordinate_hypothesis_plan_context.clear()
            self._coordinate_hypothesis_target_commitment.clear()
            self._coordinate_hypothesis_terminal_best_incomplete_post_peak_replan.clear()
            return
        if verdict == "coordinate_progress" and bool(outcome.get("objective_progress")):
            current = dict(self._coordinate_hypothesis_target_commitment or {})
            current_progress_kind = str(current.get("progress_kind", "") or "")
            if (
                bool(self._coordinate_hypothesis_repair_commitment_complete_on_restore_enabled())
                and current_progress_kind == "satisfied_pair_regression_repair"
                and str(outcome.get("primitive_id", "") or "") == "coordinate_hypothesis_target_commitment"
                and int(outcome.get("post_satisfied_pair_count", 0) or 0)
                > int(outcome.get("pre_satisfied_pair_count", 0) or 0)
            ):
                if isinstance(outcome, dict):
                    outcome["regression_repair_commitment_completed"] = True
                    outcome["regression_repair_completion_target_key"] = str(
                        current.get("target_key", "") or target_key
                    )
                    if bool(
                        self._coordinate_hypothesis_repair_completion_provider_cooldown_enabled()
                    ):
                        cooldown_steps = (
                            self._coordinate_hypothesis_repair_completion_provider_cooldown_steps()
                        )
                        cooldown_min_score_successes = (
                            self._coordinate_hypothesis_repair_completion_provider_cooldown_min_score_successes()
                        )
                        outcome["repair_completion_provider_cooldown_steps"] = int(cooldown_steps)
                        outcome["repair_completion_provider_cooldown_min_score_successes"] = int(
                            cooldown_min_score_successes
                        )
                        outcome["repair_completion_provider_cooldown_score_success_count"] = int(
                            self._coordinate_hypothesis_score_success_count
                        )
                        if (
                            int(self._coordinate_hypothesis_score_success_count)
                            >= int(cooldown_min_score_successes)
                        ):
                            self._coordinate_hypothesis_provider_cooldown_remaining = max(
                                int(self._coordinate_hypothesis_provider_cooldown_remaining),
                                int(cooldown_steps),
                            )
                            self._coordinate_hypothesis_provider_cooldown_source = (
                                "repair_completion_provider_cooldown"
                            )
                            outcome["repair_completion_provider_cooldown_started"] = True
                        else:
                            outcome["repair_completion_provider_cooldown_started"] = False
                            outcome["repair_completion_provider_cooldown_skipped_reason"] = (
                                "min_score_successes"
                            )
                self._coordinate_hypothesis_target_commitment.clear()
                return
            if bool(self._coordinate_hypothesis_satisfied_target_handoff_enabled()):
                handoff_target_key = ""
                for raw_key in list(outcome.get("post_unsatisfied_target_keys") or []):
                    candidate_key = str(raw_key or "")
                    if candidate_key and not _coordinate_target_keys_match(target_key, candidate_key):
                        handoff_target_key = candidate_key
                        break
                if (
                    handoff_target_key
                    and int(outcome.get("post_satisfied_pair_count", 0) or 0)
                    > int(outcome.get("pre_satisfied_pair_count", 0) or 0)
                ):
                    self._coordinate_hypothesis_target_commitment = {
                        "target_key": handoff_target_key,
                        "source_plan_id": int(outcome.get("plan_id", 0) or 0),
                        "source_primitive_id": str(outcome.get("primitive_id", "") or ""),
                        "progress_kind": "satisfied_target_handoff",
                        "handoff_from_target_key": target_key,
                        "handoff_reason": "post_satisfied_pair_remaining_unsatisfied_target",
                        "attempt_count": 0,
                        "last_progress_site": list(outcome.get("selected_site") or []),
                    }
                    return
            if bool(self._coordinate_hypothesis_preserve_satisfied_handoff_enabled()):
                current_target_key = str(current.get("target_key", "") or "")
                handoff_from_key = str(current.get("handoff_from_target_key", "") or "")
                current_still_unsatisfied = any(
                    _coordinate_target_keys_match(current_target_key, str(raw_key or ""))
                    for raw_key in list(outcome.get("post_unsatisfied_target_keys") or [])
                )
                if (
                    str(current.get("progress_kind", "") or "") == "satisfied_target_handoff"
                    and current_target_key
                    and handoff_from_key
                    and _coordinate_target_keys_match(handoff_from_key, target_key)
                    and not _coordinate_target_keys_match(current_target_key, target_key)
                    and current_still_unsatisfied
                ):
                    current["preserved_through_source_progress_count"] = (
                        int(current.get("preserved_through_source_progress_count", 0) or 0) + 1
                    )
                    current["last_source_progress_site"] = list(outcome.get("selected_site") or [])
                    current["last_source_progress_kind"] = str(
                        outcome.get("objective_progress_kind", "") or ""
                    )
                    self._coordinate_hypothesis_target_commitment = current
                    return
            if bool(
                self._coordinate_hypothesis_target_commitment_satisfied_target_churn_guard_enabled()
            ):
                post_satisfied_keys = [
                    str(key or "")
                    for key in list(outcome.get("post_satisfied_target_keys") or [])
                    if str(key or "")
                ]
                post_unsatisfied_keys = [
                    str(key or "")
                    for key in list(outcome.get("post_unsatisfied_target_keys") or [])
                    if str(key or "")
                ]
                remaining_unsatisfied_keys = (
                    self._coordinate_hypothesis_satisfied_target_churn_remaining_keys(
                        selected_target_key=target_key,
                        satisfied_target_keys=post_satisfied_keys,
                        unsatisfied_target_keys=post_unsatisfied_keys,
                    )
                )
                if (
                    remaining_unsatisfied_keys
                    and int(outcome.get("score_before", 0) or 0) > 0
                    and int(outcome.get("score_delta", 0) or 0) <= 0
                ):
                    score_evidence_count = (
                        self._coordinate_hypothesis_target_score_evidence_count(target_key)
                    )
                    event = {
                        "source": "target_commitment_update_sensor",
                        "primitive_id": str(outcome.get("primitive_id", "") or ""),
                        "plan_id": int(outcome.get("plan_id", 0) or 0),
                        "selected_site": list(outcome.get("selected_site") or []),
                        "selected_target_key": str(target_key),
                        "remaining_unsatisfied_target_keys": list(
                            remaining_unsatisfied_keys
                        ),
                        "positive_score_evidence_count": int(score_evidence_count),
                        "score_before": int(outcome.get("score_before", 0) or 0),
                        "score_delta": int(outcome.get("score_delta", 0) or 0),
                        "block_reason": "",
                    }
                    if isinstance(outcome, dict):
                        outcome["satisfied_target_churn_guard_observed"] = True
                        outcome["satisfied_target_churn_target_key"] = str(target_key)
                        outcome["satisfied_target_churn_remaining_unsatisfied_target_keys"] = list(
                            remaining_unsatisfied_keys
                        )
                        outcome["satisfied_target_churn_positive_score_evidence_count"] = int(
                            score_evidence_count
                        )
                    self._record_coordinate_hypothesis_satisfied_target_churn_event(event)
            self._coordinate_hypothesis_target_commitment = {
                "target_key": target_key,
                "source_plan_id": int(outcome.get("plan_id", 0) or 0),
                "source_primitive_id": str(outcome.get("primitive_id", "") or ""),
                "progress_kind": str(outcome.get("objective_progress_kind", "") or ""),
                "attempt_count": 0,
                "last_progress_site": list(outcome.get("selected_site") or []),
            }
            return
        current_key = str(self._coordinate_hypothesis_target_commitment.get("target_key", "") or "")
        if (
            current_key
            and verdict == "falsified_no_coordinate_progress"
            and _coordinate_target_keys_match(current_key, target_key)
        ):
            if (
                bool(self._coordinate_hypothesis_terminal_failed_commitment_retirement_enabled())
                and int(outcome.get("score_before", 0) or 0) >= 3
            ):
                if isinstance(outcome, dict):
                    outcome["terminal_failed_commitment_retired"] = True
                    outcome["terminal_failed_commitment_retired_target_key"] = current_key
                self._coordinate_hypothesis_target_commitment.clear()
                return
            if not bool(outcome.get("plan_completed")):
                return
            if str(outcome.get("primitive_id", "") or "") == "coordinate_hypothesis_target_commitment":
                self._coordinate_hypothesis_target_commitment.clear()
                return
            commitment = dict(self._coordinate_hypothesis_target_commitment)
            commitment["last_no_progress_plan_id"] = int(outcome.get("plan_id", 0) or 0)
            commitment["last_no_progress_site"] = list(outcome.get("selected_site") or [])
            commitment["last_no_progress_primitive_id"] = str(outcome.get("primitive_id", "") or "")
            self._coordinate_hypothesis_target_commitment = commitment

    def _target_operator_for_candidate(
        self,
        candidate: dict[str, Any],
        *,
        selection: PrimitiveSelection | None = None,
        default: str = "route_to",
    ) -> str:
        if selection is not None:
            operator = str((selection.control_target or {}).get("primary_operator", "") or "")
            if operator:
                return operator
        operator = str(candidate.get("operator", "") or "")
        return operator or default

    def _target_candidate_key(
        self,
        candidate: dict[str, Any],
        *,
        operator: str | None = None,
    ) -> tuple[str, int, int, str] | None:
        site = candidate.get("site")
        if not isinstance(site, (list, tuple)) or len(site) < 2:
            return None
        try:
            x = int(site[0])
            y = int(site[1])
        except (TypeError, ValueError):
            return None
        return (str(candidate.get("kind", "") or "target"), x, y, str(operator or "route_to"))

    def _pop_goal_shortplan_step(
        self,
        available: set[str],
    ) -> tuple[str, dict[str, Any] | None] | None:
        if not self._enable_goal_bearing_shortplan:
            return None
        while self._active_goal_shortplan:
            action_name, payload = self._active_goal_shortplan.popleft()
            action = _normalize_action_name(action_name)
            if action in available:
                self._goal_shortplan_stats["post_transition_plan_executed"] += 1
                self._active_goal_shortplan_executed_count += 1
                return action, dict(payload) if isinstance(payload, Mapping) else None
            self._goal_shortplan_stats["post_transition_plan_aborted"] += 1
            self._record_goal_shortplan_plan_failure(reason="unavailable_action")
            self._active_goal_shortplan.clear()
            self._active_goal_shortplan_target.clear()
            self._active_goal_shortplan_score_delta = 0
            self._active_goal_shortplan_executed_count = 0
            self._active_goal_shortplan_last_distance = None
            self._active_goal_shortplan_no_improve_count = 0
            return None
        return None

    def _pending_target_from_unknown_action_choice(
        self,
        choice: Mapping[str, Any],
        *,
        action_name: str,
        action_payload: Mapping[str, Any] | None,
        actor_pos: tuple[int, int] | None,
    ) -> dict[str, Any] | None:
        hypothesis = choice.get("hypothesis") if isinstance(choice, Mapping) else None
        if hypothesis is None:
            return None
        x = getattr(hypothesis, "x", None)
        y = getattr(hypothesis, "y", None)
        try:
            site = [int(x), int(y)]
        except (TypeError, ValueError):
            site = []
        candidate = {
            "kind": "unknown_affordance",
            "site": list(site),
            "action_name": _normalize_action_name(action_name),
            "operator": "protected_probe",
            "objective_kind": "state_advance",
            "relation_kind": "weak_evidence_affordance",
            "source": "unknown_action_proposal",
            "goal_likelihood": float(getattr(hypothesis, "confidence", 0.0) or 0.0),
            "source_event_id": str(getattr(hypothesis, "source_event_id", "") or ""),
            "novelty_key": str(getattr(hypothesis, "novelty_key", "") or ""),
            "source_kind": str(getattr(hypothesis, "source_kind", "") or "psa_llm_proposed"),
            "llm_role": str(getattr(hypothesis, "llm_role", "") or "candidate_generation"),
            "expected_delta_signature": str(
                getattr(hypothesis, "expected_delta_signature", "") or ""
            ),
            "expected_post_state_hash": str(
                getattr(hypothesis, "expected_post_state_hash", "") or ""
            ),
            "state_precondition_mode": str(
                (getattr(hypothesis, "metadata", {}) or {}).get("state_precondition_mode", "")
                if isinstance(getattr(hypothesis, "metadata", {}), Mapping)
                else ""
            ),
        }
        pending = {
            "candidate": candidate,
            "primitive_id": "unknown_affordance_probe",
            "solver_family": "unknown_affordance_probe",
            "operator": "protected_probe",
            "action_name": _normalize_action_name(action_name),
            "action_payload": dict(action_payload or {}),
            "objective_kind": "state_advance",
            "source_kind": str(getattr(hypothesis, "source_kind", "") or "psa_llm_proposed"),
            "llm_role": str(getattr(hypothesis, "llm_role", "") or "candidate_generation"),
            "expected_post_state_hash": candidate["expected_post_state_hash"],
            "expected_delta_signature": candidate["expected_delta_signature"],
        }
        if site:
            pending["key"] = ["unknown_affordance", int(site[0]), int(site[1]), "protected_probe"]
        if actor_pos is not None:
            pending["actor_pos"] = [int(actor_pos[0]), int(actor_pos[1])]
            pending["actor_pos_source"] = "current_state_reader"
        return pending

    def _pending_target_from_goal_shortplan(
        self,
        *,
        action_name: str,
        actor_pos: tuple[int, int] | None,
    ) -> dict[str, Any] | None:
        if not self._active_goal_shortplan_target:
            return None
        pending = dict(self._active_goal_shortplan_target)
        pending["action_name"] = _normalize_action_name(action_name)
        pending["primitive_id"] = "goal_bearing_shortplan"
        pending["solver_family"] = "goal_shortplan"
        pending["operator"] = "route_to"
        if actor_pos is not None:
            pending["actor_pos"] = [int(actor_pos[0]), int(actor_pos[1])]
            pending["actor_pos_source"] = "current_state_reader"
        return pending

    def _goal_linked_select_push_pending_target(
        self,
        state: Mapping[str, Any] | None,
        *,
        action_name: str,
        action_payload: Mapping[str, Any] | None,
        primitive_id: str,
    ) -> dict[str, Any] | None:
        if not self._enable_goal_bearing_shortplan:
            return None
        action = _normalize_action_name(action_name)
        if action not in DIRECTIONAL_ACTIONS:
            return None
        if not isinstance(state, Mapping):
            return None
        active_piece = _site_tuple(state.get("active_piece"))
        raw_targets = state.get("targets")
        if active_piece is None or not isinstance(raw_targets, list):
            return None
        stride = max(1, int(state.get("stride", 3) or 3))
        actor = (int(active_piece[0]) + 1, int(active_piece[1]) + 1)
        dx, dy = {
            "ACTION1": (0, -stride),
            "ACTION2": (0, stride),
            "ACTION3": (-stride, 0),
            "ACTION4": (stride, 0),
        }.get(action, (0, 0))
        next_actor = (actor[0] + dx, actor[1] + dy)
        target_centres: list[tuple[int, int]] = []
        for raw_target in raw_targets:
            target = _site_tuple(raw_target)
            if target is not None:
                target_centres.append((int(target[0]) + 1, int(target[1]) + 1))
        if not target_centres:
            return None
        scored = []
        for target in target_centres:
            before = _manhattan(actor, target)
            after = _manhattan(next_actor, target)
            scored.append((after - before, after, target))
        scored.sort()
        delta, _after, target = scored[0]
        if delta >= 0:
            return None
        candidate = {
            "kind": "macro_score_route",
            "site": [int(target[0]), int(target[1])],
            "action_name": action,
            "score_delta": 0,
            "goal_likelihood": 0.65,
            "objective_kind": "state_advance",
            "relation_kind": "select_push_cover_target_alignment",
            "source": "select_push_cover_goal_link",
            "macro_goal_link": True,
        }
        if self._goal_failure_posterior_blocks_candidate(
            candidate,
            action_name=action,
            operator="push",
        ):
            return None
        pending = self._pending_target_from_candidate(
            candidate,
            operator="push",
            action_name=action,
            primitive_id=primitive_id,
            actor_pos=actor,
            actor_pos_source="select_push_active_piece",
        )
        if pending is not None and isinstance(action_payload, Mapping):
            pending["action_payload"] = dict(action_payload)
        return pending

    def _goal_failure_posterior_blocks_candidate(
        self,
        candidate: Mapping[str, Any],
        *,
        action_name: str,
        operator: str,
    ) -> bool:
        objective_kind = _objective_kind_for_candidate(candidate)
        if not _objective_kind_goal_bearing(objective_kind):
            return False
        posterior_key = _goal_failure_posterior_key(
            target_kind=str(candidate.get("kind", "") or "target"),
            objective_kind=objective_kind,
            action_name=action_name,
            operator=operator,
        )
        failures = int(self._goal_failure_posterior[posterior_key])
        successes = int(self._goal_success_posterior[posterior_key])
        return bool(failures >= 2 and successes <= 0)

    def _record_goal_shortplan_plan_failure(self, *, reason: str) -> None:
        pending = dict(self._active_goal_shortplan_target or {})
        if not pending:
            return
        candidate = pending.get("candidate")
        candidate = candidate if isinstance(candidate, Mapping) else {}
        target_kind = str(candidate.get("kind", "") or "goal_shortplan_target")
        objective_kind = str(pending.get("objective_kind", "") or "") or _objective_kind_for_candidate(candidate)
        action_name = str(pending.get("action_name", "") or "")
        operator = str(pending.get("operator", "") or "route_to")
        posterior_key = _goal_failure_posterior_key(
            target_kind=target_kind,
            objective_kind=objective_kind,
            action_name=action_name,
            operator=operator,
        )
        self._goal_failure_posterior[posterior_key] += 1
        self._goal_shortplan_stats["post_transition_plan_no_score_failure_count"] += 1
        self._goal_shortplan_stats["post_transition_plan_failure_posterior_update_count"] += 1
        if reason:
            self._goal_shortplan_stats[f"post_transition_plan_failure_reason:{reason}"] += 1
        raw_key = pending.get("key")
        if isinstance(raw_key, list) and len(raw_key) >= 4:
            try:
                key = (str(raw_key[0]), int(raw_key[1]), int(raw_key[2]), str(raw_key[3]))
            except (TypeError, ValueError):
                key = None
            if key is not None:
                self._target_failures[key] += 1

    def _goal_shortplan_target_and_actor(
        self,
        frame: np.ndarray,
    ) -> tuple[tuple[int, int], tuple[int, int]] | None:
        pending = dict(self._active_goal_shortplan_target or {})
        if not pending:
            return None
        candidate = pending.get("candidate")
        candidate = candidate if isinstance(candidate, Mapping) else {}
        target = _site_tuple(candidate.get("site"))
        if target is None:
            target = _site_tuple(pending.get("target_key")[1:3] if isinstance(pending.get("target_key"), list) else None)
        if target is None:
            return None
        actor_source = str(pending.get("actor_pos_source", "") or "")
        actor = (
            self._mirror_joint_cursor_proxy_position(frame, target)
            if actor_source == "mirror_joint_cursor"
            else self._actor_position(frame)
        )
        if actor is None:
            actor = _site_tuple(pending.get("actor_pos"))
        if actor is None:
            return None
        return target, actor

    def _abort_goal_shortplan(self, *, reason: str) -> None:
        self._goal_shortplan_stats["post_transition_plan_aborted"] += 1
        if reason:
            self._goal_shortplan_stats[f"post_transition_plan_abort_reason:{reason}"] += 1
        self._record_goal_shortplan_plan_failure(reason=reason)
        self._active_goal_shortplan.clear()
        self._active_goal_shortplan_target.clear()
        self._active_goal_shortplan_score_delta = 0
        self._active_goal_shortplan_executed_count = 0
        self._active_goal_shortplan_last_distance = None
        self._active_goal_shortplan_no_improve_count = 0

    def _update_goal_shortplan_target_health(
        self,
        record: ActionEffectRecord,
        post_frame: np.ndarray,
    ) -> None:
        if not self._active_goal_shortplan_target:
            return
        if int(record.score_delta) > 0:
            self._active_goal_shortplan_no_improve_count = 0
            return
        target_actor = self._goal_shortplan_target_and_actor(post_frame)
        if target_actor is None:
            self._goal_shortplan_stats["target_health_unknown_count"] += 1
            self._active_goal_shortplan_no_improve_count += 1
        else:
            target, actor = target_actor
            distance = _manhattan(actor, target)
            self._goal_shortplan_stats["target_health_check_count"] += 1
            previous = self._active_goal_shortplan_last_distance
            if previous is None or distance < int(previous):
                self._goal_shortplan_stats["target_health_improved_count"] += 1
                self._active_goal_shortplan_no_improve_count = 0
            else:
                self._goal_shortplan_stats["target_health_not_improving_count"] += 1
                self._active_goal_shortplan_no_improve_count += 1
            self._active_goal_shortplan_last_distance = int(distance)
        if bool(record.no_op) or int(record.changed_pixel_count) <= 0:
            self._active_goal_shortplan_no_improve_count += 1
        if self._active_goal_shortplan_no_improve_count >= 2 and self._active_goal_shortplan:
            self._goal_shortplan_stats["target_health_abort_count"] += 1
            self._abort_goal_shortplan(reason="target_health_not_improving")

    def _finalize_goal_shortplan_outcome(self, record: ActionEffectRecord) -> None:
        if not self._active_goal_shortplan_target:
            return
        if int(self._active_goal_shortplan_executed_count) <= 0:
            return
        self._goal_shortplan_stats["post_transition_plan_completed"] += 1
        if int(self._active_goal_shortplan_score_delta) > 0 or int(record.score_delta) > 0:
            pending = dict(self._active_goal_shortplan_target or {})
            candidate = pending.get("candidate")
            candidate = candidate if isinstance(candidate, Mapping) else {}
            posterior_key = _goal_failure_posterior_key(
                target_kind=str(candidate.get("kind", "") or "goal_shortplan_target"),
                objective_kind=str(pending.get("objective_kind", "") or "")
                or _objective_kind_for_candidate(candidate),
                action_name=str(record.action_name),
                operator=str(pending.get("operator", "") or "route_to"),
            )
            self._goal_success_posterior[posterior_key] += 1
        else:
            self._record_goal_shortplan_plan_failure(reason="completed_no_score")
        self._active_goal_shortplan_target.clear()
        self._active_goal_shortplan_score_delta = 0
        self._active_goal_shortplan_executed_count = 0
        self._active_goal_shortplan_last_distance = None
        self._active_goal_shortplan_no_improve_count = 0

    def _control_target_with_pending_goal_context(
        self,
        selection: PrimitiveSelection,
    ) -> dict[str, Any]:
        control_target = dict(selection.control_target or {})
        pending = self._pending_control_target
        if not isinstance(pending, Mapping):
            return control_target
        candidate = pending.get("candidate")
        if not isinstance(candidate, Mapping):
            return control_target
        objective_kind = _objective_kind_for_candidate(candidate)
        if not _objective_kind_goal_bearing(objective_kind):
            return control_target
        candidate_dict = dict(candidate)
        existing_targets = [
            dict(item)
            for item in list(control_target.get("target_candidates") or [])
            if isinstance(item, dict)
        ]
        control_target.update(
            {
                "primitive_id": str(pending.get("primitive_id", "") or control_target.get("primitive_id", "")),
                "solver_family": str(pending.get("solver_family", "") or control_target.get("solver_family", "")),
                "primary_operator": str(pending.get("operator", "") or control_target.get("primary_operator", "")),
                "primary_target": candidate_dict,
                "target_candidates": _dedupe_target_candidates([candidate_dict] + existing_targets),
            }
        )
        control_target["goal_target_contract"] = self._goal_target_contract(control_target)
        return control_target

    def _seed_goal_shortplan_from_verification(
        self,
        verification: Mapping[str, Any],
        *,
        pending: Mapping[str, Any],
        post_frame: np.ndarray,
    ) -> None:
        if not self._enable_goal_bearing_shortplan:
            return
        if str(verification.get("primitive_id", "") or "") == "goal_bearing_shortplan":
            return
        if self._active_goal_shortplan:
            return
        if int(verification.get("score_delta", 0) or 0) > 0:
            return
        if not bool(verification.get("goal_aligned_progress")):
            return
        target = _site_tuple((pending.get("candidate") if isinstance(pending.get("candidate"), Mapping) else {}).get("site"))
        if target is None:
            target = _site_tuple(verification.get("target_key")[1:3] if isinstance(verification.get("target_key"), list) else None)
        if target is None:
            return
        actor_source = str(verification.get("actor_pos_source", "") or "")
        actor = (
            self._mirror_joint_cursor_proxy_position(post_frame, target)
            if actor_source == "mirror_joint_cursor"
            else self._actor_position(post_frame)
        )
        if actor is None:
            actor = _site_tuple(pending.get("actor_pos"))
        if actor is None:
            return
        plan = _route_shortplan_actions(
            actor,
            target,
            max_len=self._goal_shortplan_max_len,
        )
        if not plan:
            return
        payload_plan = [(action, None) for action in plan]
        self._active_goal_shortplan = deque(payload_plan)
        self._active_goal_shortplan_target = dict(pending)
        self._active_goal_shortplan_score_delta = 0
        self._active_goal_shortplan_executed_count = 0
        self._active_goal_shortplan_last_distance = _manhattan(actor, target)
        self._active_goal_shortplan_no_improve_count = 0
        self._goal_shortplan_stats["post_transition_plan_generated"] += 1
        self._goal_shortplan_stats["post_transition_plan_action_count"] += len(plan)
        self._goal_shortplan_stats["post_transition_plan_length_total"] += len(plan)
        if bool(verification.get("goal_aligned_progress")):
            self._goal_shortplan_stats["goal_linked_plan_count"] += 1

    def _goal_failure_posterior_summary(self) -> dict[str, Any]:
        keys = set(self._goal_failure_posterior)
        keys.update(self._goal_success_posterior)
        by_key: dict[str, dict[str, Any]] = {}
        for key in sorted(keys):
            failures = int(self._goal_failure_posterior[key])
            successes = int(self._goal_success_posterior[key])
            attempts = failures + successes
            text_key = "|".join(str(part) for part in key)
            by_key[text_key] = {
                "target_kind": str(key[0]),
                "objective_kind": str(key[1]),
                "action_family": str(key[2]),
                "attempts": attempts,
                "successes": successes,
                "failures": failures,
                "failure_rate": round(float(failures) / float(max(1, attempts)), 6),
            }
        return {
            "update_count": int(
                sum(self._goal_failure_posterior.values())
                + sum(self._goal_success_posterior.values())
            ),
            "failure_update_count": int(sum(self._goal_failure_posterior.values())),
            "success_update_count": int(sum(self._goal_success_posterior.values())),
            "by_target_action_family": by_key,
        }

