    def _mechanic_hypothesis_outcome_summary(self) -> dict[str, Any]:
        confirmed_total = int(sum(self._mechanic_hypothesis_confirmed.values()))
        falsified_total = int(sum(self._mechanic_hypothesis_falsified.values()))
        source_kinds = set(self._mechanic_hypothesis_confirmed)
        source_kinds.update(self._mechanic_hypothesis_falsified)
        primitive_id_counts: dict[str, dict[str, int]] = {}
        for item in self._mechanic_hypothesis_outcomes:
            primitive_id = str(item.get("primitive_id", "") or "unknown")
            verdict = str(item.get("verdict", "") or "")
            bucket = primitive_id_counts.setdefault(primitive_id, {"confirmed": 0, "falsified": 0})
            if verdict == "confirmed":
                bucket["confirmed"] += 1
            elif verdict == "falsified":
                bucket["falsified"] += 1
        return {
            "outcome_count": int(len(self._mechanic_hypothesis_outcomes)),
            "confirmed_count": confirmed_total,
            "falsified_count": falsified_total,
            "source_kind_counts": {
                str(kind): {
                    "confirmed": int(self._mechanic_hypothesis_confirmed[kind]),
                    "falsified": int(self._mechanic_hypothesis_falsified[kind]),
                }
                for kind in sorted(source_kinds)
            },
            "primitive_id_counts": {
                primitive_id: dict(counts)
                for primitive_id, counts in sorted(primitive_id_counts.items())
            },
            "recent": list(self._mechanic_hypothesis_outcomes[-8:]),
        }

    def _mechanic_hypothesis_posterior_summary(
        self,
        *,
        gate: Mapping[str, Any] | None = None,
    ) -> dict[str, Any]:
        keys = set(self._mechanic_hypothesis_posterior_confirmed)
        keys.update(self._mechanic_hypothesis_posterior_falsified)
        keys.update(self._mechanic_hypothesis_posterior_suppressed)
        recent = [
            {
                "posterior_key": str(key),
                "confirmed": int(self._mechanic_hypothesis_posterior_confirmed[key]),
                "falsified": int(self._mechanic_hypothesis_posterior_falsified[key]),
                "suppressed": int(self._mechanic_hypothesis_posterior_suppressed[key]),
            }
            for key in sorted(keys)[-8:]
        ]
        return {
            "enabled": bool(self._mechanic_hypothesis_posterior_enabled()),
            "confirmed_count": int(sum(self._mechanic_hypothesis_posterior_confirmed.values())),
            "falsified_count": int(sum(self._mechanic_hypothesis_posterior_falsified.values())),
            "suppressed_count": int(sum(self._mechanic_hypothesis_posterior_suppressed.values())),
            "gate": dict(gate or {}),
            "recent": recent,
        }

    def _mechanic_hypothesis_goal_candidate_summary(self) -> dict[str, Any]:
        candidates = list(self._mechanic_hypothesis_goal_candidates)
        return {
            "candidate_count": int(len(candidates)),
            "score_bearing_candidate_count": int(
                sum(1 for item in candidates if bool(item.get("score_bearing_candidate")))
            ),
            "score_evidence_candidate_count": int(
                sum(1 for item in candidates if bool(item.get("score_evidence")))
            ),
            "goal_aligned_candidate_count": int(
                sum(1 for item in candidates if bool(item.get("goal_aligned_candidate")))
            ),
            "structural_only_candidate_count": int(
                sum(1 for item in candidates if bool(item.get("structural_only_candidate")))
            ),
            "recent": candidates[-8:],
        }

    def _mechanic_hypothesis_goal_plan_summary(
        self,
        *,
        gate: Mapping[str, Any] | None = None,
    ) -> dict[str, Any]:
        return {
            "enabled": bool(self._mechanic_hypothesis_goal_candidate_plan_enabled()),
            "compiled_count": int(self._mechanic_hypothesis_goal_plan_stats.get("compiled_count", 0)),
            "score_bearing_plan_count": int(
                self._mechanic_hypothesis_goal_plan_stats.get("score_bearing_plan_count", 0)
            ),
            "score_evidence_plan_count": int(
                self._mechanic_hypothesis_goal_plan_stats.get("score_evidence_plan_count", 0)
            ),
            "goal_linked_plan_count": int(
                self._mechanic_hypothesis_goal_plan_stats.get("goal_linked_plan_count", 0)
            ),
            "non_score_bearing_validation_plan_count": int(
                self._mechanic_hypothesis_goal_plan_stats.get("non_score_bearing_validation_plan_count", 0)
            ),
            "suppressed_count": int(
                self._mechanic_hypothesis_goal_plan_stats.get("suppressed_count", 0)
            ),
            "gate": dict(gate or {}),
        }

    def _mechanic_hypothesis_goal_candidate_plan_step(
        self,
        *,
        current_hash: str,
        available_actions: Iterable[str],
    ) -> tuple[dict[str, Any] | None, dict[str, Any]]:
        enabled = self._mechanic_hypothesis_goal_candidate_plan_enabled()
        available = {_normalize_action_name(action) for action in available_actions}
        gate: dict[str, Any] = {
            "enabled": bool(enabled),
            "candidate_count": int(len(self._mechanic_hypothesis_goal_candidates)),
            "suppressed_count": 0,
            "suppressed_reasons": {},
            "selected_key": "",
        }
        if not enabled:
            return None, gate
        for candidate in reversed(self._mechanic_hypothesis_goal_candidates):
            reason = self._mechanic_hypothesis_goal_candidate_plan_reject_reason(
                candidate,
                current_hash=current_hash,
                available=available,
            )
            if reason:
                gate["suppressed_count"] = int(gate["suppressed_count"]) + 1
                reasons = dict(gate["suppressed_reasons"])
                reasons[reason] = int(reasons.get(reason, 0)) + 1
                gate["suppressed_reasons"] = reasons
                self._mechanic_hypothesis_goal_plan_stats["suppressed_count"] += 1
                self._mechanic_hypothesis_goal_plan_stats[f"suppressed_reason:{reason}"] += 1
                continue
            bounded_plan = candidate.get("bounded_plan")
            if not isinstance(bounded_plan, list) or not bounded_plan:
                continue
            step = bounded_plan[0]
            if not isinstance(step, Mapping):
                continue
            action_name = _normalize_action_name(step.get("action_name"))
            payload = step.get("payload") if isinstance(step.get("payload"), Mapping) else {}
            plan_key = self._mechanic_hypothesis_goal_candidate_plan_key(candidate)
            self._mechanic_hypothesis_goal_plan_attempted.add(plan_key)
            if (
                not bool(candidate.get("score_bearing_candidate"))
                and not bool(candidate.get("goal_linked_candidate"))
            ):
                self._mechanic_hypothesis_goal_plan_attempted.add(
                    self._mechanic_hypothesis_goal_candidate_validation_key(candidate)
                )
            self._mechanic_hypothesis_goal_plan_stats["compiled_count"] += 1
            if bool(candidate.get("score_bearing_candidate")):
                self._mechanic_hypothesis_goal_plan_stats["score_bearing_plan_count"] += 1
            elif bool(candidate.get("goal_linked_candidate")):
                self._mechanic_hypothesis_goal_plan_stats["goal_linked_plan_count"] += 1
            else:
                self._mechanic_hypothesis_goal_plan_stats["non_score_bearing_validation_plan_count"] += 1
            if bool(candidate.get("score_evidence")):
                self._mechanic_hypothesis_goal_plan_stats["score_evidence_plan_count"] += 1
            gate["selected_key"] = plan_key
            return {
                "primitive_id": "mechanic_hypothesis_goal_candidate_plan",
                "source_primitive_id": str(
                    candidate.get("source_primitive_id", "")
                    or "mechanic_hypothesis_goal_candidate"
                ),
                "source_kind": str(candidate.get("source_kind", "") or ""),
                "llm_role": str(candidate.get("llm_role", "") or "none"),
                "llm_direct_action": bool(candidate.get("llm_direct_action", False)),
                "hypothesis_id": str(candidate.get("hypothesis_id", "") or ""),
                "posterior_key": str(candidate.get("posterior_key", "") or ""),
                "repair_id": str(candidate.get("repair_id", "") or ""),
                "goal_link_id": str(candidate.get("goal_link_id", "") or ""),
                "protected_plan_id": str(candidate.get("protected_plan_id", "") or ""),
                "protected_plan_len": int(candidate.get("protected_plan_len", 0) or 0),
                "protected_plan_step_index": int(candidate.get("protected_plan_step_index", 0) or 0),
                "candidate": dict(candidate),
                "step": (
                    action_name,
                    {key: int(value) for key, value in dict(payload).items() if key in {"x", "y"}},
                ),
                "score_bearing_candidate": bool(candidate.get("score_bearing_candidate")),
                "claim_boundary": str(candidate.get("claim_boundary", "") or ""),
                "reason": (
                    "mechanic_hypothesis_goal_candidate_plan compiled bounded "
                    "intervention from confirmed hypothesis posterior"
                ),
            }, gate
        return None, gate

    def _mechanic_hypothesis_goal_candidate_plan_reject_reason(
        self,
        candidate: Mapping[str, Any],
        *,
        current_hash: str,
        available: set[str],
    ) -> str:
        posterior_key = str(candidate.get("posterior_key", "") or "")
        if not posterior_key:
            return "missing_posterior_key"
        if bool(candidate.get("llm_direct_action", False)):
            return "llm_direct_action"
        if str(candidate.get("source_primitive_id", "") or "") == "unknown_affordance_probe":
            confirmed = int(self._unknown_affordance_posterior_support[posterior_key])
            falsified = int(self._unknown_affordance_posterior_falsified[posterior_key])
        else:
            confirmed = int(self._mechanic_hypothesis_posterior_confirmed[posterior_key])
            falsified = int(self._mechanic_hypothesis_posterior_falsified[posterior_key])
        if confirmed <= 0 or confirmed <= falsified:
            return "posterior_key_unconfirmed"
        if (
            not bool(candidate.get("score_bearing_candidate"))
            and not bool(candidate.get("goal_linked_candidate"))
            and self._mechanic_hypothesis_goal_candidate_validation_key(candidate)
            in self._mechanic_hypothesis_goal_plan_attempted
        ):
            return "non_score_validation_already_attempted"
        expected_hash = str(candidate.get("required_current_state_hash", "") or "")
        if expected_hash and expected_hash != str(current_hash or ""):
            return "stale_current_state"
        bounded_plan = candidate.get("bounded_plan")
        if not isinstance(bounded_plan, list) or not bounded_plan:
            return "missing_bounded_plan"
        max_len = int(candidate.get("bounded_plan_max_len", len(bounded_plan)) or len(bounded_plan))
        family = str(candidate.get("mechanic_family", "") or "")
        hard_limit = 32 if family in {"coverage", "reflection"} else 6
        if max_len > hard_limit or len(bounded_plan) > max_len:
            return "bounded_plan_too_long"
        plan_key = self._mechanic_hypothesis_goal_candidate_plan_key(candidate)
        if plan_key in self._mechanic_hypothesis_goal_plan_attempted:
            return "already_attempted"
        step = bounded_plan[0]
        if not isinstance(step, Mapping):
            return "malformed_bounded_step"
        action_name = _normalize_action_name(step.get("action_name"))
        if not action_name or action_name not in available:
            return "action_unavailable"
        if action_name == "ACTION6":
            site = _site_tuple(candidate.get("site"))
            payload = step.get("payload") if isinstance(step.get("payload"), Mapping) else {}
            payload_site = _site_tuple((payload.get("x"), payload.get("y")))
            if site is None or payload_site is None or site != payload_site:
                return "wrong_click_site"
        return ""

    def _mechanic_hypothesis_goal_candidate_plan_key(
        self,
        candidate: Mapping[str, Any],
    ) -> str:
        plan = candidate.get("bounded_plan")
        step = plan[0] if isinstance(plan, list) and plan else {}
        step = step if isinstance(step, Mapping) else {}
        payload = step.get("payload") if isinstance(step.get("payload"), Mapping) else {}
        payload_key = ",".join(f"{key}={payload.get(key)}" for key in sorted(payload))
        return "|".join(
            [
                str(candidate.get("posterior_key", "") or ""),
                _normalize_action_name(step.get("action_name")),
                payload_key,
                str(candidate.get("required_current_state_hash", "") or ""),
            ]
        )

    def _mechanic_hypothesis_goal_candidate_validation_key(
        self,
        candidate: Mapping[str, Any],
    ) -> str:
        return "validation|" + str(candidate.get("posterior_key", "") or "")

    def _click_site_discovery_summary(self) -> dict[str, Any]:
        return {
            "enabled": self._click_site_discovery_enabled(),
            "attempt_count": int(sum(self._click_discovery_attempts.values())),
            "success_count": int(sum(self._click_discovery_successes.values())),
            "failure_count": int(sum(self._click_discovery_failures.values())),
            "tested_sites": [list(site) for site, _count in self._click_discovery_attempts.most_common(12)],
            "failed_sites": [list(site) for site, _count in self._click_discovery_failures.most_common(12)],
            "successful_sites": [list(site) for site, _count in self._click_discovery_successes.most_common(12)],
            "source_stats": self._click_discovery_source_stats(),
        }

    def _click_affordance_induction_summary(self) -> dict[str, Any]:
        return self.click_affordance_inducer.summary(
            enabled=self._click_affordance_induction_enabled()
        )

    def _click_visual_sampling_exhausted(self) -> bool:
        if int(sum(self._click_discovery_attempts.values())) < 24:
            return False
        if int(sum(self._click_discovery_successes.values())) > 0:
            return False
        if any(
            int(stats.get("successes", 0) or 0) > 0
            for stats in self._click_discovery_source_stats().values()
        ):
            return False
        induction_summary = self.click_affordance_inducer.summary(
            enabled=self._click_affordance_induction_enabled()
        )
        chain_stats = induction_summary.get("chain_stats")
        if isinstance(chain_stats, Mapping):
            for stats in chain_stats.values():
                if isinstance(stats, Mapping) and int(stats.get("successes", 0) or 0) > 0:
                    return False
        return True

    def _click_discovery_source_stats(self) -> dict[str, dict[str, int]]:
        sources = set(self._click_discovery_source_attempts)
        sources.update(self._click_discovery_source_successes)
        sources.update(self._click_discovery_source_failures)
        return {
            str(source): {
                "attempts": int(self._click_discovery_source_attempts[source]),
                "successes": int(self._click_discovery_source_successes[source]),
                "failures": int(self._click_discovery_source_failures[source]),
            }
            for source in sorted(sources)
        }

    def _grid_bfs_action(
        self,
        state_hash: str,
        summary,
        selection: PrimitiveSelection,
        available: set[str],
        *,
        actor_pos: tuple[int, int] | None,
        frame: np.ndarray | None = None,
    ) -> tuple[str, bool]:
        if actor_pos is not None:
            if self._post_broad_level_epoch():
                topology_target = self._current_click_topology_target(actor_pos=actor_pos)
                visual_route_action = self._visual_route_to_target(actor_pos, topology_target, frame, available)
                if visual_route_action is not None:
                    return visual_route_action, False
                topology_action = self._click_topology_biased_action(actor_pos, available)
                if topology_action is not None:
                    return topology_action, False
                visual_target_action = self._score_visual_target_action(actor_pos, frame, available)
                if visual_target_action is not None:
                    return visual_target_action, False
            actor_frontier = self._actor_frontier_actions(actor_pos, available)
            if self._actor_stagnating(actor_pos):
                stagnation_escape = self._actor_stagnation_escape_action(actor_pos, available)
                if stagnation_escape is not None:
                    return stagnation_escape, True
            if self._epoch_id > 0 or summary.score_event_count > 0:
                if actor_frontier:
                    return self._win_bias_tiebreak(actor_frontier, frame), True
                route_action = self._actor_graph_route_to_frontier(actor_pos, available)
                if route_action:
                    return route_action, False
                score_biased = self._score_precondition_biased_action(actor_pos, available)
                if score_biased is not None:
                    return score_biased, False
                actor_action = self._actor_graph_explore_action(actor_pos, available)
                if actor_action:
                    return actor_action, False
            hypothesis_directed = self._win_hypothesis_directed_action(
                actor_pos, available, frame,
            )
            if hypothesis_directed is not None:
                return hypothesis_directed, False
            goal_biased = self._goal_biased_actor_action(actor_pos, available)
            if goal_biased is not None:
                return goal_biased, False
            if actor_frontier:
                return _least_issued(actor_frontier, self._issued_counts), True
            route_action = self._actor_graph_route_to_frontier(actor_pos, available)
            if route_action:
                return route_action, False
            actor_action = self._actor_graph_explore_action(actor_pos, available)
            if actor_action:
                return actor_action, False
        frontier = self._frontier_actions(state_hash, available, preferred_actions=GOAL_BIASED_DIRECTIONAL_ACTIONS)
        if frontier:
            return _least_issued(frontier, self._issued_counts), True
        scored: list[tuple[float, int, str]] = []
        for action in GOAL_BIASED_DIRECTIONAL_ACTIONS:
            if action not in available:
                continue
            stats = summary.action_stats.get(action)
            if stats is None:
                scored.append((0.0, self._issued_counts[action], action))
                continue
            score = float(stats.changed_rate) + float(stats.localized_change_rate) - float(stats.no_op_rate)
            # W1 stage 2: bias exploration toward fulfilling the episode's
            # confirmed win relation (subject centroid -> object centroid).
            # Gated on the stuck condition so the soft bonus never reshapes
            # the generic base's directional ranking before it has had its
            # un-biased chance to score. (An ungated variant was measured
            # 2026-06-11: zero consultations on dc22's scoring path — this
            # grid-bfs ranking is not where pre-score routing happens; the
            # pre-score wiring lives in _goal_biased_actor_action.)
            if (
                self._win_relation_bias_enabled
                and frame is not None
                and self._win_hypothesis_exploration_stuck()
            ):
                score += 0.5 * self._win_relation_tracker.direction_bonus(frame, action)
            scored.append((score, self._issued_counts[action], action))
        if not scored:
            return self._probe_action(selection, available), False
        scored.sort(key=lambda item: (-item[0], item[1], item[2]))
        return scored[0][2], False

    @property
    def actor_value(self) -> int | None:
        if not self._actor_value_votes:
            return None
        value, votes = self._actor_value_votes.most_common(1)[0]
        return int(value) if votes > 0 else None

    def _update_actor_graph(self, record, pre_frame: np.ndarray, post_frame: np.ndarray) -> None:
        if record.action_name not in DIRECTIONAL_ACTIONS:
            return
        candidate = self._infer_actor_value(pre_frame, post_frame)
        if candidate is not None:
            self._actor_value_votes[int(candidate)] += 1
        pre_pos = self._actor_position(pre_frame)
        post_pos = self._actor_position(post_frame)
        # Gap-tolerant reset detection (bias-ON arm only): the reset
        # animation hides the actor for a frame, so the jump spans two
        # observes. Attribute the reappearance jump to the action taken
        # just before the gap.
        if self._win_relation_bias_enabled:
            if pre_pos is not None and post_pos is None:
                self._pending_actor_gap = (pre_pos, record.action_name)
            elif pre_pos is None and post_pos is not None \
                    and self._pending_actor_gap is not None:
                gap_pos, gap_action = self._pending_actor_gap
                gap_jump = abs(post_pos[0] - gap_pos[0]) + abs(post_pos[1] - gap_pos[1])
                if gap_jump > RESET_JUMP_DISTANCE:
                    self._reset_action_bans[(gap_pos, gap_action)] += 1
                self._pending_actor_gap = None
            elif pre_pos is not None and post_pos is not None:
                self._pending_actor_gap = None
        if pre_pos is None:
            return
        self._actor_action_attempts[pre_pos][record.action_name] += 1
        self._actor_visit_counts[pre_pos] += 1
        # E-1 S4 lane-local bucket bookkeeping (bias-ON arm only): the
        # facing-dot wobble aliases node keys; the bucket layer is what
        # the lane's systematic explorer reads (shared structures stay
        # untouched for the OFF arm).
        if self._win_relation_bias_enabled:
            bucket = (pre_pos[0] // LANE_NODE_BUCKET, pre_pos[1] // LANE_NODE_BUCKET)
            self._lane_node_attempts[(bucket, record.action_name)] += 1
            if post_pos is not None:
                post_bucket = (
                    post_pos[0] // LANE_NODE_BUCKET,
                    post_pos[1] // LANE_NODE_BUCKET,
                )
                if post_bucket != bucket:
                    self._lane_node_edges[(bucket, record.action_name)] = post_bucket
        if post_pos is not None:
            # E-1 S4 (bias-ON arm only; OFF stays bit-identical): a jump
            # far beyond any stride is a RESET/teleport hazard, not a
            # move. Recording it as a normal edge poisons the route graph
            # (measured tu93: the router used the reset edge
            # (28,22)->(16,16) as a path and orbited through the hazard
            # forever). Ban the (node, action) pair and keep the edge out
            # of the graph; the transport learner still sees it (its own
            # protected validation separates true transports from
            # resets).
            jump = abs(post_pos[0] - pre_pos[0]) + abs(post_pos[1] - pre_pos[1])
            if self._win_relation_bias_enabled and jump > RESET_JUMP_DISTANCE:
                self._reset_action_bans[(pre_pos, record.action_name)] += 1
                if self._transport_effect_repair_enabled:
                    self._observe_transport_effect(
                        record.action_name, pre_frame, pre_pos, post_pos
                    )
                self._actor_visit_counts[post_pos] += 1
                return
            # Phase M / P8: feed the transport learner BEFORE this step's
            # observation lands in _actor_action_targets, so the predicted
            # target is the modal target of PAST transitions only.
            if self._transport_effect_repair_enabled:
                self._observe_transport_effect(
                    record.action_name, pre_frame, pre_pos, post_pos
                )
            self._actor_action_targets[(pre_pos, record.action_name)][post_pos] += 1
            self._actor_visit_counts[post_pos] += 1
            if post_pos != pre_pos:
                if self._stride_lattice_plan_enabled:
                    self._transport_effect_learner.observe_move_displacement(
                        record.action_name,
                        (int(post_pos[0]) - int(pre_pos[0]), int(post_pos[1]) - int(pre_pos[1])),
                    )
                self._record_passable_values(pre_frame, post_frame, pre_pos, post_pos)
            elif self._passable_carryover_enabled:
                self._record_passable_contradiction(pre_frame, pre_pos, record.action_name)

    def _observe_transport_effect(
        self,
        action_name: str,
        pre_frame: np.ndarray,
        pre_pos: tuple[int, int],
        post_pos: tuple[int, int],
    ) -> None:
        """Phase M / P8: feed the TransportEffectLearner from the generic
        actor-graph layer.

        The predicted target is the OBSERVED modal target of past
        (pre_pos, action) transitions (>= 2 sightings) — never the
        fixed-stride projection — so per-game stride is absorbed by
        observation and ordinary movement is never mis-read as a
        transport. The learner's own protected validation (plain-floor
        exclusion + determinism demotion) handles the rest.
        """
        targets = self._actor_action_targets.get((pre_pos, action_name), Counter())
        if not targets:
            return
        predicted, count = targets.most_common(1)[0]
        if int(count) < 2 or predicted == pre_pos:
            return
        signature = _transport_patch_signature(pre_frame, predicted)
        if signature is None:
            return
        self._transport_effect_learner.observe_transition(
            prev_actors=[pre_pos],
            observed_actors=[post_pos],
            predicted_targets=[predicted],
            prev_signatures={predicted: signature},
            progress_score=int(self._loop_running_positive_delta),
        )

    def transport_effect_summary(self) -> dict[str, Any]:
        """Diagnostics for the Phase M transport-repair loop (P8)."""
        summary = dict(self._transport_effect_learner.summary())
        summary["enabled"] = bool(self._transport_effect_repair_enabled)
        return summary

    def _update_click_memory(self, record, pre_frame: np.ndarray) -> None:
        if record.action_name != "ACTION6":
            return
        pre_pos = self._actor_position(pre_frame)
        if pre_pos is not None:
            self._blocked_click_counts[pre_pos] += 1
        payload = dict(record.action_payload or {})
        try:
            point = (int(payload.get("x")), int(payload.get("y")))
        except (TypeError, ValueError):
            point = None
        if point is not None:
            self._recent_click_points.append(point)
            self._epoch_click_points[point] += 1
            self._epoch_click_contexts[(point, pre_pos)] += 1
        if point is not None and self._click_effect_significant(record):
            if point in self._effective_click_points:
                self._effective_click_points.remove(point)
            self._effective_click_points.insert(0, point)
            self._effective_click_points = self._effective_click_points[:8]
            self._click_topology_events.append(
                {
                    "epoch_id": self._epoch_id,
                    "click_point": list(point),
                    "actor_pos": list(pre_pos) if pre_pos is not None else None,
                    "changed_pixel_count": int(record.changed_pixel_count),
                    "changed_bbox": record.changed_bbox.to_dict() if record.changed_bbox else None,
                    "frame_shape": list(record.frame_shape[:2]),
                    "actor_edge_count_before_reset": len(self._actor_action_targets),
                    "local_patch_hash": _local_patch_hash(pre_frame, pre_pos),
                }
            )
            self._click_topology_events = self._click_topology_events[-64:]
        if pre_pos is not None and record.changed_pixel_count > 0:
            self._reset_actor_topology_memory(preserve_blocked_clicks=True)

    def _click_effect_significant(self, record: ActionEffectRecord) -> bool:
        if record.score_delta != 0:
            return True
        if record.changed_pixel_count <= 0 or record.changed_bbox is None:
            return False
        bbox = record.changed_bbox
        height = int(record.frame_shape[0]) if record.frame_shape else 0
        width = int(record.frame_shape[1]) if len(record.frame_shape) >= 2 else height
        touches_border = (
            int(bbox.min_y) <= 0
            or int(bbox.min_x) <= 0
            or int(bbox.max_y) >= max(0, height - 1)
            or int(bbox.max_x) >= max(0, width - 1)
        )
        if touches_border and int(record.changed_pixel_count) <= 4:
            return False
        if touches_border and (int(bbox.width) <= 2 or int(bbox.height) <= 2):
            return False
        return True

    def _infer_actor_value(self, pre_frame: np.ndarray, post_frame: np.ndarray) -> int | None:
        if pre_frame.shape != post_frame.shape:
            return None
        mask = pre_frame != post_frame
        if mask.ndim >= 3:
            mask = np.any(mask, axis=tuple(range(2, mask.ndim)))
        if int(np.count_nonzero(mask)) <= 0 or int(np.count_nonzero(mask)) > 64:
            return None
        pre_values = set(int(value) for value in np.unique(pre_frame[mask]).tolist())
        post_values = set(int(value) for value in np.unique(post_frame[mask]).tolist())
        candidates = sorted(pre_values & post_values)
        best: tuple[int, int] | None = None
        for value in candidates:
            pre_count = int(np.count_nonzero(pre_frame == value))
            post_count = int(np.count_nonzero(post_frame == value))
            if pre_count <= 0 or pre_count != post_count or pre_count > 16:
                continue
            score = pre_count
            if best is None or score < best[0]:
                best = (score, value)
        return best[1] if best else None

    def _actor_position(self, frame: np.ndarray) -> tuple[int, int] | None:
        value = self.actor_value
        if value is None:
            return None
        ys, xs = np.where(frame == value)
        if len(xs) <= 0 or len(xs) > 32:
            return None
        return int(round(float(np.mean(xs)))), int(round(float(np.mean(ys))))

    def _record_passable_values(
        self,
        pre_frame: np.ndarray,
        post_frame: np.ndarray,
        pre_pos: tuple[int, int],
        post_pos: tuple[int, int],
    ) -> None:
        actor_value = self.actor_value
        for frame, pos in ((pre_frame, post_pos), (post_frame, pre_pos)):
            value = _dominant_patch_value(frame, pos, radius=0, exclude_value=actor_value)
            if value is not None:
                self._passable_value_votes[int(value)] += 1
        if self._passable_carryover_enabled or self._stride_lattice_plan_enabled:
            self._record_swept_passable_values(pre_frame, pre_pos, post_pos)

    def _record_swept_passable_values(
        self,
        frame: np.ndarray,
        pre_pos: tuple[int, int],
        post_pos: tuple[int, int],
    ) -> None:
        dx = int(post_pos[0]) - int(pre_pos[0])
        dy = int(post_pos[1]) - int(pre_pos[1])
        if dx != 0 and dy != 0:
            return
        distance = abs(dx) + abs(dy)
        if distance <= 1 or distance > RESET_JUMP_DISTANCE:
            return
        step_x = 0 if dx == 0 else (1 if dx > 0 else -1)
        step_y = 0 if dy == 0 else (1 if dy > 0 else -1)
        actor_value = self.actor_value
        for offset in range(1, distance):
            pos = (int(pre_pos[0]) + step_x * offset, int(pre_pos[1]) + step_y * offset)
            value = _dominant_patch_value(frame, pos, radius=0, exclude_value=actor_value)
            if value is not None:
                self._passable_value_votes[int(value)] += 1

    def _record_passable_contradiction(
        self,
        frame: np.ndarray,
        actor_pos: tuple[int, int],
        action_name: str,
    ) -> None:
        if not self._passable_value_prior:
            return
        projected = self._project_actor_stride_step(actor_pos, action_name)
        value = _dominant_patch_value(frame, projected, radius=0, exclude_value=self.actor_value)
        if value is None:
            return
        value_int = int(value)
        if value_int not in self._passable_value_prior:
            return
        self._passable_contradiction_cells[value_int].add((int(projected[0]), int(projected[1])))
        if len(self._passable_contradiction_cells[value_int]) >= 2:
            self._passable_demoted.add(value_int)

    def _passable_values(self) -> list[int]:
        values: list[int] = []
        for value, count in self._passable_value_votes.most_common(6):
            if count <= 0:
                continue
            values.append(int(value))
        if self._passable_carryover_enabled:
            seen = set(values)
            for value, count in self._passable_value_prior.most_common(6):
                value_int = int(value)
                if int(count) <= 0 or value_int in self._passable_demoted or value_int in seen:
                    continue
                values.append(value_int)
                seen.add(value_int)
        return values

    def _actor_frontier_actions(self, actor_pos: tuple[int, int], available: set[str]) -> list[str]:
        attempts = self._actor_action_attempts.get(actor_pos, Counter())
        return [action for action in GOAL_BIASED_DIRECTIONAL_ACTIONS if action in available and attempts[action] <= 0]

    def _score_bearing_actions(self, available: set[str]) -> list[str]:
        actions: list[str] = []
        for item in reversed(self._score_preconditions):
            normalized = _normalize_action_name(item.get("action_name"))
            if normalized in available and normalized not in actions:
                actions.append(normalized)
        return actions

    def _win_hypothesis_directed_action(
        self,
        actor_pos: tuple[int, int],
        available: set[str],
        frame,
    ) -> str | None:
        """D-1 stage 3: when an active win hypothesis exists, walk its
        subject toward its object (the highest-bonus, non-blocked
        directional action). This sits where the fixed position
        heuristic (_goal_biased_actor_action) used to decide — the
        branch measured to own the actor path in score-less episodes."""
        if not self._win_relation_bias_enabled or frame is None:
            return None
        # Same last-resort gate as the early-return lane: stay dormant
        # until the level is stuck so the generic base keeps first refusal.
        if not self._win_hypothesis_exploration_stuck():
            return None
        return self._win_hypothesis_route_action(actor_pos, available, frame)

    def _win_hypothesis_route_action(
        self,
        actor_pos: tuple[int, int],
        available: set[str],
        frame,
    ) -> str | None:
        """Drive the actor toward the active win hypothesis's OBJECT cell.

        A greedy centroid gradient walks straight into walls on obstacle
        games (measured: tu93 maze / dc22 toggle board never scored under
        the directed walk). The win hypothesis supplies a concrete goal
        cell (object centroid); the existing frame-only navigators then
        route AROUND obstacles using learned walkability — both are
        holdout-safe (no offline simulator, no game ids):
          1. _visual_route_to_target: BFS over learned passable cells.
          2. _actor_graph_route_to_target_frontier: BFS over the learned
             actor transition graph.
        Falls back to the greedy direction bonus when neither route is
        available yet (e.g. walkability not learned during the probe)."""
        if frame is None:
            return None
        goal = self._win_relation_tracker.active_object_centroid(frame)
        # Revisit pressure: when the actor keeps returning to the same
        # node, the graph/visual routes are cycling (measured tu93 trace:
        # a 6-node orbit around (34..46, 16..34) that _actor_stagnating's
        # tight 2-3-distinct window cannot see). Routes lose precedence
        # to the committed wall-follow until fresh ground is reached.
        looping = int(self._actor_visit_counts.get(actor_pos, 0)) >= 4
        if looping:
            # Goal-greedy frontier ordering starves in mazes whose true
            # path first leads AWAY from the goal, and the POSITION-keyed
            # frontier never exhausts under facing-dot aliasing (measured
            # tu93: identical steady state at 240 and 400 actions). Once
            # looping, explore on the BUCKET graph: route to the nearest
            # bucket-node with an untried action.
            routed = self._lane_bucket_frontier_action(actor_pos, available)
            if routed is not None:
                return routed
        if goal is not None and not looping:
            # Learned-transition route FIRST: it is stride-correct (routes
            # over the actor's actually-observed moves), so it handles
            # multi-cell strides the unit-step visual BFS overshoots
            # (measured tu93: the 6-cell stride made the visual route
            # oscillate short of the exit).
            routed = self._actor_graph_route_to_target_frontier(
                actor_pos, goal, available
            )
            if routed is not None:
                return routed
            routed = self._visual_route_to_target(actor_pos, goal, frame, available)
            if routed is not None:
                return routed
        best: tuple[float, str] | None = None
        for action in ("ACTION1", "ACTION2", "ACTION3", "ACTION4"):
            if action not in available:
                continue
            if self._actor_action_blocked(actor_pos, action):
                continue
            bonus = self._win_relation_tracker.direction_bonus(frame, action)
            if bonus <= 0.0:
                continue
            if best is None or bonus > best[0]:
                best = (bonus, action)
        if best is not None:
            # Goal-ward is open again: release the wall.
            self._wall_follow_commit = None
            return best[1]
        return self._wall_follow_action(actor_pos, available, frame)

    def _lane_bucket_frontier_action(
        self,
        actor_pos: tuple[int, int],
        available: set[str],
    ) -> str | None:
        """E-1 S4: systematic exploration on the bucket-quantized lane
        graph. BFS from the actor's bucket over observed bucket edges to
        the nearest bucket holding an UNTRIED action; returns the first
        step of that route (or the untried action itself at the current
        bucket). Exhausts in O(buckets x actions) tries because aliasing
        is collapsed — the property the position-keyed frontier lacks."""
        start = (actor_pos[0] // LANE_NODE_BUCKET, actor_pos[1] // LANE_NODE_BUCKET)

        def untried(bucket: tuple[int, int]) -> str | None:
            for action in GOAL_BIASED_DIRECTIONAL_ACTIONS:
                if action not in available:
                    continue
                if self._lane_node_attempts[(bucket, action)] <= 0:
                    return action
            return None

        direct = untried(start)
        if direct is not None:
            return direct
        visited = {start}
        queue: deque[tuple[tuple[int, int], str | None]] = deque([(start, None)])
        while queue:
            bucket, first_action = queue.popleft()
            for action in GOAL_BIASED_DIRECTIONAL_ACTIONS:
                if action not in available:
                    continue
                nxt = self._lane_node_edges.get((bucket, action))
                if nxt is None or nxt in visited:
                    continue
                step = first_action or action
                if untried(nxt) is not None:
                    return step
                visited.add(nxt)
                queue.append((nxt, step))
        return None

    def _wall_follow_action(
        self,
        actor_pos: tuple[int, int],
        available: set[str],
        frame,
    ) -> str | None:
        """E-1 S4: wall-follow fallback when every goal-ward direction is
        blocked. Measured tu93 failure mode (D-1 §10.7): the directed
        walk pressed the eastern barrier to dist 11 and stalled, because
        with the goal due-east the perpendicular bonuses are ~0 and the
        greedy loop returns None — the walker never slides along the wall
        to find the crossing row. Classic maze remedy, frame-only and
        game-agnostic: when blocked toward the goal, step PERPENDICULAR
        to the dominant goal direction, preferring the least-visited
        side (visit counts prevent ping-pong; over time both wall ends
        get probed and a winding corridor's gap is found)."""
        goal = self._win_relation_tracker.active_object_centroid(frame)
        if goal is None:
            self._wall_follow_commit = None
            return None
        # Committed slide first: keep the hand on the wall until the
        # slide itself is blocked (re-deciding per step oscillates in
        # L-shaped corridors — measured tu93 ping-pong).
        commit = self._wall_follow_commit
        if (
            commit is not None
            and commit in available
            and not self._actor_action_blocked(actor_pos, commit)
        ):
            return commit
        vx = goal[0] - actor_pos[0]
        vy = goal[1] - actor_pos[1]
        if abs(vx) >= abs(vy):
            perpendicular = ("ACTION1", "ACTION2")   # blocked east/west: slide N/S
        else:
            perpendicular = ("ACTION3", "ACTION4")   # blocked north/south: slide W/E
        candidates: list[tuple[int, int, str]] = []
        for action in perpendicular:
            if action not in available:
                continue
            if self._actor_action_blocked(actor_pos, action):
                continue
            targets = self._actor_action_targets.get((actor_pos, action), Counter())
            if targets:
                projected = targets.most_common(1)[0][0]
            else:
                projected = _project_actor_step(actor_pos, action)
            visits = int(self._actor_visit_counts.get(projected, 0))
            candidates.append((visits, self._issued_counts[action], action))
        if not candidates:
            self._wall_follow_commit = None
            return None
        candidates.sort()
        self._wall_follow_commit = candidates[0][2]
        return candidates[0][2]

    def _win_bias_tiebreak(self, actions: list[str], frame) -> str:
        """D-1 stage 3 injection: among equally-exploratory candidates
        (a frontier set), prefer the action moving the active win
        hypothesis's subject toward its object; fall back to the
        least-issued heuristic when the bias is off / silent."""
        if (
            self._win_relation_bias_enabled
            and frame is not None
            and len(actions) > 1
        ):
            scored = [
                (
                    -self._win_relation_tracker.direction_bonus(frame, action),
                    self._issued_counts[action],
                    action,
                )
                for action in actions
            ]
            scored.sort()
            if scored[0][0] < 0:  # at least one action has a positive bonus
                return scored[0][2]
        return _least_issued(actions, self._issued_counts)

    def _goal_biased_actor_action(self, actor_pos: tuple[int, int], available: set[str]) -> str | None:
        # D-1 branch-2 wiring (measured 2026-06-11): this fixed-position
        # heuristic is the routing function of dc22's SCORING primitive
        # (click_opened_region_navigation), and the instrumented run
        # showed direction_bonus was consulted ZERO times on that path —
        # the prior's correct goal (reach 14->11) never reached the
        # ranking. With an active hypothesis, prefer the goal-ward
        # direction (within-primitive reorder, non-preempting — the lane
        # preemption that regressed dc22 is a different mechanism and
        # stays stuck-gated). Falls back to the fixed heuristic.
        if self._win_relation_bias_enabled:
            for action in self._win_relation_tracker.goal_ward_actions():
                if action in available and not self._actor_action_blocked(actor_pos, action):
                    return action
        if actor_pos[1] <= int(float(self._last_frame_height) * 0.32):
            preferred = ("ACTION4", "ACTION1")
        else:
            preferred = ("ACTION1", "ACTION4")
        for action in preferred:
            if action in available and not self._actor_action_blocked(actor_pos, action):
                return action
        return None

    def _score_precondition_biased_action(self, actor_pos: tuple[int, int], available: set[str]) -> str | None:
        desired = self._score_precondition_desired_action(actor_pos, available)
        if desired is not None:
            return desired if not self._actor_action_blocked(actor_pos, desired) else None
        scored = [item for item in self._score_preconditions if item.get("actor_pos")]
        for item in reversed(scored):
            action_name = str(item.get("action_name") or "")
            normalized = _normalize_action_name(action_name)
            if normalized in available and not self._actor_action_blocked(actor_pos, normalized):
                return normalized
        return None

    def _score_precondition_desired_action(self, actor_pos: tuple[int, int], available: set[str]) -> str | None:
        scored = [
            item
            for item in self._score_preconditions
            if item.get("actor_pos") and int(item.get("epoch_id", self._epoch_id)) == self._epoch_id
        ]
        if not scored:
            return None
        xs = [int(item["actor_pos"][0]) for item in scored]
        ys = [int(item["actor_pos"][1]) for item in scored]
        target_x = int(round(float(sum(xs)) / float(len(xs))))
        target_y = int(round(float(sum(ys)) / float(len(ys))))
        x, y = actor_pos
        if y > target_y:
            return "ACTION1" if "ACTION1" in available else None
        elif y < target_y:
            return "ACTION2" if "ACTION2" in available else None
        if x < target_x:
            return "ACTION4" if "ACTION4" in available else None
        elif x > target_x:
            return "ACTION3" if "ACTION3" in available else None
        return None

    def _actor_action_blocked(self, actor_pos: tuple[int, int], action: str) -> bool:
        # E-1 S4: reset-hazard bans (bias-ON arm only — the Counter stays
        # empty on the OFF arm by construction, so this is a no-op there).
        if self._reset_action_bans.get((actor_pos, action), 0) > 0:
            return True
        attempts = self._actor_action_attempts.get(actor_pos, Counter())
        if attempts[action] <= 0:
            return False
        targets = self._actor_action_targets.get((actor_pos, action), Counter())
        if not targets:
            return False
        target, _count = targets.most_common(1)[0]
        return target == actor_pos

    def _actor_graph_explore_action(self, actor_pos: tuple[int, int], available: set[str]) -> str | None:
        scored: list[tuple[int, int, int, str]] = []
        for action in GOAL_BIASED_DIRECTIONAL_ACTIONS:
            if action not in available:
                continue
            targets = self._actor_action_targets.get((actor_pos, action), Counter())
            if not targets:
                continue
            target, _count = targets.most_common(1)[0]
            visits = self._actor_visit_counts[target]
            attempts = self._actor_action_attempts.get(actor_pos, Counter())[action]
            scored.append((visits, attempts, self._issued_counts[action], action))
        if not scored:
            return None
        scored.sort(key=lambda item: (item[0], item[1], item[2], item[3]))
        return scored[0][3]

    def _actor_stagnation_escape_action(self, actor_pos: tuple[int, int], available: set[str]) -> str | None:
        frontier = self._actor_frontier_actions(actor_pos, available)
        if frontier:
            return _least_issued(frontier, self._issued_counts)
        recent_positions = set(self._recent_actor_positions)
        scored: list[tuple[int, int, int, str]] = []
        for action in GOAL_BIASED_DIRECTIONAL_ACTIONS:
            if action not in available or self._actor_action_blocked(actor_pos, action):
                continue
            targets = self._actor_action_targets.get((actor_pos, action), Counter())
            target, _count = targets.most_common(1)[0] if targets else (_project_actor_step(actor_pos, action), 0)
            returns_to_recent = int(target in recent_positions)
            attempts = self._actor_action_attempts.get(actor_pos, Counter())[action]
            scored.append((returns_to_recent, attempts, self._issued_counts[action], action))
        if not scored:
            return None
        scored.sort()
        return scored[0][3]

    def _mirror_joint_cursor_action(self, frame: np.ndarray, available: set[str]) -> str | None:
        state = _mirror_joint_cursor_state(frame)
        if state is None:
            return None
        cur_a = state["cursor_a"]
        cur_b = state["cursor_b"]
        walkable = state["walkable"]
        signatures: dict[tuple[int, int], tuple] = state.get("cell_signatures") or {}

        # Phase L-2 dynamic confirmation: verify the mirror solver's OWN
        # prediction. When the action the solver planned last step was
        # actually issued AND both cursors landed exactly on the
        # mirror_x-predicted cells (a real predicted MOVE, not a no-op),
        # that is direct evidence the mirror_x forward model governs this
        # game. cn04's coincidentally-symmetric pairs fail this: their
        # sprites move by bounce-traversal, independent of the issued
        # action, so the solver's prediction does not come true.
        if self._mirror_last_move is not None:
            pa, pb, pact, ppa, ppb = self._mirror_last_move
            if (
                self._mirror_last_issued_action == pact
                and (ppa != pa or ppb != pb)
                and cur_a == ppa
                and cur_b == ppb
            ):
                self._mirror_dynamic_confirms += 1

        # Phase M-9 (2026-06-01, ported from merge-phase246): learn observed
        # no-ops. If the previous decision predicted the cursors would MOVE
        # but they did NOT, the perceived-walkable move was actually blocked
        # by the game (a phantom-walkable wall). Record (a, b, action) so the
        # BFS prunes it and re-plans instead of looping on the dead move.
        if self._mirror_last_move is not None:
            pa, pb, pact, ppa, ppb = self._mirror_last_move
            predicted_move = (ppa != pa or ppb != pb)
            no_movement = (cur_a == pa and cur_b == pb)
            if predicted_move and no_movement:
                self._mirror_blocked_moves.add((pa, pb, pact))

        repair_on = str(
            os.environ.get("ECA_ENABLE_MODEL_REPAIR", "") or ""
        ).strip().lower() in {"1", "true", "yes", "on"}

        # ---- Phase L self-repairing loop (ported from merge-phase246),
        # delegated to the generic TileEffectLearner. The mirror solver
        # supplies its forward model (mirror_x prediction) and perception;
        # the learner does the generic hazard-discovery + protected
        # validation. ----
        learner = self._tile_effect_learner
        if repair_on:
            # Protected-validation evidence: walkable tiles are stand-on-
            # able classes (generic perception, not the 50/50 rule).
            learner.observe_safe(walkable, signatures)
            # Prediction error -> structural hypothesis.
            if self._mirror_last_prediction is not None:
                prev_a, prev_b, tgt_a, tgt_b, prev_sigs = self._mirror_last_prediction
                learner.observe_transition(
                    prev_actors=[prev_a, prev_b],
                    observed_actors=[cur_a, cur_b],
                    predicted_targets=[tgt_a, tgt_b],
                    prev_signatures=prev_sigs,
                    progress_score=int(self._loop_running_positive_delta),
                )

        # MODEL REPAIR -> PLANNER. The perception-derived hazards stay (the
        # mainline default behaviour, bit-preserving canonical results); the
        # learner's confirmed hazard classes are ADDED when repair is on.
        hazard_cells: set[tuple[int, int]] = set(state.get("hazards") or ())
        if repair_on:
            hazard_cells |= learner.hazard_cells(
                signatures, exclude=(cur_a, cur_b),
            )

        action = _mirror_joint_cursor_bfs_action(
            cur_a,
            cur_b,
            walkable,
            available,
            hazards=frozenset(hazard_cells),
            blocked=self._mirror_blocked_moves or None,
        )

        # Phase M-9: record this decision's (a, b, action, predicted_a,
        # predicted_b) so the next step can detect an observed no-op and
        # learn the phantom-walkable block.
        if action is not None:
            _dirs = {"ACTION1": (0, -1), "ACTION2": (0, 1), "ACTION3": (-1, 0), "ACTION4": (1, 0)}
            _dxdy = _dirs.get(_normalize_action_name(action))
            if _dxdy is not None:
                _dx, _dy = _dxdy
                _ta = (cur_a[0] + _dx, cur_a[1] + _dy) if (cur_a[0] + _dx, cur_a[1] + _dy) in walkable else cur_a
                _tb = (cur_b[0] - _dx, cur_b[1] + _dy) if (cur_b[0] - _dx, cur_b[1] + _dy) in walkable else cur_b
                self._mirror_last_move = (cur_a, cur_b, _normalize_action_name(action), _ta, _tb)
        else:
            self._mirror_last_move = None

        # Record this decision's move targets + signature snapshot for
        # the next step's prediction-error attribution.
        if repair_on and action is not None:
            dirs = {"ACTION1": (0, -1), "ACTION2": (0, 1), "ACTION3": (-1, 0), "ACTION4": (1, 0)}
            dxdy = dirs.get(_normalize_action_name(action))
            if dxdy is not None:
                dx, dy = dxdy
                ta = (cur_a[0] + dx, cur_a[1] + dy)
                tb = (cur_b[0] - dx, cur_b[1] + dy)  # mirror_x
                self._mirror_last_prediction = (
                    cur_a, cur_b, ta, tb, dict(signatures),
                )
        return action

    def _mirror_selectable_blocker_reposition_step(
        self,
        frame: np.ndarray,
        available: set[str],
    ) -> tuple[str, dict[str, Any] | None] | None:
        diag: dict[str, Any] = {
            "schema_version": "eca_mirror_selectable_blocker_reposition.v1",
            "enabled": bool(self._mirror_selectable_blocker_reposition_enabled),
            "default_off": True,
            "applied": False,
            "blocked_reason": "",
            "active_queue_len_before": int(
                len(self._active_mirror_selectable_blocker_plan)
            ),
        }
        if not self._mirror_selectable_blocker_reposition_enabled:
            diag["blocked_reason"] = "disabled"
            self._last_mirror_selectable_blocker_reposition = diag
            return None
        if not self._primitive_enabled("mirror_selectable_blocker_reposition"):
            diag["blocked_reason"] = "primitive_disabled"
            self._last_mirror_selectable_blocker_reposition = diag
            return None
        if self._active_mirror_selectable_blocker_plan:
            step = self._active_mirror_selectable_blocker_plan.popleft()
            diag.update(
                {
                    "applied": True,
                    "source": "active_plan",
                    "selected_action": step[0],
                    "remaining_after": int(
                        len(self._active_mirror_selectable_blocker_plan)
                    ),
                }
            )
            self._last_mirror_selectable_blocker_reposition = diag
            return step
        if "ACTION6" not in available:
            diag["blocked_reason"] = "action6_unavailable"
            self._last_mirror_selectable_blocker_reposition = diag
            return None
        if not any(action in available for action in DIRECTIONAL_ACTIONS):
            diag["blocked_reason"] = "directional_actions_unavailable"
            self._last_mirror_selectable_blocker_reposition = diag
            return None
        state = _mirror_joint_cursor_state(frame)
        if state is None:
            diag["blocked_reason"] = "no_mirror_joint_state"
            self._last_mirror_selectable_blocker_reposition = diag
            return None
        existing_action = _mirror_joint_cursor_bfs_action(
            state["cursor_a"],
            state["cursor_b"],
            state["walkable"],
            available,
            hazards=frozenset(state.get("hazards") or ()),
            blocked=self._mirror_blocked_moves or None,
        )
        if existing_action is not None:
            diag["blocked_reason"] = "mirror_bfs_already_has_action"
            self._last_mirror_selectable_blocker_reposition = diag
            return None
        plan, plan_diag = _mirror_selectable_blocker_reposition_plan(
            state,
            available,
            max_expansions=_eca_env_int(
                "ECA_MIRROR_SELECTABLE_BLOCKER_REPOSITION_MAX_EXPANSIONS",
                20000,
                minimum=128,
                maximum=200000,
            ),
        )
        diag.update(plan_diag)
        if not plan:
            diag.setdefault("blocked_reason", "no_reposition_plan")
            self._last_mirror_selectable_blocker_reposition = diag
            return None
        self._active_mirror_selectable_blocker_plan.extend(plan)
        step = self._active_mirror_selectable_blocker_plan.popleft()
        diag.update(
            {
                "applied": True,
                "source": "new_plan",
                "selected_action": step[0],
                "remaining_after": int(
                    len(self._active_mirror_selectable_blocker_plan)
                ),
            }
        )
        self._last_mirror_selectable_blocker_reposition = diag
        return step

