    def _sprite_anchor_overlap_step(
        self,
        frame: np.ndarray,
        available: set[str],
        *,
        state: dict[str, Any] | None = None,
    ) -> tuple[str, dict[str, Any] | None] | None:
        primitive_id = "sprite_anchor_overlap_solver"
        if (
            not self._enable_sprite_anchor_overlap_solver
            or not self._primitive_enabled(primitive_id)
        ):
            self._active_sprite_anchor_overlap_plan.clear()
            self._last_sprite_anchor_overlap_state = None
            return None
        if not self._active_sprite_anchor_overlap_plan:
            if state is None:
                state = _sprite_anchor_overlap_state(np.array(frame, copy=True))
            if state is None:
                state = _sprite_anchor_cycle_group_hidden_state(np.array(frame, copy=True))
            if state is None:
                hidden_step = self._sprite_anchor_hidden_probe_step(frame, available)
                if hidden_step is not None:
                    return hidden_step
                self._last_sprite_anchor_overlap_state = None
                return None
            plan = _sprite_anchor_overlap_plan(state, available)
            if not plan:
                self._last_sprite_anchor_overlap_state = state
                return None
            self._active_sprite_anchor_overlap_plan.clear()
            self._active_sprite_anchor_overlap_plan.extend(plan)
            self._last_sprite_anchor_overlap_state = {
                **state,
                "operation_plan_len": int(len(plan)),
            }
        if not self._active_sprite_anchor_overlap_plan:
            return None
        action_name, payload = self._active_sprite_anchor_overlap_plan.popleft()
        if action_name not in available:
            self._active_sprite_anchor_overlap_plan.clear()
            return None
        return action_name, payload

    def _sprite_anchor_hidden_probe_step(
        self,
        frame: np.ndarray,
        available: set[str],
    ) -> tuple[str, dict[str, Any] | None] | None:
        if "ACTION6" not in available:
            return None
        components = _sprite_anchor_hidden_probe_components(frame)
        if (
            len(components) < 3
            or len(components) > 5
            or (
                not self._sprite_anchor_hidden_probe_records
                and not _sprite_anchor_hidden_probe_admissible(frame)
            )
        ):
            self._sprite_anchor_hidden_probe_records.clear()
            self._sprite_anchor_hidden_probe_current_key = None
            return None
        visible_keys = {tuple(component["key"]) for component in components}
        for key in list(self._sprite_anchor_hidden_probe_records):
            if key not in visible_keys:
                self._sprite_anchor_hidden_probe_records.pop(key, None)
        for component in components:
            key = tuple(component["key"])
            if int(component.get("anchor_count", 0) or 0) >= 2:
                record_key = (
                    self._sprite_anchor_hidden_probe_current_key
                    if self._sprite_anchor_hidden_probe_current_key is not None
                    else key
                )
                record = dict(component)
                record["key"] = tuple(record_key)
                self._sprite_anchor_hidden_probe_records[tuple(record_key)] = record
                self._sprite_anchor_hidden_probe_current_key = tuple(record_key)
        if len(self._sprite_anchor_hidden_probe_records) >= len(components):
            state = _sprite_anchor_hidden_overlap_state(
                list(self._sprite_anchor_hidden_probe_records.values()),
                current_key=self._sprite_anchor_hidden_probe_current_key,
                grid_w=max(int(component["pos"][0]) + int(component["width"]) for component in components),
                grid_h=max(int(component["pos"][1]) + int(component["height"]) for component in components),
            )
            plan = _sprite_anchor_overlap_plan(state, available)
            if plan:
                self._active_sprite_anchor_overlap_plan.clear()
                self._active_sprite_anchor_overlap_plan.extend(plan)
                self._last_sprite_anchor_overlap_state = {
                    **(state or {}),
                    "operation_plan_len": int(len(plan)),
                }
                action_name, payload = self._active_sprite_anchor_overlap_plan.popleft()
                return action_name, payload
        recorded = set(self._sprite_anchor_hidden_probe_records)
        for component in sorted(
            components,
            key=lambda item: (
                tuple(item["key"]) in recorded,
                int(item.get("area", 0) or 0),
                tuple(item.get("pos") or (0, 0)),
            ),
        ):
            key = tuple(component["key"])
            if key in recorded:
                continue
            self._sprite_anchor_hidden_probe_current_key = key
            self._last_sprite_anchor_overlap_state = {
                "mechanic_state_type": "sprite_anchor_hidden_probe",
                "goal_link_type": "hidden_same_color_anchor_overlap_probe",
                "component_count": int(len(components)),
                "recorded_component_count": int(len(recorded)),
                "reader_confidence": 0.56,
                "goal_link_confidence": 0.5,
            }
            return "ACTION6", dict(component["click_payload"])
        return None

    def _stride_marker_maze_action(
        self,
        frame: np.ndarray,
        available: set[str],
        *,
        actor_hint: tuple[int, int] | None = None,
    ) -> str | None:
        state = _stride_marker_maze_state(
            frame,
            actor_hint=actor_hint,
            enumerate_actors=self._stride_marker_maze_multi_actor_enumeration_enabled(),
        )
        if state is None:
            return None
        if actor_hint is None and int(state.get("marker_count", 0) or 0) == 1:
            self._actor_value_votes[int(state["actor_value"])] += 1
        return _stride_marker_maze_bfs_action(
            state["actor_pos"],
            state["targets"],
            state["walkable"],
            available,
            stride=state["stride"],
            edge_offset=state["edge_offset"],
            forbidden=state.get("forbidden", frozenset()),
        )

    def _stride_marker_absorber_action(
        self,
        frame: np.ndarray,
        available: set[str],
        *,
        actor_value: int | None,
    ) -> str | None:
        self._last_stride_marker_absorber_state = {
            "enabled": bool(self._enable_stride_marker_absorber_bfs),
            "admitted": False,
        }
        if not self._enable_stride_marker_absorber_bfs:
            self._last_stride_marker_absorber_state["reason"] = "disabled"
            return None
        if not self._primitive_enabled("generic_stride_marker_absorber_bfs"):
            self._last_stride_marker_absorber_state["reason"] = "primitive_disabled"
            return None
        if self._active_stride_marker_absorber_plan:
            action = str(self._active_stride_marker_absorber_plan[0])
            context = dict(self._active_stride_marker_absorber_context)
            context["enabled"] = True
            context["admitted"] = True
            context["from_active_queue"] = True
            context["next_action"] = action
            context["remaining_after"] = max(
                0,
                int(len(self._active_stride_marker_absorber_plan)) - 1,
            )
            self._last_stride_marker_absorber_state = context
            if action in available:
                return action
            self._active_stride_marker_absorber_plan.clear()
            self._active_stride_marker_absorber_context.clear()
            self._last_stride_marker_absorber_state["reason"] = "queued_action_unavailable"
            return None
        state = _stride_marker_absorber_plan(
            frame,
            available,
            actor_value=actor_value,
        )
        if state is None:
            self._last_stride_marker_absorber_state["reason"] = "no_absorber_plan"
            return None
        self._last_stride_marker_absorber_state = _compact_stride_marker_absorber_state(
            state
        )
        plan = [str(action) for action in state.get("plan", [])]
        if not plan:
            self._last_stride_marker_absorber_state["reason"] = "empty_plan"
            return None
        self._active_stride_marker_absorber_plan.clear()
        self._active_stride_marker_absorber_plan.extend(plan)
        self._active_stride_marker_absorber_context = dict(
            self._last_stride_marker_absorber_state
        )
        action = str(self._active_stride_marker_absorber_plan[0])
        if action not in available:
            self._active_stride_marker_absorber_plan.clear()
            self._active_stride_marker_absorber_context.clear()
            self._last_stride_marker_absorber_state["reason"] = "action_unavailable"
            return None
        self._last_stride_marker_absorber_state["admitted"] = True
        self._last_stride_marker_absorber_state["remaining_after"] = max(
            0,
            int(len(self._active_stride_marker_absorber_plan)) - 1,
        )
        return action

