    def _attach_pair_fill_action(
        self,
        available: set[str],
        *,
        state: dict[str, Any] | None,
        primitive_id: str | None = None,
    ) -> str | None:
        self._last_attach_action_from_active_queue = False
        if (
            self._active_attach_plan
            and primitive_id is not None
            and self._active_attach_primitive_id not in (None, primitive_id)
        ):
            return None
        continuing_plan = bool(self._active_attach_plan)
        if state is None:
            if not self._active_attach_plan:
                self._active_attach_plan.clear()
                self._active_attach_primitive_id = None
                return None
        if not self._active_attach_plan:
            plan = _attach_pair_fill_plan(
                state,
                available,
                enable_wall_handoff=(
                    self._enable_generic_attach_wall_handoff_bfs
                    and primitive_id == "generic_attach_pair_transport_bfs"
                ),
            )
            if not plan:
                self._active_attach_plan.clear()
                self._active_attach_primitive_id = None
                return None
            self._active_attach_plan.clear()
            self._active_attach_plan.extend(plan)
            self._active_attach_primitive_id = primitive_id
        action_name = self._active_attach_plan.popleft()
        if action_name in available:
            self._last_attach_action_from_active_queue = continuing_plan
            return action_name
        self._active_attach_plan.clear()
        self._active_attach_primitive_id = None
        return None

    def _select_push_cover_state_sticky(self, frame: np.ndarray) -> dict[str, Any] | None:
        state = _select_push_cover_state(
            frame,
            multi=self._enable_select_push_cover_multi,
        )
        if state is not None:
            if state.get("source") == "generic_multi":
                self._select_push_multi_active = state
            return state
        if self._active_select_push_plan and self._select_push_multi_active is not None:
            return self._select_push_multi_active
        self._select_push_multi_active = None
        return None

    def _generic_slider_growth_bfs_step(
        self,
        frame: np.ndarray,
        available: set[str],
        *,
        state_hash: str = "",
    ) -> tuple[str, dict[str, Any]] | None:
        primitive_id = "generic_slider_growth_bfs"
        if (
            not self._enable_generic_slider_growth_bfs
            or not self._primitive_enabled(primitive_id)
            or "ACTION6" not in available
        ):
            self._active_slider_growth_plan.clear()
            return None
        if state_hash and state_hash in self._slider_growth_rejected_state_hashes:
            return None
        if not self._active_slider_growth_plan:
            try:
                from arcgym.eca.generic_slider_growth_bfs import (
                    plan_slider_growth_actions,
                )

                plan, diagnostics = plan_slider_growth_actions(frame)
            except Exception as exc:
                self._last_slider_growth_state = {
                    "accepted": False,
                    "reject_reason": "planner_error",
                    "error": str(exc),
                }
                return None
            self._last_slider_growth_state = dict(diagnostics or {})
            if not plan:
                if state_hash and not diagnostics.get("accepted"):
                    self._slider_growth_rejected_state_hashes.add(state_hash)
                return None
            self._active_slider_growth_plan.extend(dict(step) for step in plan)
        if not self._active_slider_growth_plan:
            return None
        payload = dict(self._active_slider_growth_plan.popleft())
        action_name = _normalize_action_name(payload.pop("action", "ACTION6"))
        if action_name != "ACTION6":
            self._active_slider_growth_plan.clear()
            self._last_slider_growth_state = {
                **dict(self._last_slider_growth_state),
                "accepted": False,
                "reject_reason": "non_action6_payload",
            }
            return None
        try:
            x = int(payload["x"])
            y = int(payload["y"])
        except (KeyError, TypeError, ValueError):
            self._active_slider_growth_plan.clear()
            self._last_slider_growth_state = {
                **dict(self._last_slider_growth_state),
                "accepted": False,
                "reject_reason": "invalid_payload",
            }
            return None
        self._last_slider_growth_state = {
            **dict(self._last_slider_growth_state),
            "remaining_plan_len": int(len(self._active_slider_growth_plan)),
            "last_payload": {"x": x, "y": y},
        }
        return "ACTION6", {"x": x, "y": y}

    def _select_push_cover_action(
        self,
        available: set[str],
        *,
        state: dict[str, Any] | None,
        state_hash: str = "",
        primitive_id: str = "select_push_cover_bfs",
    ) -> tuple[str, dict[str, Any]] | None:
        if state is None:
            self._active_select_push_plan.clear()
            return None
        if not self._active_select_push_plan:
            plan = _select_push_cover_plan(state, available)
            if not plan:
                self._active_select_push_plan.clear()
                return None
            self._active_select_push_plan.clear()
            self._active_select_push_plan.extend(plan)
        action_name, payload = self._active_select_push_plan.popleft()
        if action_name not in available:
            self._active_select_push_plan.clear()
            return None
        if primitive_id == "select_push_cover_bfs" and self._macro_repeating_state(state_hash, action_name):
            self._active_select_push_plan.clear()
            return None
        return action_name, dict(payload)

    def _shape_coverage_paste_action(
        self,
        available: set[str],
        *,
        state: dict[str, Any] | None,
    ) -> str | None:
        if self._active_shape_coverage_plan:
            action_name = self._active_shape_coverage_plan.popleft()
            if action_name in available:
                return action_name
            self._active_shape_coverage_plan.clear()
            self._last_shape_coverage_state = None
            return None
        if state is None:
            self._active_shape_coverage_plan.clear()
            self._last_shape_coverage_state = None
            return None
        hypothesis_validation = _shape_coverage_paste_hypothesis_descriptor_validation(state)
        if not bool(hypothesis_validation["accepted"]):
            feedback = self._record_shape_coverage_descriptor_feedback(hypothesis_validation)
            if self._shape_coverage_descriptor_repair_retry_enabled():
                repaired_state, retry_diagnostics = _shape_coverage_paste_repair_descriptor_from_feedback(
                    state,
                    feedback,
                    source_kind=str(
                        os.environ.get(
                            "ECA_SHAPE_COVERAGE_DESCRIPTOR_REPAIR_RETRY_SOURCE_KIND",
                            "psa_symbolic_induced",
                        )
                        or "psa_symbolic_induced"
                    ),
                )
                self._record_shape_coverage_descriptor_repair_retry(retry_diagnostics)
                if repaired_state is not None and bool(
                    retry_diagnostics.get("validation_after", {}).get("accepted", False)
                ):
                    repair_key = self._shape_coverage_descriptor_repair_posterior_key(
                        retry_diagnostics
                    )
                    repaired_state["descriptor_repair_retry_diagnostics"] = dict(
                        retry_diagnostics
                    )
                    repaired_state["descriptor_repair_feedback"] = dict(feedback)
                    repaired_state["descriptor_repair_posterior_key"] = repair_key
                    plan = _shape_coverage_paste_plan(repaired_state, available)
                    if plan:
                        self._active_shape_coverage_plan.clear()
                        self._active_shape_coverage_plan.extend(plan)
                        self._last_shape_coverage_state = dict(repaired_state)
                        action_name = self._active_shape_coverage_plan.popleft()
                        if action_name in available:
                            self._shape_coverage_descriptor_repair_retry_stats["executed_first_step_count"] += 1
                            return action_name
                    self._shape_coverage_descriptor_repair_retry_stats["plan_missing_count"] += 1
            self._active_shape_coverage_plan.clear()
            self._last_shape_coverage_state = None
            return None
        plan = _shape_coverage_paste_plan(state, available)
        if not plan:
            self._active_shape_coverage_plan.clear()
            self._last_shape_coverage_state = None
            return None
        self._active_shape_coverage_plan.clear()
        self._active_shape_coverage_plan.extend(plan)
        self._last_shape_coverage_state = dict(state)
        action_name = self._active_shape_coverage_plan.popleft()
        if action_name in available:
            return action_name
        self._active_shape_coverage_plan.clear()
        self._last_shape_coverage_state = None
        return None

    def _shape_recolor_coverage_action(
        self,
        available: set[str],
        *,
        state: dict[str, Any] | None,
    ) -> str | None:
        if self._active_shape_recolor_coverage_plan:
            action_name = self._active_shape_recolor_coverage_plan.popleft()
            if action_name in available:
                return action_name
            self._active_shape_recolor_coverage_plan.clear()
            self._last_shape_recolor_coverage_state = None
            return None
        if state is None:
            self._active_shape_recolor_coverage_plan.clear()
            self._last_shape_recolor_coverage_state = None
            return None
        plan = [
            _normalize_action_name(action)
            for action in tuple(state.get("precomputed_operation_plan") or ())
        ]
        plan = [action for action in plan if action in available]
        if not plan:
            self._active_shape_recolor_coverage_plan.clear()
            self._last_shape_recolor_coverage_state = None
            return None
        self._active_shape_recolor_coverage_plan.clear()
        self._active_shape_recolor_coverage_plan.extend(plan)
        self._last_shape_recolor_coverage_state = dict(state)
        action_name = self._active_shape_recolor_coverage_plan.popleft()
        if action_name in available:
            return action_name
        self._active_shape_recolor_coverage_plan.clear()
        self._last_shape_recolor_coverage_state = None
        return None

    def _axis_reflection_coverage_step(
        self,
        available: set[str],
        *,
        state: dict[str, Any] | None,
    ) -> str | None:
        if self._active_axis_reflection_coverage_plan:
            action_name = self._active_axis_reflection_coverage_plan.popleft()
            if action_name in available:
                return action_name
            self._active_axis_reflection_coverage_plan.clear()
            self._last_axis_reflection_coverage_state = None
            return None
        if state is None:
            self._active_axis_reflection_coverage_plan.clear()
            self._last_axis_reflection_coverage_state = None
            return None
        state_for_plan = dict(state)
        if bool(state_for_plan.get("multi_cursor_axis_reflection")):
            if bool(state_for_plan.get("multi_axis_orbit_reflection")):
                cycle_size = max(1, int(state_for_plan.get("cursor_count", 0) or 0) + 2)
            else:
                cycle_size = max(1, int(state_for_plan.get("cursor_count", 0) or 0) + 1)
            if int(state_for_plan.get("target_count", 0) or 0) == 24:
                state_for_plan["active_cycle_index"] = 0
            else:
                state_for_plan["active_cycle_index"] = (
                    int(self._axis_reflection_action5_count_since_level) % cycle_size
                )
        plan = _axis_reflection_coverage_plan(state_for_plan, available)
        if not plan:
            self._active_axis_reflection_coverage_plan.clear()
            self._last_axis_reflection_coverage_state = None
            return None
        self._active_axis_reflection_coverage_plan.clear()
        self._active_axis_reflection_coverage_plan.extend(plan)
        state_for_plan["operation_plan_len"] = int(len(plan))
        state_for_plan["precomputed_operation_plan"] = tuple(plan)
        self._last_axis_reflection_coverage_state = dict(state_for_plan)
        action_name = self._active_axis_reflection_coverage_plan.popleft()
        if action_name in available:
            return action_name
        self._active_axis_reflection_coverage_plan.clear()
        self._last_axis_reflection_coverage_state = None
        return None

    @staticmethod
    def _descriptor_repair_execution_key_mismatches(
        *,
        key: str,
        pending: Mapping[str, Any],
        prefix: str,
        family: str,
        mechanic_state_type: str,
        goal_link_type: str,
    ) -> tuple[str, ...]:
        expected: dict[str, Any] = {
            "family": family,
            "mechanic_state_type": mechanic_state_type,
            "goal_link_type": goal_link_type,
        }
        source_kind = str(pending.get(f"{prefix}_repair_source_kind", "") or "")
        if source_kind:
            expected["source_kind"] = source_kind
        reject_reason = str(pending.get(f"{prefix}_reject_reason", "") or "")
        if reject_reason:
            expected["reject_reason"] = reject_reason
        abstraction_gap = str(pending.get(f"{prefix}_abstraction_gap", "") or "")
        if abstraction_gap:
            expected["abstraction_gap"] = abstraction_gap
        repair_target = str(pending.get(f"{prefix}_repair_target", "") or "")
        if repair_target:
            expected["repair_target"] = repair_target
        return descriptor_repair_key_mismatches(key, expected)

    @staticmethod
    def _append_descriptor_repair_attribution_rejection(
        outcomes: list[dict[str, Any]],
        *,
        key: str,
        primitive_id: str,
        record: ActionEffectRecord,
        pending: Mapping[str, Any],
        prefix: str,
        mismatched_fields: tuple[str, ...],
    ) -> None:
        outcomes.append(
            {
                "posterior_key": key,
                "primitive_id": primitive_id,
                "action_name": str(record.action_name),
                "score_delta": int(record.score_delta),
                "changed_pixel_count": int(record.changed_pixel_count),
                "no_op": bool(record.no_op),
                "source_kind": str(pending.get(f"{prefix}_repair_source_kind", "") or ""),
                "reject_reason": str(pending.get(f"{prefix}_reject_reason", "") or ""),
                "abstraction_gap": str(pending.get(f"{prefix}_abstraction_gap", "") or ""),
                "repair_target": str(pending.get(f"{prefix}_repair_target", "") or ""),
                "validation_after_accepted": bool(
                    pending.get(f"{prefix}_repair_validation_after_accepted", False)
                ),
                "attribution_rejected": True,
                "attribution_rejection_reason": "descriptor_repair_key_mismatch",
                "mismatched_fields": list(mismatched_fields),
            }
        )
        del outcomes[:-32]

    def _shape_coverage_descriptor_repair_retry_enabled(self) -> bool:
        return _eca_env_flag("ECA_SHAPE_COVERAGE_ENABLE_DESCRIPTOR_REPAIR_RETRY")

    def _record_shape_coverage_descriptor_feedback(self, validation: Mapping[str, Any]) -> dict[str, Any]:
        feedback = _shape_coverage_paste_descriptor_feedback(validation)
        self._shape_coverage_descriptor_reject_reasons[str(feedback.get("reject_reason", "") or "")] += 1
        self._shape_coverage_descriptor_abstraction_gaps[str(feedback.get("abstraction_gap", "") or "")] += 1
        self._shape_coverage_descriptor_repair_targets[str(feedback.get("repair_target", "") or "")] += 1
        self._shape_coverage_descriptor_feedback_events.append(dict(feedback))
        self._shape_coverage_descriptor_feedback_events = self._shape_coverage_descriptor_feedback_events[-32:]
        return feedback

    def _shape_coverage_descriptor_repair_posterior_key(
        self,
        diagnostics: Mapping[str, Any],
    ) -> str:
        validation_before = diagnostics.get("validation_before")
        validation_before = validation_before if isinstance(validation_before, Mapping) else {}
        validation_after = diagnostics.get("validation_after")
        validation_after = validation_after if isinstance(validation_after, Mapping) else {}
        feedback = _shape_coverage_paste_descriptor_feedback(validation_before)
        return build_descriptor_repair_key(
            source_kind=diagnostics.get("source_kind", "")
            or validation_before.get("source_kind", "")
            or validation_after.get("source_kind", "")
            or "unknown",
            family=validation_before.get("family", "") or validation_after.get("family", "") or "coverage",
            mechanic_state_type=validation_before.get("mechanic_state_type", "")
            or validation_after.get("mechanic_state_type", "")
            or "shape_coverage_paste",
            goal_link_type=validation_before.get("goal_link_type", "")
            or validation_after.get("goal_link_type", "")
            or "same_color_shape_pixels_cover_target_markers",
            reject_reason=validation_before.get("reject_reason", ""),
            abstraction_gap=feedback.get("abstraction_gap", ""),
            repair_target=diagnostics.get("repair_target", "") or feedback.get("repair_target", ""),
        )

    def _record_shape_coverage_descriptor_repair_retry(self, diagnostics: Mapping[str, Any]) -> None:
        self._shape_coverage_descriptor_repair_retry_stats["attempt_count"] += 1
        strategy = str(diagnostics.get("strategy", "") or "")
        if strategy:
            self._shape_coverage_descriptor_repair_retry_stats[f"strategy:{strategy}"] += 1
        if bool(diagnostics.get("repaired", False)):
            self._shape_coverage_descriptor_repair_retry_stats["repaired_count"] += 1
        validation_after = diagnostics.get("validation_after")
        if isinstance(validation_after, Mapping) and bool(validation_after.get("accepted", False)):
            self._shape_coverage_descriptor_repair_retry_stats["validation_after_accepted_count"] += 1
        key = self._shape_coverage_descriptor_repair_posterior_key(diagnostics)
        if key:
            posterior = self._shape_coverage_descriptor_repair_posterior[key]
            posterior["attempts"] += 1
            if bool(diagnostics.get("repaired", False)):
                posterior["repair_successes"] += 1
            if strategy:
                posterior[f"strategy:{strategy}"] += 1
            validation_before = diagnostics.get("validation_before")
            if isinstance(validation_before, Mapping) and not bool(
                validation_before.get("accepted", False)
            ):
                posterior["validation_rejections"] += 1
            if isinstance(validation_after, Mapping) and bool(validation_after.get("accepted", False)):
                posterior["validation_successes"] += 1
        self._shape_coverage_descriptor_repair_retry_events.append(dict(diagnostics))
        self._shape_coverage_descriptor_repair_retry_events = self._shape_coverage_descriptor_repair_retry_events[-16:]

    def _record_shape_coverage_descriptor_repair_execution_outcome(
        self,
        *,
        record: ActionEffectRecord,
        pending: Mapping[str, Any],
    ) -> None:
        key = str(pending.get("shape_coverage_descriptor_repair_posterior_key", "") or "")
        if not key:
            return
        mismatches = self._descriptor_repair_execution_key_mismatches(
            key=key,
            pending=pending,
            prefix="shape_coverage_descriptor",
            family="coverage",
            mechanic_state_type="shape_coverage_paste",
            goal_link_type="same_color_shape_pixels_cover_target_markers",
        )
        if mismatches:
            self._append_descriptor_repair_attribution_rejection(
                self._shape_coverage_descriptor_repair_outcomes,
                key=key,
                primitive_id="shape_coverage_paste_solver",
                record=record,
                pending=pending,
                prefix="shape_coverage_descriptor",
                mismatched_fields=mismatches,
            )
            return
        posterior = self._shape_coverage_descriptor_repair_posterior[key]
        posterior["execution_events"] += 1
        if int(record.changed_pixel_count) > 0 and not bool(record.no_op):
            posterior["execution_successes"] += 1
        else:
            posterior["execution_no_effects"] += 1
        score_delta = int(record.score_delta)
        if score_delta > 0:
            posterior["score_successes"] += 1
            posterior["total_score_delta"] += score_delta
        else:
            posterior["no_score_events"] += 1
        self._shape_coverage_descriptor_repair_outcomes.append(
            {
                "posterior_key": key,
                "primitive_id": "shape_coverage_paste_solver",
                "action_name": str(record.action_name),
                "score_delta": score_delta,
                "changed_pixel_count": int(record.changed_pixel_count),
                "no_op": bool(record.no_op),
                "source_kind": str(pending.get("shape_coverage_descriptor_repair_source_kind", "") or ""),
                "reject_reason": str(pending.get("shape_coverage_descriptor_reject_reason", "") or ""),
                "abstraction_gap": str(pending.get("shape_coverage_descriptor_abstraction_gap", "") or ""),
                "repair_target": str(pending.get("shape_coverage_descriptor_repair_target", "") or ""),
                "validation_after_accepted": bool(
                    pending.get("shape_coverage_descriptor_repair_validation_after_accepted", False)
                ),
                "attribution_rejected": False,
                "mismatched_fields": [],
                "hypothesis_id": str(pending.get("shape_coverage_descriptor_hypothesis_id", "") or ""),
            }
        )
        self._shape_coverage_descriptor_repair_outcomes = self._shape_coverage_descriptor_repair_outcomes[-32:]

    def _seed_shape_coverage_descriptor_repair_posterior_from_env(self) -> None:
        raw = str(os.environ.get("ECA_SHAPE_COVERAGE_REPAIR_POSTERIOR_SEED_JSON", "") or "").strip()
        if not raw:
            return
        try:
            parsed = json.loads(raw)
        except (TypeError, ValueError):
            return
        entries: list[Any]
        if isinstance(parsed, Mapping):
            entries = [parsed]
        elif isinstance(parsed, list):
            entries = list(parsed)
        else:
            return
        counter_fields = {
            "attempts",
            "repair_successes",
            "validation_rejections",
            "validation_successes",
            "execution_events",
            "execution_successes",
            "execution_no_effects",
            "score_successes",
            "no_score_events",
            "total_score_delta",
        }
        for item in entries:
            if not isinstance(item, Mapping):
                continue
            key = str(item.get("posterior_key", "") or "")
            if not key:
                key = build_descriptor_repair_key(
                    source_kind=item.get("source_kind", ""),
                    family=item.get("family", ""),
                    mechanic_state_type=item.get("mechanic_state_type", ""),
                    goal_link_type=item.get("goal_link_type", ""),
                    reject_reason=item.get("reject_reason", ""),
                    abstraction_gap=item.get("abstraction_gap", ""),
                    repair_target=item.get("repair_target", ""),
                    defaults={
                        "source_kind": "psa_symbolic_induced",
                        "family": "coverage",
                        "mechanic_state_type": "shape_coverage_paste",
                        "goal_link_type": "same_color_shape_pixels_cover_target_markers",
                        "reject_reason": "operation_plan_len_mismatch",
                        "abstraction_gap": "stale_or_incomplete_plan",
                        "repair_target": "reread_shape_coverage_plan",
                    },
                )
            posterior = self._shape_coverage_descriptor_repair_posterior[key]
            for field_name in counter_fields:
                try:
                    value = int(item.get(field_name, 0) or 0)
                except (TypeError, ValueError):
                    value = 0
                if value:
                    posterior[field_name] += value
            strategy = str(item.get("strategy", "") or "")
            if strategy:
                try:
                    value = int(item.get(f"strategy:{strategy}", item.get("strategy_count", 0)) or 0)
                except (TypeError, ValueError):
                    value = 0
                if value:
                    posterior[f"strategy:{strategy}"] += value

    def _shape_coverage_descriptor_repair_posterior_summary(self) -> dict[str, Any]:
        by_key: dict[str, dict[str, Any]] = {}
        ranked: list[tuple[float, str]] = []
        for key in sorted(self._shape_coverage_descriptor_repair_posterior):
            counter = self._shape_coverage_descriptor_repair_posterior[key]
            confidence = descriptor_repair_confidence(counter)
            suppression_reason = descriptor_repair_suppression_reason(counter)
            by_key[key] = {
                "attempts": int(counter.get("attempts", 0)),
                "repair_successes": int(counter.get("repair_successes", 0)),
                "validation_rejections": int(counter.get("validation_rejections", 0)),
                "validation_successes": int(counter.get("validation_successes", 0)),
                "execution_events": int(counter.get("execution_events", 0)),
                "execution_successes": int(counter.get("execution_successes", 0)),
                "execution_no_effects": int(counter.get("execution_no_effects", 0)),
                "score_successes": int(counter.get("score_successes", 0)),
                "no_score_events": int(counter.get("no_score_events", 0)),
                "total_score_delta": int(counter.get("total_score_delta", 0)),
                "confidence": round(confidence, 6),
                "suppressed": bool(suppression_reason),
                "suppression_reason": suppression_reason,
            }
            ranked.append((-confidence, key))
        ranked.sort()
        return {
            "schema_version": "shape_coverage_descriptor_repair_posterior.v1",
            "entry_count": int(len(by_key)),
            "attempt_count": int(
                sum(counter.get("attempts", 0) for counter in self._shape_coverage_descriptor_repair_posterior.values())
            ),
            "validation_success_count": int(
                sum(
                    counter.get("validation_successes", 0)
                    for counter in self._shape_coverage_descriptor_repair_posterior.values()
                )
            ),
            "execution_success_count": int(
                sum(
                    counter.get("execution_successes", 0)
                    for counter in self._shape_coverage_descriptor_repair_posterior.values()
                )
            ),
            "score_success_count": int(
                sum(counter.get("score_successes", 0) for counter in self._shape_coverage_descriptor_repair_posterior.values())
            ),
            "total_score_delta": int(
                sum(counter.get("total_score_delta", 0) for counter in self._shape_coverage_descriptor_repair_posterior.values())
            ),
            "ranked_keys": [key for _score, key in ranked[:8]],
            "by_key": by_key,
            "recent_outcomes": list(self._shape_coverage_descriptor_repair_outcomes[-8:]),
        }

    def _shape_coverage_descriptor_feedback_summary(self) -> dict[str, Any]:
        return {
            "schema_version": "shape_coverage_descriptor_feedback_summary.v1",
            "event_count": int(len(self._shape_coverage_descriptor_feedback_events)),
            "reject_reason_counts": dict(sorted(self._shape_coverage_descriptor_reject_reasons.items())),
            "abstraction_gap_counts": dict(sorted(self._shape_coverage_descriptor_abstraction_gaps.items())),
            "repair_target_counts": dict(sorted(self._shape_coverage_descriptor_repair_targets.items())),
            "recent": list(self._shape_coverage_descriptor_feedback_events[-8:]),
            "repair_retry": {
                "enabled": bool(self._shape_coverage_descriptor_repair_retry_enabled()),
                "stats": dict(sorted(self._shape_coverage_descriptor_repair_retry_stats.items())),
                "recent": list(self._shape_coverage_descriptor_repair_retry_events[-4:]),
            },
            "repair_posterior": self._shape_coverage_descriptor_repair_posterior_summary(),
        }

    def _sand_filter_flow_step(
        self,
        available: set[str],
        *,
        state: dict[str, Any] | None,
    ) -> tuple[str, dict[str, Any]] | None:
        if self._active_sand_filter_flow_plan:
            action_name, payload = self._active_sand_filter_flow_plan.popleft()
            if action_name in available:
                return action_name, dict(payload)
            self._active_sand_filter_flow_plan.clear()
            self._last_sand_filter_flow_state = None
            return None
        if state is None:
            self._active_sand_filter_flow_plan.clear()
            self._last_sand_filter_flow_state = None
            return None
        plan = _sand_filter_flow_plan(state, available)
        if not plan:
            self._active_sand_filter_flow_plan.clear()
            self._last_sand_filter_flow_state = None
            return None
        self._active_sand_filter_flow_plan.clear()
        self._active_sand_filter_flow_plan.extend(plan)
        self._last_sand_filter_flow_state = dict(state)
        action_name, payload = self._active_sand_filter_flow_plan.popleft()
        if action_name in available:
            return action_name, dict(payload)
        self._active_sand_filter_flow_plan.clear()
        self._last_sand_filter_flow_state = None
        return None

    def _paint_region_reference_step(
        self,
        available: set[str],
        *,
        state: dict[str, Any] | None,
    ) -> tuple[str, dict[str, Any]] | None:
        if self._active_paint_region_reference_plan:
            action_name, payload = self._active_paint_region_reference_plan.popleft()
            if action_name in available:
                return action_name, dict(payload)
            self._active_paint_region_reference_plan.clear()
            self._last_paint_region_reference_state = None
            return None
        if state is None:
            self._active_paint_region_reference_plan.clear()
            self._last_paint_region_reference_state = None
            return None
        hypothesis_validation = _paint_region_reference_hypothesis_descriptor_validation(state)
        if not bool(hypothesis_validation["accepted"]):
            feedback = self._record_paint_region_descriptor_feedback(hypothesis_validation)
            if self._paint_region_descriptor_repair_retry_enabled():
                repaired_state, retry_diagnostics = _paint_region_reference_repair_descriptor_from_feedback(
                    state,
                    feedback,
                    source_kind=str(
                        os.environ.get(
                            "ECA_PAINT_REGION_DESCRIPTOR_REPAIR_RETRY_SOURCE_KIND",
                            "psa_symbolic_induced",
                        )
                        or "psa_symbolic_induced"
                    ),
                )
                self._record_paint_region_descriptor_repair_retry(retry_diagnostics)
                if repaired_state is not None and bool(retry_diagnostics.get("repaired", False)):
                    repaired_state = dict(repaired_state)
                    repair_key = self._paint_region_descriptor_repair_posterior_key(
                        retry_diagnostics
                    )
                    repaired_state["descriptor_repair_feedback"] = dict(feedback)
                    repaired_state["descriptor_repair_retry_diagnostics"] = dict(
                        retry_diagnostics
                    )
                    repaired_state["descriptor_repair_posterior_key"] = repair_key
                    plan = _paint_region_reference_plan(repaired_state, available)
                    if plan:
                        self._active_paint_region_reference_plan.clear()
                        self._active_paint_region_reference_plan.extend(plan)
                        self._last_paint_region_reference_state = dict(repaired_state)
                        action_name, payload = self._active_paint_region_reference_plan.popleft()
                        if action_name in available:
                            self._paint_region_descriptor_repair_retry_stats["executed_first_step_count"] += 1
                            return action_name, dict(payload)
                    self._paint_region_descriptor_repair_retry_stats["plan_missing_count"] += 1
            self._active_paint_region_reference_plan.clear()
            self._last_paint_region_reference_state = None
            return None
        plan = _paint_region_reference_plan(state, available)
        if not plan:
            self._active_paint_region_reference_plan.clear()
            self._last_paint_region_reference_state = None
            return None
        self._active_paint_region_reference_plan.clear()
        self._active_paint_region_reference_plan.extend(plan)
        self._last_paint_region_reference_state = dict(state)
        action_name, payload = self._active_paint_region_reference_plan.popleft()
        if action_name in available:
            return action_name, dict(payload)
        self._active_paint_region_reference_plan.clear()
        self._last_paint_region_reference_state = None
        return None

    def _paint_region_descriptor_repair_retry_enabled(self) -> bool:
        return _eca_env_flag("ECA_PAINT_REGION_ENABLE_DESCRIPTOR_REPAIR_RETRY")

    def _record_paint_region_descriptor_feedback(self, validation: Mapping[str, Any]) -> dict[str, Any]:
        feedback = _paint_region_reference_descriptor_feedback(validation)
        self._paint_region_descriptor_reject_reasons[str(feedback.get("reject_reason", "") or "")] += 1
        self._paint_region_descriptor_abstraction_gaps[str(feedback.get("abstraction_gap", "") or "")] += 1
        self._paint_region_descriptor_repair_targets[str(feedback.get("repair_target", "") or "")] += 1
        self._paint_region_descriptor_feedback_events.append(dict(feedback))
        self._paint_region_descriptor_feedback_events = self._paint_region_descriptor_feedback_events[-32:]
        return feedback

    def _paint_region_descriptor_repair_posterior_key(
        self,
        diagnostics: Mapping[str, Any],
    ) -> str:
        validation_before = diagnostics.get("validation_before")
        validation_before = validation_before if isinstance(validation_before, Mapping) else {}
        validation_after = diagnostics.get("validation_after")
        validation_after = validation_after if isinstance(validation_after, Mapping) else {}
        feedback = _paint_region_reference_descriptor_feedback(validation_before)
        return build_descriptor_repair_key(
            source_kind=diagnostics.get("source_kind", "")
            or validation_before.get("source_kind", "")
            or validation_after.get("source_kind", "")
            or "unknown",
            family=validation_before.get("family", "") or validation_after.get("family", "") or "paint_reference",
            mechanic_state_type=validation_before.get("mechanic_state_type", "")
            or validation_after.get("mechanic_state_type", "")
            or "paint_region_reference",
            goal_link_type=validation_before.get("goal_link_type", "")
            or validation_after.get("goal_link_type", "")
            or "canvas_matches_visible_reference",
            reject_reason=validation_before.get("reject_reason", ""),
            abstraction_gap=feedback.get("abstraction_gap", ""),
            repair_target=diagnostics.get("repair_target", "") or feedback.get("repair_target", ""),
        )

    def _record_paint_region_descriptor_repair_retry(self, diagnostics: Mapping[str, Any]) -> None:
        self._paint_region_descriptor_repair_retry_stats["attempt_count"] += 1
        strategy = str(diagnostics.get("strategy", "") or "")
        if strategy:
            self._paint_region_descriptor_repair_retry_stats[f"strategy:{strategy}"] += 1
        if bool(diagnostics.get("repaired", False)):
            self._paint_region_descriptor_repair_retry_stats["repaired_count"] += 1
        validation_after = diagnostics.get("validation_after")
        if isinstance(validation_after, Mapping) and bool(validation_after.get("accepted", False)):
            self._paint_region_descriptor_repair_retry_stats["validation_after_accepted_count"] += 1
        key = self._paint_region_descriptor_repair_posterior_key(diagnostics)
        if key:
            posterior = self._paint_region_descriptor_repair_posterior[key]
            posterior["attempts"] += 1
            if bool(diagnostics.get("repaired", False)):
                posterior["repair_successes"] += 1
            if strategy:
                posterior[f"strategy:{strategy}"] += 1
            validation_before = diagnostics.get("validation_before")
            if isinstance(validation_before, Mapping) and not bool(
                validation_before.get("accepted", False)
            ):
                posterior["validation_rejections"] += 1
            if isinstance(validation_after, Mapping) and bool(validation_after.get("accepted", False)):
                posterior["validation_successes"] += 1
        self._paint_region_descriptor_repair_retry_events.append(dict(diagnostics))
        self._paint_region_descriptor_repair_retry_events = self._paint_region_descriptor_repair_retry_events[-16:]

    def _record_paint_region_descriptor_repair_execution_outcome(
        self,
        *,
        record: ActionEffectRecord,
        pending: Mapping[str, Any],
    ) -> None:
        key = str(pending.get("paint_region_descriptor_repair_posterior_key", "") or "")
        if not key:
            return
        mismatches = self._descriptor_repair_execution_key_mismatches(
            key=key,
            pending=pending,
            prefix="paint_region_descriptor",
            family="paint_reference",
            mechanic_state_type="paint_region_reference",
            goal_link_type="canvas_matches_visible_reference",
        )
        if mismatches:
            self._append_descriptor_repair_attribution_rejection(
                self._paint_region_descriptor_repair_outcomes,
                key=key,
                primitive_id="paint_region_reference_solver",
                record=record,
                pending=pending,
                prefix="paint_region_descriptor",
                mismatched_fields=mismatches,
            )
            return
        posterior = self._paint_region_descriptor_repair_posterior[key]
        posterior["execution_events"] += 1
        if int(record.changed_pixel_count) > 0 and not bool(record.no_op):
            posterior["execution_successes"] += 1
        else:
            posterior["execution_no_effects"] += 1
        score_delta = int(record.score_delta)
        if score_delta > 0:
            posterior["score_successes"] += 1
            posterior["total_score_delta"] += score_delta
        else:
            posterior["no_score_events"] += 1
        self._paint_region_descriptor_repair_outcomes.append(
            {
                "posterior_key": key,
                "primitive_id": "paint_region_reference_solver",
                "action_name": str(record.action_name),
                "score_delta": score_delta,
                "changed_pixel_count": int(record.changed_pixel_count),
                "no_op": bool(record.no_op),
                "source_kind": str(pending.get("paint_region_descriptor_repair_source_kind", "") or ""),
                "reject_reason": str(pending.get("paint_region_descriptor_reject_reason", "") or ""),
                "abstraction_gap": str(pending.get("paint_region_descriptor_abstraction_gap", "") or ""),
                "repair_target": str(pending.get("paint_region_descriptor_repair_target", "") or ""),
                "validation_after_accepted": bool(
                    pending.get("paint_region_descriptor_repair_validation_after_accepted", False)
                ),
                "attribution_rejected": False,
                "mismatched_fields": [],
                "hypothesis_id": str(pending.get("paint_region_descriptor_hypothesis_id", "") or ""),
            }
        )
        self._paint_region_descriptor_repair_outcomes = self._paint_region_descriptor_repair_outcomes[-32:]

    def _seed_paint_region_descriptor_repair_posterior_from_env(self) -> None:
        raw = str(os.environ.get("ECA_PAINT_REGION_REPAIR_POSTERIOR_SEED_JSON", "") or "").strip()
        if not raw:
            return
        try:
            parsed = json.loads(raw)
        except (TypeError, ValueError):
            return
        entries: list[Any]
        if isinstance(parsed, Mapping):
            entries = [parsed]
        elif isinstance(parsed, list):
            entries = list(parsed)
        else:
            return
        counter_fields = {
            "attempts",
            "repair_successes",
            "validation_rejections",
            "validation_successes",
            "execution_events",
            "execution_successes",
            "execution_no_effects",
            "score_successes",
            "no_score_events",
            "total_score_delta",
        }
        for item in entries:
            if not isinstance(item, Mapping):
                continue
            key = str(item.get("posterior_key", "") or "")
            if not key:
                key = build_descriptor_repair_key(
                    source_kind=item.get("source_kind", ""),
                    family=item.get("family", ""),
                    mechanic_state_type=item.get("mechanic_state_type", ""),
                    goal_link_type=item.get("goal_link_type", ""),
                    reject_reason=item.get("reject_reason", ""),
                    abstraction_gap=item.get("abstraction_gap", ""),
                    repair_target=item.get("repair_target", ""),
                    defaults={
                        "source_kind": "psa_symbolic_induced",
                        "family": "paint_reference",
                        "mechanic_state_type": "paint_region_reference",
                        "goal_link_type": "canvas_matches_visible_reference",
                        "reject_reason": "operation_plan_len_mismatch",
                        "abstraction_gap": "stale_or_incomplete_plan",
                        "repair_target": "reread_paint_operations",
                    },
                )
            posterior = self._paint_region_descriptor_repair_posterior[key]
            for field_name in counter_fields:
                try:
                    value = int(item.get(field_name, 0) or 0)
                except (TypeError, ValueError):
                    value = 0
                if value:
                    posterior[field_name] += value
            strategy = str(item.get("strategy", "") or "")
            if strategy:
                try:
                    value = int(item.get(f"strategy:{strategy}", item.get("strategy_count", 0)) or 0)
                except (TypeError, ValueError):
                    value = 0
                if value:
                    posterior[f"strategy:{strategy}"] += value

    def _paint_region_descriptor_repair_posterior_summary(self) -> dict[str, Any]:
        by_key: dict[str, dict[str, Any]] = {}
        ranked: list[tuple[float, str]] = []
        for key in sorted(self._paint_region_descriptor_repair_posterior):
            counter = self._paint_region_descriptor_repair_posterior[key]
            confidence = descriptor_repair_confidence(counter)
            suppression_reason = descriptor_repair_suppression_reason(counter)
            by_key[key] = {
                "attempts": int(counter.get("attempts", 0)),
                "repair_successes": int(counter.get("repair_successes", 0)),
                "validation_rejections": int(counter.get("validation_rejections", 0)),
                "validation_successes": int(counter.get("validation_successes", 0)),
                "execution_events": int(counter.get("execution_events", 0)),
                "execution_successes": int(counter.get("execution_successes", 0)),
                "execution_no_effects": int(counter.get("execution_no_effects", 0)),
                "score_successes": int(counter.get("score_successes", 0)),
                "no_score_events": int(counter.get("no_score_events", 0)),
                "total_score_delta": int(counter.get("total_score_delta", 0)),
                "confidence": round(confidence, 6),
                "suppressed": bool(suppression_reason),
                "suppression_reason": suppression_reason,
            }
            ranked.append((-confidence, key))
        ranked.sort()
        return {
            "schema_version": "paint_region_descriptor_repair_posterior.v1",
            "entry_count": int(len(by_key)),
            "attempt_count": int(
                sum(counter.get("attempts", 0) for counter in self._paint_region_descriptor_repair_posterior.values())
            ),
            "validation_success_count": int(
                sum(
                    counter.get("validation_successes", 0)
                    for counter in self._paint_region_descriptor_repair_posterior.values()
                )
            ),
            "execution_success_count": int(
                sum(
                    counter.get("execution_successes", 0)
                    for counter in self._paint_region_descriptor_repair_posterior.values()
                )
            ),
            "score_success_count": int(
                sum(counter.get("score_successes", 0) for counter in self._paint_region_descriptor_repair_posterior.values())
            ),
            "total_score_delta": int(
                sum(counter.get("total_score_delta", 0) for counter in self._paint_region_descriptor_repair_posterior.values())
            ),
            "ranked_keys": [key for _score, key in ranked[:8]],
            "by_key": by_key,
            "recent_outcomes": list(self._paint_region_descriptor_repair_outcomes[-8:]),
        }

    def _paint_region_descriptor_feedback_summary(self) -> dict[str, Any]:
        return {
            "schema_version": "paint_region_descriptor_feedback_summary.v1",
            "event_count": int(len(self._paint_region_descriptor_feedback_events)),
            "reject_reason_counts": dict(sorted(self._paint_region_descriptor_reject_reasons.items())),
            "abstraction_gap_counts": dict(sorted(self._paint_region_descriptor_abstraction_gaps.items())),
            "repair_target_counts": dict(sorted(self._paint_region_descriptor_repair_targets.items())),
            "recent": list(self._paint_region_descriptor_feedback_events[-8:]),
            "repair_retry": {
                "enabled": bool(self._paint_region_descriptor_repair_retry_enabled()),
                "stats": dict(sorted(self._paint_region_descriptor_repair_retry_stats.items())),
                "recent": list(self._paint_region_descriptor_repair_retry_events[-4:]),
            },
            "repair_posterior": self._paint_region_descriptor_repair_posterior_summary(),
        }

    def _slot_pool_sequence_step(
        self,
        available: set[str],
        *,
        state: dict[str, Any] | None,
    ) -> tuple[str, dict[str, Any]] | None:
        if self._active_slot_pool_sequence_plan:
            action_name, payload = self._active_slot_pool_sequence_plan.popleft()
            if action_name in available:
                return action_name, dict(payload)
            self._active_slot_pool_sequence_plan.clear()
            self._last_slot_pool_sequence_state = None
            return None
        if state is None:
            self._active_slot_pool_sequence_plan.clear()
            self._last_slot_pool_sequence_state = None
            return None
        hypothesis_validation = _slot_pool_sequence_hypothesis_descriptor_validation(state)
        if not bool(hypothesis_validation["accepted"]):
            feedback = self._record_slot_pool_descriptor_feedback(hypothesis_validation)
            if self._slot_pool_descriptor_repair_retry_enabled():
                repaired_state, retry_diagnostics = _slot_pool_sequence_repair_descriptor_from_feedback(
                    state,
                    feedback,
                    source_kind=str(
                        os.environ.get(
                            "ECA_SLOT_POOL_DESCRIPTOR_REPAIR_RETRY_SOURCE_KIND",
                            "psa_symbolic_induced",
                        )
                        or "psa_symbolic_induced"
                    ),
                )
                self._record_slot_pool_descriptor_repair_retry(retry_diagnostics)
                if repaired_state is not None and bool(retry_diagnostics.get("repaired", False)):
                    repaired_state = dict(repaired_state)
                    repair_key = self._slot_pool_descriptor_repair_posterior_key(
                        retry_diagnostics
                    )
                    repaired_state["descriptor_repair_feedback"] = dict(feedback)
                    repaired_state["descriptor_repair_retry_diagnostics"] = dict(
                        retry_diagnostics
                    )
                    repaired_state["descriptor_repair_posterior_key"] = repair_key
                    plan = _slot_pool_sequence_plan(repaired_state, available)
                    if plan:
                        self._active_slot_pool_sequence_plan.clear()
                        self._active_slot_pool_sequence_plan.extend(plan)
                        self._last_slot_pool_sequence_state = dict(repaired_state)
                        action_name, payload = self._active_slot_pool_sequence_plan.popleft()
                        if action_name in available:
                            self._slot_pool_descriptor_repair_retry_stats["executed_first_step_count"] += 1
                            return action_name, dict(payload)
                    self._slot_pool_descriptor_repair_retry_stats["plan_missing_count"] += 1
            self._active_slot_pool_sequence_plan.clear()
            self._last_slot_pool_sequence_state = None
            return None
        plan = _slot_pool_sequence_plan(state, available)
        if not plan:
            self._active_slot_pool_sequence_plan.clear()
            self._last_slot_pool_sequence_state = None
            return None
        self._active_slot_pool_sequence_plan.clear()
        self._active_slot_pool_sequence_plan.extend(plan)
        self._last_slot_pool_sequence_state = dict(state)
        action_name, payload = self._active_slot_pool_sequence_plan.popleft()
        if action_name in available:
            return action_name, dict(payload)
        self._active_slot_pool_sequence_plan.clear()
        self._last_slot_pool_sequence_state = None
        return None

    def _slot_pool_descriptor_repair_retry_enabled(self) -> bool:
        return _eca_env_flag("ECA_SLOT_POOL_ENABLE_DESCRIPTOR_REPAIR_RETRY")

    def _slot_pool_descriptor_repair_posterior_ranker_enabled(self) -> bool:
        return _eca_env_flag("ECA_SLOT_POOL_ENABLE_REPAIR_POSTERIOR_RANKER")

    def _record_slot_pool_descriptor_feedback(self, validation: Mapping[str, Any]) -> dict[str, Any]:
        feedback = _slot_pool_sequence_descriptor_feedback(validation)
        if (
            self._slot_pool_descriptor_repair_posterior_ranker_enabled()
            and not bool(feedback.get("accepted", False))
        ):
            feedback = self._rank_slot_pool_descriptor_repair_targets(validation, feedback)
        self._slot_pool_descriptor_reject_reasons[str(feedback.get("reject_reason", "") or "")] += 1
        self._slot_pool_descriptor_abstraction_gaps[str(feedback.get("abstraction_gap", "") or "")] += 1
        self._slot_pool_descriptor_repair_targets[str(feedback.get("repair_target", "") or "")] += 1
        self._slot_pool_descriptor_feedback_events.append(dict(feedback))
        self._slot_pool_descriptor_feedback_events = self._slot_pool_descriptor_feedback_events[-32:]
        return feedback

    def _slot_pool_descriptor_repair_candidate_targets(
        self,
        feedback: Mapping[str, Any],
    ) -> list[str]:
        default_target = str(feedback.get("repair_target", "") or "")
        reason = str(feedback.get("reject_reason", "") or "")
        extras_by_reason: dict[str, list[str]] = {
            "missing_descriptor": ["emit_slot_pool_descriptor"],
            "missing_state_variables": [
                "emit_state_variables",
                "reread_visible_sequence",
                "reread_slot_markers",
            ],
            "sequence_len_mismatch": [
                "reread_visible_sequence",
                "emit_state_variables",
            ],
            "slot_count_mismatch": [
                "reread_slot_markers",
                "emit_state_variables",
            ],
            "operator_not_coordinate_free": [
                "remove_coordinate_bound_operator",
                "rewrite_operator_candidate",
            ],
            "missing_required_predicates": [
                "reread_required_predicates",
                "emit_state_variables",
            ],
            "missing_reentry_predicate": [
                "reread_repeated_child_block",
                "reread_required_predicates",
            ],
        }
        candidates = [default_target, *extras_by_reason.get(reason, [])]
        out: list[str] = []
        seen: set[str] = set()
        for target in candidates:
            target = str(target or "")
            if not target or target in seen:
                continue
            seen.add(target)
            out.append(target)
        return out

    def _slot_pool_descriptor_repair_posterior_key_for_feedback(
        self,
        validation: Mapping[str, Any],
        feedback: Mapping[str, Any],
        *,
        repair_target: str,
    ) -> str:
        return build_descriptor_repair_key(
            source_kind=validation.get("source_kind", "") or feedback.get("source_kind", ""),
            family=validation.get("family", ""),
            mechanic_state_type=validation.get("mechanic_state_type", ""),
            goal_link_type=validation.get("goal_link_type", ""),
            reject_reason=validation.get("reject_reason", "") or feedback.get("reject_reason", ""),
            abstraction_gap=feedback.get("abstraction_gap", ""),
            repair_target=repair_target,
            defaults={
                "source_kind": "unknown",
                "family": "slot_pool",
                "mechanic_state_type": "slot_pool_sequence",
                "goal_link_type": "visible_sequence_filled_into_slot_row",
            },
        )

    @staticmethod
    def _slot_pool_descriptor_repair_confidence(counter: Mapping[str, Any]) -> float:
        return descriptor_repair_confidence(counter)

    @staticmethod
    def _slot_pool_descriptor_repair_suppression_reason(counter: Mapping[str, Any]) -> str:
        return descriptor_repair_suppression_reason(counter)

    def _rank_slot_pool_descriptor_repair_targets(
        self,
        validation: Mapping[str, Any],
        feedback: Mapping[str, Any],
    ) -> dict[str, Any]:
        default_target = str(feedback.get("repair_target", "") or "")
        ranked: list[tuple[int, float, int, dict[str, Any]]] = []
        for index, target in enumerate(self._slot_pool_descriptor_repair_candidate_targets(feedback)):
            key = self._slot_pool_descriptor_repair_posterior_key_for_feedback(
                validation,
                feedback,
                repair_target=target,
            )
            counter = self._slot_pool_descriptor_repair_posterior.get(key, Counter())
            attempts = int(counter.get("attempts", 0))
            confidence = self._slot_pool_descriptor_repair_confidence(counter)
            suppression_reason = self._slot_pool_descriptor_repair_suppression_reason(counter)
            suppressed = bool(suppression_reason)
            default_bonus = 0.01 if target == default_target else 0.0
            supported_bonus = 0.02 if attempts > 0 else 0.0
            rank_score = confidence + default_bonus + supported_bonus
            ranked.append(
                (
                    1 if suppressed else 0,
                    -rank_score,
                    index,
                    {
                        "repair_target": target,
                        "posterior_key": key,
                        "confidence": round(confidence, 6),
                        "attempts": attempts,
                        "suppressed": suppressed,
                        "suppression_reason": suppression_reason,
                        "validation_successes": int(counter.get("validation_successes", 0)),
                        "execution_successes": int(counter.get("execution_successes", 0)),
                        "score_successes": int(counter.get("score_successes", 0)),
                        "no_score_events": int(counter.get("no_score_events", 0)),
                        "total_score_delta": int(counter.get("total_score_delta", 0)),
                    },
                )
            )
        ranked.sort(key=lambda item: (item[0], item[1], item[2]))
        ranked_entries = [entry for _suppressed, _score, _index, entry in ranked]
        selected = ranked_entries[0] if ranked_entries else {}
        suppressed_entries = [
            {
                "repair_target": str(entry.get("repair_target", "") or ""),
                "posterior_key": str(entry.get("posterior_key", "") or ""),
                "suppression_reason": str(entry.get("suppression_reason", "") or ""),
                "attempts": int(entry.get("attempts", 0) or 0),
            }
            for entry in ranked_entries
            if bool(entry.get("suppressed", False))
        ]
        selected_attempts = int(selected.get("attempts", 0) or 0)
        selected_target = str(selected.get("repair_target", default_target) or default_target)
        if selected_attempts > 0:
            selection_reason = "posterior_ranked"
        elif suppressed_entries and selected_target != default_target:
            selection_reason = "posterior_suppressed_fallback"
        else:
            selection_reason = "default_mapping"
        out = dict(feedback)
        out["posterior_ranker_enabled"] = True
        out["posterior_ranker_candidate_targets"] = [
            str(entry.get("repair_target", "") or "") for entry in ranked_entries
        ]
        out["posterior_ranked_repair_targets"] = ranked_entries
        out["posterior_suppressed_repair_targets"] = suppressed_entries
        out["posterior_selected_repair_target"] = str(
            selected.get("repair_target", default_target) or default_target
        )
        out["posterior_selected_key"] = str(selected.get("posterior_key", "") or "")
        out["posterior_selected_suppressed"] = bool(selected.get("suppressed", False))
        out["posterior_selected_suppression_reason"] = str(
            selected.get("suppression_reason", "") or ""
        )
        out["posterior_selection_reason"] = selection_reason
        out["original_repair_target"] = default_target
        out["repair_target"] = str(out["posterior_selected_repair_target"])
        return out

    def _record_slot_pool_descriptor_repair_retry(self, diagnostics: Mapping[str, Any]) -> None:
        self._slot_pool_descriptor_repair_retry_stats["attempt_count"] += 1
        strategy = str(diagnostics.get("strategy", "") or "")
        if strategy:
            self._slot_pool_descriptor_repair_retry_stats[f"strategy:{strategy}"] += 1
        if bool(diagnostics.get("repaired", False)):
            self._slot_pool_descriptor_repair_retry_stats["repaired_count"] += 1
        validation_after = diagnostics.get("validation_after")
        if isinstance(validation_after, Mapping) and bool(validation_after.get("accepted", False)):
            self._slot_pool_descriptor_repair_retry_stats["validation_after_accepted_count"] += 1
        key = self._slot_pool_descriptor_repair_posterior_key(diagnostics)
        if key:
            posterior = self._slot_pool_descriptor_repair_posterior[key]
            posterior["attempts"] += 1
            if bool(diagnostics.get("repaired", False)):
                posterior["repair_successes"] += 1
            if strategy:
                posterior[f"strategy:{strategy}"] += 1
            validation_before = diagnostics.get("validation_before")
            if isinstance(validation_before, Mapping) and not bool(
                validation_before.get("accepted", False)
            ):
                posterior["validation_rejections"] += 1
            if isinstance(validation_after, Mapping) and bool(validation_after.get("accepted", False)):
                posterior["validation_successes"] += 1
        self._slot_pool_descriptor_repair_retry_events.append(dict(diagnostics))
        self._slot_pool_descriptor_repair_retry_events = self._slot_pool_descriptor_repair_retry_events[-16:]

    def _record_slot_pool_descriptor_repair_execution_outcome(
        self,
        *,
        record: ActionEffectRecord,
        pending: Mapping[str, Any],
    ) -> None:
        key = str(pending.get("slot_pool_descriptor_repair_posterior_key", "") or "")
        if not key:
            return
        mismatches = self._descriptor_repair_execution_key_mismatches(
            key=key,
            pending=pending,
            prefix="slot_pool_descriptor",
            family="slot_pool",
            mechanic_state_type="slot_pool_sequence",
            goal_link_type="visible_sequence_filled_into_slot_row",
        )
        if mismatches:
            self._append_descriptor_repair_attribution_rejection(
                self._slot_pool_descriptor_repair_outcomes,
                key=key,
                primitive_id="slot_pool_sequence_solver",
                record=record,
                pending=pending,
                prefix="slot_pool_descriptor",
                mismatched_fields=mismatches,
            )
            return
        posterior = self._slot_pool_descriptor_repair_posterior[key]
        posterior["execution_events"] += 1
        if int(record.changed_pixel_count) > 0 and not bool(record.no_op):
            posterior["execution_successes"] += 1
        else:
            posterior["execution_no_effects"] += 1
        score_delta = int(record.score_delta)
        if score_delta > 0:
            posterior["score_successes"] += 1
            posterior["total_score_delta"] += score_delta
        else:
            posterior["no_score_events"] += 1
        self._slot_pool_descriptor_repair_outcomes.append(
            {
                "posterior_key": key,
                "primitive_id": "slot_pool_sequence_solver",
                "action_name": str(record.action_name),
                "score_delta": score_delta,
                "changed_pixel_count": int(record.changed_pixel_count),
                "no_op": bool(record.no_op),
                "source_kind": str(pending.get("slot_pool_descriptor_repair_source_kind", "") or ""),
                "reject_reason": str(pending.get("slot_pool_descriptor_reject_reason", "") or ""),
                "abstraction_gap": str(pending.get("slot_pool_descriptor_abstraction_gap", "") or ""),
                "repair_target": str(pending.get("slot_pool_descriptor_repair_target", "") or ""),
                "validation_after_accepted": bool(
                    pending.get("slot_pool_descriptor_repair_validation_after_accepted", False)
                ),
                "ranker_enabled": bool(
                    pending.get("slot_pool_descriptor_repair_ranker_enabled", False)
                ),
                "selection_reason": str(
                    pending.get("slot_pool_descriptor_repair_selection_reason", "") or ""
                ),
                "selected_repair_target": str(
                    pending.get("slot_pool_descriptor_selected_repair_target", "") or ""
                ),
                "attribution_rejected": False,
                "mismatched_fields": [],
                "hypothesis_id": str(pending.get("slot_pool_descriptor_hypothesis_id", "") or ""),
            }
        )
        self._slot_pool_descriptor_repair_outcomes = self._slot_pool_descriptor_repair_outcomes[-32:]

    def _slot_pool_descriptor_repair_posterior_key(
        self,
        diagnostics: Mapping[str, Any],
    ) -> str:
        validation_before = diagnostics.get("validation_before")
        validation_before = validation_before if isinstance(validation_before, Mapping) else {}
        validation_after = diagnostics.get("validation_after")
        validation_after = validation_after if isinstance(validation_after, Mapping) else {}
        source_kind = str(
            diagnostics.get("source_kind", "")
            or validation_before.get("source_kind", "")
            or validation_after.get("source_kind", "")
            or "unknown"
        )
        family = str(
            validation_before.get("family", "")
            or validation_after.get("family", "")
            or "slot_pool"
        )
        mechanic_state_type = str(
            validation_before.get("mechanic_state_type", "")
            or validation_after.get("mechanic_state_type", "")
            or "slot_pool_sequence"
        )
        goal_link_type = str(
            validation_before.get("goal_link_type", "")
            or validation_after.get("goal_link_type", "")
            or "visible_sequence_filled_into_slot_row"
        )
        reject_reason = str(validation_before.get("reject_reason", "") or "")
        feedback = _slot_pool_sequence_descriptor_feedback(validation_before)
        abstraction_gap = str(feedback.get("abstraction_gap", "") or "")
        repair_target = str(diagnostics.get("repair_target", "") or feedback.get("repair_target", "") or "")
        return build_descriptor_repair_key(
            source_kind=source_kind,
            family=family,
            mechanic_state_type=mechanic_state_type,
            goal_link_type=goal_link_type,
            reject_reason=reject_reason,
            abstraction_gap=abstraction_gap,
            repair_target=repair_target,
        )

    def _seed_slot_pool_descriptor_repair_posterior_from_env(self) -> None:
        raw = str(os.environ.get("ECA_SLOT_POOL_REPAIR_POSTERIOR_SEED_JSON", "") or "").strip()
        if not raw:
            return
        try:
            parsed = json.loads(raw)
        except (TypeError, ValueError):
            return
        entries: list[Any]
        if isinstance(parsed, Mapping):
            entries = [parsed]
        elif isinstance(parsed, list):
            entries = list(parsed)
        else:
            return
        counter_fields = {
            "attempts",
            "repair_successes",
            "validation_rejections",
            "validation_successes",
            "execution_events",
            "execution_successes",
            "execution_no_effects",
            "score_successes",
            "no_score_events",
            "total_score_delta",
        }
        for item in entries:
            if not isinstance(item, Mapping):
                continue
            key = str(item.get("posterior_key", "") or "")
            if not key:
                key = build_descriptor_repair_key(
                    source_kind=item.get("source_kind", ""),
                    family=item.get("family", ""),
                    mechanic_state_type=item.get("mechanic_state_type", ""),
                    goal_link_type=item.get("goal_link_type", ""),
                    reject_reason=item.get("reject_reason", ""),
                    abstraction_gap=item.get("abstraction_gap", ""),
                    repair_target=item.get("repair_target", ""),
                    defaults={
                        "source_kind": "psa_symbolic_induced",
                        "family": "slot_pool",
                        "mechanic_state_type": "slot_pool_sequence",
                        "goal_link_type": "visible_sequence_filled_into_slot_row",
                        "reject_reason": "sequence_len_mismatch",
                        "abstraction_gap": "stale_or_incomplete_state",
                        "repair_target": "reread_visible_sequence",
                    },
                )
            posterior = self._slot_pool_descriptor_repair_posterior[key]
            for field_name in counter_fields:
                try:
                    value = int(item.get(field_name, 0) or 0)
                except (TypeError, ValueError):
                    value = 0
                if value:
                    posterior[field_name] += value
            strategy = str(item.get("strategy", "") or "")
            if strategy:
                try:
                    value = int(item.get(f"strategy:{strategy}", item.get("strategy_count", 0)) or 0)
                except (TypeError, ValueError):
                    value = 0
                if value:
                    posterior[f"strategy:{strategy}"] += value

    def _slot_pool_descriptor_repair_posterior_summary(self) -> dict[str, Any]:
        by_key: dict[str, dict[str, Any]] = {}
        ranked: list[tuple[float, str]] = []
        for key in sorted(self._slot_pool_descriptor_repair_posterior):
            counter = self._slot_pool_descriptor_repair_posterior[key]
            attempts = int(counter.get("attempts", 0))
            validation_successes = int(counter.get("validation_successes", 0))
            execution_successes = int(counter.get("execution_successes", 0))
            score_successes = int(counter.get("score_successes", 0))
            no_score_events = int(counter.get("no_score_events", 0))
            total_score_delta = int(counter.get("total_score_delta", 0))
            confidence = self._slot_pool_descriptor_repair_confidence(counter)
            suppression_reason = self._slot_pool_descriptor_repair_suppression_reason(counter)
            by_key[key] = {
                "attempts": attempts,
                "repair_successes": int(counter.get("repair_successes", 0)),
                "validation_rejections": int(counter.get("validation_rejections", 0)),
                "validation_successes": validation_successes,
                "execution_events": int(counter.get("execution_events", 0)),
                "execution_successes": execution_successes,
                "execution_no_effects": int(counter.get("execution_no_effects", 0)),
                "score_successes": score_successes,
                "no_score_events": no_score_events,
                "total_score_delta": total_score_delta,
                "confidence": round(confidence, 6),
                "suppressed": bool(suppression_reason),
                "suppression_reason": suppression_reason,
            }
            ranked.append((-confidence, key))
        ranked.sort()
        return {
            "schema_version": "slot_pool_descriptor_repair_posterior.v1",
            "entry_count": int(len(by_key)),
            "attempt_count": int(
                sum(counter.get("attempts", 0) for counter in self._slot_pool_descriptor_repair_posterior.values())
            ),
            "validation_success_count": int(
                sum(
                    counter.get("validation_successes", 0)
                    for counter in self._slot_pool_descriptor_repair_posterior.values()
                )
            ),
            "execution_success_count": int(
                sum(
                    counter.get("execution_successes", 0)
                    for counter in self._slot_pool_descriptor_repair_posterior.values()
                )
            ),
            "score_success_count": int(
                sum(counter.get("score_successes", 0) for counter in self._slot_pool_descriptor_repair_posterior.values())
            ),
            "total_score_delta": int(
                sum(counter.get("total_score_delta", 0) for counter in self._slot_pool_descriptor_repair_posterior.values())
            ),
            "ranked_keys": [key for _score, key in ranked[:8]],
            "by_key": by_key,
            "recent_outcomes": list(self._slot_pool_descriptor_repair_outcomes[-8:]),
        }

    def _slot_pool_descriptor_feedback_summary(self) -> dict[str, Any]:
        return {
            "schema_version": "slot_pool_descriptor_feedback_summary.v1",
            "event_count": int(len(self._slot_pool_descriptor_feedback_events)),
            "reject_reason_counts": dict(sorted(self._slot_pool_descriptor_reject_reasons.items())),
            "abstraction_gap_counts": dict(sorted(self._slot_pool_descriptor_abstraction_gaps.items())),
            "repair_target_counts": dict(sorted(self._slot_pool_descriptor_repair_targets.items())),
            "recent": list(self._slot_pool_descriptor_feedback_events[-8:]),
            "repair_retry": {
                "enabled": bool(self._slot_pool_descriptor_repair_retry_enabled()),
                "stats": dict(sorted(self._slot_pool_descriptor_repair_retry_stats.items())),
                "recent": list(self._slot_pool_descriptor_repair_retry_events[-4:]),
            },
            "repair_posterior": self._slot_pool_descriptor_repair_posterior_summary(),
        }

    def _pending_target_from_cycle_constraint_step(
        self,
        *,
        primitive_id: str,
        state: Mapping[str, Any] | None,
        action_name: str,
        action_payload: Mapping[str, Any] | None,
        actor_pos: tuple[int, int] | None,
    ) -> dict[str, Any] | None:
        if state is None:
            return None
        primitive = str(primitive_id or "")
        normalized_action = _normalize_action_name(action_name)
        payload = dict(action_payload or {})
        click_point = _click_point_from_payload({"action": normalized_action, **payload})
        site = click_point
        operator = "click" if click_point is not None else "cycle"
        if primitive == "color_cycle_constraint_solver":
            if site is None:
                return None
            candidate: dict[str, Any] = {
                "kind": "color_cycle_constraint",
                **_compact_cycle_constraint_metadata(state),
                "site": [int(site[0]), int(site[1])],
                "action_name": "ACTION6",
                "score_delta": 0,
                "goal_likelihood": 0.55,
                "objective_kind": "state_advance",
                "macro_goal_link": True,
                "constraint_count": int(state.get("constraint_count", 0) or 0),
                "clickable_count": int(state.get("clickable_count", 0) or 0),
            }
        elif primitive == "button_cycle_rotation_solver":
            if site is None:
                return None
            target = tuple(state.get("target_pos") or ())
            current = tuple(state.get("current_pos") or ())
            candidate = {
                "kind": "button_cycle_target",
                **_compact_cycle_constraint_metadata(state),
                "site": [int(site[0]), int(site[1])],
                "action_name": "ACTION6",
                "score_delta": 0,
                "goal_likelihood": 0.6,
                "objective_kind": "state_advance",
                "macro_goal_link": True,
                "target_pos": [int(target[0]), int(target[1])] if len(target) >= 2 else [],
                "current_pos": [int(current[0]), int(current[1])] if len(current) >= 2 else [],
                "expected_goal_delta": float(state.get("expected_goal_delta", 0.0) or 0.0),
                "reader_confidence": float(state.get("reader_confidence", 0.0) or 0.0),
                "goal_link_confidence": float(state.get("goal_link_confidence", 0.0) or 0.0),
            }
        elif primitive == "rule_table_rotation_solver":
            selected_center = tuple(state.get("selected_slot_center") or ())
            target_center = tuple(state.get("target_slot_center") or ())
            if len(target_center) >= 2:
                site = (int(target_center[0]), int(target_center[1]))
            elif len(selected_center) >= 2:
                site = (int(selected_center[0]), int(selected_center[1]))
            if site is None:
                return None
            candidate = {
                "kind": "rule_table_rotation_target",
                **_compact_cycle_constraint_metadata(state),
                "site": [int(site[0]), int(site[1])],
                "action_name": normalized_action,
                "score_delta": 0,
                "goal_likelihood": 0.65,
                "objective_kind": "state_advance",
                "macro_goal_link": True,
                "selected_index": int(state.get("selected_index", -1)),
                "target_index": int(state.get("target_index", -1)),
                "mismatch_count": int(state.get("mismatch_count", 0) or 0),
                "satisfied_count": int(state.get("satisfied_count", 0) or 0),
                "action_role": str(state.get("action_role", "") or ""),
                "cycle_operation_kind": str(state.get("cycle_operation_kind", "") or ""),
                "learned_successor_count": int(state.get("learned_successor_count", 0) or 0),
                "expected_goal_delta": float(state.get("expected_goal_delta", 0.0) or 0.0),
                "reader_confidence": float(state.get("reader_confidence", 0.0) or 0.0),
                "goal_link_confidence": float(state.get("goal_link_confidence", 0.0) or 0.0),
            }
        else:
            return None
        pending = self._pending_target_from_candidate(
            candidate,
            operator=operator,
            action_name=normalized_action,
            primitive_id=primitive,
            actor_pos=actor_pos,
        )
        if pending is not None:
            pending["macro_goal_link"] = True
            pending["objective_kind"] = "state_advance"
        return pending

    def _pending_target_from_mechanic_hypothesis_choice(
        self,
        choice: Mapping[str, Any],
        *,
        action_name: str,
        action_payload: Mapping[str, Any] | None,
        actor_pos: tuple[int, int] | None,
    ) -> dict[str, Any] | None:
        hypothesis = choice.get("hypothesis")
        state = (
            dict(getattr(hypothesis, "evidence", {}) or {}).get("cycle_state")
            if hypothesis is not None
            else None
        )
        source_primitive = str(choice.get("source_primitive_id", "") or "")
        source_kind = str(choice.get("source_kind", "") or "")
        if source_kind == "ledger_induced" or source_kind in ABSTRACTION_SOURCE_KINDS:
            control_sites = list(getattr(hypothesis, "control_sites", []) or [])
            site_payload = dict(control_sites[0]) if control_sites and isinstance(control_sites[0], Mapping) else {}
            if "x" not in site_payload or "y" not in site_payload:
                payload = dict(action_payload or {})
                site_payload = {"x": payload.get("x"), "y": payload.get("y")}
            try:
                site = (int(site_payload["x"]), int(site_payload["y"]))
            except (TypeError, ValueError, KeyError):
                return None
            current_state = dict(getattr(hypothesis, "current_state", {}) or {})
            target_state = dict(getattr(hypothesis, "target_state", {}) or {})
            hypothesis_family = str(getattr(hypothesis, "family", "") or "")
            max_plan_len = 32 if hypothesis_family in {"coverage", "reflection"} else 6
            proposed_plan = _bounded_plan_from_steps(
                getattr(hypothesis, "proposed_plan", []) or [],
                max_len=max_plan_len,
            )
            expected_goal_delta = float(getattr(hypothesis, "expected_goal_delta", 0.0) or 0.0)
            evidence = dict(getattr(hypothesis, "evidence", {}) or {})
            repair_id = str(choice.get("repair_id", "") or evidence.get("repair_id", "") or "")
            goal_link_id = str(choice.get("goal_link_id", "") or evidence.get("goal_link_id", "") or "")
            protected_plan_id = str(
                choice.get("protected_plan_id", "") or evidence.get("protected_plan_id", "") or ""
            )
            protected_plan_len = int(
                choice.get("protected_plan_len", 0)
                or evidence.get("protected_plan_len", 0)
                or len(proposed_plan)
                or 0
            )
            force_wrong_site = evidence.get("force_wrong_site_after_first_step")
            force_wrong_site = dict(force_wrong_site) if isinstance(force_wrong_site, Mapping) else {}
            force_stale_hash = str(evidence.get("force_required_current_state_hash", "") or "")
            candidate_kind = (
                "psa_state_variable_transition"
                if source_kind in ABSTRACTION_SOURCE_KINDS
                else "ledger_induced_transition"
            )
            candidate = {
                "kind": candidate_kind,
                "source_kind": source_kind,
                "llm_role": str(choice.get("llm_role", "") or getattr(hypothesis, "llm_role", "") or "none"),
                "llm_direct_action": bool(
                    choice.get("llm_direct_action", getattr(hypothesis, "llm_direct_action", False))
                ),
                "mechanic_state_type": str(current_state.get("mechanic_state_type", "") or candidate_kind),
                "goal_link_type": str(target_state.get("goal_link_type", "") or "visible_state_advance"),
                "site": [int(site[0]), int(site[1])],
                "action_name": _normalize_action_name(action_name),
                "score_delta": int(target_state.get("score_delta", 0) or 0),
                "goal_likelihood": float(getattr(hypothesis, "goal_link_confidence", 0.0) or 0.0),
                "objective_kind": "state_advance",
                "macro_goal_link": True,
                "pre_state_hash": str(current_state.get("pre_state_hash", "") or ""),
                "post_state_hash": str(target_state.get("post_state_hash", "") or ""),
                "expected_goal_delta": expected_goal_delta,
                "source_event_ids": list(getattr(hypothesis, "source_event_ids", ()) or ()),
                "repair_id": repair_id,
                "goal_link_id": goal_link_id,
                "protected_plan_id": protected_plan_id,
                "protected_plan_len": protected_plan_len,
                "protected_plan_step_index": int(choice.get("protected_plan_step_index", 0) or 0),
                "mechanic_family": hypothesis_family,
                "repair_control_mode": str(evidence.get("repair_control_mode", "") or ""),
                "force_wrong_site_after_first_step": force_wrong_site,
                "force_required_current_state_hash": force_stale_hash,
                "bounded_plan": proposed_plan,
                "bounded_plan_max_len": max_plan_len if proposed_plan else 1,
                "goal_linked_candidate": bool(expected_goal_delta > 0.0 and proposed_plan),
                "score_bearing_candidate": bool(int(target_state.get("score_delta", 0) or 0) > 0),
            }
            pending = self._pending_target_from_candidate(
                candidate,
                operator="click",
                action_name=_normalize_action_name(action_name),
                primitive_id="mechanic_hypothesis_cycle_executor",
                actor_pos=actor_pos,
            )
            if pending is not None:
                pending["macro_goal_link"] = True
                pending["objective_kind"] = "state_advance"
                pending["mechanic_hypothesis_id"] = str(choice.get("hypothesis_id", "") or "")
                pending["mechanic_hypothesis_posterior_key"] = str(choice.get("posterior_key", "") or "")
                pending["repair_id"] = repair_id
                pending["goal_link_id"] = goal_link_id
                pending["protected_plan_id"] = protected_plan_id
                pending["protected_plan_len"] = protected_plan_len
                pending["protected_plan_step_index"] = int(choice.get("protected_plan_step_index", 0) or 0)
                pending["repair_control_mode"] = str(evidence.get("repair_control_mode", "") or "")
                pending["force_wrong_site_after_first_step"] = force_wrong_site
                pending["force_required_current_state_hash"] = force_stale_hash
                pending["source_primitive_id"] = source_primitive
                pending["source_kind"] = source_kind
                pending["llm_role"] = str(choice.get("llm_role", "") or getattr(hypothesis, "llm_role", "") or "none")
                pending["llm_direct_action"] = bool(
                    choice.get("llm_direct_action", getattr(hypothesis, "llm_direct_action", False))
                )
            return pending
        if not isinstance(state, Mapping):
            state = None
        if state is None:
            # The normal cycle pending-target builder expects the reader state.
            # Reconstruct enough target data from the hypothesis to keep rod
            # bookkeeping generic and verifiable.
            current_state = dict(getattr(hypothesis, "current_state", {}) or {})
            target_state = dict(getattr(hypothesis, "target_state", {}) or {})
            state = {
                **current_state,
                **target_state,
                "mechanic_family": "cycle_state_constraint",
                "mechanic_state_type": str(current_state.get("mechanic_state_type", "cycle_hypothesis") or "cycle_hypothesis"),
                "goal_link_type": str(target_state.get("goal_link_type", "induced_goal_link") or "induced_goal_link"),
                "required_primitive_family": "cycle_operation_solver",
                "expected_goal_delta": float(getattr(hypothesis, "expected_goal_delta", 0.0) or 0.0),
                "reader_confidence": float(getattr(hypothesis, "effect_confidence", 0.0) or 0.0),
                "goal_link_confidence": float(getattr(hypothesis, "goal_link_confidence", 0.0) or 0.0),
            }
        pending = self._pending_target_from_cycle_constraint_step(
            primitive_id=source_primitive,
            state=state,
            action_name=action_name,
            action_payload=action_payload,
            actor_pos=actor_pos,
        )
        if pending is not None:
            pending["primitive_id"] = "mechanic_hypothesis_cycle_executor"
            pending["solver_family"] = _solver_family_for_primitive_id("mechanic_hypothesis_cycle_executor")
            pending["mechanic_hypothesis_id"] = str(choice.get("hypothesis_id", "") or "")
            pending["mechanic_hypothesis_posterior_key"] = str(choice.get("posterior_key", "") or "")
            pending["source_primitive_id"] = source_primitive
            pending["source_kind"] = source_kind or "reader_fixed"
            pending["llm_role"] = str(choice.get("llm_role", "") or getattr(hypothesis, "llm_role", "") or "none")
            pending["llm_direct_action"] = bool(
                choice.get("llm_direct_action", getattr(hypothesis, "llm_direct_action", False))
            )
        return pending

    def _pending_target_from_mechanic_goal_candidate_choice(
        self,
        choice: Mapping[str, Any],
        *,
        action_name: str,
        action_payload: Mapping[str, Any] | None,
        actor_pos: tuple[int, int] | None,
    ) -> dict[str, Any] | None:
        raw_candidate = choice.get("candidate")
        if not isinstance(raw_candidate, Mapping):
            return None
        site = _site_tuple(raw_candidate.get("site"))
        if site is None and isinstance(action_payload, Mapping):
            site = _site_tuple((action_payload.get("x"), action_payload.get("y")))
        if site is None:
            return None
