    def _pending_target_from_shape_coverage_state(
        self,
        state: Mapping[str, Any] | None,
        *,
        action_name: str,
        actor_pos: tuple[int, int] | None,
    ) -> dict[str, Any] | None:
        if state is None:
            return None
        active = dict(state.get("active_piece") or {})
        target = tuple(active.get("target_anchor") or ())
        current = tuple(active.get("pos") or ())
        site = target if len(target) >= 2 else current
        if len(site) < 2:
            return None
        candidate = {
            "kind": "shape_coverage_paste_target",
            "mechanic_state_type": "shape_coverage_paste",
            "goal_link_type": "same_color_shape_pixels_cover_target_markers",
            "site": [int(site[0]), int(site[1])],
            "action_name": _normalize_action_name(action_name),
            "score_delta": 0,
            "goal_likelihood": 0.66,
            "objective_kind": "state_advance",
            "macro_goal_link": True,
            "active_color": int(active.get("color", -1)),
            "current_pos": [int(current[0]), int(current[1])] if len(current) >= 2 else [],
            "target_anchor": [int(target[0]), int(target[1])] if len(target) >= 2 else [],
            "marker_count": int(active.get("marker_count", 0) or 0),
            "marker_color_count": int(state.get("marker_color_count", 0) or 0),
            "piece_count": int(state.get("piece_count", 0) or 0),
            "operation_plan_len": int(state.get("operation_plan_len", 0) or 0),
            "same_color_multi_piece_partition": bool(state.get("same_color_multi_piece_partition")),
            "precomputed_operation_plan_len": len(tuple(state.get("precomputed_operation_plan") or ())),
            "expected_goal_delta": float(state.get("expected_goal_delta", 0.0) or 0.0),
            "reader_confidence": float(state.get("reader_confidence", 0.0) or 0.0),
            "goal_link_confidence": float(state.get("goal_link_confidence", 0.0) or 0.0),
        }
        pending = self._pending_target_from_candidate(
            candidate,
            operator="route_to" if _normalize_action_name(action_name) in DIRECTIONAL_ACTIONS else "cycle",
            action_name=_normalize_action_name(action_name),
            primitive_id="shape_coverage_paste_solver",
            actor_pos=actor_pos,
        )
        if pending is not None:
            pending["macro_goal_link"] = True
            pending["objective_kind"] = "state_advance"
            pending["shape_coverage_descriptor_repair_posterior_key"] = str(
                state.get("descriptor_repair_posterior_key", "") or ""
            )
            retry_diagnostics = state.get("descriptor_repair_retry_diagnostics")
            if isinstance(retry_diagnostics, Mapping):
                validation_before = retry_diagnostics.get("validation_before")
                validation_after = retry_diagnostics.get("validation_after")
                feedback = state.get("descriptor_repair_feedback")
                feedback = feedback if isinstance(feedback, Mapping) else {}
                pending["shape_coverage_descriptor_repair_source_kind"] = str(
                    retry_diagnostics.get("source_kind", "") or ""
                )
                if isinstance(validation_before, Mapping):
                    pending["shape_coverage_descriptor_reject_reason"] = str(
                        validation_before.get("reject_reason", "") or ""
                    )
                    pending["shape_coverage_descriptor_hypothesis_id"] = str(
                        validation_before.get("hypothesis_id", "") or ""
                    )
                pending["shape_coverage_descriptor_abstraction_gap"] = str(
                    feedback.get("abstraction_gap", "") or ""
                )
                pending["shape_coverage_descriptor_repair_target"] = str(
                    retry_diagnostics.get("repair_target", "") or feedback.get("repair_target", "") or ""
                )
                if isinstance(validation_after, Mapping):
                    pending["shape_coverage_descriptor_repair_validation_after_accepted"] = bool(
                        validation_after.get("accepted", False)
                    )
        return pending

    def _pending_target_from_shape_recolor_coverage_state(
        self,
        state: Mapping[str, Any] | None,
        *,
        action_name: str,
        actor_pos: tuple[int, int] | None,
    ) -> dict[str, Any] | None:
        if state is None:
            return None
        tasks = [
            dict(task)
            for task in list(state.get("tasks") or [])
            if isinstance(task, Mapping)
        ]
        active_task = tasks[0] if tasks else {}
        target = tuple(active_task.get("target_anchor") or ())
        waypoint = tuple(active_task.get("recolor_waypoint") or ())
        site = waypoint if _normalize_action_name(action_name) in DIRECTIONAL_ACTIONS else target
        if len(site) < 2:
            site = target
        if len(site) < 2:
            return None
        candidate = {
            "kind": "shape_recolor_coverage_target",
            "mechanic_state_type": "shape_recolor_coverage",
            "goal_link_type": "palette_recolored_shape_pixels_cover_target_markers",
            "site": [int(site[0]), int(site[1])],
            "action_name": _normalize_action_name(action_name),
            "score_delta": 0,
            "goal_likelihood": 0.62,
            "objective_kind": "state_advance",
            "macro_goal_link": True,
            "marker_color_count": int(state.get("marker_color_count", 0) or 0),
            "piece_count": int(state.get("piece_count", 0) or 0),
            "operation_plan_len": int(state.get("operation_plan_len", 0) or 0),
            "expected_goal_delta": float(state.get("expected_goal_delta", 0.0) or 0.0),
            "reader_confidence": float(state.get("reader_confidence", 0.0) or 0.0),
            "goal_link_confidence": float(state.get("goal_link_confidence", 0.0) or 0.0),
        }
        pending = self._pending_target_from_candidate(
            candidate,
            operator="route_to" if _normalize_action_name(action_name) in DIRECTIONAL_ACTIONS else "cycle",
            action_name=_normalize_action_name(action_name),
            primitive_id="shape_recolor_coverage_solver",
            actor_pos=actor_pos,
        )
        if pending is not None:
            pending["macro_goal_link"] = True
            pending["objective_kind"] = "state_advance"
        return pending

    def _pending_target_from_coordinate_hypothesis_choice(
        self,
        choice: Mapping[str, Any],
        *,
        action_name: str,
        action_payload: Mapping[str, Any] | None,
        actor_pos: tuple[int, int] | None,
    ) -> dict[str, Any] | None:
        payload = dict(action_payload or {})
        site = choice.get("selected_site")
        if not isinstance(site, (list, tuple)) or len(site) < 2:
            site = [payload.get("x"), payload.get("y")]
        if not isinstance(site, (list, tuple)) or len(site) < 2:
            return None
        try:
            x, y = int(site[0]), int(site[1])
        except (TypeError, ValueError):
            return None
        hypothesis = dict(choice.get("hypothesis") or {})
        primitive_id = str(choice.get("primitive_id", "") or "coordinate_hypothesis_choice")
        candidate = {
            "kind": "coordinate_hypothesis_candidate",
            "mechanic_state_type": "coordinate_relation",
            "goal_link_type": str(hypothesis.get("goal_test", "") or "coordinate_relation_probe"),
            "site": [int(x), int(y)],
            "action_name": _normalize_action_name(action_name),
            "score_delta": 0,
            "goal_likelihood": float(hypothesis.get("confidence", 0.0) or 0.0),
            "objective_kind": "state_advance",
            "macro_goal_link": True,
            "coordinate_hypothesis": str(hypothesis.get("coordinate_hypothesis", "") or ""),
            "candidate_generation": str(hypothesis.get("candidate_generation", "") or ""),
            "candidate_count": int(choice.get("candidate_count", 0) or 0),
        }
        pending = self._pending_target_from_candidate(
            candidate,
            operator="click",
            action_name=_normalize_action_name(action_name),
            primitive_id=primitive_id,
            actor_pos=actor_pos,
        )
        if pending is not None:
            pending["macro_goal_link"] = True
            pending["objective_kind"] = "state_advance"
            if primitive_id == "coordinate_hypothesis_plan_lease":
                pending["source_kind"] = "coordinate_hypothesis_plan_lease"
            elif primitive_id == "coordinate_hypothesis_target_commitment":
                pending["source_kind"] = "coordinate_hypothesis_target_commitment"
            elif primitive_id == "coordinate_hypothesis_terminal_local_verifier":
                pending["source_kind"] = "coordinate_hypothesis_terminal_local_verifier"
            elif primitive_id == "coordinate_hypothesis_post_peak_replan":
                pending["source_kind"] = "coordinate_hypothesis_post_peak_replan"
            else:
                pending["source_kind"] = "coordinate_hypothesis"
            pending["llm_role"] = "coordinate_hypothesis_generation"
            pending["llm_direct_action"] = False
            pending["coordinate_plan_id"] = int(choice.get("coordinate_plan_id", 0) or 0)
            pending["coordinate_plan_step_index"] = int(
                choice.get("coordinate_plan_step_index", 0) or 0
            )
            pending["coordinate_plan_remaining_after"] = _int_or_default(
                choice.get("coordinate_plan_remaining_after"),
                -1,
            )
            pending["coordinate_target_key"] = str(choice.get("coordinate_target_key", "") or "")
            pending["coordinate_target_keys"] = [
                str(key or "")
                for key in list(choice.get("coordinate_target_keys") or [])
                if str(key or "")
            ]
            pending["target_commitment_preconditioning_structured_fallback_applied"] = bool(
                choice.get("target_commitment_preconditioning_structured_fallback_applied")
            )
            pending[
                "target_commitment_preconditioning_structured_fallback_selected_target_key"
            ] = str(
                choice.get(
                    "target_commitment_preconditioning_structured_fallback_selected_target_key",
                    "",
                )
                or ""
            )
            pending["target_commitment_preconditioning_structured_fallback_single_piece"] = bool(
                choice.get("target_commitment_preconditioning_structured_fallback_single_piece")
            )
            pending["single_piece_target_family_outcome_probe_applied"] = bool(
                choice.get("single_piece_target_family_outcome_probe_applied")
            )
            pending["single_piece_target_family_outcome_probe_route_key"] = str(
                choice.get("single_piece_target_family_outcome_probe_route_key", "")
                or ""
            )
            pending["single_piece_target_family_outcome_probe_route_sites"] = [
                [int(site[0]), int(site[1])]
                for site in list(
                    choice.get("single_piece_target_family_outcome_probe_route_sites")
                    or []
                )
                if isinstance(site, (list, tuple)) and len(site) >= 2
            ]
            pending["terminal_completion_best_incomplete_fallback_applied"] = bool(
                choice.get("terminal_completion_best_incomplete_fallback_applied")
            )
            pending[
                "terminal_completion_best_incomplete_fallback_application_count_after"
            ] = int(
                choice.get(
                    "terminal_completion_best_incomplete_fallback_application_count_after",
                    0,
                )
                or 0
            )
            pending[
                "terminal_completion_best_incomplete_fallback_provider_cooldown_started"
            ] = bool(
                choice.get(
                    "terminal_completion_best_incomplete_fallback_provider_cooldown_started"
                )
            )
            pending[
                "terminal_completion_best_incomplete_fallback_provider_cooldown_steps"
            ] = int(
                choice.get(
                    "terminal_completion_best_incomplete_fallback_provider_cooldown_steps",
                    0,
                )
                or 0
            )
            pending["terminal_self_overlap_detour_used"] = bool(
                choice.get("terminal_self_overlap_detour_used")
            )
            pending["terminal_self_overlap_detour_count"] = int(
                choice.get("terminal_self_overlap_detour_count", 0) or 0
            )
            pending["terminal_self_overlap_detour"] = dict(
                choice.get("terminal_self_overlap_detour") or {}
            )
            pending["target_commitment_single_no_score_alternative_probe_applied"] = bool(
                choice.get("target_commitment_single_no_score_alternative_probe_applied")
            )
            pending["target_commitment_single_no_score_alternative_probe"] = dict(
                choice.get("target_commitment_single_no_score_alternative_probe") or {}
            )
            observation = choice.get("target_commitment_preconditioning_observation")
            if isinstance(observation, Mapping):
                pending["target_commitment_preconditioning_observation"] = dict(
                    observation
                )
        return pending

