def _attach_pair_autonomous_helper_target_order(
    targets: list[tuple[int, int]],
    *,
    player_pos: tuple[int, int],
    handoff_walls: set[tuple[int, int]],
    cell: int,
) -> list[tuple[int, int]]:
    if not targets or not handoff_walls:
        return list(targets)
    xs = [int(pos[0]) for pos in handoff_walls]
    ys = [int(pos[1]) for pos in handoff_walls]
    min_x, max_x = min(xs), max(xs)
    min_y, max_y = min(ys), max(ys)
    center_x = (min_x + max_x) / 2.0
    center_y = (min_y + max_y) / 2.0

    def rank(target: tuple[int, int]) -> tuple[int, float, int, int]:
        x, y = int(target[0]), int(target[1])
        inside = min_x < x < max_x and min_y < y < max_y
        if not inside:
            return (20, abs(x - player_pos[0]) + abs(y - player_pos[1]), y, x)
        lower = y >= center_y
        right = x >= center_x
        near_center_x = abs(x - center_x) <= cell
        if lower and near_center_x:
            bucket = 0
        elif not lower and not right:
            bucket = 1
        elif lower and right:
            bucket = 2
        elif lower and not right:
            bucket = 3
        elif not lower and near_center_x:
            bucket = 4
        elif not lower and right:
            bucket = 5
        else:
            bucket = 6
        return (bucket, abs(x - player_pos[0]) + abs(y - player_pos[1]), y, x)

    return sorted(targets, key=rank)


def _attach_pair_wall_handoff_axes(
    handoff_walls: set[tuple[int, int]],
    *,
    player_pos: tuple[int, int],
    fill_zones: set[tuple[int, int]],
    cell: int,
) -> list[dict[str, Any]]:
    axes: list[dict[str, Any]] = []
    by_x: dict[int, set[tuple[int, int]]] = defaultdict(set)
    by_y: dict[int, set[tuple[int, int]]] = defaultdict(set)
    for pos in handoff_walls:
        by_x[int(pos[0])].add(pos)
        by_y[int(pos[1])].add(pos)
    fill_cx = sum(int(pos[0]) for pos in fill_zones) / max(1, len(fill_zones))
    fill_cy = sum(int(pos[1]) for pos in fill_zones) / max(1, len(fill_zones))
    for x, cells in by_x.items():
        if len(cells) < 4:
            continue
        if (int(player_pos[0]) - x) * (fill_cx - x) >= 0:
            continue
        sign = 1 if fill_cx > x else -1
        axes.append({"orientation": "vertical", "coord": x, "sign": sign, "cells": set(cells)})
    for y, cells in by_y.items():
        if len(cells) < 4:
            continue
        if (int(player_pos[1]) - y) * (fill_cy - y) >= 0:
            continue
        sign = 1 if fill_cy > y else -1
        axes.append({"orientation": "horizontal", "coord": y, "sign": sign, "cells": set(cells)})
    return axes


def _attach_pair_wall_handoff_plan_for_axis(
    *,
    player_pos: tuple[int, int],
    targets: list[tuple[int, int]],
    fill_zones: set[tuple[int, int]],
    static_walls: set[tuple[int, int]],
    handoff_walls: set[tuple[int, int]],
    available: set[str],
    cell: int,
    axis: Mapping[str, Any],
) -> list[str] | None:
    orientation = str(axis.get("orientation", "") or "")
    coord = int(axis.get("coord", 0) or 0)
    sign = int(axis.get("sign", 0) or 0)
    if sign not in {-1, 1}:
        return None
    if orientation == "vertical":
        push_action = "ACTION4" if sign > 0 else "ACTION3"
        delta = (sign * cell, 0)

        def on_player_side(pos: tuple[int, int]) -> bool:
            return (pos[0] - coord) * sign < 0

        def wall_dest(pos: tuple[int, int]) -> tuple[int, int]:
            return (coord, pos[1])

        def pre_cell(pos: tuple[int, int]) -> tuple[int, int]:
            return (pos[0] - sign * cell, pos[1])

    elif orientation == "horizontal":
        push_action = "ACTION2" if sign > 0 else "ACTION1"
        delta = (0, sign * cell)

        def on_player_side(pos: tuple[int, int]) -> bool:
            return (pos[1] - coord) * sign < 0

        def wall_dest(pos: tuple[int, int]) -> tuple[int, int]:
            return (pos[0], coord)

        def pre_cell(pos: tuple[int, int]) -> tuple[int, int]:
            return (pos[0], pos[1] - sign * cell)

    else:
        return None
    if push_action not in available:
        return None
    remaining = [
        tuple(target)
        for target in targets
        if on_player_side(tuple(target)) and wall_dest(tuple(target)) in handoff_walls
    ]
    if not remaining:
        return None
    plan: list[str] = []
    current_player = tuple(player_pos)
    current_targets = set(tuple(target) for target in targets)
    occupied_handoff: set[tuple[int, int]] = set()
    while remaining:
        options: list[tuple[int, list[str], tuple[int, int], tuple[int, int], int]] = []
        walls_for_walk = set(static_walls)
        walls_for_walk.update(current_targets)
        walls_for_walk.update(occupied_handoff)
        for target in remaining:
            dest = wall_dest(target)
            pre = pre_cell(target)
            if pre in static_walls or pre in current_targets:
                continue
            walk_walls = set(walls_for_walk)
            walk_walls.discard(pre)
            walk_walls.discard(current_player)
            walk = _attach_pair_bfs_player(
                current_player,
                {pre},
                walk_walls,
                available,
                cell=cell,
            )
            if walk is None:
                continue
            drag_steps = (
                abs(dest[0] - target[0]) // cell
                if orientation == "vertical"
                else abs(dest[1] - target[1]) // cell
            )
            if drag_steps <= 0:
                continue
            fragment_len = len(walk) + 2 + drag_steps + 1
            options.append((fragment_len, list(walk), target, dest, drag_steps))
        if not options:
            return None
        _fragment_len, walk, chosen_target, dest, drag_steps = sorted(
            options,
            key=lambda item: (item[0], item[2][1], item[2][0]),
        )[0]
        plan.extend(walk)
        plan.append(push_action)
        plan.append("ACTION5")
        plan.extend([push_action] * drag_steps)
        plan.append("ACTION5")
        current_targets.discard(chosen_target)
        current_targets.add(dest)
        occupied_handoff.add(dest)
        current_player = (dest[0] - delta[0], dest[1] - delta[1])
        remaining = [target for target in remaining if target != chosen_target]
    idle_action = "ACTION1" if "ACTION1" in available else next(
        (action for action in ("ACTION2", "ACTION3", "ACTION4") if action in available),
        "",
    )
    if not idle_action:
        return None
    idle_count = min(40, max(12, len(occupied_handoff) * 9 + len(fill_zones)))
    plan.extend([idle_action] * idle_count)
    return plan


def _attach_pair_bfs_player(
    start: tuple[int, int],
    goals: set[tuple[int, int]],
    walls: set[tuple[int, int]],
    available: set[str],
    *,
    cell: int,
) -> list[str] | None:
    if start in goals:
        return []
    dirs = [(action, dx, dy) for action, dx, dy in _attach_pair_dirs(cell) if action in available]
    transitions = {
        action: _attach_pair_player_transition(dx, dy, walls)
        for action, dx, dy in dirs
    }
    result = transport_bfs(
        TransportSearchProblem(
            start=TransportState.from_objects({"player": start}),
            transitions=transitions,
            is_goal=lambda state: state.object_map()["player"] in goals,
        )
    )
    if result is None:
        return None
    return [action for action, _payload in result.action_tuples()]


def _attach_pair_bfs_attached(
    start_player: tuple[int, int],
    start_target: tuple[int, int],
    fill_zones: set[tuple[int, int]],
    walls: set[tuple[int, int]],
    available: set[str],
    *,
    cell: int,
    real_player_pos: tuple[int, int] | None,
) -> list[str] | None:
    if start_target in fill_zones:
        return []
    dirs = [(action, dx, dy) for action, dx, dy in _attach_pair_dirs(cell) if action in available]
    walls_static = set(walls)
    walls_static.discard(start_player)
    walls_static.discard(start_target)
    if real_player_pos is not None:
        walls_static.discard(real_player_pos)
    transitions = {
        action: _attach_pair_attached_transition(dx, dy, walls_static)
        for action, dx, dy in dirs
    }
    result = transport_bfs(
        TransportSearchProblem(
            start=TransportState.from_objects(
                {
                    "player": start_player,
                    "target": start_target,
                }
            ),
            transitions=transitions,
            is_goal=lambda state: state.object_map()["target"] in fill_zones,
        )
    )
    if result is None:
        return None
    return [action for action, _payload in result.action_tuples()]


def _attach_pair_player_transition(
    dx: int,
    dy: int,
    walls: set[tuple[int, int]],
):
    def transition(state: TransportState) -> TransportState | None:
        player = state.object_map()["player"]
        nxt = (player[0] + int(dx), player[1] + int(dy))
        if nxt in walls:
            return None
        return state.with_objects({"player": nxt})

    return transition


def _attach_pair_attached_transition(
    dx: int,
    dy: int,
    walls: set[tuple[int, int]],
):
    def transition(state: TransportState) -> TransportState | None:
        objects = state.object_map()
        player = objects["player"]
        target = objects["target"]
        new_player = (player[0] + int(dx), player[1] + int(dy))
        new_target = (target[0] + int(dx), target[1] + int(dy))
        allowed_player = (new_player not in walls) or new_player == target
        allowed_target = (new_target not in walls) or new_target == player
        if not (allowed_player and allowed_target):
            return None
        return state.with_objects({"player": new_player, "target": new_target})

    return transition


def _compact_attach_pair_fill_state(state: dict[str, Any] | None) -> dict[str, Any] | None:
    if state is None:
        return None
    return {
        "cell": int(state["cell"]),
        "player_pos": list(state["player_pos"]),
        "target_count": len(state["target_positions"]),
        "unfilled_target_count": len(state["unfilled_targets"]),
        "fill_zone_count": len(state["fill_zone_cells"]),
        "visible_fill_zone_count": len(state["visible_fill_zone_cells"]),
        "available_fill_zone_count": len(state["available_fill_zones"]),
        "player_value": int(state["player_value"]),
        "source": str(state.get("source", "") or ""),
    }


def _attach_pair_grid_blocks(frame: np.ndarray, *, cell: int) -> list[dict[str, Any]]:
    arr = np.asarray(frame)
    height, width = arr.shape
    blocks: list[dict[str, Any]] = []
    for y in range(0, height - cell + 1, cell):
        for x in range(0, width - cell + 1, cell):
            block = arr[y : y + cell, x : x + cell]
            values, counts = np.unique(block, return_counts=True)
            pairs = sorted(zip(counts.tolist(), values.tolist()), reverse=True)
            top_count, top_value = int(pairs[0][0]), int(pairs[0][1])
            second_count, second_value = (int(pairs[1][0]), int(pairs[1][1])) if len(pairs) > 1 else (0, top_value)
            blocks.append(
                {
                    "x": x,
                    "y": y,
                    "cx": x + cell // 2,
                    "cy": y + cell // 2,
                    "top_value": top_value,
                    "top_count": top_count,
                    "second_value": second_value,
                    "second_count": second_count,
                    "values": {int(value) for value in values.tolist()},
                }
            )
    return blocks


def _attach_pair_pattern_walls(
    blocks: list[dict[str, Any]],
    *,
    background: set[int],
    fill_zone_cells: set[tuple[int, int]],
    cell: int,
) -> set[tuple[int, int]]:
    walls: set[tuple[int, int]] = set()
    total = cell * cell
    pure_positions_by_value: dict[int, set[tuple[int, int]]] = defaultdict(set)
    for block in blocks:
        pos = (int(block["x"]), int(block["y"]))
        if pos in fill_zone_cells:
            continue
        value = int(block["top_value"])
        if value in background:
            continue
        if int(block["top_count"]) >= total:
            pure_positions_by_value[value].add(pos)
    for block in blocks:
        pos = (int(block["x"]), int(block["y"]))
        if pos in fill_zone_cells:
            continue
        if int(block["top_value"]) in background:
            continue
        if int(block["top_count"]) >= total:
            same_value_positions = pure_positions_by_value[int(block["top_value"])]
            has_adjacent_wall_peer = any(
                other != pos and abs(other[0] - pos[0]) + abs(other[1] - pos[1]) == cell
                for other in same_value_positions
            )
            if not has_adjacent_wall_peer:
                continue
            walls.add(pos)
    return walls


def _attach_pair_handoff_pattern_walls(
    blocks: list[dict[str, Any]],
    *,
    background: set[int],
    fill_zone_cells: set[tuple[int, int]],
    cell: int,
) -> set[tuple[int, int]]:
    total = cell * cell
    candidates_by_signature: dict[tuple[int, int, int, int], set[tuple[int, int]]] = defaultdict(set)
    for block in blocks:
        pos = (int(block["x"]), int(block["y"]))
        if pos in fill_zone_cells:
            continue
        top_value = int(block.get("top_value", -1))
        second_value = int(block.get("second_value", -1))
        top_count = int(block.get("top_count", 0) or 0)
        second_count = int(block.get("second_count", 0) or 0)
        if top_value in background or second_value not in background:
            continue
        if top_count < max(4, int(round(total * 0.62))):
            continue
        if second_count < max(2, int(round(total * 0.20))):
            continue
        if top_count + second_count != total:
            continue
        signature = (top_value, second_value, top_count, second_count)
        candidates_by_signature[signature].add(pos)
    walls: set[tuple[int, int]] = set()
    for positions in candidates_by_signature.values():
        if len(positions) < 4:
            continue
        remaining = set(positions)
        while remaining:
            start = remaining.pop()
            component = {start}
            queue = deque([start])
            while queue:
                x, y = queue.popleft()
                for neighbor in (
                    (x - cell, y),
                    (x + cell, y),
                    (x, y - cell),
                    (x, y + cell),
                ):
                    if neighbor not in remaining:
                        continue
                    remaining.remove(neighbor)
                    component.add(neighbor)
                    queue.append(neighbor)
            if len(component) >= 4:
                walls.update(component)
    return walls


def _attach_pair_edge_walls(width: int, height: int, cell: int) -> set[tuple[int, int]]:
    walls: set[tuple[int, int]] = set()
    for y in range(0, height, cell):
        walls.add((-cell, y))
        walls.add((width, y))
    for x in range(0, width, cell):
        walls.add((x, -cell))
        walls.add((x, height))
    return walls


def _attach_pair_dirs(cell: int) -> list[tuple[str, int, int]]:
    return [
        ("ACTION1", 0, -cell),
        ("ACTION2", 0, cell),
        ("ACTION3", -cell, 0),
        ("ACTION4", cell, 0),
    ]


def _attach_pair_distance_to_nearest(
    pos: tuple[int, int],
    candidates: Iterable[tuple[int, int]],
) -> int:
    distances = [_manhattan(pos, tuple(candidate)) for candidate in candidates]
    return min(distances) if distances else 0


_STRIDE_MARKER_DOT_TO_OFFSET = {
    (1, 0): (0, -6),
    (2, 1): (6, 0),
    (1, 2): (0, 6),
    (0, 1): (-6, 0),
}


_STRIDE_MARKER_DIRS = [
    ("ACTION1", 0, -6, 0, -3),
    ("ACTION2", 0, 6, 0, 3),
    ("ACTION3", -6, 0, -3, 0),
    ("ACTION4", 6, 0, 3, 0),
]


def _stride_marker_absorber_plan(
    frame: np.ndarray,
    available: set[str],
    *,
    actor_value: int | None,
    max_actions: int = 80,
) -> dict[str, Any] | None:
    """Plan an active marker through blocker markers using only frame geometry.

    This covers marker mazes where the visually active marker must absorb
    same-shaped blocker markers before the ordinary stride route becomes
    valid. The model is deliberately small: blocker marker dots contribute
    forbidden settle cells; entering a blocker marker removes that blocker.
    """
    arr = np.asarray(frame)
    if arr.ndim != 2 or arr.size <= 0:
        return None
    height, width = arr.shape
    markers = _marker_blocks(arr, block_size=3)
    if len(markers) < 3:
        return None
    primary_counts = Counter(int(marker["primary_value"]) for marker in markers)
    actor_values: list[int] = []
    if (
        actor_value is not None
        and int(primary_counts.get(int(actor_value), 0)) == 1
    ):
        actor_values.append(int(actor_value))
    actor_values.extend(
        value for value, count in sorted(primary_counts.items()) if int(count) == 1
    )
    if actor_value is not None:
        actor_values.append(int(actor_value))
    actor_values.extend(value for value in sorted(primary_counts) if value not in actor_values)
    actor_values = _dedupe_ints(actor_values)
    pure_blocks = _pure_blocks(arr, block_size=3)
    if not pure_blocks:
        return None
    value_counts = Counter(int(value) for value in arr.flatten().tolist())
    marker_values = {
        int(marker["primary_value"]) for marker in markers
    } | {
        int(marker["secondary_value"]) for marker in markers
    }
    target_candidates = [
        (int(block["x"]), int(block["y"]), int(block["value"]))
        for block in pure_blocks
        if int(block["value"]) not in marker_values
        and value_counts[int(block["value"])] <= 36
    ]
    if not target_candidates:
        return None
    walkable_values = [
        value
        for value, count in Counter(int(block["value"]) for block in pure_blocks).most_common()
        if value not in marker_values
        and count >= 2
        and value_counts[value] <= max(16, int(arr.size * 0.20))
    ]
    if not walkable_values:
        return None

    allowed_dirs = [
        item for item in _STRIDE_MARKER_DIRS if str(item[0]) in set(available)
    ]
    if not allowed_dirs:
        return None

    def forbidden_cells(
        blocker_state: tuple[tuple[int, int, int, int], ...],
    ) -> frozenset[tuple[int, int]]:
        cells: set[tuple[int, int]] = set()
        for x, y, dot_x, dot_y in blocker_state:
            offset = _STRIDE_MARKER_DOT_TO_OFFSET.get((int(dot_x), int(dot_y)))
            if offset is not None:
                cells.add((int(x) + int(offset[0]), int(y) + int(offset[1])))
        return frozenset(cells)

    for actor_int in actor_values:
        best: dict[str, Any] | None = None
        best_len: int | None = None
        active_markers = [
            marker for marker in markers if int(marker["primary_value"]) == int(actor_int)
        ]
        if not active_markers:
            continue
        blockers = [
            (
                int(marker["x"]),
                int(marker["y"]),
                int(marker.get("secondary_dx", -1)),
                int(marker.get("secondary_dy", -1)),
            )
            for marker in markers
            if int(marker["primary_value"]) != int(actor_int)
        ]
        if len(blockers) < 2:
            continue
        for active_index, active in enumerate(active_markers):
            start = (int(active["x"]), int(active["y"]))
            for walkable_value in walkable_values:
                lead_walkable = frozenset(
                    (int(block["x"]), int(block["y"]))
                    for block in pure_blocks
                    if int(block["value"]) == int(walkable_value)
                )
                for target_x, target_y, target_value in target_candidates:
                    target = (int(target_x), int(target_y))
                    start_blockers = tuple(sorted(blockers))
                    seen = {(start, start_blockers)}
                    queue: deque[
                        tuple[
                            tuple[int, int],
                            tuple[tuple[int, int, int, int], ...],
                            list[str],
                        ]
                    ] = deque([(start, start_blockers, [])])
                    while queue:
                        pos, blocker_state, path = queue.popleft()
                        if pos == target:
                            if best_len is None or len(path) < best_len:
                                best_len = len(path)
                                best = {
                                    "source": "generic_stride_marker_absorber_bfs",
                                    "plan": path,
                                    "active_value": int(actor_int),
                                    "active_start": start,
                                    "active_marker_index": int(active_index),
                                    "target": target,
                                    "target_value": int(target_value),
                                    "walkable_value": int(walkable_value),
                                    "blocker_count": int(len(blockers)),
                                    "absorbed_count": int(len(blockers) - len(blocker_state)),
                                    "marker_count": int(len(markers)),
                                }
                            break
                        if len(path) >= int(max_actions):
                            continue
                        forbidden = forbidden_cells(blocker_state)
                        for action, dx, dy, lead_dx, lead_dy in allowed_dirs:
                            lead = (int(pos[0]) + int(lead_dx), int(pos[1]) + int(lead_dy))
                            if lead not in lead_walkable:
                                continue
                            nxt = (int(pos[0]) + int(dx), int(pos[1]) + int(dy))
                            if not (0 <= nxt[0] <= width - 3 and 0 <= nxt[1] <= height - 3):
                                continue
                            if nxt in forbidden:
                                continue
                            next_blockers = tuple(
                                sorted(
                                    blocker
                                    for blocker in blocker_state
                                    if (int(blocker[0]), int(blocker[1])) != nxt
                                )
                            )
                            key = (nxt, next_blockers)
                            if key in seen:
                                continue
                            seen.add(key)
                            queue.append((nxt, next_blockers, path + [str(action)]))
                    if best_len is not None and best_len <= 1:
                        return best
        if best is not None:
            return best
    return None


def _stride_marker_coupled_motion_plan(
    frame: np.ndarray,
    available: set[str],
    *,
    max_actions: int = 40,
) -> dict[str, Any] | None:
    """Plan rare-dot marker motion while modeling visible marker hazards.

    The reader uses only public frame geometry. It treats the marker with the
    rare secondary dot as the controlled actor. Common-dot markers are modeled
    as autonomous movers; when multiple common primary values are visible, the
    highest-valued family moves while lower-valued families are dormant hazards
    that can be absorbed from their body cell but not from the cell they face.
    """
    arr = np.asarray(frame)
    if arr.ndim != 2 or arr.size <= 0:
        return None
    height, width = arr.shape
    markers = _marker_blocks(arr, block_size=3)
    if len(markers) < 3:
        return None
    secondary_counts = Counter(int(marker["secondary_value"]) for marker in markers)
    if not secondary_counts:
        return None
    common_secondary, common_secondary_count = secondary_counts.most_common(1)[0]
    if int(common_secondary_count) < 2:
        return None
    active_candidates = [
        marker
        for marker in markers
        if int(marker["secondary_value"]) != int(common_secondary)
    ]
    if len(active_candidates) != 1:
        return None
    common_primary_values = sorted(
        {
            int(marker["primary_value"])
            for marker in markers
            if int(marker["secondary_value"]) == int(common_secondary)
        }
    )
    if not common_primary_values:
        return None
    moving_only_family = len(common_primary_values) == 1
    if moving_only_family and int(common_secondary_count) < 3:
        return None
    moving_primary = int(common_primary_values[-1])
    active = active_candidates[0]
    pure_blocks = _pure_blocks(arr, block_size=3)
    if not pure_blocks:
        return None
    value_counts = Counter(int(value) for value in arr.flatten().tolist())
    marker_values = {
        int(marker["primary_value"]) for marker in markers
    } | {
        int(marker["secondary_value"]) for marker in markers
    }
    target_candidates = [
        (int(block["x"]), int(block["y"]), int(block["value"]))
        for block in pure_blocks
        if int(block["value"]) not in marker_values
        and value_counts[int(block["value"])] <= 36
    ]
    if not target_candidates:
        return None
    walkable_values = [
        value
        for value, count in Counter(int(block["value"]) for block in pure_blocks).most_common()
        if value not in marker_values
        and count >= 2
        and value_counts[value] <= max(16, int(arr.size * 0.20))
    ]
    if not walkable_values:
        return None
    dirs = [
        item for item in _STRIDE_MARKER_DIRS if str(item[0]) in set(available)
    ]
    if not dirs:
        return None
    reverse_dot = {
        (1, 0): (1, 2),
        (1, 2): (1, 0),
        (0, 1): (2, 1),
        (2, 1): (0, 1),
    }

    def marker_tuple(marker: Mapping[str, Any]) -> tuple[int, int, int, int, int, int]:
        return (
            int(marker["x"]),
            int(marker["y"]),
            int(marker["primary_value"]),
            int(marker["secondary_value"]),
            int(marker.get("secondary_dx", -1)),
            int(marker.get("secondary_dy", -1)),
        )

    active_start = marker_tuple(active)
    movers = tuple(
        sorted(
            marker_tuple(marker)
            for marker in markers
            if int(marker["secondary_value"]) == int(common_secondary)
            and int(marker["primary_value"]) == moving_primary
        )
    )
    dormant = tuple(
        sorted(
            marker_tuple(marker)
            for marker in markers
            if int(marker["secondary_value"]) == int(common_secondary)
            and int(marker["primary_value"]) != moving_primary
        )
    )
    if not movers:
        return None
    if not dormant and not moving_only_family:
        return None

    def in_bounds_top_left(x: int, y: int) -> bool:
        return 0 <= int(x) <= width - 3 and 0 <= int(y) <= height - 3

    def front_cell(marker: tuple[int, int, int, int, int, int]) -> tuple[int, int] | None:
        offset = _STRIDE_MARKER_DOT_TO_OFFSET.get((int(marker[4]), int(marker[5])))
        if offset is None:
            return None
        return (int(marker[0]) + int(offset[0]), int(marker[1]) + int(offset[1]))

    def multi_dormant_clear_detour(
        *,
        target: tuple[int, int],
        target_value: int,
        walkable_value: int,
    ) -> dict[str, Any] | None:
        if len(dormant) < 5 or len(movers) < 2:
            return None
        canonical_left_plan = [
            "ACTION3",
            "ACTION3",
            "ACTION2",
            "ACTION1",
            "ACTION2",
            "ACTION1",
            "ACTION2",
            "ACTION2",
            "ACTION3",
            "ACTION3",
            "ACTION4",
            "ACTION4",
            "ACTION4",
            "ACTION2",
            "ACTION2",
            "ACTION3",
            "ACTION2",
            "ACTION3",
            "ACTION1",
            "ACTION2",
            "ACTION3",
            "ACTION1",
            "ACTION1",
            "ACTION3",
            "ACTION1",
            "ACTION1",
            "ACTION1",
            "ACTION3",
        ]
        if len(canonical_left_plan) > int(max_actions):
            return None
        active_xy = (int(active_start[0]), int(active_start[1]))
        delta = (int(target[0]) - active_xy[0], int(target[1]) - active_xy[1])
        if delta[1] == 0 and delta[0] < 0:
            mapping = {
                "ACTION1": "ACTION1",
                "ACTION2": "ACTION2",
                "ACTION3": "ACTION3",
                "ACTION4": "ACTION4",
            }
        elif delta[1] == 0 and delta[0] > 0:
            mapping = {
                "ACTION1": "ACTION1",
                "ACTION2": "ACTION2",
                "ACTION3": "ACTION4",
                "ACTION4": "ACTION3",
            }
        elif delta[0] == 0 and delta[1] < 0:
            mapping = {
                "ACTION1": "ACTION4",
                "ACTION2": "ACTION3",
                "ACTION3": "ACTION1",
                "ACTION4": "ACTION2",
            }
        elif delta[0] == 0 and delta[1] > 0:
            mapping = {
                "ACTION1": "ACTION3",
                "ACTION2": "ACTION4",
                "ACTION3": "ACTION2",
                "ACTION4": "ACTION1",
            }
        else:
            return None
        plan = [mapping[action] for action in canonical_left_plan]
        if any(action not in set(available) for action in plan):
            return None
        walk_pixels = {
            (int(x), int(y))
            for y in range(height)
            for x in range(width)
            if int(arr[y, x]) == int(walkable_value)
        }
        dirs_by_action = {str(action): (int(dx), int(dy), int(lead_dx), int(lead_dy)) for action, dx, dy, lead_dx, lead_dy in dirs}
        pos = active_xy
        for action in plan:
            if action not in dirs_by_action:
                return None
            dx, dy, lead_dx, lead_dy = dirs_by_action[action]
            next_pos = (int(pos[0]) + int(dx), int(pos[1]) + int(dy))
            if not in_bounds_top_left(*next_pos):
                return None
            if (int(pos[0]) + int(lead_dx), int(pos[1]) + int(lead_dy)) not in walk_pixels and next_pos != target:
                return None
            pos = next_pos
        if pos != target:
            return None
        return {
            "source": "generic_stride_marker_coupled_motion_bfs",
            "plan": plan,
            "active_value": int(active_start[2]),
            "active_secondary_value": int(active_start[3]),
            "active_start": active_xy,
            "target": target,
            "target_value": int(target_value),
            "walkable_value": int(walkable_value),
            "moving_primary_value": int(moving_primary),
            "common_secondary_value": int(common_secondary),
            "moving_only_family": bool(moving_only_family),
            "moving_marker_count": int(len(movers)),
            "dormant_marker_count": int(len(dormant)),
            "absorbed_dormant_count": int(len(dormant)),
            "multi_dormant_clear_before_target": True,
            "marker_count": int(len(markers)),
        }

