def _shape_recolor_wall_morph_coverage_state(
    frame: np.ndarray,
    *,
    background_value: int,
    marker_groups: Mapping[int, Sequence[tuple[int, int]]],
    ring_values: set[int],
    marker_colors: set[int],
    selector_values: set[int],
) -> dict[str, Any] | None:
    arr = np.asarray(frame)
    if arr.ndim != 2 or len(marker_groups) < 2:
        return None
    pieces = _shape_wall_morph_pieces_from_frame(
        arr,
        marker_colors=marker_colors,
        selector_values=selector_values,
    )
    if len(pieces) != len(marker_groups):
        return None
    if sum(1 for piece in pieces if bool(piece.get("active"))) != 1:
        return None
    obstacles = _shape_wall_morph_obstacles_from_frame(
        arr,
        background_value=background_value,
        marker_colors=marker_colors,
        ring_values=ring_values,
        selector_values=selector_values,
    )
    if not obstacles:
        return None
    planned = _shape_wall_morph_multi_piece_plan(
        pieces,
        obstacles=obstacles,
        marker_groups=marker_groups,
        frame_shape=arr.shape,
    )
    if planned is None:
        return None
    plan, tasks = planned
    if not plan:
        return None
    marker_count = sum(len(tuple(group)) for group in marker_groups.values())
    return {
        "mechanic_state_type": "shape_recolor_coverage",
        "goal_link_type": "wall_morphed_shape_pixels_cover_target_markers",
        "background_value": int(background_value),
        "ring_value": int(next(iter(ring_values))) if len(ring_values) == 1 else -1,
        "marker_count": int(marker_count),
        "marker_color_count": int(len(marker_groups)),
        "piece_count": int(len(pieces)),
        "palette_pad_count": 0,
        "tasks": tasks,
        "active_piece": dict(tasks[0]) if tasks else {},
        "pieces": [_shape_wall_morph_public_piece(piece) for piece in pieces],
        "wall_morph_shape_coverage": True,
        "precomputed_operation_plan": tuple(plan),
        "operation_plan": tuple(plan),
        "operation_plan_len": int(len(plan)),
        "expected_goal_delta": 1.0,
        "reader_confidence": 0.58,
        "goal_link_confidence": 0.58,
    }


def _shape_wall_morph_pieces_from_frame(
    frame: np.ndarray,
    *,
    marker_colors: set[int],
    selector_values: set[int],
) -> list[dict[str, Any]]:
    arr = np.asarray(frame)
    selector_positions = [
        (int(x), int(y))
        for selector in selector_values
        for y, x in np.argwhere(arr == int(selector)).tolist()
    ]
    pieces: list[dict[str, Any]] = []
    for color in sorted(int(value) for value in marker_colors):
        comps = _shape_coverage_mask_components(
            arr,
            arr == int(color),
            color=int(color),
            selector_values=set(),
        )
        for comp in comps:
            if int(comp.get("color_area", 0) or 0) < 8:
                continue
            width = int(comp.get("width", 0) or 0)
            height = int(comp.get("height", 0) or 0)
            if width < 6 or height < 6:
                continue
            min_x = int(comp["min_x"])
            min_y = int(comp["min_y"])
            pixels = np.full((height, width), -1, dtype=np.int16)
            for ox, oy in tuple(comp.get("color_offsets") or ()):
                pixels[int(oy), int(ox)] = int(color)
            selector_inside = [
                (sx, sy)
                for sx, sy in selector_positions
                if min_x <= sx <= int(comp["max_x"]) and min_y <= sy <= int(comp["max_y"])
            ]
            active = bool(selector_inside)
            if active:
                sx, sy = selector_inside[0]
                pixels[int(sy) - min_y, int(sx) - min_x] = 0
            kind = _shape_wall_morph_piece_kind(pixels)
            if kind == "unknown":
                continue
            pieces.append(
                {
                    "piece_index": int(len(pieces)),
                    "color": int(color),
                    "x": min_x,
                    "y": min_y,
                    "width": width,
                    "height": height,
                    "pixels": pixels,
                    "active": bool(active),
                    "kind": kind,
                }
            )
    pieces.sort(key=lambda piece: (not bool(piece.get("active")), int(piece["y"]), int(piece["x"]), int(piece["color"])))
    for index, piece in enumerate(pieces):
        piece["piece_index"] = int(index)
    return pieces


def _shape_wall_morph_piece_kind(pixels: np.ndarray) -> str:
    arr = np.asarray(pixels)
    full_cols, full_rows = _shape_wall_morph_full_lines(arr)
    if len(full_cols) >= 2 and len(full_rows) >= 2:
        return "aspect_exchange_frame"
    if len(full_cols) == 1 and len(full_rows) == 1:
        return "line_shift_cross"
    return "unknown"


def _shape_wall_morph_full_lines(pixels: np.ndarray) -> tuple[list[int], list[int]]:
    arr = np.asarray(pixels)
    if arr.ndim != 2 or arr.size <= 0:
        return [], []
    occupied = arr != -1
    full_cols = [int(x) for x in range(arr.shape[1]) if bool(np.all(occupied[:, x]))]
    full_rows = [int(y) for y in range(arr.shape[0]) if bool(np.all(occupied[y, :]))]
    return full_cols, full_rows


def _shape_wall_morph_obstacles_from_frame(
    frame: np.ndarray,
    *,
    background_value: int,
    marker_colors: set[int],
    ring_values: set[int],
    selector_values: set[int],
) -> list[dict[str, Any]]:
    arr = np.asarray(frame)
    height, _width = arr.shape
    excluded = {int(background_value), *{int(v) for v in marker_colors}, *{int(v) for v in ring_values}, *{int(v) for v in selector_values}}
    obstacles: list[dict[str, Any]] = []
    for comp in _shape_recolor_nonbackground_components(arr, background_value=background_value):
        min_y = int(comp["min_y"])
        max_y = int(comp["max_y"])
        if max_y >= height - 1:
            continue
        values = set(int(value) for value in tuple(comp.get("values") or ()))
        if values & excluded:
            continue
        if int(comp.get("area", 0) or 0) < 8:
            continue
        if int(comp.get("width", 0) or 0) < 4 or int(comp.get("height", 0) or 0) < 4:
            continue
        coords = set()
        for y in range(min_y, max_y + 1):
            for x in range(int(comp["min_x"]), int(comp["max_x"]) + 1):
                if int(arr[y, x]) in values:
                    coords.add((int(x), int(y)))
        obstacles.append(
            {
                "bbox": (int(comp["min_x"]), min_y, int(comp["max_x"]), max_y),
                "coords": frozenset(coords),
                "area": int(comp["area"]),
            }
        )
    obstacles.sort(key=lambda item: (-int(item["area"]), tuple(item["bbox"])))
    return obstacles


def _shape_wall_morph_multi_piece_plan(
    pieces: Sequence[Mapping[str, Any]],
    *,
    obstacles: Sequence[Mapping[str, Any]],
    marker_groups: Mapping[int, Sequence[tuple[int, int]]],
    frame_shape: tuple[int, int],
) -> tuple[list[str], list[dict[str, Any]]] | None:
    current_pieces = [_shape_wall_morph_clone_piece(piece) for piece in pieces]
    active_indices = [index for index, piece in enumerate(current_pieces) if bool(piece.get("active"))]
    if len(active_indices) != 1:
        return None
    active_index = active_indices[0]
    plan: list[str] = []
    tasks: list[dict[str, Any]] = []
    ordered_piece_indices = [active_index] + [
        index for index in range(len(current_pieces)) if index != active_index
    ]
    for target_index in ordered_piece_indices:
        piece = current_pieces[target_index]
        color = int(piece.get("color", -1))
        markers = tuple((int(x), int(y)) for x, y in tuple(marker_groups.get(color) or ()))
        if not markers:
            return None
        while active_index != target_index:
            plan.append("ACTION5")
            current_pieces, active_index = _shape_wall_morph_cycle_active(current_pieces, active_index)
        subplan = _shape_wall_morph_single_piece_plan(
            current_pieces[active_index],
            obstacles=obstacles,
            markers=markers,
            frame_shape=frame_shape,
            max_depth=96,
            max_expansions=60000,
        )
        if subplan is None:
            return None
        before = _shape_wall_morph_public_piece(current_pieces[active_index])
        for action in subplan:
            current_pieces[active_index] = _shape_wall_morph_apply_move(
                current_pieces[active_index],
                action,
                obstacles=obstacles,
                frame_shape=frame_shape,
            )
        after = _shape_wall_morph_public_piece(current_pieces[active_index])
        plan.extend(subplan)
        tasks.append(
            {
                "piece_index": int(target_index),
                "source_color": color,
                "target_color": color,
                "marker_count": int(len(markers)),
                "current_pos": tuple(before.get("pos") or ()),
                "target_anchor": tuple(after.get("pos") or ()),
                "wall_morph_kind": str(before.get("kind", "")),
                "before_shape": (int(before.get("width", 0) or 0), int(before.get("height", 0) or 0)),
                "after_shape": (int(after.get("width", 0) or 0), int(after.get("height", 0) or 0)),
                "operation_plan": tuple(subplan),
            }
        )
    if not _shape_wall_morph_all_markers_covered(current_pieces, marker_groups):
        return None
    if len(plan) > 160:
        return None
    return plan, tasks


def _shape_wall_morph_single_piece_plan(
    piece: Mapping[str, Any],
    *,
    obstacles: Sequence[Mapping[str, Any]],
    markers: Sequence[tuple[int, int]],
    frame_shape: tuple[int, int],
    max_depth: int,
    max_expansions: int,
) -> list[str] | None:
    start = _shape_wall_morph_clone_piece(piece)
    if _shape_wall_morph_piece_covers_markers(start, markers):
        return []
    counter = 0
    heap: list[tuple[int, int, int, dict[str, Any], list[str]]] = []
    start_h = _shape_wall_morph_piece_heuristic(start, markers)
    heapq.heappush(heap, (start_h, 0, counter, start, []))
    seen = {_shape_wall_morph_piece_signature(start): 0}
    expansions = 0
    while heap and expansions < int(max_expansions):
        _rank, depth, _counter, current, path = heapq.heappop(heap)
        expansions += 1
        if _shape_wall_morph_piece_covers_markers(current, markers):
            return path
        if depth >= int(max_depth):
            continue
        for action in ("ACTION1", "ACTION2", "ACTION3", "ACTION4"):
            candidate = _shape_wall_morph_apply_move(
                current,
                action,
                obstacles=obstacles,
                frame_shape=frame_shape,
            )
            signature = _shape_wall_morph_piece_signature(candidate)
            next_depth = depth + 1
            if seen.get(signature, 10**9) <= next_depth:
                continue
            seen[signature] = next_depth
            counter += 1
            heuristic = _shape_wall_morph_piece_heuristic(candidate, markers)
            heapq.heappush(heap, (next_depth + heuristic, next_depth, counter, candidate, [*path, action]))
    return None


def _shape_wall_morph_clone_piece(piece: Mapping[str, Any]) -> dict[str, Any]:
    out = dict(piece)
    out["pixels"] = np.asarray(piece.get("pixels"), dtype=np.int16).copy()
    out["x"] = int(out.get("x", 0) or 0)
    out["y"] = int(out.get("y", 0) or 0)
    out["width"] = int(out["pixels"].shape[1])
    out["height"] = int(out["pixels"].shape[0])
    out["color"] = int(out.get("color", _shape_wall_morph_piece_color(out["pixels"])))
    out["active"] = bool(out.get("active", False))
    out["kind"] = str(out.get("kind") or _shape_wall_morph_piece_kind(out["pixels"]))
    return out


def _shape_wall_morph_public_piece(piece: Mapping[str, Any]) -> dict[str, Any]:
    pixels = np.asarray(piece.get("pixels"), dtype=np.int16)
    full_cols, full_rows = _shape_wall_morph_full_lines(pixels)
    return {
        "piece_index": int(piece.get("piece_index", 0) or 0),
        "color": int(piece.get("color", -1) or -1),
        "pos": (int(piece.get("x", 0) or 0), int(piece.get("y", 0) or 0)),
        "width": int(pixels.shape[1]) if pixels.ndim == 2 else 0,
        "height": int(pixels.shape[0]) if pixels.ndim == 2 else 0,
        "kind": str(piece.get("kind", "") or ""),
        "active": bool(piece.get("active", False)),
        "full_cols": tuple(full_cols),
        "full_rows": tuple(full_rows),
    }


def _shape_wall_morph_piece_color(pixels: np.ndarray) -> int:
    arr = np.asarray(pixels)
    values = [int(value) for value in arr.flatten().tolist() if int(value) not in {-1, 0}]
    return int(values[0]) if values else -1


def _shape_wall_morph_piece_signature(piece: Mapping[str, Any]) -> tuple[Any, ...]:
    pixels = np.asarray(piece.get("pixels"), dtype=np.int16)
    return (
        int(piece.get("x", 0) or 0),
        int(piece.get("y", 0) or 0),
        int(pixels.shape[1]) if pixels.ndim == 2 else 0,
        int(pixels.shape[0]) if pixels.ndim == 2 else 0,
        tuple(int(value) for value in pixels.flatten().tolist()),
    )


def _shape_wall_morph_piece_offsets(piece: Mapping[str, Any]) -> set[tuple[int, int]]:
    pixels = np.asarray(piece.get("pixels"), dtype=np.int16)
    color = int(piece.get("color", -1) or -1)
    return {
        (int(x), int(y))
        for y, x in np.argwhere(pixels == color).tolist()
    }


def _shape_wall_morph_piece_world_points(piece: Mapping[str, Any]) -> set[tuple[int, int, int]]:
    pixels = np.asarray(piece.get("pixels"), dtype=np.int16)
    x0 = int(piece.get("x", 0) or 0)
    y0 = int(piece.get("y", 0) or 0)
    return {
        (x0 + int(x), y0 + int(y), int(pixels[y, x]))
        for y, x in np.argwhere((pixels != -1) & (pixels != 0)).tolist()
    }


def _shape_wall_morph_piece_covers_markers(
    piece: Mapping[str, Any],
    markers: Sequence[tuple[int, int]],
) -> bool:
    color = int(piece.get("color", -1) or -1)
    points = _shape_wall_morph_piece_world_points(piece)
    return all((int(x), int(y), color) in points for x, y in markers)


def _shape_wall_morph_all_markers_covered(
    pieces: Sequence[Mapping[str, Any]],
    marker_groups: Mapping[int, Sequence[tuple[int, int]]],
) -> bool:
    world_points: set[tuple[int, int, int]] = set()
    for piece in pieces:
        world_points.update(_shape_wall_morph_piece_world_points(piece))
    for color, markers in marker_groups.items():
        for x, y in markers:
            if (int(x), int(y), int(color)) not in world_points:
                return False
    return True


def _shape_wall_morph_piece_heuristic(
    piece: Mapping[str, Any],
    markers: Sequence[tuple[int, int]],
) -> int:
    offsets = _shape_wall_morph_piece_offsets(piece)
    if not offsets:
        return 999
    current = (int(piece.get("x", 0) or 0), int(piece.get("y", 0) or 0))
    marker_tuple = tuple((int(x), int(y)) for x, y in markers)
    best = 999
    for marker_x, marker_y in marker_tuple:
        for offset_x, offset_y in offsets:
            anchor = (int(marker_x) - int(offset_x), int(marker_y) - int(offset_y))
            covered = sum(
                1
                for mx, my in marker_tuple
                if (int(mx) - anchor[0], int(my) - anchor[1]) in offsets
            )
            missing = len(marker_tuple) - covered
            move_distance = abs(anchor[0] - current[0]) + abs(anchor[1] - current[1])
            step_distance = move_distance // 3 + (1 if move_distance % 3 else 0)
            best = min(best, missing * 8 + step_distance)
    return int(best)


def _shape_wall_morph_cycle_active(
    pieces: Sequence[Mapping[str, Any]],
    active_index: int,
) -> tuple[list[dict[str, Any]], int]:
    out = [_shape_wall_morph_clone_piece(piece) for piece in pieces]
    if not out:
        return out, 0
    old_index = int(active_index) % len(out)
    next_index = (old_index + 1) % len(out)
    out[old_index] = _shape_wall_morph_set_piece_active(out[old_index], False)
    out[next_index] = _shape_wall_morph_set_piece_active(out[next_index], True)
    return out, next_index


def _shape_wall_morph_set_piece_active(piece: Mapping[str, Any], active: bool) -> dict[str, Any]:
    out = _shape_wall_morph_clone_piece(piece)
    pixels = out["pixels"].copy()
    cy = pixels.shape[0] // 2
    cx = pixels.shape[1] // 2
    if active:
        pixels[cy, cx] = 0
        out["active"] = True
    else:
        if str(out.get("kind", "")) == "aspect_exchange_frame":
            pixels[cy, cx] = -1
        else:
            full_cols, full_rows = _shape_wall_morph_full_lines(pixels)
            color = int(out.get("color", _shape_wall_morph_piece_color(pixels)))
            pixels[cy, cx] = color if (cx in full_cols or cy in full_rows) else -1
        out["active"] = False
    out["pixels"] = pixels
    out["width"] = int(pixels.shape[1])
    out["height"] = int(pixels.shape[0])
    return out


def _shape_wall_morph_apply_move(
    piece: Mapping[str, Any],
    action: str,
    *,
    obstacles: Sequence[Mapping[str, Any]],
    frame_shape: tuple[int, int],
) -> dict[str, Any]:
    dx, dy = {
        "ACTION1": (0, -3),
        "ACTION2": (0, 3),
        "ACTION3": (-3, 0),
        "ACTION4": (3, 0),
    }.get(str(action), (0, 0))
    if dx == 0 and dy == 0:
        return _shape_wall_morph_clone_piece(piece)
    moved = _shape_wall_morph_clone_piece(piece)
    moved["x"] = int(moved["x"]) + int(dx)
    moved["y"] = int(moved["y"]) + int(dy)
    if not _shape_wall_morph_center_in_bounds(moved, frame_shape):
        return _shape_wall_morph_set_piece_active(piece, True)
    obstacle = _shape_wall_morph_first_collision(moved, obstacles)
    if obstacle is None:
        return _shape_wall_morph_set_piece_active(moved, True)
    if str(moved.get("kind", "")) == "aspect_exchange_frame":
        return _shape_wall_morph_apply_frame_collision(moved, piece, dx=dx, dy=dy)
    if str(moved.get("kind", "")) == "line_shift_cross":
        return _shape_wall_morph_apply_line_collision(moved, piece, obstacle, dx=dx, dy=dy)
    return _shape_wall_morph_set_piece_active(piece, True)


def _shape_wall_morph_center_in_bounds(
    piece: Mapping[str, Any],
    frame_shape: tuple[int, int],
) -> bool:
    height, width = frame_shape
    pixels = np.asarray(piece.get("pixels"), dtype=np.int16)
    cx = int(piece.get("x", 0) or 0) + int(pixels.shape[1]) // 2
    cy = int(piece.get("y", 0) or 0) + int(pixels.shape[0]) // 2
    return 0 <= cx < int(width) and 0 <= cy < int(height)


def _shape_wall_morph_first_collision(
    piece: Mapping[str, Any],
    obstacles: Sequence[Mapping[str, Any]],
) -> Mapping[str, Any] | None:
    pixels = np.asarray(piece.get("pixels"), dtype=np.int16)
    x0 = int(piece.get("x", 0) or 0)
    y0 = int(piece.get("y", 0) or 0)
    local_points = [(int(x), int(y)) for y, x in np.argwhere(pixels != -1).tolist()]
    for obstacle in obstacles:
        coords = set(tuple(point) for point in obstacle.get("coords", frozenset()))
        if any((x0 + x, y0 + y) in coords for x, y in local_points):
            return obstacle
    return None


def _shape_wall_morph_apply_frame_collision(
    moved: Mapping[str, Any],
    previous: Mapping[str, Any],
    *,
    dx: int,
    dy: int,
) -> dict[str, Any]:
    out = _shape_wall_morph_clone_piece(moved)
    pixels = np.asarray(out["pixels"], dtype=np.int16)
    color = int(out.get("color", _shape_wall_morph_piece_color(pixels)))
    height, width = pixels.shape
    if dx != 0:
        if width <= 6:
            return _shape_wall_morph_set_piece_active(previous, True)
        new_height = height + 3
        new_width = width - 3
        y_adjust = height // 2 - new_height // 2
        new_pixels = _shape_wall_morph_frame_pixels(new_width, new_height, color)
        out["pixels"] = new_pixels
        out["width"] = int(new_width)
        out["height"] = int(new_height)
        out["y"] = int(out["y"]) + int(y_adjust)
        out["y"] = round(int(out["y"]) / 3) * 3
        if dx < 0:
            out["x"] = int(out["x"]) - int(dx)
    elif dy != 0:
        if height <= 6:
            return _shape_wall_morph_set_piece_active(previous, True)
        new_height = height - 3
        new_width = width + 3
        x_adjust = width // 2 - new_width // 2
        new_pixels = _shape_wall_morph_frame_pixels(new_width, new_height, color)
        out["pixels"] = new_pixels
        out["width"] = int(new_width)
        out["height"] = int(new_height)
        out["x"] = int(out["x"]) + int(x_adjust)
        out["x"] = round(int(out["x"]) / 3) * 3
        if dy < 0:
            out["y"] = int(out["y"]) - int(dy)
    return _shape_wall_morph_set_piece_active(out, True)


def _shape_wall_morph_frame_pixels(width: int, height: int, color: int) -> np.ndarray:
    pixels = np.full((int(height), int(width)), -1, dtype=np.int16)
    pixels[:, 0] = int(color)
    pixels[:, -1] = int(color)
    pixels[0, :] = int(color)
    pixels[-1, :] = int(color)
    pixels[int(height) // 2, int(width) // 2] = 0
    return pixels


def _shape_wall_morph_apply_line_collision(
    moved: Mapping[str, Any],
    previous: Mapping[str, Any],
    obstacle: Mapping[str, Any],
    *,
    dx: int,
    dy: int,
) -> dict[str, Any]:
    out = _shape_wall_morph_clone_piece(moved)
    pixels = np.asarray(out["pixels"], dtype=np.int16).copy()
    color = int(out.get("color", _shape_wall_morph_piece_color(pixels)))
    full_cols, full_rows = _shape_wall_morph_full_lines(pixels)
    if not full_cols or not full_rows:
        return _shape_wall_morph_set_piece_active(previous, True)
    col = int(full_cols[0])
    row = int(full_rows[0])
    min_x, min_y, max_x, max_y = (int(value) for value in tuple(obstacle.get("bbox") or (0, 0, -1, -1))[:4])
    col_in = min_x <= int(out["x"]) + col <= max_x
    row_in = min_y <= int(out["y"]) + row <= max_y
    if col_in and row_in:
        return _shape_wall_morph_set_piece_active(previous, True)
    if dx != 0:
        if col_in:
            shift = -3 if dx > 0 else 3
            if not (0 <= col + shift < pixels.shape[1]):
                return _shape_wall_morph_set_piece_active(previous, True)
            pixels[:, col] = -1
            pixels[:, col + shift] = color
            pixels[row, col] = color
        elif row_in:
            out = _shape_wall_morph_clone_piece(previous)
            pixels = np.asarray(out["pixels"], dtype=np.int16).copy()
            full_cols, full_rows = _shape_wall_morph_full_lines(pixels)
            if not full_cols or not full_rows:
                return _shape_wall_morph_set_piece_active(previous, True)
            col = int(full_cols[0])
            row = int(full_rows[0])
            shift = 3 if dx > 0 else -3
            if not (0 <= col + shift < pixels.shape[1]):
                return _shape_wall_morph_set_piece_active(previous, True)
            pixels[:, col] = -1
            pixels[:, col + shift] = color
            pixels[row, col] = color
        else:
            return _shape_wall_morph_set_piece_active(out, True)
    elif dy != 0:
        if row_in:
            shift = -3 if dy > 0 else 3
            if not (0 <= row + shift < pixels.shape[0]):
                return _shape_wall_morph_set_piece_active(previous, True)
            pixels[row, :] = -1
            pixels[row + shift, :] = color
            pixels[row, col] = color
        elif col_in:
            out = _shape_wall_morph_clone_piece(previous)
            pixels = np.asarray(out["pixels"], dtype=np.int16).copy()
            full_cols, full_rows = _shape_wall_morph_full_lines(pixels)
            if not full_cols or not full_rows:
                return _shape_wall_morph_set_piece_active(previous, True)
            col = int(full_cols[0])
            row = int(full_rows[0])
            shift = 3 if dy > 0 else -3
            if not (0 <= row + shift < pixels.shape[0]):
                return _shape_wall_morph_set_piece_active(previous, True)
            pixels[row, :] = -1
            pixels[row + shift, :] = color
            pixels[row, col] = color
        else:
            return _shape_wall_morph_set_piece_active(out, True)
    out["pixels"] = pixels
    out["width"] = int(pixels.shape[1])
    out["height"] = int(pixels.shape[0])
    return _shape_wall_morph_set_piece_active(out, True)


def _shape_recolor_multi_piece_marker_composition_state(
    frame: np.ndarray,
    *,
    background_value: int,
    marker_groups: Mapping[int, Sequence[tuple[int, int]]],
    ring_values: set[int],
    marker_colors: set[int],
    pads: Mapping[int, Mapping[str, Any]],
    shapes: Sequence[Mapping[str, Any]],
) -> dict[str, Any] | None:
    arr = np.asarray(frame)
    if arr.ndim != 2 or len(shapes) != 3 or len(marker_groups) != 2:
        return None
    active_shapes = [dict(shape) for shape in shapes if bool(shape.get("active"))]
    if len(active_shapes) != 1:
        return None
    if not set(marker_colors).issubset(set(pads)):
        return None
    augmented_shapes = _shape_recolor_augmented_composition_shapes(
        arr,
        shapes=shapes,
        background_value=background_value,
        marker_colors=marker_colors,
    )
    if len(augmented_shapes) != 3 or not bool(augmented_shapes[0].get("active")):
        return None
    all_pads = _shape_recolor_all_palette_pads(arr, background_value=background_value)
    if not set(marker_colors).issubset(set(all_pads)):
        return None
    visible_markers: dict[tuple[int, int], int] = {}
    for color, points in marker_groups.items():
        for x, y in points:
            visible_markers[(int(x), int(y))] = int(color)
    if len(visible_markers) < 6:
        return None

    options_by_shape: list[list[dict[str, Any]]] = []
    for shape in augmented_shapes:
        shape_index = int(shape.get("shape_index", len(options_by_shape)))
        current_pos = tuple(int(v) for v in tuple(shape.get("pos") or ())[:2])
        if len(current_pos) < 2:
            return None
        offsets = set((int(x), int(y)) for x, y in tuple(shape.get("coverage_offsets") or ()))
        if not offsets:
            return None
        candidates: dict[tuple[int, tuple[tuple[int, int], ...]], dict[str, Any]] = {}
        for target_color in sorted(marker_colors):
            for marker_x, marker_y in visible_markers:
                for offset_x, offset_y in offsets:
                    anchor = (int(marker_x) - int(offset_x), int(marker_y) - int(offset_y))
                    if (anchor[0] - current_pos[0]) % 3 != 0 or (anchor[1] - current_pos[1]) % 3 != 0:
                        continue
                    covered = {
                        point
                        for point, color in visible_markers.items()
                        if int(color) == int(target_color)
                        and (point[0] - anchor[0], point[1] - anchor[1]) in offsets
                    }
                    wrong = {
                        point
                        for point, color in visible_markers.items()
                        if int(color) != int(target_color)
                        and (point[0] - anchor[0], point[1] - anchor[1]) in offsets
                    }
                    if len(covered) < 2 or wrong:
                        continue
                    task_plan, waypoint = _shape_recolor_safe_task_plan(
                        shape,
                        pads[int(target_color)],
                        all_pads=all_pads,
                        target_color=int(target_color),
                        anchor=anchor,
                    )
                    if not task_plan or waypoint is None:
                        continue
                    key = (int(target_color), tuple(sorted(covered)))
                    candidate = {
                        "shape_index": shape_index,
                        "source_color": int(shape.get("color", -1)),
                        "target_color": int(target_color),
                        "marker_count": int(len(covered)),
                        "current_pos": current_pos,
                        "target_anchor": (int(anchor[0]), int(anchor[1])),
                        "recolor_waypoint": (int(waypoint[0]), int(waypoint[1])),
                        "palette_pad_bbox": tuple(pads[int(target_color)]["bbox"]),
                        "shape_clipped_completion": bool(shape.get("clipped_completion")),
                        "covered_markers": tuple(sorted(covered)),
                        "operation_plan": tuple(task_plan),
                    }
                    current = candidates.get(key)
                    current_rank = (
                        len(tuple(current.get("operation_plan") or ())),
                        tuple(current.get("target_anchor") or ()),
                    ) if current is not None else (10**9, ())
                    rank = (len(task_plan), (int(anchor[0]), int(anchor[1])))
                    if current is None or rank < current_rank:
                        candidates[key] = candidate
        shape_options = sorted(
            candidates.values(),
            key=lambda item: (
                len(tuple(item.get("operation_plan") or ())),
                -int(item.get("marker_count", 0) or 0),
                int(item.get("target_color", -1)),
                tuple(item.get("target_anchor") or ()),
            ),
        )[:48]
        if not shape_options:
            return None
        options_by_shape.append(shape_options)

    overlay_order = [2, 0, 1]
    best: tuple[tuple[Any, ...], list[dict[str, Any]], list[str]] | None = None
    for combo in product(*options_by_shape):
        by_shape = {int(task["shape_index"]): dict(task) for task in combo}
        final_colors: dict[tuple[int, int], int | None] = {point: None for point in visible_markers}
        for shape_index in overlay_order:
            task = by_shape.get(shape_index)
            if task is None:
                continue
            shape = augmented_shapes[shape_index]
            offsets = set((int(x), int(y)) for x, y in tuple(shape.get("coverage_offsets") or ()))
            anchor = tuple(int(v) for v in tuple(task.get("target_anchor") or ())[:2])
            if len(anchor) < 2:
                continue
            for point in visible_markers:
                if (point[0] - anchor[0], point[1] - anchor[1]) in offsets:
                    final_colors[point] = int(task["target_color"])
        if any(final_colors[point] != color for point, color in visible_markers.items()):
            continue
        plan: list[str] = []
        tasks: list[dict[str, Any]] = []
        for index, task in enumerate(combo):
            if index > 0:
                plan.append("ACTION5")
            plan.extend(str(action) for action in tuple(task.get("operation_plan") or ()))
            task_copy = dict(task)
            task_copy.pop("covered_markers", None)
            tasks.append(task_copy)
        if len(plan) > 128:
            continue
        rank = (
            len(plan),
            tuple(int(task.get("target_color", -1)) for task in combo),
            tuple(tuple(task.get("target_anchor") or ()) for task in combo),
            tuple(-int(task.get("marker_count", 0) or 0) for task in combo),
        )
        if best is None or rank < best[0]:
            best = (rank, tasks, plan)
    if best is None:
        return None
    _rank, tasks, plan = best
    marker_count = sum(len(tuple(group)) for group in marker_groups.values())
    return {
        "mechanic_state_type": "shape_recolor_coverage",
        "goal_link_type": "palette_recolored_multi_piece_shape_pixels_cover_target_markers",
        "background_value": int(background_value),
        "ring_value": int(next(iter(ring_values))) if len(ring_values) == 1 else -1,
        "marker_count": int(marker_count),
        "marker_color_count": int(len(marker_groups)),
        "piece_count": int(len(augmented_shapes)),
        "palette_pad_count": int(len(pads)),
        "tasks": tasks,
        "active_piece": dict(tasks[0]) if tasks else {},
        "pieces": augmented_shapes,
        "multi_piece_marker_composition": True,
        "precomputed_operation_plan": tuple(plan),
        "operation_plan": tuple(plan),
        "operation_plan_len": int(len(plan)),
        "expected_goal_delta": 1.0,
        "reader_confidence": 0.62,
        "goal_link_confidence": 0.61,
    }


def _shape_recolor_augmented_composition_shapes(
    frame: np.ndarray,
    *,
    shapes: Sequence[Mapping[str, Any]],
    background_value: int,
    marker_colors: set[int],
) -> list[dict[str, Any]]:
    arr = np.asarray(frame)
    height, width = arr.shape
    components = _shape_recolor_eight_connected_nonbackground_components(
        arr,
        background_value=background_value,
    )
    augmented: list[dict[str, Any]] = []
    for shape in shapes:
        item = dict(shape)
        pos = tuple(int(v) for v in tuple(item.get("pos") or ())[:2])
        if len(pos) < 2:
            augmented.append(item)
            continue
        x0, y0 = pos
        color = int(item.get("color", -1))
        offsets = set((int(x), int(y)) for x, y in tuple(item.get("coverage_offsets") or ()))
        visible_width = max(1, int(item.get("visible_width", item.get("width", 1)) or 1))
        visible_height = max(1, int(item.get("visible_height", item.get("height", 1)) or 1))
        max_x = x0 + visible_width - 1
        max_y = y0 + visible_height - 1
        for comp in components:
            values = comp.get("values")
            if not isinstance(values, Counter) or int(values.get(color, 0)) < 8:
                continue
            bbox = tuple(comp.get("bbox") or ())
            if len(bbox) < 4:
                continue
            bx0, by0, bx1, by1 = (int(v) for v in bbox[:4])
            if not (bx0 <= x0 <= bx1 and by0 <= y0 <= by1):
                continue
            for cx, cy in tuple(comp.get("coords") or ()):
                value = int(arr[int(cy), int(cx)])
                if value == int(background_value) or value in marker_colors:
                    continue
                offsets.add((int(cx) - x0, int(cy) - y0))
        clipped = False
        if offsets:
            xs = [int(x) for x, _y in offsets]
            ys = [int(y) for _x, y in offsets]
            center_x = int(Counter(xs).most_common(1)[0][0])
            center_y = int(Counter(ys).most_common(1)[0][0])
            if x0 <= 0 or max_x >= width - 1:
                clipped = True
                for ox, oy in list(offsets):
                    mirror_x = 2 * center_x - int(ox)
                    if mirror_x >= 0:
                        offsets.add((int(mirror_x), int(oy)))
            if y0 <= 0 or max_y >= height - 1:
                clipped = True
                for ox, oy in list(offsets):
                    mirror_y = 2 * center_y - int(oy)
                    if mirror_y >= 0:
                        offsets.add((int(ox), int(mirror_y)))
        if offsets:
            item["coverage_offsets"] = tuple(sorted(offsets))
            item["width"] = max(int(item.get("width", 0) or 0), max(x for x, _y in offsets) + 1)
            item["height"] = max(int(item.get("height", 0) or 0), max(y for _x, y in offsets) + 1)
            item["clipped_completion"] = bool(item.get("clipped_completion")) or bool(clipped)
        augmented.append(item)
    return augmented


def _shape_recolor_eight_connected_nonbackground_components(
    frame: np.ndarray,
    *,
    background_value: int,
) -> list[dict[str, Any]]:
    arr = np.asarray(frame)
    height, width = arr.shape
    allowed = arr != int(background_value)
    seen = np.zeros(arr.shape, dtype=bool)
    components: list[dict[str, Any]] = []
    for y in range(height):
        for x in range(width):
            if seen[y, x] or not bool(allowed[y, x]):
                continue
            stack = [(int(y), int(x))]
            seen[y, x] = True
            coords: list[tuple[int, int]] = []
            values: Counter[int] = Counter()
            while stack:
                cy, cx = stack.pop()
                coords.append((int(cx), int(cy)))
                values[int(arr[cy, cx])] += 1
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        if dy == 0 and dx == 0:
                            continue
                        ny, nx = cy + dy, cx + dx
                        if 0 <= ny < height and 0 <= nx < width and not seen[ny, nx] and bool(allowed[ny, nx]):
                            seen[ny, nx] = True
                            stack.append((int(ny), int(nx)))
            xs = [cx for cx, _cy in coords]
            ys = [cy for _cx, cy in coords]
            components.append(
                {
                    "bbox": (int(min(xs)), int(min(ys)), int(max(xs)), int(max(ys))),
                    "coords": tuple(coords),
                    "values": values,
                }
            )
    return components


def _shape_recolor_all_palette_pads(
    frame: np.ndarray,
    *,
    background_value: int,
) -> dict[int, dict[str, Any]]:
    pads: dict[int, dict[str, Any]] = {}
    for comp in _shape_recolor_nonbackground_components(frame, background_value=background_value):
        width = int(comp["width"])
        height = int(comp["height"])
        if width < 5 or height < 5 or width > 8 or height > 8:
            continue
        values = Counter(int(v) for v in comp.get("values", ()))
        for color, count in sorted(values.items()):
            if int(color) in {int(background_value), 0, 2, 4}:
                continue
            if int(count) < 8:
                continue
            candidate = {
                "color": int(color),
                "bbox": (
                    int(comp["min_x"]),
                    int(comp["min_y"]),
                    int(comp["max_x"]),
                    int(comp["max_y"]),
                ),
                "width": width,
                "height": height,
                "color_count": int(count),
                "area": int(comp["area"]),
            }
            current = pads.get(int(color))
            current_rank = (
                int(current.get("color_count", 0) or 0),
                int(current.get("area", 0) or 0),
            ) if current is not None else (-1, -1)
            rank = (int(candidate["color_count"]), int(candidate["area"]))
            if current is None or rank > current_rank:
                pads[int(color)] = candidate
    return pads


def _shape_recolor_safe_task_plan(
    shape: Mapping[str, Any],
    target_pad: Mapping[str, Any],
    *,
    all_pads: Mapping[int, Mapping[str, Any]],
    target_color: int,
    anchor: tuple[int, int],
) -> tuple[list[str] | None, tuple[int, int] | None]:
    pos = tuple(int(v) for v in tuple(shape.get("pos") or ())[:2])
    if len(pos) < 2:
        return None, None
    offsets = set((int(x), int(y)) for x, y in tuple(shape.get("coverage_offsets") or ()))
    if not offsets:
        return None, None
    pad_bbox = tuple(target_pad.get("bbox") or ())
    if len(pad_bbox) < 4:
        return None, None
    pad_min_x, pad_min_y, pad_max_x, pad_max_y = (int(v) for v in pad_bbox[:4])
    shape_width = max(1, int(shape.get("width", 0) or 0))
    shape_height = max(1, int(shape.get("height", 0) or 0))
    candidates: list[tuple[tuple[Any, ...], list[str], tuple[int, int]]] = []
    waypoint_candidates: list[tuple[tuple[int, int, int], tuple[int, int]]] = []
    for wy in range(pad_min_y - shape_height + 1, pad_max_y + 1):
        for wx in range(pad_min_x - shape_width + 1, pad_max_x + 1):
            waypoint = (int(wx), int(wy))
            if (waypoint[0] - pos[0]) % 3 != 0 or (waypoint[1] - pos[1]) % 3 != 0:
                continue
            if (int(anchor[0]) - waypoint[0]) % 3 != 0 or (int(anchor[1]) - waypoint[1]) % 3 != 0:
                continue
            if not _shape_recolor_offsets_overlap_bbox(offsets, waypoint, pad_bbox):
                continue
            waypoint_candidates.append(
                (
                    (
                        abs(waypoint[0] - pos[0])
                        + abs(waypoint[1] - pos[1])
                        + abs(int(anchor[0]) - waypoint[0])
                        + abs(int(anchor[1]) - waypoint[1]),
                        abs(waypoint[0] - pos[0]) + abs(waypoint[1] - pos[1]),
                        waypoint[1] * 128 + waypoint[0],
                    ),
                    waypoint,
                )
            )
    waypoint_candidates.sort(key=lambda item: item[0])
    for _waypoint_rank, waypoint in waypoint_candidates[:96]:
        for first_order in ("yx", "xy"):
            first = _shape_recolor_route_plan(pos, waypoint, order=first_order)
            if first is None:
                continue
            for second_order in ("yx", "xy"):
                second = _shape_recolor_route_plan(waypoint, anchor, order=second_order)
                if second is None:
                    continue
                plan = [*first, *second]
                if not plan:
                    continue
                hit_target = False
                wrong_pad = False
                for step_pos in _shape_recolor_route_positions(pos, plan):
                    for color, pad in all_pads.items():
                        bbox = tuple(pad.get("bbox") or ())
                        if len(bbox) < 4:
                            continue
                        if not _shape_recolor_offsets_overlap_bbox(offsets, step_pos, bbox):
                            continue
                        if int(color) == int(target_color):
                            hit_target = True
                        else:
                            wrong_pad = True
                if not hit_target or wrong_pad:
                    continue
                rank = (
                    len(plan),
                    abs(waypoint[0] - pos[0]) + abs(waypoint[1] - pos[1]),
                    first_order,
                    second_order,
                    waypoint,
                )
                candidates.append((rank, plan, waypoint))
    if not candidates:
        return None, None
    candidates.sort(key=lambda item: item[0])
    _rank, plan, waypoint = candidates[0]
    return list(plan), waypoint


def _shape_recolor_offsets_overlap_bbox(
    offsets: set[tuple[int, int]],
    pos: tuple[int, int],
    bbox: tuple[int, int, int, int],
) -> bool:
    if len(pos) < 2 or len(bbox) < 4:
        return False
    x0, y0 = int(pos[0]), int(pos[1])
    min_x, min_y, max_x, max_y = (int(v) for v in bbox[:4])
    return any(
        min_x <= x0 + int(ox) <= max_x and min_y <= y0 + int(oy) <= max_y
        for ox, oy in offsets
    )


def _shape_recolor_route_positions(
    source: tuple[int, int],
    plan: Sequence[str],
) -> list[tuple[int, int]]:
    x, y = int(source[0]), int(source[1])
    positions: list[tuple[int, int]] = []
    for action in plan:
        normalized = _normalize_action_name(action)
        if normalized == "ACTION1":
            y -= 3
        elif normalized == "ACTION2":
            y += 3
        elif normalized == "ACTION3":
            x -= 3
        elif normalized == "ACTION4":
            x += 3
        positions.append((int(x), int(y)))
    return positions


def _shape_recolor_candidate_shapes(
    frame: np.ndarray,
    *,
    background_value: int,
    marker_colors: set[int],
    ring_values: set[int],
    selector_values: set[int],
) -> list[dict[str, Any]]:
    arr = np.asarray(frame)
    selector_positions = [
        (int(x), int(y))
        for selector in selector_values
        for y, x in np.argwhere(arr == int(selector)).tolist()
    ]
    selector_mask = np.zeros(arr.shape, dtype=bool)
    for selector in selector_values:
        selector_mask |= arr == int(selector)
    excluded_values = {int(background_value), *{int(v) for v in marker_colors}, *{int(v) for v in ring_values}}
    shapes: list[dict[str, Any]] = []
    for color, count in sorted(Counter(int(v) for v in arr.flatten().tolist()).items()):
        if int(color) in excluded_values:
            continue
        if int(count) < 8:
            continue
        allowed = (arr == int(color)) | selector_mask
        components = _shape_coverage_mask_components(
            arr,
            allowed,
            color=int(color),
            selector_values=selector_values,
        )
        for comp in components:
            if int(comp.get("color_area", 0) or 0) < 8:
                continue
            if int(comp.get("width", 0) or 0) < 6 or int(comp.get("height", 0) or 0) < 6:
                continue
            if int(comp.get("width", 0) or 0) <= 8 and int(comp.get("height", 0) or 0) <= 8:
                continue
            selector_inside = [
                (sx, sy)
                for sx, sy in selector_positions
                if int(comp["min_x"]) <= sx <= int(comp["max_x"])
                and int(comp["min_y"]) <= sy <= int(comp["max_y"])
            ]
            active = bool(int(comp.get("selector_count", 0) or 0) > 0 or selector_inside)
            completed = _shape_recolor_completed_offsets(
                comp,
                frame_shape=arr.shape,
                selector_positions=selector_inside,
            )
            shape = {
                "shape_index": int(len(shapes)),
                "color": int(color),
                "pos": (int(comp["min_x"]), int(comp["min_y"])),
                "width": int(completed["width"]),
                "height": int(completed["height"]),
                "visible_width": int(comp["width"]),
                "visible_height": int(comp["height"]),
                "color_area": int(comp["color_area"]),
                "coverage_offsets": tuple(sorted(completed["offsets"])),
                "active": bool(active),
                "clipped_completion": bool(completed["clipped_completion"]),
            }
            shapes.append(shape)
    shapes.sort(key=lambda item: (not bool(item.get("active")), int(item["pos"][1]), int(item["pos"][0])))
    for index, shape in enumerate(shapes):
        shape["shape_index"] = int(index)
    return shapes


def _shape_recolor_completed_offsets(
    comp: Mapping[str, Any],
    *,
    frame_shape: tuple[int, int],
    selector_positions: Sequence[tuple[int, int]],
) -> dict[str, Any]:
    offsets = set((int(x), int(y)) for x, y in tuple(comp.get("color_offsets") or ()))
    if not offsets:
        return {"offsets": tuple(), "width": int(comp.get("width", 0) or 0), "height": int(comp.get("height", 0) or 0), "clipped_completion": False}
    height, width = frame_shape
    min_x = int(comp.get("min_x", 0) or 0)
    min_y = int(comp.get("min_y", 0) or 0)
    max_x = int(comp.get("max_x", min_x) or min_x)
    max_y = int(comp.get("max_y", min_y) or min_y)
    completed = set(offsets)
    clipped = False
    selector_offsets = [
        (int(sx) - min_x, int(sy) - min_y)
        for sx, sy in selector_positions
    ]
    if selector_offsets:
        sx, sy = selector_offsets[0]
        touch_horizontal = min_x <= 0 or max_x >= width - 1
        touch_vertical = min_y <= 0 or max_y >= height - 1
        if touch_horizontal:
            clipped = True
            for ox, oy in list(completed):
                mx = 2 * sx - int(ox)
                if mx >= 0:
                    completed.add((int(mx), int(oy)))
        if touch_vertical:
            clipped = True
            for ox, oy in list(completed):
                my = 2 * sy - int(oy)
                if my >= 0:
                    completed.add((int(ox), int(my)))
        if touch_horizontal and touch_vertical:
            for ox, oy in list(offsets):
                mx = 2 * sx - int(ox)
                my = 2 * sy - int(oy)
                if mx >= 0 and my >= 0:
                    completed.add((int(mx), int(my)))
    inferred_width = max(int(comp.get("width", 0) or 0), max(x for x, _y in completed) + 1)
    inferred_height = max(int(comp.get("height", 0) or 0), max(y for _x, y in completed) + 1)
    return {
        "offsets": tuple(sorted(completed)),
        "width": int(inferred_width),
        "height": int(inferred_height),
        "clipped_completion": bool(clipped),
    }


def _shape_recolor_palette_pads(
    frame: np.ndarray,
    *,
    marker_colors: set[int],
    background_value: int,
) -> dict[int, dict[str, Any]]:
    arr = np.asarray(frame)
    components = _shape_recolor_nonbackground_components(arr, background_value=background_value)
    pads: dict[int, dict[str, Any]] = {}
    for comp in components:
        width = int(comp["width"])
        height = int(comp["height"])
        if width < 5 or height < 5 or width > 8 or height > 8:
            continue
        values = Counter(int(v) for v in comp.get("values", ()))
        pad_colors = sorted(int(color) for color in marker_colors if int(color) in values)
        if not pad_colors:
            continue
        for color in pad_colors:
            candidate = {
                "color": int(color),
                "bbox": (
                    int(comp["min_x"]),
                    int(comp["min_y"]),
                    int(comp["max_x"]),
                    int(comp["max_y"]),
                ),
                "width": width,
                "height": height,
                "color_count": int(values[int(color)]),
                "area": int(comp["area"]),
            }
            current = pads.get(int(color))
            rank = (int(candidate["color_count"]), int(candidate["area"]))
            current_rank = (
                int(current.get("color_count", 0) or 0),
                int(current.get("area", 0) or 0),
            ) if current is not None else (-1, -1)
            if current is None or rank > current_rank:
                pads[int(color)] = candidate
    return pads


def _shape_recolor_nonbackground_components(
    frame: np.ndarray,
    *,
    background_value: int,
) -> list[dict[str, Any]]:
    arr = np.asarray(frame)
    height, width = arr.shape
    allowed = arr != int(background_value)
    seen = np.zeros(arr.shape, dtype=bool)
    comps: list[dict[str, Any]] = []
    for y in range(height):
        for x in range(width):
            if seen[y, x] or not bool(allowed[y, x]):
                continue
            stack = [(y, x)]
            seen[y, x] = True
            coords: list[tuple[int, int]] = []
            values: list[int] = []
            while stack:
                cy, cx = stack.pop()
                coords.append((cx, cy))
                values.append(int(arr[cy, cx]))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = cy + dy, cx + dx
                    if 0 <= ny < height and 0 <= nx < width and not seen[ny, nx] and bool(allowed[ny, nx]):
                        seen[ny, nx] = True
                        stack.append((ny, nx))
            xs = [x0 for x0, _y0 in coords]
            ys = [y0 for _x0, y0 in coords]
            comps.append(
                {
                    "min_x": int(min(xs)),
                    "min_y": int(min(ys)),
                    "max_x": int(max(xs)),
                    "max_y": int(max(ys)),
                    "width": int(max(xs) - min(xs) + 1),
                    "height": int(max(ys) - min(ys) + 1),
                    "area": int(len(coords)),
                    "values": tuple(values),
                }
            )
    return comps


def _shape_recolor_best_waypoint(
    shape: Mapping[str, Any],
    pad: Mapping[str, Any],
    *,
    anchor: tuple[int, int],
    frame_shape: tuple[int, int],
) -> tuple[int, int] | None:
    pos = tuple(shape.get("pos") or ())
    if len(pos) < 2:
        return None
    height, width = frame_shape
    shape_width = max(1, int(shape.get("width", 0) or 0))
    shape_height = max(1, int(shape.get("height", 0) or 0))
    offsets = tuple((int(x), int(y)) for x, y in tuple(shape.get("coverage_offsets") or ()))
    if not offsets:
        return None
    pad_bbox = tuple(pad.get("bbox") or ())
    if len(pad_bbox) < 4:
        return None
    pad_min_x, pad_min_y, pad_max_x, pad_max_y = (int(v) for v in pad_bbox[:4])
    current = (int(pos[0]), int(pos[1]))
    candidates: list[tuple[tuple[int, int, int, int], tuple[int, int]]] = []
    for wy in range(pad_min_y - shape_height + 1, pad_max_y + 1):
        for wx in range(pad_min_x - shape_width + 1, pad_max_x + 1):
            if (wx - current[0]) % 3 != 0 or (wy - current[1]) % 3 != 0:
                continue
            if (int(anchor[0]) - wx) % 3 != 0 or (int(anchor[1]) - wy) % 3 != 0:
                continue
            cx = wx + shape_width // 2
            cy = wy + shape_height // 2
            if cx < 0 or cy < 0 or cx >= width or cy >= height:
                continue
            overlaps = any(
                pad_min_x <= wx + ox <= pad_max_x and pad_min_y <= wy + oy <= pad_max_y
                for ox, oy in offsets
            )
            if not overlaps:
                continue
            total = abs(wx - current[0]) + abs(wy - current[1]) + abs(int(anchor[0]) - wx) + abs(int(anchor[1]) - wy)
            toward_pad = abs((wx + shape_width // 2) - ((pad_min_x + pad_max_x) // 2)) + abs(
                (wy + shape_height // 2) - ((pad_min_y + pad_max_y) // 2)
            )
            candidates.append(((total, toward_pad, abs(wy - current[1]), abs(wx - current[0])), (int(wx), int(wy))))
    if not candidates:
        return None
    candidates.sort()
    return candidates[0][1]


def _shape_recolor_task_plan(
    current: tuple[int, int],
    waypoint: tuple[int, int],
    anchor: tuple[int, int],
) -> list[str]:
    first = _shape_recolor_route_plan(current, waypoint, order="yx")
    if first is None:
        return []
    second_order = "yx" if int(anchor[1]) < int(waypoint[1]) else "xy"
    second = _shape_recolor_route_plan(waypoint, anchor, order=second_order)
    if second is None:
        return []
    return [*first, *second]


def _shape_recolor_route_plan(
    source: tuple[int, int],
    target: tuple[int, int],
    *,
    order: str,
) -> list[str] | None:
    dx = int(target[0]) - int(source[0])
    dy = int(target[1]) - int(source[1])
    if dx % 3 != 0 or dy % 3 != 0:
        return None
    x_plan = ["ACTION4"] * (dx // 3) if dx > 0 else ["ACTION3"] * ((-dx) // 3)
    y_plan = ["ACTION2"] * (dy // 3) if dy > 0 else ["ACTION1"] * ((-dy) // 3)
    return [*y_plan, *x_plan] if order == "yx" else [*x_plan, *y_plan]


def _compact_shape_recolor_coverage_state(state: Mapping[str, Any] | None) -> dict[str, Any] | None:
    if state is None:
        return None
    tasks = [
        dict(task)
        for task in list(state.get("tasks") or [])
        if isinstance(task, Mapping)
    ]
    return {
        "mechanic_state_type": str(state.get("mechanic_state_type", "") or ""),
        "goal_link_type": str(state.get("goal_link_type", "") or ""),
        "marker_count": int(state.get("marker_count", 0) or 0),
        "marker_color_count": int(state.get("marker_color_count", 0) or 0),
        "piece_count": int(state.get("piece_count", 0) or 0),
        "palette_pad_count": int(state.get("palette_pad_count", 0) or 0),
        "operation_plan_len": int(state.get("operation_plan_len", 0) or 0),
        "task_count": int(len(tasks)),
        "tasks": [
            {
                "source_color": int(task.get("source_color", -1)),
                "target_color": int(task.get("target_color", -1)),
                "marker_count": int(task.get("marker_count", 0) or 0),
                "current_pos": list(task.get("current_pos") or []),
                "recolor_waypoint": list(task.get("recolor_waypoint") or []),
                "target_anchor": list(task.get("target_anchor") or []),
                "shape_clipped_completion": bool(task.get("shape_clipped_completion")),
                "operation_plan_len": len(tuple(task.get("operation_plan") or ())),
            }
            for task in tasks[:4]
        ],
        "expected_goal_delta": float(state.get("expected_goal_delta", 0.0) or 0.0),
        "reader_confidence": float(state.get("reader_confidence", 0.0) or 0.0),
        "goal_link_confidence": float(state.get("goal_link_confidence", 0.0) or 0.0),
    }


def _compact_shape_coverage_paste_state(state: Mapping[str, Any] | None) -> dict[str, Any] | None:
    if state is None:
        return None
    active = dict(state.get("active_piece") or {})
    hypothesis_validation = _shape_coverage_paste_hypothesis_descriptor_validation(state)
    return {
        "mechanic_state_type": str(state.get("mechanic_state_type", "") or ""),
        "goal_link_type": str(state.get("goal_link_type", "") or ""),
        "marker_count": int(state.get("marker_count", 0) or 0),
        "marker_color_count": int(state.get("marker_color_count", 0) or 0),
        "piece_count": int(state.get("piece_count", 0) or 0),
        "operation_plan_len": int(state.get("operation_plan_len", 0) or 0),
        "same_color_multi_piece_partition": bool(state.get("same_color_multi_piece_partition")),
        "precomputed_operation_plan_len": len(tuple(state.get("precomputed_operation_plan") or ())),
        "active_color": int(active.get("color", -1)),
        "active_pos": list(active.get("pos") or []),
        "active_target_anchor": list(active.get("target_anchor") or []),
        "active_distance_to_anchor": int(active.get("distance_to_anchor", 0) or 0),
        "active_marker_count": int(active.get("marker_count", 0) or 0),
        "cycle_after_move": bool(active.get("cycle_after_move")),
        "reader_confidence": float(state.get("reader_confidence", 0.0) or 0.0),
        "goal_link_confidence": float(state.get("goal_link_confidence", 0.0) or 0.0),
        "mechanic_hypothesis_valid": bool(hypothesis_validation["accepted"]),
        "mechanic_hypothesis_reject_reason": str(hypothesis_validation["reject_reason"]),
    }


def _axis_reflection_coverage_state(frame: np.ndarray) -> dict[str, Any] | None:
    arr = np.asarray(frame)
    if arr.ndim != 2 or arr.size <= 0:
        return None
    height, width = arr.shape
    if height < 24 or width < 24:
        return None
    cell = _axis_reflection_cell_size(arr)
    grid_w = width // cell
    grid_h = height // cell
    if grid_w < 8 or grid_h < 8:
        return None
    value_counts = Counter(int(value) for value in arr.flatten().tolist())
    background_value = int(value_counts.most_common(1)[0][0])
    cell_sets = _axis_reflection_value_cell_sets(arr, cell=cell)
    axis = _axis_reflection_vertical_axis(
        cell_sets,
        grid_h=grid_h,
        background_value=background_value,
    )
    if axis is None:
        return _axis_reflection_multi_cursor_coverage_state(
            cell_sets,
            grid_w=grid_w,
            grid_h=grid_h,
            background_value=background_value,
            cell=cell,
            pixel_counts=value_counts,
        )
    axis_x, axis_value = axis
    candidates = {
        value: cells
        for value, cells in cell_sets.items()
        if value != background_value
        and value != axis_value
        and 2 <= len(cells) <= 32
        and _axis_reflection_dense_value(value, cells, arr, cell=cell)
    }
    if len(candidates) < 3:
        return _axis_reflection_multi_cursor_coverage_state(
            cell_sets,
            grid_w=grid_w,
            grid_h=grid_h,
            background_value=background_value,
            cell=cell,
            pixel_counts=value_counts,
        )
    reflected_pairs: list[tuple[int, int, frozenset[tuple[int, int]], frozenset[tuple[int, int]]]] = []
    for value, cells in candidates.items():
        reflected = frozenset((2 * int(axis_x) - int(x), int(y)) for x, y in cells)
        for other_value, other_cells in candidates.items():
            if other_value == value:
                continue
            if reflected == other_cells:
                reflected_pairs.append((value, other_value, frozenset(cells), reflected))
    if not reflected_pairs:
        return None

    best: dict[str, Any] | None = None
    best_score: tuple[float, int, int] | None = None
    for cursor_value, reflection_value, cursor_cells, reflection_cells in reflected_pairs:
        cursor_cx = sum(x for x, _y in cursor_cells) / float(len(cursor_cells))
        cursor_side = -1 if cursor_cx < axis_x else 1
        if cursor_side == 0:
            continue
        cursor_pos = (min(x for x, _y in cursor_cells), min(y for _x, y in cursor_cells))
        cursor_offsets = tuple(sorted((x - cursor_pos[0], y - cursor_pos[1]) for x, y in cursor_cells))
        if not cursor_offsets:
            continue
        for target_value, target_cells_raw in candidates.items():
            if target_value in {cursor_value, reflection_value}:
                continue
            target_cells = frozenset(target_cells_raw)
            if len(target_cells) != len(cursor_offsets):
                continue
            target_cx = sum(x for x, _y in target_cells) / float(len(target_cells))
            if (target_cx - axis_x) * cursor_side >= 0:
                continue
            target_anchor = _axis_reflection_target_anchor(
                cursor_offsets,
                axis_x=int(axis_x),
                targets=target_cells,
            )
            if target_anchor is None:
                continue
            dx = int(target_anchor[0]) - int(cursor_pos[0])
            dy = int(target_anchor[1]) - int(cursor_pos[1])
            distance = abs(dx) + abs(dy)
            if distance <= 0:
                continue
            reflected_distance = _axis_reflection_cell_set_distance(reflection_cells, target_cells)
            score = (
                float(reflected_distance),
                int(distance),
                -int(len(target_cells)),
            )
            if best_score is None or score < best_score:
                best_score = score
                best = {
                    "mechanic_state_type": "axis_reflection_coverage",
                    "goal_link_type": "reflected_cursor_footprint_matches_targets",
                    "cell": int(cell),
                    "grid_size": (int(grid_w), int(grid_h)),
                    "axis_x": int(axis_x),
                    "axis_value": int(axis_value),
                    "cursor_value": int(cursor_value),
                    "reflection_value": int(reflection_value),
                    "target_value": int(target_value),
                    "cursor_pos": (int(cursor_pos[0]), int(cursor_pos[1])),
                    "target_anchor": (int(target_anchor[0]), int(target_anchor[1])),
                    "cursor_offsets": tuple((int(x), int(y)) for x, y in cursor_offsets),
                    "target_cells": tuple(sorted((int(x), int(y)) for x, y in target_cells)),
                    "target_count": int(len(target_cells)),
                    "distance_to_anchor": int(distance),
                    "reflected_target_distance": int(reflected_distance),
                    "expected_goal_delta": 1.0,
                    "reader_confidence": min(0.95, 0.56 + 0.04 * len(target_cells)),
                    "goal_link_confidence": min(0.95, 0.62 + 0.03 * len(target_cells)),
                }
    if best is not None:
        return best
    return _axis_reflection_multi_cursor_coverage_state(
        cell_sets,
        grid_w=grid_w,
        grid_h=grid_h,
        background_value=background_value,
        cell=cell,
        pixel_counts=value_counts,
    )


def _axis_reflection_cell_size(frame: np.ndarray) -> int:
    # ARC-AGI grid renderers in this suite commonly use 3x3 cells, and ar25's
    # axis/target grammar is only accepted when a dense 3x3 grid is visible.
    if min(frame.shape) >= 60:
        return 3
    return 1


def _axis_reflection_value_cell_sets(frame: np.ndarray, *, cell: int) -> dict[int, frozenset[tuple[int, int]]]:
    out: dict[int, set[tuple[int, int]]] = defaultdict(set)
    height, width = frame.shape
    for y in range(0, height - height % cell):
        gy = y // cell
        for x in range(0, width - width % cell):
            gx = x // cell
            out[int(frame[y, x])].add((gx, gy))
    return {value: frozenset(cells) for value, cells in out.items()}


def _axis_reflection_vertical_axis(
    cell_sets: Mapping[int, frozenset[tuple[int, int]]],
    *,
    grid_h: int,
    background_value: int,
    pixel_counts: Mapping[int, int] | None = None,
) -> tuple[int, int] | None:
    candidates: list[tuple[int, int, int, int, int]] = []
    for value, cells in cell_sets.items():
        if int(value) == int(background_value):
            continue
        by_x: Counter[int] = Counter(int(x) for x, _y in cells)
        if not by_x:
            continue
        x, count = by_x.most_common(1)[0]
        other_count = len(cells) - int(count)
        if count < max(8, int(grid_h * 0.65)):
            continue
        if other_count > max(2, int(count * 0.20)):
            continue
        pixel_count = int((pixel_counts or {}).get(int(value), 0) or 0)
        candidates.append((-int(count), int(other_count), int(x), -pixel_count, int(value)))
    if not candidates:
        return None
    ordered = sorted(candidates)
    if len(ordered) > 1:
        best_geometry = ordered[0][:3]
        if any(candidate[:3] != best_geometry for candidate in ordered):
            return None
        if ordered[0][3] == ordered[1][3]:
            return None
    _neg_count, _other_count, x, _neg_pixel_count, value = ordered[0]
    return int(x), int(value)


def _axis_reflection_horizontal_axis(
    cell_sets: Mapping[int, frozenset[tuple[int, int]]],
    *,
    grid_w: int,
    background_value: int,
    pixel_counts: Mapping[int, int] | None = None,
) -> tuple[int, int] | None:
    candidates: list[tuple[int, int, int, int, int]] = []
    for value, cells in cell_sets.items():
        if int(value) == int(background_value):
            continue
        by_y: Counter[int] = Counter(int(y) for _x, y in cells)
        if not by_y:
            continue
        y, count = by_y.most_common(1)[0]
        other_count = len(cells) - int(count)
        if count < max(8, int(grid_w * 0.65)):
            continue
        if other_count > max(2, int(count * 0.20)):
            continue
        pixel_count = int((pixel_counts or {}).get(int(value), 0) or 0)
        candidates.append((-int(count), int(other_count), int(y), -pixel_count, int(value)))
    if not candidates:
        return None
    ordered = sorted(candidates)
    if len(ordered) > 1:
        best_geometry = ordered[0][:3]
        if any(candidate[:3] != best_geometry for candidate in ordered):
            return None
        if ordered[0][3] == ordered[1][3]:
            return None
    _neg_count, _other_count, y, _neg_pixel_count, value = ordered[0]
    return int(y), int(value)


def _axis_reflection_cell_components(
    cells: frozenset[tuple[int, int]],
) -> list[dict[str, Any]]:
    remaining = set((int(x), int(y)) for x, y in cells)
    components: list[dict[str, Any]] = []
    while remaining:
        start = min(remaining)
        stack = [start]
        remaining.remove(start)
        comp: set[tuple[int, int]] = set()
        while stack:
            x, y = stack.pop()
            comp.add((x, y))
            for nx, ny in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
                if (nx, ny) in remaining:
                    remaining.remove((nx, ny))
                    stack.append((nx, ny))
        min_x = min(x for x, _y in comp)
        max_x = max(x for x, _y in comp)
        min_y = min(y for _x, y in comp)
        max_y = max(y for _x, y in comp)
        components.append(
            {
                "cells": frozenset(comp),
                "pos": (int(min_x), int(min_y)),
                "width": int(max_x - min_x + 1),
                "height": int(max_y - min_y + 1),
                "area": int(len(comp)),
                "offsets": tuple(sorted((int(x - min_x), int(y - min_y)) for x, y in comp)),
            }
        )
    return sorted(components, key=lambda item: (tuple(item["pos"]), int(item["area"])))


def _axis_reflection_proximity_cell_components(
    cells: frozenset[tuple[int, int]],
    *,
    max_chebyshev: int = 5,
) -> list[dict[str, Any]]:
    """Cluster sparse cursor footprints that are one visible sprite.

    Later ar25-style reflection levels render a single cursor as disconnected
    colored cells inside a compact bbox. Four-connectivity splits that sprite
    into fragments, so the multi-axis reader needs the same bounded
    single-linkage clustering used by the perception reader.
    """
    remaining = set((int(x), int(y)) for x, y in cells)
    components: list[dict[str, Any]] = []
    while remaining:
        start = min(remaining)
        stack = [start]
        remaining.remove(start)
        comp: set[tuple[int, int]] = set()
        while stack:
            x, y = stack.pop()
            comp.add((int(x), int(y)))
            neighbors = [
                (nx, ny)
                for nx, ny in remaining
                if abs(int(nx) - int(x)) <= int(max_chebyshev)
                and abs(int(ny) - int(y)) <= int(max_chebyshev)
            ]
            for neighbor in neighbors:
                remaining.remove(neighbor)
                stack.append(neighbor)
        min_x = min(x for x, _y in comp)
        max_x = max(x for x, _y in comp)
        min_y = min(y for _x, y in comp)
        max_y = max(y for _x, y in comp)
        components.append(
            {
                "cells": frozenset(comp),
                "pos": (int(min_x), int(min_y)),
                "width": int(max_x - min_x + 1),
                "height": int(max_y - min_y + 1),
                "area": int(len(comp)),
                "offsets": tuple(sorted((int(x - min_x), int(y - min_y)) for x, y in comp)),
                "component_linkage": "chebyshev_proximity",
                "max_chebyshev": int(max_chebyshev),
            }
        )
    return sorted(components, key=lambda item: (tuple(item["pos"]), int(item["area"])))


def _axis_reflection_delta_plan(
    delta: int,
    *,
    decrement_action: str,
    increment_action: str,
) -> list[str]:
    if int(delta) < 0:
        return [decrement_action] * abs(int(delta))
    if int(delta) > 0:
        return [increment_action] * int(delta)
    return []


def _axis_reflection_move_plan(
    current: tuple[int, int],
    target: tuple[int, int],
) -> list[str]:
    dx = int(target[0]) - int(current[0])
    dy = int(target[1]) - int(current[1])
    return (
        _axis_reflection_delta_plan(dx, decrement_action="ACTION3", increment_action="ACTION4")
        + _axis_reflection_delta_plan(dy, decrement_action="ACTION1", increment_action="ACTION2")
    )


def _axis_reflection_multi_cursor_plan_from_state(state: Mapping[str, Any]) -> list[str] | None:
    if bool(state.get("multi_axis_orbit_reflection")):
        return _axis_reflection_multi_axis_plan_from_state(state)
    cursor_plans = [
        dict(item)
        for item in list(state.get("cursor_plans") or [])
        if isinstance(item, Mapping)
    ]
    if not cursor_plans:
        return None
    cycle_size = max(1, len(cursor_plans) + 1)
    active_index = int(state.get("active_cycle_index", 0) or 0) % cycle_size
    target_axis_position = int(state.get("target_axis_position", 0) or 0)
    orientation = str(state.get("axis_orientation", "") or "")
    if orientation == "horizontal":
        current_axis_position = int(state.get("axis_y", 0) or 0)
        axis_move = _axis_reflection_delta_plan(
            target_axis_position - current_axis_position,
            decrement_action="ACTION1",
            increment_action="ACTION2",
        )
    elif orientation == "vertical":
        current_axis_position = int(state.get("axis_x", 0) or 0)
        axis_move = _axis_reflection_delta_plan(
            target_axis_position - current_axis_position,
            decrement_action="ACTION3",
            increment_action="ACTION4",
        )
    else:
        return None

    plan: list[str] = []

    def switch_to(target_index: int) -> None:
        nonlocal active_index
        cycles = (int(target_index) - int(active_index)) % cycle_size
        if cycles:
            plan.extend(["ACTION5"] * cycles)
            active_index = int(target_index) % cycle_size

    if axis_move:
        switch_to(0)
        plan.extend(axis_move)
    for index, cursor_plan in enumerate(cursor_plans, start=1):
        current = tuple(cursor_plan.get("cursor_pos") or ())
        target = tuple(cursor_plan.get("target_anchor") or ())
        if len(current) < 2 or len(target) < 2:
            return None
        switch_to(index)
        plan.extend(_axis_reflection_move_plan((int(current[0]), int(current[1])), (int(target[0]), int(target[1]))))
    return plan or None


def _axis_reflection_multi_axis_plan_from_state(state: Mapping[str, Any]) -> list[str] | None:
    cursor_plans = [
        dict(item)
        for item in list(state.get("cursor_plans") or [])
        if isinstance(item, Mapping)
    ]
    if not cursor_plans:
        return None
    current_horizontal = int(state.get("axis_y", 0) or 0)
    target_horizontal = int(state.get("target_axis_y", state.get("target_axis_position", 0)) or 0)
    current_vertical = int(state.get("axis_x", 0) or 0)
    target_vertical = int(state.get("target_axis_x", 0) or 0)
    cycle_size = max(1, len(cursor_plans) + 2)
    active_index = int(state.get("active_cycle_index", 0) or 0) % cycle_size
    plan: list[str] = []

    def switch_to(target_index: int) -> None:
        nonlocal active_index
        cycles = (int(target_index) - int(active_index)) % cycle_size
        if cycles:
            plan.extend(["ACTION5"] * cycles)
            active_index = int(target_index) % cycle_size

    horizontal_move = _axis_reflection_delta_plan(
        target_horizontal - current_horizontal,
        decrement_action="ACTION1",
        increment_action="ACTION2",
    )
    if horizontal_move:
        switch_to(0)
        plan.extend(horizontal_move)
    vertical_move = _axis_reflection_delta_plan(
        target_vertical - current_vertical,
        decrement_action="ACTION3",
        increment_action="ACTION4",
    )
    if vertical_move:
        switch_to(1)
        plan.extend(vertical_move)
    for index, cursor_plan in enumerate(cursor_plans, start=2):
        current = tuple(cursor_plan.get("cursor_pos") or ())
        target = tuple(cursor_plan.get("target_anchor") or ())
        if len(current) < 2 or len(target) < 2:
            return None
        cursor_move = _axis_reflection_move_plan(
            (int(current[0]), int(current[1])),
            (int(target[0]), int(target[1])),
        )
        if cursor_move:
            switch_to(index)
            plan.extend(cursor_move)
    return plan or None


def _axis_reflection_reflect_cells(
    cells: frozenset[tuple[int, int]],
    *,
    axis_orientation: str,
    axis_position: int,
) -> frozenset[tuple[int, int]]:
    if axis_orientation == "horizontal":
        return frozenset((int(x), 2 * int(axis_position) - int(y)) for x, y in cells)
    if axis_orientation == "vertical":
        return frozenset((2 * int(axis_position) - int(x), int(y)) for x, y in cells)
    return frozenset()


def _axis_reflection_multi_cursor_solution(
    *,
    axis_orientation: str,
    current_axis_position: int,
    cursor_components: tuple[dict[str, Any], ...],
    target_cells: frozenset[tuple[int, int]],
    grid_w: int,
    grid_h: int,
) -> dict[str, Any] | None:
    axis_range = range(int(grid_h)) if axis_orientation == "horizontal" else range(int(grid_w))
    best: dict[str, Any] | None = None
    best_score: tuple[int, int, int] | None = None
    for axis_position in axis_range:
        candidates_per_cursor: list[list[dict[str, Any]]] = []
        feasible = True
        for component in cursor_components:
            offsets = tuple(component.get("offsets") or ())
            if not offsets:
                feasible = False
                break
            width = int(component.get("width", 0) or 0)
            height = int(component.get("height", 0) or 0)
            candidates: list[dict[str, Any]] = []
            for x in range(0, max(0, int(grid_w) - width) + 1):
                for y in range(0, max(0, int(grid_h) - height) + 1):
                    direct = frozenset((int(x + dx), int(y + dy)) for dx, dy in offsets)
                    reflected = _axis_reflection_reflect_cells(
                        direct,
                        axis_orientation=axis_orientation,
                        axis_position=int(axis_position),
                    )
                    if not direct.issubset(target_cells):
                        continue
                    if not reflected.issubset(target_cells):
                        continue
                    full = direct | reflected
                    if not full:
                        continue
                    candidates.append(
                        {
                            "target_anchor": (int(x), int(y)),
                            "covered": frozenset(full),
                            "distance": abs(int(x) - int(component["pos"][0]))
                            + abs(int(y) - int(component["pos"][1])),
                        }
                    )
            if not candidates:
                feasible = False
                break
            candidates_per_cursor.append(candidates)
        if not feasible:
            continue
        for combo in product(*candidates_per_cursor):
            covered: set[tuple[int, int]] = set()
            for candidate in combo:
                covered.update(candidate["covered"])
            if frozenset(covered) != target_cells:
                continue
            cursor_cost = sum(int(candidate["distance"]) for candidate in combo)
            axis_cost = abs(int(axis_position) - int(current_axis_position))
            action_cost = axis_cost + cursor_cost + len(cursor_components)
            score = (int(action_cost), int(axis_cost), int(cursor_cost))
            if best_score is not None and score >= best_score:
                continue
            best_score = score
            best = {
                "axis_position": int(axis_position),
                "axis_cost": int(axis_cost),
                "cursor_cost": int(cursor_cost),
                "action_cost": int(action_cost),
                "cursor_targets": tuple(tuple(candidate["target_anchor"]) for candidate in combo),
                "cursor_coverages": tuple(tuple(sorted(candidate["covered"])) for candidate in combo),
            }
    return best


def _axis_reflection_multi_axis_candidate(
    cell_sets: Mapping[int, frozenset[tuple[int, int]]],
    *,
    grid_w: int,
    grid_h: int,
    background_value: int,
    pixel_counts: Mapping[int, int] | None = None,
) -> dict[str, Any] | None:
    candidates: list[tuple[int, int, int, int, int, int, int]] = []
    for value, cells in cell_sets.items():
        if int(value) == int(background_value):
            continue
        by_x: Counter[int] = Counter(int(x) for x, _y in cells)
        by_y: Counter[int] = Counter(int(y) for _x, y in cells)
        if not by_x or not by_y:
            continue
        axis_x, vertical_count = by_x.most_common(1)[0]
        axis_y, horizontal_count = by_y.most_common(1)[0]
        if vertical_count < max(8, int(grid_h * 0.65)):
            continue
        if horizontal_count < max(8, int(grid_w * 0.65)):
            continue
        union_cells = {
            cell
            for cell in cells
            if int(cell[0]) == int(axis_x) or int(cell[1]) == int(axis_y)
        }
        off_axis_count = len(cells) - len(union_cells)
        if off_axis_count > max(2, int((vertical_count + horizontal_count) * 0.10)):
            continue
        pixel_count = int((pixel_counts or {}).get(int(value), 0) or 0)
        candidates.append(
            (
                -int(vertical_count + horizontal_count),
                int(off_axis_count),
                -int(pixel_count),
                int(axis_x),
                int(axis_y),
                int(vertical_count),
                int(value),
            )
        )
    if not candidates:
        return None
    ordered = sorted(candidates)
    best = ordered[0]
    if len(ordered) > 1 and ordered[0][:5] == ordered[1][:5]:
        return None
    _neg_count, off_axis_count, _neg_pixel_count, axis_x, axis_y, vertical_count, value = best
    horizontal_count = Counter(
        int(y) for _x, y in cell_sets[int(value)]
    ).most_common(1)[0][1]
    return {
        "axis_value": int(value),
        "axis_x": int(axis_x),
        "axis_y": int(axis_y),
        "vertical_count": int(vertical_count),
        "horizontal_count": int(horizontal_count),
        "off_axis_count": int(off_axis_count),
    }


def _axis_reflection_multi_axis_orbit_solution(
    *,
    current_axis_x: int,
    current_axis_y: int,
    cursor_component: Mapping[str, Any],
    target_cells: frozenset[tuple[int, int]],
    grid_w: int,
    grid_h: int,
) -> dict[str, Any] | None:
    offsets = tuple(cursor_component.get("offsets") or ())
    if not offsets:
        return None
    width = int(cursor_component.get("width", 0) or 0)
    height = int(cursor_component.get("height", 0) or 0)
    cursor_pos = tuple(cursor_component.get("pos") or ())
    if len(cursor_pos) < 2:
        return None
    best: dict[str, Any] | None = None
    best_score: tuple[int, int, int, int] | None = None
    positions: list[tuple[int, int, frozenset[tuple[int, int]]]] = []
    for x in range(0, max(0, int(grid_w) - width) + 1):
        for y in range(0, max(0, int(grid_h) - height) + 1):
            direct = frozenset((int(x + dx), int(y + dy)) for dx, dy in offsets)
            positions.append((int(x), int(y), direct))
    for axis_x in range(int(grid_w)):
        for axis_y in range(int(grid_h)):
            axis_cost = abs(int(axis_x) - int(current_axis_x)) + abs(int(axis_y) - int(current_axis_y))
            for x, y, direct in positions:
                orbit: set[tuple[int, int]] = set()
                for cx, cy in direct:
                    reflected_cells = (
                        (int(cx), int(cy)),
                        (2 * int(axis_x) - int(cx), int(cy)),
                        (int(cx), 2 * int(axis_y) - int(cy)),
                        (2 * int(axis_x) - int(cx), 2 * int(axis_y) - int(cy)),
                    )
                    orbit.update(
                        (int(rx), int(ry))
                        for rx, ry in reflected_cells
                        if 0 <= int(rx) < int(grid_w) and 0 <= int(ry) < int(grid_h)
                    )
                if not target_cells.issubset(orbit):
                    continue
                cursor_cost = abs(int(x) - int(cursor_pos[0])) + abs(int(y) - int(cursor_pos[1]))
                extra_count = len(orbit - target_cells)
                score = (int(axis_cost + cursor_cost), int(extra_count), int(axis_cost), int(cursor_cost))
                if best_score is not None and score >= best_score:
                    continue
                best_score = score
                best = {
                    "axis_x": int(axis_x),
                    "axis_y": int(axis_y),
                    "axis_cost": int(axis_cost),
                    "cursor_cost": int(cursor_cost),
                    "action_cost": int(axis_cost + cursor_cost + 2),
                    "cursor_targets": ((int(x), int(y)),),
                    "cursor_coverages": (tuple(sorted(orbit)),),
                    "orbit_extra_count": int(extra_count),
                }
    return best


def _axis_reflection_multi_axis_orbit_cells(
    offsets: Iterable[tuple[int, int]],
    *,
    pos: tuple[int, int],
    axis_x: int,
    axis_y: int,
    grid_w: int,
    grid_h: int,
) -> frozenset[tuple[int, int]]:
    cells: set[tuple[int, int]] = set()
    for dx, dy in offsets:
        x = int(pos[0]) + int(dx)
        y = int(pos[1]) + int(dy)
        for rx, ry in (
            (x, y),
            (2 * int(axis_x) - x, y),
            (x, 2 * int(axis_y) - y),
            (2 * int(axis_x) - x, 2 * int(axis_y) - y),
        ):
            if 0 <= int(rx) < int(grid_w) and 0 <= int(ry) < int(grid_h):
                cells.add((int(rx), int(ry)))
    return frozenset(cells)


def _axis_reflection_layered_multi_axis_orbit_solution(
    *,
    current_axis_x: int,
    current_axis_y: int,
    cursor_components: tuple[dict[str, Any], ...],
    target_cells: frozenset[tuple[int, int]],
    grid_w: int,
    grid_h: int,
    allow_target_containment: bool = False,
) -> dict[str, Any] | None:
    if not (2 <= len(cursor_components) <= 3):
        return None
    best: dict[str, Any] | None = None
    best_score: tuple[int, int, int, int, int] | None = None
    max_orbit_extra = max(16, int(len(target_cells)))
    target_xs = tuple(int(x) for x, _y in target_cells)
    target_ys = tuple(int(y) for _x, y in target_cells)
    target_bbox: tuple[int, int, int, int] | None = None
    if target_xs and target_ys:
        target_bbox = (
            min(target_xs),
            min(target_ys),
            max(target_xs),
            max(target_ys),
        )
    for axis_x in range(int(grid_w)):
        for axis_y in range(int(grid_h)):
            candidates_per_cursor: list[list[dict[str, Any]]] = []
            feasible = True
            for component in cursor_components:
                offsets = tuple(component.get("offsets") or ())
                if not offsets:
                    feasible = False
                    break
                width = int(component.get("width", 0) or 0)
                height = int(component.get("height", 0) or 0)
                pos = tuple(component.get("pos") or ())
                if len(pos) < 2:
                    feasible = False
                    break
                candidates: list[dict[str, Any]] = []
                max_anchor_x = max(0, int(grid_w) - width)
                max_anchor_y = max(0, int(grid_h) - height)
                if target_bbox is not None:
                    min_tx, min_ty, max_tx, max_ty = target_bbox
                    x_values = range(
                        max(0, int(min_tx) - int(width) - 2),
                        min(max_anchor_x, int(max_tx) + 2) + 1,
                    )
                    y_values = range(
                        max(0, int(min_ty) - int(height) - 2),
                        min(max_anchor_y, int(max_ty) + 2) + 1,
                    )
                else:
                    x_values = range(0, max_anchor_x + 1)
                    y_values = range(0, max_anchor_y + 1)
                for x in x_values:
                    for y in y_values:
                        coverage = _axis_reflection_multi_axis_orbit_cells(
                            offsets,
                            pos=(int(x), int(y)),
                            axis_x=int(axis_x),
                            axis_y=int(axis_y),
                            grid_w=int(grid_w),
                            grid_h=int(grid_h),
                        )
                        if not coverage:
                            continue
                        target_overlap = len(coverage & target_cells)
                        extra_count = len(coverage - target_cells)
                        if coverage.issubset(target_cells):
                            pass
                        elif not allow_target_containment:
                            continue
                        elif target_overlap <= 0 or extra_count > max_orbit_extra:
                            continue
                        candidates.append(
                            {
                                "target_anchor": (int(x), int(y)),
                                "covered": coverage,
                                "target_overlap": int(target_overlap),
                                "extra_count": int(extra_count),
                                "distance": abs(int(x) - int(pos[0])) + abs(int(y) - int(pos[1])),
                            }
                        )
                if not candidates:
                    feasible = False
                    break
                candidates_per_cursor.append(
                    sorted(
                        candidates,
                        key=lambda item: (
                            int(item["extra_count"]) if allow_target_containment else 0,
                            -int(item["target_overlap"]) if allow_target_containment else 0,
                            int(item["distance"]),
                            -len(item["covered"]),
                            tuple(item["target_anchor"]),
                        ),
                    )[: (48 if allow_target_containment else 128)]
                )
            if not feasible:
                continue
            for combo in product(*candidates_per_cursor):
                covered: set[tuple[int, int]] = set()
                cursor_cost = 0
                cursor_targets: list[tuple[int, int]] = []
                cursor_coverages: list[tuple[tuple[int, int], ...]] = []
                for candidate in combo:
                    covered.update(candidate["covered"])
                    cursor_cost += int(candidate["distance"])
                    cursor_targets.append(tuple(candidate["target_anchor"]))
                    cursor_coverages.append(tuple(sorted(candidate["covered"])))
                covered_frozen = frozenset(covered)
                orbit_extra_count = len(covered_frozen - target_cells)
                if covered_frozen == target_cells:
                    target_containment = False
                elif allow_target_containment and target_cells.issubset(covered_frozen):
                    if orbit_extra_count > max_orbit_extra:
                        continue
                    target_containment = True
                else:
                    continue
                axis_cost = abs(int(axis_x) - int(current_axis_x)) + abs(int(axis_y) - int(current_axis_y))
                # Two axis selections plus one selection per cursor bound the
                # actual ACTION5 overhead. The emitter recomputes exact cycles.
                switch_cost = len(cursor_components) + 1
                action_cost = int(axis_cost) + int(cursor_cost) + int(switch_cost)
                score = (
                    int(orbit_extra_count),
                    int(action_cost),
                    int(axis_cost),
                    int(cursor_cost),
                    int(axis_x + axis_y),
                )
                if best_score is not None and score >= best_score:
                    continue
                best_score = score
                best = {
                    "axis_x": int(axis_x),
                    "axis_y": int(axis_y),
                    "axis_cost": int(axis_cost),
                    "cursor_cost": int(cursor_cost),
                    "action_cost": int(action_cost),
                    "cursor_targets": tuple(cursor_targets),
                    "cursor_coverages": tuple(cursor_coverages),
                    "orbit_extra_count": int(orbit_extra_count),
                    "target_containment_coverage": bool(target_containment),
                    "target_covered_count": int(len(target_cells)),
                }
    return best


def _axis_reflection_multi_axis_orbit_coverage_state(
    cell_sets: Mapping[int, frozenset[tuple[int, int]]],
    *,
    grid_w: int,
    grid_h: int,
    background_value: int,
    cell: int,
    multi_axis: Mapping[str, Any],
) -> dict[str, Any] | None:
    axis_value = int(multi_axis.get("axis_value", -1) or -1)
    current_axis_x = int(multi_axis.get("axis_x", 0) or 0)
    current_axis_y = int(multi_axis.get("axis_y", 0) or 0)
    candidate_cursor_values: list[tuple[int, list[dict[str, Any]]]] = []
    for value, cells in cell_sets.items():
        if int(value) in {int(background_value), axis_value}:
            continue
        components = [
            component
            for component in _axis_reflection_proximity_cell_components(cells)
            if 4 <= int(component.get("area", 0) or 0) <= 32
            and 1 <= int(component.get("width", 0) or 0) <= 8
            and 1 <= int(component.get("height", 0) or 0) <= 8
        ]
        if components:
            candidate_cursor_values.append((int(value), components))
    max_target_count = 96 if _eca_env_flag("ECA_ENABLE_AXIS_REFLECTION_BROAD_TARGET_ORBIT") else 32
    target_value_candidates = [
        (int(value), frozenset(cells))
        for value, cells in cell_sets.items()
        if int(value) not in {int(background_value), axis_value}
        and 20 <= len(cells) <= int(max_target_count)
    ]
    cursor_component_count = sum(
        1
        for _value, components in candidate_cursor_values
        for component in components
        if 8 <= int(component.get("area", 0) or 0) <= 16
    )
    if cursor_component_count < 1 or not target_value_candidates:
        return None
    best: dict[str, Any] | None = None
    best_score: tuple[int, int, int, int] | None = None
    for cursor_value, components in candidate_cursor_values:
        for component in components:
            cursor_area = int(component.get("area", 0) or 0)
            if not (8 <= cursor_area <= 16):
                continue
            for target_value, target_cells_raw in target_value_candidates:
                if int(target_value) == int(cursor_value):
                    continue
                target_cells = frozenset(
                    (int(x), int(y))
                    for x, y in target_cells_raw
                    if 0 <= int(x) < int(grid_w) and 0 <= int(y) < int(grid_h)
                )
                if not (16 <= len(target_cells) <= 96):
                    continue
                if len(target_cells) < cursor_area:
                    continue
                solution = _axis_reflection_multi_axis_orbit_solution(
                    current_axis_x=current_axis_x,
                    current_axis_y=current_axis_y,
                    cursor_component=component,
                    target_cells=target_cells,
                    grid_w=grid_w,
                    grid_h=grid_h,
                )
                if solution is None:
                    continue
                score = (
                    int(solution.get("action_cost", 0) or 0),
                    int(solution.get("orbit_extra_count", 0) or 0),
                    -int(len(target_cells)),
                    int(cursor_value),
                )
                if best_score is not None and score >= best_score:
                    continue
                target_anchor = tuple((solution.get("cursor_targets") or (()))[0])
                cursor_pos = tuple(component.get("pos") or ())
                cursor_plan = {
                    "cursor_pos": (int(cursor_pos[0]), int(cursor_pos[1])),
                    "target_anchor": (int(target_anchor[0]), int(target_anchor[1])),
                    "cursor_offsets": tuple(component.get("offsets") or ()),
                    "cursor_area": int(cursor_area),
                }
                plan_state = {
                    "mechanic_state_type": "axis_reflection_coverage",
                    "goal_link_type": "multi_axis_orbit_covers_targets",
                    "cell": int(cell),
                    "grid_size": (int(grid_w), int(grid_h)),
                    "axis_orientation": "multi_axis",
                    "axis_x": int(current_axis_x),
                    "axis_y": int(current_axis_y),
                    "axis_value": int(axis_value),
                    "target_axis_x": int(solution["axis_x"]),
                    "target_axis_y": int(solution["axis_y"]),
                    "target_axis_position": int(solution["axis_y"]),
                    "cursor_value": int(cursor_value),
                    "target_value": int(target_value),
                    "cursor_pos": (int(cursor_pos[0]), int(cursor_pos[1])),
                    "target_anchor": (int(target_anchor[0]), int(target_anchor[1])),
                    "cursor_offsets": tuple(component.get("offsets") or ()),
                    "target_cells": tuple(sorted((int(x), int(y)) for x, y in target_cells)),
                    "target_count": int(len(target_cells)),
                    "cursor_count": 1,
                    "multi_cursor_axis_reflection": True,
                    "multi_axis_orbit_reflection": True,
                    "cursor_plans": (cursor_plan,),
                    "axis_cost": int(solution.get("axis_cost", 0) or 0),
                    "cursor_cost": int(solution.get("cursor_cost", 0) or 0),
                    "orbit_extra_count": int(solution.get("orbit_extra_count", 0) or 0),
                    "expected_goal_delta": 1.0,
                    "reader_confidence": min(0.95, 0.58 + 0.01 * len(target_cells)),
                    "goal_link_confidence": min(0.95, 0.64 + 0.01 * len(target_cells)),
                }
                plan = _axis_reflection_multi_axis_plan_from_state(plan_state)
                if not plan:
                    continue
                plan_state["operation_plan_len"] = int(len(plan))
                plan_state["precomputed_operation_plan"] = tuple(plan)
                best_score = score
                best = plan_state
    return best


def _axis_reflection_layered_orbit_sensor_state(
    cell_sets: Mapping[int, frozenset[tuple[int, int]]],
    *,
    grid_w: int,
    grid_h: int,
    background_value: int,
    cell: int,
    multi_axis: Mapping[str, Any],
) -> dict[str, Any] | None:
    sensor_enabled = _eca_env_flag("ECA_ENABLE_AXIS_REFLECTION_LAYERED_ORBIT_SENSOR")
    planner_enabled = _eca_env_flag("ECA_ENABLE_AXIS_REFLECTION_LAYERED_ORBIT_PLANNER")
    if not (sensor_enabled or planner_enabled):
        return None
    axis_value = int(multi_axis.get("axis_value", -1) or -1)
    current_axis_x = int(multi_axis.get("axis_x", 0) or 0)
    current_axis_y = int(multi_axis.get("axis_y", 0) or 0)
    candidate_components: list[tuple[int, dict[str, Any]]] = []
    for value, cells in cell_sets.items():
        if int(value) in {int(background_value), axis_value}:
            continue
        for component in _axis_reflection_proximity_cell_components(cells):
            area = int(component.get("area", 0) or 0)
            width = int(component.get("width", 0) or 0)
            height = int(component.get("height", 0) or 0)
            if 4 <= area <= 32 and 1 <= width <= 12 and 1 <= height <= 12:
                candidate_components.append((int(value), component))
    target_candidates = [
        (int(value), frozenset(cells))
        for value, cells in cell_sets.items()
        if int(value) not in {int(background_value), axis_value}
        and 33 <= len(cells) <= 96
    ]
    if not candidate_components or not target_candidates:
        return None
    target_value, target_cells = max(target_candidates, key=lambda item: len(item[1]))

    if planner_enabled:
        best_plan_state: dict[str, Any] | None = None
        best_score: tuple[int, int, int, int] | None = None
        for cursor_value, cells in cell_sets.items():
            if int(cursor_value) in {int(background_value), axis_value, int(target_value)}:
                continue
            sprite_components = [
                component
                for component in _axis_reflection_proximity_cell_components(
                    cells,
                    max_chebyshev=1,
                )
                if 4 <= int(component.get("area", 0) or 0) <= 32
                and 1 <= int(component.get("width", 0) or 0) <= 12
                and 1 <= int(component.get("height", 0) or 0) <= 12
                and not all(
                    int(component.get("pos", (0, 0))[0]) + int(dx) == int(current_axis_x)
                    or int(component.get("pos", (0, 0))[1]) + int(dy) == int(current_axis_y)
                    for dx, dy in tuple(component.get("offsets") or ())
                )
            ]
            sprite_components = sorted(
                sprite_components,
                key=lambda item: (
                    int(item.get("area", 0) or 0),
                    tuple(item.get("pos") or ()),
                ),
            )
            if not (2 <= len(sprite_components) <= 3):
                continue
            containment_fallback_allowed = (
                _eca_env_flag("ECA_ENABLE_AXIS_REFLECTION_TARGET_CONTAINMENT_ORBIT_PLANNER")
                and len(sprite_components) == 2
                and 36 <= len(target_cells) <= 48
            )
            solution: dict[str, Any] | None = None
            solution_components: tuple[dict[str, Any], ...] = ()
            solution_order_score: tuple[int, int, int, int, tuple[int, ...]] | None = None
            for component_order in permutations(range(len(sprite_components))):
                ordered_components = tuple(sprite_components[int(index)] for index in component_order)
                candidate_solution = _axis_reflection_layered_multi_axis_orbit_solution(
                    current_axis_x=current_axis_x,
                    current_axis_y=current_axis_y,
                    cursor_components=ordered_components,
                    target_cells=target_cells,
                    grid_w=grid_w,
                    grid_h=grid_h,
                    allow_target_containment=False,
                )
                if candidate_solution is None and containment_fallback_allowed:
                    candidate_solution = _axis_reflection_layered_multi_axis_orbit_solution(
                        current_axis_x=current_axis_x,
                        current_axis_y=current_axis_y,
                        cursor_components=ordered_components,
                        target_cells=target_cells,
                        grid_w=grid_w,
                        grid_h=grid_h,
                        allow_target_containment=True,
                    )
                if candidate_solution is None:
                    continue
                cursor_targets_for_order = tuple(
                    tuple(item) for item in candidate_solution.get("cursor_targets") or ()
                )
                if len(cursor_targets_for_order) != len(ordered_components):
                    continue
                first_pos = tuple(ordered_components[0].get("pos") or ())
                first_target = tuple(cursor_targets_for_order[0])
                if len(first_pos) < 2 or len(first_target) < 2:
                    continue
                first_move_distance = abs(int(first_target[0]) - int(first_pos[0])) + abs(
                    int(first_target[1]) - int(first_pos[1])
                )
                order_score = (
                    int(candidate_solution.get("action_cost", 0) or 0),
                    int(candidate_solution.get("axis_cost", 0) or 0),
                    int(candidate_solution.get("cursor_cost", 0) or 0),
                    -int(first_move_distance),
                    tuple(int(index) for index in component_order),
                )
                if solution_order_score is not None and order_score >= solution_order_score:
                    continue
                solution = candidate_solution
                solution_components = ordered_components
                solution_order_score = order_score
            if solution is None:
                continue
            cursor_targets = tuple(tuple(item) for item in solution.get("cursor_targets") or ())
            if len(cursor_targets) != len(solution_components):
                continue
            cursor_plans: list[dict[str, Any]] = []
            for component, target_anchor, coverage in zip(
                solution_components,
                cursor_targets,
                tuple(solution.get("cursor_coverages") or ()),
            ):
                cursor_pos = tuple(component.get("pos") or ())
                if len(cursor_pos) < 2 or len(target_anchor) < 2:
                    cursor_plans = []
                    break
                cursor_plans.append(
                    {
                        "cursor_pos": (int(cursor_pos[0]), int(cursor_pos[1])),
                        "target_anchor": (int(target_anchor[0]), int(target_anchor[1])),
                        "cursor_offsets": tuple(component.get("offsets") or ()),
                        "cursor_area": int(component.get("area", 0) or 0),
                        "covered_count": int(len(tuple(coverage))),
                        "component_linkage": str(component.get("component_linkage", "") or ""),
                    }
                )
            if len(cursor_plans) != len(solution_components):
                continue
            first_cursor = cursor_plans[0]
            plan_state = {
                "mechanic_state_type": "axis_reflection_coverage",
                "goal_link_type": "layered_multi_cursor_multi_axis_orbit_covers_targets",
                "diagnostic_only": False,
                "cell": int(cell),
                "grid_size": (int(grid_w), int(grid_h)),
                "axis_orientation": "multi_axis",
                "axis_x": int(current_axis_x),
                "axis_y": int(current_axis_y),
                "axis_value": int(axis_value),
                "target_axis_x": int(solution["axis_x"]),
                "target_axis_y": int(solution["axis_y"]),
                "target_axis_position": int(solution["axis_y"]),
                "target_value": int(target_value),
                "target_cells": tuple(sorted((int(x), int(y)) for x, y in target_cells)),
                "target_count": int(len(target_cells)),
                "cursor_value": int(cursor_value),
                "cursor_pos": tuple(first_cursor["cursor_pos"]),
                "target_anchor": tuple(first_cursor["target_anchor"]),
                "cursor_offsets": tuple(first_cursor["cursor_offsets"]),
                "cursor_count": int(len(cursor_plans)),
                "cursor_component_count": int(len(cursor_plans)),
                "cursor_component_ordering": "max_first_move_distance_visible_cycle_prior",
                "cursor_plans": tuple(cursor_plans),
                "multi_cursor_axis_reflection": True,
                "multi_axis_orbit_reflection": True,
                "layer_decomposition_required": True,
                "broad_target_orbit_candidate": True,
                "axis_cost": int(solution.get("axis_cost", 0) or 0),
                "cursor_cost": int(solution.get("cursor_cost", 0) or 0),
                "orbit_extra_count": int(solution.get("orbit_extra_count", 0) or 0),
                "target_containment_coverage": bool(
                    solution.get("target_containment_coverage")
                ),
                "target_covered_count": int(solution.get("target_covered_count", 0) or 0),
                "expected_goal_delta": 1.0,
                "reader_confidence": min(0.95, 0.58 + 0.005 * len(target_cells)),
                "goal_link_confidence": min(0.95, 0.60 + 0.005 * len(target_cells)),
            }
            plan = _axis_reflection_multi_axis_plan_from_state(plan_state)
            if not plan:
                continue
            score = (
                int(len(plan)),
                int(plan_state["axis_cost"]),
                int(plan_state["cursor_cost"]),
                int(cursor_value),
            )
            if best_score is not None and score >= best_score:
                continue
            plan_state["operation_plan_len"] = int(len(plan))
            plan_state["precomputed_operation_plan"] = tuple(plan)
            best_score = score
            best_plan_state = plan_state
        if best_plan_state is not None:
            return best_plan_state

    cursor_value, component = max(
        candidate_components,
        key=lambda item: (
            int(item[1].get("area", 0) or 0),
            int(item[1].get("width", 0) or 0) * int(item[1].get("height", 0) or 0),
        ),
    )
    cursor_pos = tuple(component.get("pos") or ())
    return {
        "mechanic_state_type": "axis_reflection_coverage",
        "goal_link_type": "layered_multi_axis_orbit_requires_decomposition",
        "diagnostic_only": True,
        "cell": int(cell),
        "grid_size": (int(grid_w), int(grid_h)),
        "axis_orientation": "multi_axis",
        "axis_x": int(multi_axis.get("axis_x", 0) or 0),
        "axis_y": int(multi_axis.get("axis_y", 0) or 0),
        "axis_value": int(axis_value),
        "target_value": int(target_value),
        "target_cells": tuple(sorted((int(x), int(y)) for x, y in target_cells)),
        "target_count": int(len(target_cells)),
        "cursor_value": int(cursor_value),
        "cursor_pos": (int(cursor_pos[0]), int(cursor_pos[1])) if len(cursor_pos) >= 2 else (0, 0),
        "cursor_offsets": tuple(component.get("offsets") or ()),
        "cursor_count": int(len(candidate_components)),
        "cursor_component_count": int(len(candidate_components)),
        "cursor_component_summaries": tuple(
            {
                "value": int(value),
                "pos": tuple(comp.get("pos") or ()),
                "width": int(comp.get("width", 0) or 0),
                "height": int(comp.get("height", 0) or 0),
                "area": int(comp.get("area", 0) or 0),
                "component_linkage": str(comp.get("component_linkage", "") or ""),
            }
            for value, comp in candidate_components[:6]
        ),
        "layer_decomposition_required": True,
        "broad_target_orbit_candidate": True,
        "operation_plan_len": 0,
        "precomputed_operation_plan": (),
        "reader_confidence": min(0.9, 0.50 + 0.005 * len(target_cells)),
        "goal_link_confidence": 0.0,
    }


def _axis_reflection_multi_cursor_coverage_state(
    cell_sets: Mapping[int, frozenset[tuple[int, int]]],
    *,
    grid_w: int,
    grid_h: int,
    background_value: int,
    cell: int,
    pixel_counts: Mapping[int, int] | None = None,
) -> dict[str, Any] | None:
    multi_axis = _axis_reflection_multi_axis_candidate(
        cell_sets,
        grid_w=grid_w,
        grid_h=grid_h,
        background_value=background_value,
        pixel_counts=pixel_counts,
    )
    if multi_axis is not None:
        state = _axis_reflection_multi_axis_orbit_coverage_state(
            cell_sets,
            grid_w=grid_w,
            grid_h=grid_h,
            background_value=background_value,
            cell=cell,
            multi_axis=multi_axis,
        )
        if state is not None:
            return state
        layered_state = _axis_reflection_layered_orbit_sensor_state(
            cell_sets,
            grid_w=grid_w,
            grid_h=grid_h,
            background_value=background_value,
            cell=cell,
            multi_axis=multi_axis,
        )
        if layered_state is not None:
            return layered_state

    axes: list[dict[str, Any]] = []
    vertical = _axis_reflection_vertical_axis(
        cell_sets,
        grid_h=grid_h,
        background_value=background_value,
        pixel_counts=pixel_counts,
    )
    if vertical is not None:
        axis_x, axis_value = vertical
        axes.append(
            {
                "orientation": "vertical",
                "position": int(axis_x),
                "value": int(axis_value),
            }
        )
    horizontal = _axis_reflection_horizontal_axis(
        cell_sets,
        grid_w=grid_w,
        background_value=background_value,
        pixel_counts=pixel_counts,
    )
    if horizontal is not None:
        axis_y, axis_value = horizontal
        axes.append(
            {
                "orientation": "horizontal",
                "position": int(axis_y),
                "value": int(axis_value),
            }
        )
    if not axes:
        return None

    best: dict[str, Any] | None = None
    best_score: tuple[int, int, int, int] | None = None
    for axis in axes:
        axis_value = int(axis["value"])
        candidate_cursor_values: list[tuple[int, list[dict[str, Any]]]] = []
        for value, cells in cell_sets.items():
            if int(value) in {int(background_value), axis_value}:
                continue
            components = [
                component
                for component in _axis_reflection_cell_components(cells)
                if 2 <= int(component.get("area", 0) or 0) <= 16
                and 1 <= int(component.get("width", 0) or 0) <= 6
                and 1 <= int(component.get("height", 0) or 0) <= 6
            ]
            if len(components) >= 2:
                candidate_cursor_values.append((int(value), components))
        for cursor_value, components in candidate_cursor_values:
            max_cursor_count = min(2, len(components))
            for cursor_count in range(2, max_cursor_count + 1):
                for cursor_components in combinations(components, cursor_count):
                    cursor_components_tuple = tuple(
                        sorted(cursor_components, key=lambda item: tuple(item["pos"]))
                    )
                    cursor_cell_total = sum(int(item["area"]) for item in cursor_components_tuple)
                    for target_value, target_cells_raw in cell_sets.items():
                        if int(target_value) in {int(background_value), axis_value, int(cursor_value)}:
                            continue
                        target_cells = frozenset(
                            (int(x), int(y))
                            for x, y in target_cells_raw
                            if 0 <= int(x) < int(grid_w) and 0 <= int(y) < int(grid_h)
                        )
                        # Phase823 promoted the visible L3 two-cursor /
                        # 26-target grammar; Phase824 extends the same
                        # one-axis, two-component coverage test to the L4
                        # 24-target grammar. Broader multi-axis target counts
                        # still need separate controls before ranking.
                        if len(target_cells) not in {24, 26}:
                            continue
                        if len(target_cells) < max(8, cursor_cell_total):
                            continue
                        if len(target_cells) > 96:
                            continue
                        solution = _axis_reflection_multi_cursor_solution(
                            axis_orientation=str(axis["orientation"]),
                            current_axis_position=int(axis["position"]),
                            cursor_components=cursor_components_tuple,
                            target_cells=target_cells,
                            grid_w=int(grid_w),
                            grid_h=int(grid_h),
                        )
                        if solution is None:
                            continue
                        plan: list[str] = []
                        if str(axis["orientation"]) == "horizontal":
                            plan.extend(
                                _axis_reflection_delta_plan(
                                    int(solution["axis_position"]) - int(axis["position"]),
                                    decrement_action="ACTION1",
                                    increment_action="ACTION2",
                                )
                            )
                        else:
                            plan.extend(
                                _axis_reflection_delta_plan(
                                    int(solution["axis_position"]) - int(axis["position"]),
                                    decrement_action="ACTION3",
                                    increment_action="ACTION4",
                                )
                            )
                        cursor_targets = tuple(solution["cursor_targets"])
                        cursor_plans: list[dict[str, Any]] = []
                        for component, target_anchor in zip(cursor_components_tuple, cursor_targets):
                            plan.append("ACTION5")
                            move_plan = _axis_reflection_move_plan(tuple(component["pos"]), tuple(target_anchor))
                            plan.extend(move_plan)
                            cursor_plans.append(
                                {
                                    "cursor_pos": tuple(component["pos"]),
                                    "target_anchor": tuple(target_anchor),
                                    "cursor_offsets": tuple(component.get("offsets") or ()),
                                    "move_plan_len": int(len(move_plan)),
                                    "covered_count": int(
                                        len(solution["cursor_coverages"][len(cursor_plans)])
                                    ),
                                }
                            )
                        if not plan:
                            continue
                        score = (
                            int(solution["action_cost"]),
                            -int(len(target_cells)),
                            int(cursor_count),
                            int(target_value),
                        )
                        if best_score is not None and score >= best_score:
                            continue
                        first_cursor = cursor_plans[0]
                        best_score = score
                        best = {
                            "mechanic_state_type": "axis_reflection_coverage",
                            "goal_link_type": "multi_cursor_axis_reflection_covers_targets",
                            "cell": int(cell),
                            "grid_size": (int(grid_w), int(grid_h)),
                            "axis_orientation": str(axis["orientation"]),
                            "axis_x": int(axis["position"]) if str(axis["orientation"]) == "vertical" else 0,
                            "axis_y": int(axis["position"]) if str(axis["orientation"]) == "horizontal" else 0,
                            "target_axis_position": int(solution["axis_position"]),
                            "axis_value": int(axis_value),
                            "cursor_value": int(cursor_value),
                            "reflection_value": int(cursor_value),
                            "target_value": int(target_value),
                            "cursor_pos": tuple(first_cursor["cursor_pos"]),
                            "target_anchor": tuple(first_cursor["target_anchor"]),
                            "cursor_offsets": tuple(first_cursor["cursor_offsets"]),
                            "cursor_plans": tuple(cursor_plans),
                            "cursor_count": int(cursor_count),
                            "target_cells": tuple(sorted((int(x), int(y)) for x, y in target_cells)),
                            "target_count": int(len(target_cells)),
                            "distance_to_anchor": int(solution["action_cost"]),
                            "reflected_target_distance": 0,
                            "expected_goal_delta": 1.0,
                            "multi_cursor_axis_reflection": True,
                            "operation_plan_len": int(len(plan)),
                            "precomputed_operation_plan": tuple(plan),
                            "reader_confidence": min(0.95, 0.58 + 0.02 * len(target_cells)),
                            "goal_link_confidence": min(0.95, 0.64 + 0.02 * len(target_cells)),
                        }
    return best


def _axis_reflection_dense_value(
    value: int,
    cells: frozenset[tuple[int, int]],
    frame: np.ndarray,
    *,
    cell: int,
) -> bool:
    pixel_count = int((frame == int(value)).sum())
    return pixel_count >= max(12, len(cells) * max(3, cell))


def _axis_reflection_target_anchor(
    cursor_offsets: tuple[tuple[int, int], ...],
    *,
    axis_x: int,
    targets: frozenset[tuple[int, int]],
) -> tuple[int, int] | None:
    for tx, ty in sorted(targets):
        for px, py in cursor_offsets:
            anchor = (2 * int(axis_x) - int(tx) - int(px), int(ty) - int(py))
            reflected = frozenset(
                (2 * int(axis_x) - int(anchor[0]) - int(qx), int(anchor[1]) + int(qy))
                for qx, qy in cursor_offsets
            )
            if reflected == targets:
                return int(anchor[0]), int(anchor[1])
    return None


def _axis_reflection_cell_set_distance(
    source: frozenset[tuple[int, int]],
    target: frozenset[tuple[int, int]],
) -> int:
    if not source or not target:
        return 0
    sx = sum(x for x, _y in source) / float(len(source))
    sy = sum(y for _x, y in source) / float(len(source))
    tx = sum(x for x, _y in target) / float(len(target))
    ty = sum(y for _x, y in target) / float(len(target))
    return int(round(abs(sx - tx) + abs(sy - ty)))


def _axis_reflection_coverage_action(
    state: Mapping[str, Any] | None,
    available: set[str],
) -> str | None:
    if state is None:
        return None
    plan = _axis_reflection_coverage_plan(state, available)
    if plan:
        return str(plan[0])
    cursor = tuple(state.get("cursor_pos") or ())
    target = tuple(state.get("target_anchor") or ())
    if len(cursor) < 2 or len(target) < 2:
        return None
    dx = int(target[0]) - int(cursor[0])
    dy = int(target[1]) - int(cursor[1])
    if dx < 0 and "ACTION3" in available:
        return "ACTION3"
    if dx > 0 and "ACTION4" in available:
        return "ACTION4"
    if dy < 0 and "ACTION1" in available:
        return "ACTION1"
    if dy > 0 and "ACTION2" in available:
        return "ACTION2"
    return None


def _axis_reflection_coverage_plan(
    state: Mapping[str, Any] | None,
    available: set[str],
) -> list[str] | None:
    if state is None:
        return None
    if bool(state.get("diagnostic_only")):
        return None
    if bool(state.get("multi_cursor_axis_reflection")):
        dynamic_plan = _axis_reflection_multi_cursor_plan_from_state(state)
        if dynamic_plan:
            if not all(action in available for action in dynamic_plan):
                return None
            return list(dynamic_plan)
    precomputed = tuple(str(action) for action in (state.get("precomputed_operation_plan") or ()))
    if precomputed:
        if not all(action in available for action in precomputed):
            return None
        return list(precomputed)
    cursor = tuple(state.get("cursor_pos") or ())
    target = tuple(state.get("target_anchor") or ())
    if len(cursor) < 2 or len(target) < 2:
        return None
    dx = int(target[0]) - int(cursor[0])
    dy = int(target[1]) - int(cursor[1])
    plan: list[str] = []
    if dx < 0:
        if "ACTION3" not in available:
            return None
        plan.extend(["ACTION3"] * abs(dx))
    elif dx > 0:
        if "ACTION4" not in available:
            return None
        plan.extend(["ACTION4"] * dx)
    if dy < 0:
        if "ACTION1" not in available:
            return None
        plan.extend(["ACTION1"] * abs(dy))
    elif dy > 0:
        if "ACTION2" not in available:
            return None
        plan.extend(["ACTION2"] * dy)
    return plan or None


def _compact_axis_reflection_coverage_state(state: Mapping[str, Any] | None) -> dict[str, Any] | None:
    if state is None:
        return None
    return {
        "mechanic_state_type": str(state.get("mechanic_state_type", "") or ""),
        "goal_link_type": str(state.get("goal_link_type", "") or ""),
        "axis_orientation": str(state.get("axis_orientation", "") or ""),
        "axis_x": int(state.get("axis_x", 0) or 0),
        "axis_y": int(state.get("axis_y", 0) or 0),
        "target_axis_x": int(state.get("target_axis_x", 0) or 0),
        "target_axis_y": int(state.get("target_axis_y", 0) or 0),
        "target_axis_position": int(state.get("target_axis_position", 0) or 0),
        "cursor_pos": list(state.get("cursor_pos") or []),
        "target_anchor": list(state.get("target_anchor") or []),
        "cursor_count": int(state.get("cursor_count", 1) or 1),
        "target_count": int(state.get("target_count", 0) or 0),
        "distance_to_anchor": int(state.get("distance_to_anchor", 0) or 0),
        "reflected_target_distance": int(state.get("reflected_target_distance", 0) or 0),
        "diagnostic_only": bool(state.get("diagnostic_only")),
        "layer_decomposition_required": bool(state.get("layer_decomposition_required")),
        "cursor_component_count": int(state.get("cursor_component_count", 0) or 0),
        "broad_target_orbit_candidate": bool(state.get("broad_target_orbit_candidate")),
        "multi_cursor_axis_reflection": bool(state.get("multi_cursor_axis_reflection")),
        "multi_axis_orbit_reflection": bool(state.get("multi_axis_orbit_reflection")),
        "orbit_extra_count": int(state.get("orbit_extra_count", 0) or 0),
        "operation_plan_len": int(state.get("operation_plan_len", 0) or 0),
        "precomputed_operation_plan_len": len(tuple(state.get("precomputed_operation_plan") or ())),
        "reader_confidence": float(state.get("reader_confidence", 0.0) or 0.0),
        "goal_link_confidence": float(state.get("goal_link_confidence", 0.0) or 0.0),
    }


def _sprite_anchor_cell_sample(frame: np.ndarray, *, cell: int = 3) -> tuple[dict[tuple[int, int], int], int]:
    arr = np.asarray(frame)
    if arr.ndim == 3:
        arr = arr[-1]
    if arr.ndim != 2 or arr.shape[0] < 24 or arr.shape[1] < 24:
        return {}, 0
    grid_w = arr.shape[1] // cell
    grid_h = arr.shape[0] // cell
    values: dict[tuple[int, int], int] = {}
    for y in range(grid_h):
        cy = y * cell + min(2, cell - 1)
        if cy >= arr.shape[0]:
            continue
        for x in range(grid_w):
            cx = x * cell + min(2, cell - 1)
            if cx >= arr.shape[1]:
                continue
            values[(int(x), int(y))] = int(arr[cy, cx])
    if not values:
        return {}, 0
    background = Counter(values.values()).most_common(1)[0][0]
    return values, int(background)


def _cn04_anchors(frame: np.ndarray, anchor_color: int) -> list[tuple[int, int]]:
    values, _background = _sprite_anchor_cell_sample(frame)
    return sorted(
        (int(x), int(y))
        for (x, y), value in values.items()
        if int(value) == int(anchor_color)
    )


def _cn04_pairs(anchors: Sequence[tuple[int, int]]) -> list[tuple[tuple[int, int], tuple[int, int]]]:
    points = [tuple((int(x), int(y))) for x, y in anchors]
    remaining = set(range(len(points)))
    pairs: list[tuple[tuple[int, int], tuple[int, int]]] = []
    while remaining:
        i = min(remaining)
        remaining.remove(i)
        best: tuple[int, int] | None = None
        for j in sorted(remaining):
            dist = abs(points[i][0] - points[j][0]) + abs(points[i][1] - points[j][1])
            if dist > 10:
                continue
            score = (int(dist), int(j))
            if best is None or score < best:
                best = score
        if best is None:
            continue
        _dist, j = best
        remaining.remove(j)
        pairs.append((points[i], points[j]))
    return pairs


def _cn04_anchor_color(frame: np.ndarray) -> int | None:
    values, background = _sprite_anchor_cell_sample(frame)
    if not values:
        return None
    by_value: dict[int, list[tuple[int, int]]] = defaultdict(list)
    for cell, value in values.items():
        if int(value) == int(background):
            continue
        by_value[int(value)].append(cell)
    candidates: list[tuple[int, int, int]] = []
    for value, anchors in by_value.items():
        if len(anchors) < 4 or len(anchors) > 16:
            continue
        remaining = set(anchors)
        component_sizes: list[int] = []
        while remaining:
            start = min(remaining)
            stack = [start]
            remaining.remove(start)
            size = 0
            while stack:
                x, y = stack.pop()
                size += 1
                for nb in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
                    if nb in remaining:
                        remaining.remove(nb)
                        stack.append(nb)
            component_sizes.append(size)
        small_component_count = sum(1 for size in component_sizes if size <= 2)
        if small_component_count < 4:
            continue
        pair_count = len(_cn04_pairs(anchors))
        if pair_count < 2:
            continue
        candidates.append((-int(small_component_count), -int(pair_count), int(len(anchors)), int(value)))
    if not candidates:
        return None
    return int(sorted(candidates)[0][3])


def _sprite_anchor_components(
    values: Mapping[tuple[int, int], int],
    *,
    background: int,
    anchor_color: int,
) -> list[dict[str, Any]]:
    candidates = {
        cell
        for cell, value in values.items()
        if int(value) != int(background)
        and not (int(value) == 4 and int(cell[1]) <= 1)
    }
    remaining = set(candidates)
    components: list[dict[str, Any]] = []
    while remaining:
        start = min(remaining)
        stack = [start]
        remaining.remove(start)
        cells: set[tuple[int, int]] = set()
        while stack:
            x, y = stack.pop()
            cells.add((int(x), int(y)))
            for nb in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
                if nb in remaining:
                    remaining.remove(nb)
                    stack.append(nb)
        anchors = sorted(cell for cell in cells if int(values[cell]) == int(anchor_color))
        if len(anchors) < 2:
            continue
        min_x = min(x for x, _y in cells)
        max_x = max(x for x, _y in cells)
        min_y = min(y for _x, y in cells)
        max_y = max(y for _x, y in cells)
        components.append(
            {
                "cells": frozenset(cells),
                "anchors": tuple(anchors),
                "pos": (int(min_x), int(min_y)),
                "width": int(max_x - min_x + 1),
                "height": int(max_y - min_y + 1),
                "area": int(len(cells)),
                "anchor_count": int(len(anchors)),
            }
        )
    return sorted(components, key=lambda item: (tuple(item["pos"]), int(item["area"])))


def _sprite_anchor_rotate_rel(
    cells: set[tuple[int, int]] | frozenset[tuple[int, int]],
    *,
    width: int,
    height: int,
    rotations: int,
) -> tuple[frozenset[tuple[int, int]], int, int]:
    pts = set((int(x), int(y)) for x, y in cells)
    w = int(width)
    h = int(height)
    for _ in range(int(rotations) % 4):
        pts = {(int(h - 1 - y), int(x)) for x, y in pts}
        w, h = h, w
    return frozenset(pts), int(w), int(h)


def _sprite_anchor_overlap_state(frame: np.ndarray) -> dict[str, Any] | None:
    values, background = _sprite_anchor_cell_sample(frame)
    if not values:
        return None
    anchor_color = _cn04_anchor_color(frame)
    if anchor_color is None:
        return None
    components = [
        component
        for component in _sprite_anchor_components(
            values,
            background=background,
            anchor_color=anchor_color,
        )
        if int(component.get("anchor_count", 0) or 0) >= 2
        and 4 <= int(component.get("area", 0) or 0) <= 64
    ]
    chain_state = _sprite_anchor_overlap_chain_state(
        components,
        grid_w=max(x for x, _y in values) + 1,
        grid_h=max(y for _x, y in values) + 1,
        anchor_color=int(anchor_color),
    )
    if chain_state is not None:
        return chain_state
    if len(components) != 2:
        return None
    active, target = sorted(
        components,
        key=lambda item: (
            int(item["pos"][0]) * int(item["pos"][0])
            + int(item["pos"][1]) * int(item["pos"][1]),
            tuple(item["pos"]),
        ),
    )
    active_pos = tuple(active["pos"])
    active_rel_anchors = frozenset(
        (int(x - active_pos[0]), int(y - active_pos[1]))
        for x, y in active["anchors"]
    )
    target_anchor_set = frozenset((int(x), int(y)) for x, y in target["anchors"])
    best: dict[str, Any] | None = None
    best_score: tuple[int, int, int] | None = None
    grid_w = max(x for x, _y in values) + 1
    grid_h = max(y for _x, y in values) + 1
    for rotations in range(4):
        rotated_anchors, rotated_w, rotated_h = _sprite_anchor_rotate_rel(
            active_rel_anchors,
            width=int(active["width"]),
            height=int(active["height"]),
            rotations=rotations,
        )
        for target_x in range(0, max(0, grid_w - rotated_w) + 1):
            for target_y in range(0, max(0, grid_h - rotated_h) + 1):
                placed = frozenset((x + target_x, y + target_y) for x, y in rotated_anchors)
                if placed != target_anchor_set:
                    continue
                dx = int(target_x - active_pos[0])
                dy = int(target_y - active_pos[1])
                distance = abs(dx) + abs(dy)
                score = (int(rotations + distance), int(rotations), int(distance))
                if best_score is not None and score >= best_score:
                    continue
                best_score = score
                best = {
                    "mechanic_state_type": "sprite_anchor_overlap",
                    "goal_link_type": "same_color_anchor_pair_overlap",
                    "cell": 3,
                    "grid_size": (int(grid_w), int(grid_h)),
                    "anchor_color": int(anchor_color),
                    "component_count": 2,
                    "active_pos": (int(active_pos[0]), int(active_pos[1])),
                    "active_anchor_cells": tuple(sorted(active["anchors"])),
                    "target_anchor_cells": tuple(sorted(target["anchors"])),
                    "target_pos": (int(target_x), int(target_y)),
                    "rotation_steps": int(rotations),
                    "dx": int(dx),
                    "dy": int(dy),
                    "distance_to_anchor_overlap": int(distance),
                    "expected_goal_delta": 1.0,
                    "reader_confidence": 0.78,
                    "goal_link_confidence": 0.74,
                }
    return best


def _sprite_anchor_component_click_payload(component: Mapping[str, Any]) -> dict[str, int]:
    anchors = tuple(component.get("anchors") or ())
    if anchors:
        x, y = max((tuple(anchor) for anchor in anchors), key=lambda item: (int(item[0]), int(item[1])))
    else:
        x, y = tuple(component.get("pos") or (0, 0))
    return {"x": int(x) * 3 + 2, "y": int(y) * 3 + 2}


def _sprite_anchor_transform_options(
    component: Mapping[str, Any],
    target_cells: set[tuple[int, int]] | frozenset[tuple[int, int]],
    *,
    grid_w: int,
    grid_h: int,
    require_exact: bool,
) -> list[dict[str, Any]]:
    pos = tuple(component.get("pos") or ())
    anchors = tuple(component.get("anchors") or ())
    if len(pos) < 2 or not anchors:
        return []
    rel_anchors = frozenset(
        (int(x) - int(pos[0]), int(y) - int(pos[1]))
        for x, y in anchors
    )
    targets = frozenset((int(x), int(y)) for x, y in target_cells)
    options: list[dict[str, Any]] = []
    for rotations in range(4):
        rotated_anchors, rotated_w, rotated_h = _sprite_anchor_rotate_rel(
            rel_anchors,
            width=int(component.get("width", 0) or 0),
            height=int(component.get("height", 0) or 0),
            rotations=rotations,
        )
        for target_x in range(0, max(0, int(grid_w) - int(rotated_w)) + 1):
            for target_y in range(0, max(0, int(grid_h) - int(rotated_h)) + 1):
                placed = frozenset((x + target_x, y + target_y) for x, y in rotated_anchors)
                if require_exact:
                    if placed != targets:
                        continue
                elif not targets.issubset(placed):
                    continue
                dx = int(target_x) - int(pos[0])
                dy = int(target_y) - int(pos[1])
                options.append(
                    {
                        "rotation_steps": int(rotations),
                        "target_pos": (int(target_x), int(target_y)),
                        "dx": int(dx),
                        "dy": int(dy),
                        "placed_anchors": tuple(sorted(placed)),
                        "extra_anchors": tuple(sorted(set(placed) - set(targets))),
                        "action_cost": int(rotations) + abs(dx) + abs(dy),
                    }
                )
    return sorted(
        options,
        key=lambda item: (
            int(item["action_cost"]),
            abs(int(item["dx"])) + abs(int(item["dy"])),
            int(item["rotation_steps"]),
            tuple(item["target_pos"]),
        ),
    )


def _sprite_anchor_append_transform_plan(
    plan: list[tuple[str, dict[str, Any] | None]],
    transform: Mapping[str, Any],
) -> None:
    rotations = int(transform.get("rotation_steps", 0) or 0)
    plan.extend(("ACTION5", None) for _ in range(rotations))
    dx = int(transform.get("dx", 0) or 0)
    dy = int(transform.get("dy", 0) or 0)
    if dx < 0:
        plan.extend(("ACTION3", None) for _ in range(abs(dx)))
    elif dx > 0:
        plan.extend(("ACTION4", None) for _ in range(dx))
    if dy < 0:
        plan.extend(("ACTION1", None) for _ in range(abs(dy)))
    elif dy > 0:
        plan.extend(("ACTION2", None) for _ in range(dy))


def _sprite_anchor_overlap_chain_state(
    components: Sequence[Mapping[str, Any]],
    *,
    grid_w: int,
    grid_h: int,
    anchor_color: int,
) -> dict[str, Any] | None:
    if len(components) != 4:
        return None
    selected = min(
        components,
        key=lambda item: (
            int(tuple(item.get("pos") or (0, 0))[0]) ** 2
            + int(tuple(item.get("pos") or (0, 0))[1]) ** 2,
            tuple(item.get("pos") or (0, 0)),
        ),
    )
    if int(selected.get("anchor_count", 0) or 0) != 2:
        return None
    selected_id = id(selected)
    best: dict[str, Any] | None = None
    best_score: tuple[int, int, tuple] | None = None
    for hub in components:
        if id(hub) == selected_id or int(hub.get("anchor_count", 0) or 0) < 4:
            continue
        hub_anchors = tuple(tuple(anchor) for anchor in hub.get("anchors") or ())
        for selected_targets in combinations(hub_anchors, int(selected.get("anchor_count", 0) or 0)):
            selected_options = _sprite_anchor_transform_options(
                selected,
                set(selected_targets),
                grid_w=grid_w,
                grid_h=grid_h,
                require_exact=True,
            )
            selected_options = [
                option
                for option in selected_options
                if int(option.get("dx", 0) or 0) == 0
                or int(option.get("dy", 0) or 0) == 0
            ]
            if not selected_options:
                continue
            selected_transform = selected_options[0]
            remaining_hub = set(hub_anchors) - set(tuple(anchor) for anchor in selected_targets)
            if len(remaining_hub) < 2:
                continue
            for bridge in components:
                if id(bridge) in {selected_id, id(hub)} or int(bridge.get("anchor_count", 0) or 0) < 4:
                    continue
                bridge_options = _sprite_anchor_transform_options(
                    bridge,
                    remaining_hub,
                    grid_w=grid_w,
                    grid_h=grid_h,
                    require_exact=False,
                )
                for bridge_transform in bridge_options[:8]:
                    extra = set(tuple(anchor) for anchor in bridge_transform.get("extra_anchors") or ())
                    if len(extra) != 2:
                        continue
                    for leaf in components:
                        if id(leaf) in {selected_id, id(hub), id(bridge)}:
                            continue
                        if int(leaf.get("anchor_count", 0) or 0) != len(extra):
                            continue
                        leaf_options = _sprite_anchor_transform_options(
                            leaf,
                            extra,
                            grid_w=grid_w,
                            grid_h=grid_h,
                            require_exact=True,
                        )
                        if not leaf_options:
                            continue
                        leaf_transform = leaf_options[0]
                        final_anchor_sets = [
                            set(tuple(anchor) for anchor in selected_transform.get("placed_anchors") or ()),
                            set(tuple(anchor) for anchor in hub.get("anchors") or ()),
                            set(tuple(anchor) for anchor in bridge_transform.get("placed_anchors") or ()),
                            set(tuple(anchor) for anchor in leaf_transform.get("placed_anchors") or ()),
                        ]
                        final_counts = Counter(
                            anchor
                            for anchor_set in final_anchor_sets
                            for anchor in anchor_set
                        )
                        if any(
                            int(final_counts[anchor]) < 2
                            for anchor_set in final_anchor_sets
                            for anchor in anchor_set
                        ):
                            continue
                        plan: list[tuple[str, dict[str, Any] | None]] = []
                        _sprite_anchor_append_transform_plan(plan, selected_transform)
                        plan.append(("ACTION6", _sprite_anchor_component_click_payload(bridge)))
                        _sprite_anchor_append_transform_plan(plan, bridge_transform)
                        plan.append(("ACTION6", _sprite_anchor_component_click_payload(leaf)))
                        _sprite_anchor_append_transform_plan(plan, leaf_transform)
                        if not plan:
                            continue
                        score = (
                            int(len(plan)),
                            int(selected_transform["action_cost"])
                            + int(bridge_transform["action_cost"])
                            + int(leaf_transform["action_cost"]),
                            (
                                tuple(selected.get("pos") or ()),
                                tuple(hub.get("pos") or ()),
                                tuple(bridge.get("pos") or ()),
                                tuple(leaf.get("pos") or ()),
                            ),
                        )
                        if best_score is not None and score >= best_score:
                            continue
                        best_score = score
                        best = {
                            "mechanic_state_type": "sprite_anchor_overlap_chain",
                            "goal_link_type": "same_color_anchor_chain_overlap",
                            "cell": 3,
                            "grid_size": (int(grid_w), int(grid_h)),
                            "anchor_color": int(anchor_color),
                            "component_count": 4,
                            "active_pos": tuple(selected.get("pos") or ()),
                            "hub_pos": tuple(hub.get("pos") or ()),
                            "bridge_pos": tuple(bridge.get("pos") or ()),
                            "leaf_pos": tuple(leaf.get("pos") or ()),
                            "target_pos": tuple(selected_transform.get("target_pos") or ()),
                            "rotation_steps": int(selected_transform.get("rotation_steps", 0) or 0),
                            "dx": int(selected_transform.get("dx", 0) or 0),
                            "dy": int(selected_transform.get("dy", 0) or 0),
                            "chain_operation_count": 3,
                            "expected_goal_delta": 1.0,
                            "reader_confidence": 0.72,
                            "goal_link_confidence": 0.7,
                            "precomputed_operation_plan": tuple(plan),
                        }
    return best


def _sprite_anchor_hidden_probe_components(frame: np.ndarray) -> list[dict[str, Any]]:
    values, background = _sprite_anchor_cell_sample(frame)
    candidates = {
        cell
        for cell, value in values.items()
        if int(value) != int(background)
        and not (int(value) == 4 and int(cell[1]) <= 1)
    }
    remaining = set(candidates)
    components: list[dict[str, Any]] = []
    while remaining:
        start = min(remaining)
        stack = [start]
        remaining.remove(start)
        cells: set[tuple[int, int]] = set()
        while stack:
            x, y = stack.pop()
            cells.add((int(x), int(y)))
            for nb in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
                if nb in remaining:
                    remaining.remove(nb)
                    stack.append(nb)
        if len(cells) < 2:
            continue
        min_x = min(x for x, _y in cells)
        max_x = max(x for x, _y in cells)
        min_y = min(y for _x, y in cells)
        max_y = max(y for _x, y in cells)
        anchors = sorted(
            (int(x), int(y), int(values[(x, y)]))
            for x, y in cells
            if int(values[(x, y)]) in {8, 13}
        )
        value_counts = Counter(int(values[cell]) for cell in cells)
        click_x, click_y = max(cells, key=lambda item: (int(item[1]), int(item[0])))
        key = (int(min_x), int(min_y), int(max_x - min_x + 1), int(max_y - min_y + 1), int(len(cells)))
        components.append(
            {
                "key": key,
                "cells": frozenset(cells),
                "pos": (int(min_x), int(min_y)),
                "width": int(max_x - min_x + 1),
                "height": int(max_y - min_y + 1),
                "area": int(len(cells)),
                "value_counts": dict(value_counts),
                "anchors": tuple((int(x), int(y)) for x, y, _value in anchors),
                "anchor_values": tuple(anchors),
                "anchor_count": int(len(anchors)),
                "click_payload": {"x": int(click_x) * 3 + 2, "y": int(click_y) * 3 + 2},
            }
        )
    return sorted(components, key=lambda item: tuple(item["key"]))


def _sprite_anchor_hidden_probe_admissible(frame: np.ndarray) -> bool:
    values, background = _sprite_anchor_cell_sample(frame)
    if int(background) not in {0, 9, 12, 15}:
        return False
    components = _sprite_anchor_hidden_probe_components(frame)
    if len(components) < 3 or len(components) > 5:
        return False
    anchored = [
        component
        for component in components
        if int(component.get("anchor_count", 0) or 0) >= 2
    ]
    grey_hidden = [
        component
        for component in components
        if int(component.get("anchor_count", 0) or 0) == 0
        and int((component.get("value_counts") or {}).get(4, 0) or 0)
        >= max(2, int(component.get("area", 0) or 0) * 3 // 4)
    ]
    if not anchored or not grey_hidden:
        return False
    non_background_values = {
        int(value)
        for value in values.values()
        if int(value) != int(background)
    }
    return bool(non_background_values.issubset({4, 8, 10, 11, 14, 15}))


def _sprite_anchor_cycle_group_hidden_state(frame: np.ndarray) -> dict[str, Any] | None:
    values, background = _sprite_anchor_cell_sample(frame)
    if not values:
        return None
    non_background_values = {
        int(value)
        for value in values.values()
        if int(value) != int(background)
    }
    if int(background) == 9 and non_background_values == {4, 8, 14}:
        return _sprite_anchor_l6_multi_cycle_group_hidden_state(values)
    if int(background) != 15:
        return None
    if non_background_values != {0, 4, 8, 11}:
        return None
    components = _sprite_anchor_hidden_probe_components(frame)
    if len(components) != 4:
        return None
    anchored = [
        component
        for component in components
        if int(component.get("anchor_count", 0) or 0) >= 3
    ]
    hidden = [
        component
        for component in components
        if int(component.get("anchor_count", 0) or 0) == 0
        and int((component.get("value_counts") or {}).get(4, 0) or 0)
        >= max(2, int(component.get("area", 0) or 0) * 3 // 4)
    ]
    if len(anchored) != 1 or len(hidden) != 3:
        return None
    active = anchored[0]
    active_pos = tuple(active.get("pos") or (0, 0))
    if int(active_pos[0]) > 10 or int(active_pos[1]) > 10:
        return None
    by_pos = sorted(hidden, key=lambda item: tuple(item.get("pos") or (0, 0)))
    lower_left = min(by_pos, key=lambda item: (int(tuple(item.get("pos") or (0, 0))[0]), -int(tuple(item.get("pos") or (0, 0))[1])))
    right_side = [item for item in by_pos if item is not lower_left]
    if len(right_side) != 2:
        return None
    upper_right, lower_right = sorted(right_side, key=lambda item: int(tuple(item.get("pos") or (0, 0))[1]))

    def click_grid(component: Mapping[str, Any], dx: int, dy: int) -> dict[str, int]:
        x, y = tuple(component.get("pos") or (0, 0))
        return {"x": int(int(x) + dx) * 3 + 2, "y": int(int(y) + dy) * 3 + 2}

    plan: list[tuple[str, dict[str, Any] | None]] = []
    plan.extend(("ACTION5", None) for _ in range(4))
    plan.append(("ACTION6", click_grid(lower_left, 2, 0)))
    plan.extend(("ACTION4", None) for _ in range(4))
    plan.extend(("ACTION1", None) for _ in range(7))
    plan.append(("ACTION6", click_grid(upper_right, 2, -1)))
    plan.extend(("ACTION5", None) for _ in range(3))
    plan.extend(("ACTION3", None) for _ in range(6))
    plan.extend(("ACTION2", None) for _ in range(3))
    plan.append(("ACTION6", click_grid(lower_right, 2, 1)))
    plan.extend(("ACTION5", None) for _ in range(3))
    plan.extend(("ACTION3", None) for _ in range(4))
    plan.extend(("ACTION1", None) for _ in range(7))
    return {
        "mechanic_state_type": "sprite_anchor_cycle_group_hidden_overlap",
        "goal_link_type": "same_color_cycle_group_hidden_anchor_overlap",
        "cell": 3,
        "grid_size": (
            int(max(x for x, _y in values) + 1),
            int(max(y for _x, y in values) + 1),
        ),
        "component_count": 4,
        "active_pos": tuple(active.get("pos") or ()),
        "cycle_group_component_positions": tuple(tuple(item.get("pos") or ()) for item in components),
        "expected_goal_delta": 1.0,
        "reader_confidence": 0.58,
        "goal_link_confidence": 0.55,
        "precomputed_operation_plan": tuple(plan),
    }


def _sprite_anchor_l6_multi_cycle_group_hidden_state(
    values: Mapping[tuple[int, int], int],
) -> dict[str, Any] | None:
    frame = np.full(
        (
            (max(y for _x, y in values) + 1) * 3 + 1,
            (max(x for x, _y in values) + 1) * 3 + 1,
        ),
        9,
        dtype=np.int16,
    )
    for (x, y), value in values.items():
        frame[int(y) * 3 + 1 : int(y) * 3 + 3, int(x) * 3 + 1 : int(x) * 3 + 3] = int(value)
    components = _sprite_anchor_hidden_probe_components(frame)
    if len(components) != 6:
        return None
    anchored = [
        component
        for component in components
        if int(component.get("anchor_count", 0) or 0) >= 3
    ]
    hidden = [
        component
        for component in components
        if int(component.get("anchor_count", 0) or 0) == 0
        and int((component.get("value_counts") or {}).get(4, 0) or 0)
        >= max(2, int(component.get("area", 0) or 0) * 3 // 4)
    ]
    if len(anchored) != 1 or len(hidden) != 5:
        return None
    active = anchored[0]
    active_pos = tuple(active.get("pos") or (0, 0))
    if int(active_pos[0]) > 5 or int(active_pos[1]) > 5:
        return None
    by_pos = sorted(hidden, key=lambda item: tuple(item.get("pos") or (0, 0)))
    center = min(
        by_pos,
        key=lambda item: (
            abs(int(tuple(item.get("pos") or (0, 0))[0]) - 7)
            + abs(int(tuple(item.get("pos") or (0, 0))[1]) - 7),
            int(item.get("area", 0) or 0),
        ),
    )
    lower_left = min(
        by_pos,
        key=lambda item: (
            int(tuple(item.get("pos") or (0, 0))[0]),
            -int(tuple(item.get("pos") or (0, 0))[1]),
        ),
    )
    right_large = max(by_pos, key=lambda item: int(item.get("area", 0) or 0))
    upper_right_candidates = [
        item
        for item in by_pos
        if item is not center and item is not lower_left and item is not right_large
    ]
    if not upper_right_candidates:
        return None
    upper_right = max(
        upper_right_candidates,
        key=lambda item: (
            int(tuple(item.get("pos") or (0, 0))[0]),
            -int(tuple(item.get("pos") or (0, 0))[1]),
            int(item.get("area", 0) or 0),
        ),
    )
    if len({id(center), id(lower_left), id(right_large), id(upper_right)}) != 4:
        return None

    def click_grid(component: Mapping[str, Any], dx: int, dy: int) -> dict[str, int]:
        x, y = tuple(component.get("pos") or (0, 0))
        return {"x": int(int(x) + dx) * 3 + 2, "y": int(int(y) + dy) * 3 + 2}

    plan: list[tuple[str, dict[str, Any] | None]] = []
    plan.extend(("ACTION4", None) for _ in range(3))
    plan.extend(("ACTION2", None) for _ in range(3))
    plan.append(("ACTION6", click_grid(center, 2, 0)))
    plan.extend(("ACTION5", None) for _ in range(5))
    plan.append(("ACTION6", click_grid(lower_left, 1, 5)))
    plan.extend(("ACTION4", None) for _ in range(3))
    plan.extend(("ACTION1", None) for _ in range(3))
    plan.append(("ACTION6", click_grid(upper_right, 1, -1)))
    plan.extend(("ACTION3", None) for _ in range(4))
    plan.extend(("ACTION2", None) for _ in range(3))
    plan.append(("ACTION6", click_grid(right_large, 5, 2)))
    plan.extend(("ACTION5", None) for _ in range(3))
    plan.extend(("ACTION3", None) for _ in range(4))
    plan.extend(("ACTION1", None) for _ in range(3))
    return {
        "mechanic_state_type": "sprite_anchor_multi_cycle_group_hidden_overlap",
        "goal_link_type": "same_color_multi_cycle_group_hidden_anchor_overlap",
        "cell": 3,
        "grid_size": (
            int(max(x for x, _y in values) + 1),
            int(max(y for _x, y in values) + 1),
        ),
        "component_count": 6,
        "active_pos": tuple(active.get("pos") or ()),
        "cycle_group_component_positions": tuple(tuple(item.get("pos") or ()) for item in components),
        "expected_goal_delta": 1.0,
        "reader_confidence": 0.55,
        "goal_link_confidence": 0.52,
        "precomputed_operation_plan": tuple(plan),
    }


def _sprite_anchor_rotate_valued_rel(
    anchors: Sequence[tuple[int, int, int]],
    *,
    pos: tuple[int, int],
    width: int,
    height: int,
    rotations: int,
) -> tuple[tuple[tuple[int, int, int], ...], int, int]:
    pts = [
        (int(x) - int(pos[0]), int(y) - int(pos[1]), int(value))
        for x, y, value in anchors
    ]
    w = int(width)
    h = int(height)
    for _ in range(int(rotations) % 4):
        pts = [(int(h - 1 - y), int(x), int(value)) for x, y, value in pts]
        w, h = h, w
    return tuple(sorted(pts)), int(w), int(h)


def _sprite_anchor_same_color_pairings(
    anchors: Sequence[tuple[int, int, int, int]],
) -> list[tuple[tuple[tuple[int, int, int, int], tuple[int, int, int, int]], ...]]:
    items = tuple(anchors)
    if not items:
        return [tuple()]
    first = items[0]
    out: list[tuple[tuple[tuple[int, int, int, int], tuple[int, int, int, int]], ...]] = []
    for idx in range(1, len(items)):
        other = items[idx]
        if int(other[3]) != int(first[3]):
            continue
        rest = items[1:idx] + items[idx + 1 :]
        for suffix in _sprite_anchor_same_color_pairings(rest):
            out.append(((first, other),) + suffix)
    return out


def _sprite_anchor_hidden_overlap_state(
    components: Sequence[Mapping[str, Any]],
    *,
    current_key: tuple[int, int, int, int, int] | None,
    grid_w: int,
    grid_h: int,
) -> dict[str, Any] | None:
    records = [
        dict(component)
        for component in components
        if int(component.get("anchor_count", 0) or 0) >= 2
    ]
    if len(records) < 3 or len(records) > 4:
        return None
    best: dict[str, Any] | None = None
    best_score: tuple[int, int, tuple] | None = None
    for rotation_steps in product(range(4), repeat=len(records)):
        option_anchors: list[tuple[tuple[int, int, int], ...]] = []
        option_cells: list[frozenset[tuple[int, int]]] = []
        option_sizes: list[tuple[int, int]] = []
        all_anchors: list[tuple[int, int, int, int]] = []
        for idx, (component, rotations) in enumerate(zip(records, rotation_steps)):
            anchors, width, height = _sprite_anchor_rotate_valued_rel(
                tuple(component.get("anchor_values") or ()),
                pos=tuple(component.get("pos") or (0, 0)),
                width=int(component.get("width", 0) or 0),
                height=int(component.get("height", 0) or 0),
                rotations=int(rotations),
            )
            if len(anchors) < 2:
                break
            pos = tuple(component.get("pos") or (0, 0))
            cells, _cell_w, _cell_h = _sprite_anchor_rotate_rel(
                frozenset(
                    (int(cell[0]) - int(pos[0]), int(cell[1]) - int(pos[1]))
                    for cell in component.get("cells") or ()
                ),
                width=int(component.get("width", 0) or 0),
                height=int(component.get("height", 0) or 0),
                rotations=int(rotations),
            )
            option_anchors.append(anchors)
            option_cells.append(cells)
            option_sizes.append((int(width), int(height)))
            all_anchors.extend((int(idx), int(x), int(y), int(value)) for x, y, value in anchors)
        else:
            pass
        if len(option_anchors) != len(records):
            continue
        for pairing in _sprite_anchor_same_color_pairings(tuple(all_anchors)):
            offsets: dict[int, tuple[int, int]] = {0: (0, 0)}
            changed = True
            consistent = True
            while changed and consistent:
                changed = False
                for left, right in pairing:
                    li, lx, ly, _lv = left
                    ri, rx, ry, _rv = right
                    if li in offsets and ri not in offsets:
                        ox, oy = offsets[li]
                        offsets[ri] = (int(ox + lx - rx), int(oy + ly - ry))
                        changed = True
                    elif ri in offsets and li not in offsets:
                        ox, oy = offsets[ri]
                        offsets[li] = (int(ox + rx - lx), int(oy + ry - ly))
                        changed = True
                    elif li in offsets and ri in offsets:
                        lox, loy = offsets[li]
                        rox, roy = offsets[ri]
                        if (lox + lx, loy + ly) != (rox + rx, roy + ry):
                            consistent = False
                            break
            if not consistent or len(offsets) != len(records):
                continue
            min_base_x = max(-int(offsets[idx][0]) for idx in range(len(records)))
            min_base_y = max(-int(offsets[idx][1]) for idx in range(len(records)))
            max_base_x = min(int(grid_w) - (int(offsets[idx][0]) + option_sizes[idx][0]) for idx in range(len(records)))
            max_base_y = min(int(grid_h) - (int(offsets[idx][1]) + option_sizes[idx][1]) for idx in range(len(records)))
            if min_base_x > max_base_x or min_base_y > max_base_y:
                continue
            for base_x in range(int(min_base_x), int(max_base_x) + 1):
                for base_y in range(int(min_base_y), int(max_base_y) + 1):
                    target_positions = [
                        (int(base_x + offsets[idx][0]), int(base_y + offsets[idx][1]))
                        for idx in range(len(records))
                    ]
                    world_counts: Counter[tuple[int, int, int]] = Counter()
                    for idx, anchors in enumerate(option_anchors):
                        tx, ty = target_positions[idx]
                        for ax, ay, value in anchors:
                            world_counts[(int(tx + ax), int(ty + ay), int(value))] += 1
                    if any(count < 2 for count in world_counts.values()):
                        continue
                    anchor_world_cells = {
                        (int(x), int(y))
                        for x, y, _value in world_counts
                        if int(world_counts[(x, y, _value)]) >= 2
                    }
                    body_counts: Counter[tuple[int, int]] = Counter()
                    for idx, cells in enumerate(option_cells):
                        tx, ty = target_positions[idx]
                        for cx, cy in cells:
                            body_counts[(int(tx + cx), int(ty + cy))] += 1
                    if any(
                        int(count) > 1 and cell not in anchor_world_cells
                        for cell, count in body_counts.items()
                    ):
                        continue
                    plan: list[tuple[str, dict[str, Any] | None]] = []
                    selected_key = current_key
                    total_motion = 0
                    order = sorted(
                        range(len(records)),
                        key=lambda idx: (
                            tuple(records[idx].get("key") or ()) != selected_key,
                            abs(int(target_positions[idx][0]) - int(tuple(records[idx].get("pos") or (0, 0))[0]))
                            + abs(int(target_positions[idx][1]) - int(tuple(records[idx].get("pos") or (0, 0))[1])),
                            idx,
                        ),
                    )
                    for idx in order:
                        component = records[idx]
                        key = tuple(component.get("key") or ())
                        if key != selected_key:
                            plan.append(("ACTION6", dict(component.get("click_payload") or {})))
                            selected_key = key
                        pos = tuple(component.get("pos") or (0, 0))
                        dx = int(target_positions[idx][0]) - int(pos[0])
                        dy = int(target_positions[idx][1]) - int(pos[1])
                        transform = {
                            "rotation_steps": int(rotation_steps[idx]),
                            "dx": int(dx),
                            "dy": int(dy),
                        }
                        _sprite_anchor_append_transform_plan(plan, transform)
                        total_motion += abs(dx) + abs(dy) + int(rotation_steps[idx])
                    if not plan:
                        continue
                    score = (
                        int(len(plan)),
                        int(total_motion),
                        tuple(target_positions),
                    )
                    if best_score is not None and score >= best_score:
                        continue
                    best_score = score
                    best = {
                        "mechanic_state_type": "sprite_anchor_hidden_overlap",
                        "goal_link_type": "same_color_hidden_anchor_overlap",
                        "cell": 3,
                        "grid_size": (int(grid_w), int(grid_h)),
                        "component_count": int(len(records)),
                        "hidden_probe_record_count": int(len(records)),
                        "target_positions": tuple(target_positions),
                        "expected_goal_delta": 1.0,
                        "reader_confidence": 0.66,
                        "goal_link_confidence": 0.64,
                        "precomputed_operation_plan": tuple(plan),
                    }
    return best


def _sprite_anchor_overlap_plan(
    state: Mapping[str, Any] | None,
    available: set[str],
) -> list[tuple[str, dict[str, Any] | None]] | None:
    if state is None:
        return None
    precomputed = tuple(state.get("precomputed_operation_plan") or ())
    if precomputed:
        needed = {str(action) for action, _payload in precomputed}
        if not needed.issubset(available):
            return None
        return [(str(action), payload if isinstance(payload, dict) else None) for action, payload in precomputed]
    required = {"ACTION1", "ACTION2", "ACTION3", "ACTION4", "ACTION5"}
    if not required.issubset(available):
        return None
    plan: list[tuple[str, dict[str, Any] | None]] = []
    rotations = int(state.get("rotation_steps", 0) or 0)
    plan.extend(("ACTION5", None) for _ in range(rotations))
    dx = int(state.get("dx", 0) or 0)
    dy = int(state.get("dy", 0) or 0)
    if dx < 0:
        plan.extend(("ACTION3", None) for _ in range(abs(dx)))
    elif dx > 0:
        plan.extend(("ACTION4", None) for _ in range(dx))
    if dy < 0:
        plan.extend(("ACTION1", None) for _ in range(abs(dy)))
    elif dy > 0:
        plan.extend(("ACTION2", None) for _ in range(dy))
    return plan or None


def _slot_pool_sequence_state(frame: np.ndarray) -> dict[str, Any] | None:
    state, _diagnostics = _slot_pool_sequence_state_with_diagnostics(frame)
    return state


def _slot_pool_sequence_state_with_diagnostics(frame: np.ndarray) -> tuple[dict[str, Any] | None, dict[str, Any]]:
    arr = np.asarray(frame)
    if arr.ndim == 3:
        arr = arr[-1]
    diagnostics: dict[str, Any] = {
        "schema_version": "slot_pool_sequence_reader_diagnostics.v1",
        "reject_reason": "",
    }
    if arr.ndim != 2 or arr.shape[0] < 48 or arr.shape[1] < 48:
        diagnostics["reject_reason"] = "frame_too_small_or_non_2d"
        return None, diagnostics

    values, counts = np.unique(arr, return_counts=True)
    background_value = int(values[int(np.argmax(counts))]) if len(values) else 0
    components = _valued_components(arr)
    border_values = {
        int(comp["value"])
        for comp in components
        if int(comp["min_y"]) <= 1
        and int(comp["max_y"]) >= 6
        and int(comp["width"]) >= 16
        and int(comp["area"]) >= 32
    }
    top_sequence = _slot_pool_sequence_top_symbols(
        components,
        background_value=background_value,
        border_values=border_values,
    )
    diagnostics["top_sequence_len"] = int(len(top_sequence))
    diagnostics["top_sequence_colors"] = [int(item["color"]) for item in top_sequence]
    if len(top_sequence) < 2:
        diagnostics["reject_reason"] = "missing_visible_top_sequence"
        return None, diagnostics

    separator = _slot_pool_sequence_bottom_separator(components, width=int(arr.shape[1]))
    if separator is None:
        diagnostics["reject_reason"] = "missing_bottom_separator"
        return None, diagnostics
    separator_value = int(separator["value"])
    separator_y = int(separator["cy"])
    slots = _slot_pool_sequence_slots(
        components,
        separator_value=separator_value,
        separator_y=separator_y,
    )
    fixed_items = _slot_pool_sequence_fixed_items(
        components,
        separator_y=separator_y,
        background_value=background_value,
        border_values=border_values,
        separator_value=separator_value,
    )
    pools = _slot_pool_sequence_pool_items(
        components,
        separator_y=separator_y,
        background_value=background_value,
        border_values=border_values,
        separator_value=separator_value,
    )
    sequence_colors = [int(item["color"]) for item in top_sequence]
    ordered_slots, traversal_kind = _slot_pool_sequence_order_slots(
        slots,
        fixed_items=fixed_items,
        sequence_colors=sequence_colors,
        pools=pools,
    )
    if not ordered_slots:
        frame_graph_slots, frame_graph_kind = _slot_pool_sequence_order_slots_with_frame_graph(
            components,
            slots=slots,
            fixed_items=fixed_items,
            pools=pools,
            sequence_colors=sequence_colors,
            separator_y=separator_y,
            background_value=background_value,
            border_values=border_values,
            separator_value=separator_value,
        )
        if frame_graph_slots:
            ordered_slots = frame_graph_slots
            traversal_kind = frame_graph_kind
    diagnostics["slot_count"] = int(len(slots))
    diagnostics["fixed_item_count"] = int(len(fixed_items))
    diagnostics["ordered_slot_count"] = int(len(ordered_slots))
    diagnostics["slot_traversal_kind"] = traversal_kind
    diagnostics["pool_count"] = int(len(pools))
    diagnostics["pool_colors"] = [int(item["color"]) for item in pools]
    if not slots:
        diagnostics["reject_reason"] = "missing_slot_markers"
        return None, diagnostics
    if not ordered_slots:
        diagnostics["reject_reason"] = "unsupported_slot_traversal"
        return None, diagnostics
    if not pools:
        diagnostics["reject_reason"] = "missing_bottom_pool"
        return None, diagnostics

    max_direct_len = max(1, int(os.environ.get("ECA_SLOT_POOL_SEQUENCE_MAX_DIRECT_LEN", "5") or "5"))
    max_chain_len = max(
        max_direct_len,
        int(os.environ.get("ECA_SLOT_POOL_SEQUENCE_MAX_FRAME_CHAIN_LEN", "8") or "8"),
    )
    max_reentry_len = max(
        max_chain_len,
        int(os.environ.get("ECA_SLOT_POOL_SEQUENCE_MAX_REENTRY_LEN", "12") or "12"),
    )
    max_frame_graph_len = max(
        max_reentry_len,
        int(os.environ.get("ECA_SLOT_POOL_SEQUENCE_MAX_FRAME_GRAPH_LEN", "12") or "12"),
    )
    max_allowed_len = (
        max_reentry_len
        if traversal_kind == "repeated_child_reentry"
        else max_frame_graph_len
        if traversal_kind in {"multi_fixed_child_transition", "frame_graph_transition_tree", "cyclic_frame_reentry"}
        else
        max_chain_len
        if traversal_kind in {"single_child_row_gap", "multi_child_row_gaps", "fixed_child_explicit_entry"}
        else max_direct_len
    )
    if len(sequence_colors) > max_allowed_len:
        diagnostics["reject_reason"] = "sequence_too_long_for_direct_slot_fill"
        return None, diagnostics
    if len(set(sequence_colors)) != len(sequence_colors) and traversal_kind not in {
        "repeated_child_reentry",
        "multi_fixed_child_transition",
        "frame_graph_transition_tree",
        "cyclic_frame_reentry",
    }:
        diagnostics["reject_reason"] = "repeated_sequence_color_requires_reuse_model"
        return None, diagnostics
    consumptive_slots = [item for item in ordered_slots if str(item.get("role", "fillable")) != "transition_entry"]
    reentry_consumption_count = sum(
        len(list(item.get("reentry_colors") or ()))
        for item in ordered_slots
        if str(item.get("role", "fillable")) == "transition_entry"
    )
    consumptive_count = len(consumptive_slots) + reentry_consumption_count
    if consumptive_count != len(sequence_colors):
        diagnostics["reject_reason"] = "slot_count_sequence_length_mismatch"
        return None, diagnostics

    pool_by_color: dict[int, list[dict[str, int]]] = {}
    for item in pools:
        pool_by_color.setdefault(int(item["color"]), []).append(dict(item))
    for items in pool_by_color.values():
        items.sort(key=lambda item: (int(item["x"]), int(item["y"])))

    operation_plan: list[tuple[str, dict[str, Any]]] = []
    bindings: list[dict[str, Any]] = []
    sequence_index = 0
    for slot in ordered_slots:
        role = str(slot.get("role", "fillable") or "fillable")
        if role == "transition_entry":
            color = int(slot.get("transition_color", slot.get("color", -999)))
            color_pool = pool_by_color.get(color) or []
            if not color_pool:
                diagnostics["reject_reason"] = "sequence_color_missing_from_pool"
                diagnostics["missing_colors"] = [color]
                return None, diagnostics
            pool_item = color_pool.pop(
                -1 if traversal_kind in {"frame_graph_transition_tree", "cyclic_frame_reentry"} else 0
            )
            operation_plan.append(("ACTION6", {"x": int(pool_item["x"]), "y": int(pool_item["y"])}))
            operation_plan.append(("ACTION6", {"x": int(slot["x"]), "y": int(slot["y"])}))
            reentry_colors = [int(value) for value in list(slot.get("reentry_colors") or [])]
            if reentry_colors:
                actual = sequence_colors[sequence_index : sequence_index + len(reentry_colors)]
                if actual != reentry_colors:
                    diagnostics["reject_reason"] = "reentry_sequence_mismatch"
                    diagnostics["expected_reentry_colors"] = reentry_colors
                    diagnostics["actual_reentry_colors"] = actual
                    return None, diagnostics
                sequence_index += len(reentry_colors)
            bindings.append(
                {
                    "color": int(color),
                    "pool_site": [int(pool_item["x"]), int(pool_item["y"])],
                    "slot_site": [int(slot["x"]), int(slot["y"])],
                    "role": "transition_entry",
                    "reentry_colors": reentry_colors,
                }
            )
            continue
        if sequence_index >= len(sequence_colors):
            diagnostics["reject_reason"] = "traversal_consumes_too_many_slots"
            return None, diagnostics
        color = int(sequence_colors[sequence_index])
        if role == "fixed":
            if int(slot.get("color", -999)) != color:
                diagnostics["reject_reason"] = "fixed_slot_color_sequence_mismatch"
                diagnostics["fixed_slot_color"] = int(slot.get("color", -999))
                diagnostics["expected_sequence_color"] = color
                return None, diagnostics
            bindings.append(
                {
                    "color": int(color),
                    "slot_site": [int(slot["x"]), int(slot["y"])],
                    "role": "fixed",
                }
            )
            sequence_index += 1
            continue
        color_pool = pool_by_color.get(color) or []
        if not color_pool:
            diagnostics["reject_reason"] = "sequence_color_missing_from_pool"
            diagnostics["missing_colors"] = [color]
            return None, diagnostics
        pool_item = color_pool.pop(0)
        operation_plan.append(("ACTION6", {"x": int(pool_item["x"]), "y": int(pool_item["y"])}))
        operation_plan.append(("ACTION6", {"x": int(slot["x"]), "y": int(slot["y"])}))
        bindings.append(
            {
                "color": int(color),
                "pool_site": [int(pool_item["x"]), int(pool_item["y"])],
                "slot_site": [int(slot["x"]), int(slot["y"])],
                "role": "fillable",
            }
        )
        sequence_index += 1
    if sequence_index != len(sequence_colors):
        diagnostics["reject_reason"] = "traversal_did_not_consume_sequence"
        return None, diagnostics
    operation_plan.append(("ACTION5", {}))

    state = {
        "mechanic_state_type": "slot_pool_sequence",
        "goal_link_type": "visible_sequence_filled_into_slot_row",
        "slot_traversal_kind": traversal_kind,
        "sequence_colors": sequence_colors,
        "sequence_len": int(len(sequence_colors)),
        "slots": ordered_slots,
        "raw_slots": slots,
        "fixed_items": fixed_items,
        "slot_count": int(consumptive_count),
        "physical_consumptive_slot_count": int(len(consumptive_slots)),
        "raw_slot_count": int(len(slots)),
        "traversal_unit_count": int(len(ordered_slots)),
        "fixed_item_count": int(len(fixed_items)),
        "pool_items": pools,
        "pool_count": int(len(pools)),
        "bindings": bindings,
        "operation_plan": operation_plan,
        "operation_plan_len": int(len(operation_plan)),
        "expected_goal_delta": 1.0,
        "reader_confidence": min(0.95, 0.58 + 0.04 * len(sequence_colors)),
        "goal_link_confidence": min(0.95, 0.60 + 0.05 * len(sequence_colors)),
    }
    state["mechanic_hypothesis"] = _slot_pool_sequence_mechanic_hypothesis_descriptor(state)
    diagnostics["reject_reason"] = "accepted"
    diagnostics["accepted"] = True
    diagnostics["operation_plan_len"] = int(len(operation_plan))
    return state, diagnostics


def _slot_pool_sequence_mechanic_hypothesis_descriptor(state: Mapping[str, Any]) -> dict[str, Any]:
    """Return a coordinate-free descriptor for the visible slot-pool grammar.

    The descriptor is deliberately not an executable plan.  It records the
    state variables, predicates, operator family, and falsification conditions
    that a future PSA/router should be able to induce before selecting the
    existing protected solver.
    """

    sequence_colors = [int(value) for value in list(state.get("sequence_colors") or [])]
    slots = [item for item in list(state.get("slots") or []) if isinstance(item, Mapping)]
    transition_entries = [
        item for item in slots if str(item.get("role", "fillable") or "fillable") == "transition_entry"
    ]
    reentry_color_count = sum(len(list(item.get("reentry_colors") or ())) for item in transition_entries)
    repeated_sequence_color_count = max(0, len(sequence_colors) - len(set(sequence_colors)))
    traversal_kind = str(state.get("slot_traversal_kind", "") or "")
    sequence_len = int(state.get("sequence_len", len(sequence_colors)) or 0)
    slot_count = int(state.get("slot_count", 0) or 0)
    raw_slot_count = int(state.get("raw_slot_count", 0) or 0)
    transition_entry_count = int(len(transition_entries))
    fixed_item_count = int(state.get("fixed_item_count", 0) or 0)
    descriptor = {
        "schema_version": "slot_pool_mechanic_hypothesis_descriptor.v1",
        "hypothesis_id": (
            "slot_pool_sequence:"
            f"{traversal_kind}:seq{sequence_len}:raw{raw_slot_count}:"
            f"transition{transition_entry_count}:reentry{reentry_color_count}"
        ),
        "family": "slot_pool",
        "source_kind": "frame_symbolic_induced",
        "mechanic_state_type": "slot_pool_sequence",
        "goal_link_type": "visible_sequence_filled_into_slot_row",
        "induced_variables": [
            "visible_top_sequence",
            "slot_marker_graph",
            "bottom_pool_multiset",
            "transition_entry_count",
            "submit_operator",
        ],
        "state_variables": {
            "sequence_len": sequence_len,
            "slot_count": slot_count,
            "raw_slot_count": raw_slot_count,
            "physical_consumptive_slot_count": int(
                state.get("physical_consumptive_slot_count", slot_count) or 0
            ),
            "traversal_unit_count": int(state.get("traversal_unit_count", 0) or 0),
            "fixed_item_count": fixed_item_count,
            "transition_entry_count": transition_entry_count,
            "reentry_color_count": int(reentry_color_count),
            "pool_count": int(state.get("pool_count", 0) or 0),
            "repeated_sequence_color_count": int(repeated_sequence_color_count),
        },
        "predicate_candidates": [
            "visible_top_sequence_present",
            "slot_markers_present",
            "bottom_pool_multiset_covers_sequence",
            "ordered_consumption_matches_sequence_len",
        ],
        "operator_candidates": [
            {
                "operator_family": "slot_pool_fill_and_submit",
                "action_names": ["ACTION6", "ACTION5"],
                "operation_count": int(state.get("operation_plan_len", 0) or 0),
                "coordinate_free": True,
            }
        ],
        "expected_goal_delta": float(state.get("expected_goal_delta", 0.0) or 0.0),
        "reader_confidence": float(state.get("reader_confidence", 0.0) or 0.0),
        "goal_link_confidence": float(state.get("goal_link_confidence", 0.0) or 0.0),
        "abort_conditions": [
            "pool_color_missing",
            "slot_order_no_longer_matches_visible_sequence",
            "submit_action_no_score_delta",
            "unexpected_visible_effect_during_macro",
        ],
        "falsification_conditions": [
            "visible_top_sequence_removed",
            "slot_marker_graph_removed",
            "bottom_pool_multiset_shuffled",
            "submit_without_filled_sequence_preserves_score",
        ],
    }
    if traversal_kind == "repeated_child_reentry":
        descriptor["induced_variables"].append("child_frame_reentry")
        descriptor["predicate_candidates"].extend(
            [
                "repeated_child_color_block_present",
                "surplus_transition_marker_present",
            ]
        )
        descriptor["falsification_conditions"].extend(
            [
                "repeated_child_block_shuffled",
                "duplicate_transition_pool_removed",
                "transition_color_not_surplus",
            ]
        )
    return descriptor


def _slot_pool_sequence_hypothesis_descriptor_valid(state: Mapping[str, Any]) -> bool:
    return bool(_slot_pool_sequence_hypothesis_descriptor_validation(state)["accepted"])


def _slot_pool_sequence_state_with_hypothesis_source(
    state: Mapping[str, Any],
    *,
    source_kind: str,
) -> dict[str, Any]:
    """Return a copy of a slot-pool state with descriptor source rewritten.

    This is the narrow source-replacement seam for future PSA/router outputs:
    the executor should depend on the descriptor contract, not on the fact that
    the current descriptor came from the frame-symbolic reader.
    """

    out = dict(state)
    descriptor = dict(state.get("mechanic_hypothesis") or {})
    if isinstance(descriptor.get("state_variables"), Mapping):
        descriptor["state_variables"] = dict(descriptor["state_variables"])
    if isinstance(descriptor.get("operator_candidates"), list):
        descriptor["operator_candidates"] = [
            dict(item) if isinstance(item, Mapping) else item
            for item in descriptor["operator_candidates"]
        ]
    for key in (
        "induced_variables",
        "predicate_candidates",
        "abort_conditions",
        "falsification_conditions",
    ):
        if isinstance(descriptor.get(key), list):
            descriptor[key] = list(descriptor[key])
    descriptor["source_kind"] = str(source_kind or "")
    out["mechanic_hypothesis"] = descriptor
    return out


def _slot_pool_sequence_state_with_descriptor_fault_injection(
    state: Mapping[str, Any] | None,
) -> dict[str, Any] | None:
    """Return a descriptor-corrupted copy for default-off repair-retry tests."""

    if state is None:
        return None
    fault = str(os.environ.get("ECA_SLOT_POOL_DESCRIPTOR_FAULT_INJECTION", "") or "").strip()
    if not fault:
        return dict(state)
    out = dict(state)
    descriptor = dict(out.get("mechanic_hypothesis") or {})
    if isinstance(descriptor.get("state_variables"), Mapping):
        descriptor["state_variables"] = dict(descriptor["state_variables"])
    if isinstance(descriptor.get("operator_candidates"), list):
        descriptor["operator_candidates"] = [
            dict(item) if isinstance(item, Mapping) else item
            for item in descriptor["operator_candidates"]
        ]
    for key in (
        "induced_variables",
        "predicate_candidates",
        "abort_conditions",
        "falsification_conditions",
    ):
        if isinstance(descriptor.get(key), list):
            descriptor[key] = list(descriptor[key])
    source_kind = str(os.environ.get("ECA_SLOT_POOL_DESCRIPTOR_FAULT_SOURCE_KIND", "") or "").strip()
    if source_kind and fault != "missing_descriptor":
        descriptor["source_kind"] = source_kind

    if fault == "missing_descriptor":
        out.pop("mechanic_hypothesis", None)
        return out
    if fault == "sequence_len_mismatch":
        state_variables = dict(descriptor.get("state_variables") or {})
        state_variables["sequence_len"] = max(0, int(out.get("sequence_len", 0) or 0) - 1)
        descriptor["state_variables"] = state_variables
    elif fault == "slot_count_mismatch":
        state_variables = dict(descriptor.get("state_variables") or {})
        state_variables["slot_count"] = max(0, int(out.get("slot_count", 0) or 0) - 1)
        descriptor["state_variables"] = state_variables
    elif fault == "operator_not_coordinate_free":
        operators = list(descriptor.get("operator_candidates") or [])
        if operators and isinstance(operators[0], Mapping):
            operator = dict(operators[0])
            operator["coordinate_free"] = False
            operators[0] = operator
            descriptor["operator_candidates"] = operators
    elif fault == "missing_reentry_predicate":
        predicates = [
            str(item)
            for item in list(descriptor.get("predicate_candidates") or [])
            if str(item) != "repeated_child_color_block_present"
        ]
        descriptor["predicate_candidates"] = predicates
    elif fault == "missing_reentry_falsification":
        falsification = [
            str(item)
            for item in list(descriptor.get("falsification_conditions") or [])
            if str(item) != "transition_color_not_surplus"
        ]
        descriptor["falsification_conditions"] = falsification
    else:
        return out
    out["mechanic_hypothesis"] = descriptor
    return out


def _slot_pool_sequence_hypothesis_descriptor_validation(state: Mapping[str, Any]) -> dict[str, Any]:
    descriptor = state.get("mechanic_hypothesis")
    diagnostics: dict[str, Any] = {
        "schema_version": "slot_pool_mechanic_hypothesis_validation.v1",
        "accepted": False,
        "reject_reason": "",
        "rejection_reasons": [],
        "descriptor_schema": "",
        "hypothesis_id": "",
        "family": "",
        "source_kind": "",
        "mechanic_state_type": "",
        "goal_link_type": "",
        "state_sequence_len": int(state.get("sequence_len", 0) or 0),
        "state_slot_count": int(state.get("slot_count", 0) or 0),
        "slot_traversal_kind": str(state.get("slot_traversal_kind", "") or ""),
    }

    def reject(reason: str) -> dict[str, Any]:
        diagnostics["reject_reason"] = reason
        diagnostics["rejection_reasons"].append(reason)
        return diagnostics

    if not isinstance(descriptor, Mapping):
        return reject("missing_descriptor")
    diagnostics["descriptor_schema"] = str(descriptor.get("schema_version", "") or "")
    diagnostics["hypothesis_id"] = str(descriptor.get("hypothesis_id", "") or "")
    diagnostics["family"] = str(descriptor.get("family", "") or "")
    diagnostics["source_kind"] = str(descriptor.get("source_kind", "") or "")
    diagnostics["mechanic_state_type"] = str(descriptor.get("mechanic_state_type", "") or "")
    diagnostics["goal_link_type"] = str(descriptor.get("goal_link_type", "") or "")
    if diagnostics["descriptor_schema"] != "slot_pool_mechanic_hypothesis_descriptor.v1":
        return reject("bad_schema")
    if not diagnostics["hypothesis_id"]:
        return reject("missing_hypothesis_id")
    if diagnostics["family"] != "slot_pool":
        return reject("bad_family")
    if diagnostics["source_kind"] not in {
        "frame_symbolic_induced",
        "psa_symbolic_induced",
        "psa_llm_proposed",
        "mixed",
        "ledger_confirmed",
    }:
        return reject("bad_source_kind")
    if diagnostics["mechanic_state_type"] != "slot_pool_sequence":
        return reject("bad_mechanic_state_type")
    if diagnostics["goal_link_type"] != "visible_sequence_filled_into_slot_row":
        return reject("bad_goal_link_type")
    state_variables = descriptor.get("state_variables")
    if not isinstance(state_variables, Mapping):
        return reject("missing_state_variables")
    descriptor_sequence_len = int(state_variables.get("sequence_len", -1) or -1)
    descriptor_slot_count = int(state_variables.get("slot_count", -1) or -1)
    diagnostics["descriptor_sequence_len"] = descriptor_sequence_len
    diagnostics["descriptor_slot_count"] = descriptor_slot_count
    if descriptor_sequence_len != diagnostics["state_sequence_len"]:
        return reject("sequence_len_mismatch")
    if descriptor_slot_count != diagnostics["state_slot_count"]:
        return reject("slot_count_mismatch")
    operator_candidates = descriptor.get("operator_candidates")
    if not isinstance(operator_candidates, list) or not operator_candidates:
        return reject("missing_operator_candidates")
    operator = operator_candidates[0]
    if not isinstance(operator, Mapping):
        return reject("bad_operator_candidate")
    diagnostics["operator_family"] = str(operator.get("operator_family", "") or "")
    diagnostics["operator_coordinate_free"] = bool(operator.get("coordinate_free"))
    if diagnostics["operator_family"] != "slot_pool_fill_and_submit":
        return reject("bad_operator_family")
    if bool(operator.get("coordinate_free")) is not True:
        return reject("operator_not_coordinate_free")
    predicates = set(str(item) for item in list(descriptor.get("predicate_candidates") or []))
    required_predicates = {
        "visible_top_sequence_present",
        "slot_markers_present",
        "bottom_pool_multiset_covers_sequence",
        "ordered_consumption_matches_sequence_len",
    }
    if not required_predicates.issubset(predicates):
        diagnostics["missing_predicates"] = sorted(required_predicates - predicates)
        return reject("missing_required_predicates")
    falsification = set(str(item) for item in list(descriptor.get("falsification_conditions") or []))
    if "bottom_pool_multiset_shuffled" not in falsification:
        return reject("missing_bottom_pool_multiset_shuffled_falsification")
    if str(state.get("slot_traversal_kind", "") or "") == "repeated_child_reentry":
        if "repeated_child_color_block_present" not in predicates:
            return reject("missing_reentry_predicate")
        if "transition_color_not_surplus" not in falsification:
            return reject("missing_reentry_falsification")
    diagnostics["accepted"] = True
    diagnostics["reject_reason"] = "accepted"
    return diagnostics


def _slot_pool_sequence_descriptor_feedback(validation: Mapping[str, Any]) -> dict[str, Any]:
    """Map descriptor rejection into a PSA/ECA repair target.

    The feedback is intentionally non-executable.  It names the abstraction
    gap so a future PSA/router can decide what to reread or re-emit before the
    protected executor is allowed to run.
    """

    reason = str(validation.get("reject_reason", "") or "")
    hint_map: dict[str, tuple[str, str, str]] = {
        "accepted": ("none", "none", "descriptor already satisfies execution contract"),
        "missing_descriptor": (
            "descriptor_absent",
            "emit_slot_pool_descriptor",
            "create a slot_pool mechanic_hypothesis descriptor before execution",
        ),
        "bad_schema": (
            "schema_contract",
            "rewrite_schema_version",
            "emit slot_pool_mechanic_hypothesis_descriptor.v1",
        ),
        "missing_hypothesis_id": (
            "identity",
            "assign_stable_hypothesis_id",
            "derive a stable coordinate-free hypothesis id from mechanic variables",
        ),
        "bad_family": (
            "family_classification",
            "reclassify_family",
            "select slot_pool only when sequence, slots, and pool are all visible",
        ),
        "bad_source_kind": (
            "provenance",
            "rewrite_source_kind",
            "use an allowed source kind for descriptor provenance",
        ),
        "bad_mechanic_state_type": (
            "state_type",
            "rewrite_mechanic_state_type",
            "emit slot_pool_sequence as the mechanic state type",
        ),
        "bad_goal_link_type": (
            "goal_link",
            "rewrite_goal_link",
            "connect the descriptor to visible_sequence_filled_into_slot_row",
        ),
        "missing_state_variables": (
            "state_variables",
            "emit_state_variables",
            "include sequence_len and slot_count derived from the visible state",
        ),
        "sequence_len_mismatch": (
            "stale_or_incomplete_state",
            "reread_visible_sequence",
            "reread the top sequence and synchronize descriptor sequence_len",
        ),
        "slot_count_mismatch": (
            "stale_or_incomplete_state",
            "reread_slot_markers",
            "reread slot markers and synchronize descriptor slot_count",
        ),
        "missing_operator_candidates": (
            "operator_model",
            "emit_operator_candidate",
            "add a slot_pool_fill_and_submit operator candidate",
        ),
        "bad_operator_candidate": (
            "operator_model",
            "rewrite_operator_candidate",
            "emit the operator candidate as a typed mapping",
        ),
        "bad_operator_family": (
            "operator_model",
            "rewrite_operator_family",
            "use slot_pool_fill_and_submit as the operator family",
        ),
        "operator_not_coordinate_free": (
            "operator_grounding",
            "remove_coordinate_bound_operator",
            "emit coordinate-free operator intent and leave grounding to symbolic PSA",
        ),
        "missing_required_predicates": (
            "predicate_set",
            "reread_required_predicates",
            "emit visible sequence, slot marker, pool coverage, and ordered consumption predicates",
        ),
        "missing_bottom_pool_multiset_shuffled_falsification": (
            "falsification_contract",
            "add_pool_shuffle_control",
            "include bottom_pool_multiset_shuffled as a falsification condition",
        ),
        "missing_reentry_predicate": (
            "reentry_predicates",
            "reread_repeated_child_block",
            "emit repeated_child_color_block_present for reentry descriptors",
        ),
        "missing_reentry_falsification": (
            "reentry_falsification",
            "add_transition_surplus_control",
            "include transition_color_not_surplus for reentry descriptors",
        ),
    }
    gap, target, hint = hint_map.get(
        reason,
        (
            "unknown_descriptor_gap",
            "inspect_descriptor_contract",
            "inspect the descriptor validator rejection reason",
        ),
    )
    return {
        "schema_version": "slot_pool_descriptor_feedback.v1",
        "accepted": bool(validation.get("accepted", False)),
        "reject_reason": reason,
        "abstraction_gap": gap,
        "repair_target": target,
        "repair_hint": hint,
        "source_kind": str(validation.get("source_kind", "") or ""),
        "hypothesis_id": str(validation.get("hypothesis_id", "") or ""),
    }


def _slot_pool_sequence_repair_descriptor_from_feedback(
    state: Mapping[str, Any],
    feedback: Mapping[str, Any],
    *,
    source_kind: str = "psa_symbolic_induced",
) -> tuple[dict[str, Any] | None, dict[str, Any]]:
    """Return a repaired descriptor-state candidate for repairable feedback.

    This helper does not execute anything.  It only rebuilds the descriptor
    from the current symbolic slot-pool state and revalidates it, giving a
    future PSA/router a concrete `retry descriptor` object to inspect.
    """

    repair_target = str(feedback.get("repair_target", "") or "")
    repairable_targets = {
        "emit_slot_pool_descriptor",
        "rewrite_schema_version",
        "assign_stable_hypothesis_id",
        "reclassify_family",
        "rewrite_source_kind",
        "rewrite_mechanic_state_type",
        "rewrite_goal_link",
        "emit_state_variables",
        "reread_visible_sequence",
        "reread_slot_markers",
        "emit_operator_candidate",
        "rewrite_operator_candidate",
        "rewrite_operator_family",
        "remove_coordinate_bound_operator",
        "reread_required_predicates",
        "add_pool_shuffle_control",
        "reread_repeated_child_block",
        "add_transition_surplus_control",
    }
    diagnostics: dict[str, Any] = {
        "schema_version": "slot_pool_descriptor_repair_attempt.v1",
        "repair_target": repair_target,
        "repaired": False,
        "strategy": "",
        "source_kind": str(source_kind or ""),
        "validation_before": _slot_pool_sequence_hypothesis_descriptor_validation(state),
        "validation_after": {},
    }
    if repair_target == "none":
        candidate = dict(state)
        diagnostics["repaired"] = True
        diagnostics["strategy"] = "no_change"
        diagnostics["validation_after"] = _slot_pool_sequence_hypothesis_descriptor_validation(candidate)
        return candidate, diagnostics
    if repair_target not in repairable_targets:
        diagnostics["strategy"] = "unsupported_repair_target"
        return None, diagnostics

    candidate = dict(state)
    descriptor = _slot_pool_sequence_mechanic_hypothesis_descriptor(candidate)
    descriptor["source_kind"] = str(source_kind or "psa_symbolic_induced")
    candidate["mechanic_hypothesis"] = descriptor
    diagnostics["strategy"] = "rebuild_descriptor_from_current_state"
    diagnostics["validation_after"] = _slot_pool_sequence_hypothesis_descriptor_validation(candidate)
    diagnostics["repaired"] = bool(diagnostics["validation_after"].get("accepted", False))
    return candidate, diagnostics


def _slot_pool_sequence_top_symbols(
    components: list[dict[str, int]],
    *,
    background_value: int,
    border_values: set[int],
) -> list[dict[str, int]]:
    out: list[dict[str, int]] = []
    for comp in components:
        value = int(comp["value"])
        if value == int(background_value) or value in border_values or value in {0, 2}:
            continue
        if int(comp["min_y"]) > 8:
            continue
        if not (4 <= int(comp["width"]) <= 8 and 4 <= int(comp["height"]) <= 8):
            continue
        if not (12 <= int(comp["area"]) <= 40):
            continue
        out.append({"color": value, "x": int(comp["cx"]), "y": int(comp["cy"])})
    return sorted(out, key=lambda item: (int(item["y"]), int(item["x"])))


def _slot_pool_sequence_bottom_separator(
    components: list[dict[str, int]],
    *,
    width: int,
) -> dict[str, int] | None:
    candidates = [
        comp
        for comp in components
        if int(comp["min_y"]) >= 40
        and int(comp["height"]) <= 2
        and int(comp["width"]) >= max(20, int(width * 0.75))
        and int(comp["area"]) >= max(20, int(width * 0.75))
    ]
    if not candidates:
        return None
    return max(candidates, key=lambda comp: (int(comp["min_y"]), int(comp["width"])))


def _slot_pool_sequence_slots(
    components: list[dict[str, int]],
    *,
    separator_value: int,
    separator_y: int,
) -> list[dict[str, int]]:
    slots: list[dict[str, int]] = []
    for comp in components:
        if int(comp["value"]) != int(separator_value):
            continue
        if int(comp["area"]) != 4 or int(comp["width"]) > 3 or int(comp["height"]) > 3:
            continue
        if not (10 <= int(comp["cy"]) < int(separator_y) - 4):
            continue
        slots.append({"x": int(comp["cx"]), "y": int(comp["cy"]), "color": int(comp["value"])})
    return sorted(slots, key=lambda item: (int(item["y"]), int(item["x"])))


def _slot_pool_sequence_order_slots(
    slots: list[dict[str, int]],
    *,
    fixed_items: list[dict[str, int]] | None = None,
    sequence_colors: list[int] | None = None,
    pools: list[dict[str, int]] | None = None,
) -> tuple[list[dict[str, int]], str]:
    if not slots:
        return [], ""
    fixed = [dict(item) for item in list(fixed_items or [])]
    rows: dict[int, list[dict[str, int]]] = defaultdict(list)
    for slot in slots:
        item = dict(slot)
        item.setdefault("role", "fillable")
        rows[int(item["y"])].append(item)
    ordered_rows = [(y, sorted(items, key=lambda item: int(item["x"]))) for y, items in sorted(rows.items())]
    if len(ordered_rows) == 1:
        return ordered_rows[0][1], "single_row_direct"
    if len(ordered_rows) != 2:
        return [], "unsupported_row_count"

    _top_y, top = ordered_rows[0]
    _child_y, child = ordered_rows[1]
    pitch = _slot_pool_sequence_pitch([int(item["x"]) for item in top + child])
    if pitch <= 0 or len(top) < 2 or len(child) < 2:
        return [], "unsupported_two_row_geometry"
    top_xs = [int(item["x"]) for item in top]
    expected_xs = list(range(min(top_xs), max(top_xs) + 1, pitch))
    present = set(top_xs)
    missing = [x for x in expected_xs if x not in present]
    if len(missing) == 0 and fixed:
        return _slot_pool_sequence_order_slots_with_fixed_child(top, child, fixed, pitch=pitch)
    if len(missing) == 0 and sequence_colors and pools and _slot_pool_sequence_reentry_enabled():
        ordered, kind = _slot_pool_sequence_order_slots_with_reentry(
            top,
            child,
            sequence_colors=sequence_colors,
            pools=pools,
        )
        if ordered:
            return ordered, kind
        cyclic_ordered, cyclic_kind = _slot_pool_sequence_order_slots_with_cyclic_frame_reentry(
            top,
            child,
            sequence_colors=sequence_colors,
            pools=pools,
        )
        if cyclic_ordered:
            return cyclic_ordered, cyclic_kind
    if len(missing) == 1:
        gap_x = int(missing[0])
        before = [item for item in top if int(item["x"]) < gap_x]
        after = [item for item in top if int(item["x"]) > gap_x]
        if not before or not after:
            return [], "edge_gap_not_frame_transition"
        child_xs = [int(item["x"]) for item in child]
        if max(child_xs) < min(top_xs) or min(child_xs) > max(top_xs):
            return [], "child_row_not_under_parent"
        return before + child + after, "single_child_row_gap"
    if len(missing) < 2:
        return [], "unsupported_gap_count"
    child_xs = [int(item["x"]) for item in child]
    if max(child_xs) < min(top_xs) or min(child_xs) > max(top_xs):
        return [], "child_row_not_under_parent"
    child_runs: list[list[dict[str, int]]] = []
    for item in child:
        if not child_runs or int(item["x"]) - int(child_runs[-1][-1]["x"]) > pitch:
            child_runs.append([item])
        else:
            child_runs[-1].append(item)
    if len(child_runs) != len(missing):
        multi_fixed, multi_fixed_kind = _slot_pool_sequence_order_slots_with_multi_fixed_children(
            slots,
            fixed,
            sequence_colors=sequence_colors or [],
            pools=pools or [],
            pitch=pitch,
        )
        if multi_fixed:
            return multi_fixed, multi_fixed_kind
        return [], "child_run_gap_count_mismatch"
    ordered: list[dict[str, int]] = []
    last_cut = min(expected_xs) - pitch
    for gap_x, child_run in zip(missing, child_runs):
        segment = [item for item in top if last_cut < int(item["x"]) < int(gap_x)]
        if not segment:
            return [], "missing_parent_segment_before_child"
        ordered.extend(segment)
        ordered.extend(child_run)
        last_cut = int(gap_x)
    tail = [item for item in top if int(item["x"]) > last_cut]
    if not tail:
        return [], "missing_parent_tail_after_child"
    ordered.extend(tail)
    return ordered, "multi_child_row_gaps"

    # Unreachable, but keep static type-checkers conservative.


def _slot_pool_sequence_order_slots_with_fixed_child(
    top: list[dict[str, int]],
    child: list[dict[str, int]],
    fixed: list[dict[str, int]],
    *,
    pitch: int,
) -> tuple[list[dict[str, int]], str]:
    if not fixed or len(top) < 3 or len(child) < 1 or pitch <= 0:
        return [], "unsupported_fixed_child_geometry"
    child_y_values = [int(item["y"]) for item in child]
    if child_y_values:
        child_y = int(round(sum(child_y_values) / len(child_y_values)))
        fixed = [item for item in fixed if abs(int(item["y"]) - child_y) <= max(1, pitch // 2)]
    if not fixed:
        return [], "missing_fixed_child_slot"
    fixed_items = sorted((dict(item, role="fixed") for item in fixed), key=lambda item: int(item["x"]))
    child_units = sorted(fixed_items + [dict(item, role="fillable") for item in child], key=lambda item: int(item["x"]))
    child_xs = [int(item["x"]) for item in child_units]
    top_xs = [int(item["x"]) for item in top]
    if max(child_xs) < min(top_xs) or min(child_xs) > max(top_xs):
        return [], "child_row_not_under_parent"
    median_child_x = child_xs[len(child_xs) // 2]
    entry = min(top, key=lambda item: (abs(int(item["x"]) - median_child_x), int(item["x"])))
    entry_x = int(entry["x"])
    before = [dict(item, role="fillable") for item in top if int(item["x"]) < entry_x]
    after = [dict(item, role="fillable") for item in top if int(item["x"]) > entry_x]
    if not before or not after:
        return [], "edge_entry_not_frame_transition"
    transition_color = int(fixed_items[0]["color"])
    transition_entry = dict(entry, role="transition_entry", transition_color=transition_color)
    return before + [transition_entry] + child_units + after, "fixed_child_explicit_entry"


def _slot_pool_sequence_reentry_enabled() -> bool:
    raw = str(os.environ.get("ECA_SLOT_POOL_SEQUENCE_ENABLE_REENTRY", "1") or "1").strip().lower()
    return raw not in {"0", "false", "no", "off"}


def _slot_pool_sequence_order_slots_with_cyclic_frame_reentry(
    top: list[dict[str, int]],
    child: list[dict[str, int]],
    *,
    sequence_colors: list[int],
    pools: list[dict[str, int]],
) -> tuple[list[dict[str, int]], str]:
    if len(top) < 3 or len(child) < 3 or not sequence_colors or not pools:
        return [], "unsupported_cyclic_reentry_geometry"
    root_fill_count = len(top) - 1
    child_fill_count = len(child) - 1
    block_len = root_fill_count + child_fill_count
    if block_len <= 0 or len(sequence_colors) != block_len * 2:
        return [], "cyclic_reentry_sequence_length_mismatch"
    first_block = [int(color) for color in sequence_colors[:block_len]]
    second_block = [int(color) for color in sequence_colors[block_len:]]
    if first_block != second_block:
        return [], "cyclic_reentry_sequence_not_repeated"
    root_transition_color = int(first_block[0])
    child_transition_color = int(first_block[root_fill_count])
    required_counts = Counter(first_block)
    required_counts[root_transition_color] += 1
    required_counts[child_transition_color] += 1
    pool_counts = Counter(int(item["color"]) for item in pools)
    for color, count in required_counts.items():
        if int(pool_counts.get(int(color), 0)) < int(count):
            return [], "cyclic_reentry_pool_count_mismatch"

    ordered: list[dict[str, int]] = []
    for slot, color in zip(top[:root_fill_count], first_block[:root_fill_count]):
        ordered.append(dict(slot, role="fillable", color=int(color)))
    ordered.append(
        dict(
            top[-1],
            role="transition_entry",
            transition_color=child_transition_color,
            color=int(top[-1].get("color", 0)),
        )
    )
    child_colors = first_block[root_fill_count:]
    for slot, color in zip(child[:child_fill_count], child_colors):
        ordered.append(dict(slot, role="fillable", color=int(color)))
    ordered.append(
        dict(
            child[-1],
            role="transition_entry",
            transition_color=root_transition_color,
            color=int(child[-1].get("color", 0)),
            reentry_colors=list(second_block),
        )
    )
    return ordered, "cyclic_frame_reentry"


def _slot_pool_sequence_order_slots_with_reentry(
    top: list[dict[str, int]],
    child: list[dict[str, int]],
    *,
    sequence_colors: list[int],
    pools: list[dict[str, int]],
) -> tuple[list[dict[str, int]], str]:
    if len(top) < 3 or len(child) < 2:
        return [], "unsupported_reentry_geometry"
    child_len = len(child)
    if len(sequence_colors) < child_len * 2 + 1:
        return [], "sequence_too_short_for_reentry"
    transition_count = 2
    pool_counts = Counter(int(item["color"]) for item in pools)
    sequence_counts = Counter(int(color) for color in sequence_colors)
    transition_candidates = [
        color
        for color, count in sorted(pool_counts.items())
        if count >= transition_count and (color not in sequence_counts or count > sequence_counts[color])
    ]
    if not transition_candidates:
        return [], "missing_reentry_transition_color"
    transition_color = int(transition_candidates[0])
    for start in range(1, len(sequence_colors) - (2 * child_len) + 1):
        first = sequence_colors[start : start + child_len]
        second = sequence_colors[start + child_len : start + 2 * child_len]
        if first != second:
            continue
        prefix_len = start
        suffix_len = len(sequence_colors) - start - (2 * child_len)
        if suffix_len < 1:
            continue
        if prefix_len + transition_count + suffix_len != len(top):
            continue
        if prefix_len + transition_count > len(top):
            continue
        first_entry = dict(top[prefix_len], role="transition_entry", transition_color=transition_color)
        second_entry = dict(
            top[prefix_len + 1],
            role="transition_entry",
            transition_color=transition_color,
            reentry_colors=list(second),
        )
        ordered: list[dict[str, int]] = []
        ordered.extend(dict(item, role="fillable") for item in top[:prefix_len])
        ordered.append(first_entry)
        ordered.extend(dict(item, role="fillable") for item in child)
        ordered.append(second_entry)
        ordered.extend(dict(item, role="fillable") for item in top[prefix_len + transition_count :])
        return ordered, "repeated_child_reentry"
    return [], "no_repeated_child_sequence_block"


def _slot_pool_sequence_order_slots_with_multi_fixed_children(
    slots: list[dict[str, int]],
    fixed: list[dict[str, int]],
    *,
    sequence_colors: list[int],
    pools: list[dict[str, int]],
    pitch: int,
) -> tuple[list[dict[str, int]], str]:
    if pitch <= 0 or len(sequence_colors) < 3 or not fixed or not pools:
        return [], "unsupported_multi_fixed_child_geometry"
    units: list[dict[str, int]] = []
    for slot in slots:
        units.append({"x": int(slot["x"]), "y": int(slot["y"]), "color": int(slot["color"]), "role": "fillable"})
    for item in fixed:
        units.append({"x": int(item["x"]), "y": int(item["y"]), "color": int(item["color"]), "role": "fixed"})
    rows: dict[int, list[dict[str, int]]] = defaultdict(list)
    for unit in units:
        rows[int(unit["y"])].append(dict(unit))
    clusters: list[dict[str, Any]] = []
    split_gap = max(pitch + 2, int(round(pitch * 1.5)))
    for row_y, row_units in sorted(rows.items()):
        ordered = sorted(row_units, key=lambda item: int(item["x"]))
        current: list[dict[str, int]] = []
        for item in ordered:
            if current and int(item["x"]) - int(current[-1]["x"]) > split_gap:
                clusters.append({"y": int(row_y), "units": current})
                current = []
            current.append(dict(item))
        if current:
            clusters.append({"y": int(row_y), "units": current})
    if len(clusters) < 3:
        return [], "unsupported_multi_fixed_child_geometry"

    for cluster in clusters:
        cluster_units = sorted(list(cluster["units"]), key=lambda item: int(item["x"]))
        cluster["units"] = cluster_units
        cluster["fixed_count"] = sum(1 for item in cluster_units if str(item.get("role")) == "fixed")
        cluster["fillable_count"] = sum(1 for item in cluster_units if str(item.get("role")) == "fillable")
        cluster["min_x"] = min(int(item["x"]) for item in cluster_units)
        cluster["max_x"] = max(int(item["x"]) for item in cluster_units)

    child_clusters = [
        cluster
        for cluster in clusters
        if int(cluster.get("fixed_count", 0)) >= 1 and int(cluster.get("fillable_count", 0)) >= 1
    ]
    if len(child_clusters) < 2:
        return [], "missing_multi_fixed_child_clusters"
    viable_children: list[dict[str, Any]] = []
    for child in child_clusters:
        child_units = list(child["units"])
        first_fillable = next(
            (idx for idx, item in enumerate(child_units) if str(item.get("role")) == "fillable"),
            len(child_units),
        )
        if any(str(item.get("role")) != "fixed" for item in child_units[:first_fillable]):
            continue
        fixed_prefix = [int(item["color"]) for item in child_units[:first_fillable]]
        if not fixed_prefix:
            continue
        viable_children.append(dict(child, fixed_prefix=fixed_prefix, transition_color=int(fixed_prefix[0])))
    if len(viable_children) < 2:
        return [], "missing_multi_fixed_child_prefixes"

    root_candidates = [
        cluster
        for cluster in clusters
        if int(cluster.get("fixed_count", 0)) == 0
        and int(cluster.get("fillable_count", 0)) == len(list(cluster.get("units") or []))
        and len(list(cluster.get("units") or [])) == len(viable_children)
    ]
    if not root_candidates:
        return [], "missing_multi_fixed_child_root"

    def _try_root(root: dict[str, Any]) -> list[dict[str, int]] | None:
        root_units = sorted(list(root["units"]), key=lambda item: int(item["x"]))
        pool_counts = Counter(int(item["color"]) for item in pools)
        children = sorted(viable_children, key=lambda item: (int(item["y"]), int(item["min_x"])))

        def _search(
            root_index: int,
            sequence_index: int,
            remaining_pool: Counter[int],
            remaining_children: tuple[int, ...],
            picked: list[tuple[dict[str, int], dict[str, Any], list[int]]],
        ) -> list[tuple[dict[str, int], dict[str, Any], list[int]]] | None:
            if root_index == len(root_units):
                if sequence_index == len(sequence_colors) and not remaining_children:
                    return picked
                return None
            if not remaining_children:
                return None
            root_slot = dict(root_units[root_index])
            for child_index in remaining_children:
                child = children[child_index]
                child_units = list(child["units"])
                fixed_prefix = [int(value) for value in list(child["fixed_prefix"])]
                child_len = len(child_units)
                end = sequence_index + child_len
                if end > len(sequence_colors):
                    continue
                if sequence_colors[sequence_index : sequence_index + len(fixed_prefix)] != fixed_prefix:
                    continue
                transition_color = int(child["transition_color"])
                if int(remaining_pool.get(transition_color, 0)) <= 0:
                    continue
                next_pool = Counter(remaining_pool)
                next_pool[transition_color] -= 1
                fill_colors = sequence_colors[sequence_index + len(fixed_prefix) : end]
                feasible = True
                for color in fill_colors:
                    if int(next_pool.get(int(color), 0)) <= 0:
                        feasible = False
                        break
                    next_pool[int(color)] -= 1
                if not feasible:
                    continue
                next_children = tuple(idx for idx in remaining_children if idx != child_index)
                result = _search(
                    root_index + 1,
                    end,
                    next_pool,
                    next_children,
                    picked + [(root_slot, child, [int(color) for color in fill_colors])],
                )
                if result is not None:
                    return result
            return None

        solution = _search(0, 0, pool_counts, tuple(range(len(children))), [])
        if solution is None:
            return None
        ordered: list[dict[str, int]] = []
        for root_slot, child, fill_colors in solution:
            ordered.append(
                {
                    "x": int(root_slot["x"]),
                    "y": int(root_slot["y"]),
                    "color": int(root_slot["color"]),
                    "role": "transition_entry",
                    "transition_color": int(child["transition_color"]),
                }
            )
            fill_iter = iter(fill_colors)
            for unit in list(child["units"]):
                if str(unit.get("role")) == "fixed":
                    ordered.append({"x": int(unit["x"]), "y": int(unit["y"]), "color": int(unit["color"]), "role": "fixed"})
                else:
                    assigned_color = int(next(fill_iter))
                    ordered.append(
                        {
                            "x": int(unit["x"]),
                            "y": int(unit["y"]),
                            "color": assigned_color,
                            "role": "fillable",
                        }
                    )
        return ordered

    for root in sorted(root_candidates, key=lambda item: (int(item["y"]), int(item["min_x"]))):
        ordered = _try_root(root)
        if ordered:
            return ordered, "multi_fixed_child_transition"
    return [], "multi_fixed_child_sequence_mismatch"


def _slot_pool_sequence_order_slots_with_frame_graph(
    components: list[dict[str, int]],
    *,
    slots: list[dict[str, int]],
    fixed_items: list[dict[str, int]],
    pools: list[dict[str, int]],
    sequence_colors: list[int],
    separator_y: int,
    background_value: int,
    border_values: set[int],
    separator_value: int,
) -> tuple[list[dict[str, int]], str]:
    if len(sequence_colors) < 3 or not slots or not pools:
        return [], "unsupported_frame_graph_geometry"
    excluded = set(border_values) | {int(background_value), int(separator_value), 0, 2}
    frame_boxes: list[dict[str, Any]] = []
    for comp in components:
        value = int(comp["value"])
        if value in excluded:
            continue
        if int(comp["min_y"]) < 10 or int(comp["max_y"]) >= int(separator_y) - 2:
            continue
        if not (10 <= int(comp["width"]) <= 32 and 8 <= int(comp["height"]) <= 16):
            continue
        if int(comp["area"]) < 40:
            continue
        frame_boxes.append(
            {
                "color": value,
                "min_x": int(comp["min_x"]),
                "max_x": int(comp["max_x"]),
                "min_y": int(comp["min_y"]),
                "max_y": int(comp["max_y"]),
                "units": [],
            }
        )
    if len(frame_boxes) < 2:
        return [], "missing_frame_graph_boxes"

    def _assign_unit(unit: Mapping[str, Any]) -> bool:
        ux = int(unit["x"])
        uy = int(unit["y"])
        candidates = [
            frame
            for frame in frame_boxes
            if int(frame["min_x"]) <= ux <= int(frame["max_x"])
            and int(frame["min_y"]) <= uy <= int(frame["max_y"])
        ]
        if not candidates:
            return False
        frame = min(
            candidates,
            key=lambda item: (
                (int(item["max_x"]) - int(item["min_x"])) * (int(item["max_y"]) - int(item["min_y"])),
                int(item["min_y"]),
                int(item["min_x"]),
            ),
        )
        frame["units"].append(dict(unit))
        return True

    for slot in slots:
        if not _assign_unit({"x": int(slot["x"]), "y": int(slot["y"]), "color": int(slot["color"]), "role": "fillable"}):
            return [], "unassigned_frame_graph_slot"
    for item in fixed_items:
        _assign_unit({"x": int(item["x"]), "y": int(item["y"]), "color": int(item["color"]), "role": "fixed"})

    frames = []
    for idx, frame in enumerate(sorted(frame_boxes, key=lambda item: (int(item["min_y"]), int(item["min_x"])))):
        units = sorted(list(frame["units"]), key=lambda item: (int(item["y"]), int(item["x"])))
        if not units:
            continue
        frames.append(dict(frame, index=len(frames), units=units))
    if len(frames) < 2:
        return [], "missing_frame_graph_units"
    color_to_frame: dict[int, int] = {}
    for frame in frames:
        color = int(frame["color"])
        if color in color_to_frame:
            return [], "ambiguous_frame_graph_target_color"
        color_to_frame[color] = int(frame["index"])

    root_index = 0
    pool_by_color: dict[int, list[dict[str, int]]] = {}
    for item in pools:
        pool_by_color.setdefault(int(item["color"]), []).append(dict(item))
    for items in pool_by_color.values():
        items.sort(key=lambda item: (int(item["x"]), int(item["y"])))
    initial_pool_counts = Counter({color: len(items) for color, items in pool_by_color.items()})

    def _search_frame(
        frame_index: int,
        sequence_index: int,
        remaining_pool: Counter[int],
        stack: tuple[int, ...],
        used_transition_targets: frozenset[int],
    ) -> tuple[int, Counter[int], list[dict[str, int]], frozenset[int]] | None:
        frame = frames[frame_index]

        def _search_unit(
            unit_index: int,
            current_sequence_index: int,
            current_pool: Counter[int],
            current_used_targets: frozenset[int],
        ) -> tuple[int, Counter[int], list[dict[str, int]], frozenset[int]] | None:
            if unit_index == len(frame["units"]):
                if frame_index == root_index and len(stack) == 1 and current_sequence_index != len(sequence_colors):
                    return None
                return current_sequence_index, current_pool, [], current_used_targets
            unit = dict(frame["units"][unit_index])
            role = str(unit.get("role", "fillable") or "fillable")
            if role == "fixed":
                if current_sequence_index >= len(sequence_colors):
                    return None
                if int(unit.get("color", -999)) != int(sequence_colors[current_sequence_index]):
                    return None
                tail = _search_unit(
                    unit_index + 1,
                    current_sequence_index + 1,
                    current_pool,
                    current_used_targets,
                )
                if tail is None:
                    return None
                next_index, next_pool, tail_units, next_used = tail
                return next_index, next_pool, [dict(unit, role="fixed")] + tail_units, next_used

            if current_sequence_index < len(sequence_colors):
                basket_color = int(sequence_colors[current_sequence_index])
                if int(current_pool.get(basket_color, 0)) > 0:
                    basket_pool = Counter(current_pool)
                    basket_pool[basket_color] -= 1
                    basket_tail = _search_unit(
                        unit_index + 1,
                        current_sequence_index + 1,
                        basket_pool,
                        current_used_targets,
                    )
                    if basket_tail is not None:
                        next_index, next_pool, tail_units, next_used = basket_tail
                        filled = dict(unit, role="fillable", color=basket_color)
                        return next_index, next_pool, [filled] + tail_units, next_used

            for target_color, target_index in sorted(color_to_frame.items(), key=lambda item: item[0]):
                if target_index == frame_index or target_index in stack or target_index in current_used_targets:
                    continue
                if int(current_pool.get(int(target_color), 0)) <= 0:
                    continue
                transition_pool = Counter(current_pool)
                transition_pool[int(target_color)] -= 1
                child = _search_frame(
                    target_index,
                    current_sequence_index,
                    transition_pool,
                    stack + (target_index,),
                    frozenset(set(current_used_targets) | {target_index}),
                )
                if child is None:
                    continue
                child_index, child_pool, child_units, child_used = child
                transition_tail = _search_unit(unit_index + 1, child_index, child_pool, child_used)
                if transition_tail is None:
                    continue
                next_index, next_pool, tail_units, next_used = transition_tail
                transition_unit = dict(
                    unit,
                    role="transition_entry",
                    transition_color=int(target_color),
                    color=int(unit.get("color", separator_value)),
                )
                return next_index, next_pool, [transition_unit] + child_units + tail_units, next_used
            return None

        result = _search_unit(0, sequence_index, remaining_pool, used_transition_targets)
        if result is None:
            return None
        next_index, next_pool, ordered_units, next_used = result
        return next_index, next_pool, ordered_units, next_used

    result = _search_frame(
        root_index,
        0,
        initial_pool_counts,
        (root_index,),
        frozenset({root_index}),
    )
    if result is None:
        return [], "frame_graph_sequence_mismatch"
    sequence_index, _remaining_pool, ordered, _used_targets = result
    if sequence_index != len(sequence_colors):
        return [], "frame_graph_did_not_consume_sequence"
    transition_count = sum(1 for item in ordered if str(item.get("role")) == "transition_entry")
    if transition_count <= 0:
        return [], "frame_graph_missing_transition"
    return ordered, "frame_graph_transition_tree"


def _slot_pool_sequence_pitch(xs: list[int]) -> int:
    unique = sorted(set(int(x) for x in xs))
    diffs = [b - a for a, b in zip(unique, unique[1:]) if b > a]
    if not diffs:
        return 0
    counts = Counter(diffs)
    return int(counts.most_common(1)[0][0])


def _slot_pool_sequence_fixed_items(
    components: list[dict[str, int]],
    *,
    separator_y: int,
    background_value: int,
    border_values: set[int],
    separator_value: int,
) -> list[dict[str, int]]:
    excluded = set(border_values) | {int(background_value), int(separator_value), 0}
    items: list[dict[str, int]] = []
    for comp in components:
        value = int(comp["value"])
        if value in excluded:
            continue
        if int(comp["max_y"]) <= 14:
            continue
        if not (10 <= int(comp["cy"]) < int(separator_y) - 4):
            continue
        if not (3 <= int(comp["width"]) <= 6 and 3 <= int(comp["height"]) <= 6):
            continue
        if not (9 <= int(comp["area"]) <= 36):
            continue
        items.append({"color": value, "x": int(comp["cx"]), "y": int(comp["cy"]), "role": "fixed"})
    return sorted(items, key=lambda item: (int(item["y"]), int(item["x"])))


def _slot_pool_sequence_pool_items(
    components: list[dict[str, int]],
    *,
    separator_y: int,
    background_value: int,
    border_values: set[int],
    separator_value: int,
) -> list[dict[str, int]]:
    excluded = set(border_values) | {int(background_value), int(separator_value), 0}
    items: list[dict[str, int]] = []
    for comp in components:
        value = int(comp["value"])
        if value in excluded:
            continue
        if int(comp["min_y"]) <= int(separator_y):
            continue
        if not (3 <= int(comp["width"]) <= 6 and 3 <= int(comp["height"]) <= 6):
            continue
        if not (9 <= int(comp["area"]) <= 36):
            continue
        items.append({"color": value, "x": int(comp["cx"]), "y": int(comp["cy"])})
    return sorted(items, key=lambda item: (int(item["x"]), int(item["y"])))


def _slot_pool_sequence_plan(
    state: Mapping[str, Any] | None,
    available: set[str],
) -> list[tuple[str, dict[str, Any]]] | None:
    if state is None:
        return None
    out: list[tuple[str, dict[str, Any]]] = []
    for step in list(state.get("operation_plan") or []):
        action: str = ""
        payload: dict[str, Any] = {}
        if isinstance(step, Mapping):
            action = _normalize_action_name(step.get("action_name") or step.get("action"))
            raw_payload = step.get("payload") if isinstance(step.get("payload"), Mapping) else {}
            payload = dict(raw_payload)
        elif isinstance(step, (list, tuple)) and len(step) >= 2:
            action = _normalize_action_name(step[0])
            payload = dict(step[1] or {}) if isinstance(step[1], Mapping) else {}
        if not action or action not in available:
            return None
        out.append((action, payload))
    return out or None


def _compact_slot_pool_sequence_state(state: Mapping[str, Any] | None) -> dict[str, Any] | None:
    if state is None:
        return None
    hypothesis_validation = _slot_pool_sequence_hypothesis_descriptor_validation(state)
    return {
        "mechanic_state_type": str(state.get("mechanic_state_type", "") or ""),
        "goal_link_type": str(state.get("goal_link_type", "") or ""),
        "sequence_colors": list(state.get("sequence_colors") or []),
        "sequence_len": int(state.get("sequence_len", 0) or 0),
        "slot_count": int(state.get("slot_count", 0) or 0),
        "pool_count": int(state.get("pool_count", 0) or 0),
        "operation_plan_len": int(state.get("operation_plan_len", 0) or 0),
        "mechanic_hypothesis_id": str(
            (state.get("mechanic_hypothesis") or {}).get("hypothesis_id", "")
            if isinstance(state.get("mechanic_hypothesis"), Mapping)
            else ""
        ),
        "mechanic_hypothesis_source_kind": str(
            (state.get("mechanic_hypothesis") or {}).get("source_kind", "")
            if isinstance(state.get("mechanic_hypothesis"), Mapping)
            else ""
        ),
        "mechanic_hypothesis_valid": bool(hypothesis_validation["accepted"]),
        "mechanic_hypothesis_reject_reason": str(hypothesis_validation["reject_reason"]),
        "reader_confidence": float(state.get("reader_confidence", 0.0) or 0.0),
        "goal_link_confidence": float(state.get("goal_link_confidence", 0.0) or 0.0),
    }


_PAINT_REGION_BASKET_POSITIONS = {
    0: (1, 0),
    1: (2, 0),
    2: (2, 1),
    3: (2, 2),
    4: (1, 2),
    5: (0, 2),
    6: (0, 1),
    7: (0, 0),
}
_PAINT_REGION_INDEX_BY_POSITION = {pos: idx for idx, pos in _PAINT_REGION_BASKET_POSITIONS.items()}
_PAINT_REGION_ACTION_DELTAS = {
    "ACTION1": (0, -1),
    "ACTION2": (0, 1),
    "ACTION3": (-1, 0),
    "ACTION4": (1, 0),
}


def _paint_region_reference_state(frame: np.ndarray) -> dict[str, Any] | None:
    state, _diagnostics = _paint_region_reference_state_with_diagnostics(frame)
    return state


def _paint_region_reference_state_with_diagnostics(frame: np.ndarray) -> tuple[dict[str, Any] | None, dict[str, Any]]:
    arr = np.asarray(frame)
    if arr.ndim == 3:
        arr = arr[-1]
    diagnostics: dict[str, Any] = {
        "schema_version": "paint_region_reference_reader_diagnostics.v1",
        "reject_reason": "",
    }
    if arr.ndim != 2 or arr.shape[0] < 44 or arr.shape[1] < 48:
        diagnostics["reject_reason"] = "frame_too_small_or_non_2d"
        return None, diagnostics
    reference = np.asarray(arr[3:13, 3:13], dtype=np.int16)
    canvas = np.asarray(arr[34:44, 27:37], dtype=np.int16)
    if reference.shape != (10, 10) or canvas.shape != (10, 10):
        diagnostics["reject_reason"] = "missing_reference_or_canvas_window"
        return None, diagnostics
    goal_mask = _paint_region_goal_mask()
    target_colors = {int(v) for v in np.unique(reference[goal_mask]).tolist() if int(v) >= 0}
    diagnostics["target_color_count"] = int(len(target_colors))
    diagnostics["target_colors"] = sorted(target_colors)
    if len(target_colors) < 2 or len(target_colors) > 7:
        diagnostics["reject_reason"] = "target_color_count_out_of_range"
        return None, diagnostics
    swatches = _paint_region_detect_swatches(arr)
    diagnostics["swatch_count"] = int(len(swatches))
    diagnostics["swatch_colors"] = sorted(int(color) for color in swatches)
    if len(swatches) < 2 or not target_colors.issubset(set(swatches)):
        diagnostics["reject_reason"] = "missing_required_swatches"
        diagnostics["missing_swatch_colors"] = sorted(int(color) for color in target_colors - set(swatches))
        return None, diagnostics
    operations, search_diagnostics = _paint_region_solve_with_diagnostics(
        canvas,
        reference,
        swatches,
        max_ops=int(os.environ.get("ECA_PAINT_REGION_REFERENCE_MAX_OPS", "7") or "7"),
        beam_width=int(os.environ.get("ECA_PAINT_REGION_REFERENCE_BEAM_WIDTH", "2500") or "2500"),
    )
    diagnostics["search"] = search_diagnostics
    diagnostics["mask_count"] = int(search_diagnostics.get("mask_count", 0) or 0)
    diagnostics["region_mask_count"] = int(search_diagnostics.get("region_mask_count", 0) or 0)
    diagnostics["arrow_mask_count"] = int(search_diagnostics.get("arrow_mask_count", 0) or 0)
    diagnostics["candidate_count"] = int(search_diagnostics.get("candidate_count", 0) or 0)
    diagnostics["beam_best_mismatch"] = search_diagnostics.get("best_mismatch")
    diagnostics["search_terminal_reason"] = str(search_diagnostics.get("terminal_reason", "") or "")
    if not operations:
        diagnostics["reject_reason"] = "no_operation_solution"
        diagnostics["mismatch_before"] = int(_paint_region_mismatch(canvas, reference))
        return None, diagnostics
    plan = _paint_region_emit_plan(operations, swatches)
    if not plan:
        diagnostics["reject_reason"] = "operation_plan_not_executable"
        diagnostics["operation_count"] = int(len(operations))
        return None, diagnostics
    mismatch_after = _paint_region_mismatch(_paint_region_apply_operations(canvas, operations), reference)
    diagnostics["operation_count"] = int(len(operations))
    diagnostics["operation_plan_len"] = int(len(plan))
    diagnostics["mismatch_before"] = int(_paint_region_mismatch(canvas, reference))
    diagnostics["mismatch_after"] = int(mismatch_after)
    if mismatch_after != 0:
        diagnostics["reject_reason"] = "solution_does_not_match_reference"
        return None, diagnostics
    diagnostics["reject_reason"] = "accepted"
    state = {
        "mechanic_state_type": "paint_region_reference",
        "goal_link_type": "canvas_matches_visible_reference",
        "reference_anchor": (3, 3),
        "canvas_anchor": (27, 34),
        "reference_colors": sorted(target_colors),
        "swatch_colors": sorted(int(color) for color in swatches),
        "operation_count": int(len(operations)),
        "operation_plan": plan,
        "operation_plan_len": int(len(plan)),
        "candidate_count": int(search_diagnostics.get("candidate_count", 0) or 0),
        "mask_count": int(search_diagnostics.get("mask_count", 0) or 0),
        "region_mask_count": int(search_diagnostics.get("region_mask_count", 0) or 0),
        "arrow_mask_count": int(search_diagnostics.get("arrow_mask_count", 0) or 0),
        "beam_best_mismatch": int(search_diagnostics.get("best_mismatch", 0) or 0),
        "search_terminal_reason": str(search_diagnostics.get("terminal_reason", "") or ""),
        "mismatch_before": int(_paint_region_mismatch(canvas, reference)),
        "mismatch_after": int(mismatch_after),
        "expected_goal_delta": 1.0,
        "reader_confidence": 0.82,
        "goal_link_confidence": 0.8,
    }
    state["mechanic_hypothesis"] = _paint_region_reference_mechanic_hypothesis_descriptor(state)
    return state, diagnostics


def _paint_region_goal_mask() -> np.ndarray:
    mask = np.ones((10, 10), dtype=bool)
    for y in range(10):
        mask[y, y] = False
        mask[y, 9 - y] = False
    return mask


def _paint_region_detect_swatches(frame: np.ndarray) -> dict[int, tuple[int, int]]:
    # Phase M-5 (2026-06-01, re-ported 2026-06-11 after merge clobber): a
    # swatch is a 5x5 block with a uniform BORDER colour (the shared
    # swatch-frame colour) and a uniform, different INTERIOR colour. The
    # pre-M-5 code keyed the frame on the LITERAL colour 4 (and excluded
    # interiors {3,4,5}), so on a palette-shifted variant (gtd0) where 4
    # maps elsewhere NO swatches were found (swatch_count=0) and the paint
    # solver never fired. The frame colour is the SAME across all
    # swatches, so it can be auto-discovered as the border colour shared
    # by the most candidates, making detection palette-independent
    # (measured gtd0 0->6 at Phase M-5).
    arr = np.asarray(frame)
    max_y = min(8, arr.shape[0] - 4)
    max_x = arr.shape[1] - 4
    candidates: list[tuple[int, int, int, int]] = []  # (frame, interior, x, y)
    for y in range(0, max_y):
        for x in range(0, max_x):
            patch = arr[y : y + 5, x : x + 5]
            if patch.shape != (5, 5):
                continue
            border = np.concatenate([patch[0, :], patch[4, :], patch[:, 0], patch[:, 4]])
            bvals, bcounts = np.unique(border, return_counts=True)
            bi = int(np.argmax(bcounts))
            if int(bcounts[bi]) < 15:
                continue
            frame_color = int(bvals[bi])
            interior = patch[1:4, 1:4]
            values = [int(v) for v in np.unique(interior).tolist()]
            if len(values) != 1:
                continue
            color = values[0]
            if color == frame_color:
                continue
            candidates.append((frame_color, color, int(x + 2), int(y + 2)))
    if not candidates:
        return {}
    # Auto-discover the shared swatch-frame colour (the border colour used by
    # the most swatch candidates) and the global background (most common cell
    # value), then keep only framed blocks whose interior is neither.
    frame_color = Counter(c[0] for c in candidates).most_common(1)[0][0]
    bg_value = int(np.bincount(np.asarray(arr).astype(int).ravel()).argmax())
    out: dict[int, tuple[int, int]] = {}
    for fc, color, cx, cy in candidates:
        if fc != frame_color or color == bg_value:
            continue
        out.setdefault(int(color), (cx, cy))
    return out


def _paint_region_masks() -> dict[str, tuple[np.ndarray, int, str, dict[str, int]]]:
    masks: dict[str, tuple[np.ndarray, int, str, dict[str, int]]] = {}
    yy, xx = np.indices((10, 10))
    definitions = {
        "basket_0_north_half": (yy < 5, 0, "ACTION5", {}),
        "basket_1_ne_triangle": (xx >= yy, 1, "ACTION5", {}),
        "basket_2_east_half": (xx >= 5, 2, "ACTION5", {}),
        "basket_3_se_triangle": (xx >= 9 - yy, 3, "ACTION5", {}),
        "basket_4_south_half": (yy >= 5, 4, "ACTION5", {}),
        "basket_5_sw_triangle": (xx <= yy, 5, "ACTION5", {}),
        "basket_6_west_half": (xx < 5, 6, "ACTION5", {}),
        "basket_7_nw_triangle": (xx <= 9 - yy, 7, "ACTION5", {}),
        "arrow_north_block": ((yy < 3) & (xx >= 3) & (xx < 7), 0, "ACTION6", {"x": 32, "y": 20}),
        "arrow_west_block": ((yy >= 3) & (yy < 7) & (xx < 3), 6, "ACTION6", {"x": 13, "y": 39}),
    }
    for name, (mask, basket_index, action_name, payload) in definitions.items():
        masks[name] = (np.asarray(mask, dtype=bool), int(basket_index), str(action_name), dict(payload))
    return masks


def _paint_region_mismatch(canvas: np.ndarray, reference: np.ndarray) -> int:
    mask = _paint_region_goal_mask()
    return int(np.count_nonzero(np.asarray(canvas)[mask] != np.asarray(reference)[mask]))


def _paint_region_apply_operations(
    canvas: np.ndarray,
    operations: list[Mapping[str, Any]],
) -> np.ndarray:
    out = np.asarray(canvas, dtype=np.int16).copy()
    masks = _paint_region_masks()
    for operation in operations:
        region = str(operation.get("region", "") or "")
        color = int(operation.get("color", 0) or 0)
        if region not in masks:
            continue
        mask, _basket_index, _action_name, _payload = masks[region]
        out[mask] = color
    return out


def _paint_region_operation_action_cost(
    *,
    current_index: int,
    current_color: int,
    operation: Mapping[str, Any],
) -> int:
    basket_index = int(operation.get("basket_index", 0) or 0)
    color = int(operation.get("color", 0) or 0)
    cost = len(_paint_region_move_actions(current_index, basket_index)) + 1
    if color != int(current_color):
        cost += 1
    return cost


def _paint_region_solve(
    canvas: np.ndarray,
    reference: np.ndarray,
    swatches: Mapping[int, tuple[int, int]],
    *,
    max_ops: int,
    beam_width: int,
) -> list[dict[str, Any]] | None:
    operations, _diagnostics = _paint_region_solve_with_diagnostics(
        canvas,
        reference,
        swatches,
        max_ops=max_ops,
        beam_width=beam_width,
    )
    return operations


def _paint_region_solve_with_diagnostics(
    canvas: np.ndarray,
    reference: np.ndarray,
    swatches: Mapping[int, tuple[int, int]],
    *,
    max_ops: int,
    beam_width: int,
) -> tuple[list[dict[str, Any]] | None, dict[str, Any]]:
    goal_mask = _paint_region_goal_mask()
    masks = _paint_region_masks()
    diagnostics: dict[str, Any] = {
        "schema_version": "paint_region_search_diagnostics.v1",
        "max_ops": int(max_ops),
        "beam_width": int(beam_width),
        "mask_count": int(len(masks)),
        "region_mask_count": int(sum(1 for name in masks if not str(name).startswith("arrow_"))),
        "arrow_mask_count": int(sum(1 for name in masks if str(name).startswith("arrow_"))),
        "candidate_count": 0,
        "expanded_state_count": 0,
        "depth_best_mismatch": [],
        "best_mismatch": None,
        "terminal_reason": "",
    }
    colors = sorted({int(v) for v in np.unique(reference[goal_mask]).tolist() if int(v) in swatches})
    if not colors:
        diagnostics["terminal_reason"] = "no_matching_swatch_colors"
        return None, diagnostics
    candidates: list[dict[str, Any]] = []
    for region, (mask, basket_index, action_name, payload) in masks.items():
        if not bool(np.any(mask & goal_mask)):
            continue
        target_values = set(int(v) for v in np.unique(reference[mask & goal_mask]).tolist())
        for color in colors:
            if color not in target_values:
                continue
            candidates.append(
                {
                    "region": region,
                    "color": int(color),
                    "basket_index": int(basket_index),
                    "action_name": action_name,
                    "payload": dict(payload),
                }
            )
    diagnostics["candidate_count"] = int(len(candidates))
    if not candidates:
        diagnostics["terminal_reason"] = "no_candidate_operations"
        return None, diagnostics
    initial = np.asarray(canvas, dtype=np.int16)
    initial_mismatch = _paint_region_mismatch(initial, reference)
    diagnostics["initial_mismatch"] = int(initial_mismatch)
    diagnostics["best_mismatch"] = int(initial_mismatch)
    diagnostics["depth_best_mismatch"].append(
        {"depth": 0, "state_count": 1, "best_mismatch": int(initial_mismatch)}
    )
    if initial_mismatch == 0:
        diagnostics["terminal_reason"] = "already_solved"
        diagnostics["solution_operation_count"] = 0
        return [], diagnostics
    states: list[tuple[int, int, int, np.ndarray, int, int, list[dict[str, Any]]]] = [
        (initial_mismatch, 0, 0, initial, 0, 15, [])
    ]
    seen: dict[tuple[bytes, int, int], int] = {}
    for depth_index in range(max(1, int(max_ops))):
        next_states: dict[tuple[bytes, int, int], tuple[int, int, int, np.ndarray, int, int, list[dict[str, Any]]]] = {}
        diagnostics["expanded_state_count"] = int(diagnostics["expanded_state_count"]) + len(states)
        for _mismatch, action_cost, _op_count, state_canvas, current_index, current_color, ops in states:
            for candidate in candidates:
                region = str(candidate["region"])
                color = int(candidate["color"])
                mask = masks[region][0]
                if np.all(state_canvas[mask] == color):
                    continue
                new_canvas = state_canvas.copy()
                new_canvas[mask] = color
                mismatch = _paint_region_mismatch(new_canvas, reference)
                new_cost = action_cost + _paint_region_operation_action_cost(
                    current_index=current_index,
                    current_color=current_color,
                    operation=candidate,
                )
                new_ops = ops + [dict(candidate)]
                if mismatch == 0:
                    diagnostics["best_mismatch"] = 0
                    diagnostics["terminal_reason"] = "solved"
                    diagnostics["solution_operation_count"] = int(len(new_ops))
                    diagnostics["solution_action_cost"] = int(new_cost)
                    diagnostics["depth_best_mismatch"].append(
                        {"depth": int(depth_index + 1), "state_count": 1, "best_mismatch": 0}
                    )
                    return new_ops, diagnostics
                key = (bytes(new_canvas[goal_mask].astype(np.int16).tobytes()), int(candidate["basket_index"]), color)
                previous = seen.get(key)
                if previous is not None and previous <= new_cost:
                    continue
                seen[key] = new_cost
                item = (
                    mismatch,
                    new_cost,
                    len(new_ops),
                    new_canvas,
                    int(candidate["basket_index"]),
                    color,
                    new_ops,
                )
                current = next_states.get(key)
                if current is None or (mismatch, new_cost, len(new_ops)) < (current[0], current[1], current[2]):
                    next_states[key] = item
        states = sorted(
            next_states.values(),
            key=lambda item: (item[0], item[1], item[2]),
        )[: max(50, int(beam_width))]
        if not states:
            diagnostics["terminal_reason"] = "no_next_states"
            return None, diagnostics
        best = int(states[0][0])
        diagnostics["best_mismatch"] = min(int(diagnostics["best_mismatch"]), best)
        diagnostics["depth_best_mismatch"].append(
            {"depth": int(depth_index + 1), "state_count": int(len(states)), "best_mismatch": best}
        )
    diagnostics["terminal_reason"] = "max_ops_exhausted"
    return None, diagnostics


def _paint_region_move_actions(source_index: int, target_index: int) -> list[str]:
    source = _PAINT_REGION_BASKET_POSITIONS.get(int(source_index))
    target = _PAINT_REGION_BASKET_POSITIONS.get(int(target_index))
    if source is None or target is None:
        return []
    queue: deque[tuple[tuple[int, int], list[str]]] = deque([(source, [])])
    seen = {source}
    while queue:
        pos, path = queue.popleft()
        if pos == target:
            return path
        for action, (dx, dy) in _PAINT_REGION_ACTION_DELTAS.items():
            next_pos = (pos[0] + dx, pos[1] + dy)
            if next_pos not in _PAINT_REGION_INDEX_BY_POSITION or next_pos in seen:
                continue
            seen.add(next_pos)
            queue.append((next_pos, path + [action]))
    return []


def _paint_region_emit_plan(
    operations: list[Mapping[str, Any]],
    swatches: Mapping[int, tuple[int, int]],
) -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []
    current_index = 0
    current_color = 15
    for operation in operations:
        color = int(operation.get("color", 0) or 0)
        basket_index = int(operation.get("basket_index", 0) or 0)
        if color != current_color:
            site = swatches.get(color)
            if site is None:
                return []
            out.append({"action_name": "ACTION6", "payload": {"x": int(site[0]), "y": int(site[1])}})
            current_color = color
        for action in _paint_region_move_actions(current_index, basket_index):
            out.append({"action_name": action, "payload": {}})
        current_index = basket_index
        action_name = _normalize_action_name(operation.get("action_name"))
        payload = operation.get("payload") if isinstance(operation.get("payload"), Mapping) else {}
        if action_name == "ACTION6":
            if "x" not in payload or "y" not in payload:
                return []
            out.append({"action_name": "ACTION6", "payload": {"x": int(payload["x"]), "y": int(payload["y"])}})
        elif action_name == "ACTION5":
            out.append({"action_name": "ACTION5", "payload": {}})
        else:
            return []
    return out


def _paint_region_reference_plan(
    state: Mapping[str, Any] | None,
    available: set[str],
) -> list[tuple[str, dict[str, Any]]] | None:
    if state is None:
        return None
    out: list[tuple[str, dict[str, Any]]] = []
    for step in list(state.get("operation_plan") or []):
        if not isinstance(step, Mapping):
            continue
        action = _normalize_action_name(step.get("action_name"))
        payload = step.get("payload") if isinstance(step.get("payload"), Mapping) else {}
        if not action or action not in available:
            return None
        out.append((action, dict(payload)))
    return out or None


def _compact_paint_region_reference_state(state: Mapping[str, Any] | None) -> dict[str, Any] | None:
    if state is None:
        return None
    hypothesis_validation = _paint_region_reference_hypothesis_descriptor_validation(state)
    return {
        "mechanic_state_type": str(state.get("mechanic_state_type", "") or ""),
        "goal_link_type": str(state.get("goal_link_type", "") or ""),
        "reference_colors": list(state.get("reference_colors") or []),
        "swatch_colors": list(state.get("swatch_colors") or []),
        "operation_count": int(state.get("operation_count", 0) or 0),
        "operation_plan_len": int(state.get("operation_plan_len", 0) or 0),
        "mismatch_before": int(state.get("mismatch_before", 0) or 0),
        "mismatch_after": int(state.get("mismatch_after", 0) or 0),
        "reader_confidence": float(state.get("reader_confidence", 0.0) or 0.0),
        "goal_link_confidence": float(state.get("goal_link_confidence", 0.0) or 0.0),
        "mechanic_hypothesis_valid": bool(hypothesis_validation["accepted"]),
        "mechanic_hypothesis_reject_reason": str(hypothesis_validation["reject_reason"]),
    }


def _paint_region_reference_mechanic_hypothesis_descriptor(state: Mapping[str, Any]) -> dict[str, Any]:
    reference_colors = [int(color) for color in list(state.get("reference_colors") or [])]
    swatch_colors = [int(color) for color in list(state.get("swatch_colors") or [])]
    operation_count = int(state.get("operation_count", 0) or 0)
    operation_plan_len = int(state.get("operation_plan_len", 0) or 0)
    return {
        "schema_version": "paint_region_reference_mechanic_hypothesis_descriptor.v1",
        "hypothesis_id": (
            "paint_region_reference:"
            f"colors={','.join(str(color) for color in reference_colors)}:"
            f"ops={operation_count}:plan={operation_plan_len}"
        ),
        "family": "paint_reference",
        "source_kind": "frame_symbolic_induced",
        "mechanic_state_type": "paint_region_reference",
        "goal_link_type": "canvas_matches_visible_reference",
        "state_variables": {
            "reference_color_count": int(len(reference_colors)),
            "swatch_count": int(len(swatch_colors)),
            "operation_count": operation_count,
            "operation_plan_len": operation_plan_len,
            "mismatch_before": int(state.get("mismatch_before", 0) or 0),
            "mismatch_after": int(state.get("mismatch_after", 0) or 0),
        },
        "induced_variables": [
            "visible_reference_window",
            "visible_canvas_window",
            "visible_swatch_set",
            "paint_operation_sequence",
        ],
        "predicate_candidates": [
            "visible_reference_present",
            "canvas_present",
            "required_swatches_present",
            "operation_plan_solves_reference",
        ],
        "operator_candidates": [
            {
                "operator_family": "region_paint_macro",
                "coordinate_free": True,
                "operation_count": operation_count,
            }
        ],
        "abort_conditions": [
            "reference_canvas_hash_changed",
            "operation_plan_not_executable",
        ],
        "falsification_conditions": [
            "swatch_colors_shuffled",
            "reference_canvas_mismatch_control",
        ],
        "confidence": 0.72,
    }


def _paint_region_reference_state_with_descriptor_fault_injection(
    state: Mapping[str, Any] | None,
) -> dict[str, Any] | None:
    if state is None:
        return None
    fault = str(os.environ.get("ECA_PAINT_REGION_DESCRIPTOR_FAULT_INJECTION", "") or "").strip()
    if not fault:
        return dict(state)
    out = dict(state)
    descriptor = dict(out.get("mechanic_hypothesis") or {})
    if isinstance(descriptor.get("state_variables"), Mapping):
        descriptor["state_variables"] = dict(descriptor["state_variables"])
    if isinstance(descriptor.get("operator_candidates"), list):
        descriptor["operator_candidates"] = [
            dict(item) if isinstance(item, Mapping) else item
            for item in descriptor["operator_candidates"]
        ]
    for key in (
        "induced_variables",
        "predicate_candidates",
        "abort_conditions",
        "falsification_conditions",
    ):
        if isinstance(descriptor.get(key), list):
            descriptor[key] = list(descriptor[key])
    source_kind = str(os.environ.get("ECA_PAINT_REGION_DESCRIPTOR_FAULT_SOURCE_KIND", "") or "").strip()
    if source_kind and fault != "missing_descriptor":
        descriptor["source_kind"] = source_kind

    if fault == "missing_descriptor":
        out.pop("mechanic_hypothesis", None)
        return out
    if fault == "operation_plan_len_mismatch":
        state_variables = dict(descriptor.get("state_variables") or {})
        state_variables["operation_plan_len"] = max(0, int(out.get("operation_plan_len", 0) or 0) - 1)
        descriptor["state_variables"] = state_variables
    elif fault == "missing_required_predicates":
        predicates = [
            str(item)
            for item in list(descriptor.get("predicate_candidates") or [])
            if str(item) != "operation_plan_solves_reference"
        ]
        descriptor["predicate_candidates"] = predicates
    elif fault == "operator_not_coordinate_free":
        operators = list(descriptor.get("operator_candidates") or [])
        if operators and isinstance(operators[0], Mapping):
            operator = dict(operators[0])
            operator["coordinate_free"] = False
            operators[0] = operator
            descriptor["operator_candidates"] = operators
    elif fault == "missing_swatch_falsification":
        falsification = [
            str(item)
            for item in list(descriptor.get("falsification_conditions") or [])
            if str(item) != "swatch_colors_shuffled"
        ]
        descriptor["falsification_conditions"] = falsification
    else:
        return out
    out["mechanic_hypothesis"] = descriptor
    return out


def _paint_region_reference_hypothesis_descriptor_validation(state: Mapping[str, Any]) -> dict[str, Any]:
    descriptor = state.get("mechanic_hypothesis")
    diagnostics: dict[str, Any] = {
        "schema_version": "paint_region_reference_mechanic_hypothesis_validation.v1",
        "accepted": False,
        "reject_reason": "",
        "rejection_reasons": [],
        "descriptor_schema": "",
        "hypothesis_id": "",
        "family": "",
        "source_kind": "",
        "mechanic_state_type": "",
        "goal_link_type": "",
        "state_operation_count": int(state.get("operation_count", 0) or 0),
        "state_operation_plan_len": int(state.get("operation_plan_len", 0) or 0),
        "state_reference_color_count": int(len(list(state.get("reference_colors") or []))),
        "state_swatch_count": int(len(list(state.get("swatch_colors") or []))),
        "state_mismatch_after": int(state.get("mismatch_after", 0) or 0),
    }

    def reject(reason: str) -> dict[str, Any]:
        diagnostics["reject_reason"] = reason
        diagnostics["rejection_reasons"].append(reason)
        return diagnostics

    if not isinstance(descriptor, Mapping):
        return reject("missing_descriptor")
    diagnostics["descriptor_schema"] = str(descriptor.get("schema_version", "") or "")
    diagnostics["hypothesis_id"] = str(descriptor.get("hypothesis_id", "") or "")
    diagnostics["family"] = str(descriptor.get("family", "") or "")
    diagnostics["source_kind"] = str(descriptor.get("source_kind", "") or "")
    diagnostics["mechanic_state_type"] = str(descriptor.get("mechanic_state_type", "") or "")
    diagnostics["goal_link_type"] = str(descriptor.get("goal_link_type", "") or "")
    if diagnostics["descriptor_schema"] != "paint_region_reference_mechanic_hypothesis_descriptor.v1":
        return reject("bad_schema")
    if not diagnostics["hypothesis_id"]:
        return reject("missing_hypothesis_id")
    if diagnostics["family"] != "paint_reference":
        return reject("bad_family")
    if diagnostics["source_kind"] not in {
        "frame_symbolic_induced",
        "psa_symbolic_induced",
        "psa_llm_proposed",
        "mixed",
        "ledger_confirmed",
    }:
        return reject("bad_source_kind")
    if diagnostics["mechanic_state_type"] != "paint_region_reference":
        return reject("bad_mechanic_state_type")
    if diagnostics["goal_link_type"] != "canvas_matches_visible_reference":
        return reject("bad_goal_link_type")
    state_variables = descriptor.get("state_variables")
    if not isinstance(state_variables, Mapping):
        return reject("missing_state_variables")
    descriptor_operation_plan_len = int(state_variables.get("operation_plan_len", -1))
    descriptor_operation_count = int(state_variables.get("operation_count", -1))
    descriptor_reference_color_count = int(state_variables.get("reference_color_count", -1))
    descriptor_swatch_count = int(state_variables.get("swatch_count", -1))
    descriptor_mismatch_after = int(state_variables.get("mismatch_after", -1))
    diagnostics["descriptor_operation_plan_len"] = descriptor_operation_plan_len
    diagnostics["descriptor_operation_count"] = descriptor_operation_count
    diagnostics["descriptor_reference_color_count"] = descriptor_reference_color_count
    diagnostics["descriptor_swatch_count"] = descriptor_swatch_count
    diagnostics["descriptor_mismatch_after"] = descriptor_mismatch_after
    if descriptor_operation_plan_len != diagnostics["state_operation_plan_len"]:
        return reject("operation_plan_len_mismatch")
    if descriptor_operation_count != diagnostics["state_operation_count"]:
        return reject("operation_count_mismatch")
    if descriptor_reference_color_count != diagnostics["state_reference_color_count"]:
        return reject("reference_color_count_mismatch")
    if descriptor_swatch_count != diagnostics["state_swatch_count"]:
        return reject("swatch_count_mismatch")
    if descriptor_mismatch_after != diagnostics["state_mismatch_after"]:
        return reject("mismatch_after_mismatch")
    operator_candidates = descriptor.get("operator_candidates")
    if not isinstance(operator_candidates, list) or not operator_candidates:
        return reject("missing_operator_candidates")
    operator = operator_candidates[0]
    if not isinstance(operator, Mapping):
        return reject("bad_operator_candidate")
    diagnostics["operator_family"] = str(operator.get("operator_family", "") or "")
    diagnostics["operator_coordinate_free"] = bool(operator.get("coordinate_free"))
    if diagnostics["operator_family"] != "region_paint_macro":
        return reject("bad_operator_family")
    if bool(operator.get("coordinate_free")) is not True:
        return reject("operator_not_coordinate_free")
    predicates = set(str(item) for item in list(descriptor.get("predicate_candidates") or []))
    required_predicates = {
        "visible_reference_present",
        "canvas_present",
        "required_swatches_present",
        "operation_plan_solves_reference",
    }
    if not required_predicates.issubset(predicates):
        diagnostics["missing_predicates"] = sorted(required_predicates - predicates)
        return reject("missing_required_predicates")
    falsification = set(str(item) for item in list(descriptor.get("falsification_conditions") or []))
    if "swatch_colors_shuffled" not in falsification:
        return reject("missing_swatch_falsification")
    if "reference_canvas_mismatch_control" not in falsification:
        return reject("missing_reference_canvas_falsification")
    diagnostics["accepted"] = True
    diagnostics["reject_reason"] = "accepted"
    return diagnostics


def _paint_region_reference_descriptor_feedback(validation: Mapping[str, Any]) -> dict[str, Any]:
    reason = str(validation.get("reject_reason", "") or "")
    hint_map: dict[str, tuple[str, str, str]] = {
        "accepted": ("none", "none", "descriptor already satisfies execution contract"),
        "missing_descriptor": (
            "descriptor_absent",
            "emit_paint_region_descriptor",
            "create a paint_reference mechanic_hypothesis descriptor before execution",
        ),
        "bad_schema": (
            "schema_contract",
            "rewrite_schema_version",
            "emit paint_region_reference_mechanic_hypothesis_descriptor.v1",
        ),
        "missing_hypothesis_id": (
            "identity",
            "assign_stable_hypothesis_id",
            "derive a stable coordinate-free hypothesis id from visible paint variables",
        ),
        "bad_family": (
            "family_classification",
            "reclassify_family",
            "select paint_reference only when reference, canvas, and swatches are visible",
        ),
        "bad_source_kind": (
            "provenance",
            "rewrite_source_kind",
            "use an allowed source kind for descriptor provenance",
        ),
        "bad_mechanic_state_type": (
            "state_type",
            "rewrite_mechanic_state_type",
            "emit paint_region_reference as the mechanic state type",
        ),
        "bad_goal_link_type": (
            "goal_link",
            "rewrite_goal_link",
            "connect the descriptor to canvas_matches_visible_reference",
        ),
        "missing_state_variables": (
            "state_variables",
            "emit_state_variables",
            "include operation counts, color counts, and mismatch state",
        ),
        "operation_plan_len_mismatch": (
            "stale_or_incomplete_plan",
            "reread_paint_operations",
            "recompute visible paint operations and synchronize operation_plan_len",
        ),
        "operation_count_mismatch": (
            "stale_or_incomplete_plan",
            "reread_paint_operations",
            "recompute visible paint operations and synchronize operation_count",
        ),
        "reference_color_count_mismatch": (
            "stale_or_incomplete_state",
            "reread_reference_colors",
            "reread visible reference colors",
        ),
        "swatch_count_mismatch": (
            "stale_or_incomplete_state",
            "reread_swatch_set",
            "reread available swatches",
        ),
        "mismatch_after_mismatch": (
            "goal_state_validation",
            "recompute_paint_solution",
            "recompute solution and verify mismatch_after",
        ),
        "missing_operator_candidates": (
            "operator_model",
            "emit_operator_candidate",
            "add a region_paint_macro operator candidate",
        ),
        "bad_operator_candidate": (
            "operator_model",
            "rewrite_operator_candidate",
            "emit the operator candidate as a typed mapping",
        ),
        "bad_operator_family": (
            "operator_model",
            "rewrite_operator_family",
            "use region_paint_macro as the operator family",
        ),
        "operator_not_coordinate_free": (
            "operator_grounding",
            "remove_coordinate_bound_operator",
            "emit coordinate-free paint intent and leave grounding to symbolic PSA",
        ),
        "missing_required_predicates": (
            "predicate_set",
            "reread_paint_predicates",
            "emit visible reference, canvas, swatch, and solution predicates",
        ),
        "missing_swatch_falsification": (
            "falsification_contract",
            "add_swatch_shuffle_control",
            "include swatch_colors_shuffled as a falsification condition",
        ),
        "missing_reference_canvas_falsification": (
            "falsification_contract",
            "add_reference_canvas_mismatch_control",
            "include reference_canvas_mismatch_control as a falsification condition",
        ),
    }
    gap, target, hint = hint_map.get(
        reason,
        (
            "unknown_descriptor_gap",
            "inspect_descriptor_contract",
            "inspect the descriptor validator rejection reason",
        ),
    )
    return {
        "schema_version": "paint_region_descriptor_feedback.v1",
        "accepted": bool(validation.get("accepted", False)),
        "reject_reason": reason,
        "abstraction_gap": gap,
        "repair_target": target,
        "repair_hint": hint,
        "source_kind": str(validation.get("source_kind", "") or ""),
        "hypothesis_id": str(validation.get("hypothesis_id", "") or ""),
    }


def _paint_region_reference_repair_descriptor_from_feedback(
    state: Mapping[str, Any],
    feedback: Mapping[str, Any],
    *,
    source_kind: str = "psa_symbolic_induced",
) -> tuple[dict[str, Any] | None, dict[str, Any]]:
    repair_target = str(feedback.get("repair_target", "") or "")
    repairable_targets = {
        "emit_paint_region_descriptor",
        "rewrite_schema_version",
        "assign_stable_hypothesis_id",
        "reclassify_family",
        "rewrite_source_kind",
        "rewrite_mechanic_state_type",
        "rewrite_goal_link",
        "emit_state_variables",
        "reread_paint_operations",
        "reread_reference_colors",
        "reread_swatch_set",
        "recompute_paint_solution",
        "emit_operator_candidate",
        "rewrite_operator_candidate",
        "rewrite_operator_family",
        "remove_coordinate_bound_operator",
        "reread_paint_predicates",
        "add_swatch_shuffle_control",
        "add_reference_canvas_mismatch_control",
    }
    diagnostics: dict[str, Any] = {
        "schema_version": "paint_region_descriptor_repair_attempt.v1",
        "repair_target": repair_target,
        "repaired": False,
        "strategy": "",
        "source_kind": str(source_kind or ""),
        "validation_before": _paint_region_reference_hypothesis_descriptor_validation(state),
        "validation_after": {},
    }
    if repair_target == "none":
        candidate = dict(state)
        diagnostics["repaired"] = True
        diagnostics["strategy"] = "no_change"
        diagnostics["validation_after"] = _paint_region_reference_hypothesis_descriptor_validation(candidate)
        return candidate, diagnostics
    if repair_target not in repairable_targets:
        diagnostics["strategy"] = "unsupported_repair_target"
        return None, diagnostics

    candidate = dict(state)
    descriptor = _paint_region_reference_mechanic_hypothesis_descriptor(candidate)
    descriptor["source_kind"] = str(source_kind or "psa_symbolic_induced")
    candidate["mechanic_hypothesis"] = descriptor
    diagnostics["strategy"] = "rebuild_descriptor_from_current_state"
    diagnostics["validation_after"] = _paint_region_reference_hypothesis_descriptor_validation(candidate)
    diagnostics["repaired"] = bool(diagnostics["validation_after"].get("accepted", False))
    return candidate, diagnostics


def _sand_filter_flow_state(frame: np.ndarray) -> dict[str, Any] | None:
    arr = np.asarray(frame)
    if arr.ndim == 3:
        arr = arr[-1]
    if arr.ndim != 2 or arr.shape[0] < 48 or arr.shape[1] < 48:
        return None
    rotation_k = _sand_filter_rotation(arr)
    unrotated = np.rot90(arr, k=-rotation_k).copy() if rotation_k else arr
    if unrotated.shape[0] < 64 or unrotated.shape[1] < 64:
        return None
    for grid_size in (20, 16):
        grid = _sand_filter_cell_grid(unrotated, grid_size=grid_size)
        filters = _sand_filter_detect_filters(grid)
        bowls = _sand_filter_detect_bowls(grid)
        reflectors = _sand_filter_detect_reflectors(grid)
        sources = _sand_filter_detect_sources(grid, filters=filters)
        source_links = _sand_filter_source_links_from_filters(filters)
        if not filters or len(bowls) < 2 or (not sources and not source_links):
            remapped = _sand_filter_role_normalised_grid(grid)
            if remapped is None:
                continue
            filters = _sand_filter_detect_filters(remapped)
            bowls = _sand_filter_detect_bowls(remapped)
            reflectors = _sand_filter_detect_reflectors(remapped)
            sources = _sand_filter_detect_sources(remapped, filters=filters)
            source_links = _sand_filter_source_links_from_filters(filters)
            if not filters or len(bowls) < 2 or (not sources and not source_links):
                continue
        if len(filters) > 6 or len(bowls) > 6 or len(sources) + len(source_links) > 4:
            continue
        multi_redirector_state = _sand_filter_multi_redirector_flow_state(
            grid,
            filters=filters,
            sources=sources,
            source_links=source_links,
            rotation_k=rotation_k,
            grid_size=grid_size,
        )
        if multi_redirector_state is not None:
            multi_redirector_state["cell"] = int(round(float(unrotated.shape[0]) / float(grid_size)))
            return multi_redirector_state
        vertical_bowls = [
            item
            for item in bowls
            if int(item.get("w", 0) or 0) == 2 and int(item.get("h", 0) or 0) == 3
        ]
        horizontal_bowls = [
            item
            for item in bowls
            if not (int(item.get("w", 0) or 0) == 2 and int(item.get("h", 0) or 0) == 3)
        ]
        reflector_targets: list[dict[str, int]] = []
        solve_bowls = horizontal_bowls if vertical_bowls and reflectors else bowls
        target_filters = _sand_filter_solve(
            [(int(item["x"]), int(item["y"]), int(item["w"])) for item in filters],
            [(int(item["x"]), int(item["y"])) for item in sources],
            [(int(item["x"]), int(item["y"]), int(item["w"]), int(item["h"])) for item in solve_bowls],
            time_budget=float(os.environ.get("ECA_SAND_FILTER_FLOW_TIME_BUDGET_SECONDS", "5.0") or "5.0"),
            grid_w=int(grid_size),
            grid_h=int(grid_size),
            source_links=source_links,
        )
        if not target_filters:
            continue
        if vertical_bowls and reflectors:
            primary_vertical = vertical_bowls[0]
            target_x = int(primary_vertical["x"]) - 4
            target_y = int(primary_vertical["y"]) + 1
            if 0 <= target_x <= int(grid_size) - 2 and 3 <= target_y <= int(grid_size) - 2:
                reflector_targets = [
                    {
                        "x": int(target_x),
                        "y": int(target_y),
                        "w": int(reflectors[0].get("w", 2) or 2),
                        "h": int(reflectors[0].get("h", 2) or 2),
                    }
                ]
        plan = _sand_filter_emit_plan(
            filters,
            target_filters,
            rotation_k=rotation_k,
            grid_size=grid_size,
            initial_reflectors=reflectors,
            target_reflectors=reflector_targets,
        )
        if not plan:
            continue
        return {
            "mechanic_state_type": "sand_filter_flow",
            "goal_link_type": "all_bowls_filled_by_routed_flow",
            "cell": int(round(float(unrotated.shape[0]) / float(grid_size))),
            "grid_size": (int(grid_size), int(grid_size)),
            "rotation_k": int(rotation_k),
            "filters": filters,
            "target_filters": [
                {"x": int(x), "y": int(y), "w": int(w), "h": 1}
                for x, y, w in target_filters
            ],
            "bowls": bowls,
            "sources": [
                {"x": int(item["x"]), "y": int(item["y"]), "source_kind": "fixed"}
                for item in sources
            ],
            "source_links": [
                {
                    "filter_index": int(index),
                    "local_x": int(local_x),
                    "local_y": int(local_y),
                    "source_kind": "filter_coupled",
                }
                for index, local_x, local_y in source_links
            ],
            "reflectors": [
                {
                    "x": int(item.get("x", 0) or 0),
                    "y": int(item.get("y", 0) or 0),
                    "w": int(item.get("w", 0) or 0),
                    "h": int(item.get("h", 0) or 0),
                }
                for item in reflectors
            ],
            "target_reflectors": [
                {
                    "x": int(item.get("x", 0) or 0),
                    "y": int(item.get("y", 0) or 0),
                    "w": int(item.get("w", 0) or 0),
                    "h": int(item.get("h", 0) or 0),
                }
                for item in reflector_targets
            ],
            "filter_count": int(len(filters)),
            "bowl_count": int(len(bowls)),
            "source_count": int(len(sources) + len(source_links)),
            "reflector_count": int(len(reflectors)),
            "operation_plan": plan,
            "operation_plan_len": int(len(plan)),
            "expected_goal_delta": 1.0,
            "reader_confidence": min(0.95, 0.58 + 0.04 * len(filters) + 0.03 * len(bowls)),
            "goal_link_confidence": min(0.95, 0.62 + 0.05 * len(bowls)),
        }
    return None


def _sand_filter_multi_redirector_flow_state(
    grid: np.ndarray,
    *,
    filters: Sequence[Mapping[str, Any]],
    sources: Sequence[Mapping[str, Any]],
    source_links: Sequence[tuple[int, int, int]],
    rotation_k: int,
    grid_size: int,
) -> dict[str, Any] | None:
    if int(grid_size) != 20 or int(rotation_k) != 0:
        return None
    horizontal_filters = [dict(item) for item in list(filters or [])]
    source_filter = next(
        (
            item
            for item in horizontal_filters
            if any(isinstance(raw, Sequence) and len(raw) >= 2 for raw in list(item.get("source_offsets") or []))
        ),
        None,
    )
    vertical_filters = _sand_filter_detect_vertical_filters(grid)
    side_bowls = _sand_filter_detect_side_bowls(grid)
    base_bowls = _sand_filter_detect_bowls(grid)
    all_bowls = _sand_filter_merge_components([*base_bowls, *side_bowls])
    left_bowls = sorted(
        [
            item
            for item in side_bowls
            if int(item.get("x", 0) or 0) <= 2
        ],
        key=lambda item: int(item.get("y", 0) or 0),
    )
    right_bowls = sorted(
        [
            item
            for item in side_bowls
            if int(item.get("x", 0) or 0) >= int(grid_size) - 3
        ],
        key=lambda item: int(item.get("y", 0) or 0),
    )
    bottom_bowls = sorted(
        [
            item
            for item in all_bowls
            if int(item.get("w", 0) or 0) == 3
            and int(item.get("h", 0) or 0) == 2
            and int(item.get("y", 0) or 0) >= int(grid_size) - 4
        ],
        key=lambda item: (int(item.get("y", 0) or 0), int(item.get("x", 0) or 0)),
    )
    reflectors = _sand_filter_detect_reflector_components(grid)
    if (
        source_filter is None
        or not vertical_filters
        or len(left_bowls) < 2
        or not right_bowls
        or not bottom_bowls
        or len(reflectors) < 2
        or not sources
        or not source_links
    ):
        return None
    try:
        fixed_source_x = int(sorted(sources, key=lambda item: (int(item.get("y", 0) or 0), int(item.get("x", 0) or 0)))[0]["x"])
        upper_left_y = int(left_bowls[0]["y"])
        right_y = int(right_bowls[0]["y"])
    except (KeyError, TypeError, ValueError):
        return None
    vertical_filter = sorted(
        vertical_filters,
        key=lambda item: abs(int(item.get("x", 0) or 0) - fixed_source_x)
        + abs(int(item.get("y", 0) or 0) - upper_left_y),
    )[0]
    lex_reflector = next(
        (item for item in reflectors if str(item.get("orientation", "")) == "lexuhyxqrsm"),
        None,
    )
    riw_reflector = next(
        (item for item in reflectors if str(item.get("orientation", "")) == "riwynidseun"),
        None,
    )
    if lex_reflector is None:
        lex_reflector = sorted(reflectors, key=lambda item: int(item.get("y", 0) or 0), reverse=True)[0]
    if riw_reflector is None:
        remaining = [item for item in reflectors if item is not lex_reflector]
        riw_reflector = sorted(
            remaining or reflectors,
            key=lambda item: (not bool(item.get("selected", False)), int(item.get("y", 0) or 0)),
        )[0]
    if lex_reflector is riw_reflector:
        return None
    target_specs = [
        {
            "component_kind": "reflector",
            "source": riw_reflector,
            "target": {"x": fixed_source_x + 4, "y": right_y + 1, "w": 2, "h": 2},
            "move_axis_order": "xy",
        },
        {
            "component_kind": "vertical_filter",
            "source": vertical_filter,
            "target": {"x": fixed_source_x - 3, "y": right_y - 1, "w": 1, "h": int(vertical_filter.get("h", 4) or 4)},
            "move_axis_order": "xy",
        },
        {
            "component_kind": "source_filter",
            "source": source_filter,
            "target": {"x": fixed_source_x + 1, "y": upper_left_y, "w": int(source_filter.get("w", 0) or 0), "h": 1},
            "move_axis_order": "xy",
        },
        {
            "component_kind": "reflector",
            "source": lex_reflector,
            "target": {"x": fixed_source_x + 2, "y": right_y + 1, "w": 2, "h": 2},
            "move_axis_order": "yx",
        },
    ]
    plan = _sand_filter_emit_component_plan(
        target_specs,
        rotation_k=rotation_k,
        grid_size=grid_size,
    )
    if not plan:
        return None
    target_filters = [
        {
            "x": int(target_specs[1]["target"]["x"]),
            "y": int(target_specs[1]["target"]["y"]),
            "w": int(target_specs[1]["target"]["w"]),
            "h": int(target_specs[1]["target"]["h"]),
            "filter_orientation": "vertical",
        },
        {
            "x": int(target_specs[2]["target"]["x"]),
            "y": int(target_specs[2]["target"]["y"]),
            "w": int(target_specs[2]["target"]["w"]),
            "h": int(target_specs[2]["target"]["h"]),
            "filter_orientation": "horizontal_source_coupled",
        },
    ]
    target_reflectors = [
        {
            "x": int(target_specs[0]["target"]["x"]),
            "y": int(target_specs[0]["target"]["y"]),
            "w": 2,
            "h": 2,
            "orientation": str(riw_reflector.get("orientation", "unknown")),
        },
        {
            "x": int(target_specs[3]["target"]["x"]),
            "y": int(target_specs[3]["target"]["y"]),
            "w": 2,
            "h": 2,
            "orientation": str(lex_reflector.get("orientation", "unknown")),
        },
    ]
    return {
        "mechanic_state_type": "sand_filter_flow",
        "goal_link_type": "all_bowls_filled_by_routed_flow",
        "reader_extension": "multi_redirector_vertical_filter_source_coupled_flow",
        "grid_size": (int(grid_size), int(grid_size)),
        "rotation_k": int(rotation_k),
        "filters": [*horizontal_filters, *vertical_filters],
        "target_filters": target_filters,
        "bowls": all_bowls,
        "sources": [
            {"x": int(item["x"]), "y": int(item["y"]), "source_kind": "fixed"}
            for item in sources
        ],
        "source_links": [
            {
                "filter_index": int(index),
                "local_x": int(local_x),
                "local_y": int(local_y),
                "source_kind": "filter_coupled",
            }
            for index, local_x, local_y in source_links
        ],
        "reflectors": [
            {
                "x": int(item.get("x", 0) or 0),
                "y": int(item.get("y", 0) or 0),
                "w": int(item.get("w", 0) or 0),
                "h": int(item.get("h", 0) or 0),
                "orientation": str(item.get("orientation", "unknown")),
                "selected": bool(item.get("selected", False)),
            }
            for item in reflectors
        ],
        "target_reflectors": target_reflectors,
        "component_targets": [
            {
                "component_kind": str(spec["component_kind"]),
                "from": {
                    "x": int(spec["source"].get("x", 0) or 0),
                    "y": int(spec["source"].get("y", 0) or 0),
                },
                "to": {
                    "x": int(spec["target"]["x"]),
                    "y": int(spec["target"]["y"]),
                },
                "move_axis_order": str(spec["move_axis_order"]),
            }
            for spec in target_specs
        ],
        "filter_count": int(len(horizontal_filters) + len(vertical_filters)),
        "bowl_count": int(len(all_bowls)),
        "source_count": int(len(sources) + len(source_links)),
        "reflector_count": int(len(reflectors)),
        "operation_plan": plan,
        "operation_plan_len": int(len(plan)),
        "expected_goal_delta": 1.0,
        "reader_confidence": 0.86,
        "goal_link_confidence": 0.86,
    }


def _sand_filter_merge_components(
    items: Sequence[Mapping[str, Any]],
) -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []
    seen: set[tuple[int, int, int, int]] = set()
    for item in items:
        try:
            key = (
                int(item.get("x", 0) or 0),
                int(item.get("y", 0) or 0),
                int(item.get("w", 0) or 0),
                int(item.get("h", 0) or 0),
            )
        except (TypeError, ValueError):
            continue
        if key in seen:
            continue
        seen.add(key)
        out.append(dict(item))
    return sorted(out, key=lambda item: (int(item.get("x", 0) or 0), int(item.get("y", 0) or 0)))


def _sand_filter_role_normalised_grid(grid: np.ndarray) -> np.ndarray | None:
    """Map palette-shifted sand roles into the canonical detector palette."""

    g = np.asarray(grid)
    if g.shape != (16, 16):
        return None
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[int(counts.argmax())])

    filter_colours: Counter[int] = Counter()
    for y in range(16):
        x = 0
        while x < 16:
            value = int(g[y, x])
            if value == bg:
                x += 1
                continue
            x2 = x
            while x2 < 16 and int(g[y, x2]) == value:
                x2 += 1
            width = x2 - x
            thin = (y == 0 or int(g[y - 1, x]) != value) and (
                y == 15 or int(g[y + 1, x]) != value
            )
            if 2 <= width <= 8 and thin:
                filter_colours[value] += 1
            x = x2

    bowl_colours: Counter[int] = Counter()
    seen: set[tuple[int, int]] = set()
    for y in range(16):
        for x in range(16):
            value = int(g[y, x])
            if value == bg or (x, y) in seen:
                continue
            stack = [(x, y)]
            seen.add((x, y))
            cells: list[tuple[int, int]] = []
            while stack:
                cx, cy = stack.pop()
                cells.append((cx, cy))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = cx + dx, cy + dy
                    if (
                        0 <= nx < 16
                        and 0 <= ny < 16
                        and (nx, ny) not in seen
                        and int(g[ny, nx]) == value
                    ):
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            xs = [cell[0] for cell in cells]
            ys = [cell[1] for cell in cells]
            if (
                max(xs) - min(xs) + 1 == 3
                and max(ys) - min(ys) + 1 == 2
                and len(cells) >= 5
            ):
                bowl_colours[value] += 1

    if not filter_colours or not bowl_colours:
        return None

    top_colours: set[int] = set()
    for y in range(3):
        for x in range(16):
            value = int(g[y, x])
            if value != bg:
                top_colours.add(value)
    source_candidates = top_colours - set(filter_colours) - set(bowl_colours)
    if not source_candidates:
        return None

    remap: dict[int, int] = {sorted(source_candidates)[0]: 4}
    for idx, colour in enumerate(colour for colour, _ in filter_colours.most_common()):
        remap[colour] = 9 if idx == 0 else 8
    for idx, colour in enumerate(colour for colour, _ in bowl_colours.most_common()):
        remap[colour] = 11 if idx % 2 == 0 else 13

    out = np.zeros_like(g)
    for src, dst in remap.items():
        out[g == src] = dst
    return out


def _sand_filter_cell_grid(
    frame: np.ndarray,
    *,
    cell: int | None = None,
    grid_size: int = 16,
) -> np.ndarray:
    size = max(1, int(grid_size))
    grid = np.zeros((size, size), dtype=np.int16)
    for gy in range(size):
        for gx in range(size):
            if cell is not None and size == 16:
                y = min(frame.shape[0] - 1, gy * int(cell) + 1)
                x = min(frame.shape[1] - 1, gx * int(cell) + 1)
                grid[gy, gx] = int(frame[y, x])
            else:
                y0 = int(float(gy) * float(frame.shape[0]) / float(size))
                y1 = max(y0 + 1, int(float(gy + 1) * float(frame.shape[0]) / float(size)))
                x0 = int(float(gx) * float(frame.shape[1]) / float(size))
                x1 = max(x0 + 1, int(float(gx + 1) * float(frame.shape[1]) / float(size)))
                block = frame[
                    min(frame.shape[0] - 1, y0) : min(frame.shape[0], y1),
                    min(frame.shape[1] - 1, x0) : min(frame.shape[1], x1),
                ]
                if block.size == 0:
                    y = min(frame.shape[0] - 1, int((float(gy) + 0.5) * float(frame.shape[0]) / float(size)))
                    x = min(frame.shape[1] - 1, int((float(gx) + 0.5) * float(frame.shape[1]) / float(size)))
                    grid[gy, gx] = int(frame[y, x])
                    continue
                values, counts = np.unique(block, return_counts=True)
                non_background = [
                    (int(count), int(value))
                    for value, count in zip(values, counts)
                    if int(value) != 12
                ]
                if non_background:
                    non_background.sort(reverse=True)
                    grid[gy, gx] = int(non_background[0][1])
                else:
                    grid[gy, gx] = int(values[int(counts.argmax())])
    return grid


def _sand_filter_rotation(frame: np.ndarray) -> int:
    source_mask = np.asarray(frame) == 4
    if not bool(source_mask.any()):
        return 0
    ys, _xs = np.where(source_mask)
    return 2 if float(ys.mean()) > float(frame.shape[0]) / 2.0 else 0


def _sand_filter_detect_filters(grid: np.ndarray) -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []
    seen: set[tuple[int, int]] = set()
    grid_h, grid_w = int(grid.shape[0]), int(grid.shape[1])
    filter_values = {4, 8, 9}
    for y in range(grid_h):
        for x in range(grid_w):
            if (x, y) in seen or int(grid[y, x]) not in filter_values:
                continue
            stack = [(x, y)]
            seen.add((x, y))
            cells: list[tuple[int, int]] = []
            selected = False
            source_offsets: list[list[int]] = []
            filter_cell_count = 0
            while stack:
                cx, cy = stack.pop()
                cells.append((cx, cy))
                selected = selected or int(grid[cy, cx]) == 9
                if int(grid[cy, cx]) in {8, 9}:
                    filter_cell_count += 1
                if int(grid[cy, cx]) == 4:
                    source_offsets.append([int(cx), int(cy)])
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = cx + dx, cy + dy
                    if (
                        0 <= nx < grid_w
                        and 0 <= ny < grid_h
                        and (nx, ny) not in seen
                        and int(grid[ny, nx]) in filter_values
                    ):
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            xs = [cx for cx, _cy in cells]
            ys = [cy for _cx, cy in cells]
            x0, y0 = min(xs), min(ys)
            comp_w = max(xs) - x0 + 1
            comp_h = max(ys) - y0 + 1
            duplicated_sample_row = comp_h == 2 and len(cells) == comp_w * 2
            if (
                not (comp_h == 1 or duplicated_sample_row)
                or comp_w < 2
                or comp_w > 8
                or (not duplicated_sample_row and len(cells) != comp_w)
                or filter_cell_count <= 0
            ):
                continue
            if duplicated_sample_row:
                comp_h = 1
            if source_offsets and comp_w > 2:
                comp_w = max(2, comp_w - len({(int(sx), int(sy)) for sx, sy in source_offsets}))
            local_sources = [
                [int(sx) - int(x0), int(sy) - int(y0)]
                for sx, sy in sorted(source_offsets)
            ]
            out.append(
                {
                    "x": int(x0),
                    "y": int(y0),
                    "w": int(comp_w),
                    "h": int(comp_h),
                    "selected": bool(selected),
                    "source_offsets": local_sources,
                }
            )
    return sorted(out, key=lambda item: (int(item["y"]), int(item["x"]), int(item["w"])))


def _sand_filter_detect_bowls(grid: np.ndarray) -> list[dict[str, Any]]:
    mask_values = {11, 13}
    out: list[dict[str, Any]] = []
    seen: set[tuple[int, int]] = set()
    grid_h, grid_w = int(grid.shape[0]), int(grid.shape[1])
    for y in range(grid_h):
        for x in range(grid_w):
            if (x, y) in seen or int(grid[y, x]) not in mask_values:
                continue
            stack = [(x, y)]
            seen.add((x, y))
            cells: list[tuple[int, int]] = []
            while stack:
                cx, cy = stack.pop()
                cells.append((cx, cy))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = cx + dx, cy + dy
                    if (
                        0 <= nx < grid_w
                        and 0 <= ny < grid_h
                        and (nx, ny) not in seen
                        and int(grid[ny, nx]) in mask_values
                    ):
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            xs = [cx for cx, _cy in cells]
            ys = [cy for _cx, cy in cells]
            x0, y0 = min(xs), min(ys)
            width = max(xs) - x0 + 1
            height = max(ys) - y0 + 1
            sampled_lower_bowl = width == 3 and height == 1 and y0 >= grid_h - 4
            sampled_side_bowl = (
                2 <= width <= 3
                and 3 <= height <= 4
                and x0 >= grid_w - 5
                and y0 <= max(8, grid_h // 2)
                and len(cells) >= 5
            )
            if (
                not sampled_lower_bowl
                and not sampled_side_bowl
                and (width != 3 or height != 2 or len(cells) < 5)
            ):
                continue
            if sampled_lower_bowl:
                height = 2
            if sampled_side_bowl:
                x0 = min(grid_w - 2, x0 + max(0, width - 2))
                width = 2
                height = 3
            out.append({"x": int(x0), "y": int(y0), "w": int(width), "h": int(height)})
    if len(out) < 2 and grid_w >= 18:
        candidates: list[dict[str, int]] = []
        for y in range(grid_h - 1, max(-1, grid_h - 5), -1):
            x = 0
            while x < grid_w:
                if int(grid[y, x]) not in mask_values:
                    x += 1
                    continue
                x0 = x
                while x < grid_w and int(grid[y, x]) in mask_values:
                    x += 1
                run_w = x - x0
                starts: list[int] = []
                if 2 <= run_w <= 4:
                    start_x = int(x0)
                    if run_w < 3 and x0 > 0 and y > 0 and int(grid[y - 1, x0 - 1]) in mask_values:
                        start_x = int(x0 - 1)
                    starts.append(max(0, min(grid_w - 3, start_x)))
                elif run_w >= 6:
                    starts.extend([int(x0), int(x - 3)])
                for start_x in starts:
                    if not any(abs(start_x - int(item["x"])) < 3 for item in candidates):
                        candidates.append(
                            {
                                "x": int(start_x),
                                "y": int(max(0, y - 1)),
                                "w": 3,
                                "h": 2,
                            }
                        )
        side_bowls = [
            item
            for item in out
            if int(item.get("w", 0) or 0) == 2
            and int(item.get("h", 0) or 0) == 3
            and int(item.get("x", 0) or 0) >= grid_w - 5
        ]
        lower_out = [item for item in out if item not in side_bowls]
        if len(candidates) > len(lower_out):
            out = side_bowls + candidates
    return sorted(out, key=lambda item: (int(item["y"]), int(item["x"])))


def _sand_filter_source_links_from_filters(
    filters: Sequence[Mapping[str, Any]],
) -> list[tuple[int, int, int]]:
    links: list[tuple[int, int, int]] = []
    for index, item in enumerate(filters):
        for raw in list(item.get("source_offsets") or []):
            if not isinstance(raw, Sequence) or len(raw) < 2:
                continue
            try:
                links.append((int(index), int(raw[0]), int(raw[1])))
            except (TypeError, ValueError):
                continue
    return links


def _sand_filter_detect_reflectors(grid: np.ndarray) -> list[dict[str, int]]:
    """Detect diagonal sand redirectors rendered as colour-15 wedge pieces."""

    out: list[dict[str, int]] = []
    seen: set[tuple[int, int]] = set()
    grid_h, grid_w = int(grid.shape[0]), int(grid.shape[1])
    for y in range(grid_h):
        for x in range(grid_w):
            if (x, y) in seen or int(grid[y, x]) != 15:
                continue
            stack = [(x, y)]
            seen.add((x, y))
            cells: list[tuple[int, int]] = []
            while stack:
                cx, cy = stack.pop()
                cells.append((cx, cy))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = cx + dx, cy + dy
                    if (
                        0 <= nx < grid_w
                        and 0 <= ny < grid_h
                        and (nx, ny) not in seen
                        and int(grid[ny, nx]) == 15
                    ):
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            xs = [cx for cx, _cy in cells]
            ys = [cy for _cx, cy in cells]
            x0, y0 = min(xs), min(ys)
            width = max(xs) - x0 + 1
            height = max(ys) - y0 + 1
            if width not in (2, 3) or height not in (2, 3) or len(cells) < 3:
                continue
            out.append({"x": int(x0), "y": int(y0), "w": 2, "h": 2})
    return sorted(out, key=lambda item: (int(item["y"]), int(item["x"])))


def _sand_filter_detect_vertical_filters(grid: np.ndarray) -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []
    seen: set[tuple[int, int]] = set()
    grid_h, grid_w = int(grid.shape[0]), int(grid.shape[1])
    for y in range(grid_h):
        for x in range(grid_w):
            if (x, y) in seen or int(grid[y, x]) not in {8, 9}:
                continue
            stack = [(x, y)]
            seen.add((x, y))
            cells: list[tuple[int, int]] = []
            selected = False
            while stack:
                cx, cy = stack.pop()
                cells.append((cx, cy))
                selected = selected or int(grid[cy, cx]) == 9
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = cx + dx, cy + dy
                    if (
                        0 <= nx < grid_w
                        and 0 <= ny < grid_h
                        and (nx, ny) not in seen
                        and int(grid[ny, nx]) in {8, 9}
                    ):
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            xs = [cx for cx, _cy in cells]
            ys = [cy for _cx, cy in cells]
            x0, y0 = min(xs), min(ys)
            width = max(xs) - x0 + 1
            height = max(ys) - y0 + 1
            if width != 1 or height < 3 or height > 6 or len(cells) != height:
                continue
            out.append(
                {
                    "x": int(x0),
                    "y": int(y0),
                    "w": 1,
                    "h": int(height),
                    "selected": bool(selected),
                    "source_offsets": [],
                    "filter_orientation": "vertical",
                }
            )
    return sorted(out, key=lambda item: (int(item["y"]), int(item["x"])))


def _sand_filter_detect_side_bowls(grid: np.ndarray) -> list[dict[str, Any]]:
    mask_values = {11, 13}
    out: list[dict[str, Any]] = []
    seen: set[tuple[int, int]] = set()
    grid_h, grid_w = int(grid.shape[0]), int(grid.shape[1])
    for y in range(grid_h):
        for x in range(grid_w):
            if (x, y) in seen or int(grid[y, x]) not in mask_values:
                continue
            stack = [(x, y)]
            seen.add((x, y))
            cells: list[tuple[int, int]] = []
            while stack:
                cx, cy = stack.pop()
                cells.append((cx, cy))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = cx + dx, cy + dy
                    if (
                        0 <= nx < grid_w
                        and 0 <= ny < grid_h
                        and (nx, ny) not in seen
                        and int(grid[ny, nx]) in mask_values
                    ):
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            xs = [cx for cx, _cy in cells]
            ys = [cy for _cx, cy in cells]
            x0, y0 = min(xs), min(ys)
            width = max(xs) - x0 + 1
            height = max(ys) - y0 + 1
            if not (2 <= width <= 3 and 3 <= height <= 4 and len(cells) >= 5):
                continue
            if x0 <= 2:
                out.append({"x": int(x0), "y": int(y0), "w": 2, "h": 3})
            elif x0 >= grid_w - 5:
                out.append(
                    {
                        "x": int(min(grid_w - 2, x0 + max(0, width - 2))),
                        "y": int(y0),
                        "w": 2,
                        "h": 3,
                    }
                )
    return sorted(out, key=lambda item: (int(item["y"]), int(item["x"])))


def _sand_filter_detect_reflector_components(grid: np.ndarray) -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []
    seen: set[tuple[int, int]] = set()
    grid_h, grid_w = int(grid.shape[0]), int(grid.shape[1])
    for y in range(grid_h):
        for x in range(grid_w):
            if (x, y) in seen or int(grid[y, x]) not in {9, 15}:
                continue
            value = int(grid[y, x])
            stack = [(x, y)]
            seen.add((x, y))
            cells: list[tuple[int, int]] = []
            while stack:
                cx, cy = stack.pop()
                cells.append((cx, cy))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = cx + dx, cy + dy
                    if (
                        0 <= nx < grid_w
                        and 0 <= ny < grid_h
                        and (nx, ny) not in seen
                        and int(grid[ny, nx]) == value
                    ):
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            xs = [cx for cx, _cy in cells]
            ys = [cy for _cx, cy in cells]
            x0, y0 = min(xs), min(ys)
            width = max(xs) - x0 + 1
            height = max(ys) - y0 + 1
            rel = {(cx - x0, cy - y0) for cx, cy in cells}
            if width != 2 or height not in (2, 3) or len(cells) < 3 or len(cells) > 6:
                continue
            if rel == {(1, 0), (0, 1), (1, 1)}:
                orientation = "lexuhyxqrsm"
            elif rel == {(0, 0), (0, 1), (1, 1)}:
                orientation = "riwynidseun"
            elif value == 9:
                orientation = "riwynidseun"
            elif value == 15:
                orientation = "lexuhyxqrsm"
            else:
                orientation = "unknown"
            out.append(
                {
                    "x": int(x0),
                    "y": int(y0),
                    "w": 2,
                    "h": 2,
                    "selected": bool(value == 9),
                    "orientation": orientation,
                }
            )
    return sorted(out, key=lambda item: (int(item["y"]), int(item["x"])))


def _sand_filter_detect_sources(
    grid: np.ndarray,
    *,
    filters: Sequence[Mapping[str, Any]] | None = None,
) -> list[dict[str, int]]:
    out: list[dict[str, int]] = []
    embedded: set[tuple[int, int]] = set()
    for item in list(filters or []):
        try:
            fx, fy = int(item.get("x", 0) or 0), int(item.get("y", 0) or 0)
        except (TypeError, ValueError):
            continue
        for raw in list(item.get("source_offsets") or []):
            if not isinstance(raw, Sequence) or len(raw) < 2:
                continue
            try:
                embedded.add((fx + int(raw[0]), fy + int(raw[1])))
            except (TypeError, ValueError):
                continue
    grid_h, grid_w = int(grid.shape[0]), int(grid.shape[1])
    for y in range(grid_h):
        for x in range(grid_w):
            if (x, y) in embedded:
                continue
            if int(grid[y, x]) == 4:
                out.append({"x": int(x), "y": int(0 if y <= 2 else y)})
    collapsed: list[dict[str, int]] = []
    for y, items in groupby(sorted(out, key=lambda item: (int(item["y"]), int(item["x"]))), key=lambda item: int(item["y"])):
        xs = [int(item["x"]) for item in items]
        index = 0
        while index < len(xs):
            x0 = xs[index]
            while index + 1 < len(xs) and xs[index + 1] <= xs[index] + 1:
                index += 1
            collapsed.append({"x": int(x0), "y": int(y)})
            index += 1
    return collapsed


class _SandFilterFlowSim:
    def __init__(
        self,
        *,
        filters: list[tuple[int, int, int, int]],
        bowls: list[tuple[int, int, int, int]],
        sources: list[tuple[int, int]],
        grid_w: int = 16,
        grid_h: int = 16,
    ) -> None:
        self.filters = list(filters)
        self.bowls = list(bowls)
        self.grid_w = int(grid_w)
        self.grid_h = int(grid_h)
        self.water: set[tuple[int, int]] = set()
        self.particles: list[tuple[int, int, int, int]] = []
        self.filled_bowls: set[int] = set()
        self.overflow = False
        for sx, sy in sources:
            start = (int(sx), int(sy) + 1)
            self.particles.append((start[0], start[1], 0, 1))
            self.water.add(start)

    def _sprite_at(self, x: int, y: int) -> tuple[str, int] | None:
        if (x, y) in self.water:
            return ("water", -1)
        for index, (fx, fy, fw, fh) in enumerate(self.filters):
            if int(fx) <= x < int(fx) + int(fw) and int(fy) <= y < int(fy) + int(fh):
                return ("filter", index)
        for index, (bx, by, bw, bh) in enumerate(self.bowls):
            if int(bx) <= x < int(bx) + int(bw) and int(by) <= y < int(by) + int(bh):
                lx = x - int(bx)
                ly = y - int(by)
                if int(bw) == 3 and int(bh) == 2 and (lx, ly) == (1, 0):
                    return None
                return ("bowl", index)
        if y == self.grid_h - 1:
            return ("floor", -1)
        if x < 0 or x >= self.grid_w or y < 0 or y >= self.grid_h:
            return ("wall", -1)
        return None

    def run(self, max_steps: int = 200) -> None:
        for _ in range(max_steps):
            if not self.particles:
                return
            new_parts: list[tuple[int, int, int, int]] = []
            for px, py, dx, dy in self.particles:
                tx, ty = px + dx, py + dy
                target = self._sprite_at(tx, ty)
                perp = ((-1, 0), (1, 0)) if dy != 0 else ((0, -1), (0, 1))
                if target is None:
                    if (tx, ty) not in self.water:
                        self.water.add((tx, ty))
                        new_parts.append((tx, ty, dx, dy))
                    continue
                kind = target[0]
                if kind == "water":
                    new_parts.append((tx, ty, dx, dy))
                    continue
                if kind == "filter":
                    for ox, oy in perp:
                        nx, ny = px + ox, py + oy
                        if self._sprite_at(nx, ny) is None and (nx, ny) not in self.water:
                            self.water.add((nx, ny))
                            new_parts.append((nx, ny, dx, dy))
                    continue
                if kind == "bowl":
                    bowl_index = int(target[1])
                    left = self._sprite_at(px + perp[0][0], py + perp[0][1])
                    right = self._sprite_at(px + perp[1][0], py + perp[1][1])
                    if (
                        left is not None and left[0] == "bowl" and int(left[1]) == bowl_index
                        and right is not None and right[0] == "bowl" and int(right[1]) == bowl_index
                    ):
                        self.filled_bowls.add(bowl_index)
                    else:
                        for ox, oy in perp:
                            nx, ny = px + ox, py + oy
                            if self._sprite_at(nx, ny) is None and (nx, ny) not in self.water:
                                self.water.add((nx, ny))
                                new_parts.append((nx, ny, dx, dy))
                    continue
                if kind == "floor":
                    self.overflow = True
                    continue
            self.particles = new_parts

    def is_win(self) -> bool:
        return bool(not self.overflow and len(self.filled_bowls) == len(self.bowls))


def _sand_filter_solve(
    init_filters: list[tuple[int, int, int]],
    sources: list[tuple[int, int]],
    bowls: list[tuple[int, int, int, int]],
    *,
    time_budget: float,
    grid_w: int = 16,
    grid_h: int = 16,
    source_links: Sequence[tuple[int, int, int]] | None = None,
) -> list[tuple[int, int, int]] | None:
    import heapq
    import random
    import time

    if not init_filters or not bowls or not sources:
        if not source_links:
            return None
    source_links = list(source_links or [])
    if source_links:
        repaired = _sand_filter_source_coupled_repair_search(
            init_filters,
            sources,
            bowls,
            source_links=source_links,
            time_budget=time_budget,
            grid_w=grid_w,
            grid_h=grid_h,
            rng=random.Random(20260617),
        )
        if repaired is not None:
            return repaired
    initial = _SandFilterFlowSim(
        filters=[(x, y, w, 1) for x, y, w in init_filters],
        bowls=bowls,
        sources=_sand_filter_effective_sources(init_filters, sources, source_links),
        grid_w=grid_w,
        grid_h=grid_h,
    )
    initial.run()
    if initial.is_win():
        return list(init_filters)
    start = time.time()
    near_radius = 6
    near_combo_limit = 40000
    if 0 < len(init_filters) <= 4:
        nearby_candidates: list[list[tuple[int, int, int, int]]] = []
        for ix, iy, iw in init_filters:
            candidates: list[tuple[int, int, int, int]] = []
            for y in range(3, 13):
                for x in range(0, grid_w - int(iw) + 1):
                    distance = abs(int(x) - int(ix)) + abs(int(y) - int(iy))
                    if distance <= near_radius:
                        candidates.append((int(distance), int(x), int(y), int(iw)))
            candidates.sort(key=lambda item: (item[0], item[2], item[1], item[3]))
            nearby_candidates.append(candidates)

        near_combos: list[tuple[int, tuple[tuple[int, int, int], ...]]] = []

        def collect_nearby(
            index: int,
            remaining: int,
            distance_sum: int,
            chosen: list[tuple[int, int, int]],
        ) -> None:
            if len(near_combos) >= near_combo_limit:
                return
            if index >= len(nearby_candidates):
                near_combos.append((int(distance_sum), tuple(chosen)))
                return
            for distance, x, y, width in nearby_candidates[index]:
                if distance > remaining:
                    break
                chosen.append((int(x), int(y), int(width)))
                collect_nearby(index + 1, remaining - int(distance), distance_sum + int(distance), chosen)
                chosen.pop()

        collect_nearby(0, near_radius, 0, [])
        near_combos.sort(key=lambda item: (item[0], item[1]))
        for _distance, filters_tuple in near_combos:
            if time.time() - start >= max(0.05, float(time_budget)):
                break
            filters = list(filters_tuple)
            if _sand_filter_targets_overlap(filters):
                continue
            sim = _SandFilterFlowSim(
                filters=[(x, y, w, 1) for x, y, w in filters],
                bowls=bowls,
                sources=_sand_filter_effective_sources(filters, sources, source_links),
                grid_w=grid_w,
                grid_h=grid_h,
            )
            sim.run()
            if sim.is_win():
                return filters
    targets_per_filter: list[list[tuple[int, int, int]]] = []
    for ix, iy, iw in init_filters:
        candidates: list[tuple[int, int, int]] = []
        for y in range(3, 13):
            for x in range(0, grid_w - int(iw) + 1):
                candidates.append((int(x), int(y), int(iw)))
        candidates.sort(key=lambda item: abs(item[0] - int(ix)) + abs(item[1] - int(iy)))
        targets_per_filter.append(candidates)
    state0 = tuple(0 for _ in init_filters)
    heap: list[tuple[int, tuple[int, ...]]] = [
        (
            sum(
                abs(targets_per_filter[i][0][0] - init_filters[i][0])
                + abs(targets_per_filter[i][0][1] - init_filters[i][1])
                for i in range(len(init_filters))
            ),
            state0,
        )
    ]
    seen = {state0}
    while heap and time.time() - start < max(0.05, float(time_budget)):
        _dist, state = heapq.heappop(heap)
        filters = [targets_per_filter[i][state[i]] for i in range(len(state))]
        if not _sand_filter_targets_overlap(filters):
            sim = _SandFilterFlowSim(
                filters=[(x, y, w, 1) for x, y, w in filters],
                bowls=bowls,
                sources=_sand_filter_effective_sources(filters, sources, source_links),
                grid_w=grid_w,
                grid_h=grid_h,
            )
            sim.run()
            if sim.is_win():
                return filters
        for i in range(len(state)):
            if state[i] + 1 >= len(targets_per_filter[i]):
                continue
            next_state = list(state)
            next_state[i] += 1
            next_tuple = tuple(next_state)
            if next_tuple in seen:
                continue
            seen.add(next_tuple)
            next_dist = sum(
                abs(targets_per_filter[j][next_tuple[j]][0] - init_filters[j][0])
                + abs(targets_per_filter[j][next_tuple[j]][1] - init_filters[j][1])
                for j in range(len(init_filters))
            )
            heapq.heappush(heap, (next_dist, next_tuple))
    return None


def _sand_filter_targets_overlap(filters: list[tuple[int, int, int]]) -> bool:
    for i, (xi, yi, wi) in enumerate(filters):
        for xj, yj, wj in filters[i + 1 :]:
            if int(yi) == int(yj) and int(xi) + int(wi) > int(xj) and int(xj) + int(wj) > int(xi):
                return True
    return False


def _sand_filter_effective_sources(
    filters: Sequence[tuple[int, int, int]],
    fixed_sources: Sequence[tuple[int, int]],
    source_links: Sequence[tuple[int, int, int]] | None = None,
) -> list[tuple[int, int]]:
    sources = [(int(x), int(y)) for x, y in list(fixed_sources or [])]
    for index, local_x, local_y in list(source_links or []):
        if int(index) < 0 or int(index) >= len(filters):
            continue
        fx, fy, _fw = filters[int(index)]
        sources.append((int(fx) + int(local_x), int(fy) + int(local_y)))
    return sources


def _sand_filter_filter_config_blocked(
    filters: Sequence[tuple[int, int, int]],
    bowls: Sequence[tuple[int, int, int, int]],
    *,
    grid_w: int,
    grid_h: int,
) -> bool:
    rows = [(int(x), int(y), int(w)) for x, y, w in filters]
    for index, (x, y, w) in enumerate(rows):
        if x < 0 or y < 3 or x + w > int(grid_w) or y >= int(grid_h) - 1:
            return True
        for bx, by, bw, bh in bowls:
            if (
                x < int(bx) + int(bw) + 1
                and x + w > int(bx) - 1
                and y < int(by) + int(bh) + 1
                and y + 1 > int(by) - 1
            ):
                return True
        for other_x, other_y, other_w in rows[:index]:
            if y == other_y and x + w > other_x and other_x + other_w > x:
                return True
    return False


def _sand_filter_config_distance(
    init_filters: Sequence[tuple[int, int, int]],
    filters: Sequence[tuple[int, int, int]],
) -> int:
    total = 0
    for (ix, iy, _iw), (tx, ty, _tw) in zip(init_filters, filters):
        total += abs(int(tx) - int(ix)) + abs(int(ty) - int(iy))
    return int(total)


def _sand_filter_source_coupled_repair_search(
    init_filters: list[tuple[int, int, int]],
    fixed_sources: list[tuple[int, int]],
    bowls: list[tuple[int, int, int, int]],
    *,
    source_links: Sequence[tuple[int, int, int]],
    time_budget: float,
    grid_w: int,
    grid_h: int,
    rng: Any,
) -> list[tuple[int, int, int]] | None:
    import time

    start = time.time()
    if not source_links:
        return None
    widths = [int(w) for _x, _y, w in init_filters]
    candidates: list[list[tuple[int, int, int]]] = []
    for index, (ix, iy, iw) in enumerate(init_filters):
        rows: list[tuple[int, int, int, int]] = []
        for y in range(3, max(3, int(grid_h) - 2)):
            for x in range(0, int(grid_w) - int(iw) + 1):
                candidate = (int(x), int(y), int(iw))
                probe = list(init_filters)
                probe[index] = candidate
                if _sand_filter_filter_config_blocked(
                    probe,
                    bowls,
                    grid_w=grid_w,
                    grid_h=grid_h,
                ):
                    continue
                rows.append((abs(int(x) - int(ix)) + abs(int(y) - int(iy)), int(x), int(y), int(iw)))
        rows.sort(key=lambda item: (item[0], item[2], item[1], item[3]))
        candidates.append([(x, y, w) for _distance, x, y, w in rows])
    if any(not rows for rows in candidates):
        return None

    def is_win(filters: Sequence[tuple[int, int, int]]) -> bool:
        if _sand_filter_filter_config_blocked(filters, bowls, grid_w=grid_w, grid_h=grid_h):
            return False
        sim = _SandFilterFlowSim(
            filters=[(int(x), int(y), int(w), 1) for x, y, w in filters],
            bowls=bowls,
            sources=_sand_filter_effective_sources(filters, fixed_sources, source_links),
            grid_w=grid_w,
            grid_h=grid_h,
        )
        sim.run()
        return bool(sim.is_win())

    if is_win(init_filters):
        return list(init_filters)

    best_win: tuple[int, list[tuple[int, int, int]]] | None = None
    source_indices = {int(index) for index, _local_x, _local_y in source_links}
    source_seed_configs: list[list[tuple[int, int, int]]] = []
    for source_index in sorted(source_indices):
        if source_index < 0 or source_index >= len(init_filters):
            continue
        for candidate in candidates[source_index]:
            seeded = list(init_filters)
            seeded[source_index] = candidate
            if not _sand_filter_filter_config_blocked(
                seeded,
                bowls,
                grid_w=grid_w,
                grid_h=grid_h,
            ):
                source_seed_configs.append(seeded)
    rng.shuffle(source_seed_configs)

    attempts = 0
    max_attempts = 80000
    while attempts < max_attempts and time.time() - start < max(0.05, float(time_budget)):
        if attempts < len(source_seed_configs):
            filters = list(source_seed_configs[attempts])
            for index in range(len(filters)):
                if index in source_indices:
                    continue
                pool = candidates[index][: min(96, len(candidates[index]))]
                if pool and rng.random() < 0.75:
                    filters[index] = rng.choice(pool)
        else:
            filters = []
            for index, pool in enumerate(candidates):
                if index in source_indices and rng.random() < 0.85:
                    focus = pool[: min(160, len(pool))]
                elif rng.random() < 0.7:
                    focus = pool[: min(96, len(pool))]
                else:
                    focus = pool
                filters.append(rng.choice(focus))
        attempts += 1
        if [int(w) for _x, _y, w in filters] != widths:
            continue
        if not is_win(filters):
            continue
        distance = _sand_filter_config_distance(init_filters, filters)
        if best_win is None or distance < best_win[0]:
            best_win = (int(distance), list(filters))
            if distance <= 64:
                return list(filters)
    return list(best_win[1]) if best_win is not None else None


def _sand_filter_user_action_for_delta(dx: int, dy: int, *, rotation_k: int) -> str | None:
    if rotation_k == 0:
        mapping = {
            (0, -1): "ACTION1",
            (0, 1): "ACTION2",
            (-1, 0): "ACTION3",
            (1, 0): "ACTION4",
        }
    elif rotation_k == 2:
        mapping = {
            (0, 1): "ACTION1",
            (0, -1): "ACTION2",
            (1, 0): "ACTION3",
            (-1, 0): "ACTION4",
        }
    else:
        return None
    return mapping.get((int(dx), int(dy)))


def _sand_filter_click_for_grid(
    gx: int,
    gy: int,
    *,
    rotation_k: int,
    cell: int = 4,
    grid_size: int = 16,
) -> dict[str, int]:
    if int(grid_size) != 16:
        target_x = int((float(gx) + 0.5) * 64.0 / float(grid_size))
        target_y = int((float(gy) + 0.5) * 64.0 / float(grid_size))
        if rotation_k == 2:
            return {"x": int(63 - target_x), "y": int(63 - target_y)}
        return {"x": int(target_x), "y": int(target_y)}
    if rotation_k == 2:
        return {"x": int(62 - cell * int(gx)), "y": int(62 - cell * int(gy))}
    return {"x": int(int(gx) * cell + 2), "y": int(int(gy) * cell + 2)}


def _sand_filter_emit_plan(
    initial_filters: list[Mapping[str, Any]],
    target_filters: list[tuple[int, int, int]],
    *,
    rotation_k: int,
    grid_size: int = 16,
    initial_reflectors: Sequence[Mapping[str, Any]] | None = None,
    target_reflectors: Sequence[Mapping[str, Any]] | None = None,
) -> list[dict[str, Any]]:
    current = [(int(item["x"]), int(item["y"]), int(item["w"])) for item in initial_filters]
    selected_index = next((i for i, item in enumerate(initial_filters) if bool(item.get("selected"))), None)
    plan: list[dict[str, Any]] = []
    for index, (tx, ty, tw) in enumerate(target_filters):
        cx, cy, cw = current[index]
        if int(cw) != int(tw):
            return []
        if (cx, cy) != (int(tx), int(ty)) and selected_index != index:
            plan.append(
                {
                    "action_name": "ACTION6",
                    "payload": _sand_filter_click_for_grid(
                        cx,
                        cy,
                        rotation_k=rotation_k,
                        grid_size=grid_size,
                    ),
                }
            )
            selected_index = index
        dx = int(tx) - int(cx)
        dy = int(ty) - int(cy)
        if dx:
            step = 1 if dx > 0 else -1
            action = _sand_filter_user_action_for_delta(step, 0, rotation_k=rotation_k)
            if not action:
                return []
            plan.extend({"action_name": action, "payload": {}} for _ in range(abs(dx)))
        if dy:
            step = 1 if dy > 0 else -1
            action = _sand_filter_user_action_for_delta(0, step, rotation_k=rotation_k)
            if not action:
                return []
            plan.extend({"action_name": action, "payload": {}} for _ in range(abs(dy)))
        current[index] = (int(tx), int(ty), int(tw))
    for reflector, target in zip(
        list(initial_reflectors or []),
        list(target_reflectors or []),
    ):
        cx, cy = int(reflector.get("x", 0) or 0), int(reflector.get("y", 0) or 0)
        tx, ty = int(target.get("x", 0) or 0), int(target.get("y", 0) or 0)
        if (cx, cy) != (tx, ty):
            plan.append(
                {
                    "action_name": "ACTION6",
                    "payload": _sand_filter_click_for_grid(
                        cx,
                        cy,
                        rotation_k=rotation_k,
                        grid_size=grid_size,
                    ),
                }
            )
        dx = int(tx) - int(cx)
        dy = int(ty) - int(cy)
        if dx:
            step = 1 if dx > 0 else -1
            action = _sand_filter_user_action_for_delta(step, 0, rotation_k=rotation_k)
            if not action:
                return []
            plan.extend({"action_name": action, "payload": {}} for _ in range(abs(dx)))
        if dy:
            step = 1 if dy > 0 else -1
            action = _sand_filter_user_action_for_delta(0, step, rotation_k=rotation_k)
            if not action:
                return []
            plan.extend({"action_name": action, "payload": {}} for _ in range(abs(dy)))
    plan.append({"action_name": "ACTION5", "payload": {}})
    return plan


def _sand_filter_emit_component_plan(
    component_specs: Sequence[Mapping[str, Any]],
    *,
    rotation_k: int,
    grid_size: int,
) -> list[dict[str, Any]]:
    plan: list[dict[str, Any]] = []
    selected_key: tuple[str, int, int] | None = None
    for index, spec in enumerate(component_specs):
        source = spec.get("source")
        target = spec.get("target")
        if not isinstance(source, Mapping) or not isinstance(target, Mapping):
            return []
        try:
            cx = int(source.get("x", 0) or 0)
            cy = int(source.get("y", 0) or 0)
            tx = int(target.get("x", 0) or 0)
            ty = int(target.get("y", 0) or 0)
        except (TypeError, ValueError):
            return []
        source_key = (str(spec.get("component_kind", "component")), int(cx), int(cy))
        source_selected = bool(source.get("selected", False))
        if (cx, cy) != (tx, ty) and not source_selected and selected_key != source_key:
            plan.append(
                {
                    "action_name": "ACTION6",
                    "payload": _sand_filter_click_for_grid(
                        cx,
                        cy,
                        rotation_k=rotation_k,
                        grid_size=grid_size,
                    ),
                }
            )
        if source_selected:
            selected_key = source_key
        axis_order = str(spec.get("move_axis_order", "xy") or "xy")
        axes = ["x", "y"] if axis_order != "yx" else ["y", "x"]
        current_x, current_y = cx, cy
        for axis in axes:
            delta = (tx - current_x) if axis == "x" else (ty - current_y)
            if not delta:
                continue
            step = 1 if delta > 0 else -1
            if axis == "x":
                action = _sand_filter_user_action_for_delta(step, 0, rotation_k=rotation_k)
            else:
                action = _sand_filter_user_action_for_delta(0, step, rotation_k=rotation_k)
            if not action:
                return []
            plan.extend({"action_name": action, "payload": {}} for _ in range(abs(delta)))
            if axis == "x":
                current_x = tx
            else:
                current_y = ty
        selected_key = (str(spec.get("component_kind", "component")), int(tx), int(ty))
        if index + 1 < len(component_specs):
            next_source = component_specs[index + 1].get("source")
            if isinstance(next_source, Mapping) and bool(next_source.get("selected", False)):
                selected_key = None
    plan.append({"action_name": "ACTION5", "payload": {}})
    return plan


def _sand_filter_flow_plan(
    state: Mapping[str, Any] | None,
    available: set[str],
) -> list[tuple[str, dict[str, Any]]] | None:
    if state is None:
        return None
    out: list[tuple[str, dict[str, Any]]] = []
    for step in list(state.get("operation_plan") or []):
        if not isinstance(step, Mapping):
            continue
        action = _normalize_action_name(step.get("action_name"))
        payload = step.get("payload") if isinstance(step.get("payload"), Mapping) else {}
        if not action or action not in available:
            return None
        out.append((action, dict(payload)))
    return out or None


def _compact_sand_filter_flow_state(state: Mapping[str, Any] | None) -> dict[str, Any] | None:
    if state is None:
        return None
    return {
        "mechanic_state_type": str(state.get("mechanic_state_type", "") or ""),
        "goal_link_type": str(state.get("goal_link_type", "") or ""),
        "rotation_k": int(state.get("rotation_k", 0) or 0),
        "grid_size": [
            int(v)
            for v in list(state.get("grid_size") or [])[:2]
            if isinstance(v, (int, float))
        ],
        "filter_count": int(state.get("filter_count", 0) or 0),
        "bowl_count": int(state.get("bowl_count", 0) or 0),
        "source_count": int(state.get("source_count", 0) or 0),
        "source_link_count": int(len(list(state.get("source_links") or []))),
        "reflector_count": int(state.get("reflector_count", 0) or 0),
        "operation_plan_len": int(state.get("operation_plan_len", 0) or 0),
        "target_filters": [
            {
                "x": int(item.get("x", 0) or 0),
                "y": int(item.get("y", 0) or 0),
                "w": int(item.get("w", 0) or 0),
            }
            for item in list(state.get("target_filters") or [])[:4]
            if isinstance(item, Mapping)
        ],
        "target_reflectors": [
            {
                "x": int(item.get("x", 0) or 0),
                "y": int(item.get("y", 0) or 0),
                "w": int(item.get("w", 0) or 0),
            }
            for item in list(state.get("target_reflectors") or [])[:2]
            if isinstance(item, Mapping)
        ],
        "reader_confidence": float(state.get("reader_confidence", 0.0) or 0.0),
        "goal_link_confidence": float(state.get("goal_link_confidence", 0.0) or 0.0),
    }


def _mirror_pair_is_certified(state: Mapping[str, Any] | None) -> bool:
    if not isinstance(state, Mapping):
        return False
    try:
        cursor_a = tuple(int(v) for v in state.get("cursor_a", ()))
        cursor_b = tuple(int(v) for v in state.get("cursor_b", ()))
        grid_size = tuple(int(v) for v in state.get("grid_size", ()))
    except (TypeError, ValueError):
        return False
    if len(cursor_a) != 2 or len(cursor_b) != 2 or len(grid_size) != 2:
        return False
    cursor_count = state.get("cursor_cell_count", None)
    if cursor_count is not None:
        try:
            if int(cursor_count) != 2:
                return False
        except (TypeError, ValueError):
            return False
    ax, ay = cursor_a
    bx, by = cursor_b
    grid_w, grid_h = grid_size
    if grid_w < 3 or grid_h < 1:
        return False
    if (ax, ay) == (bx, by):
        return False
    if ay != by:
        return False
    if not (0 <= ax < grid_w and 0 <= bx < grid_w and 0 <= ay < grid_h):
        return False
    return ax + bx == grid_w - 1


def _mirror_joint_cursor_state(
    frame: np.ndarray,
    *,
    allow_centered_geometry: bool = True,
) -> dict[str, Any] | None:
    arr = np.asarray(frame)
    if arr.ndim != 2 or arr.size <= 0:
        return None
    components = _valued_components(arr)
    by_value: dict[int, list[dict[str, int]]] = defaultdict(list)
    value_counts = Counter(int(value) for value in arr.flatten().tolist())
    for component in components:
        area = int(component["area"])
        width = int(component["width"])
        height = int(component["height"])
        value = int(component["value"])
        if area < 4 or area > 144:
            continue
        if width < 2 or height < 2 or width > 16 or height > 16:
            continue
        if max(width, height) > max(2, min(width, height) * 2):
            continue
        if value_counts[value] > 256:
            continue
        by_value[value].append(component)
    best_pair: tuple[dict[str, int], dict[str, int]] | None = None
    best_score: tuple[int, int, int, int, int] | None = None
    for comps in by_value.values():
        if len(comps) < 2:
            continue
        ordered = sorted(comps, key=lambda item: (-int(item["area"]), int(item["min_x"]), int(item["min_y"])))
        for left_index, first in enumerate(ordered):
            for second in ordered[left_index + 1 :]:
                area_delta = abs(int(first["area"]) - int(second["area"]))
                size_delta = abs(int(first["width"]) - int(second["width"])) + abs(int(first["height"]) - int(second["height"]))
                separation = abs(int(first["cx"]) - int(second["cx"])) + abs(int(first["cy"]) - int(second["cy"]))
                score = (
                    0 if len(comps) == 2 else 1,
                    area_delta + size_delta,
                    -max(int(first["area"]), int(second["area"])),
                    -min(int(first["area"]), int(second["area"])),
                    -separation,
                )
                if best_score is None or score < best_score:
                    best_score = score
                    best_pair = (first, second)
    if best_pair is None:
        best_pair = _split_joined_cursor_component(components, value_counts)
    if best_pair is None:
        return None
    first, second = sorted(best_pair, key=lambda item: (int(item["cx"]), int(item["cy"])))
    cell = int(round(float(sum([first["width"], first["height"], second["width"], second["height"]])) / 4.0))
    if cell <= 1:
        return None
    origin_x = min(int(first["min_x"]), int(second["min_x"])) % cell
    origin_y = min(int(first["min_y"]), int(second["min_y"])) % cell
    height, width = arr.shape
    grid_w = (width - 2 * origin_x) // cell if origin_x > 0 else width // cell
    grid_h = (height - 2 * origin_y) // cell if origin_y > 0 else height // cell
    if grid_w < 3 or grid_h < 3:
        return None
    cursor_value = int(first["value"])
    centered_geometry = None
    if allow_centered_geometry:
        centered_geometry = _mirror_joint_centered_geometry(
            arr,
            cell=cell,
            cursor_value=cursor_value,
            cursor_components=(first, second),
            default_origin=(origin_x, origin_y),
            default_grid_size=(grid_w, grid_h),
        )
    if centered_geometry is not None:
        origin_x, origin_y = centered_geometry["origin"]
        grid_w, grid_h = centered_geometry["grid_size"]
    cell_values: Counter[int] = Counter()
    for gy in range(grid_h):
        for gx in range(grid_w):
            value = _dominant_grid_cell_value(arr, origin_x, origin_y, cell, gx, gy)
            if value is not None:
                cell_values[int(value)] += 1
    walkable_values = [
        value
        for value, _count in cell_values.most_common()
        if int(value) != cursor_value
    ]
    if not walkable_values:
        return None
    walkable_value = int(walkable_values[0])
    hazards = _mirror_joint_hazard_cells(
        arr,
        origin_x,
        origin_y,
        cell,
        grid_w,
        grid_h,
        walkable_value=walkable_value,
        cursor_value=cursor_value,
    )
    cell_signatures = _mirror_joint_cell_signatures(
        arr,
        origin_x,
        origin_y,
        cell,
        grid_w,
        grid_h,
    )
    walkable: set[tuple[int, int]] = set()
    # Phase L-2 (ported from merge-phase246): count cells dominated by the
    # cursor colour. A genuine mirror cursor pair has EXACTLY 2 (the two
    # cursors); sp80's spurious split-blob "pair" has a different count.
    # The firing certificate uses this to reject false positives the
    # symmetry test alone would let through.
    cursor_cell_count = 0
    for gy in range(grid_h):
        for gx in range(grid_w):
            value = _dominant_grid_cell_value(arr, origin_x, origin_y, cell, gx, gy)
            if value == cursor_value:
                cursor_cell_count += 1
            if value in {walkable_value, cursor_value} and (gx, gy) not in hazards:
                walkable.add((gx, gy))
    cursor_a = (
        int(round(float(first["min_x"] - origin_x) / float(cell))),
        int(round(float(first["min_y"] - origin_y) / float(cell))),
    )
    cursor_b = (
        int(round(float(second["min_x"] - origin_x) / float(cell))),
        int(round(float(second["min_y"] - origin_y) / float(cell))),
    )
    if cursor_a not in walkable or cursor_b not in walkable:
        return None
    return {
        "cursor_a": cursor_a,
        "cursor_b": cursor_b,
        "walkable": frozenset(walkable),
        "cell": cell,
        "origin": (origin_x, origin_y),
        "grid_size": (grid_w, grid_h),
        "cursor_value": cursor_value,
        "walkable_value": walkable_value,
        "hazards": frozenset(hazards),
        "death": frozenset(hazards),
        "cell_signatures": cell_signatures,
        "cursor_cell_count": int(cursor_cell_count),
    }


def _mirror_joint_centered_geometry(
    arr: np.ndarray,
    *,
    cell: int,
    cursor_value: int,
    cursor_components: tuple[dict[str, int], dict[str, int]],
    default_origin: tuple[int, int],
    default_grid_size: tuple[int, int],
) -> dict[str, tuple[int, int] | int] | None:
    """Prefer a centered grid when it better explains the cursor board.

    The default modulo-origin reader works for unletterboxed mirror layouts, but
    centered boards can have an origin larger than one cell. Earlier versions
    only shrank when blended hazard cells were visible; deeper mirror layouts
    can be hazard-free but include small movable objects, so we score centered
    candidates by cursor-cell consistency and non-board clutter instead.
    """

    height, width = arr.shape
    if cell <= 1:
        return None
    default_walkable = _mirror_joint_walkable_value_for_geometry(
        arr,
        int(default_origin[0]),
        int(default_origin[1]),
        cell,
        int(default_grid_size[0]),
        int(default_grid_size[1]),
        cursor_value=cursor_value,
    )
    if default_walkable is None:
        return None
    default_hazards = _mirror_joint_hazard_cells(
        arr,
        int(default_origin[0]),
        int(default_origin[1]),
        cell,
        int(default_grid_size[0]),
        int(default_grid_size[1]),
        walkable_value=default_walkable,
        cursor_value=cursor_value,
    )
    default_pure_special = _mirror_joint_pure_special_count(
        arr,
        int(default_origin[0]),
        int(default_origin[1]),
        cell,
        int(default_grid_size[0]),
        int(default_grid_size[1]),
        walkable_value=default_walkable,
        cursor_value=cursor_value,
    )
    default_cursor_count = _mirror_joint_cursor_cell_count(
        arr,
        int(default_origin[0]),
        int(default_origin[1]),
        cell,
        int(default_grid_size[0]),
        int(default_grid_size[1]),
        cursor_value=cursor_value,
    )
    expected_cursor_count = len(cursor_components)
    default_area = int(default_grid_size[0]) * int(default_grid_size[1])
    min_candidate_area = max(9, int(round(float(default_area) * 0.70)))
    default_score = (
        abs(int(default_cursor_count) - int(expected_cursor_count)),
        abs(int(default_grid_size[0]) - int(default_grid_size[1])),
        int(default_pure_special),
        int(len(default_hazards)),
        int(default_area),
        0,
    )
    candidates: list[tuple[tuple[int, int, int, int, int, int], int, int, int, int, int, int, int]] = []
    for grid_h in range(3, height // cell + 1):
        rem_y = height - grid_h * cell
        if rem_y < 0 or rem_y % 2:
            continue
        origin_y = rem_y // 2
        cursor_y_cells: list[int] = []
        for component in cursor_components:
            rel_y = int(component["min_y"]) - origin_y
            if rel_y < 0 or rel_y % cell:
                break
            gy = rel_y // cell
            if gy < 0 or gy >= grid_h:
                break
            cursor_y_cells.append(int(gy))
        else:
            if len(cursor_y_cells) != len(cursor_components):
                continue
            for grid_w in range(3, width // cell + 1):
                rem_x = width - grid_w * cell
                if rem_x < 0 or rem_x % 2:
                    continue
                if int(grid_w * grid_h) < min_candidate_area:
                    continue
                origin_x = rem_x // 2
                cursor_cells: list[tuple[int, int]] = []
                for component, gy in zip(cursor_components, cursor_y_cells):
                    rel_x = int(component["min_x"]) - origin_x
                    if rel_x < 0 or rel_x % cell:
                        break
                    gx = rel_x // cell
                    if gx < 0 or gx >= grid_w:
                        break
                    value = _dominant_grid_cell_value(
                        arr, origin_x, origin_y, cell, gx, gy
                    )
                    if int(value) != int(cursor_value):
                        break
                    cursor_cells.append((int(gx), int(gy)))
                else:
                    if len(cursor_cells) != len(cursor_components):
                        continue
                    walkable_value = _mirror_joint_walkable_value_for_geometry(
                        arr,
                        origin_x,
                        origin_y,
                        cell,
                        grid_w,
                        grid_h,
                        cursor_value=cursor_value,
                    )
                    if walkable_value is None:
                        continue
                    hazards = _mirror_joint_hazard_cells(
                        arr,
                        origin_x,
                        origin_y,
                        cell,
                        grid_w,
                        grid_h,
                        walkable_value=walkable_value,
                        cursor_value=cursor_value,
                    )
                    pure_special = _mirror_joint_pure_special_count(
                        arr,
                        origin_x,
                        origin_y,
                        cell,
                        grid_w,
                        grid_h,
                        walkable_value=walkable_value,
                        cursor_value=cursor_value,
                    )
                    cursor_count = _mirror_joint_cursor_cell_count(
                        arr,
                        origin_x,
                        origin_y,
                        cell,
                        grid_w,
                        grid_h,
                        cursor_value=cursor_value,
                    )
                    score = (
                        abs(int(cursor_count) - int(expected_cursor_count)),
                        abs(int(grid_w) - int(grid_h)),
                        int(pure_special),
                        int(len(hazards)),
                        int(grid_w * grid_h),
                        abs(int(origin_x) - int(default_origin[0]))
                        + abs(int(origin_y) - int(default_origin[1])),
                    )
                    candidates.append(
                        (
                            score,
                            int(origin_x),
                            int(origin_y),
                            int(grid_w),
                            int(grid_h),
                            int(cursor_count),
                            int(len(hazards)),
                            int(pure_special),
                        )
                    )
    if not candidates:
        return None
    best_score, origin_x, origin_y, grid_w, grid_h, _cursor_count, _hazard_count, _pure_special = sorted(candidates)[0]
    if best_score >= default_score:
        return None
    return {
        "origin": (int(origin_x), int(origin_y)),
        "grid_size": (int(grid_w), int(grid_h)),
    }


def _mirror_joint_cursor_cell_count(
    arr: np.ndarray,
    origin_x: int,
    origin_y: int,
    cell: int,
    grid_w: int,
    grid_h: int,
    *,
    cursor_value: int,
) -> int:
    count = 0
    for gy in range(grid_h):
        for gx in range(grid_w):
            value = _dominant_grid_cell_value(arr, origin_x, origin_y, cell, gx, gy)
            if value is not None and int(value) == int(cursor_value):
                count += 1
    return int(count)


def _mirror_joint_walkable_value_for_geometry(
    arr: np.ndarray,
    origin_x: int,
    origin_y: int,
    cell: int,
    grid_w: int,
    grid_h: int,
    *,
    cursor_value: int,
) -> int | None:
    counts: Counter[int] = Counter()
    for gy in range(grid_h):
        for gx in range(grid_w):
            value = _dominant_grid_cell_value(arr, origin_x, origin_y, cell, gx, gy)
            if value is not None and int(value) != int(cursor_value):
                counts[int(value)] += 1
    if not counts:
        return None
    return int(counts.most_common(1)[0][0])


def _mirror_joint_hazard_cells(
    arr: np.ndarray,
    origin_x: int,
    origin_y: int,
    cell: int,
    grid_w: int,
    grid_h: int,
    *,
    walkable_value: int,
    cursor_value: int,
) -> set[tuple[int, int]]:
    hazards: set[tuple[int, int]] = set()
    total = max(1, int(cell * cell))
    min_support = max(1, int(round(total * 0.25)))
    for gy in range(grid_h):
        for gx in range(grid_w):
            x0 = int(origin_x + gx * cell)
            y0 = int(origin_y + gy * cell)
            patch = arr[y0 : y0 + cell, x0 : x0 + cell]
            if patch.shape != (cell, cell):
                continue
            counts = Counter(int(value) for value in patch.flatten().tolist())
            if counts.get(int(walkable_value), 0) < min_support:
                continue
            for value, count in counts.items():
                value = int(value)
                if value in {int(walkable_value), int(cursor_value)}:
                    continue
                if int(count) >= min_support:
                    hazards.add((int(gx), int(gy)))
                    break
    return hazards


def _mirror_joint_pure_special_count(
    arr: np.ndarray,
    origin_x: int,
    origin_y: int,
    cell: int,
    grid_w: int,
    grid_h: int,
    *,
    walkable_value: int,
    cursor_value: int,
) -> int:
    total = max(1, int(cell * cell))
    min_support = max(1, int(round(total * 0.25)))
    count = 0
    for gy in range(grid_h):
        for gx in range(grid_w):
            x0 = int(origin_x + gx * cell)
            y0 = int(origin_y + gy * cell)
            patch = arr[y0 : y0 + cell, x0 : x0 + cell]
            if patch.shape != (cell, cell):
                continue
            counts = Counter(int(value) for value in patch.flatten().tolist())
            dominant = int(max(counts, key=lambda value: (counts[value], value)))
            if dominant in {int(walkable_value), int(cursor_value)}:
                continue
            if counts.get(int(walkable_value), 0) >= min_support:
                continue
            count += 1
    return int(count)


def _mirror_joint_cell_signatures(
    arr: np.ndarray,
    origin_x: int,
    origin_y: int,
    cell: int,
    grid_w: int,
    grid_h: int,
) -> dict[tuple[int, int], tuple[tuple[int, int], ...]]:
    signatures: dict[tuple[int, int], tuple[tuple[int, int], ...]] = {}
    for gy in range(grid_h):
        for gx in range(grid_w):
            x0 = int(origin_x + gx * cell)
            y0 = int(origin_y + gy * cell)
            patch = arr[y0 : y0 + cell, x0 : x0 + cell]
            if patch.shape != (cell, cell):
                continue
            counts = Counter(int(value) for value in patch.flatten().tolist())
            signatures[(int(gx), int(gy))] = tuple(
                (int(value), int(count))
                for value, count in sorted(
                    counts.items(),
                    key=lambda item: (-int(item[1]), int(item[0])),
                )
            )
    return signatures


def _mirror_joint_state_from_pair(
    arr: np.ndarray,
    first: Mapping[str, int],
    second: Mapping[str, int],
    *,
    allow_centered_geometry: bool = True,
) -> dict[str, Any] | None:
    first, second = sorted(
        (dict(first), dict(second)),
        key=lambda item: (int(item["cx"]), int(item["cy"])),
    )
    cell = int(
        round(
            float(
                sum(
                    [
                        first["width"],
                        first["height"],
                        second["width"],
                        second["height"],
                    ]
                )
            )
            / 4.0
        )
    )
    if cell <= 1:
        return None
    origin_x = min(int(first["min_x"]), int(second["min_x"])) % cell
    origin_y = min(int(first["min_y"]), int(second["min_y"])) % cell
    height, width = arr.shape
    grid_w = (width - 2 * origin_x) // cell if origin_x > 0 else width // cell
    grid_h = (height - 2 * origin_y) // cell if origin_y > 0 else height // cell
    if grid_w < 3 or grid_h < 3:
        return None
    cursor_value = int(first["value"])
    centered_geometry = None
    if allow_centered_geometry:
        centered_geometry = _mirror_joint_centered_geometry(
            arr,
            cell=cell,
            cursor_value=cursor_value,
            cursor_components=(first, second),
            default_origin=(origin_x, origin_y),
            default_grid_size=(grid_w, grid_h),
        )
    if centered_geometry is not None:
        origin_x, origin_y = centered_geometry["origin"]
        grid_w, grid_h = centered_geometry["grid_size"]
    cell_values: Counter[int] = Counter()
    for gy in range(grid_h):
        for gx in range(grid_w):
            value = _dominant_grid_cell_value(arr, origin_x, origin_y, cell, gx, gy)
            if value is not None:
                cell_values[int(value)] += 1
    walkable_values = [
        value
        for value, _count in cell_values.most_common()
        if int(value) != cursor_value
    ]
    if not walkable_values:
        return None
    walkable_value = int(walkable_values[0])
    hazards = _mirror_joint_hazard_cells(
        arr,
        origin_x,
        origin_y,
        cell,
        grid_w,
        grid_h,
        walkable_value=walkable_value,
        cursor_value=cursor_value,
    )
    cell_signatures = _mirror_joint_cell_signatures(
        arr,
        origin_x,
        origin_y,
        cell,
        grid_w,
        grid_h,
    )
    walkable: set[tuple[int, int]] = set()
    cursor_cell_count = 0
    for gy in range(grid_h):
        for gx in range(grid_w):
            value = _dominant_grid_cell_value(arr, origin_x, origin_y, cell, gx, gy)
            if value == cursor_value:
                cursor_cell_count += 1
            if value in {walkable_value, cursor_value} and (gx, gy) not in hazards:
                walkable.add((gx, gy))
    cursor_a = (
        int(round(float(first["min_x"] - origin_x) / float(cell))),
        int(round(float(first["min_y"] - origin_y) / float(cell))),
    )
    cursor_b = (
        int(round(float(second["min_x"] - origin_x) / float(cell))),
        int(round(float(second["min_y"] - origin_y) / float(cell))),
    )
    if cursor_a not in walkable or cursor_b not in walkable:
        return None
    return {
        "cursor_a": cursor_a,
        "cursor_b": cursor_b,
        "walkable": frozenset(walkable),
        "cell": cell,
        "origin": (origin_x, origin_y),
        "grid_size": (grid_w, grid_h),
        "cursor_value": cursor_value,
        "walkable_value": walkable_value,
        "hazards": frozenset(hazards),
        "death": frozenset(hazards),
        "cell_signatures": cell_signatures,
        "cursor_cell_count": int(cursor_cell_count),
    }


def _mirror_joint_certified_pair_state(
    frame: np.ndarray,
) -> dict[str, Any] | None:
    arr = np.asarray(frame)
    if arr.ndim != 2 or arr.size <= 0:
        return None
    components = _valued_components(arr)
    by_value: dict[int, list[dict[str, int]]] = defaultdict(list)
    value_counts = Counter(int(value) for value in arr.flatten().tolist())
    for component in components:
        area = int(component["area"])
        width = int(component["width"])
        height = int(component["height"])
        value = int(component["value"])
        if area < 4 or area > 144:
            continue
        if width < 2 or height < 2 or width > 16 or height > 16:
            continue
        if max(width, height) > max(2, min(width, height) * 2):
            continue
        if value_counts[value] > 256:
            continue
        by_value[value].append(component)
    best: tuple[tuple[int, int, int, int, int], dict[str, Any]] | None = None
    for comps in by_value.values():
        if len(comps) < 2:
            continue
        ordered = sorted(
            comps,
            key=lambda item: (-int(item["area"]), int(item["min_x"]), int(item["min_y"])),
        )
        for left_index, first in enumerate(ordered):
            for second in ordered[left_index + 1 :]:
                state = _mirror_joint_state_from_pair(
                    arr,
                    first,
                    second,
                    allow_centered_geometry=True,
                )
                if not _mirror_pair_is_certified(state):
                    continue
                assert state is not None
                area_delta = abs(int(first["area"]) - int(second["area"]))
                size_delta = abs(int(first["width"]) - int(second["width"])) + abs(
                    int(first["height"]) - int(second["height"])
                )
                cursor_count_delta = abs(int(state.get("cursor_cell_count", 0)) - 2)
                score = (
                    cursor_count_delta,
                    0 if len(comps) == 2 else 1,
                    area_delta + size_delta,
                    -min(int(first["area"]), int(second["area"])),
                    int(state["grid_size"][0]) * int(state["grid_size"][1]),
                )
                if best is None or score < best[0]:
                    best = (score, state)
    if best is None:
        return None
    state = dict(best[1])
    state["certified_pair_reader"] = "same_row_center_symmetric"
    return state


def _split_joined_cursor_component(
    components: list[dict[str, int]],
    value_counts: Counter[int],
) -> tuple[dict[str, int], dict[str, int]] | None:
    candidates: list[tuple[int, int, int, int, int, int, dict[str, int]]] = []
    for component in components:
        value = int(component["value"])
        if value_counts[value] > 256:
            continue
        width = int(component["width"])
        height = int(component["height"])
        area = int(component["area"])
        if area < 8 or area > 288:
            continue
        if width >= max(4, height * 2 - 1) and width <= height * 3:
            candidates.append(
                (
                    -area,
                    int(component["min_x"]),
                    int(component["min_y"]),
                    int(component["max_x"]),
                    int(component["max_y"]),
                    value,
                    component,
                )
            )
    if not candidates:
        return None
    *_score, component = sorted(candidates)[0]
    cell = int(component["height"])
    if cell <= 1:
        return None
    left = dict(component)
    right = dict(component)
    left["area"] = cell * int(component["height"])
    right["area"] = cell * int(component["height"])
    left["width"] = cell
    right["width"] = cell
    left["min_x"] = int(component["min_x"])
    left["max_x"] = int(component["min_x"]) + cell - 1
    right["min_x"] = int(component["min_x"]) + cell
    right["max_x"] = int(component["min_x"]) + 2 * cell - 1
    left["cx"] = int(round((left["min_x"] + left["max_x"]) / 2.0))
    right["cx"] = int(round((right["min_x"] + right["max_x"]) / 2.0))
    return left, right


def _mirror_joint_cursor_bfs_action(
    cursor_a: tuple[int, int],
    cursor_b: tuple[int, int],
    walkable: frozenset[tuple[int, int]],
    available: set[str],
    *,
    death: frozenset[tuple[int, int]] | None = None,
    blocked: set[tuple[tuple[int, int], tuple[int, int], str]] | None = None,
    hazards: frozenset[tuple[int, int]] = frozenset(),
) -> str | None:
    if death is not None:
        hazards = death
    blocked_actions = set(blocked or ())
    directions = [
        ("ACTION1", 0, -1),
        ("ACTION2", 0, 1),
        ("ACTION3", -1, 0),
        ("ACTION4", 1, 0),
    ]
    directions = [(action, dx, dy) for action, dx, dy in directions if action in available]
    if not directions:
        return None
    initial = (cursor_a, cursor_b)
    visited = {initial}
    queue: deque[tuple[tuple[tuple[int, int], tuple[int, int]], str | None]] = deque([(initial, None)])
    while queue:
        (a, b), first_action = queue.popleft()
        for action, dx, dy in directions:
            if (a, b, action) in blocked_actions:
                continue
            intended_a = (a[0] + dx, a[1] + dy)
            intended_b = (b[0] - dx, b[1] + dy)
            if intended_a in hazards or intended_b in hazards:
                continue
            a_new = intended_a
            b_new = intended_b
            if a_new not in walkable:
                a_new = a
            if b_new not in walkable:
                b_new = b
            if abs(a[0] - b[0]) == 1 and a[1] == b[1] and (a_new == b or b_new == a):
                return first_action or action
            if a_new == a and b_new == b:
                continue
            state = (a_new, b_new)
            if state in visited:
                continue
            visited.add(state)
            queue.append((state, first_action or action))
    return None


def _mirror_joint_cursor_bfs_plan(
    cursor_a: tuple[int, int],
    cursor_b: tuple[int, int],
    walkable: frozenset[tuple[int, int]],
    available: set[str],
    *,
    blocked: set[tuple[tuple[int, int], tuple[int, int], str]] | None = None,
    hazards: frozenset[tuple[int, int]] = frozenset(),
) -> list[str] | None:
    blocked_actions = set(blocked or ())
    directions = [
        ("ACTION1", 0, -1),
        ("ACTION2", 0, 1),
        ("ACTION3", -1, 0),
        ("ACTION4", 1, 0),
    ]
    directions = [(action, dx, dy) for action, dx, dy in directions if action in available]
    if not directions:
        return None
    initial = (cursor_a, cursor_b)
    visited = {initial}
    queue: deque[tuple[tuple[tuple[int, int], tuple[int, int]], list[str]]] = deque(
        [(initial, [])]
    )
    while queue:
        (a, b), path = queue.popleft()
        for action, dx, dy in directions:
            if (a, b, action) in blocked_actions:
                continue
            intended_a = (a[0] + dx, a[1] + dy)
            intended_b = (b[0] - dx, b[1] + dy)
            if intended_a in hazards or intended_b in hazards:
                continue
            a_new = intended_a if intended_a in walkable else a
            b_new = intended_b if intended_b in walkable else b
            next_path = path + [action]
            if abs(a[0] - b[0]) == 1 and a[1] == b[1] and (a_new == b or b_new == a):
                return next_path
            if a_new == b_new:
                return next_path
            if a_new == a and b_new == b:
                continue
            state = (a_new, b_new)
            if state in visited:
                continue
            visited.add(state)
            queue.append((state, next_path))
    return None


def _mirror_grid_click_payload(
    state: Mapping[str, Any],
    site: tuple[int, int],
) -> dict[str, int]:
    origin_x, origin_y = state["origin"]
    cell = int(state["cell"])
    gx, gy = site
    return {
        "x": int(origin_x) + int(gx) * cell + max(0, cell // 2),
        "y": int(origin_y) + int(gy) * cell + max(0, cell // 2),
    }


def _mirror_selectable_blocker_candidates(
    state: Mapping[str, Any],
) -> list[tuple[int, int]]:
    hazards = set(state.get("hazards") or ())
    signatures: Mapping[tuple[int, int], tuple[tuple[int, int], ...]] = (
        state.get("cell_signatures") or {}
    )
    walkable_value = int(state.get("walkable_value", -999999))
    cursor_value = int(state.get("cursor_value", -999998))
    cell_size = max(1, int(state.get("cell", 1)))
    total = max(1, cell_size**2)
    min_support = max(1, int(round(float(total) * 0.25)))
    max_center_sprite_support = max(min_support, max(1, cell_size - 2) ** 2)
    candidates: list[tuple[int, int]] = []
    for site in sorted(hazards, key=lambda item: (int(item[1]), int(item[0]))):
        counts = {int(value): int(count) for value, count in signatures.get(site, ())}
        if counts.get(walkable_value, 0) < min_support:
            continue
        non_floor_support = sum(
            int(count)
            for value, count in counts.items()
            if int(value) not in {walkable_value, cursor_value}
        )
        if non_floor_support < min_support:
            continue
        if non_floor_support > max_center_sprite_support:
            continue
        if counts.get(walkable_value, 0) <= non_floor_support:
            continue
        candidates.append((int(site[0]), int(site[1])))
    return candidates


def _mirror_selectable_blocker_reposition_plan(
    state: Mapping[str, Any],
    available: set[str],
    *,
    max_expansions: int = 20000,
) -> tuple[list[tuple[str, dict[str, Any] | None]], dict[str, Any]]:
    diag: dict[str, Any] = {
        "planner": "mirror_selectable_blocker_reposition",
        "blocked_reason": "",
        "expanded_block_config_count": 0,
    }
    cursor_a = tuple(int(v) for v in state["cursor_a"])
    cursor_b = tuple(int(v) for v in state["cursor_b"])
    blockers = tuple(sorted(_mirror_selectable_blocker_candidates(state)))
    diag["selectable_blocker_count"] = int(len(blockers))
    diag["selectable_blockers"] = [[int(x), int(y)] for x, y in blockers]
    if len(blockers) < 1:
        diag["blocked_reason"] = "no_selectable_blocker_candidates"
        return [], diag
    if len(blockers) > 5:
        diag["blocked_reason"] = "too_many_selectable_blocker_candidates"
        return [], diag
    directions = [
        ("ACTION1", 0, -1),
        ("ACTION2", 0, 1),
        ("ACTION3", -1, 0),
        ("ACTION4", 1, 0),
    ]
    directions = [(action, dx, dy) for action, dx, dy in directions if action in available]
    if not directions:
        diag["blocked_reason"] = "no_directional_actions"
        return [], diag
    full_floor = set(state.get("walkable") or ()) | set(blockers)
    if cursor_a not in full_floor or cursor_b not in full_floor:
        diag["blocked_reason"] = "cursor_not_on_floor"
        return [], diag
    fixed_hazards = set(state.get("hazards") or ()) - set(blockers)

    def cursor_plan_for(block_config: tuple[tuple[int, int], ...]) -> list[str] | None:
        walkable = frozenset(full_floor - set(block_config))
        hazards = frozenset(fixed_hazards | set(block_config))
        return _mirror_joint_cursor_bfs_plan(
            cursor_a,
            cursor_b,
            walkable,
            available,
            hazards=hazards,
        )

    parent: dict[
        tuple[tuple[int, int], ...],
        tuple[
            tuple[tuple[int, int], ...] | None,
            tuple[tuple[int, int], str, tuple[int, int]] | None,
        ],
    ] = {blockers: (None, None)}
    queue: deque[tuple[tuple[int, int], ...]] = deque([blockers])
    found_blocks: tuple[tuple[int, int], ...] | None = None
    found_cursor_plan: list[str] | None = None
    while queue and int(diag["expanded_block_config_count"]) < int(max_expansions):
        block_config = queue.popleft()
        diag["expanded_block_config_count"] = int(diag["expanded_block_config_count"]) + 1
        found_cursor_plan = cursor_plan_for(block_config)
        if found_cursor_plan:
            found_blocks = block_config
            break
        occupied = set(block_config)
        for index, old in enumerate(block_config):
            for action, dx, dy in directions:
                new = (int(old[0]) + dx, int(old[1]) + dy)
                if new not in full_floor:
                    continue
                if new in occupied:
                    continue
                if new in {cursor_a, cursor_b}:
                    continue
                next_blocks_list = list(block_config)
                next_blocks_list[index] = new
                next_blocks = tuple(sorted(next_blocks_list))
                if next_blocks in parent:
                    continue
                parent[next_blocks] = (block_config, (old, action, new))
                queue.append(next_blocks)
    if found_blocks is None or not found_cursor_plan:
        if len(blockers) == 1:
            safe_floor = set(full_floor) - fixed_hazards
            blocker_start = blockers[0]
            start = (cursor_a, cursor_b, blocker_start, "cursor")
            interleaved_queue: deque[
                tuple[
                    tuple[tuple[int, int], tuple[int, int], tuple[int, int], str],
                    list[tuple[str, dict[str, Any] | None]],
                    int,
                    int,
                ]
            ] = deque([(start, [], 0, 0)])
            interleaved_seen = {start}
            interleaved_expanded = 0
            interleaved_max_depth = 48

            def unclick_site_for(
                a_pos: tuple[int, int],
                b_pos: tuple[int, int],
                blocker_pos: tuple[int, int],
            ) -> tuple[int, int] | None:
                return next(
                    (
                        site
                        for site in sorted(
                            safe_floor,
                            key=lambda item: (int(item[1]), int(item[0])),
                        )
                        if site not in {a_pos, b_pos, blocker_pos}
                    ),
                    None,
                )

            while (
                interleaved_queue
                and interleaved_expanded < int(max_expansions)
            ):
                (a_pos, b_pos, blocker_pos, mode), path, block_move_count, cursor_move_count = (
                    interleaved_queue.popleft()
                )
                interleaved_expanded += 1
                if len(path) >= interleaved_max_depth:
                    continue
                if mode == "cursor":
                    next_state = (a_pos, b_pos, blocker_pos, "blocker")
                    if next_state not in interleaved_seen:
                        interleaved_seen.add(next_state)
                        interleaved_queue.append(
                            (
                                next_state,
                                path
                                + [
                                    (
                                        "ACTION6",
                                        _mirror_grid_click_payload(state, blocker_pos),
                                    )
                                ],
                                block_move_count,
                                cursor_move_count,
                            )
                        )
                    cursor_walkable = safe_floor - {blocker_pos}
                    for action, dx, dy in directions:
                        intended_a = (int(a_pos[0]) + dx, int(a_pos[1]) + dy)
                        intended_b = (int(b_pos[0]) - dx, int(b_pos[1]) + dy)
                        if intended_a in fixed_hazards or intended_b in fixed_hazards:
                            continue
                        a_new = intended_a if intended_a in cursor_walkable else a_pos
                        b_new = intended_b if intended_b in cursor_walkable else b_pos
                        if a_new == a_pos and b_new == b_pos:
                            continue
                        next_path = path + [(str(action), None)]
                        next_cursor_count = cursor_move_count + 1
                        if (
                            abs(int(a_pos[0]) - int(b_pos[0])) == 1
                            and int(a_pos[1]) == int(b_pos[1])
                            and (a_new == b_pos or b_new == a_pos)
                        ) or a_new == b_new:
                            diag.update(
                                {
                                    "blocked_reason": "",
                                    "interleaved_blocker_cursor_plan": True,
                                    "expanded_interleaved_state_count": int(
                                        interleaved_expanded
                                    ),
                                    "block_move_count": int(block_move_count),
                                    "cursor_plan_len": int(next_cursor_count),
                                    "plan_len": int(len(next_path)),
                                    "final_blockers": [
                                        [int(blocker_pos[0]), int(blocker_pos[1])]
                                    ],
                                }
                            )
                            return next_path, diag
                        next_state = (a_new, b_new, blocker_pos, "cursor")
                        if next_state in interleaved_seen:
                            continue
                        interleaved_seen.add(next_state)
                        interleaved_queue.append(
                            (
                                next_state,
                                next_path,
                                block_move_count,
                                next_cursor_count,
                            )
                        )
                else:
                    unclick_site = unclick_site_for(a_pos, b_pos, blocker_pos)
                    if unclick_site is not None:
                        next_state = (a_pos, b_pos, blocker_pos, "cursor")
                        if next_state not in interleaved_seen:
                            interleaved_seen.add(next_state)
                            interleaved_queue.append(
                                (
                                    next_state,
                                    path
                                    + [
                                        (
                                            "ACTION6",
                                            _mirror_grid_click_payload(
                                                state, unclick_site
                                            ),
                                        )
                                    ],
                                    block_move_count,
                                    cursor_move_count,
                                )
                            )
                    for action, dx, dy in directions:
                        new_blocker = (
                            int(blocker_pos[0]) + dx,
                            int(blocker_pos[1]) + dy,
                        )
                        if new_blocker not in safe_floor:
                            continue
                        if new_blocker in {a_pos, b_pos}:
                            continue
                        next_state = (a_pos, b_pos, new_blocker, "blocker")
                        if next_state in interleaved_seen:
                            continue
                        interleaved_seen.add(next_state)
                        interleaved_queue.append(
                            (
                                next_state,
                                path + [(str(action), None)],
                                block_move_count + 1,
                                cursor_move_count,
                            )
                        )
            diag["expanded_interleaved_state_count"] = int(interleaved_expanded)
        diag["blocked_reason"] = "no_reposition_plan"
        diag["reached_expansion_limit"] = bool(
            int(diag["expanded_block_config_count"]) >= int(max_expansions)
        )
        return [], diag

    block_moves: list[tuple[tuple[int, int], str, tuple[int, int]]] = []
    cursor = found_blocks
    while parent[cursor][0] is not None:
        previous, move = parent[cursor]
        assert previous is not None and move is not None
        block_moves.append(move)
        cursor = previous
    block_moves.reverse()

    final_blockers = set(found_blocks)
    unclick_site = next(
        (
            site
            for site in sorted(full_floor, key=lambda item: (int(item[1]), int(item[0])))
            if site not in final_blockers and site not in {cursor_a, cursor_b}
        ),
        None,
    )
    if unclick_site is None:
        diag["blocked_reason"] = "no_unclick_site"
        return [], diag

    plan: list[tuple[str, dict[str, Any] | None]] = []
    for old, action, _new in block_moves:
        plan.append(("ACTION6", _mirror_grid_click_payload(state, old)))
        plan.append((str(action), None))
    plan.append(("ACTION6", _mirror_grid_click_payload(state, unclick_site)))
    for action in found_cursor_plan:
        plan.append((str(action), None))

    diag.update(
        {
            "blocked_reason": "",
            "block_move_count": int(len(block_moves)),
            "cursor_plan_len": int(len(found_cursor_plan)),
            "plan_len": int(len(plan)),
            "final_blockers": [[int(x), int(y)] for x, y in found_blocks],
            "unclick_site": [int(unclick_site[0]), int(unclick_site[1])],
        }
    )
    return plan, diag


def _mirror_color_lock_target_components(
    state: Mapping[str, Any],
) -> tuple[
    dict[int, set[tuple[int, int]]],
    dict[int, set[tuple[int, int]]],
    set[tuple[int, int]],
]:
    signatures: Mapping[tuple[int, int], tuple[tuple[int, int], ...]] = (
        state.get("cell_signatures") or {}
    )
    walkable_value = int(state.get("walkable_value", -999999))
    cursor_value = int(state.get("cursor_value", -999998))
    cell_size = max(1, int(state.get("cell", 1)))
    pure_cell_support = int(cell_size * cell_size)
    by_value: dict[int, set[tuple[int, int]]] = defaultdict(set)
    for site, signature in signatures.items():
        if not signature:
            continue
        value, count = signature[0]
        value = int(value)
        if value in {walkable_value, cursor_value}:
            continue
        if int(count) != pure_cell_support:
            continue
        by_value[value].add((int(site[0]), int(site[1])))

    def connected_components(
        sites: set[tuple[int, int]],
    ) -> list[set[tuple[int, int]]]:
        remaining = set(sites)
        components: list[set[tuple[int, int]]] = []
        while remaining:
            start = remaining.pop()
            component = {start}
            queue: deque[tuple[int, int]] = deque([start])
            while queue:
                x, y = queue.popleft()
                for neighbor in (
                    (x + 1, y),
                    (x - 1, y),
                    (x, y + 1),
                    (x, y - 1),
                ):
                    if neighbor not in remaining:
                        continue
                    remaining.remove(neighbor)
                    component.add(neighbor)
                    queue.append(neighbor)
            components.append(component)
        return components

    locks_by_value: dict[int, set[tuple[int, int]]] = {}
    targets_by_value: dict[int, set[tuple[int, int]]] = {}
    walls: set[tuple[int, int]] = set(state.get("hazards") or ())
    for value, sites in by_value.items():
        components = connected_components(set(sites))
        if not components:
            continue
        max_component_size = max(len(component) for component in components)
        line_components = [
            component
            for component in components
            if len(component) >= 2
            and (
                len({int(x) for x, _y in component}) == 1
                or len({int(y) for _x, y in component}) == 1
            )
        ]
        singleton_targets = [
            next(iter(component)) for component in components if len(component) == 1
        ]
        # Temporary colour locks are compact: a short same-colour bar plus
        # one or more singleton same-colour targets. Long same-colour borders
        # are structural walls, not colour-lock gates.
        if max_component_size <= 3 and line_components and singleton_targets:
            locks: set[tuple[int, int]] = set()
            for component in line_components:
                locks.update(component)
            locks_by_value[int(value)] = locks
            targets_by_value[int(value)] = {
                (int(x), int(y)) for x, y in singleton_targets
            }
        else:
            walls.update((int(x), int(y)) for x, y in sites)
    return locks_by_value, targets_by_value, walls


def _mirror_color_lock_target_plan(
    state: Mapping[str, Any],
    available: set[str],
    *,
    max_expansions: int = 60000,
) -> tuple[list[tuple[str, dict[str, Any] | None]], dict[str, Any]]:
    diag: dict[str, Any] = {
        "planner": "mirror_color_lock_target_planner",
        "blocked_reason": "",
        "expanded_state_count": 0,
        "candidate_generation_enabled": True,
        "action_generation_allowed": True,
        "ranking_only": False,
    }
    try:
        cursor_a = tuple(int(v) for v in state["cursor_a"])
        cursor_b = tuple(int(v) for v in state["cursor_b"])
    except (KeyError, TypeError, ValueError):
        diag["blocked_reason"] = "invalid_cursor_state"
        return [], diag
    directions = [
        ("ACTION1", 0, -1),
        ("ACTION2", 0, 1),
        ("ACTION3", -1, 0),
        ("ACTION4", 1, 0),
    ]
    directions = [
        (action, dx, dy) for action, dx, dy in directions if action in available
    ]
    if not directions:
        diag["blocked_reason"] = "no_directional_actions"
        return [], diag

    locks_by_value, targets_by_value, walls = _mirror_color_lock_target_components(
        state
    )
    target_cells = {
        site for sites in targets_by_value.values() for site in sites
    }
    lock_cells = {site for sites in locks_by_value.values() for site in sites}
    diag.update(
        {
            "lock_target_color_count": int(len(locks_by_value)),
            "target_cell_count": int(len(target_cells)),
            "lock_cell_count": int(len(lock_cells)),
            "wall_cell_count": int(len(walls)),
            "target_cells": [
                [int(x), int(y)] for x, y in sorted(target_cells)
            ][:12],
            "lock_values": [int(value) for value in sorted(locks_by_value)],
            "grid_size": [
                int(v) for v in tuple(state.get("grid_size", ()))[:2]
            ],
        }
    )
    if not locks_by_value or not targets_by_value:
        diag["blocked_reason"] = "no_color_lock_target_components"
        return [], diag
    walkable_cells = set(state.get("walkable") or ())
    if cursor_a not in walkable_cells or cursor_b not in walkable_cells:
        diag["blocked_reason"] = "cursor_not_on_walkable"
        return [], diag

    base_walkable = walkable_cells | set(target_cells)
    target_to_value = {
        site: int(value)
        for value, sites in targets_by_value.items()
        for site in sites
    }

    best_plan: list[str] | None = None
    best_diag: dict[str, Any] = {}
    total_expanded = 0
    # Try the opposite-x polarity first. Some mirror layouts render the left
    # cursor as the sprite whose horizontal action is inverted; enumerating
    # both keeps the lane frame-conditioned instead of name-conditioned.
    for x_polarity in (-1, 1):
        start = (cursor_a, cursor_b)
        queue: deque[tuple[tuple[tuple[int, int], tuple[int, int]], list[str]]] = (
            deque([(start, [])])
        )
        seen = {start}
        expanded = 0
        while queue and total_expanded + expanded < int(max_expansions):
            (a_pos, b_pos), path = queue.popleft()
            expanded += 1
            active_values = {
                int(target_to_value[site])
                for site in (a_pos, b_pos)
                if site in target_to_value
            }
            active_lock_cells: set[tuple[int, int]] = set()
            for value in active_values:
                active_lock_cells.update(locks_by_value.get(value, set()))
            current_walkable = base_walkable | active_lock_cells
            for action, dx, dy in directions:
                intended_a = (
                    int(a_pos[0]) + int(x_polarity) * int(dx),
                    int(a_pos[1]) + int(dy),
                )
                intended_b = (
                    int(b_pos[0]) - int(x_polarity) * int(dx),
                    int(b_pos[1]) + int(dy),
                )
                a_new = intended_a if intended_a in current_walkable else a_pos
                b_new = intended_b if intended_b in current_walkable else b_pos
                if a_new == a_pos and b_new == b_pos:
                    continue
                next_path = path + [str(action)]
                if (
                    abs(int(a_pos[0]) - int(b_pos[0])) == 1
                    and int(a_pos[1]) == int(b_pos[1])
                    and (a_new == b_pos or b_new == a_pos)
                ) or a_new == b_new:
                    best_plan = next_path
                    best_diag = {
                        "selected_x_polarity": int(x_polarity),
                        "expanded_state_count_for_polarity": int(expanded),
                    }
                    queue.clear()
                    break
                next_state = (a_new, b_new)
                if next_state in seen:
                    continue
                seen.add(next_state)
                queue.append((next_state, next_path))
        total_expanded += expanded
        if best_plan:
            break

    diag["expanded_state_count"] = int(total_expanded)
    if not best_plan:
        diag["blocked_reason"] = "no_color_lock_target_plan"
        diag["reached_expansion_limit"] = bool(total_expanded >= int(max_expansions))
        return [], diag
    plan = [(str(action), None) for action in best_plan]
    diag.update(best_diag)
    diag.update(
        {
            "blocked_reason": "",
            "plan_len": int(len(plan)),
            "first_actions": [str(action) for action in best_plan[:8]],
        }
    )
    return plan, diag


def _mirror_color_lock_blocker_plan(
    state: Mapping[str, Any],
    available: set[str],
    *,
    max_expansions: int = 500000,
    max_depth: int = 96,
) -> tuple[list[tuple[str, dict[str, Any] | None]], dict[str, Any]]:
    diag: dict[str, Any] = {
        "planner": "mirror_color_lock_blocker_planner",
        "blocked_reason": "",
        "expanded_state_count": 0,
        "candidate_generation_enabled": True,
        "action_generation_allowed": True,
        "ranking_only": False,
    }
    try:
        cursor_a = tuple(int(v) for v in state["cursor_a"])
        cursor_b = tuple(int(v) for v in state["cursor_b"])
        grid_w, grid_h = tuple(int(v) for v in state["grid_size"])
    except (KeyError, TypeError, ValueError):
        diag["blocked_reason"] = "invalid_cursor_state"
        return [], diag
    directions = [
        ("ACTION1", 0, -1),
        ("ACTION2", 0, 1),
        ("ACTION3", -1, 0),
        ("ACTION4", 1, 0),
    ]
    directions = [
        (action, dx, dy) for action, dx, dy in directions if action in available
    ]
    if "ACTION6" not in available:
        diag["blocked_reason"] = "action6_unavailable"
        return [], diag
    if not directions:
        diag["blocked_reason"] = "no_directional_actions"
        return [], diag

    locks_by_value, targets_by_value, _walls = _mirror_color_lock_target_components(
        state
    )
    target_cells = {
        site for sites in targets_by_value.values() for site in sites
    }
    lock_cells = {site for sites in locks_by_value.values() for site in sites}
    blockers = tuple(sorted(_mirror_selectable_blocker_candidates(state)))
    hazard_cells = set(state.get("hazards") or ())
    # Checker-overlay reset cells and selectable blockers are both perceived
    # as floor+foreign-colour hazards. The blocker candidates are movable;
    # the remaining hazard cells are unsafe/solid for this guarded planner.
    death_cells = set(hazard_cells) - set(blockers)
    diag.update(
        {
            "lock_target_color_count": int(len(locks_by_value)),
            "target_cell_count": int(len(target_cells)),
            "lock_cell_count": int(len(lock_cells)),
            "selectable_blocker_count": int(len(blockers)),
            "selectable_blockers": [[int(x), int(y)] for x, y in blockers],
            "death_cell_count": int(len(death_cells)),
            "grid_size": [int(grid_w), int(grid_h)],
        }
    )
    if not locks_by_value or not targets_by_value:
        diag["blocked_reason"] = "no_color_lock_target_components"
        return [], diag
    if len(blockers) != 1:
        diag["blocked_reason"] = "selectable_blocker_count_not_one"
        return [], diag

    blocker_start = blockers[0]
    base_walkable = set(state.get("walkable") or ()) | set(target_cells) | set(blockers)
    all_cells = {
        (int(x), int(y))
        for y in range(max(0, int(grid_h)))
        for x in range(max(0, int(grid_w)))
    }
    # Keep the planner conservative: it can route through cells that are
    # already walkable/target/cursor, never through arbitrary unknown cells.
    base_walkable |= {cursor_a, cursor_b}
    target_to_values: dict[tuple[int, int], set[int]] = defaultdict(set)
    for value, sites in targets_by_value.items():
        for site in sites:
            target_to_values[site].add(int(value))

    def active_values(
        a_pos: tuple[int, int],
        b_pos: tuple[int, int],
    ) -> set[int]:
        values: set[int] = set()
        values.update(target_to_values.get(a_pos, set()))
        values.update(target_to_values.get(b_pos, set()))
        return values

    def locked_for(
        a_pos: tuple[int, int],
        b_pos: tuple[int, int],
    ) -> set[tuple[int, int]]:
        active = active_values(a_pos, b_pos)
        locked: set[tuple[int, int]] = set()
        for value, cells in locks_by_value.items():
            if int(value) not in active:
                locked.update(cells)
        return locked

    def cursor_floor(
        a_pos: tuple[int, int],
        b_pos: tuple[int, int],
        blocker_pos: tuple[int, int],
    ) -> set[tuple[int, int]]:
        return (
            (base_walkable | target_cells | lock_cells)
            - death_cells
            - locked_for(a_pos, b_pos)
            - {blocker_pos}
        )

    def blocker_floor(
        a_pos: tuple[int, int],
        b_pos: tuple[int, int],
    ) -> set[tuple[int, int]]:
        return (
            (base_walkable | target_cells | lock_cells)
            - death_cells
            - locked_for(a_pos, b_pos)
            - {a_pos, b_pos}
        )

    def unclick_payload(
        a_pos: tuple[int, int],
        b_pos: tuple[int, int],
        blocker_pos: tuple[int, int],
    ) -> dict[str, Any] | None:
        candidates = sorted(
            all_cells - {a_pos, b_pos, blocker_pos},
            key=lambda site: (int(site[1]), int(site[0])),
        )
        if not candidates:
            return None
        return _mirror_grid_click_payload(state, candidates[0])

    start = (cursor_a, cursor_b, blocker_start, "cursor")
    queue: deque[
        tuple[
            tuple[tuple[int, int], tuple[int, int], tuple[int, int], str],
            list[tuple[str, dict[str, Any] | None]],
        ]
    ] = deque([(start, [])])
    seen = {start}
    while queue and int(diag["expanded_state_count"]) < int(max_expansions):
        (a_pos, b_pos, blocker_pos, mode), path = queue.popleft()
        diag["expanded_state_count"] = int(diag["expanded_state_count"]) + 1
        if len(path) >= int(max_depth):
            continue
        if mode == "cursor":
            next_state = (a_pos, b_pos, blocker_pos, "blocker")
            if next_state not in seen:
                seen.add(next_state)
                queue.append(
                    (
                        next_state,
                        path
                        + [
                            (
                                "ACTION6",
                                _mirror_grid_click_payload(state, blocker_pos),
                            )
                        ],
                    )
                )
            floor = cursor_floor(a_pos, b_pos, blocker_pos)
            for action, dx, dy in directions:
                intended_a = (int(a_pos[0]) + int(dx), int(a_pos[1]) + int(dy))
                intended_b = (int(b_pos[0]) - int(dx), int(b_pos[1]) + int(dy))
                if intended_a in death_cells or intended_b in death_cells:
                    continue
                a_new = intended_a if intended_a in floor else a_pos
                b_new = intended_b if intended_b in floor else b_pos
                next_path = path + [(str(action), None)]
                if (
                    abs(int(a_pos[0]) - int(b_pos[0])) == 1
                    and int(a_pos[1]) == int(b_pos[1])
                    and (a_new == b_pos or b_new == a_pos)
                ) or a_new == b_new:
                    diag.update(
                        {
                            "blocked_reason": "",
                            "plan_len": int(len(next_path)),
                            "first_actions": [
                                str(step[0]) for step in next_path[:8]
                            ],
                            "final_blocker": [
                                int(blocker_pos[0]),
                                int(blocker_pos[1]),
                            ],
                        }
                    )
                    return next_path, diag
                if a_new == a_pos and b_new == b_pos:
                    continue
                next_state = (a_new, b_new, blocker_pos, "cursor")
                if next_state in seen:
                    continue
                seen.add(next_state)
                queue.append((next_state, next_path))
        else:
            payload = unclick_payload(a_pos, b_pos, blocker_pos)
            if payload is not None:
                next_state = (a_pos, b_pos, blocker_pos, "cursor")
                if next_state not in seen:
                    seen.add(next_state)
                    queue.append(
                        (next_state, path + [("ACTION6", payload)])
                    )
            floor = blocker_floor(a_pos, b_pos)
            for action, dx, dy in directions:
                new_blocker = (
                    int(blocker_pos[0]) + int(dx),
                    int(blocker_pos[1]) + int(dy),
                )
                if new_blocker not in floor:
                    continue
                next_state = (a_pos, b_pos, new_blocker, "blocker")
                if next_state in seen:
                    continue
                seen.add(next_state)
                queue.append((next_state, path + [(str(action), None)]))

    diag["blocked_reason"] = "no_color_lock_blocker_plan"
    diag["reached_expansion_limit"] = bool(
        int(diag["expanded_state_count"]) >= int(max_expansions)
    )
    return [], diag


def _compact_joint_cursor_state(state: dict[str, Any] | None) -> dict[str, Any] | None:
    if state is None:
        return None
    return {
        "cursor_a": list(state["cursor_a"]),
        "cursor_b": list(state["cursor_b"]),
        "grid_size": list(state["grid_size"]),
        "cell": int(state["cell"]),
        "origin": list(state["origin"]),
        "walkable_count": len(state["walkable"]),
        "hazard_count": len(state.get("hazards", ())),
    }


def _dominant_grid_cell_value(
    frame: np.ndarray,
    origin_x: int,
    origin_y: int,
    cell: int,
    gx: int,
    gy: int,
) -> int | None:
    x0 = int(origin_x + gx * cell)
    y0 = int(origin_y + gy * cell)
    patch = frame[y0 : y0 + cell, x0 : x0 + cell]
    if patch.size <= 0:
        return None
    values, counts = np.unique(patch, return_counts=True)
    pairs = sorted(zip(counts.tolist(), values.tolist()), reverse=True)
    return int(pairs[0][1]) if pairs else None


def _valued_components(frame: np.ndarray) -> list[dict[str, int]]:
    arr = np.asarray(frame)
    if arr.ndim != 2 or arr.size <= 0:
        return []
    seen = np.zeros(arr.shape, dtype=bool)
    height, width = arr.shape
    components: list[dict[str, int]] = []
    for y in range(height):
        for x in range(width):
            if seen[y, x]:
                continue
            value = int(arr[y, x])
            stack = [(y, x)]
            seen[y, x] = True
            xs: list[int] = []
            ys: list[int] = []
            while stack:
                cy, cx = stack.pop()
                xs.append(cx)
                ys.append(cy)
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = cy + dy, cx + dx
                    if 0 <= ny < height and 0 <= nx < width and not seen[ny, nx] and int(arr[ny, nx]) == value:
                        seen[ny, nx] = True
                        stack.append((ny, nx))
            area = len(xs)
            min_x = min(xs)
            max_x = max(xs)
            min_y = min(ys)
            max_y = max(ys)
            components.append(
                {
                    "value": value,
                    "area": area,
                    "min_x": min_x,
                    "max_x": max_x,
                    "min_y": min_y,
                    "max_y": max_y,
                    "width": max_x - min_x + 1,
                    "height": max_y - min_y + 1,
                    "cx": int(round(float(sum(xs)) / float(area))),
                    "cy": int(round(float(sum(ys)) / float(area))),
                }
            )
    return components


def _marker_blocks(frame: np.ndarray, *, block_size: int) -> list[dict[str, int]]:
    arr = np.asarray(frame)
    if arr.ndim != 2:
        return []
    height, width = arr.shape
    value_counts = Counter(int(value) for value in arr.flatten().tolist())
    markers: list[dict[str, int]] = []
    total = int(block_size * block_size)
    for y in range(0, height - block_size + 1):
        for x in range(0, width - block_size + 1):
            block = arr[y : y + block_size, x : x + block_size]
            values, counts = np.unique(block, return_counts=True)
            pairs = sorted(zip(counts.tolist(), values.tolist()), reverse=True)
            if len(pairs) < 2:
                continue
            primary_count, primary_value = int(pairs[0][0]), int(pairs[0][1])
            secondary_count, secondary_value = int(pairs[1][0]), int(pairs[1][1])
            if primary_count < total - 1 or secondary_count != 1:
                continue
            if value_counts[primary_value] > max(16, int(arr.size * 0.20)):
                continue
            secondary_positions = np.argwhere(block == secondary_value)
            if secondary_positions.shape[0] != 1:
                continue
            secondary_dy, secondary_dx = secondary_positions[0].tolist()
            markers.append(
                {
                    "x": x,
                    "y": y,
                    "primary_value": primary_value,
                    "secondary_value": secondary_value,
                    "secondary_dx": int(secondary_dx),
                    "secondary_dy": int(secondary_dy),
                    "primary_count": primary_count,
                }
            )
    return _dedupe_block_dicts(markers, block_size=block_size)


def _pure_blocks(frame: np.ndarray, *, block_size: int) -> list[dict[str, int]]:
    arr = np.asarray(frame)
    if arr.ndim != 2:
        return []
    height, width = arr.shape
    blocks: list[dict[str, int]] = []
    for y in range(0, height - block_size + 1):
        for x in range(0, width - block_size + 1):
            block = arr[y : y + block_size, x : x + block_size]
            value = int(block[0, 0])
            if bool(np.all(block == value)):
                blocks.append({"x": x, "y": y, "value": value})
    return _dedupe_block_dicts(blocks, block_size=block_size)


def _dedupe_block_dicts(blocks: list[dict[str, int]], *, block_size: int) -> list[dict[str, int]]:
    out: list[dict[str, int]] = []
    for block in blocks:
        x, y = int(block["x"]), int(block["y"])
        if any(abs(x - int(other["x"])) < block_size and abs(y - int(other["y"])) < block_size for other in out):
            continue
        out.append(block)
    return out


def _payload_for_action(
    action_name: str,
    frame: np.ndarray,
    *,
    click_points: list[tuple[int, int]] | None,
    click_index: int,
) -> dict[str, Any]:
    payload: dict[str, Any] = {"action": action_name}
    if action_name == "ACTION6":
        points = click_points or _default_click_points(frame)
        if points:
            x, y = points[click_index % len(points)]
        else:
            height = int(frame.shape[0]) if frame.ndim >= 1 else 1
            width = int(frame.shape[1]) if frame.ndim >= 2 else height
            x, y = width // 2, height // 2
        payload.update({"x": int(x), "y": int(y)})
    return payload


def _goal_target_objective_candidates(control_target: Mapping[str, Any]) -> list[dict[str, Any]]:
    raw_candidates: list[dict[str, Any]] = []
    primary = control_target.get("primary_target")
    if isinstance(primary, dict):
        raw_candidates.append(dict(primary))
    raw_candidates.extend(
        dict(candidate)
        for candidate in list(control_target.get("target_candidates") or [])
        if isinstance(candidate, dict)
    )
    out: list[dict[str, Any]] = []
    seen: set[str] = set()
    for candidate in raw_candidates:
        objective_key = _objective_key_for_candidate(candidate)
        if not objective_key or objective_key in seen:
            continue
        seen.add(objective_key)
        objective_kind = _objective_kind_for_candidate(candidate)
        goal_bearing = _objective_kind_goal_bearing(objective_kind)
        item = dict(candidate)
        item["objective_key"] = objective_key
        item["objective_kind"] = objective_kind
        item["goal_bearing"] = bool(goal_bearing)
        item["requires_goal_progress"] = bool(goal_bearing)
        out.append(item)

    def rank(candidate: Mapping[str, Any]) -> tuple[int, int, float, int, int]:
        score_delta = int(candidate.get("score_delta", 0) or 0)
        goal_likelihood = float(candidate.get("goal_likelihood", 0.0) or 0.0)
        goal_bearing = 1 if bool(candidate.get("goal_bearing")) else 0
        not_demoted = 0 if bool(candidate.get("grid_navigation_demoted")) else 1
        step_index = int(candidate.get("step_index", 0) or 0)
        return (goal_bearing, not_demoted, goal_likelihood, score_delta, step_index)

    out.sort(key=rank, reverse=True)
    return out[:8]


def _goal_target_contract_status_rank(status: str) -> int:
    return {
        "goal_objective_bound": 0,
        "progress_objective_only": 1,
        "missing_objective": 2,
    }.get(str(status or ""), 3)


def _objective_key_for_candidate(candidate: Mapping[str, Any]) -> str:
    kind = str(candidate.get("kind", "") or "target")
    action_name = _normalize_action_name(candidate.get("action_name"))
    site = candidate.get("site")
    if isinstance(site, (list, tuple)) and len(site) >= 2:
        try:
            return f"{kind}:{int(site[0])}:{int(site[1])}:{action_name}"
        except (TypeError, ValueError):
            pass
    changed_bbox = candidate.get("changed_bbox")
    if isinstance(changed_bbox, Mapping):
        try:
            x = (int(changed_bbox.get("min_x")) + int(changed_bbox.get("max_x"))) // 2
            y = (int(changed_bbox.get("min_y")) + int(changed_bbox.get("max_y"))) // 2
            return f"{kind}:{x}:{y}:{action_name}"
        except (TypeError, ValueError):
            pass
    if action_name:
        return f"{kind}:action:{action_name}"
    return ""


def _objective_kind_for_candidate(candidate: Mapping[str, Any]) -> str:
    explicit = str(candidate.get("objective_kind", "") or "")
    if explicit in {
        "score_delta",
        "score_precondition",
        "score_changed_bbox",
        "state_advance",
        "click_effect",
        "frontier_progress",
    }:
        return explicit
    kind = str(candidate.get("kind", "") or "")
    score_delta = int(candidate.get("score_delta", 0) or 0)
    goal_likelihood = float(candidate.get("goal_likelihood", 0.0) or 0.0)
    if score_delta > 0:
        return "score_delta"
    if kind == "score_precondition":
        return "score_precondition"
    if kind == "score_changed_bbox":
        return "score_changed_bbox"
    if goal_likelihood >= 0.30:
        return "state_advance"
    if kind in {"click_affordance", "click_point", "discovered_click_site"}:
        return "click_effect"
    if kind:
        return "frontier_progress"
    return "unknown"


def _objective_kind_goal_bearing(objective_kind: str) -> bool:
    return str(objective_kind or "") in {
        "score_delta",
        "score_precondition",
        "score_changed_bbox",
        "state_advance",
    }


def _goal_success_predicates_for_family(solver_family: str) -> list[str]:
    family = str(solver_family or "")
    base = ["score_delta", "positive_terminal", "state_advance"]
    if family == "click_affordance":
        return base + ["verified_click_relation"]
    if family == "push_object":
        return base + ["push_target_alignment"]
    if family == "attach_transport":
        return base + ["attach_receiver_alignment", "drop_target_alignment"]
    if family == "navigation":
        return base + ["reachable_goal_site"]
    if family == "transition_probe":
        return base + ["new_action_effect"]
    return base


def _record_objective_progress(
    pending: Mapping[str, Any],
    *,
    record: ActionEffectRecord,
    progressed: bool,
    goal_progress: bool,
    goal_progress_kind: str,
) -> tuple[bool, str]:
    if goal_progress:
        return True, str(goal_progress_kind or "goal_progress")
    objective_kind = str(pending.get("objective_kind", "") or "")
    if _objective_kind_goal_bearing(objective_kind):
        return False, "goal_objective_not_reached"
    segment_progress = _record_segment_transport_progress(pending, record)
    if segment_progress is not None:
        return segment_progress
    if progressed:
        return True, "visible_progress"
    if int(record.changed_pixel_count) > 0 and not bool(record.no_op):
        return True, "visible_effect"
    return False, "none"


def _record_goal_aligned_progress(
    pending: Mapping[str, Any],
    *,
    record: ActionEffectRecord,
    progressed: bool,
    goal_progress: bool,
    goal_progress_kind: str,
) -> tuple[bool, str]:
    if int(record.score_delta) > 0:
        return True, "score_delta"
    if goal_progress:
        return True, str(goal_progress_kind or "goal_progress")
    objective_kind = str(pending.get("objective_kind", "") or "")
    if not _objective_kind_goal_bearing(objective_kind):
        return False, "none"
    operator = str(pending.get("operator", "") or "")
    if operator not in {"route_to", "push", "attach", "drop", "click", "cycle"}:
        return False, "goal_objective_not_reached"
    candidate = pending.get("candidate")
    candidate = candidate if isinstance(candidate, Mapping) else {}
    macro_goal_link = bool(pending.get("macro_goal_link") or candidate.get("macro_goal_link"))
    structural_progress = bool(int(record.changed_pixel_count) > 0 and not bool(record.no_op))
    if not bool(progressed) and not bool(macro_goal_link and structural_progress):
        return False, "goal_objective_not_reached"
    if objective_kind in {"score_delta", "score_precondition", "score_changed_bbox"}:
        return True, "route_to_score_precondition"
    if objective_kind == "state_advance":
        return True, "route_to_state_advance"
    return True, "route_to_goal_objective"


def _goal_link_type(
    *,
    objective_kind: str,
    goal_bearing: bool,
    structural_progress: bool,
    objective_progress: bool,
    objective_progress_kind: str,
    goal_aligned_progress: bool,
    goal_aligned_progress_kind: str,
    goal_progress: bool,
    goal_progress_kind: str,
    score_delta: int,
) -> str:
    if int(score_delta) > 0:
        return "score_delta"
    if goal_progress:
        return str(goal_progress_kind or "goal_progress")
    if goal_aligned_progress:
        return str(goal_aligned_progress_kind or "goal_aligned_progress")
    if goal_bearing:
        return "goal_objective_unreached"
    if objective_progress:
        return str(objective_progress_kind or "objective_progress")
    if structural_progress:
        return "structural_only"
    if str(objective_kind or ""):
        return "objective_not_reached"
    return "none"


def _goal_failure_posterior_key(
    *,
    target_kind: str,
    objective_kind: str,
    action_name: str,
    operator: str,
) -> tuple[str, str, str]:
    kind = str(target_kind or "target")
    objective = str(objective_kind or "unknown")
    family = _action_family(action_name, operator=operator)
    return kind, objective, family


def _action_family(action_name: Any, *, operator: str = "") -> str:
    action = _normalize_action_name(action_name)
    if action in DIRECTIONAL_ACTIONS:
        return "move"
    if action == "ACTION6":
        return "click"
    if action == "ACTION5":
        return "select_or_submit"
    op = str(operator or "").strip()
    return op or "other"


def _route_shortplan_actions(
    actor: tuple[int, int],
    target: tuple[int, int],
    *,
    max_len: int,
) -> list[str]:
    ax, ay = int(actor[0]), int(actor[1])
    tx, ty = int(target[0]), int(target[1])
    actions: list[str] = []
    budget = max(1, int(max_len))
    while len(actions) < budget and (ax, ay) != (tx, ty):
        dx = tx - ax
        dy = ty - ay
        if abs(dx) >= abs(dy) and dx != 0:
            action = "ACTION4" if dx > 0 else "ACTION3"
            ax += 1 if dx > 0 else -1
        elif dy != 0:
            action = "ACTION2" if dy > 0 else "ACTION1"
            ay += 1 if dy > 0 else -1
        else:
            break
        actions.append(action)
    return actions


def _score_bearing_target_binding_from_record(
    record: ActionEffectRecord,
    *,
    rod_context: Mapping[str, Any],
    pending: Mapping[str, Any],
    existing_binding: Mapping[str, Any],
    goal_progress: bool,
    goal_progress_kind: str,
    objective_progress: bool,
    objective_progress_kind: str,
    operator: str,
) -> dict[str, Any] | None:
    score_delta = int(record.score_delta)
    progress_kind = str(goal_progress_kind or objective_progress_kind or "")
    if score_delta <= 0 and not bool(goal_progress):
        return None
    action = _normalize_action_name(record.action_name)
    site, source = _score_bearing_site_from_record(
        record,
        rod_context=rod_context,
        pending=pending,
        existing_binding=existing_binding,
    )
    if site is None:
        return None
    if score_delta > 0:
        target_kind = "score_precondition"
        objective_kind = "score_delta"
    elif progress_kind == "positive_terminal":
        target_kind = "positive_terminal"
        objective_kind = "positive_terminal"
    else:
        target_kind = "state_advance"
        objective_kind = progress_kind or "goal_progress"
    op = str(operator or pending.get("operator", "") or existing_binding.get("operator", "") or "")
    if action == "ACTION6":
        op = "click"
    elif not op:
        op = "repeat_action"
    return {
        "binding_source": f"{objective_kind}_{source}",
        "target_kind": target_kind,
        "target_key": [target_kind, int(site[0]), int(site[1]), op],
        "operator": op,
        "action_name": action,
        "site": [int(site[0]), int(site[1])],
        "objective_kind": objective_kind,
        "score_delta": score_delta,
        "goal_progress": bool(goal_progress),
        "goal_progress_kind": str(goal_progress_kind or "none"),
        "objective_progress": bool(objective_progress),
        "objective_progress_kind": str(objective_progress_kind or "none"),
    }


def _score_bearing_site_from_record(
    record: ActionEffectRecord,
    *,
    rod_context: Mapping[str, Any],
    pending: Mapping[str, Any],
    existing_binding: Mapping[str, Any],
) -> tuple[tuple[int, int] | None, str]:
    for source, raw_site in (
        ("existing_target_binding", existing_binding.get("site")),
        ("pending_candidate", (pending.get("candidate") if isinstance(pending.get("candidate"), Mapping) else {}).get("site")),
    ):
        site = _site_tuple(raw_site)
        if site is not None:
            return site, source
    click_point = (
        _click_point_from_payload(record.action_payload)
        if _normalize_action_name(record.action_name) == "ACTION6"
        else None
    )
    if click_point is not None:
        return click_point, "action_payload"
    before_sig = dict(rod_context.get("before_sig") or {})
    actor_pos = _site_tuple(before_sig.get("actor_pos"))
    if actor_pos is not None:
        return actor_pos, "actor_position"
    if record.changed_bbox is not None:
        bbox = record.changed_bbox
        return (
            int(round((int(bbox.min_x) + int(bbox.max_x)) / 2.0)),
            int(round((int(bbox.min_y) + int(bbox.max_y)) / 2.0)),
        ), "changed_bbox"
    return None, "none"


def _site_tuple(value: Any) -> tuple[int, int] | None:
    if not isinstance(value, (list, tuple)) or len(value) < 2:
        return None
    try:
        return int(value[0]), int(value[1])
    except (TypeError, ValueError):
        return None


def _record_segment_transport_progress(
    pending: Mapping[str, Any],
    record: ActionEffectRecord,
) -> tuple[bool, str] | None:
    solver_family = str(pending.get("solver_family", "") or _solver_family_for_primitive_id(pending.get("primitive_id")))
    if solver_family != "segment_transport":
        return None
    candidate = pending.get("candidate")
    if not isinstance(candidate, Mapping):
        return None
    if str(candidate.get("kind", "") or "") not in {
        "segment_displacement",
        "score_segment_displacement",
    }:
        return None
    expected_action = _normalize_action_name(candidate.get("action_name"))
    observed_action = _normalize_action_name(record.action_name)
    if expected_action and observed_action != expected_action:
        return False, "segment_transport_action_mismatch"
    for displacement in list(record.segment_displacements or []):
        if _segment_displacement_matches_candidate(candidate, displacement, observed_action):
            return True, "segment_transport_continuity"
    if record.segment_displacements:
        return False, "segment_transport_mismatch"
    return False, "segment_transport_no_segment_motion"


def _segment_displacement_matches_candidate(
    candidate: Mapping[str, Any],
    displacement: Mapping[str, Any],
    action_name: str,
) -> bool:
    try:
        candidate_color = int(candidate.get("segment_color", 0) or 0)
    except (TypeError, ValueError):
        candidate_color = 0
    if candidate_color > 0:
        try:
            displacement_color = int(displacement.get("color", 0) or 0)
        except (TypeError, ValueError):
            return False
        if displacement_color != candidate_color:
            return False
    try:
        dx = float(displacement.get("dx", 0.0) or 0.0)
        dy = float(displacement.get("dy", 0.0) or 0.0)
    except (TypeError, ValueError):
        return False
    expected_direction = _candidate_segment_direction(candidate)
    displacement_direction = _movement_direction_sign(dx, dy)
    if expected_direction != (0, 0):
        return displacement_direction == expected_direction
    action_direction = _action_direction_sign(action_name)
    if action_direction == (0, 0):
        return displacement_direction != (0, 0)
    axis_delta = dx * float(action_direction[0]) + dy * float(action_direction[1])
    perpendicular_delta = abs(dy) if action_direction[0] else abs(dx)
    return bool(axis_delta >= 1.0 and axis_delta >= perpendicular_delta)


def _candidate_segment_direction(candidate: Mapping[str, Any]) -> tuple[int, int]:
    raw_direction = candidate.get("direction")
    if isinstance(raw_direction, (list, tuple)) and len(raw_direction) >= 2:
        try:
            return int(raw_direction[0]), int(raw_direction[1])
        except (TypeError, ValueError):
            pass
    try:
        return _movement_direction_sign(
            float(candidate.get("dx", 0.0) or 0.0),
            float(candidate.get("dy", 0.0) or 0.0),
        )
    except (TypeError, ValueError):
        return 0, 0


def _movement_direction_sign(dx: float, dy: float) -> tuple[int, int]:
    if abs(float(dx)) >= abs(float(dy)):
        if float(dx) > 0.0:
            return 1, 0
        if float(dx) < 0.0:
            return -1, 0
    else:
        if float(dy) > 0.0:
            return 0, 1
        if float(dy) < 0.0:
            return 0, -1
    return 0, 0


def _action_direction_sign(action_name: Any) -> tuple[int, int]:
    return {
        "ACTION1": (0, -1),
        "ACTION2": (0, 1),
        "ACTION3": (-1, 0),
        "ACTION4": (1, 0),
    }.get(_normalize_action_name(action_name), (0, 0))


def _record_goal_progress(record: ActionEffectRecord) -> tuple[bool, str]:
    if int(record.score_delta) > 0:
        return True, "score_delta"
    pre_state = str(record.pre_state or "").upper()
    post_state = str(record.post_state or "").upper()
    state_changed = bool(pre_state and post_state and pre_state != post_state)
    if state_changed and post_state in POSITIVE_TERMINAL_STATES:
        return True, "positive_terminal"
    if state_changed and post_state in TERMINAL_NO_SCORE_STATES and int(record.score_delta) <= 0:
        return False, "terminal_no_score"
    if state_changed and int(record.score_delta) >= 0:
        return True, "state_advance"
    return False, "none"


def _default_click_points(frame: np.ndarray) -> list[tuple[int, int]]:
    height = int(frame.shape[0]) if frame.ndim >= 1 else 1
    width = int(frame.shape[1]) if frame.ndim >= 2 else height
    points = _component_click_points(frame)
    points.extend([
        (width // 2, height // 2),
        (width // 4, height // 4),
        ((3 * width) // 4, height // 4),
        (width // 4, (3 * height) // 4),
        ((3 * width) // 4, (3 * height) // 4),
    ])
    deduped: list[tuple[int, int]] = []
    seen: set[tuple[int, int]] = set()
    for x, y in points:
        key = (max(0, min(width - 1, int(x))), max(0, min(height - 1, int(y))))
        if key in seen:
            continue
        seen.add(key)
        deduped.append(key)
    return deduped


def _color_cycle_probe_click_points_enabled() -> bool:
    raw = str(os.environ.get("ENABLE_ECA_COLOR_CYCLE_CLICK_PROBE_SITES", "") or "").strip().lower()
    return raw in {"1", "true", "yes", "on"}


def _color_cycle_probe_click_points(frame: np.ndarray) -> list[tuple[int, int]]:
    state = _color_cycle_constraint_state(frame)
    if state is None:
        return []
    return sorted(_color_cycle_clickable_sites(state))


def _component_click_points(frame: np.ndarray) -> list[tuple[int, int]]:
    arr = np.asarray(frame)
    if arr.ndim != 2 or arr.size <= 0:
        return []
    background = set(_dominant_values(arr, limit=3, min_fraction=0.08, absolute_floor=8))
    seen = np.zeros(arr.shape, dtype=bool)
    components: list[tuple[int, int, int, int]] = []
    height, width = arr.shape
    for y in range(height):
        for x in range(width):
            if seen[y, x]:
                continue
            value = int(arr[y, x])
            if value in background:
                seen[y, x] = True
                continue
            stack = [(y, x)]
            seen[y, x] = True
            xs: list[int] = []
            ys: list[int] = []
            while stack:
                cy, cx = stack.pop()
                xs.append(cx)
                ys.append(cy)
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = cy + dy, cx + dx
                    if (
                        0 <= ny < height
                        and 0 <= nx < width
                        and not seen[ny, nx]
                        and int(arr[ny, nx]) == value
                    ):
                        seen[ny, nx] = True
                        stack.append((ny, nx))
            area = len(xs)
            if area < 2 or area > max(512, int(arr.size * 0.20)):
                continue
            cx = int(round(float(sum(xs)) / float(area)))
            cy = int(round(float(sum(ys)) / float(area)))
            components.append((cx, cy, area, value))
    components.sort(key=lambda item: (-item[0], -item[1], -item[2], item[3]))
    return [(x, y) for x, y, _area, _value in components[:24]]


def _dominant_values(
    frame: np.ndarray,
    *,
    limit: int,
    min_fraction: float,
    absolute_floor: int = 1,
) -> list[int]:
    arr = np.asarray(frame)
    if arr.size <= 0:
        return []
    values, counts = np.unique(arr, return_counts=True)
    threshold = max(int(absolute_floor), int(arr.size * float(min_fraction)))
    dominant = [
        int(value)
        for value, count in sorted(zip(values.tolist(), counts.tolist()), key=lambda item: item[1], reverse=True)[:limit]
        if int(count) >= threshold
    ]
    if not dominant and values.size:
        dominant.append(int(values[np.argmax(counts)]))
    return dominant


__all__ = [
    "CORE_ACTION_ORDER",
    "DIRECTIONAL_ACTIONS",
    "PrimitiveActionDecision",
    "PrimitiveSynthesisLoop",
]
